        let login = repo_owner_login installation in
        Alcotest.(check (list string)) "exact contiguous ordered snapshot"
          [ Pod_store.sig_of ~position:1 ~id:601L ~account_id ~login
              ~description:"Core — servizio principale" "core"
          ; Pod_store.sig_of ~position:2 ~id:602L ~account_id ~login
              ~branch:"release/v1" "ops"
          ; Pod_store.sig_of ~position:3 ~id:604L ~account_id ~login
              ~archived:true "archive"
          ; Pod_store.sig_of ~position:4 ~id:605L ~account_id ~login "docs"
          ]
          sigs;
        Lwt.return_unit)

  let draft_failure_case =
    db_case
      "draft failure after installation success: intentional partial \
       persistence, then idempotent retry"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = fixture_user (module C) "ghoauth_draftfail" in
        let installation = 936000020L in
        let account_id = Int64.add installation 1L in
        let login = repo_owner_login installation in
        (* Flow 0: a normal success establishes the draft and snapshot the
           later failure must leave untouched. *)
        let* state0, cookie0 = onboard ~url ~uid ~installation "flow 0" in
        let first_sigs =
          [ Pod_store.sig_of ~position:1 ~id:801L ~account_id ~login "first"
          ]
        in
        let* response =
          run_callback ~url ~jar:[ cookie0 ]
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub [ listing_for installation ] (ref 0))
            ~repositories:
              (gur_transport
                 [ repo_listing
                     [ repo_entry ~installation ~id:801L ~name:"first" () ]
                 ]
                 (ref []))
            ~target:(callback_target state0 fixture_code)
            ()
        in
        let* () = check_success_lwt "flow 0" response in
        let* record_id =
          installation_record_id (module C) "flow 0" installation
        in
        let* draft0 = active_draft (module C) "flow 0" ~uid ~record_id in
        let draft0 = require_draft "flow 0" draft0 in
        (* Flow 1: the poison repository id makes the snapshot insert fail
           inside the draft store's transaction, deterministically, after
           record_verified has already committed. *)
        let* r = C.exec q_create_fail_fn () in
        let* () = or_fail "create fail fn" r in
        let* r = C.exec q_create_fail_trigger () in
        let* () = or_fail "create fail trigger" r in
        let* state1, cookie1 = onboard ~url ~uid ~installation "flow 1" in
        let* response =
          run_callback ~url ~jar:[ cookie1 ]
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub [ listing_for installation ] (ref 0))
            ~repositories:
              (gur_transport
                 [ repo_listing
                     [ repo_entry ~installation ~id:802L ~name:"second" ()
                     ; repo_entry ~installation ~id:poison_repo_id
                         ~name:"poisoned" ()
                     ]
                 ]
                 (ref []))
            ~target:(callback_target state1 fixture_code)
            ()
        in
        let* () = check_failure_lwt "flow 1" response in
        check_deletion "flow 1" ~cookie_name:(fst cookie1)
          ~stored_value:(snd cookie1) response;
        let* _, consumed1 = state_row (module C) "flow 1" state1 in
        Alcotest.(check bool) "flow 1 state consumed" false consumed1;
        (* Intentional partial persistence: the installation row survives
           active — no compensating deletion — while the previous draft and
           snapshot are untouched by the rolled-back refresh. *)
        let* count = installation_count (module C) "flow 1" installation in
        Alcotest.(check int) "one installation row" 1 count;
        let* status = C.find q_installation_status installation in
        let* status = or_fail "installation status" status in
        Alcotest.(check string) "installation still active" "active" status;
        let* draft1 = active_draft (module C) "flow 1" ~uid ~record_id in
        Alcotest.(check bool) "previous draft still the active one" true
          (draft1 = Some draft0);
        let* drafts = draft_count (module C) "flow 1" uid in
        Alcotest.(check int) "no extra draft" 1 drafts;
        let* sigs = snapshot_sigs (module C) "flow 1" draft0 in
        Alcotest.(check (list string)) "previous snapshot unchanged"
          first_sigs sigs;
        (* Remove the injected failure; a completely fresh flow reuses the
           installation idempotently and refreshes the draft with a
           complete new snapshot. *)
        let* r = C.exec q_drop_fail_trigger () in
        let* () = or_fail "drop trigger" r in
        let* r = C.exec q_drop_fail_fn () in
        let* () = or_fail "drop fn" r in
        let* state2, cookie2 = onboard ~url ~uid ~installation "flow 2" in
        let* response =
          run_callback ~url ~jar:[ cookie2 ]
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub [ listing_for installation ] (ref 0))
            ~repositories:
              (gur_transport
                 [ repo_listing
                     [ repo_entry ~installation ~id:803L ~name:"third" ()
                     ; repo_entry ~installation ~id:804L ~name:"fourth" ()
                     ]
                 ]
                 (ref []))
            ~target:(callback_target state2 fixture_code)
            ()
        in
        let* () = check_success_lwt "flow 2" response in
        let* count = installation_count (module C) "flow 2" installation in
        Alcotest.(check int) "still exactly one installation row" 1 count;
        let* active = active_draft_count (module C) "flow 2" uid in
        Alcotest.(check int) "exactly one active draft" 1 active;
        let* draft2 = active_draft (module C) "flow 2" ~uid ~record_id in
        let draft2 = require_draft "flow 2" draft2 in
        let* sigs = snapshot_sigs (module C) "flow 2" draft2 in
        Alcotest.(check (list string)) "complete retry snapshot"
          [ Pod_store.sig_of ~position:1 ~id:803L ~account_id ~login "third"
          ; Pod_store.sig_of ~position:2 ~id:804L ~account_id ~login
              "fourth"
          ]
          sigs;
        Lwt.return_unit)

  (* --- Analytics: github_app_installed ---

     The success boundary is exactly "state consumed, installation verified,
     and BOTH persistence steps committed". The distinct id comes from the
     consumed state row's owning user — this leg is sessionless, so a session
     could not supply it. The fake sink replaces the HTTP transport, so no
     PostHog request can leave the process. *)

  let analytics_success_case =
    db_case
      "analytics: a completed callback captures exactly one \
       github_app_installed for the state's owner, carrying no GitHub or \
       OAuth material"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = fixture_user (module C) "ghoauth_an_ok" in
        let installation = 936000101L in
        let* state, cookie = onboard ~url ~uid ~installation "analytics" in
        let ex_calls = ref 0 and inst_calls = ref 0 in
        let repo_captured = ref [] in
        let* response, captured =
          with_sink_lwt (fun () ->
              run_callback ~url ~jar:[ cookie; an_consent_granted ]
                ~exchange:(exchange_stub (Ok (200, token_body)) ex_calls)
                ~installations:
                  (installations_stub [ listing_for installation ] inst_calls)
                ~repositories:
                  (gur_transport
                     [ repo_listing (default_repo_entries installation) ]
                     repo_captured)
                ~target:(callback_target state fixture_code)
                ())
        in
        let* () = check_success_lwt "analytics success" response in
        check_single_capture "granted" ~name:"github_app_installed"
          ~distinct_id:(Printf.sprintf "user:%d" uid)
          ~props:[ ("user_id", `Int uid) ]
          captured;
        (* Privacy sweep over the serialized payload: none of the
           credential-shaped fixtures this leg handles may appear anywhere
           in it. Assertions are boolean so a failure never prints the
           payload — or the values it is being checked against. *)
        let serialized =
          String.concat "|" (List.map Yojson.Safe.to_string captured)
        in
        List.iter
          (fun needle ->
            Alcotest.(check bool)
              "credential-shaped fixture absent from the analytics payload"
              false
              (goc_contains ~needle serialized))
          [ access_fixture; refresh_fixture; fixture_code; gte_client_secret;
            GOC.state_to_string state;
            Int64.to_string installation;
            Int64.to_string (Int64.add installation 1L);
            Printf.sprintf "owner-%Ld" installation;
            gur_private_name; gur_private_description; snd cookie
          ];
        Lwt.return_unit)

  let analytics_consent_case =
    db_case
      "analytics: denied, missing, and disabled configurations capture \
       nothing while the callback still succeeds"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let run label ?(enabled = true) ~username ~installation extra_cookies =
          let* uid = fixture_user (module C) username in
          let* state, cookie = onboard ~url ~uid ~installation label in
          let ex_calls = ref 0 and inst_calls = ref 0 in
          let repo_captured = ref [] in
          let* response, captured =
            with_sink_lwt ~enabled (fun () ->
                run_callback ~url ~jar:(cookie :: extra_cookies)
                  ~exchange:(exchange_stub (Ok (200, token_body)) ex_calls)
                  ~installations:
                    (installations_stub [ listing_for installation ] inst_calls)
                  ~repositories:
                    (gur_transport
                       [ repo_listing (default_repo_entries installation) ]
                       repo_captured)
                  ~target:(callback_target state fixture_code)
                  ())
          in
          (* The business outcome is identical in every configuration. *)
          let* () = check_success_lwt label response in
          check_no_capture label captured;
          Lwt.return_unit
        in
        let* () =
          run "denied" ~username:"ghoauth_an_denied" ~installation:936000102L
            [ an_consent_denied ]
        in
        let* () =
          run "missing" ~username:"ghoauth_an_missing"
            ~installation:936000103L []
        in
        run "analytics disabled" ~enabled:false
          ~username:"ghoauth_an_disabled" ~installation:936000104L
          [ an_consent_granted ])

  let analytics_no_event_case =
    db_case
      "analytics: a rejected authorization, a failed exchange, a failed \
       verification, a failed listing, a failed persistence, and a replay \
       all capture nothing"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        (* One helper per terminal-failure shape, each over the real
           pipeline with granted consent. *)
        let failing label ~username ~installation ~target ~exchange
            ~installations ~repositories =
          let* uid = fixture_user (module C) username in
          let* state, cookie = onboard ~url ~uid ~installation label in
          let* response, captured =
            with_sink_lwt (fun () ->
                run_callback ~url ~jar:[ cookie; an_consent_granted ]
                  ~exchange ~installations ~repositories
                  ~target:(target state) ())
          in
          let* () = check_failure_lwt label response in
          check_no_capture label captured;
          Lwt.return (uid, state, cookie)
        in
        let ex_calls = ref 0 and inst_calls = ref 0 in
        let repo_captured = ref [] in
        (* The user said no at GitHub: no exchange, no SQL past consume. *)
        let* _ =
          failing "authorization rejected" ~username:"ghoauth_an_rej"
            ~installation:936000111L
            ~target:(fun state ->
              target_of
                [ "state=" ^ GOC.state_to_string state; "error=access_denied" ])
            ~exchange:(exchange_stub (Ok (200, token_body)) ex_calls)
            ~installations:(installations_stub [] inst_calls)
            ~repositories:(gur_transport [] repo_captured)
        in
        Alcotest.(check int) "rejected: no exchange" 0 !ex_calls;
        (* Exchange failure. *)
        let* _ =
          failing "exchange failure" ~username:"ghoauth_an_ex"
            ~installation:936000112L
            ~target:(fun state -> callback_target state fixture_code)
            ~exchange:(exchange_stub (Error ()) (ref 0))
            ~installations:(installations_stub [] (ref 0))
            ~repositories:(gur_transport [] (ref []))
        in
        (* Verification failure: an empty installation listing. *)
        let* _ =
          failing "verification failure" ~username:"ghoauth_an_ver"
            ~installation:936000113L
            ~target:(fun state -> callback_target state fixture_code)
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:(installations_stub [ listing_for 936000999L ] (ref 0))
            ~repositories:(gur_transport [] (ref []))
        in
        (* Repository listing failure: the installation is verified, but
           nothing is persisted, so there is no installation to report. *)
        let* _ =
          failing "listing failure" ~username:"ghoauth_an_list"
            ~installation:936000114L
            ~target:(fun state -> callback_target state fixture_code)
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub [ listing_for 936000114L ] (ref 0))
            ~repositories:(gur_transport [ Error () ] (ref []))
        in
        (* A successful callback, then its replay. *)
        let* uid = fixture_user (module C) "ghoauth_an_replay" in
        let installation = 936000115L in
        let* state, cookie = onboard ~url ~uid ~installation "replay" in
        let succeed label jar =
          with_sink_lwt (fun () ->
              run_callback ~url ~jar
                ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
                ~installations:
                  (installations_stub [ listing_for installation ] (ref 0))
                ~repositories:
                  (gur_transport
                     [ repo_listing (default_repo_entries installation) ]
                     (ref []))
                ~target:(callback_target state fixture_code)
                ())
          |> Lwt.map (fun (response, captured) -> (label, response, captured))
        in
        let* label, response, captured =
          succeed "first" [ cookie; an_consent_granted ]
        in
        let* () = check_success_lwt label response in
        check_single_capture label ~name:"github_app_installed"
          ~distinct_id:(Printf.sprintf "user:%d" uid)
          ~props:[ ("user_id", `Int uid) ]
          captured;
        (* The replay finds the state already consumed: same generic
           failure, and deliberately no second event. *)
        let* label, response, captured =
          succeed "replay" [ cookie; an_consent_granted ]
        in
        let* () = check_failure_lwt label response in
        check_no_capture label captured;
        Lwt.return_unit)

  (* --- Both GitHub account kinds, end to end ---
     The fixtures above derive one synthetic identity per installation and
     always describe it as an organization. The two cases below instead
     spell out the identity GitHub really returns for each account kind —
     a personal account and an organization with its own login and account
     id — and follow it all the way to what /projects/new renders, because
     that is where a wrongly parsed or wrongly persisted account kind would
     actually surface. *)

  (* One listing page carrying an explicit account identity and target
     type, instead of the id-derived default. *)
  let listing_as ~account_id ~login ~target installation =
    Ok
      ( 200,
        gui_entry_page
          (gui_raw_entry
             ~id:(Int64.to_string installation)
             ~account:
               (Printf.sprintf {|{"id":%Ld,"login":"%s"}|} account_id login)
             ~target:(Printf.sprintf {|"%s"|} target)
             ()) )

  (* GET /projects/new exactly as the success redirect issues it —
     parameter-free, with a memory session for the owner. With one owned
     draft the handler must open that draft's repository selector directly,
     so this is the real page a user lands on after a successful callback. *)
  let projects_new_body ~url ~uid label =
    let handler =
      Dream.memory_sessions (fun req ->
          let* () =
            Dream.set_session_field req "user_id" (string_of_int uid)
          in
          Earde.Project_setup_handlers.make_new_project_handler
            ~mode:Ob.Public req)
    in
    let* response =
      run_shared ~url handler
        (Dream.request ~method_:`GET ~target:"/projects/new" "")
    in
    Alcotest.(check int) (label ^ ": /projects/new renders") 200
      (status_of response);
    Dream.body response

  (* One account kind, from the GitHub identity through persistence to the
     rendered chooser. [private_name] must never appear anywhere. *)
  let account_kind_case name ~username ~installation ~account_id ~login
      ~target ~expected_type ~public_name ~private_name =
    db_case name (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = fixture_user (module C) username in
        let* state, cookie = onboard ~url ~uid ~installation name in
        let repo ?(private_flag = false) ?(visibility = "public") ~id
            repo_name =
          gur_repo ~owner_id:account_id ~owner_login:login ~private_flag
            ~visibility ~id ~name:repo_name ()
        in
        let inst_calls = ref 0 in
        let repo_captured = ref [] in
        let* response =
          run_callback ~url ~jar:[ cookie ]
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub
                 [ listing_as ~account_id ~login ~target installation ]
                 inst_calls)
            ~repositories:
              (gur_transport
                 [ repo_listing
                     [ repo ~id:901L public_name
                     ; repo ~private_flag:true ~visibility:"private"
                         ~id:902L private_name
                     ] ]
                 repo_captured)
            ~target:(callback_target state fixture_code)
            ()
        in
        (* The whole point: this account kind reaches the connected
           redirect, not the generic failure. *)
        let* () = check_success_lwt name response in
        Alcotest.(check int) (name ^ ": one verification") 1 !inst_calls;
        Alcotest.(check int) (name ^ ": one repository listing") 1
          (List.length !repo_captured);
        (* The account kind and login are persisted exactly as GitHub
           described them — no defaulting to the other kind. *)
        let* row = C.find q_installation_row installation in
        let* (stored_account_id, stored_login, stored_type), connected_by =
          or_fail (name ^ ": installation row") row
        in
        Alcotest.(check bool) (name ^ ": account id") true
          (stored_account_id = account_id);
        Alcotest.(check string) (name ^ ": account login") login stored_login;
        Alcotest.(check string) (name ^ ": account type") expected_type
          stored_type;
        Alcotest.(check (option int)) (name ^ ": connected by the owner")
          (Some uid) connected_by;
        (* Exactly the public repository is snapshotted, owned by this
           account. *)
        let* record_id = installation_record_id (module C) name installation in
        let* draft = active_draft (module C) name ~uid ~record_id in
        let draft = require_draft name draft in
        let* sigs = snapshot_sigs (module C) name draft in
        Alcotest.(check (list string)) (name ^ ": public snapshot only")
          [ Pod_store.sig_of ~position:1 ~id:901L ~account_id ~login
              public_name ]
          sigs;
        (* And following the success redirect itself — parameter-free —
           opens this single draft's repository selector, with the private
           repository absent from the page as well as from the snapshot. *)
        let* html = projects_new_body ~url ~uid name in
        Alcotest.(check bool) (name ^ ": public repository offered") true
          (goc_contains ~needle:(login ^ "/" ^ public_name) html);
        Alcotest.(check bool) (name ^ ": account login shown") true
          (goc_contains ~needle:login html);
        Alcotest.(check bool) (name ^ ": private repository absent") false
          (goc_contains ~needle:private_name html);
        Lwt.return_unit)

  let personal_account_case =
    account_kind_case
      "personal account: User installation connects and lands on \
       /projects/new"
      ~username:"ghoauth_personal" ~installation:936000021L
      ~account_id:220767424L ~login:"personal-owner-fixture" ~target:"User"
      ~expected_type:"user" ~public_name:"smoke-personal"
      ~private_name:"personal-private-fixture"

  let organization_account_case =
    account_kind_case
      "organization: Organization installation with an org-owned public \
       repository connects and lands on /projects/new"
      ~username:"ghoauth_org" ~installation:936000022L
      ~account_id:267672683L ~login:"org-owner-fixture"
      ~target:"Organization" ~expected_type:"organization"
      ~public_name:"smoke-org" ~private_name:"org-private-fixture"

  (* An organization listing whose repository is owned by a different
     account than the installation: the ownership check must reject the
     page rather than snapshot a foreign repository. *)
  let organization_owner_mismatch_case =
    db_case
      "organization owner mismatch: foreign repository fails closed with \
       no rows"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = fixture_user (module C) "ghoauth_orgowner" in
        let installation = 936000023L in
        let account_id = 267672683L in
        let* state, cookie = onboard ~url ~uid ~installation "org owner" in
        let* response =
          run_callback ~url ~jar:[ cookie ]
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub
                 [ listing_as ~account_id ~login:"org-owner-fixture"
                     ~target:"Organization" installation ]
                 (ref 0))
            ~repositories:
              (gur_transport
                 [ repo_listing
                     [ gur_repo
                         ~owner_id:(Int64.add account_id 7L)
                         ~owner_login:"someone-else-fixture" ~id:903L
                         ~name:"borrowed" () ] ]
                 (ref []))
            ~target:(callback_target state fixture_code)
            ()
        in
        let* () =
          check_terminal_failure (module C) "org owner" ~cookie ~installation
            response
        in
        let* drafts = draft_count (module C) "org owner" uid in
        Alcotest.(check int) "no draft" 0 drafts;
        Lwt.return_unit)

  (* The same installation id already recorded as a personal account: an
     organization verification for it is an identity change the store must
     refuse, leaving the existing row exactly as it was. *)
  let account_kind_conflict_case =
    db_case
      "account-kind conflict: an organization verification never rewrites \
       a recorded personal installation"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = fixture_user (module C) "ghoauth_kindconflict" in
        let installation = 936000024L in
        let account_id = 220767424L in
        let* r = C.exec q_insert_active_user (installation, account_id) in
        let* () = or_fail "personal fixture" r in
        let* state, cookie = onboard ~url ~uid ~installation "conflict" in
        let* response =
          run_callback ~url ~jar:[ cookie ]
            ~exchange:(exchange_stub (Ok (200, token_body)) (ref 0))
            ~installations:
              (installations_stub
                 [ listing_as ~account_id ~login:"org-owner-fixture"
                     ~target:"Organization" installation ]
                 (ref 0))
            ~repositories:
              (gur_transport
                 [ repo_listing
                     [ gur_repo ~owner_id:account_id
                         ~owner_login:"org-owner-fixture" ~id:904L
                         ~name:"conflicting" () ] ]
                 (ref []))
            ~target:(callback_target state fixture_code)
            ()
        in
        let* () = check_failure_lwt "conflict" response in
        check_deletion "conflict" ~cookie_name:(fst cookie)
          ~stored_value:(snd cookie) response;
        (* The recorded personal identity survives byte for byte, and no
           draft was created against it. *)
        let* row = C.find q_installation_row installation in
        let* (stored_account_id, stored_login, stored_type), _ =
          or_fail "conflict row" row
        in
        Alcotest.(check bool) "account id unchanged" true
          (stored_account_id = account_id);
        Alcotest.(check string) "login unchanged" "personal-owner-fixture"
          stored_login;
        Alcotest.(check string) "kind unchanged" "user" stored_type;
        let* count = installation_count (module C) "conflict" installation in
        Alcotest.(check int) "still exactly one row" 1 count;
        let* drafts = draft_count (module C) "conflict" uid in
        Alcotest.(check int) "no draft" 0 drafts;
        Lwt.return_unit)

  let db_suite =
    [ success_case; replay_case; expired_case; already_consumed_case;
      personal_account_case; organization_account_case;
      organization_owner_mismatch_case; account_kind_conflict_case;
      binding_mismatch_case; exchange_transport_case; oauth_rejected_case;
      not_accessible_case; pagination_limit_case;
      listing_transport_error_case; listing_status_case;
      listing_invalid_case; listing_no_public_case; listing_pagination_case;
      multiple_repositories_case; persistence_failure_case;
      draft_failure_case; consume_storage_error_case; parallel_case;
      analytics_success_case; analytics_consent_case; analytics_no_event_case ]
end

(* === REQUEST-TARGET REDACTION ===
   Pure redaction/path-only behavior plus the middleware pair, all DB-free.
   Fixture "secrets" are obviously fake placeholders, and assertions on the
   original values use boolean equality so a failure never prints them. *)
module Rtr = Earde.Request_target_redaction

let rtr_case name f = Alcotest.test_case name `Quick f

let rtr_check name expected input =
  rtr_case name (fun () ->
      Alcotest.(check string) name expected (Rtr.redact_target input))

let rtr_unchanged name input = rtr_check name input input

let rtr_path name expected input =
  rtr_case name (fun () ->
      Alcotest.(check string) name expected (Rtr.path_only input))

(* Runs [target] through redact -> observer -> restore -> final handler and
   returns what the middle observer and the final handler each saw, i.e. the
   views Dream.logger/analytics and the router respectively would get. *)
let rtr_pipeline_views target =
  let seen_mid = ref None and seen_final = ref None in
  let observe slot inner request =
    slot := Some (Dream.target request);
    inner request
  in
  let handler =
    Rtr.redact_middleware
    @@ observe seen_mid
    @@ Rtr.restore_middleware
    @@ fun request ->
    seen_final := Some (Dream.target request);
    Dream.respond "ok"
  in
  ignore
    (Lwt_main.run (handler (Dream.request ~method_:`GET ~target ""))
      : Dream.response);
  match (!seen_mid, !seen_final) with
  | Some mid, Some final -> (mid, final)
  | _ -> Alcotest.fail "pipeline did not reach both observation points"

(* === RATE-LIMIT BLOCKED PAGE ===
   Database-gated (EARDE_TEST_DATABASE_URL): drives the real
   Handlers.Rate_limit.middleware past its limit over Postgres and asserts the
   blocked page's return link is the path only — no query value from the
   original target may reach the rendered HTML. Fixture "secrets" are obviously
   fake, and assertions on them are boolean so a failure never prints them. *)
module Rate_limit_blocked_page = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let q_cleanup =
    (Caqti_type.string ->. Caqti_type.unit)
    "DELETE FROM rate_limits WHERE endpoint = $1"

  (* One case = one endpoint bucket, cleared before and after so repeated runs
     start from a fresh window. *)
  let db_case name ~endpoint f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 let* r = C.exec q_cleanup endpoint in
                 or_fail "cleanup" r
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* Repeats the same GET through the real middleware until the limiter
     blocks (bounded well past the production limit, which stays private to
     Db), returning the blocked response's status and body. *)
  let run_until_blocked ~url ~target =
    let handler =
      Dream.sql_pool url @@ Dream.memory_sessions
      @@ Earde.Handlers.Rate_limit.middleware (fun _ ->
             Dream.respond "rlbp-allowed")
    in
    let rec go n =
      if n > 20 then Alcotest.fail "limiter never blocked within 20 attempts"
      else
        let* response = handler (Dream.request ~method_:`GET ~target "") in
        let* body = Dream.body response in
        if contains body "rlbp-allowed" then go (n + 1)
        else Lwt.return (Dream.status_to_int (Dream.status response), body)
    in
    go 1

  let callback_case =
    db_case "blocked callback page links to the path only"
      ~endpoint:"/integrations/github/authorize/callback" (fun ~url ->
        let* status, body =
          run_until_blocked ~url
            ~target:
              "/integrations/github/authorize/callback?code=fake_rl_code_21&state=fake_rl_state_22"
        in
        Alcotest.(check int) "blocked status" 200 status;
        Alcotest.(check bool) "normal blocked page" true
          (contains body "Too Many Attempts");
        Alcotest.(check bool) "return link is path only" true
          (contains body "href='/integrations/github/authorize/callback'");
        Alcotest.(check bool) "raw code absent" false
          (contains body "fake_rl_code_21");
        Alcotest.(check bool) "raw state absent" false
          (contains body "fake_rl_state_22");
        Alcotest.(check bool) "no code parameter" false (contains body "code=");
        Alcotest.(check bool) "no state parameter" false
          (contains body "state=");
        Alcotest.(check bool) "no query on the callback path" false
          (contains body "/integrations/github/authorize/callback?");
        Lwt.return_unit)

  let login_case =
    db_case "blocked /login?next=/settings page returns to /login"
      ~endpoint:"/login" (fun ~url ->
        let* status, body =
          run_until_blocked ~url ~target:"/login?next=/settings"
        in
        Alcotest.(check int) "blocked status" 200 status;
        Alcotest.(check bool) "normal blocked page" true
          (contains body "Too Many Attempts");
        Alcotest.(check bool) "return link is /login" true
          (contains body "href='/login'");
        Alcotest.(check bool) "original query absent" false
          (contains body "next=/settings");
        Lwt.return_unit)

  let suite = [ callback_case; login_case ]
end

(* ===== Project setup: repository-selection form parser + page renderer =====
   Both pure and DB-free. Parser rejection labels name only the malformed
   category — never the fixture value — and rejection is asserted as a bare
   boolean, so no form value can reach Alcotest output; the error type itself
   is payload-free by construction. *)
module Psf = Earde.Project_setup_repository_form
module Psp = Earde.Project_setup_pages

let psf_case name f = Alcotest.test_case name `Quick f

let psf_ok name fields ~draft ~repos =
  psf_case name (fun () ->
      match Psf.of_fields fields with
      | Ok t ->
          Alcotest.(check int64) "draft id" draft (Psf.draft_id t);
          Alcotest.(check (list int64)) "snapshot ids" repos
            (Psf.selected_snapshot_ids t)
      | Error Psf.Invalid_form -> Alcotest.fail "expected a valid form")

let psf_reject name fields =
  psf_case name (fun () ->
      Alcotest.(check bool) "rejected" true
        (match Psf.of_fields fields with
        | Error Psf.Invalid_form -> true
        | Ok _ -> false))

let psf_repo_fields values = List.map (fun v -> ("repository", v)) values

let psf_fields_of_size n =
  ("draft_id", "1")
  :: psf_repo_fields (List.init n (fun i -> string_of_int (i + 1)))

let psf_cases =
  [ psf_ok "draft id alone: empty selection is valid" [ ("draft_id", "7") ]
      ~draft:7L ~repos:[]
  ; psf_ok "one repository"
      [ ("draft_id", "7"); ("repository", "31") ]
      ~draft:7L ~repos:[ 31L ]
  ; psf_ok "several repositories preserve form order"
      (("draft_id", "8") :: psf_repo_fields [ "5"; "3"; "9"; "4" ])
      ~draft:8L ~repos:[ 5L; 3L; 9L; 4L ]
  ; psf_ok "draft id position between repositories does not matter"
      [ ("repository", "2"); ("draft_id", "7"); ("repository", "1") ]
      ~draft:7L ~repos:[ 2L; 1L ]
  ; psf_case "exactly 2000 repositories accepted, order intact" (fun () ->
        match Psf.of_fields (psf_fields_of_size 2000) with
        | Ok t ->
            let ids = Psf.selected_snapshot_ids t in
            Alcotest.(check int) "count" 2000 (List.length ids);
            Alcotest.(check int64) "first preserved" 1L (List.hd ids);
            Alcotest.(check int64) "last preserved" 2000L (List.nth ids 1999)
        | Error Psf.Invalid_form -> Alcotest.fail "expected a valid form")
  ; psf_ok "leading zeroes accepted when the value is positive"
      [ ("draft_id", "007"); ("repository", "0042") ]
      ~draft:7L ~repos:[ 42L ]
  ; psf_case "largest representable int64 accepted" (fun () ->
        let fields =
          [ ("draft_id", Int64.to_string Int64.max_int)
          ; ("repository", Int64.to_string Int64.max_int)
          ]
        in
        match Psf.of_fields fields with
        | Ok t ->
            Alcotest.(check int64) "draft id" Int64.max_int (Psf.draft_id t);
            Alcotest.(check (list int64)) "snapshot ids" [ Int64.max_int ]
              (Psf.selected_snapshot_ids t)
        | Error Psf.Invalid_form -> Alcotest.fail "expected a valid form")
    (* Draft id: exactly one, strict positive decimal int64. *)
  ; psf_reject "empty field set" []
  ; psf_reject "missing draft id" (psf_repo_fields [ "1" ])
  ; psf_reject "duplicate draft id field"
      [ ("draft_id", "1"); ("draft_id", "1") ]
  ; psf_reject "blank draft id" [ ("draft_id", "") ]
  ; psf_reject "zero draft id" [ ("draft_id", "0") ]
  ; psf_reject "all-zero draft id" [ ("draft_id", "000") ]
  ; psf_reject "negative draft id" [ ("draft_id", "-5") ]
  ; psf_reject "plus-signed draft id" [ ("draft_id", "+5") ]
  ; psf_reject "leading-whitespace draft id" [ ("draft_id", " 5") ]
  ; psf_reject "trailing-whitespace draft id" [ ("draft_id", "5 ") ]
  ; psf_reject "newline-suffixed draft id" [ ("draft_id", "5\n") ]
  ; psf_reject "decimal-point draft id" [ ("draft_id", "5.0") ]
  ; psf_reject "hexadecimal draft id" [ ("draft_id", "0x10") ]
  ; psf_reject "underscore-separated draft id" [ ("draft_id", "1_000") ]
  ; psf_reject "int64-overflow draft id"
      [ ("draft_id", "9223372036854775808") ]
    (* Repository ids: same strict grammar; one bad value rejects the whole
       form. *)
  ; psf_reject "blank repository id" [ ("draft_id", "1"); ("repository", "") ]
  ; psf_reject "zero repository id" [ ("draft_id", "1"); ("repository", "0") ]
  ; psf_reject "negative repository id"
      [ ("draft_id", "1"); ("repository", "-3") ]
  ; psf_reject "plus-signed repository id"
      [ ("draft_id", "1"); ("repository", "+3") ]
  ; psf_reject "leading-whitespace repository id"
      [ ("draft_id", "1"); ("repository", " 3") ]
  ; psf_reject "trailing-whitespace repository id"
      [ ("draft_id", "1"); ("repository", "3 ") ]
  ; psf_reject "decimal-point repository id"
      [ ("draft_id", "1"); ("repository", "3.0") ]
  ; psf_reject "hexadecimal repository id"
      [ ("draft_id", "1"); ("repository", "0x3") ]
  ; psf_reject "int64-overflow repository id"
      [ ("draft_id", "1"); ("repository", "9223372036854775808") ]
  ; psf_reject "one invalid among valid repositories rejects the whole form"
      (("draft_id", "1") :: psf_repo_fields [ "4"; "x"; "6" ])
  ; psf_reject "duplicate repository ids"
      (("draft_id", "1") :: psf_repo_fields [ "4"; "4" ])
  ; psf_reject "duplicate repository ids across leading-zero spellings"
      (("draft_id", "1") :: psf_repo_fields [ "7"; "007" ])
  ; psf_reject "2001 repository fields" (psf_fields_of_size 2001)
    (* Closed field set: everything but draft_id/repository rejects,
       byte-exactly. *)
  ; psf_reject "unknown field" [ ("draft_id", "1"); ("primary", "2") ]
  ; psf_reject "unknown submit-style field"
      [ ("draft_id", "1"); ("submit", "save") ]
  ; psf_reject "capitalized field name" [ ("Draft_id", "1") ]
  ; psf_reject "field name with trailing space"
      [ ("draft_id", "1"); ("repository ", "2") ]
  ; psf_case "every rejection is the same payload-free error" (fun () ->
        let rejections =
          [ Psf.of_fields [ ("draft_id", "0") ]
          ; Psf.of_fields [ ("draft_id", "1"); ("unknown", "field") ]
          ; Psf.of_fields (("draft_id", "1") :: psf_repo_fields [ "4"; "4" ])
          ]
        in
        List.iter
          (fun r ->
            Alcotest.(check bool) "Invalid_form" true
              (r = Error Psf.Invalid_form))
          rejections)
  ]

(* --- Page renderer. Assertions scope to the feature fragment (the
   create-shell contents inside <main>): the shared layout legitimately emits
   its own scripts and styles, and these tests must pin only what the feature
   templates introduce. --- *)

let render_ps ?user ?(feedback = None) state =
  Psp.project_setup_page ?user ~state ~feedback ()

let ps_index_of haystack needle from =
  let hl = String.length haystack and nl = String.length needle in
  let rec go i =
    if i + nl > hl then None
    else if String.sub haystack i nl = needle then Some i
    else go (i + 1)
  in
  go from

let ps_count haystack needle =
  let nl = String.length needle in
  let rec go from acc =
    match ps_index_of haystack needle from with
    | None -> acc
    | Some i -> go (i + nl) (acc + 1)
  in
  go 0 0

let ps_fragment html =
  let start_marker = "<div class='create-shell'>" in
  match ps_index_of html start_marker 0 with
  | None -> Alcotest.fail "create shell missing from page"
  | Some s -> (
      match ps_index_of html "</main>" s with
      | None -> Alcotest.fail "unterminated main element"
      | Some e -> String.sub html s (e - s))

let ps_must frag s =
  Alcotest.(check bool) ("contains: " ^ s) true (contains frag s)

let ps_must_not frag s =
  Alcotest.(check bool) ("must not contain: " ^ s) false (contains frag s)

let ps_order frag first second =
  match (ps_index_of frag first 0, ps_index_of frag second 0) with
  | Some i, Some j ->
      Alcotest.(check bool)
        (Printf.sprintf "'%s' before '%s'" first second)
        true (i < j)
  | _ -> Alcotest.fail "expected both order markers present"

(* --- Structural form inspection -----------------------------------------
   Dream's framework field renders as
   [<input name="dream.csrf" type="hidden" value="TOKEN">] with a fresh
   random token per request. Any assertion that searches a whole rendered
   page for a short literal — an internal id, a count — can be spelled by
   those random bytes and fail at random, so absence assertions inspect
   structure instead: the form's own inputs, or a page with the framework
   fields removed. No assertion ever reads the token's bytes. *)

let ps_csrf_input_prefix = "<input name=\"dream.csrf\" type=\"hidden\" value=\""

(* Slices the first [<form ...>...</form>] region out of rendered HTML. *)
let ps_form_region html =
  match ps_index_of html "<form" 0 with
  | None -> Alcotest.fail "no form in the rendered markup"
  | Some s -> (
      match ps_index_of html "</form>" s with
      | None -> Alcotest.fail "unterminated form element"
      | Some e -> String.sub html s (e - s))

(* Every [<input ...>] tag of a region, as raw tag text, in source order. *)
let ps_input_tags region =
  let rec go from acc =
    match ps_index_of region "<input" from with
    | None -> List.rev acc
    | Some s -> (
        match String.index_from_opt region s '>' with
        | None -> Alcotest.fail "unterminated input element"
        | Some e -> go (e + 1) (String.sub region s (e + 1 - s) :: acc))
  in
  go 0 []

(* True when [tag] is exactly the framework CSRF field: the framework
   prefix, then one opaque value that is the tag's last attribute. The
   value is bounded but never read, so an extra attribute smuggled in
   after it fails the check. *)
let ps_is_csrf_input tag =
  let pl = String.length ps_csrf_input_prefix and tl = String.length tag in
  tl >= pl + 2
  && String.sub tag 0 pl = ps_csrf_input_prefix
  && String.sub tag (tl - 2) 2 = "\">"
  && not (String.contains (String.sub tag pl (tl - pl - 2)) '"')

(* Rendered HTML with every framework CSRF field dropped, so a whole-page
   absence assertion cannot trip over random token bytes. *)
let ps_without_csrf_inputs html =
  let len = String.length html in
  let buf = Buffer.create len in
  let rec go from =
    match ps_index_of html ps_csrf_input_prefix from with
    | None -> Buffer.add_string buf (String.sub html from (len - from))
    | Some s -> (
        Buffer.add_string buf (String.sub html from (s - from));
        match String.index_from_opt html s '>' with
        | None -> Alcotest.fail "unterminated CSRF input element"
        | Some e -> go (e + 1))
  in
  go 0;
  Buffer.contents buf

let psp_case name f = Alcotest.test_case name `Quick f

let ps_draft ?(id = 11L) ?(login = "octo-org") ?(atype = Psp.Organization)
    ?(repos = 3) ?(selected = 0) () : Psp.draft_option =
  { Psp.draft_id = id; account_login = login; account_type = atype;
    repository_count = repos; selected_repository_count = selected }

let ps_repo ?(id = 501L) ?(full_name = "octo-org/widgets")
    ?(url = "https://github.com/octo-org/widgets") ?description
    ?(branch = "main") ?(archived = false) ?(selected = false) () :
    Psp.repository_option =
  { Psp.snapshot_id = id; full_name; html_url = url; description;
    default_branch = branch; is_archived = archived; is_selected = selected }

let ps_config ?draft ?(repos = [ ps_repo () ]) () : Psp.configuration =
  { Psp.draft = (match draft with Some d -> d | None -> ps_draft ());
    repositories = repos }

