  let rm_storage_error_case =
    db_case "read model: a failing statement is a payload-free Storage_error"
      (fun ~url _conn ->
        (* A live connection whose database lacks the permanent tables: the
           one SELECT fails inside Caqti and must collapse to the
           payload-free Storage_error, never an exception or a detail. *)
        let bare_url = Uri.with_path (Uri.of_string url) "/template1" in
        let* conn2 = Caqti_lwt_unix.connect bare_url in
        let* conn2 = or_fail "bare connect" conn2 in
        let (module C2 : Caqti_lwt.CONNECTION) = conn2 in
        Lwt.finalize
          (fun () ->
            expect_error "missing tables" Hrm.Storage_error conn2 ~user:42
              ~slug:"pch-any")
          (fun () -> C2.disconnect ()))

  let read_model_db_suite =
    [ rm_input_case; rm_owner_view_case; rm_authorization_case;
      rm_kind_namespace_case; rm_inconsistent_case; rm_storage_error_case ]

  (* === Permanent page renderer (pure, DB-free) === *)

  let php_repo ?(full_name = "pcreate-owner/alpha")
      ?(html_url = "https://github.com/pcreate-owner/alpha") ?description
      ?(branch = "main") ?(primary = false) ?(archived = false) () :
      Php.repository =
    { Php.full_name; html_url; description; default_branch = branch;
      is_primary = primary; is_archived = archived }

  let php_project ?(name = "Fixture Project") ?(slug = "fixture-project")
      ?description ?website ?(kind = Pi.Project)
      ?(login = "pcreate-owner") ?(atype = Php.Personal)
      ?(repos = [ php_repo ~primary:true () ]) () : Php.project =
    { Php.name; slug; description; website_url = website; kind;
      namespace_login = login; namespace_type = atype; repositories = repos }

  let php_frag project =
    ps_fragment (Php.project_home_setup_page ~project ())

  let php_structure_cases =
    [ case "summary: heading, verification copy, complete project facts"
        (fun () ->
          let frag =
            php_frag
              (php_project
                 ~description:"A useful description"
                 ~website:"https://example.com/site" ())
          in
          ps_must frag "Project created";
          ps_must frag "Project connected through GitHub";
          ps_must frag "Fixture Project";
          ps_must frag "fixture-project";
          ps_must frag ">Project</dd>";
          ps_must frag "pcreate-owner (Personal account)";
          ps_must frag "A useful description";
          ps_must frag "<a href='https://example.com/site' \
                        class='create-link'>https://example.com/site</a>")
    ; case "summary: organization namespace and optional fields absent"
        (fun () ->
          let frag =
            php_frag
              (php_project ~kind:Pi.Ecosystem ~atype:Php.Organization
                 ~login:"pcreate-org" ())
          in
          ps_must frag "pcreate-org (Organization)";
          ps_must frag "Ecosystem";
          ps_must_not frag "Website";
          ps_must_not frag "Description")
    ; case "repositories: order, markers, branch as text, safe links"
        (fun () ->
          let frag =
            php_frag
              (php_project
                 ~repos:
                   [ php_repo ~primary:true
                       ~description:"Alpha description" ()
                   ; php_repo ~full_name:"pcreate-owner/beta"
                       ~html_url:"https://github.com/pcreate-owner/beta"
                       ~branch:"release/v1" ~archived:true ()
                   ]
                 ())
          in
          ps_order frag "pcreate-owner/alpha" "pcreate-owner/beta";
          ps_must frag
            "<a href='https://github.com/pcreate-owner/alpha' \
             class='create-link phs-repo-link'>pcreate-owner/alpha</a>";
          ps_must frag "phs-repo-primary'>Primary";
          ps_must frag "phs-repo-archived'>Archived";
          ps_must frag "Alpha description";
          ps_must frag "<code class='phs-repo-branch'>release/v1</code>";
          (* One primary marker, one archived marker. *)
          Alcotest.(check int) "one primary" 1
            (ps_count frag "phs-repo-primary");
          Alcotest.(check int) "one archived" 1
            (ps_count frag "phs-repo-archived"))
    ; case "continuation: two distinct navigation links, no form" (fun () ->
          let frag = php_frag (php_project ()) in
          ps_must frag "Choose a community home";
          (* Both real navigation steps: exact structural links to the two
             permanent routes — and nothing else actionable. *)
          ps_must frag
            "<a href='/projects/fixture-project/request-home' \
             class='create-link phs-next-request-link'>Connect to an \
             existing community</a>";
          ps_must frag
            "<a href='/projects/fixture-project/community-home/new' \
             class='create-link phs-next-create-link'>Create a community \
             home</a>";
          (* Visibly distinct: two anchors, two destinations, one each. *)
          Alcotest.(check int) "two next-step links" 2 (ps_count frag "<a href='/projects/");
          Alcotest.(check int) "one connect link" 1
            (ps_count frag "phs-next-request-link");
          Alcotest.(check int) "one create link" 1
            (ps_count frag "phs-next-create-link");
          (* The former placeholder copy is gone — the option is real now. *)
          ps_must_not frag "not available yet";
          ps_must_not frag "<form";
          ps_must_not frag "<button";
          ps_must_not frag "<input";
          ps_must_not frag "disabled";
          ps_must_not frag "<script")
    ; case "continuation: invalid project slug renders neither navigation link"
        (fun () ->
          let frag = php_frag (php_project ~slug:"Bad Slug!" ()) in
          ps_must frag "Choose a community home";
          ps_must_not frag "request-home";
          ps_must_not frag "phs-next-request-link";
          ps_must_not frag "community-home/new";
          ps_must_not frag "phs-next-create-link";
          ps_must_not frag "href='/projects/";
          (* The corrupt slug still renders only as escaped text. *)
          ps_must frag "Bad Slug!";
          ps_must_not frag "<form";
          ps_must_not frag "<button")
    ; case "continuation: no project id ever reaches the navigation section"
        (fun () ->
          let frag = php_frag (php_project ()) in
          List.iter (ps_must_not frag)
            [ "project_id"; "id='"; "value='" ])
    ]

  let php_safety_cases =
    [ case "escaping: hostile text never reaches markup" (fun () ->
          let hostile = "<script>alert('x')</script>" in
          let frag =
            php_frag
              (php_project ~name:hostile ~description:hostile
                 ~login:hostile
                 ~repos:
                   [ php_repo ~full_name:hostile
                       ~description:hostile ~branch:hostile
                       ~primary:true ()
                   ]
                 ())
          in
          ps_must_not frag "<script";
          ps_must frag "&lt;script&gt;")
    ; case "defense: invalid URLs are never actionable or emitted" (fun () ->
          let frag =
            php_frag
              (php_project
                 ~website:"javascript:alert(1)"
                 ~repos:
                   [ php_repo ~html_url:"javascript:alert(2)" ~primary:true ()
                   ]
                 ())
          in
          ps_must_not frag "javascript:";
          ps_must_not frag "href='#'";
          (* The repository stays listed as plain text. *)
          ps_must frag "phs-unlinked'>pcreate-owner/alpha")
    ; case "copy: no officiality claims, no scripts or inline styles"
        (fun () ->
          let frag = php_frag (php_project ()) in
          List.iter (ps_must_not frag)
            [ "Official"; "GitHub-approved"; "GitHub-endorsed"; "<style";
              "style='"; "style=\""; "<script"; "window.location";
              "location.href"; "http-equiv";
            ])
    ]

  let page_suite = php_structure_cases @ php_safety_cases

  (* === DB-free gate harness (mirrors Ps_handlers) === *)

  let gate_run ?session ?(headers = []) ~method_ ~target handler =
    let pipeline =
      match session with
      | None -> handler
      | Some fields ->
          Dream.memory_sessions (fun req ->
              let* () =
                Lwt_list.iter_s
                  (fun (k, v) -> Dream.set_session_field req k v)
                  fields
              in
              handler req)
    in
    let request = Dream.request ~method_ ~target ~headers "" in
    match Lwt_main.run (pipeline request) with
    | response -> `Response response
    | exception _ -> `Db_boundary

  let gate_response label = function
    | `Response response -> response
    | `Db_boundary -> Alcotest.failf "%s: unexpectedly reached the DB" label

  let check_db_boundary label = function
    | `Db_boundary -> ()
    | `Response response ->
        Alcotest.failf "%s: gate rejected with status %d" label
          (status_of response)

  let logged_in = [ ("user_id", "42") ]
  let admin_session = [ ("user_id", "42"); ("is_admin", "true") ]

  let check_clean_redirect label expected response =
    Alcotest.(check int) (label ^ ": 303") 303 (status_of response);
    Alcotest.(check (option string)) (label ^ ": Location") (Some expected)
      (Dream.header response "Location");
    Alcotest.(check (option string)) (label ^ ": no-store")
      (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": no-cache")
      (Some "no-cache")
      (Dream.header response "Pragma");
    Alcotest.(check (option string)) (label ^ ": no-referrer")
      (Some "no-referrer")
      (Dream.header response "Referrer-Policy");
    Alcotest.(check string) (label ^ ": empty body") ""
      (Lwt_main.run (Dream.body response))

  (* --- POST /projects access gates and origin policy --- *)

  let post_run ?session ?(headers = []) ~mode ~load_config () =
    gate_run ?session ~headers ~method_:`POST ~target:post_target
      (make_post ~mode ~load_config)

  let post_off_case =
    case "POST off: clean /bring redirect, loader untouched" (fun () ->
        let loader, calls = counting_loader (ok_loader ()) in
        let response =
          gate_response "off"
            (post_run ~session:admin_session ~mode:Ob.Off ~load_config:loader
               ())
        in
        check_clean_redirect "off" "/bring" response;
        Alcotest.(check int) "loader never called" 0 !calls)

  let post_anonymous_case =
    case "POST: anonymous and invalid sessions to /login, loader untouched"
      (fun () ->
        let loader, calls = counting_loader (ok_loader ()) in
        check_clean_redirect "anonymous" "/login"
          (gate_response "anonymous"
             (post_run ~mode:Ob.Public ~load_config:loader ()));
        List.iter
          (fun raw ->
            check_clean_redirect ("user_id " ^ raw) "/login"
              (gate_response ("user_id " ^ raw)
                 (post_run
                    ~session:[ ("user_id", raw) ]
                    ~mode:Ob.Public ~load_config:loader ())))
          [ "not-a-number"; ""; "0"; "-3" ];
        check_clean_redirect "is_admin only" "/login"
          (gate_response "is_admin only"
             (post_run
                ~session:[ ("is_admin", "true") ]
                ~mode:Ob.Admins ~load_config:loader ()));
        Alcotest.(check int) "loader never called" 0 !calls)

  let post_rollout_case =
    case "POST admins mode: non-admin to /bring before configuration"
      (fun () ->
        let loader, calls = counting_loader (ok_loader ()) in
        check_clean_redirect "non-admin" "/bring"
          (gate_response "non-admin"
             (post_run ~session:logged_in ~mode:Ob.Admins ~load_config:loader
                ()));
        Alcotest.(check int) "loader never called" 0 !calls;
        (* Passing the gates and the origin check, the missing content type
           is the next rejection: reaching that 400 proves mode,
           authentication, rollout, configuration, and origin all passed —
           with no SQL (no sql_pool is installed). *)
        let continues label session mode =
          let response =
            gate_response label
              (post_run ~session
                 ~headers:[ ("Origin", "https://earde.com") ]
                 ~mode
                 ~load_config:(fun () -> ok_loader ())
                 ())
          in
          Alcotest.(check int) (label ^ ": 400 content-type") 400
            (status_of response)
        in
        continues "admin continues" admin_session Ob.Admins;
        continues "public user continues" logged_in Ob.Public)

  let post_config_failure_case =
    case "POST: configuration error is a generic 503, no form, no SQL"
      (fun () ->
        let loader, calls =
          counting_loader (gac_of_values ~origin:None ())
        in
        let response =
          gate_response "config failure"
            (post_run ~session:logged_in
               ~headers:
                 [ ("Origin", "https://earde.com");
                   ("Content-Type", "application/x-www-form-urlencoded");
                 ]
               ~mode:Ob.Public ~load_config:loader ())
        in
        Alcotest.(check int) "503" 503 (status_of response);
        Alcotest.(check int) "loader called once" 1 !calls;
        let body = Lwt_main.run (Dream.body response) in
        List.iter
          (fun needle ->
            Alcotest.(check bool)
              ("body does not leak " ^ needle)
              false (contains body needle))
          [ "EARDE_PUBLIC_ORIGIN"; "Missing"; "Invalid"; "public_origin" ])

  let origin_run label ?sec_fetch_site origin =
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @
      match sec_fetch_site with
      | Some v -> [ ("Sec-Fetch-Site", v) ]
      | None -> []
    in
    post_run ~session:logged_in ~headers ~mode:Ob.Public
      ~load_config:(fun () -> ok_loader ())
      ()
    |> gate_response label

  let origin_rejected label ?sec_fetch_site origin =
    let response = origin_run label ?sec_fetch_site origin in
    Alcotest.(check int) (label ^ ": 403") 403 (status_of response)

  let origin_accepted label ?sec_fetch_site origin =
    let response = origin_run label ?sec_fetch_site origin in
    Alcotest.(check int)
      (label ^ ": passes the origin gate")
      400 (status_of response)

  let post_origin_case =
    case "POST origin gate: exact policy of the repository-selection POST"
      (fun () ->
        origin_accepted "exact origin" (Some "https://earde.com");
        origin_accepted "explicit default port" (Some "https://earde.com:443");
        origin_accepted "fetch metadata" ~sec_fetch_site:"same-origin" None;
        origin_rejected "cross-origin" (Some "https://evil.example");
        origin_rejected "same-site subdomain" (Some "https://www.earde.com");
        origin_rejected "wrong scheme" (Some "http://earde.com");
        origin_rejected "wrong port" (Some "https://earde.com:8443");
        origin_rejected "null" (Some "null");
        origin_rejected "blank" (Some "");
        origin_rejected "mismatch beats same-origin metadata"
          ~sec_fetch_site:"same-origin" (Some "https://evil.example");
        origin_rejected "no signals" None;
        origin_rejected "cross-site" ~sec_fetch_site:"cross-site" None;
        origin_rejected "same-site" ~sec_fetch_site:"same-site" None;
        origin_rejected "none" ~sec_fetch_site:"none" None;
        let response = origin_run "reflection" (Some "https://evil.example") in
        let body = Lwt_main.run (Dream.body response) in
        Alcotest.(check bool) "origin not reflected" false
          (contains body "evil.example"))

  let post_gate_suite =
    [ post_off_case; post_anonymous_case; post_rollout_case;
      post_config_failure_case; post_origin_case ]

  (* --- GET /projects/:slug/setup access gates --- *)

  let setup_gate_target = setup_target "pch-any"

  let setup_run ?session ~mode () =
    gate_run ?session ~method_:`GET ~target:setup_gate_target
      (make_setup ~mode)

  let setup_off_case =
    case "GET setup off: clean /bring redirect before params or SQL"
      (fun () ->
        check_clean_redirect "off" "/bring"
          (gate_response "off" (setup_run ~session:admin_session ~mode:Ob.Off ())))

  let setup_anonymous_case =
    case "GET setup: anonymous and invalid sessions redirect to /login"
      (fun () ->
        check_clean_redirect "anonymous" "/login"
          (gate_response "anonymous" (setup_run ~mode:Ob.Public ()));
        List.iter
          (fun raw ->
            check_clean_redirect ("user_id " ^ raw) "/login"
              (gate_response ("user_id " ^ raw)
                 (setup_run ~session:[ ("user_id", raw) ] ~mode:Ob.Public ())))
          [ "not-a-number"; ""; "0"; "-3" ];
        check_clean_redirect "is_admin only" "/login"
          (gate_response "is_admin only"
             (setup_run
                ~session:[ ("is_admin", "true") ]
                ~mode:Ob.Admins ())))

  let setup_rollout_case =
    case "GET setup admins mode: non-admin to /bring, admin continues"
      (fun () ->
        check_clean_redirect "non-admin" "/bring"
          (gate_response "non-admin"
             (setup_run ~session:logged_in ~mode:Ob.Admins ()));
        (* Past the gates, the routerless harness has no :slug parameter,
           which answers as the generic 404 — reaching it proves the gates
           passed with no SQL (no sql_pool is installed). *)
        let continues label session mode =
          let response = gate_response label (setup_run ~session ~mode ()) in
          Alcotest.(check int) (label ^ ": generic 404") 404
            (status_of response)
        in
        continues "admin continues" admin_session Ob.Admins;
        continues "public user continues" logged_in Ob.Public)

  let setup_gate_suite =
    [ setup_off_case; setup_anonymous_case; setup_rollout_case ]

  (* --- POST /projects CSRF handling (DB-free: rejections precede SQL) --- *)

  (* Values are percent-encoded, so fixture text with spaces, controls, or
     markup survives the URL-encoded body byte-exactly. *)
  let urlencode value =
    let buffer = Buffer.create (String.length value * 2) in
    String.iter
      (fun c ->
        match c with
        | 'A' .. 'Z' | 'a' .. 'z' | '0' .. '9' | '-' | '_' | '.' | '~' ->
            Buffer.add_char buffer c
        | c -> Buffer.add_string buffer (Printf.sprintf "%%%02X" (Char.code c)))
      value;
    Buffer.contents buffer

  let form_body fields =
    String.concat "&"
      (List.map (fun (k, v) -> k ^ "=" ^ urlencode v) fields)

  let session_cookie label response =
    match
      List.find_opt
        (fun v -> contains v "dream.session")
        (Dream.headers response "Set-Cookie")
    with
    | None -> Alcotest.fail (label ^ ": no session cookie")
    | Some v -> (
        match String.index_opt v ';' with
        | Some i -> String.sub v 0 i
        | None -> v)

  let identity_fields ?(kind = "project") ?(name = "Fixture Project")
      ?(slug = "pch-fixture") ?(description = "") ?(website = "")
      ?(primary = "") ~draft () =
    [ ("draft_id", draft); ("kind", kind); ("name", name); ("slug", slug);
      ("description", description); ("website_url", website);
      ("primary_snapshot_id", primary);
    ]

  let csrf_pipeline () =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    let* () = Dream.set_session_field req "user_id" "42" in
    match Dream.method_ req with
    | `GET ->
        Dream.respond
          (Dream.csrf_token req ^ "\n"
          ^ Dream.csrf_token ~valid_for:(-60.) req)
    | _ ->
        make_post ~mode:Ob.Public
          ~load_config:(fun () -> ok_loader ())
          req

  let mint_tokens label pipeline =
    let response =
      Lwt_main.run (pipeline (Dream.request ~method_:`GET ~target:"/mint" ""))
    in
    let cookie = session_cookie label response in
    match String.split_on_char '\n' (Lwt_main.run (Dream.body response)) with
    | [ fresh; expired ] -> (cookie, fresh, expired)
    | _ -> Alcotest.fail (label ^ ": unexpected mint body")

  let csrf_post ?cookie ?(content_type = true) pipeline fields =
    let headers =
      [ ("Origin", "https://earde.com") ]
      @ (if content_type then
           [ ("Content-Type", "application/x-www-form-urlencoded") ]
         else [])
      @ match cookie with Some c -> [ ("Cookie", c) ] | None -> []
    in
    match
      Lwt_main.run
        (pipeline
           (Dream.request ~method_:`POST ~target:post_target ~headers
              (form_body fields)))
    with
    | response -> `Response response
    | exception _ -> `Db_boundary

  let csrf_rejected label expected result =
    let response = gate_response label result in
    Alcotest.(check int) (label ^ ": status") expected (status_of response)

  let csrf_case =
    case "POST CSRF: Dream verification gates every submission" (fun () ->
        let pipeline = csrf_pipeline () in
        let cookie, fresh, expired = mint_tokens "mint" pipeline in
        let fields = identity_fields ~draft:"1" () in
        csrf_rejected "missing token" 403 (csrf_post ~cookie pipeline fields);
        csrf_rejected "invalid token" 403
          (csrf_post ~cookie pipeline
             (fields @ [ ("dream.csrf", "not-a-token") ]));
        csrf_rejected "expired token" 403
          (csrf_post ~cookie pipeline (fields @ [ ("dream.csrf", expired) ]));
        csrf_rejected "duplicate tokens" 403
          (csrf_post ~cookie pipeline
             (fields @ [ ("dream.csrf", fresh); ("dream.csrf", fresh) ]));
        csrf_rejected "wrong session" 403
          (csrf_post pipeline (fields @ [ ("dream.csrf", fresh) ]));
        csrf_rejected "wrong content type" 400
          (csrf_post ~cookie ~content_type:false pipeline
             (fields @ [ ("dream.csrf", fresh) ]));
        (* A verified token with valid application fields reaches the DB
           boundary: CSRF passed and Dream stripped its own field before
           the strict parser. *)
        check_db_boundary "verified form continues"
          (csrf_post ~cookie pipeline (fields @ [ ("dream.csrf", fresh) ])))

  let csrf_invalid_form_case =
    case "POST: unrecoverable malformed forms are one generic 400, no SQL"
      (fun () ->
        let pipeline = csrf_pipeline () in
        let cookie, fresh, _ = mint_tokens "mint" pipeline in
        List.iter
          (fun (label, fields) ->
            let response =
              gate_response label
                (csrf_post ~cookie pipeline
                   (fields @ [ ("dream.csrf", fresh) ]))
            in
            Alcotest.(check int) (label ^ ": 400") 400 (status_of response);
            Alcotest.(check (option string)) (label ^ ": no redirect") None
              (Dream.header response "Location");
            let body = Lwt_main.run (Dream.body response) in
            Alcotest.(check bool) (label ^ ": nothing reflected") false
              (contains body "zz9zz"))
          [ ("missing draft id",
             List.remove_assoc "draft_id" (identity_fields ~draft:"1" ()));
            ("malformed draft id", identity_fields ~draft:"zz9zz" ());
            ("duplicate draft id",
             ("draft_id", "1") :: identity_fields ~draft:"1" ());
          ];
        (* A recoverable draft id in a malformed form proceeds to the
           owner re-authorization read — the DB boundary here. *)
        check_db_boundary "recoverable draft id continues"
          (csrf_post ~cookie pipeline
             (identity_fields ~draft:"1" ()
             @ [ ("zz-unknown", "zz"); ("dream.csrf", fresh) ])))

  let post_csrf_suite = [ csrf_case; csrf_invalid_form_case ]

  (* === Database-gated: the real creation and destination paths === *)

  (* The real production shape: sql_pool + secret + memory sessions + the
     real router paths, so the setup GET reads its :slug route parameter
     exactly as in bin/main. /mint exists only to hand replay cases a
     fresh CSRF token for an already-established session. *)
  let app_pipeline ?session_user_id ~url () =
    Dream.sql_pool url @@ Dream.set_secret gck_secret
    @@ Dream.memory_sessions
    @@ (fun handler request ->
         match session_user_id with
         | None -> handler request
         | Some uid ->
             let* () =
               Dream.set_session_field request "user_id" (string_of_int uid)
             in
             handler request)
    @@ Dream.router
         [ Dream.get "/projects/new" (fun req ->
               Psh.make_new_project_handler ~mode:Ob.Public req);
           Dream.get "/mint" (fun req -> Dream.respond (Dream.csrf_token req));
           Dream.post "/projects" (fun req ->
               make_post ~mode:Ob.Public
                 ~load_config:(fun () -> ok_loader ())
                 req);
           Dream.get "/projects/:slug/setup" (fun req ->
               make_setup ~mode:Ob.Public req);
         ]

  let do_get ?cookie ~target pipeline =
    let headers =
      match cookie with Some c -> [ ("Cookie", c) ] | None -> []
    in
    let* response =
      pipeline (Dream.request ~method_:`GET ~target ~headers "")
    in
    let* body = Dream.body response in
    Lwt.return (response, body)

  let check_page label response =
    Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store")
      (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": referrer policy")
      (Some Earde.Request_origin.referrer_policy)
      (Dream.header response "Referrer-Policy")

  let csrf_field_marker = "name=\"dream.csrf\" type=\"hidden\" value=\""

  let csrf_of_page label html =
    match ps_index_of html csrf_field_marker 0 with
    | None -> Alcotest.fail (label ^ ": no framework CSRF field")
    | Some i -> (
        let start = i + String.length csrf_field_marker in
        match String.index_from_opt html start '"' with
        | None -> Alcotest.fail (label ^ ": unterminated CSRF value")
        | Some e -> String.sub html start (e - start))

  (* One GET that opens the identity step: page, session cookie, and CSRF
     token for the follow-up POST /projects. *)
  let open_identity_form label ~draft pipeline =
    let* response, body =
      do_get
        ~target:(Printf.sprintf "/projects/new?draft=%Ld&step=details" draft)
        pipeline
    in
    check_page label response;
    let cookie = session_cookie label response in
    let token = csrf_of_page label body in
    Lwt.return (cookie, token, ps_fragment body)

  let mint_token label ~cookie pipeline =
    let* response, body = do_get ~cookie ~target:"/mint" pipeline in
    Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
    Lwt.return body

  let do_post ?(origin = Some "https://earde.com") ~cookie ~fields pipeline =
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @ [ ("Content-Type", "application/x-www-form-urlencoded");
          ("Cookie", cookie);
        ]
    in
    pipeline
      (Dream.request ~method_:`POST ~target:post_target ~headers
         (form_body fields))

  let check_redirect_lwt label expected response =
    Alcotest.(check int) (label ^ ": 303") 303 (status_of response);
    Alcotest.(check (option string)) (label ^ ": Location") (Some expected)
      (Dream.header response "Location");
    Alcotest.(check (option string)) (label ^ ": no-store")
      (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": no-cache")
      (Some "no-cache")
      (Dream.header response "Pragma");
    Alcotest.(check (option string)) (label ^ ": no-referrer")
      (Some "no-referrer")
      (Dream.header response "Referrer-Policy");
    let* body = Dream.body response in
    Alcotest.(check string) (label ^ ": empty body") "" body;
    Lwt.return_unit

  let must frag s =
    Alcotest.(check bool) ("contains: " ^ s) true (contains frag s)

  let must_not frag s =
    Alcotest.(check bool) ("must not contain: " ^ s) false (contains frag s)

  let count_projects conn account_id =
    find conn "project count" Pfin.q_count_projects_for_namespace account_id

  let check_no_projects label conn account_id =
    let* projects = count_projects conn account_id in
    Alcotest.(check int) (label ^ ": no permanent project") 0 projects;
    Lwt.return_unit

  (* One steward-selected draft with a saved selection and primary,
     ready to finalize. *)
  let ready_draft ?token_body ?(login = "pcreate-owner") ?target
      ?installation_type conn ~user ~ext_id repos ~select ~primary =
    let* inst, draft, account_id =
      make_draft ?token_body ~login ?target ?installation_type conn ~user
        ~ext_id repos
    in
    let* ids = snapshot_ids conn draft in
    let selected = List.map (List.nth ids) select in
    let primary = Option.map (List.nth ids) primary in
    let* () =
      Pod_select.replace_ok "seed selection" conn ~user ~draft ?primary
        selected
    in
    Lwt.return (inst, draft, account_id, ids)

  (* === POST /projects: successful creation, PRG, replay === *)

  let post_success_case =
    db_case "POST: creation, permanent PRG redirect, owner GET, refresh"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* inst, draft, account_id, ids =
          ready_draft ~token_body:Pod_store.refresh_token_body conn ~user:uid
            ~ext_id:943000011L
            (fun account_id ->
              [ repo ~account_id ~id:943600111L
                  ~description:{|"Alpha description"|} "alpha"
              ; repo ~account_id ~id:943600112L "beta"
              ; repo ~account_id ~id:943600113L ~default_branch:"release/v1"
                  ~archived:true "gamma"
              ; gur_repo ~owner_id:account_id ~owner_login:"pcreate-owner"
                  ~private_flag:true ~visibility:"private"
                  ~description:
                    (Printf.sprintf {|"%s"|} gur_private_description)
                  ~id:943600114L ~name:gur_private_name ()
              ])
            ~select:[ 0; 2 ] ~primary:(Some 0)
        in
        let s1 = List.nth ids 0 in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, frag =
          open_identity_form "identity step" ~draft pipeline
        in
        must frag "action='/projects'";
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~name:"Pch Success Project" ~slug:"pch-success"
                 ~description:"Creata — davvero"
                 ~website:"https://example.com/pch"
                 ~primary:(Int64.to_string s1) ()
              @ [ ("dream.csrf", token) ])
            pipeline
        in
        (* The permanent PRG destination: canonical slug only — no id, no
           draft, no success flag, no submitted value. *)
        let* () =
          check_redirect_lwt "created" "/projects/pch-success/setup" response
        in
        (* Exactly one permanent project, one steward, the selected copies
           renumbered from 1, and a completed draft. *)
        let* projects = count_projects conn account_id in
        Alcotest.(check int) "one project" 1 projects;
        let* project =
          find_opt conn "project id" Pfin.q_project_id_by_slug "pch-success"
        in
        let project =
          match project with
          | Some id -> id
          | None -> Alcotest.fail "created project not found by slug"
        in
        let* stewards = collect conn "stewards" Pfin.q_steward_sigs project in
        Alcotest.(check (list string)) "one steward"
          [ Printf.sprintf "%d|%Ld|steward" uid inst ]
          stewards;
        let* repo_rows = collect conn "repo copies" Pfin.q_repo_sigs project in
        Alcotest.(check (list string)) "selected copies in order"
          [ Pfin.repo_sig ~position:1 ~id:943600111L ~login:"pcreate-owner"
              ~description:"Alpha description" ~primary:true "alpha"
          ; Pfin.repo_sig ~position:2 ~id:943600113L ~login:"pcreate-owner"
              ~branch:"release/v1" ~archived:true "gamma"
          ]
          repo_rows;
        let* status = find conn "draft status" q_draft_status draft in
        Alcotest.(check string) "draft completed" "completed" status;
        (* The permanent destination renders the created data for the
           steward. *)
        let* response, body =
          do_get ~cookie ~target:(setup_target "pch-success") pipeline
        in
        check_page "permanent GET" response;
        let frag = ps_fragment body in
        must frag "Project created";
        must frag "Project connected through GitHub";
        must frag "Pch Success Project";
        must frag "pch-success";
        must frag "Creata — davvero";
        must frag "https://example.com/pch";
        must frag "pcreate-owner (Personal account)";
        must frag "pcreate-owner/alpha";
        must frag "pcreate-owner/gamma";
        must frag "phs-repo-primary'>Primary";
        must frag "phs-repo-archived'>Archived";
        must frag "Choose a community home";
        must_not frag "pcreate-owner/beta";
        must_not frag "<form";
        (* No internal, GitHub, or credential identity leaks into the
           permanent page, the stored text, or the redirect. *)
        let* blob =
          find conn "permanent text blob" Pfin.q_permanent_text_blob project
        in
        List.iter
          (fun (label, needle) ->
            Alcotest.(check bool) (label ^ " absent from page") false
              (goc_contains ~needle body);
            Alcotest.(check bool) (label ^ " absent from stored text") false
              (goc_contains ~needle blob))
          [ ("access token", Pod_store.pods_access_fixture)
          ; ("refresh token", Pod_store.pods_refresh_fixture)
          ; ("authorization code", gte_code_string)
          ; ("PKCE verifier", gte_verifier_string)
          ; ("client secret", gte_client_secret)
          ; ("OAuth state", goc_fixture 'S')
          ; ("session binding", goc_fixture 'B')
          ; ("private repository name", gur_private_name)
          ; ("private repository description", gur_private_description)
          ; ("installation id", "943000011")
          ; ("account id", "943100011")
          ; ("GitHub repository id", "943600111")
          ; ("draft id", Int64.to_string draft)
          ];
        (* Refreshing the destination is a plain GET: no second project. *)
        let* response, _ =
          do_get ~cookie ~target:(setup_target "pch-success") pipeline
        in
        check_page "refresh" response;
        let* projects = count_projects conn account_id in
        Alcotest.(check int) "still one project" 1 projects;
        Lwt.return_unit)

  let post_replay_case =
    db_case "POST: replaying the finalization body creates no second project"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, ids =
          ready_draft conn ~user:uid ~ext_id:943000012L
            (fun account_id -> [ repo ~account_id ~id:943600121L "alpha" ])
            ~select:[ 0 ] ~primary:(Some 0)
        in
        let s1 = List.nth ids 0 in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        let fields =
          identity_fields ~draft:(Int64.to_string draft) ~slug:"pch-replay"
            ~primary:(Int64.to_string s1) ()
        in
        let* response =
          do_post ~cookie ~fields:(fields @ [ ("dream.csrf", token) ]) pipeline
        in
        let* () =
          check_redirect_lwt "created" "/projects/pch-replay/setup" response
        in
        (* Same body again, fresh valid token: the losing call maps through
           Draft_unavailable and leaks nothing about the permanent
           outcome. *)
        let* fresh = mint_token "fresh token" ~cookie pipeline in
        let* response =
          do_post ~cookie ~fields:(fields @ [ ("dream.csrf", fresh) ]) pipeline
        in
        let* () =
          check_redirect_lwt "replay" "/projects/new?selection=unavailable"
            response
        in
        (match Dream.header response "Location" with
        | Some location ->
            must_not location "pch-replay";
            must_not location (Int64.to_string draft)
        | None -> Alcotest.fail "replay: no Location");
        let* projects = count_projects conn account_id in
        Alcotest.(check int) "still one project" 1 projects;
        Lwt.return_unit)

  (* === POST /projects: selection redirects === *)

  let post_no_selection_case =
    db_case "POST: empty saved selection is the exact repository-step redirect"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, _ =
          ready_draft conn ~user:uid ~ext_id:943000013L
            (fun account_id -> [ repo ~account_id ~id:943600131L "alpha" ])
            ~select:[] ~primary:None
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        (* The identity step refuses to open without a selection, so mint
           the token directly. *)
        let* response, body = do_get ~target:"/mint" pipeline in
        let cookie = session_cookie "mint" response in
        let token = body in
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~kind:"ecosystem" ~slug:"pch-empty" ()
              @ [ ("dream.csrf", token) ])
            pipeline
        in
        let* () =
          check_redirect_lwt "no selection"
            (Printf.sprintf "/projects/new?draft=%Ld&selection=required"
               draft)
            response
        in
        check_no_projects "no selection" conn account_id)

  (* Deterministic mid-request race: the test connection locks the draft
     row before the POST, so the handler's read model sees the seeded
     selection, its finalize blocks on the draft lock, and the selection
     changes underneath before the lock is released. *)
  let race_case name ~mutate ~selection_suffix =
    db_case name (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, ids =
          ready_draft conn ~user:uid ~ext_id:943000014L
            (fun account_id ->
              [ repo ~account_id ~id:943600141L "alpha"
              ; repo ~account_id ~id:943600142L "beta"
              ])
            ~select:[ 0; 1 ] ~primary:(Some 0)
        in
        let s1 = List.nth ids 0 in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        let* () = tx_start conn in
        let* _ = find conn "lock draft" q_lock_draft draft in
        let post_promise =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~slug:"pch-race" ~primary:(Int64.to_string s1) ()
              @ [ ("dream.csrf", token) ])
            pipeline
        in
        let* () = Lwt_unix.sleep 1.0 in
        let* () = exec conn "mutate selection" mutate draft in
        let* () = tx_commit conn in
        let* response = post_promise in
        let* () =
          check_redirect_lwt "race redirect"
            (Printf.sprintf "/projects/new?draft=%Ld&selection=%s" draft
               selection_suffix)
            response
        in
        check_no_projects "race" conn account_id)

  let post_stale_primary_case =
    race_case
      "POST: primary unselected under the draft lock is the stale redirect"
      ~mutate:q_unselect_primary ~selection_suffix:"stale"

  let post_race_unselected_case =
    race_case
      "POST: selection emptied under the draft lock is the required redirect"
      ~mutate:q_unselect_all ~selection_suffix:"required"

  (* === POST /projects: structural form failure === *)

  let post_invalid_form_case =
    db_case "POST: malformed form recovers the owner draft, discloses nothing"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* other = insert_user conn "pcreate_b" in
        let* _, draft, account_id, ids =
          ready_draft conn ~user:uid ~ext_id:943000015L
            (fun account_id ->
              [ repo ~account_id ~id:943600151L "alpha"
              ; repo ~account_id ~id:943600152L "beta"
              ])
            ~select:[ 0 ] ~primary:None
        in
        let s1 = List.nth ids 0 in
        let* _, foreign, _, _ =
          ready_draft ~login:"pcreate-foreign" conn ~user:other
            ~ext_id:943000016L
            (fun account_id -> [ repo ~account_id ~id:943600161L "theirs" ])
            ~select:[ 0 ] ~primary:None
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        (* Recoverable owner draft: neutral identity re-render, generic
           invalid feedback, no malformed text preserved. *)
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~name:"zzMalformedNamezz" ()
              @ [ ("zz-unknown-field", "zzevil9"); ("dream.csrf", token) ])
            pipeline
        in
        Alcotest.(check int) "recovered: 400" 400 (status_of response);
        Alcotest.(check (option string)) "recovered: no redirect" None
          (Dream.header response "Location");
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "We couldn't read those project details";
        must frag "action='/projects'";
        must frag (Printf.sprintf "value='%Ld'" s1);
        must frag "name='name' maxlength='120' value=''";
        must_not body "zzevil9";
        must_not body "zzMalformedNamezz";
        (* Foreign draft id: one generic 400, no existence oracle, no
           redirect carrying the untrusted id. *)
        let* fresh = mint_token "fresh" ~cookie pipeline in
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string foreign) ()
              @ [ ("zz-unknown-field", "zz"); ("dream.csrf", fresh) ])
            pipeline
        in
        Alcotest.(check int) "foreign: 400" 400 (status_of response);
        Alcotest.(check (option string)) "foreign: no redirect" None
          (Dream.header response "Location");
        let* body = Dream.body response in
        must_not body (Int64.to_string foreign);
        must_not body "pcreate-foreign";
        must_not body "theirs";
        (* No finalization happened anywhere above. *)
        check_no_projects "invalid form" conn account_id)

  (* === POST /projects: domain validation (422) === *)

  let post_domain_validation_case =
    db_case "POST: every identity field error re-renders as an exact 422"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, ids =
          ready_draft conn ~user:uid ~ext_id:943000017L
            (fun account_id ->
              [ repo ~account_id ~id:943600171L "alpha"
              ; repo ~account_id ~id:943600172L "beta"
              ])
            ~select:[ 0 ] ~primary:None
        in
        let s1 = List.nth ids 0 and s2 = List.nth ids 1 in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, _, _ = open_identity_form "identity step" ~draft pipeline in
        let marker_name = "Rvx <'&> Marker" in
        let escaped_marker = "Rvx &lt;&#39;&amp;&gt; Marker" in
        let submit fields =
          let* fresh = mint_token "token" ~cookie pipeline in
          do_post ~cookie ~fields:(fields @ [ ("dream.csrf", fresh) ]) pipeline
        in
        let expect_422 label fields copy =
          let* response = submit fields in
          Alcotest.(check int) (label ^ ": 422") 422 (status_of response);
          Alcotest.(check (option string)) (label ^ ": no-store")
            (Some "no-store")
            (Dream.header response "Cache-Control");
          Alcotest.(check (option string)) (label ^ ": referrer policy")
            (Some Earde.Request_origin.referrer_policy)
            (Dream.header response "Referrer-Policy");
          Alcotest.(check (option string)) (label ^ ": no redirect") None
            (Dream.header response "Location");
          (* No submitted value enters a cookie. *)
          List.iter
            (fun cookie_header ->
              Alcotest.(check bool) (label ^ ": value not in cookies") false
                (contains cookie_header "Rvx"))
            (Dream.headers response "Set-Cookie");
          let* body = Dream.body response in
          let frag = ps_fragment body in
          must frag copy;
          (* Submitted values are preserved, escaped, and the current
             repository options are re-offered with a fresh CSRF field. *)
          must frag escaped_marker;
          must_not body marker_name;
          must frag (Printf.sprintf "value='%Ld'" s1);
          must body csrf_field_marker;
          Lwt.return_unit
        in
        let fields ?(kind = "project") ?(slug = "pch-domain")
            ?(description = "") ?(website = "")
            ?(primary = Int64.to_string s1) () =
          identity_fields ~draft:(Int64.to_string draft) ~kind
            ~name:marker_name ~slug ~description ~website ~primary ()
        in
        let* () =
          (* The failing field is the blank name; the marker rides in the
             description so preservation still shows. *)
          expect_422 "invalid name"
            (identity_fields ~draft:(Int64.to_string draft) ~name:"   "
               ~slug:"pch-domain" ~description:marker_name
               ~primary:(Int64.to_string s1) ())
            "Enter a valid project name."
        in
        let* () =
          expect_422 "invalid slug"
            (fields ~slug:"Bad_Slug" ())
            "Enter a valid project slug"
        in
        let* () =
          expect_422 "reserved slug" (fields ~slug:"new" ())
            "That project slug is reserved"
        in
        let* () =
          expect_422 "invalid description"
            (fields ~description:"bad\x01description" ())
            "Enter a valid description"
        in
        let* () =
          expect_422 "invalid website"
            (fields ~website:"not-a-url" ())
            "Enter a valid HTTP or HTTPS website address."
        in
        let* () =
          expect_422 "primary not selected"
            (fields ~primary:(Int64.to_string s2) ())
            "Choose a primary repository"
        in
        let* () =
          expect_422 "primary required" (fields ~primary:"" ())
            "must have a primary"
        in
        check_no_projects "domain validation" conn account_id)

  (* === POST /projects: finalization conflicts (409 re-renders) === *)

  let post_namespace_conflict_case =
    db_case "POST: organization kind on a personal namespace is a 409"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, _ =
          ready_draft conn ~user:uid ~ext_id:943000018L
            (fun account_id -> [ repo ~account_id ~id:943600181L "alpha" ])
            ~select:[ 0 ] ~primary:None
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~kind:"organization" ~name:"Pch Namespace Conflict"
                 ~slug:"pch-ns-conflict" ()
              @ [ ("dream.csrf", token) ])
            pipeline
        in
        Alcotest.(check int) "409" 409 (status_of response);
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "must be connected through a GitHub organization";
        (* Submitted values re-render over fresh read-model data. *)
        must frag "value='Pch Namespace Conflict'";
        must frag "value='pch-ns-conflict'";
        must frag "pcreate-owner/alpha";
        must body csrf_field_marker;
        check_no_projects "namespace conflict" conn account_id)

  let post_slug_conflict_case =
    db_case "POST: a taken slug re-renders as a 409 without the rival"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, _ =
          ready_draft conn ~user:uid ~ext_id:943000019L
            (fun account_id -> [ repo ~account_id ~id:943600191L "alpha" ])
            ~select:[ 0 ] ~primary:None
        in
        (* The rival permanent project holding the slug. *)
        let* _ =
          find conn "rival project" Pfin.q_insert_project_fixture
            ((None, "pch-taken"), (943100999L, "pch-rival-login"))
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~kind:"ecosystem" ~name:"Pch Slug <Conflict>"
                 ~slug:"pch-taken" ()
              @ [ ("dream.csrf", token) ])
            pipeline
        in
        Alcotest.(check int) "409" 409 (status_of response);
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "That project slug is already in use.";
        (* Submitted values preserved and escaped; the conflicting project
           stays unidentified. *)
        must frag "value='Pch Slug &lt;Conflict&gt;'";
        must frag "value='pch-taken'";
        must_not body "Pfin fixture";
        must_not body "pch-rival-login";
        let* projects = count_projects conn account_id in
        Alcotest.(check int) "no new project" 0 projects;
        Lwt.return_unit)

  let post_claim_conflict_case =
    db_case "POST: an already-connected repository is a 409 without the rival"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, _ =
          ready_draft conn ~user:uid ~ext_id:943000021L
            (fun account_id -> [ repo ~account_id ~id:943600211L "alpha" ])
            ~select:[ 0 ] ~primary:None
        in
        let* rival =
          find conn "rival project" Pfin.q_insert_project_fixture
            ((None, "pch-claim-holder"), (943100998L, "pch-rival-login"))
        in
        let* _ =
          find conn "rival claim" Pfin.q_insert_repo_claim
            (rival, 943600211L)
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        let* response =
          do_post ~cookie
            ~fields:
              (identity_fields ~draft:(Int64.to_string draft)
                 ~kind:"ecosystem" ~name:"Pch Claim Conflict"
                 ~slug:"pch-claim" ()
              @ [ ("dream.csrf", token) ])
            pipeline
        in
        Alcotest.(check int) "409" 409 (status_of response);
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "already connected to another Earde project";
        must frag "value='Pch Claim Conflict'";
        must_not body "pfin-claim/holder";
        must_not body "pch-claim-holder";
        must_not body "pch-rival-login";
        let* projects = count_projects conn account_id in
        Alcotest.(check int) "no new project" 0 projects;
        Lwt.return_unit)

  (* === POST /projects: rejected security gates persist nothing === *)

  let post_rejected_no_rows_case =
    db_case "POST: origin, CSRF, and content-type rejections persist nothing"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, ids =
          ready_draft conn ~user:uid ~ext_id:943000022L
            (fun account_id -> [ repo ~account_id ~id:943600221L "alpha" ])
            ~select:[ 0 ] ~primary:(Some 0)
        in
        let s1 = List.nth ids 0 in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _ =
          open_identity_form "identity step" ~draft pipeline
        in
        let fields =
          identity_fields ~draft:(Int64.to_string draft)
            ~slug:"pch-rejected" ~primary:(Int64.to_string s1) ()
        in
        let* response =
          do_post ~origin:(Some "https://evil.example") ~cookie
            ~fields:(fields @ [ ("dream.csrf", token) ])
            pipeline
        in
        Alcotest.(check int) "cross-origin: 403" 403 (status_of response);
        let* response = do_post ~cookie ~fields pipeline in
        Alcotest.(check int) "missing CSRF: 403" 403 (status_of response);
        let* response =
          do_post ~cookie
            ~fields:(fields @ [ ("dream.csrf", "not-a-token") ])
            pipeline
        in
        Alcotest.(check int) "invalid CSRF: 403" 403 (status_of response);
        let* status = find conn "draft status" q_draft_status draft in
        Alcotest.(check string) "draft still active" "active" status;
        check_no_projects "rejected requests" conn account_id)

  (* === POST /projects: storage failure === *)

  let post_storage_error_case =
    db_case "POST: finalization storage failure is the generic 500"
      (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* _, draft, account_id, ids =
          ready_draft conn ~user:uid ~ext_id:943000023L
            (fun account_id ->
              [ repo ~account_id ~id:pch_poison_repo_id "poison" ])
            ~select:[ 0 ] ~primary:(Some 0)
        in
        let s1 = List.nth ids 0 in
        let* () = exec conn "fail fn" q_create_fail_fn () in
        let* () = exec conn "fail trigger" q_create_fail_trigger () in
        Lwt.finalize
          (fun () ->
            let pipeline = app_pipeline ~session_user_id:uid ~url () in
            let* cookie, token, _ =
              open_identity_form "identity step" ~draft pipeline
            in
            let* response =
              do_post ~cookie
                ~fields:
                  (identity_fields ~draft:(Int64.to_string draft)
                     ~slug:"pch-storage" ~primary:(Int64.to_string s1) ()
                  @ [ ("dream.csrf", token) ])
                pipeline
            in
            Alcotest.(check int) "500" 500 (status_of response);
            Alcotest.(check (option string)) "no Location" None
              (Dream.header response "Location");
            let* body = Dream.body response in
            List.iter (must_not body)
              [ "pch fixture failure"; "Caqti"; "PostgreSQL" ];
            (* The transaction rolled back whole: no partial permanent
               state, and the draft is preserved. *)
            let* status = find conn "draft status" q_draft_status draft in
            Alcotest.(check string) "draft still active" "active" status;
            check_no_projects "storage failure" conn account_id)
          (fun () ->
            let* () = exec conn "drop trigger" q_drop_fail_trigger () in
            exec conn "drop fn" q_drop_fail_fn ()))

  let post_db_suite =
    [ post_success_case; post_replay_case; post_no_selection_case;
      post_stale_primary_case; post_race_unselected_case;
      post_invalid_form_case; post_domain_validation_case;
      post_namespace_conflict_case; post_slug_conflict_case;
      post_claim_conflict_case; post_rejected_no_rows_case;
      post_storage_error_case ]

  (* === GET /projects/:slug/setup: destination authorization === *)

  let setup_authorization_case =
    db_case "GET setup: stewards only; every other state is one generic 404"
      (fun ~url conn ->
        let* steward = insert_user conn "pcreate_a" in
        let* outsider = insert_user conn "pcreate_b" in
        let* creator = insert_user conn "pcreate_c" in
        let* inst =
          Pod_store.insert_installation ~login:"pcreate-owner" conn
            ~ext_id:943000024L ~account_id:943100024L
        in
        let* project =
          insert_project conn ~ns_id:943100024L ~creator
            ~project_name:"Pch Destination" ~slug:"pch-dest" ()
        in
        let* () =
          insert_steward conn ~project ~user:steward ~installation:inst
        in
        let* () =
          insert_repo conn ~project ~position:1 ~gh_id:943600241L
            ~primary:true "alpha"
        in
        let steward_pipeline = app_pipeline ~session_user_id:steward ~url () in
        let* response, body =
          do_get ~target:(setup_target "pch-dest") steward_pipeline
        in
        check_page "steward" response;
        let frag = ps_fragment body in
        must frag "Pch Destination";
        must frag "pcreate-owner/alpha";
        (* No local or GitHub identifier reaches the permanent page. *)
        must_not body "943000024";
        must_not body "943100024";
        must_not body "943600241";
        must_not body (Int64.to_string project);
        (* An unrelated authenticated user gets the generic 404 with no
           name leak and no redirect to the project. *)
        let outsider_pipeline =
          app_pipeline ~session_user_id:outsider ~url ()
        in
        let expect_404 label pipeline target =
          let* response, body = do_get ~target pipeline in
          Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
          Alcotest.(check (option string)) (label ^ ": no redirect") None
            (Dream.header response "Location");
          must_not body "Pch Destination";
          must_not body "pcreate-owner/alpha";
          Lwt.return_unit
        in
        let* () =
          expect_404 "outsider" outsider_pipeline (setup_target "pch-dest")
        in
        (* Creator provenance alone grants nothing. *)
        let creator_pipeline = app_pipeline ~session_user_id:creator ~url () in
        let* () =
          expect_404 "creator" creator_pipeline (setup_target "pch-dest")
        in
        (* Anonymous: the login redirect, not a 404 and not the page. *)
        let anonymous_pipeline = app_pipeline ~url () in
        let* response, _ =
          do_get ~target:(setup_target "pch-dest") anonymous_pipeline
        in
        Alcotest.(check int) "anonymous: 303" 303 (status_of response);
        Alcotest.(check (option string)) "anonymous: /login" (Some "/login")
          (Dream.header response "Location");
        (* Malformed slugs are the same generic 404. *)
        let* () =
          Lwt_list.iter_s
            (fun slug ->
              expect_404 ("slug " ^ slug) steward_pipeline
                (setup_target slug))
            [ "Bad_Slug"; "a--b"; "-lead"; "zz9zz-" ]
        in
        (* Stale and revoked projects vanish for the steward too. *)
        let* () = exec conn "stale" q_set_project_status (project, "stale") in
        let* () =
          expect_404 "stale" steward_pipeline (setup_target "pch-dest")
        in
        let* () =
          exec conn "revoked" q_set_project_status (project, "revoked")
        in
        expect_404 "revoked" steward_pipeline (setup_target "pch-dest"))

  let setup_inconsistent_case =
    db_case "GET setup: durable corruption is the generic 500" (fun ~url conn ->
        let* uid = insert_user conn "pcreate_a" in
        let* inst =
          Pod_store.insert_installation ~login:"pcreate-owner" conn
            ~ext_id:943000025L ~account_id:943100025L
        in
        (* The zero-repository corruption the finalization store can never
           produce. *)
        let* project =
          insert_project conn ~ns_id:943100025L ~project_name:"Pch Corrupt"
            ~slug:"pch-corrupt" ()
        in
        let* () = insert_steward conn ~project ~user:uid ~installation:inst in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* response, body =
          do_get ~target:(setup_target "pch-corrupt") pipeline
        in
        Alcotest.(check int) "500" 500 (status_of response);
        Alcotest.(check (option string)) "no-store" (Some "no-store")
          (Dream.header response "Cache-Control");
        List.iter (must_not body) [ "Caqti"; "PostgreSQL"; "SELECT " ];
        Lwt.return_unit)

  let setup_db_suite = [ setup_authorization_case; setup_inconsistent_case ]
end

(* ===== Project home relation: pure lifecycle domain =====
   DB-free. Closed status vocabulary, exact database conversion, canonical
   optional request note, explicit pending/provisioned constructors, and the
   closed MVP transition matrix. Rejection fixtures are distinctive and only
   ever asserted through booleans against the nullary errors (no public
   printer exists — a compile-time property of the mli), so no submitted
   byte can reach test output. The absence of ID, timestamp, and mutation
   accessors is likewise a compile-time property of the mli, not a runtime
   assertion. *)
module Phr = Earde.Project_home_relation

let phr_case name f = Alcotest.test_case name `Quick f

let phr_expect_ok = function
  | Ok t -> t
  | Error _ -> Alcotest.fail "expected a valid relation"

let phr_pending ?note () = Phr.create_pending ~request_note:note

let phr_status_string t = Phr.string_of_status (Phr.status t)

let phr_note_ok label ~raw ~expect =
  phr_case label (fun () ->
      Alcotest.(check (option string)) "canonical note" expect
        (Phr.request_note (phr_expect_ok (phr_pending ~note:raw ()))))

let phr_note_reject label raw =
  phr_case label (fun () ->
      Alcotest.(check bool) "rejected as invalid note" true
        (match phr_pending ~note:raw () with
        | Error Phr.Invalid_request_note -> true
        | Ok _ | Error Phr.Invalid_transition -> false))

let phr_fresh_pending () = phr_expect_ok (phr_pending ())

let phr_fresh_accepted () =
  phr_expect_ok (Phr.apply (phr_fresh_pending ()) Phr.Accept)

let phr_fresh_rejected () =
  phr_expect_ok (Phr.apply (phr_fresh_pending ()) Phr.Reject)

let phr_fresh_removed () =
  phr_expect_ok (Phr.apply (phr_fresh_accepted ()) Phr.Remove)

let phr_all_statuses = [ Phr.Pending; Phr.Accepted; Phr.Rejected; Phr.Removed ]

let phr_status_cases =
  [ phr_case "every canonical string parses and serializes back" (fun () ->
        List.iter
          (fun (s, st) ->
            (match Phr.status_of_string s with
            | Some parsed ->
                Alcotest.(check bool) "parses to the right variant" true
                  (parsed = st)
            | None -> Alcotest.fail "canonical status string did not parse");
            Alcotest.(check string) "serializes to the database value" s
              (Phr.string_of_status st))
          [ ("pending", Phr.Pending)
          ; ("accepted", Phr.Accepted)
          ; ("rejected", Phr.Rejected)
          ; ("removed", Phr.Removed)
          ])
  ; phr_case "every status round-trips" (fun () ->
        List.iter
          (fun st ->
            Alcotest.(check bool) "round trip" true
              (Phr.status_of_string (Phr.string_of_status st) = Some st))
          phr_all_statuses)
  ; phr_case "capitalization, padding, and unknown variants reject" (fun () ->
        List.iter
          (fun s ->
            Alcotest.(check bool) "rejected" true
              (Phr.status_of_string s = None))
          [ "Pending"
          ; "PENDING"
          ; "Accepted"
          ; " pending"
          ; "pending "
          ; "accepted\n"
          ; "\trejected"
          ; "reject"
          ; "rej"
          ; "approved"
          ; "cancelled"
          ; "active"
          ; "home"
          ; ""
          ; "unknown"
          ])
  ]

let phr_pending_cases =
  [ phr_case "absent note stays absent" (fun () ->
        Alcotest.(check (option string)) "no note" None
          (Phr.request_note (phr_expect_ok (phr_pending ()))))
  ; phr_note_ok "empty note collapses to none" ~raw:"" ~expect:None
  ; phr_note_ok "ascii-whitespace-only note collapses to none"
      ~raw:" \t\r\n\x0c\x0b " ~expect:None
  ; phr_note_ok "ordinary note accepted"
      ~raw:"We already discuss releases in this community."
      ~expect:(Some "We already discuss releases in this community.")
  ; phr_note_ok "outer ascii whitespace trims" ~raw:"  needs moderator eyes \t "
      ~expect:(Some "needs moderator eyes")
  ; phr_note_ok "internal ordinary spaces preserved"
      ~raw:"two  spaces   survive" ~expect:(Some "two  spaces   survive")
  ; phr_note_ok "crlf becomes lf" ~raw:"line one\r\nline two"
      ~expect:(Some "line one\nline two")
  ; phr_note_ok "lone cr becomes lf" ~raw:"line one\rline two"
      ~expect:(Some "line one\nline two")
  ; phr_note_ok "multiline utf-8 note accepted"
      ~raw:"Progetto Citt\xc3\xa0\nseconda riga \xe2\x98\x95"
      ~expect:(Some "Progetto Citt\xc3\xa0\nseconda riga \xe2\x98\x95")
  ; phr_note_ok "internal horizontal tab accepted" ~raw:"col a\tcol b"
      ~expect:(Some "col a\tcol b")
  ; phr_case "pending constructor yields status pending" (fun () ->
        Alcotest.(check string) "status" "pending"
          (phr_status_string (phr_fresh_pending ())))
  ]

let phr_note_boundary_cases =
  [ phr_case "exactly 2000 ascii scalars accepted without truncation"
      (fun () ->
        let note = String.make 2000 'a' in
        Alcotest.(check (option string)) "byte-exact note" (Some note)
          (Phr.request_note (phr_expect_ok (phr_pending ~note ()))))
  ; phr_note_reject "2001 ascii scalars reject rather than truncate"
      (String.make 2001 'a')
  ; phr_case "exactly 2000 two-byte scalars accepted, counted per scalar"
      (fun () ->
        (* 2000 two-byte scalars: byte counting would see 4000 and reject. *)
        let note = String.concat "" (List.init 2000 (fun _ -> "\xc3\xa9")) in
        Alcotest.(check (option string)) "byte-exact note" (Some note)
          (Phr.request_note (phr_expect_ok (phr_pending ~note ()))))
  ; phr_note_reject "2001 two-byte scalars reject"
      (String.concat "" (List.init 2001 (fun _ -> "\xc3\xa9")))
  ; phr_note_reject "malformed utf-8: stray continuation" "a\xffb"
  ; phr_note_reject "malformed utf-8: truncated sequence" "a\xc3"
  ; phr_note_reject "malformed utf-8: overlong encoding" "a\xc0\xafb"
  ; phr_note_reject "malformed utf-8: utf-16 surrogate" "a\xed\xa0\x80b"
  ; phr_note_reject "malformed utf-8: above U+10FFFF" "a\xf4\x90\x80\x80b"
  ; phr_note_reject "embedded nul" "a\x00b"
  ; phr_note_reject "control byte 0x01" "a\x01b"
  ; phr_note_reject "internal vertical tab" "a\x0bb"
  ; phr_note_reject "internal form feed" "a\x0cb"
  ; phr_note_reject "escape byte" "a\x1bb"
  ; phr_note_reject "del byte" "a\x7fb"
  ]

let phr_provisioned_cases =
  [ phr_case "provisioned home is accepted with no note" (fun () ->
        (* The constructor returns the accepted value directly — no pending
           intermediate state ever exists or is observable. *)
        let t = Phr.create_provisioned_home () in
        Alcotest.(check string) "status" "accepted" (phr_status_string t);
        Alcotest.(check (option string)) "note" None (Phr.request_note t))
  ]

let phr_valid_transition_cases =
  [ phr_case "pending + accept becomes accepted" (fun () ->
        Alcotest.(check string) "status" "accepted"
          (phr_status_string
             (phr_expect_ok (Phr.apply (phr_fresh_pending ()) Phr.Accept))))
  ; phr_case "pending + reject becomes rejected" (fun () ->
        Alcotest.(check string) "status" "rejected"
          (phr_status_string
             (phr_expect_ok (Phr.apply (phr_fresh_pending ()) Phr.Reject))))
  ; phr_case "accepted + remove becomes removed" (fun () ->
        Alcotest.(check string) "status" "removed"
          (phr_status_string
             (phr_expect_ok (Phr.apply (phr_fresh_accepted ()) Phr.Remove))))
  ]

let phr_invalid label make_t action =
  phr_case label (fun () ->
      Alcotest.(check bool) "invalid transition" true
        (match Phr.apply (make_t ()) action with
        | Error Phr.Invalid_transition -> true
        | Ok _ | Error Phr.Invalid_request_note -> false))

let phr_invalid_transition_cases =
  [ phr_invalid "pending + remove" phr_fresh_pending Phr.Remove
  ; phr_invalid "accepted + accept" phr_fresh_accepted Phr.Accept
  ; phr_invalid "accepted + reject" phr_fresh_accepted Phr.Reject
  ; phr_invalid "rejected + accept" phr_fresh_rejected Phr.Accept
  ; phr_invalid "rejected + reject" phr_fresh_rejected Phr.Reject
  ; phr_invalid "rejected + remove" phr_fresh_rejected Phr.Remove
  ; phr_invalid "removed + accept" phr_fresh_removed Phr.Accept
  ; phr_invalid "removed + reject" phr_fresh_removed Phr.Reject
  ; phr_invalid "removed + remove" phr_fresh_removed Phr.Remove
  ]

let phr_preservation_cases =
  [ phr_case "note is byte-exact through pending, accepted, removed" (fun () ->
        let note =
          "First line\nseconda riga \xc3\xa9\n\tindented tail"
        in
        let pending = phr_expect_ok (phr_pending ~note ()) in
        Alcotest.(check (option string)) "pending note" (Some note)
          (Phr.request_note pending);
        let accepted = phr_expect_ok (Phr.apply pending Phr.Accept) in
        Alcotest.(check (option string)) "accepted note" (Some note)
          (Phr.request_note accepted);
        let removed = phr_expect_ok (Phr.apply accepted Phr.Remove) in
        Alcotest.(check (option string)) "removed note" (Some note)
          (Phr.request_note removed))
  ; phr_case "note is byte-exact through pending, rejected" (fun () ->
        let note = "Historical context\nfor the moderators" in
        let pending = phr_expect_ok (phr_pending ~note ()) in
        let rejected = phr_expect_ok (Phr.apply pending Phr.Reject) in
        Alcotest.(check (option string)) "rejected note" (Some note)
          (Phr.request_note rejected))
  ; phr_case "provisioned home stays note-free after removal" (fun () ->
        let removed =
          phr_expect_ok (Phr.apply (Phr.create_provisioned_home ()) Phr.Remove)
        in
        Alcotest.(check (option string)) "note" None (Phr.request_note removed))
  ]

(* Terminal history is never reopened: a later attempt is a brand-new
   community_projects row represented by a brand-new create_pending value.
   No relation IDs exist in the domain, so "new" means a fresh value. *)
let phr_fresh_row_cases =
  [ phr_case "rejected value cannot be reopened; a new pending value can"
      (fun () ->
        let rejected = phr_fresh_rejected () in
        List.iter
          (fun action ->
            Alcotest.(check bool) "terminal" true
              (Phr.apply rejected action = Error Phr.Invalid_transition))
          [ Phr.Accept; Phr.Reject; Phr.Remove ];
        Alcotest.(check string) "separate new request" "pending"
          (phr_status_string (phr_fresh_pending ())))
  ; phr_case "removed value cannot be reopened; a new pending value can"
      (fun () ->
        let removed = phr_fresh_removed () in
        List.iter
          (fun action ->
            Alcotest.(check bool) "terminal" true
              (Phr.apply removed action = Error Phr.Invalid_transition))
          [ Phr.Accept; Phr.Reject; Phr.Remove ];
        Alcotest.(check string) "separate new request" "pending"
          (phr_status_string (phr_fresh_pending ())))
  ]

let phr_ordering_cases =
  [ phr_case "invalid note fails before any pending value exists" (fun () ->
        Alcotest.(check bool) "note rejection from the constructor" true
          (phr_pending ~note:"phr-fixture-\x01-bad" ()
          = Error Phr.Invalid_request_note))
  ; phr_case "a valid value reports only invalid transition afterwards"
      (fun () ->
        Alcotest.(check bool) "transition rejection from apply" true
          (Phr.apply (phr_fresh_accepted ()) Phr.Accept
          = Error Phr.Invalid_transition))
  ]

let phr_privacy_cases =
  [ phr_case "every rejection is a payload-free constructor" (fun () ->
        let all = [ Phr.Invalid_request_note; Phr.Invalid_transition ] in
        (* Distinctive fixture values: were any error to carry its input, the
           closed-membership check below could not hold for all of them. No
           public printer or serializer exists (compile-time mli property),
           so no rejected byte can reach output through this module. *)
        let rejections =
          [ phr_pending ~note:"phr-fixture-note-\x00-secret" ()
          ; phr_pending ~note:"phr-fixture-note-\x7f-secret" ()
          ; phr_pending ~note:("phr-" ^ String.make 2100 'z') ()
          ; Phr.apply (phr_fresh_rejected ()) Phr.Accept
          ]
        in
        List.iter
          (fun outcome ->
            match outcome with
            | Ok _ -> Alcotest.fail "expected a rejection"
            | Error e ->
                Alcotest.(check bool) "nullary error" true (List.mem e all))
          rejections)
  ]

(* === Scoped network-community identity constraints (shared helpers) ===
   Migration 20260726120000 bars noncanonical identity values on
   is_network_community rows at the database boundary, which also bars the
   corruption several gated cases plant on purpose to exercise
   application-level Inconsistent_data defenses. Those cases drop the
   three named constraints for one probe and restore them under
   Lwt.finalize once the corrupt rows are canonical or gone; the schema
   suite reuses the exact same statements for its down/up round-trip
   proof. The ADD statements are byte-for-byte the migration's, so a
   drifted migration fails these tests rather than silently diverging. *)
module Ncid_relax = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let ddl sql = (Caqti_type.unit ->. Caqti_type.unit) sql

  let drop_statements =
    [ ddl
        "ALTER TABLE communities \
         DROP CONSTRAINT IF EXISTS communities_network_name_check"
    ; ddl
        "ALTER TABLE communities \
         DROP CONSTRAINT IF EXISTS communities_network_slug_check"
    ; ddl
        "ALTER TABLE communities \
         DROP CONSTRAINT IF EXISTS communities_network_description_check"
    ]

  let add_statements =
    [ ddl
        "ALTER TABLE communities \
         ADD CONSTRAINT communities_network_name_check CHECK ( \
           NOT is_network_community OR ( \
             char_length(name) >= 1 \
             AND char_length(name) <= 120 \
             AND name !~ '[\\x01-\\x1f\\x7f]' \
             AND name !~ '^ ' \
             AND name !~ ' $'))"
    ; ddl
        "ALTER TABLE communities \
         ADD CONSTRAINT communities_network_slug_check CHECK ( \
           NOT is_network_community OR ( \
             slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' \
             AND char_length(slug) <= 80))"
    ; ddl
        "ALTER TABLE communities \
         ADD CONSTRAINT communities_network_description_check CHECK ( \
           NOT is_network_community OR description IS NULL OR ( \
             char_length(description) >= 1 \
             AND char_length(description) <= 2000 \
             AND description !~ '[\\x01-\\x08\\x0b-\\x1f\\x7f]' \
             AND description !~ '^[ \\t\\n]' \
             AND description !~ '[ \\t\\n]$'))"
    ]

  let run conn statements =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    Lwt_list.iter_s
      (fun q ->
        let* r = C.exec q () in
        let* _ = Pod_schema.or_fail "identity constraint DDL" r in
        Lwt.return_unit)
      statements

  let drop conn = run conn drop_statements
  let restore conn = run conn add_statements

  (* One canonicalizing restore for finalize blocks: whatever a probe left
     behind, the row is valid again before the constraints return. *)
  let q_recanonicalize =
    (Caqti_type.(t3 int string string) ->. Caqti_type.unit)
    "UPDATE communities SET slug = $2, name = $3, description = NULL \
     WHERE id = $1"
end

(* Scoped network-community lifecycle constraint (migration 20260726130000):
   the same drop/restore pattern as Ncid_relax, for the fixtures that
   deliberately write lifecycle shapes the CHECK now forbids at the database
   — a published network community reverted to private, a leaking or public
   draft, mixed published flags. Those durable shapes are no longer
   producible in production, but the defensive branches that tolerate or
   reject them are still worth exercising, so the affected fixtures relax
   the constraint for the length of one case and restore it (validated)
   after their rows are re-normalized or deleted. *)
module Nclc_relax = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let ddl sql = (Caqti_type.unit ->. Caqti_type.unit) sql

  let drop_statements =
    [ ddl
        "ALTER TABLE communities \
         DROP CONSTRAINT IF EXISTS communities_network_lifecycle_check"
    ]

  let add_statements =
    [ ddl
        "ALTER TABLE communities \
         ADD CONSTRAINT communities_network_lifecycle_check CHECK ( \
           NOT is_network_community OR ( \
             (onboarding_state = 'draft' \
              AND visibility = 'private' \
              AND NOT indexable \
              AND NOT discoverable) \
             OR \
             (onboarding_state = 'published' \
              AND visibility = 'public' \
              AND indexable = discoverable)))"
    ]

  let run conn statements =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    Lwt_list.iter_s
      (fun q ->
        let* r = C.exec q () in
        let* _ = Pod_schema.or_fail "lifecycle constraint DDL" r in
        Lwt.return_unit)
      statements

  let drop conn = run conn drop_statements
  let restore conn = run conn add_statements

  let run_cleanup conn queries =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    Lwt_list.iter_s
      (fun q ->
        let* r = C.exec q () in
        let* _ = Pod_schema.or_fail "relaxed cleanup" r in
        Lwt.return_unit)
      queries

  (* Wrap one case body: the constraint is dropped before it runs, and the
     given cleanup (normally the suite's own fixture deletes) removes every
     drift row before the constraint is restored, validated, under
     Lwt.finalize — even when an assertion fails mid-case. *)
  let around conn ~cleanup f =
    let* () = drop conn in
    Lwt.finalize f (fun () -> Lwt.finalize cleanup (fun () -> restore conn))
end

(* === Project home request store (Project_home_request_store) ===
   Transactional creation of a pending home-relation request, driven over
   verified permanent projects built through the real draft/selection/
   finalization chain. Database-gated (EARDE_TEST_DATABASE_URL, same
   opt-in as Mod_scope) with its own reserved external-installation-id
   range 944200001..944200999 (hence account ids 944300001..944300999,
   which also scope the permanent-project cleanup), phrq_% usernames, and
   phrq-% community slugs so no suite shares fixtures. Pure validation is
   proven pre-SQL against a deliberately disconnected connection. The
   pure relation values come only from Project_home_relation's real
   constructors. Credential assertions are boolean, so no fixture byte
   reaches test output on failure. *)
module Phrq = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rq = Earde.Project_home_request_store
  module Fin = Earde.Project_finalization_store

  let error_str : Rq.error -> string = function
    | Rq.Invalid_user_id -> "Invalid_user_id"
    | Rq.Invalid_project_slug -> "Invalid_project_slug"
    | Rq.Invalid_community_id -> "Invalid_community_id"
    | Rq.Invalid_relation -> "Invalid_relation"
    | Rq.Project_unavailable -> "Project_unavailable"
    | Rq.Community_unavailable -> "Community_unavailable"
    | Rq.Active_home_exists -> "Active_home_exists"
    | Rq.Inconsistent_data -> "Inconsistent_data"
    | Rq.Storage_error -> "Storage_error"

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let contains = Cprj_schema.contains

  (* Projects first (stewards, repositories, and home relations cascade
     from them, and stewards RESTRICT-protect installations); drafts next
     (installations are RESTRICT-protected while referenced); communities
     cascade their remaining relations; installations last. The LIKE
     pattern also catches deliberately corrupted phrq- slugs. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 944300001 AND 944300999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 944300001 AND 944300999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 944200001 AND 944200999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phrq-%'"
      ; "DELETE FROM users WHERE username LIKE 'phrq_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 944200001 AND 944200999"
      ]

  (* Direct community fixtures: the dedicated-community provisioning
     store does not exist yet, so lifecycle shapes are written exactly as
     the durable columns represent them today. Defaults are the eligible
     fully listed published network community. *)
  let q_insert_community =
    (Caqti_type.(t2 (t2 string string) (t2 (t2 bool bool) (t2 string bool)))
     ->! Caqti_type.int)
    "INSERT INTO communities \
       (slug, name, visibility, indexable, is_network_community, \
        onboarding_state, discoverable) \
     VALUES ($1, $1, $2, $3, $4, $5, $6) RETURNING id"

  let insert_community ?(visibility = "public") ?(indexable = true)
      ?(network = true) ?(onboarding = "published") ?(discoverable = true)
      conn slug =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* cid =
      C.find q_insert_community
        ((slug, visibility), ((indexable, network), (onboarding, discoverable)))
    in
    or_fail ("community " ^ slug) cid

  (* Everything durable on one relation row; timestamp columns reduce to
     presence/ordering booleans (their exact values are NOW()-relative). *)
  let q_relation_row =
    (Caqti_type.(int64 ->!
        t2 (t2 (t2 int64 int) (t2 string string))
           (t2 (t2 (option int) (option int))
               (t2 (option string) (t3 bool bool bool)))))
    "SELECT project_id, community_id, relation_type, status, \
            requested_by_user_id, reviewed_by_user_id, request_note, \
            reviewed_at IS NOT NULL, removed_at IS NOT NULL, \
            updated_at >= created_at \
     FROM community_projects WHERE id = $1"

  let relation_row conn id = find conn "relation row" q_relation_row id

  (* One text signature per relation row, for exact unchanged-history
     assertions. *)
  let q_relation_sig =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT project_id::text || '|' || community_id::text || '|' || \
            relation_type || '|' || status || '|' || \
            COALESCE(requested_by_user_id::text, '<null>') || '|' || \
            COALESCE(reviewed_by_user_id::text, '<null>') || '|' || \
            COALESCE(request_note, '<null>') || '|' || \
            (reviewed_at IS NOT NULL)::text || '|' || \
            (removed_at IS NOT NULL)::text \
     FROM community_projects WHERE id = $1"

  let q_community_sig =
    (Caqti_type.int ->! Caqti_type.string)
    "SELECT slug || '|' || name || '|' || visibility || '|' || \
            indexable::text || '|' || is_network_community::text || '|' || \
            onboarding_state || '|' || discoverable::text \
     FROM communities WHERE id = $1"

  let q_project_sig =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT slug || '|' || verification_status \
     FROM open_source_projects WHERE id = $1"

  let q_count_for_project =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_projects WHERE project_id = $1"

  let q_count_active_for_project =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_projects \
     WHERE project_id = $1 AND status IN ('pending', 'accepted')"

  let q_active_community_for_project =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT community_id FROM community_projects \
     WHERE project_id = $1 AND status IN ('pending', 'accepted')"

  let q_count_pending_for_community =
    (Caqti_type.int ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_projects \
     WHERE community_id = $1 AND status = 'pending'"

  let q_count_members =
    (Caqti_type.int ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_members WHERE community_id = $1"

  let q_count_moderators =
    (Caqti_type.int ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_moderators WHERE community_id = $1"

  let q_count_stewards_for_project =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM project_stewards WHERE project_id = $1"

  (* Store-shaped lifecycle transitions with coherent timestamps, used to
     free the active slot and to build accepted/historical fixtures.
     Transition legality itself is Project_home_relation territory. *)
  let q_mark_rejected =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects \
     SET status = 'rejected', reviewed_at = NOW(), updated_at = NOW() \
     WHERE id = $1"

  let q_mark_accepted =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects \
     SET status = 'accepted', reviewed_at = NOW(), updated_at = NOW() \
     WHERE id = $1"

  let q_mark_removed =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects \
     SET status = 'removed', reviewed_at = COALESCE(reviewed_at, NOW()), \
         removed_at = NOW(), updated_at = NOW() \
     WHERE id = $1"

  (* Project- and installation-side probes for the authorization cases. *)
  let q_set_verification =
    (Caqti_type.(t2 int64 string) ->. Caqti_type.unit)
    "UPDATE open_source_projects SET verification_status = $2 WHERE id = $1"

  let q_set_created_by =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "UPDATE open_source_projects SET created_by_user_id = $2 WHERE id = $1"

  let q_delete_steward =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "DELETE FROM project_stewards WHERE project_id = $1 AND user_id = $2"

  let q_insert_steward =
    (Caqti_type.(t3 int64 int int64) ->. Caqti_type.unit)
    "INSERT INTO project_stewards \
       (project_id, user_id, github_installation_record_id, role) \
     VALUES ($1, $2, $3, 'steward')"

  let q_clear_installation_provenance =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE github_installations SET connected_by_user_id = NULL \
     WHERE id = $1"

  (* Community-side probes. *)
  let q_delete_community =
    (Caqti_type.int ->. Caqti_type.unit)
    "DELETE FROM communities WHERE id = $1"

  (* Positive ids guaranteed absent, for the missing-community probe. *)
  let q_absent_community_id =
    (Caqti_type.unit ->! Caqti_type.int)
    "SELECT COALESCE(MAX(id), 0) + 1000000 FROM communities"

  (* Targeted durable corruption: communities.slug carries no schema
     grammar, so a non-addressable stored slug is directly producible;
     the mixed published flag shape is likewise representable (the
     lifecycle invariant is application-level). visibility and
     onboarding_state off-enum corruption is blocked by their DB CHECKs,
     and a non-positive returned relation id by BIGSERIAL — those
     Inconsistent_data branches stay defensive. *)
  let q_corrupt_community_slug =
    (Caqti_type.(t2 int string) ->. Caqti_type.unit)
    "UPDATE communities SET slug = $2 WHERE id = $1"

  let q_mix_community_flags =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET indexable = TRUE, discoverable = FALSE \
     WHERE id = $1"

  (* Every text column of one relation row, and the same minus the note,
     for the boolean credential-absence checks. *)
  let q_relation_text_blob =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT project_id::text || '|' || community_id::text || '|' || \
            relation_type || '|' || status || '|' || \
            COALESCE(requested_by_user_id::text, '') || '|' || \
            COALESCE(reviewed_by_user_id::text, '') || '|' || \
            COALESCE(request_note, '') \
     FROM community_projects WHERE id = $1"

  let q_relation_nonnote_blob =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT project_id::text || '|' || community_id::text || '|' || \
            relation_type || '|' || status || '|' || \
            COALESCE(requested_by_user_id::text, '') || '|' || \
            COALESCE(reviewed_by_user_id::text, '') \
     FROM community_projects WHERE id = $1"

  (* Test-only failure injection for the rollback case: an AFTER trigger
     scoped to one reserved note value, so the failure fires only after
     the insertion was genuinely attempted. Installed and dropped inside
     that case alone (IF EXISTS drops keep the cleanup idempotent even
     after a mid-case failure); production migrations are untouched. The
     function body uses plain string quoting — Caqti templates reserve
     '$'. *)
  let phrq_poison_note = "phrq poison marker"

  let q_create_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE FUNCTION phrq_fail_insert_fn() RETURNS trigger
     LANGUAGE plpgsql
     AS 'BEGIN RAISE EXCEPTION ''phrq fixture failure''; END'"

  let q_create_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE TRIGGER phrq_fail_insert
     AFTER INSERT ON community_projects
     FOR EACH ROW WHEN (NEW.request_note = 'phrq poison marker')
     EXECUTE FUNCTION phrq_fail_insert_fn()"

  let q_drop_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP TRIGGER IF EXISTS phrq_fail_insert ON community_projects"

  let q_drop_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP FUNCTION IF EXISTS phrq_fail_insert_fn()"

  (* Each case gets a fresh connection and a clean fixture slate; cleanup
     runs again afterwards even when an assertion fails mid-way. The
     connection is disconnected deterministically — the gated suite is
     large enough that leaving per-case connections to the GC brushes
     against Postgres's max_connections. *)
  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f conn))

  (* Verified permanent projects come only through the real chain —
     draft store, selection store, finalization store — never fixture
     INSERTs. Returns the installation record id (for steward fixtures)
     and the permanent project id. *)
  let make_project conn ~user ~ext_id ~slug =
    let repo_id = Int64.add ext_id 400000L in
    let* inst, draft, _, _ =
      Pfin.make_draft conn ~user ~ext_id (fun account_id ->
          [ Pfin.repo ~account_id ~id:repo_id "alpha" ])
    in
    let* ids = Pfin.snapshot_ids conn draft in
    let s1 = List.nth ids 0 in
    let* () =
      Pod_select.replace_ok "seed selection" conn ~user ~draft ~primary:s1
        [ s1 ]
    in
    let identity =
      Pfin.identity_exn ~slug ~selected:[ s1 ] ~primary:s1 ()
    in
    let* created =
      Pfin.finalize_ok "fixture project" conn ~user ~draft identity
    in
    Lwt.return (inst, Fin.project_id created)

  (* === call helpers === *)

  let create conn ~user ~slug ~community relation =
    Rq.create conn ~user_id:user ~project_slug:slug
      ~target_community_id:community ~relation

  let create_ok label conn ~user ~slug ~community relation =
    let* r = create conn ~user ~slug ~community relation in
    match r with
    | Ok created -> Lwt.return created
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let create_expect label expected conn ~user ~slug ~community relation =
    let* r = create conn ~user ~slug ~community relation in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  let count_for_project conn project =
    find conn "relation count" q_count_for_project project

  let check_no_relations label conn project =
    let* n = count_for_project conn project in
    Alcotest.(check int) label 0 n;
    Lwt.return_unit

  let mark label conn q relation =
    exec conn label q relation

  (* One winner plus one exact loser, order unasserted. *)
  let ok_and_error label expected (r1, r2) =
    match (r1, r2) with
    | Ok created, Error e when e = expected -> created
    | Error e, Ok created when e = expected -> created
    | Ok _, Ok _ -> Alcotest.failf "%s: both succeeded" label
    | Error a, Error b ->
        Alcotest.failf "%s: both failed (%s, %s)" label (error_str a)
          (error_str b)
    | Ok _, Error e | Error e, Ok _ ->
        Alcotest.failf "%s: unexpected loser error %s" label (error_str e)

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "request: invalid inputs rejected before any SQL" (fun _conn ->
        (* A deliberately unusable connection: pure validation must
           return without touching it — were any SQL attempted, the
           result would be Storage_error (or a test-failing exception),
           never the expected input error. *)
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let pending = phr_fresh_pending () in
        let expect label e ~user ~slug ~community relation =
          create_expect label e dead ~user ~slug ~community relation
        in
        let* () =
          expect "user id 0" Rq.Invalid_user_id ~user:0 ~slug:"phrq-a"
            ~community:1 pending
        in
        let* () =
          expect "negative user id" Rq.Invalid_user_id ~user:(-7)
            ~slug:"phrq-a" ~community:1 pending
        in
        let* () =
          expect "user checked before slug" Rq.Invalid_user_id ~user:0
            ~slug:"NOT A SLUG" ~community:0 pending
        in
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              expect "invalid project slug" Rq.Invalid_project_slug ~user:1
                ~slug:bad ~community:1 pending)
            [ ""
            ; "Phrq-Upper"
            ; "phrq slug"
            ; " phrq-a"
            ; "phrq-a "
            ; "phrq_a"
            ; "phrq/a"
            ; "-phrq"
            ; "phrq-"
            ; "phrq--a"
            ; String.make 81 'a'
            ]
        in
        let* () =
          expect "community id 0" Rq.Invalid_community_id ~user:1
            ~slug:"phrq-a" ~community:0 pending
        in
        let* () =
          expect "negative community id" Rq.Invalid_community_id ~user:1
            ~slug:"phrq-a" ~community:(-4) pending
        in
        let* () =
          expect "accepted relation" Rq.Invalid_relation ~user:1
            ~slug:"phrq-a" ~community:1
            (phr_fresh_accepted ())
        in
        let* () =
          expect "rejected relation" Rq.Invalid_relation ~user:1
            ~slug:"phrq-a" ~community:1
            (phr_fresh_rejected ())
        in
        expect "removed relation" Rq.Invalid_relation ~user:1 ~slug:"phrq-a"
          ~community:1
          (phr_fresh_removed ()))

  (* === successful request === *)

  let success_case =
    db_case "request: complete pending request round-trips exactly"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200001L
            ~slug:"phrq-success"
        in
        let* community = insert_community conn "phrq-home" in
        let note =
          "Prima riga — gi\xc3\xa0 discutiamo qui \xe2\x98\x95\n\
           \tseconda riga indentata"
        in
        let relation =
          phr_expect_ok (Phr.create_pending ~request_note:(Some note))
        in
        let* created =
          create_ok "request" conn ~user:uid ~slug:"phrq-success" ~community
            relation
        in
        Alcotest.(check bool) "relation id positive" true
          (Rq.relation_id created > 0L);
        let* ( ((rp, rc), (rtype, status))
             , ((req, rev), (stored_note, (has_reviewed, has_removed, upd_ge)))
             ) =
          relation_row conn (Rq.relation_id created)
        in
        Alcotest.(check int64) "exact project fk" project rp;
        Alcotest.(check int) "exact community fk" community rc;
        Alcotest.(check string) "relation type home" "home" rtype;
        Alcotest.(check string) "status pending" "pending" status;
        Alcotest.(check (option int)) "requester is supplied user"
          (Some uid) req;
        Alcotest.(check (option int)) "no reviewer" None rev;
        Alcotest.(check (option string)) "canonical note byte-exact"
          (Some note) stored_note;
        Alcotest.(check bool) "reviewed_at NULL" false has_reviewed;
        Alcotest.(check bool) "removed_at NULL" false has_removed;
        Alcotest.(check bool) "timestamps coherent" true upd_ge;
        let* n = count_for_project conn project in
        Alcotest.(check int) "exactly one relation" 1 n;
        (* Submitting a request grants nothing: no membership, no
           moderation, no stewardship change. *)
        let* members = find conn "members" q_count_members community in
        Alcotest.(check int) "no membership created" 0 members;
        let* mods = find conn "moderators" q_count_moderators community in
        Alcotest.(check int) "no moderator created" 0 mods;
        let* stewards =
          find conn "stewards" q_count_stewards_for_project project
        in
        Alcotest.(check int) "stewardship unchanged" 1 stewards;
        Lwt.return_unit)

  (* === note variants === *)

  let note_variants_case =
    db_case "request: note variants persist through the domain constructor"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, _project =
          make_project conn ~user:uid ~ext_id:944200002L ~slug:"phrq-notes"
        in
        let* community = insert_community conn "phrq-notes-home" in
        let utf8 = "Progetto Citt\xc3\xa0\nseconda riga \xe2\x98\x95" in
        let exact_2000 = String.make 2000 'a' in
        Lwt_list.iter_s
          (fun (label, raw, expected) ->
            let relation =
              phr_expect_ok (Phr.create_pending ~request_note:raw)
            in
            let* created =
              create_ok label conn ~user:uid ~slug:"phrq-notes" ~community
                relation
            in
            let* _, (_, (stored_note, _)) =
              relation_row conn (Rq.relation_id created)
            in
            Alcotest.(check (option string)) label expected stored_note;
            (* Free the active slot for the next variant; the historical
               row stays behind. *)
            mark "free slot" conn q_mark_rejected (Rq.relation_id created))
          [ ("absent note stays NULL", None, None)
          ; ("blank note canonicalizes to NULL", Some " \t\r\n ", None)
          ; ("utf-8 multiline note", Some utf8, Some utf8)
          ; ("exact 2000-character note", Some exact_2000, Some exact_2000)
          ])

  (* === project authorization === *)

  let project_unavailable_case =
    db_case "request: every unavailable-project cause collapses identically"
      (fun conn ->
        let* a = insert_user conn "phrq_a" in
        let* b = insert_user conn "phrq_b" in
        let* _, project =
          make_project conn ~user:a ~ext_id:944200003L ~slug:"phrq-auth"
        in
        let* community = insert_community conn "phrq-auth-home" in
        let pending () = phr_fresh_pending () in
        let expect label ~user ~slug =
          create_expect label Rq.Project_unavailable conn ~user ~slug
            ~community (pending ())
        in
        (* Missing project: canonical grammar, nothing stored under it. *)
        let* () = expect "missing project" ~user:a ~slug:"phrq-absent" in
        (* Another user's project. *)
        let* () = expect "foreign project" ~user:b ~slug:"phrq-auth" in
        (* Stale, then revoked verification. *)
        let* () =
          exec conn "mark stale" q_set_verification (project, "stale")
        in
        let* () = expect "stale project" ~user:a ~slug:"phrq-auth" in
        let* () =
          exec conn "mark revoked" q_set_verification (project, "revoked")
        in
        let* () = expect "revoked project" ~user:a ~slug:"phrq-auth" in
        let* () =
          exec conn "restore verified" q_set_verification
            (project, "verified")
        in
        (* Deleted stewardship: the creator keeps created_by provenance
           but loses authorization entirely. *)
        let* () = exec conn "drop steward" q_delete_steward (project, a) in
        let* () =
          expect "creator without stewardship" ~user:a ~slug:"phrq-auth"
        in
        check_no_relations "no insert from any cause" conn project)

  let project_authorization_case =
    db_case
      "request: stewardship alone authorizes — provenance never does"
      (fun conn ->
        let* a = insert_user conn "phrq_a" in
        let* b = insert_user conn "phrq_b" in
        let* inst, project =
          make_project conn ~user:a ~ext_id:944200004L ~slug:"phrq-auth2"
        in
        let* community = insert_community conn "phrq-auth2-home" in
        (* Reassign creation provenance and erase installation
           provenance: authorization must not move with either. *)
        let* () = exec conn "created_by to b" q_set_created_by (project, b) in
        let* () =
          exec conn "clear provenance" q_clear_installation_provenance inst
        in
        let* created =
          create_ok "steward still authorized" conn ~user:a
            ~slug:"phrq-auth2" ~community (phr_fresh_pending ())
        in
        (* The new creator-of-record is still not a steward. *)
        let* () =
          create_expect "creator-of-record without stewardship"
            Rq.Project_unavailable conn ~user:b ~slug:"phrq-auth2"
            ~community (phr_fresh_pending ())
        in
        let* () =
          mark "free slot" conn q_mark_rejected (Rq.relation_id created)
        in
        (* A second steward may submit. *)
        let* () =
          exec conn "second steward" q_insert_steward (project, b, inst)
        in
        let* created_b =
          create_ok "second steward submits" conn ~user:b ~slug:"phrq-auth2"
            ~community (phr_fresh_pending ())
        in
        let* ((_, rc), (_, status)), ((req, _), _) =
          relation_row conn (Rq.relation_id created_b)
        in
        Alcotest.(check int) "second steward's request targets community"
          community rc;
        Alcotest.(check string) "second steward's request pending" "pending"
          status;
        Alcotest.(check (option int)) "requester is the second steward"
          (Some b) req;
        Lwt.return_unit)

  (* === community eligibility === *)

  let community_unavailable_case =
    db_case_lifecycle_relaxed
      "request: every ineligible-community cause collapses identically"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200005L ~slug:"phrq-celig"
        in
        let expect label community =
          create_expect label Rq.Community_unavailable conn ~user:uid
            ~slug:"phrq-celig" ~community (phr_fresh_pending ())
        in
        (* Missing community. *)
        let* absent = find conn "absent id" q_absent_community_id () in
        let* () = expect "missing community" absent in
        (* Legacy/general communities, both visibilities. *)
        let* legacy = insert_community ~network:false conn "phrq-legacy" in
        let* () = expect "legacy public community" legacy in
        let* legacy_private =
          insert_community ~network:false ~visibility:"private"
            ~indexable:false ~discoverable:false conn "phrq-legacy-priv"
        in
        let* () = expect "legacy private community" legacy_private in
        (* Network setup draft in its canonical private shape. *)
        let* draft =
          insert_community ~onboarding:"draft" ~visibility:"private"
            ~indexable:false ~discoverable:false conn "phrq-draft"
        in
        let* () = expect "setup draft" draft in
        (* A representable ineligible drift: draft state with public
           flags is still unpublished. *)
        let* draft_public =
          insert_community ~onboarding:"draft" conn "phrq-draft-pub"
        in
        let* () = expect "unpublished public-flagged draft" draft_public in
        (* Fully private published network community (representable —
           the never-private-after-publish invariant is app-level). *)
        let* private_network =
          insert_community ~visibility:"private" ~indexable:false
            ~discoverable:false conn "phrq-private"
        in
        let* () = expect "fully private network community" private_network in
        (* Deletion boundary: an eligible community deleted before the
           request locks it is unavailable, never an FK diagnostic. *)
        let* deleted = insert_community conn "phrq-deleted" in
        let* () = exec conn "delete community" q_delete_community deleted in
        let* () = expect "deleted community" deleted in
        check_no_relations "no insert from any cause" conn project)

  let eligible_modes_case =
    db_case "request: public and unlisted published networks both eligible"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, _project =
          make_project conn ~user:uid ~ext_id:944200006L ~slug:"phrq-modes"
        in
        let* public = insert_community conn "phrq-mode-public" in
        let* unlisted =
          insert_community ~indexable:false ~discoverable:false conn
            "phrq-mode-unlisted"
        in
        let* created_public =
          create_ok "public network" conn ~user:uid ~slug:"phrq-modes"
            ~community:public (phr_fresh_pending ())
        in
        let* ((_, rc_pub), _), _ =
          relation_row conn (Rq.relation_id created_public)
        in
        Alcotest.(check int) "public request targets public" public rc_pub;
        let* () =
          mark "free slot" conn q_mark_rejected
            (Rq.relation_id created_public)
        in
        let* created_unlisted =
          create_ok "unlisted network" conn ~user:uid ~slug:"phrq-modes"
            ~community:unlisted (phr_fresh_pending ())
        in
        let* ((_, rc), _), _ =
          relation_row conn (Rq.relation_id created_unlisted)
        in
        Alcotest.(check int) "unlisted request targets unlisted" unlisted rc;
        Lwt.return_unit)

  (* === existing active relation === *)

  let active_relation_case =
    db_case "request: any active home blocks a new request" (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200007L ~slug:"phrq-active"
        in
        let* c1 = insert_community conn "phrq-active-one" in
        let* c2 = insert_community conn "phrq-active-two" in
        let* created =
          create_ok "first request" conn ~user:uid ~slug:"phrq-active"
            ~community:c1 (phr_fresh_pending ())
        in
        let expect label community =
          create_expect label Rq.Active_home_exists conn ~user:uid
            ~slug:"phrq-active" ~community (phr_fresh_pending ())
        in
        (* Pending blocks, same target or another. *)
        let* () = expect "pending blocks same target" c1 in
        let* () = expect "pending blocks different target" c2 in
        let* n = count_for_project conn project in
        Alcotest.(check int) "still exactly one row" 1 n;
        (* Accepted blocks identically. *)
        let* () =
          mark "accept home" conn q_mark_accepted (Rq.relation_id created)
        in
        let* () = expect "accepted blocks same target" c1 in
        let* () = expect "accepted blocks different target" c2 in
        let* n = count_for_project conn project in
        Alcotest.(check int) "no second row" 1 n;
        Lwt.return_unit)

  (* === historical relations === *)

  let historical_case =
    db_case "request: rejected and removed history never blocks" (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200008L ~slug:"phrq-hist"
        in
        let* c1 = insert_community conn "phrq-hist-one" in
        let* c2 = insert_community conn "phrq-hist-two" in
        let* first =
          create_ok "first request" conn ~user:uid ~slug:"phrq-hist"
            ~community:c1 (phr_fresh_pending ())
        in
        let* () =
          mark "reject first" conn q_mark_rejected (Rq.relation_id first)
        in
        let* rejected_sig =
          find conn "rejected sig" q_relation_sig (Rq.relation_id first)
        in
        (* Rejected history: a fresh request succeeds. *)
        let* second =
          create_ok "after rejection" conn ~user:uid ~slug:"phrq-hist"
            ~community:c2 (phr_fresh_pending ())
        in
        let* () =
          mark "accept second" conn q_mark_accepted (Rq.relation_id second)
        in
        let* () =
          mark "remove second" conn q_mark_removed (Rq.relation_id second)
        in
        let* removed_sig =
          find conn "removed sig" q_relation_sig (Rq.relation_id second)
        in
        (* Removed history: a fresh request succeeds too. *)
        let* third =
          create_ok "after removal" conn ~user:uid ~slug:"phrq-hist"
            ~community:c1 (phr_fresh_pending ())
        in
        let* rejected_after =
          find conn "rejected sig after" q_relation_sig
            (Rq.relation_id first)
        in
        let* removed_after =
          find conn "removed sig after" q_relation_sig
            (Rq.relation_id second)
        in
        Alcotest.(check string) "rejected history unchanged" rejected_sig
          rejected_after;
        Alcotest.(check string) "removed history unchanged" removed_sig
          removed_after;
        let* total = count_for_project conn project in
        Alcotest.(check int) "full history retained" 3 total;
        let* active =
          find conn "active count" q_count_active_for_project project
        in
        Alcotest.(check int) "one active relation" 1 active;
        let* ((_, rc), (_, status)), _ =
          relation_row conn (Rq.relation_id third)
        in
        Alcotest.(check int) "fresh request target" c1 rc;
        Alcotest.(check string) "fresh request pending" "pending" status;
        Lwt.return_unit)

  (* === concurrency === *)

  let same_project_same_target_race_case =
    db_case "request: concurrent identical requests leave one pending row"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200009L ~slug:"phrq-race"
        in
        let* community = insert_community conn "phrq-race-home" in
        Pod_store.with_second_connection (fun conn2 ->
            let* results =
              Lwt.both
                (create conn ~user:uid ~slug:"phrq-race" ~community
                   (phr_fresh_pending ()))
                (create conn2 ~user:uid ~slug:"phrq-race" ~community
                   (phr_fresh_pending ()))
            in
            let _ =
              ok_and_error "identical race" Rq.Active_home_exists results
            in
            let* total = count_for_project conn project in
            Alcotest.(check int) "exactly one row" 1 total;
            let* active =
              find conn "active count" q_count_active_for_project project
            in
            Alcotest.(check int) "exactly one active row" 1 active;
            Lwt.return_unit))

  let same_project_different_targets_race_case =
    db_case "request: concurrent different-target requests leave one winner"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200010L ~slug:"phrq-race2"
        in
        let* c1 = insert_community conn "phrq-race2-one" in
        let* c2 = insert_community conn "phrq-race2-two" in
        Pod_store.with_second_connection (fun conn2 ->
            let* results =
              Lwt.both
                (create conn ~user:uid ~slug:"phrq-race2" ~community:c1
                   (phr_fresh_pending ()))
                (create conn2 ~user:uid ~slug:"phrq-race2" ~community:c2
                   (phr_fresh_pending ()))
            in
            let _ =
              ok_and_error "different-target race" Rq.Active_home_exists
                results
            in
            let* total = count_for_project conn project in
            Alcotest.(check int) "no partial second row" 1 total;
            (* Which target won is deliberately unasserted. *)
            let* winner =
              find conn "winning target" q_active_community_for_project
                project
            in
            Alcotest.(check bool) "winner is one of the two targets" true
              (winner = c1 || winner = c2);
            Lwt.return_unit))

  let different_projects_race_case =
    db_case "request: one community accepts concurrent distinct projects"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, p1 =
          make_project conn ~user:uid ~ext_id:944200011L ~slug:"phrq-multi-a"
        in
        let* _, p2 =
          make_project conn ~user:uid ~ext_id:944200012L ~slug:"phrq-multi-b"
        in
        let* community = insert_community conn "phrq-multi-home" in
        Pod_store.with_second_connection (fun conn2 ->
            let* r1, r2 =
              Lwt.both
                (create conn ~user:uid ~slug:"phrq-multi-a" ~community
                   (phr_fresh_pending ()))
                (create conn2 ~user:uid ~slug:"phrq-multi-b" ~community
                   (phr_fresh_pending ()))
            in
            let check_ok label = function
              | Ok _ -> ()
              | Error e -> Alcotest.failf "%s: %s" label (error_str e)
            in
            check_ok "first project" r1;
            check_ok "second project" r2;
            let* n1 =
              find conn "p1 active" q_count_active_for_project p1
            in
            let* n2 =
              find conn "p2 active" q_count_active_for_project p2
            in
            Alcotest.(check int) "one active relation each (a)" 1 n1;
            Alcotest.(check int) "one active relation each (b)" 1 n2;
            let* pending =
              find conn "community pending" q_count_pending_for_community
                community
            in
            Alcotest.(check int) "community hosts both requests" 2 pending;
            Lwt.return_unit))

  (* === failure rollback === *)

  let rollback_case =
    db_case "request: injected insert failure leaves no trace" (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200013L ~slug:"phrq-fail"
        in
        let* community = insert_community conn "phrq-fail-home" in
        let* project_before = find conn "project sig" q_project_sig project in
        let* community_before =
          find conn "community sig" q_community_sig community
        in
        let exec_ddl label q =
          let* r = C.exec q () in
          let* () = or_fail label r in
          Lwt.return_unit
        in
        let* () = exec_ddl "pre-drop trigger" q_drop_fail_trigger in
        let* () = exec_ddl "pre-drop function" q_drop_fail_fn in
        let* () = exec_ddl "create function" q_create_fail_fn in
        let* () = exec_ddl "create trigger" q_create_fail_trigger in
        Lwt.finalize
          (fun () ->
            let relation =
              phr_expect_ok
                (Phr.create_pending ~request_note:(Some phrq_poison_note))
            in
            let* () =
              create_expect "poisoned request" Rq.Storage_error conn
                ~user:uid ~slug:"phrq-fail" ~community relation
            in
            let* () =
              check_no_relations "no relation persists" conn project
            in
            let* project_after =
              find conn "project sig after" q_project_sig project
            in
            let* community_after =
              find conn "community sig after" q_community_sig community
            in
            Alcotest.(check string) "project unchanged" project_before
              project_after;
            Alcotest.(check string) "community unchanged" community_before
              community_after;
            let* members = find conn "members" q_count_members community in
            Alcotest.(check int) "no membership side effect" 0 members;
            let* mods =
              find conn "moderators" q_count_moderators community
            in
            Alcotest.(check int) "no moderator side effect" 0 mods;
            let* stewards =
              find conn "stewards" q_count_stewards_for_project project
            in
            Alcotest.(check int) "stewardship untouched" 1 stewards;
            Lwt.return_unit)
          (fun () ->
            let* () = exec_ddl "drop trigger" q_drop_fail_trigger in
            exec_ddl "drop function" q_drop_fail_fn))

  (* === durable inconsistency === *)

  let inconsistent_case =
    db_case_lifecycle_relaxed "request: malformed durable community data is corruption"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, project =
          make_project conn ~user:uid ~ext_id:944200014L ~slug:"phrq-corrupt"
        in
        (* A non-addressable stored slug. The scoped identity constraints
           (migration 20260726120000) now bar this corruption at the
           database boundary, so they are dropped for this probe alone and
           restored under Lwt.finalize once the corrupt row is deleted —
           the store-level defense itself must stay observable. *)
        let* bad_slug = insert_community conn "phrq-bad-slug" in
        let* () = Ncid_relax.drop conn in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () =
                exec conn "corrupt slug" q_corrupt_community_slug
                  (bad_slug, "phrq-bad slug")
              in
              create_expect "corrupted slug" Rq.Inconsistent_data conn
                ~user:uid ~slug:"phrq-corrupt" ~community:bad_slug
                (phr_fresh_pending ()))
            (fun () ->
              let* () =
                exec conn "purge corrupt row" q_delete_community bad_slug
              in
              Ncid_relax.restore conn)
        in
        (* The mixed published flag shape — neither fully listed nor
           fully unlisted — is invalid per the shared lifecycle rule. *)
        let* mixed = insert_community conn "phrq-mixed" in
        let* () = exec conn "mix flags" q_mix_community_flags mixed in
        let* () =
          create_expect "mixed lifecycle flags" Rq.Inconsistent_data conn
            ~user:uid ~slug:"phrq-corrupt" ~community:mixed
            (phr_fresh_pending ())
        in
        (* visibility/onboarding off-enum corruption is blocked by their
           DB CHECKs and a non-positive relation id by BIGSERIAL: those
           store branches stay defensive and untestable without dropping
           production constraints. *)
        check_no_relations "no insert from corruption" conn project)

  (* === credential and privacy sweep === *)

  let credential_case =
    db_case "request: no credential fixture reaches the relation row"
      (fun conn ->
        let* uid = insert_user conn "phrq_a" in
        let* _, _project =
          make_project conn ~user:uid ~ext_id:944200015L ~slug:"phrq-creds"
        in
        let* community = insert_community conn "phrq-creds-home" in
        let credentials =
          [ "phrq-access-token-A1x"
          ; "phrq-refresh-token-B2x"
          ; "phrq-authorization-code-C3x"
          ; "phrq-pkce-verifier-D4x"
          ; "phrq-client-secret-E5x"
          ; "phrq-oauth-state-F6x"
          ; "phrq-session-binding-G7x"
          ; "944200999" (* installation id fixture *)
          ; "944300999" (* account id fixture *)
          ; "944699999" (* repository id fixture *)
          ; "phrq-private-repo-name-H8x"
          ; "phrq-private-repo-desc-I9x"
          ]
        in
        let* created =
          create_ok "ordinary request" conn ~user:uid ~slug:"phrq-creds"
            ~community
            (phr_expect_ok
               (Phr.create_pending
                  ~request_note:(Some "Ordinary private note.")))
        in
        let* blob =
          find conn "row blob" q_relation_text_blob (Rq.relation_id created)
        in
        List.iter
          (fun credential ->
            Alcotest.(check bool) "credential absent from relation row"
              false
              (contains ~needle:credential blob))
          credentials;
        let* () =
          mark "free slot" conn q_mark_rejected (Rq.relation_id created)
        in
        (* A credential-shaped value deliberately supplied as the note is
           legitimate there — and only there. *)
        let deliberate = List.hd credentials in
        let* second =
          create_ok "deliberate note" conn ~user:uid ~slug:"phrq-creds"
            ~community
            (phr_expect_ok
               (Phr.create_pending ~request_note:(Some deliberate)))
        in
        let* _, (_, (stored_note, _)) =
          relation_row conn (Rq.relation_id second)
        in
        Alcotest.(check bool) "deliberate note stored verbatim" true
          (stored_note = Some deliberate);
        let* nonnote =
          find conn "non-note blob" q_relation_nonnote_blob
            (Rq.relation_id second)
        in
        Alcotest.(check bool) "note value nowhere else in the row" false
          (contains ~needle:deliberate nonnote);
        Lwt.return_unit)

  let suite =
    [ pure_inputs_case; success_case; note_variants_case;
      project_unavailable_case; project_authorization_case;
      community_unavailable_case; eligible_modes_case;
      active_relation_case; historical_case;
      same_project_same_target_race_case;
      same_project_different_targets_race_case;
      different_projects_race_case; rollback_case; inconsistent_case;
      credential_case ]
end

(* ===== Existing-community home request form (Project_home_request_form) =====
   Pure strict parser: exact two-field grammar, strict positive OCaml-int
   community id, byte-exact note passthrough, and delegation to the real
   relation domain. DB-free. Rejection labels name only the malformed
   category, and every rejection is asserted against the nullary
   constructor, so no fixture value reaches test output. *)

module Phrf = Earde.Project_home_request_form

let phrf_case name f = Alcotest.test_case name `Quick f

let phrf_fields ?(target = "42") ?(note = "Please make this our home") () =
  [ ("target_community_id", target); ("request_note", note) ]

let phrf_expect_ok fields =
  match Phrf.of_fields fields with
  | Ok t -> t
  | Error Phrf.Invalid_form -> Alcotest.fail "expected a valid form"

let phrf_ok ?target ?note () = phrf_expect_ok (phrf_fields ?target ?note ())

let phrf_reject name fields =
  phrf_case name (fun () ->
      Alcotest.(check bool) "rejected" true
        (match Phrf.of_fields fields with
        | Error Phrf.Invalid_form -> true
        | Ok _ -> false))

let phrf_rename field replacement =
  List.map
    (fun (k, v) -> if k = field then (replacement, v) else (k, v))
    (phrf_fields ())

let phrf_valid_cases =
  [ phrf_case "ordinary submission parses exactly" (fun () ->
        let t = phrf_ok () in
        Alcotest.(check int) "target id" 42 (Phrf.target_community_id t);
        Alcotest.(check string) "note" "Please make this our home"
          (Phrf.request_note t))
  ; phrf_case "field order does not matter" (fun () ->
        let t = phrf_expect_ok (List.rev (phrf_fields ())) in
        Alcotest.(check int) "target id" 42 (Phrf.target_community_id t))
  ; phrf_case "empty note is preserved as the empty string" (fun () ->
        Alcotest.(check string) "empty note" ""
          (Phrf.request_note (phrf_ok ~note:"" ())))
  ; phrf_case "blank note is preserved verbatim before domain creation"
      (fun () ->
        Alcotest.(check string) "blank note" " \t\r\n "
          (Phrf.request_note (phrf_ok ~note:" \t\r\n " ())))
  ; phrf_case "note preserved byte-exactly, never canonicalized" (fun () ->
        let raw = "  Prima riga \xc3\xa8\r\nseconda\ttab \xe2\x98\x95  " in
        Alcotest.(check string) "note untouched" raw
          (Phrf.request_note (phrf_ok ~note:raw ())))
  ; phrf_case "leading zeroes accepted for the community id" (fun () ->
        Alcotest.(check int) "target id" 7
          (Phrf.target_community_id (phrf_ok ~target:"007" ())))
  ; phrf_case "largest representable int accepted" (fun () ->
        Alcotest.(check int) "target id" max_int
          (Phrf.target_community_id
             (phrf_ok ~target:(string_of_int max_int) ())))
  ]

let phrf_grammar_cases =
  [ phrf_reject "empty field set" []
  ; phrf_reject "missing target_community_id"
      [ ("request_note", "only a note") ]
  ; phrf_reject "missing request_note" [ ("target_community_id", "42") ]
  ; phrf_reject "duplicate target_community_id"
      (("target_community_id", "42") :: phrf_fields ())
  ; phrf_reject "duplicate request_note"
      (("request_note", "again") :: phrf_fields ())
  ; phrf_reject "unknown extra field"
      (phrf_fields () @ [ ("community_slug", "alpine") ])
  ; phrf_reject "unknown submit-style field"
      (phrf_fields () @ [ ("submit", "send") ])
  ; phrf_reject "project slug is never a form field"
      (phrf_fields () @ [ ("project_slug", "widget-kit") ])
  ; phrf_reject "dream.csrf is not recognized by the pure parser"
      (phrf_fields () @ [ ("dream.csrf", "token") ])
  ; phrf_reject "capitalized target name"
      (phrf_rename "target_community_id" "Target_community_id")
  ; phrf_reject "uppercase note name"
      (phrf_rename "request_note" "REQUEST_NOTE")
  ; phrf_reject "target name with leading space"
      (phrf_rename "target_community_id" " target_community_id")
  ; phrf_reject "note name with trailing space"
      (phrf_rename "request_note" "request_note ")
  ]

let phrf_id_cases =
  List.map
    (fun (label, raw) ->
      phrf_reject ("community id: " ^ label) (phrf_fields ~target:raw ()))
    [ ("blank", "")
    ; ("zero", "0")
    ; ("all zeroes", "000")
    ; ("negative", "-5")
    ; ("plus-signed", "+5")
    ; ("leading whitespace", " 5")
    ; ("trailing whitespace", "5 ")
    ; ("newline-suffixed", "5\n")
    ; ("decimal point", "5.0")
    ; ("hexadecimal", "0x10")
    ; ("underscore separator", "1_000")
    ; ("int64 overflow", "9223372036854775808")
    ; ("ocaml int overflow", string_of_int max_int ^ "0")
    ]

let phrf_delegation_cases =
  [ phrf_case "create_relation canonicalizes through the real domain"
      (fun () ->
        match
          Phrf.create_relation (phrf_ok ~note:"  ciao\r\nmondo\t \r\n" ())
        with
        | Ok relation ->
            Alcotest.(check bool) "pending" true
              (Phr.status relation = Phr.Pending);
            Alcotest.(check (option string)) "canonical note"
              (Some "ciao\nmondo")
              (Phr.request_note relation)
        | Error _ -> Alcotest.fail "expected a valid relation")
  ; phrf_case "blank note collapses to None only in the domain" (fun () ->
        let t = phrf_ok ~note:" \t\r\n " () in
        Alcotest.(check string) "parser preserves" " \t\r\n "
          (Phrf.request_note t);
        match Phrf.create_relation t with
        | Ok relation ->
            Alcotest.(check (option string)) "domain collapses" None
              (Phr.request_note relation)
        | Error _ -> Alcotest.fail "expected a valid relation")
  ; phrf_case "invalid notes propagate the exact domain error" (fun () ->
        List.iter
          (fun raw ->
            Alcotest.(check bool) "Invalid_request_note" true
              (match Phrf.create_relation (phrf_ok ~note:raw ()) with
              | Error Phr.Invalid_request_note -> true
              | Ok _ | Error _ -> false))
          [ "nul\x00byte"; "esc\x1bcontrol"; "\xff\xfe not utf-8";
            String.make 2001 'a' ])
  ]

let phrf_privacy_cases =
  [ phrf_case "every rejection is the same payload-free error" (fun () ->
        (* Distinctive fixture markers: were Invalid_form to carry any
           payload, these equalities could not all hold. *)
        let rejections =
          [ Phrf.of_fields []
          ; Phrf.of_fields (phrf_fields ~target:"phrf-fixture-zz1" ())
          ; Phrf.of_fields (phrf_fields () @ [ ("phrf-fixture-zz2", "z") ])
          ; Phrf.of_fields [ ("request_note", "phrf-fixture-zz3") ]
          ; Phrf.of_fields (phrf_fields () @ phrf_fields ())
          ]
        in
        List.iter
          (fun r ->
            Alcotest.(check bool) "Invalid_form" true
              (r = Error Phrf.Invalid_form))
          rejections)
  ]

(* ===== Home choice page (Project_home_choice_pages) =====
   Same fragment-scoped technique as the other create-flow page tests:
   assertions pin only what the feature templates introduce inside the
   shared layout. DB-free; no GitHub, installation, repository, or
   credential fixtures exist anywhere in these view models. *)

module Phcp = Earde.Project_home_choice_pages

let phcp_case name f = Alcotest.test_case name `Quick f

let phcp_project ?(name = "Widget Kit") ?(slug = "widget-kit")
    ?(login = "octo-org") () : Phcp.project =
  { Phcp.name; slug; namespace_login = login }

let phcp_community ?(id = 31) ?(name = "Alpine Devs") ?(slug = "alpine")
    ?description ?(visibility = Phcp.Public) () : Phcp.community =
  { Phcp.id; name; slug; description; visibility }

let phcp_c1 =
  phcp_community ~id:31 ~name:"Alpine Devs" ~slug:"alpine"
    ~description:"Shared alpine tooling talk" ()

let phcp_c2 =
  phcp_community ~id:32 ~name:"Beta Builders" ~slug:"beta"
    ~visibility:Phcp.Unlisted ()

let phcp_unavailable =
  phcp_community ~id:33 ~name:"Gamma Sunset" ~slug:"gamma"
    ~visibility:Phcp.Currently_unavailable ()

let phcp_choose ?project ?(communities = [ phcp_c1; phcp_c2 ])
    ?(note = "") () =
  Phcp.Choose_existing
    { project = (match project with Some p -> p | None -> phcp_project ());
      communities; request_note = note }

let phcp_render ?user ?(feedback = None) state =
  Phcp.project_home_choice_page ?user ~state ~feedback ()

let phcp_frag ?user ?feedback state =
  ps_fragment (phcp_render ?user ?feedback state)

let phcp_form_cases =
  [ phcp_case "exact form method, action, and application field set"
      (fun () ->
        let frag = phcp_frag (phcp_choose ()) in
        Alcotest.(check int) "one form" 1 (ps_count frag "<form");
        ps_must frag
          "<form method='POST' action='/projects/widget-kit/request-home' \
           class='create-form phc-request-form'>";
        Alcotest.(check int) "two radios" 2
          (ps_count frag "name='target_community_id'");
        Alcotest.(check int) "one note field" 1
          (ps_count frag "name='request_note'");
        (* Exactly the two application fields: no other name= attribute
           exists in the fragment. *)
        Alcotest.(check int) "exact application field set" 3
          (ps_count frag "name='");
        ps_must frag "<textarea name='request_note' maxlength='2000'";
        (* The one nameless submit control, byte-exact. *)
        ps_must frag
          "<button type='submit' class='create-btn \
           create-btn--block'>Send home request</button>";
        (* No hidden project slug or identifiers of any kind. *)
        ps_must_not frag "type='hidden'";
        ps_must_not frag "name='project_slug'";
        ps_must_not frag "name='slug'";
        ps_must_not frag "name='user_id'";
        ps_must_not frag "name='relation_id'";
        ps_must_not frag "installation";
        ps_must_not frag "return_url")
  ; phcp_case "radio options in supplied order, never preselected"
      (fun () ->
        let frag = phcp_frag (phcp_choose ()) in
        ps_order frag "Alpine Devs" "Beta Builders";
        ps_order frag "value='31'" "value='32'";
        ps_must_not frag "checked")
  ; phcp_case "request note is escaped, never rendered as markup" (fun () ->
        let frag =
          phcp_frag
            (phcp_choose ~note:"<script>alert('x')</script> & <b>bold</b>" ())
        in
        ps_must frag
          "&lt;script&gt;alert(&#39;x&#39;)&lt;/script&gt; &amp; \
           &lt;b&gt;bold&lt;/b&gt;";
        ps_must_not frag "<script>alert";
        ps_must_not frag "<b>bold</b>")
  ; phcp_case "community identity, visibility labels, no invented metrics"
      (fun () ->
        let frag = phcp_frag (phcp_choose ()) in
        ps_must frag "href='/c/alpine'";
        ps_must frag "href='/c/beta'";
        ps_must frag "phc-community-visibility'>Public<";
        ps_must frag "phc-community-visibility'>Unlisted<";
        ps_must frag "Shared alpine tooling talk";
        ps_must_not frag "member";
        ps_must_not frag "activity";
        ps_must_not frag "karma";
        ps_must_not frag "verified badge")
  ; phcp_case "copy: factual verification, moderator review, no officiality"
      (fun () ->
        let frag = phcp_frag (phcp_choose ()) in
        ps_must frag "Connect to an existing community";
        ps_must frag "Request an eligible Earde community";
        ps_must frag "Project connected through GitHub";
        ps_must frag "moderators must review";
        ps_must frag "grants no community moderation rights";
        ps_must frag "visible only to";
        ps_must_not frag "Official";
        ps_must_not frag "GitHub-approved";
        ps_must_not frag "GitHub-endorsed")
  ; phcp_case "no GitHub, installation, repository, or credential material"
      (fun () ->
        let frag = phcp_frag (phcp_choose ()) in
        ps_must_not frag "github.com";
        ps_must_not frag "repository";
        ps_must_not frag "installation";
        ps_must_not frag "token";
        ps_must_not frag "octo-org")
  ; phcp_case "no inline styles, scripts, or handlers in the fragment"
      (fun () ->
        List.iter
          (fun state ->
            let frag = phcp_frag state in
            ps_must_not frag "<script";
            ps_must_not frag "style='";
            ps_must_not frag "onclick";
            ps_must_not frag "javascript:";
            ps_must_not frag "http-equiv")
          [ phcp_choose ()
          ; Phcp.No_eligible_communities (phcp_project ())
          ; Phcp.Active_relation
              { project = phcp_project ();
                relation = Phcp.Pending_request phcp_c1 }
          ; Phcp.Active_relation
              { project = phcp_project ();
                relation =
                  Phcp.Accepted_home
                    { community = phcp_c1; removal_allowed = true } }
          ; Phcp.Active_relation
              { project = phcp_project ();
                relation =
                  Phcp.Accepted_home
                    { community = phcp_c1; removal_allowed = false } }
          ])
  ]

let phcp_state_cases =
  [ phcp_case "no eligible communities: explanation and setup link, no form"
      (fun () ->
        let frag =
          phcp_frag (Phcp.No_eligible_communities (phcp_project ()))
        in
        ps_must frag "No eligible published network community";
        ps_must frag "href='/projects/widget-kit/setup'";
        ps_must frag "Back to project setup";
        ps_must_not frag "<form";
        ps_must_not frag "target_community_id";
        ps_must_not frag "Send home request")
  ; phcp_case "pending relation: status copy and target, no request controls"
      (fun () ->
        let frag =
          phcp_frag
            (Phcp.Active_relation
               { project = phcp_project ();
                 relation = Phcp.Pending_request phcp_c1 })
        in
        ps_must frag "Home request pending";
        ps_must frag "Alpine Devs";
        ps_must frag "href='/c/alpine'";
        ps_must frag "accept or reject";
        ps_must_not frag "<form";
        ps_must_not frag "<textarea";
        ps_must_not frag "target_community_id";
        ps_must_not frag "Send home request";
        ps_must_not frag "phc-note")
  ; phcp_case "accepted relation: connected copy, no moderation implication"
      (fun () ->
        let frag =
          phcp_frag
            (Phcp.Active_relation
               { project = phcp_project ();
                 relation =
                   Phcp.Accepted_home
                     { community = phcp_c1; removal_allowed = true } })
        in
        ps_must frag "Community home connected";
        ps_must frag "href='/c/alpine'";
        ps_must frag "moderation stays with its moderators";
        ps_must_not frag "<form";
        ps_must_not frag "target_community_id";
        ps_must_not frag "Send home request";
        ps_must_not frag "Official")
  ; phcp_case
      "unavailable active target: generic label only, relation still shown"
      (fun () ->
        List.iter
          (fun (relation, status_copy) ->
            let frag =
              phcp_frag
                (Phcp.Active_relation
                   { project = phcp_project (); relation })
            in
            ps_must frag status_copy;
            ps_must frag "Gamma Sunset";
            ps_must frag "href='/c/gamma'";
            ps_must frag "Currently unavailable";
            (* The generic label never becomes a reason or a false
               publication state. *)
            ps_must_not frag "Unlisted";
            ps_must_not frag "Private";
            ps_must_not frag "Draft";
            ps_must_not frag "Legacy";
            ps_must_not frag "indexable";
            ps_must_not frag "discoverable";
            ps_must_not frag "onboarding";
            ps_must_not frag "network community";
            (* Still no request controls and no target id. *)
            ps_must_not frag "<form";
            ps_must_not frag "target_community_id";
            ps_must_not frag "Send home request";
            ps_must_not frag "value='33'";
            ps_must_not frag "'33'")
          [ (Phcp.Pending_request phcp_unavailable, "Home request pending")
          ; ( Phcp.Accepted_home
                { community = phcp_unavailable; removal_allowed = true },
              "Community home connected" )
          ])
  ]

let phcp_defensive_cases =
  [ phcp_case "invalid project slug: no form, no project-derived links"
      (fun () ->
        List.iter
          (fun slug ->
            let frag =
              phcp_frag
                (phcp_choose ~project:(phcp_project ~slug ()) ())
            in
            ps_must frag "Connect to an existing community";
            ps_must_not frag "<form";
            ps_must_not frag "request-home";
            ps_must_not frag "/projects/")
          [ ""; "Widget Kit"; "-widget"; "widget-"; "wid--get";
            String.make 81 'a' ])
  ; phcp_case "invalid project slug: no setup link either" (fun () ->
        let frag =
          phcp_frag
            (Phcp.No_eligible_communities (phcp_project ~slug:"Bad Slug" ()))
        in
        ps_must frag "No eligible published network community";
        ps_must_not frag "href='/projects";
        ps_must_not frag "Bad Slug")
  ; phcp_case "non-positive community ids never become radio inputs"
      (fun () ->
        let corrupt_zero = phcp_community ~id:0 ~name:"Zero Corrupt" () in
        let corrupt_neg = phcp_community ~id:(-3) ~name:"Neg Corrupt" () in
        let frag =
          phcp_frag
            (phcp_choose ~communities:[ corrupt_zero; corrupt_neg ] ())
        in
        (* With no valid option left there is no request form at all, so
           nothing renders that could carry a corrupt id. *)
        ps_must frag "Connect to an existing community";
        ps_must_not frag "type='radio'";
        ps_must_not frag "value='0'";
        ps_must_not frag "value='-3'";
        ps_must_not frag "<form")
  ; phcp_case "a valid option keeps the form; corrupt rows stay inert"
      (fun () ->
        let corrupt = phcp_community ~id:0 ~name:"Zero Corrupt" () in
        let frag =
          phcp_frag (phcp_choose ~communities:[ phcp_c1; corrupt ] ())
        in
        Alcotest.(check int) "one form" 1 (ps_count frag "<form");
        Alcotest.(check int) "one radio" 1 (ps_count frag "type='radio'");
        ps_must frag "Zero Corrupt")
  ; phcp_case "currently-unavailable community is never selectable"
      (fun () ->
        (* Alone: nothing actionable remains, so no form at all. *)
        let alone =
          phcp_frag (phcp_choose ~communities:[ phcp_unavailable ] ())
        in
        ps_must_not alone "<form";
        ps_must_not alone "type='radio'";
        ps_must_not alone "value='33'";
        (* Beside a valid option: the form renders with exactly one radio,
           and the unavailable row stays inert with the generic label. *)
        let mixed =
          phcp_frag
            (phcp_choose ~communities:[ phcp_c1; phcp_unavailable ] ())
        in
        Alcotest.(check int) "one radio" 1 (ps_count mixed "type='radio'");
        ps_must mixed "Gamma Sunset";
        ps_must mixed "Currently unavailable";
        ps_must_not mixed "value='33'")
  ; phcp_case "invalid community slug renders no actionable link" (fun () ->
        let broken =
          phcp_community ~id:41 ~name:"Broken Slug" ~slug:"has space" ()
        in
        let frag = phcp_frag (phcp_choose ~communities:[ broken ] ()) in
        ps_must frag "Broken Slug";
        ps_must_not frag "<a href='/c/";
        (* The identity still renders as inert text. *)
        ps_must frag "/c/has space")
  ; phcp_case "duplicate community ids render one actionable option"
      (fun () ->
        let duplicate = { phcp_c1 with Phcp.name = "Alpine Mirror" } in
        let frag =
          phcp_frag (phcp_choose ~communities:[ phcp_c1; duplicate ] ())
        in
        Alcotest.(check int) "one radio" 1 (ps_count frag "type='radio'");
        Alcotest.(check int) "one value" 1 (ps_count frag "value='31'"))
  ; phcp_case "empty community list renders no form" (fun () ->
        let frag = phcp_frag (phcp_choose ~communities:[] ()) in
        ps_must frag "Connect to an existing community";
        ps_must_not frag "<form")
  ]

let phcp_feedback_cases =
  [ phcp_case "each feedback variant renders its generic copy" (fun () ->
        List.iter
          (fun (feedback, marker) ->
            let frag = phcp_frag ~feedback:(Some feedback) (phcp_choose ()) in
            ps_must frag "phc-alert";
            ps_must frag marker)
          [ (Phcp.Stale_form, "This page had been open too long")
          ; (Phcp.Request_form_invalid, "Review the form and try again")
          ; (Phcp.Community_unavailable,
             "no longer available for project requests")
          ; (Phcp.Active_home_exists,
             "already has a pending request or community home")
          ; (Phcp.Request_failed, "Try again.")
          ])
  ; phcp_case "no feedback renders no alert container" (fun () ->
        ps_must_not (phcp_frag (phcp_choose ())) "phc-alert")
  ; phcp_case "feedback is cosmetic: an active relation still shows no form"
      (fun () ->
        let frag =
          phcp_frag ~feedback:(Some Phcp.Active_home_exists)
            (Phcp.Active_relation
               { project = phcp_project ();
                 relation = Phcp.Pending_request phcp_c1 })
        in
        ps_must frag "phc-alert";
        ps_must_not frag "<form")
  ]

(* --- Page rendering with a live request: the framework CSRF field. --- *)

let phcp_csrf_render state =
  let captured = ref None in
  let pipeline =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    captured :=
      Some
        (Phcp.project_home_choice_page ~request:req ~state ~feedback:None ());
    Dream.html ""
  in
  ignore
    (Lwt_main.run
       (pipeline
          (Dream.request ~method_:`GET ~target:"/projects/widget-kit/home"
             "")));
  match !captured with
  | Some html -> html
  | None -> Alcotest.fail "renderer did not run"

let phcp_csrf_cases =
  [ phcp_case "choose with request: one framework field inside the form"
      (fun () ->
        let frag = ps_fragment (phcp_csrf_render (phcp_choose ())) in
        Alcotest.(check int) "one framework field" 1
          (ps_count frag "name=\"dream.csrf\"");
        Alcotest.(check int) "framework field is hidden" 1
          (ps_count frag "type=\"hidden\"");
        (* Still zero application-owned hidden fields. *)
        Alcotest.(check int) "no application hidden field" 0
          (ps_count frag "type='hidden'");
        match
          ( ps_index_of frag "<form" 0,
            ps_index_of frag "name=\"dream.csrf\"" 0,
            ps_index_of frag "</form>" 0 )
        with
        | Some f, Some c, Some e ->
            Alcotest.(check bool) "CSRF inside the form" true (f < c && c < e)
        | _ -> Alcotest.fail "form or CSRF field missing")
  ; phcp_case "form-free states emit no framework field even with a request"
      (fun () ->
        List.iter
          (fun state ->
            ps_must_not (ps_fragment (phcp_csrf_render state)) "dream.csrf")
          [ Phcp.No_eligible_communities (phcp_project ())
          ; Phcp.Active_relation
              { project = phcp_project ();
                relation = Phcp.Pending_request phcp_c1 }
          ; phcp_choose ~communities:[] ()
          ])
    (* The accepted state is the one active-relation state that is no longer
       form-free: it carries the steward removal control, whose single
       framework field sits inside that one form. It still carries no
       application-owned hidden field. *)
  ; phcp_case "accepted state: one framework field inside the removal form"
      (fun () ->
        let frag =
          ps_fragment
            (phcp_csrf_render
               (Phcp.Active_relation
                  { project = phcp_project ();
                    relation =
                      Phcp.Accepted_home
                        { community = phcp_c1; removal_allowed = true } }))
        in
        Alcotest.(check int) "one form" 1 (ps_count frag "<form");
        Alcotest.(check int) "one framework field" 1
          (ps_count frag "name=\"dream.csrf\"");
        Alcotest.(check int) "no application hidden field" 0
          (ps_count frag "type='hidden'");
        ps_must frag
          "action='/projects/widget-kit/community-home/alpine/remove'";
        match
          ( ps_index_of frag "<form" 0,
            ps_index_of frag "name=\"dream.csrf\"" 0,
            ps_index_of frag "</form>" 0 )
        with
        | Some f, Some c, Some e ->
            Alcotest.(check bool) "CSRF inside the form" true (f < c && c < e)
        | _ -> Alcotest.fail "form or CSRF field missing")
  ; phcp_case "pure rendering without a request stays CSRF-free" (fun () ->
        ps_must_not (phcp_frag (phcp_choose ())) "dream.csrf")
  ]

(* === Project home choice read model (Project_home_choice_read_model) ===
   Owner-authorized view behind the existing-community home choice: the
   active relation or the eligible target list, driven over verified
   permanent projects built through the real draft/selection/finalization
   chain and pending relations written by the real request store.
   Database-gated (EARDE_TEST_DATABASE_URL, same opt-in as Mod_scope) with
   its own reserved external-installation-id range 944400001..944400999
   (hence account ids 944500001..944500999, which also scope the
   permanent-project cleanup), phcv_% usernames, and phcv-% community
   slugs so no suite shares fixtures. The eligible-list predicate is
   global, so exact assertions filter to phcv-% slugs — except under an
   active relation, where the list is exactly empty by contract. *)
module Phcv = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rm = Earde.Project_home_choice_read_model
  module Rq = Earde.Project_home_request_store

  let error_str : Rm.error -> string = function
    | Rm.Invalid_user_id -> "Invalid_user_id"
    | Rm.Invalid_project_slug -> "Invalid_project_slug"
    | Rm.Inconsistent_data -> "Inconsistent_data"
    | Rm.Storage_error -> "Storage_error"

  let vis_str : Rm.visibility -> string = function
    | Rm.Public -> "public"
    | Rm.Unlisted -> "unlisted"
    | Rm.Currently_unavailable -> "currently_unavailable"

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let make_project = Phrq.make_project

  (* Same dependency order as the sibling suites; the LIKE pattern also
     catches deliberately corrupted phcv- slugs. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 944500001 AND 944500999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 944500001 AND 944500999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 944400001 AND 944400999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phcv-%'"
      ; "DELETE FROM users WHERE username LIKE 'phcv_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 944400001 AND 944400999"
      ]

  (* Direct community fixtures with display name and description control:
     lifecycle shapes are written exactly as the durable columns represent
     them today. Defaults are the eligible fully listed published network
     community. *)
  let q_insert_community =
    (Caqti_type.(
       t2
         (t2 (t2 string string) (t2 (option string) string))
         (t2 (t2 bool bool) (t2 string bool)))
     ->! Caqti_type.int)
    "INSERT INTO communities \
       (slug, name, description, visibility, indexable, \
        is_network_community, onboarding_state, discoverable) \
     VALUES ($1, $2, $3, $4, $5, $6, $7, $8) RETURNING id"

  let insert_community ?name ?description ?(visibility = "public")
      ?(indexable = true) ?(network = true) ?(onboarding = "published")
      ?(discoverable = true) conn slug =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let name = match name with Some n -> n | None -> slug in
    let* cid =
      C.find q_insert_community
        ( ((slug, name), (description, visibility)),
          ((indexable, network), (onboarding, discoverable)) )
    in
    or_fail ("community " ^ slug) cid

  (* Community-side lifecycle drift and targeted durable corruption. *)
  let q_make_private =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET visibility = 'private', indexable = FALSE, \
     discoverable = FALSE WHERE id = $1"

  let q_make_unlisted =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET indexable = FALSE, discoverable = FALSE \
     WHERE id = $1"

  let q_make_listed =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET indexable = TRUE, discoverable = TRUE \
     WHERE id = $1"

  let q_make_draft_state =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET onboarding_state = 'draft', \
     visibility = 'private', indexable = FALSE, discoverable = FALSE \
     WHERE id = $1"

  let q_make_legacy =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET is_network_community = FALSE WHERE id = $1"

  let q_set_name =
    (Caqti_type.(t2 int string) ->. Caqti_type.unit)
    "UPDATE communities SET name = $2 WHERE id = $1"

  let q_corrupt_description =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET description = 'phcv' || chr(1) || 'corrupt' \
     WHERE id = $1"

  (* Each case gets a fresh connection and a clean fixture slate; cleanup
     runs again afterwards even when an assertion fails mid-way, and the
     connection is disconnected deterministically. *)
  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f conn))

  (* === call helpers === *)

  let load conn ~user ~slug =
    Rm.load_for_steward conn ~user_id:user ~project_slug:slug

  let load_view label conn ~user ~slug =
    let* r = load conn ~user ~slug in
    match r with
    | Ok (Some view) -> Lwt.return view
    | Ok None -> Alcotest.failf "%s: unexpectedly absent" label
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_none label conn ~user ~slug =
    let* r = load conn ~user ~slug in
    match r with
    | Ok None -> Lwt.return_unit
    | Ok (Some _) -> Alcotest.failf "%s: unexpectedly present" label
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_expect label expected conn ~user ~slug =
    let* r = load conn ~user ~slug in
    match r with
    | Ok None ->
        Alcotest.failf "%s: expected %s, got Ok None" label
          (error_str expected)
    | Ok (Some _) ->
        Alcotest.failf "%s: expected %s, got Ok Some" label
          (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  (* Pending relations come only through the real transactional store. *)
  let request_pending label conn ~user ~slug ~community ?note () =
    let relation = phr_expect_ok (Phr.create_pending ~request_note:note) in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok created -> Lwt.return (Rq.relation_id created)
    | Error _ -> Alcotest.failf "%s: request fixture failed" label

  let phcv_only communities =
    List.filter
      (fun c ->
        let slug = Rm.community_slug c in
        String.length slug >= 5 && String.sub slug 0 5 = "phcv-")
      communities

  let active_of label view =
    match Rm.active_relation view with
    | Some relation -> relation
    | None -> Alcotest.failf "%s: expected an active relation" label

  let check_no_active label view =
    Alcotest.(check bool) label true
      (match Rm.active_relation view with None -> true | Some _ -> false)

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "choice: invalid inputs rejected before any SQL" (fun _conn ->
        (* A deliberately unusable connection: pure validation must return
           without touching it — were any SQL attempted, the driver would
           raise on the finished connection and fail the test. *)
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let expect label e ~user ~slug = load_expect label e dead ~user ~slug in
        let* () = expect "user id 0" Rm.Invalid_user_id ~user:0 ~slug:"phcv-a" in
        let* () =
          expect "negative user id" Rm.Invalid_user_id ~user:(-7)
            ~slug:"phcv-a"
        in
        let* () =
          expect "user checked before slug" Rm.Invalid_user_id ~user:0
            ~slug:"NOT A SLUG"
        in
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              expect "invalid project slug" Rm.Invalid_project_slug ~user:1
                ~slug:bad)
            [ ""
            ; "Phcv-Upper"
            ; "phcv slug"
            ; " phcv-a"
            ; "phcv-a "
            ; "phcv_a"
            ; "phcv/a"
            ; "-phcv"
            ; "phcv-"
            ; "phcv--a"
            ; String.make 81 'a'
            ]
        in
        Lwt.return_unit)

  (* A live connection whose unqualified table names stop resolving: a real
     PostgreSQL request failure, collapsed payload-free. The path is
     restored before the shared cleanup runs on the same connection. *)
  let q_hide_tables =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO phcv_void"

  let q_restore_tables =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO public"

  let storage_case =
    db_case "choice: database failure collapses to the payload-free error"
      (fun conn ->
        let* () = exec conn "hide tables" q_hide_tables () in
        Lwt.finalize
          (fun () ->
            load_expect "storage error" Rm.Storage_error conn ~user:1
              ~slug:"phcv-a")
          (fun () -> exec conn "restore tables" q_restore_tables ()))

  (* === steward authorization === *)

  let steward_view_case =
    db_case "choice: steward load; stewardship alone authorizes" (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* b = insert_user conn "phcv_b" in
        let* inst, project =
          make_project conn ~user:a ~ext_id:944400001L ~slug:"phcv-view"
        in
        let* view = load_view "owner load" conn ~user:a ~slug:"phcv-view" in
        let p = Rm.project view in
        Alcotest.(check string) "project name" "Pfin Fixture Project"
          (Rm.project_name p);
        Alcotest.(check string) "canonical slug" "phcv-view"
          (Rm.project_slug p);
        Alcotest.(check string) "namespace login" "pfin-owner"
          (Rm.project_namespace_login p);
        check_no_active "no active relation" view;
        Alcotest.(check int) "no fixture-eligible targets" 0
          (List.length (phcv_only (Rm.eligible_communities view)));
        (* A second steward is equally authorized — membership or
           moderation in any community is never consulted. *)
        let* () =
          exec conn "add steward" Phrq.q_insert_steward (project, b, inst)
        in
        let* view_b =
          load_view "second steward" conn ~user:b ~slug:"phcv-view"
        in
        Alcotest.(check string) "same project" "phcv-view"
          (Rm.project_slug (Rm.project view_b));
        Lwt.return_unit)

  let collapse_case =
    db_case "choice: every unavailable-project cause collapses to absence"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* b = insert_user conn "phcv_b" in
        let* _, project =
          make_project conn ~user:a ~ext_id:944400002L ~slug:"phcv-auth"
        in
        let* () = load_none "missing project" conn ~user:a ~slug:"phcv-absent" in
        let* () = load_none "foreign project" conn ~user:b ~slug:"phcv-auth" in
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* () = load_none "stale project" conn ~user:a ~slug:"phcv-auth" in
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification (project, "revoked")
        in
        let* () = load_none "revoked project" conn ~user:a ~slug:"phcv-auth" in
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        let* () = exec conn "drop steward" Phrq.q_delete_steward (project, a) in
        load_none "creator without stewardship" conn ~user:a ~slug:"phcv-auth")

  (* === eligible list === *)

  let eligible_case =
    db_case_lifecycle_relaxed "choice: eligible predicate, mapping, and deterministic order"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* _, _project =
          make_project conn ~user:a ~ext_id:944400003L ~slug:"phcv-elig"
        in
        let* unl =
          insert_community conn "phcv-elig-unl" ~name:"phcv apple"
            ~indexable:false ~discoverable:false
        in
        let* same_a =
          insert_community conn "phcv-elig-same-a" ~name:"Phcv Same"
        in
        let* same_b =
          insert_community conn "phcv-elig-same-b" ~name:"Phcv Same"
        in
        let* pub =
          insert_community conn "phcv-elig-pub" ~name:"Phcv Zebra"
            ~description:"Multi\nline\twith \xe2\x98\x95"
        in
        let* _legacy =
          insert_community conn "phcv-elig-legacy" ~network:false
        in
        let* _draft =
          insert_community conn "phcv-elig-draft" ~onboarding:"draft"
            ~visibility:"private" ~indexable:false ~discoverable:false
        in
        let* _priv =
          insert_community conn "phcv-elig-priv" ~visibility:"private"
            ~indexable:false ~discoverable:false
        in
        let* view = load_view "eligible load" conn ~user:a ~slug:"phcv-elig" in
        check_no_active "no active relation" view;
        let eligible = phcv_only (Rm.eligible_communities view) in
        (* lower(name) ASC, then slug ASC for the tied pair; the excluded
           legacy, draft, and private slugs prove the predicate. *)
        Alcotest.(check (list string)) "deterministic order"
          [ "phcv-elig-unl"; "phcv-elig-same-a"; "phcv-elig-same-b";
            "phcv-elig-pub" ]
          (List.map Rm.community_slug eligible);
        Alcotest.(check (list int)) "exact local ids"
          [ unl; same_a; same_b; pub ]
          (List.map Rm.community_id eligible);
        let by_slug slug =
          List.find (fun c -> Rm.community_slug c = slug) eligible
        in
        let pub_c = by_slug "phcv-elig-pub" in
        Alcotest.(check string) "public name" "Phcv Zebra"
          (Rm.community_name pub_c);
        Alcotest.(check string) "fully listed maps to Public" "public"
          (vis_str (Rm.community_visibility pub_c));
        Alcotest.(check (option string)) "description byte-exact"
          (Some "Multi\nline\twith \xe2\x98\x95")
          (Rm.community_description pub_c);
        let unl_c = by_slug "phcv-elig-unl" in
        Alcotest.(check string) "fully unlisted maps to Unlisted" "unlisted"
          (vis_str (Rm.community_visibility unl_c));
        Alcotest.(check (option string)) "absent description stays None" None
          (Rm.community_description unl_c);
        Lwt.return_unit)

  let mixed_flags_case =
    db_case_lifecycle_relaxed "choice: mixed publication flags on an eligible row are corrupt"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* _, _project =
          make_project conn ~user:a ~ext_id:944400004L ~slug:"phcv-mix"
        in
        let* home = insert_community conn "phcv-mix-home" in
        let* () = exec conn "mix flags" Phrq.q_mix_community_flags home in
        let* () =
          load_expect "mixed flags" Rm.Inconsistent_data conn ~user:a
            ~slug:"phcv-mix"
        in
        (* The same durable rules bind an eligible row's identity. The
           scoped identity constraints are dropped for this probe alone
           and restored under Lwt.finalize once the row is canonical
           again. *)
        let* () = exec conn "restore flags" q_make_unlisted home in
        let* () = Ncid_relax.drop conn in
        Lwt.finalize
          (fun () ->
            let* () =
              exec conn "corrupt slug" Phrq.q_corrupt_community_slug
                (home, "phcv-mix bad slug")
            in
            load_expect "corrupt eligible slug" Rm.Inconsistent_data conn
              ~user:a ~slug:"phcv-mix")
          (fun () ->
            let* () =
              exec conn "recanonicalize" Ncid_relax.q_recanonicalize
                (home, "phcv-mix-home", "phcv-mix-home")
            in
            Ncid_relax.restore conn))

  (* === active relation === *)

  let active_pending_case =
    db_case "choice: active pending relation suppresses the eligible list"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* _, _project =
          make_project conn ~user:a ~ext_id:944400005L ~slug:"phcv-pend"
        in
        let* home =
          insert_community conn "phcv-pend-home" ~name:"Phcv Pending Home"
        in
        let* _other = insert_community conn "phcv-pend-other" in
        let* _rid =
          request_pending "pending fixture" conn ~user:a ~slug:"phcv-pend"
            ~community:home ~note:"phcv secret note" ()
        in
        let* view = load_view "pending load" conn ~user:a ~slug:"phcv-pend" in
        let relation = active_of "pending" view in
        Alcotest.(check bool) "status pending" true
          (Rm.active_relation_status relation = Phr.Pending);
        let c = Rm.active_relation_community relation in
        Alcotest.(check int) "target id" home (Rm.community_id c);
        Alcotest.(check string) "target slug" "phcv-pend-home"
          (Rm.community_slug c);
        Alcotest.(check string) "target name" "Phcv Pending Home"
          (Rm.community_name c);
        Alcotest.(check string) "fully eligible target maps Public" "public"
          (vis_str (Rm.community_visibility c));
        (* The private note crosses nowhere: no accessor exists, and no
           exposed field carries it. *)
        List.iter
          (fun v ->
            Alcotest.(check bool) "no note leakage" false
              (contains v "phcv secret note"))
          [ Rm.community_name c; Rm.community_slug c;
            (match Rm.community_description c with Some d -> d | None -> "")
          ];
        Alcotest.(check int) "eligible list exactly empty" 0
          (List.length (Rm.eligible_communities view));
        Lwt.return_unit)

  let active_accepted_case =
    db_case "choice: accepted home is the active relation" (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* _, _project =
          make_project conn ~user:a ~ext_id:944400006L ~slug:"phcv-acc"
        in
        let* home = insert_community conn "phcv-acc-home" in
        let* rid =
          request_pending "accepted fixture" conn ~user:a ~slug:"phcv-acc"
            ~community:home ()
        in
        let* () = exec conn "accept" Phrq.q_mark_accepted rid in
        let* view = load_view "accepted load" conn ~user:a ~slug:"phcv-acc" in
        let relation = active_of "accepted" view in
        Alcotest.(check bool) "status accepted" true
          (Rm.active_relation_status relation = Phr.Accepted);
        Alcotest.(check string) "target slug" "phcv-acc-home"
          (Rm.community_slug (Rm.active_relation_community relation));
        Alcotest.(check string) "fully eligible target maps Public" "public"
          (vis_str
             (Rm.community_visibility
                (Rm.active_relation_community relation)));
        Alcotest.(check int) "eligible list exactly empty" 0
          (List.length (Rm.eligible_communities view));
        Lwt.return_unit)

  let historical_case =
    db_case "choice: historical rejected/removed rows never suppress the list"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* _, _project =
          make_project conn ~user:a ~ext_id:944400007L ~slug:"phcv-hist"
        in
        let* home = insert_community conn "phcv-hist-home" in
        let* rid =
          request_pending "first request" conn ~user:a ~slug:"phcv-hist"
            ~community:home ()
        in
        let* () = exec conn "reject" Phrq.q_mark_rejected rid in
        let* view = load_view "after rejection" conn ~user:a ~slug:"phcv-hist" in
        check_no_active "rejection leaves no active relation" view;
        Alcotest.(check (list string)) "target eligible again"
          [ "phcv-hist-home" ]
          (List.map Rm.community_slug
             (phcv_only (Rm.eligible_communities view)));
        let* rid2 =
          request_pending "second request" conn ~user:a ~slug:"phcv-hist"
            ~community:home ()
        in
        let* () = exec conn "accept" Phrq.q_mark_accepted rid2 in
        let* () = exec conn "remove" Phrq.q_mark_removed rid2 in
        let* view2 = load_view "after removal" conn ~user:a ~slug:"phcv-hist" in
        check_no_active "removal leaves no active relation" view2;
        Alcotest.(check (list string)) "target eligible after removal"
          [ "phcv-hist-home" ]
          (List.map Rm.community_slug
             (phcv_only (Rm.eligible_communities view2)));
        Lwt.return_unit)

  let drift_case =
    db_case_lifecycle_relaxed "choice: drifted active targets map exactly, reasons collapsed"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        (* Four projects, one active target each: the still-eligible
           unlisted shape keeps its exact label; private, draft, and
           legacy drift all collapse to the same unavailable state. *)
        let* () =
          Lwt_list.iter_s
            (fun (ext_id, slug) ->
              let* _ = make_project conn ~user:a ~ext_id ~slug in
              Lwt.return_unit)
            [ (944400008L, "phcv-drift-unl")
            ; (944400009L, "phcv-drift-priv")
            ; (944400011L, "phcv-drift-draft")
            ; (944400012L, "phcv-drift-leg")
            ]
        in
        let* unlisted_home =
          insert_community conn "phcv-drift-unl-home"
            ~name:"Phcv Drift Alpha"
        in
        let* private_home =
          insert_community conn "phcv-drift-priv-home"
            ~name:"Phcv Drift Beta"
        in
        let* draft_home =
          insert_community conn "phcv-drift-draft-home"
            ~name:"Phcv Drift Gamma"
        in
        let* legacy_home =
          insert_community conn "phcv-drift-leg-home"
            ~name:"Phcv Drift Delta"
        in
        let* () =
          Lwt_list.iter_s
            (fun (slug, community) ->
              let* _ =
                request_pending "drift fixture" conn ~user:a ~slug
                  ~community ()
              in
              Lwt.return_unit)
            [ ("phcv-drift-unl", unlisted_home)
            ; ("phcv-drift-priv", private_home)
            ; ("phcv-drift-draft", draft_home)
            ; ("phcv-drift-leg", legacy_home)
            ]
        in
        let* () = exec conn "make unlisted" q_make_unlisted unlisted_home in
        let* () = exec conn "make private" q_make_private private_home in
        let* () = exec conn "make draft" q_make_draft_state draft_home in
        let* () = exec conn "make legacy" q_make_legacy legacy_home in
        Lwt_list.iter_s
          (fun (label, slug, home_slug, expected) ->
            let* view = load_view label conn ~user:a ~slug in
            let relation = active_of label view in
            let c = Rm.active_relation_community relation in
            Alcotest.(check string) (label ^ ": identity survives") home_slug
              (Rm.community_slug c);
            Alcotest.(check string) (label ^ ": exact mapping") expected
              (vis_str (Rm.community_visibility c));
            (* The reason never crosses: no accessor value names the
               drifted lifecycle. *)
            List.iter
              (fun word ->
                List.iter
                  (fun v ->
                    Alcotest.(check bool)
                      (label ^ ": no " ^ word ^ " leakage") false
                      (contains (String.lowercase_ascii v) word))
                  [ Rm.community_name c
                  ; vis_str (Rm.community_visibility c)
                  ; (match Rm.community_description c with
                    | Some d -> d
                    | None -> "")
                  ])
              [ "private"; "draft"; "legacy"; "network" ];
            (* The active relation still suppresses the chooser. *)
            Alcotest.(check int) (label ^ ": eligible list exactly empty") 0
              (List.length (Rm.eligible_communities view));
            Lwt.return_unit)
          [ ( "unlisted target", "phcv-drift-unl", "phcv-drift-unl-home",
              "unlisted" )
          ; ( "private target", "phcv-drift-priv", "phcv-drift-priv-home",
              "currently_unavailable" )
          ; ( "draft target", "phcv-drift-draft", "phcv-drift-draft-home",
              "currently_unavailable" )
          ; ( "legacy target", "phcv-drift-leg", "phcv-drift-leg-home",
              "currently_unavailable" )
          ])

  let corrupt_active_case =
    db_case_lifecycle_relaxed "choice: malformed active-target metadata is corrupt, never partial"
      (fun conn ->
        let* a = insert_user conn "phcv_a" in
        let* _, _project =
          make_project conn ~user:a ~ext_id:944400010L ~slug:"phcv-corr"
        in
        let* home =
          insert_community conn "phcv-corr-home" ~name:"Phcv Corr Home"
        in
        let* _ =
          request_pending "corrupt fixture" conn ~user:a ~slug:"phcv-corr"
            ~community:home ()
        in
        (* Flags that contradict each other are corruption even on an
           active target — never Currently_unavailable. *)
        let* () = exec conn "mix flags" Phrq.q_mix_community_flags home in
        let* () =
          load_expect "mixed flags on active target" Rm.Inconsistent_data
            conn ~user:a ~slug:"phcv-corr"
        in
        let* () = exec conn "restore flags" q_make_listed home in
        (* Identity corruption is now barred by the scoped constraints;
           they are dropped for these probes alone and restored under
           Lwt.finalize once the row is canonical again. *)
        let* () = Ncid_relax.drop conn in
        Lwt.finalize
          (fun () ->
            let* () =
              exec conn "corrupt slug" Phrq.q_corrupt_community_slug
                (home, "phcv-corr bad slug")
            in
            let* () =
              load_expect "non-addressable target slug" Rm.Inconsistent_data
                conn ~user:a ~slug:"phcv-corr"
            in
            let* () =
              exec conn "restore slug" Phrq.q_corrupt_community_slug
                (home, "phcv-corr-home")
            in
            let* () = exec conn "blank name" q_set_name (home, "   ") in
            let* () =
              load_expect "blank target name" Rm.Inconsistent_data conn
                ~user:a ~slug:"phcv-corr"
            in
            let* () =
              exec conn "restore name" q_set_name (home, "Phcv Corr Home")
            in
            let* () =
              exec conn "corrupt description" q_corrupt_description home
            in
            load_expect "control-unsafe description" Rm.Inconsistent_data
              conn ~user:a ~slug:"phcv-corr")
          (fun () ->
            let* () =
              exec conn "recanonicalize" Ncid_relax.q_recanonicalize
                (home, "phcv-corr-home", "Phcv Corr Home")
            in
            Ncid_relax.restore conn))

  let suite =
    [ pure_inputs_case; storage_case; steward_view_case; collapse_case;
      eligible_case; mixed_flags_case; active_pending_case;
      active_accepted_case; historical_case; drift_case;
      corrupt_active_case ]
end

(* === Existing-community home request handlers
   (Project_home_request_handlers) ===
   GET/POST /projects/:slug/request-home: DB-free access, origin, and CSRF
   gates (every rejection precedes SQL — no sql_pool is installed in those
   harnesses), and the database-gated end-to-end flow over verified
   permanent projects built through the real finalization chain, real
   communities, and the transactional request store. Reserved
   external-installation-id range 944800001..944800999 (hence account ids
   944900001..944900999, which also scope the permanent-project cleanup),
   phch_% usernames, and phch-% community slugs so no suite shares
   fixtures. Credential and privacy assertions are boolean, so no fixture
   byte reaches test output on failure. *)
module Phch = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module H = Earde.Project_home_request_handlers
  module Rq = Earde.Project_home_request_store

  let case = go_case
  let counting_loader = Gh_start_handler.counting_loader
  let ok_loader = Gh_start_handler.ok_loader
  let status_of = Gh_start_handler.status_of
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let make_project = Phrq.make_project
  let insert_community = Phcv.insert_community
  let must = Pch.must
  let must_not = Pch.must_not

  let target slug = Printf.sprintf "/projects/%s/request-home" slug

  let make_get ~mode = H.make_project_home_choice_handler ~mode

  let make_post ~mode ~load_config =
    H.make_project_home_request_handler ~mode ~load_config

  (* --- Fixtures --- *)

  (* Same dependency order as the sibling suites. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 944900001 AND 944900999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 944900001 AND 944900999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 944800001 AND 944800999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phch-%'"
      ; "DELETE FROM users WHERE username LIKE 'phch_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 944800001 AND 944800999"
      ]

  (* Each case gets a fresh connection and a clean fixture slate; cleanup
     runs again afterwards even when an assertion fails mid-way, and the
     connection is disconnected deterministically. *)
  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun ~url conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f ~url conn))

  let q_pending_id =
    (Caqti_type.int64 ->! Caqti_type.int64)
    "SELECT id FROM community_projects \
     WHERE project_id = $1 AND status = 'pending'"

  (* Test-only failure injection for the handler-level store failure: an
     AFTER trigger scoped to one reserved note value, so the failure fires
     only after the insertion was genuinely attempted. Installed and
     dropped inside that case alone; production migrations are
     untouched. *)
  let phch_poison_note = "phch poison marker"

  let q_create_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE FUNCTION phch_fail_insert_fn() RETURNS trigger
     LANGUAGE plpgsql
     AS 'BEGIN RAISE EXCEPTION ''phch fixture failure''; END'"

  let q_create_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE TRIGGER phch_fail_insert
     AFTER INSERT ON community_projects
     FOR EACH ROW WHEN (NEW.request_note = 'phch poison marker')
     EXECUTE FUNCTION phch_fail_insert_fn()"

  let q_drop_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP TRIGGER IF EXISTS phch_fail_insert ON community_projects"

  let q_drop_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP FUNCTION IF EXISTS phch_fail_insert_fn()"

  (* === DB-free: GET access gates === *)

  let gate_target = target "phch-any"

  let get_run ?session ~mode () =
    Pch.gate_run ?session ~method_:`GET ~target:gate_target (make_get ~mode)

  let get_off_case =
    case "GET request-home off: clean /bring redirect before params or SQL"
      (fun () ->
        Pch.check_clean_redirect "off" "/bring"
          (Pch.gate_response "off"
             (get_run ~session:Pch.admin_session ~mode:Ob.Off ())))

  let get_anonymous_case =
    case "GET request-home: anonymous and invalid sessions to /login"
      (fun () ->
        Pch.check_clean_redirect "anonymous" "/login"
          (Pch.gate_response "anonymous" (get_run ~mode:Ob.Public ()));
        List.iter
          (fun raw ->
            Pch.check_clean_redirect ("user_id " ^ raw) "/login"
              (Pch.gate_response ("user_id " ^ raw)
                 (get_run ~session:[ ("user_id", raw) ] ~mode:Ob.Public ())))
          [ "not-a-number"; ""; "0"; "-3" ];
        Pch.check_clean_redirect "is_admin only" "/login"
          (Pch.gate_response "is_admin only"
             (get_run ~session:[ ("is_admin", "true") ] ~mode:Ob.Admins ())))

  let get_rollout_case =
    case "GET request-home admins mode: non-admin to /bring, admin continues"
      (fun () ->
        Pch.check_clean_redirect "non-admin" "/bring"
          (Pch.gate_response "non-admin"
             (get_run ~session:Pch.logged_in ~mode:Ob.Admins ()));
        (* Past the gates, the routerless harness has no :slug parameter,
           which answers as the generic 404 — reaching it proves the gates
           passed with no SQL (no sql_pool is installed). *)
        let continues label session mode =
          let response =
            Pch.gate_response label (get_run ~session ~mode ())
          in
          Alcotest.(check int) (label ^ ": generic 404") 404
            (status_of response)
        in
        continues "admin continues" Pch.admin_session Ob.Admins;
        continues "public user continues" Pch.logged_in Ob.Public)

  let get_gate_suite = [ get_off_case; get_anonymous_case; get_rollout_case ]

  (* === DB-free: POST access gates, configuration, and origin policy === *)

  let post_run ?session ?(headers = []) ~mode ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST ~target:gate_target
      (make_post ~mode ~load_config)

  let post_off_case =
    case "POST request-home off: clean /bring redirect, loader untouched"
      (fun () ->
        let loader, calls = counting_loader (ok_loader ()) in
        let response =
          Pch.gate_response "off"
            (post_run ~session:Pch.admin_session ~mode:Ob.Off
               ~load_config:loader ())
        in
        Pch.check_clean_redirect "off" "/bring" response;
        Alcotest.(check int) "loader never called" 0 !calls)

  let post_anonymous_case =
    case
      "POST request-home: anonymous and invalid sessions to /login, loader \
       untouched"
      (fun () ->
        let loader, calls = counting_loader (ok_loader ()) in
        Pch.check_clean_redirect "anonymous" "/login"
          (Pch.gate_response "anonymous"
             (post_run ~mode:Ob.Public ~load_config:loader ()));
        List.iter
          (fun raw ->
            Pch.check_clean_redirect ("user_id " ^ raw) "/login"
              (Pch.gate_response ("user_id " ^ raw)
                 (post_run
                    ~session:[ ("user_id", raw) ]
                    ~mode:Ob.Public ~load_config:loader ())))
          [ "not-a-number"; ""; "0"; "-3" ];
        Pch.check_clean_redirect "is_admin only" "/login"
          (Pch.gate_response "is_admin only"
             (post_run
                ~session:[ ("is_admin", "true") ]
                ~mode:Ob.Admins ~load_config:loader ()));
        Alcotest.(check int) "loader never called" 0 !calls)

  let post_rollout_case =
    case
      "POST request-home admins mode: non-admin to /bring before the route \
       or configuration"
      (fun () ->
        let loader, calls = counting_loader (ok_loader ()) in
        Pch.check_clean_redirect "non-admin" "/bring"
          (Pch.gate_response "non-admin"
             (post_run ~session:Pch.logged_in ~mode:Ob.Admins
                ~load_config:loader ()));
        Alcotest.(check int) "loader never called" 0 !calls;
        (* Past the gates, the routerless harness has no :slug parameter:
           the defensive 404 answers before the configuration is ever
           loaded — with no SQL (no sql_pool is installed). *)
        let continues label session mode =
          let loader, calls = counting_loader (ok_loader ()) in
          let response =
            Pch.gate_response label
              (post_run ~session ~mode ~load_config:loader ())
          in
          Alcotest.(check int) (label ^ ": defensive 404") 404
            (status_of response);
          Alcotest.(check int) (label ^ ": loader after missing route") 0
            !calls
        in
        continues "admin continues" Pch.admin_session Ob.Admins;
        continues "public user continues" Pch.logged_in Ob.Public)

  (* The routed DB-free harness: the real route shape supplies :slug, so
     the configuration and origin gates are reachable; rejections still
     precede SQL (no sql_pool is installed). *)
  let routed_post ?session ?(headers = []) ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST ~target:gate_target
      (Dream.router
         [ Dream.post "/projects/:slug/request-home"
             (fun req -> make_post ~mode:Ob.Public ~load_config req)
         ])

  let post_config_failure_case =
    case "POST request-home: configuration error is a generic 503, no form"
      (fun () ->
        let loader, calls = counting_loader (gac_of_values ~origin:None ()) in
        let response =
          Pch.gate_response "config failure"
            (routed_post ~session:Pch.logged_in
               ~headers:
                 [ ("Origin", "https://earde.com");
                   ("Content-Type", "application/x-www-form-urlencoded");
                 ]
               ~load_config:loader ())
        in
        Alcotest.(check int) "503" 503 (status_of response);
        Alcotest.(check int) "loader called once" 1 !calls;
        let body = Lwt_main.run (Dream.body response) in
        List.iter
          (fun needle ->
            Alcotest.(check bool)
              ("body does not leak " ^ needle)
              false (contains body needle))
          [ "EARDE_PUBLIC_ORIGIN"; "Missing"; "Invalid"; "public_origin" ])

  let origin_run label ?sec_fetch_site origin =
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @
      match sec_fetch_site with
      | Some v -> [ ("Sec-Fetch-Site", v) ]
      | None -> []
    in
    routed_post ~session:Pch.logged_in ~headers
      ~load_config:(fun () -> ok_loader ())
      ()
    |> Pch.gate_response label

  let origin_rejected label ?sec_fetch_site origin =
    let response = origin_run label ?sec_fetch_site origin in
    Alcotest.(check int) (label ^ ": 403") 403 (status_of response)

  let origin_accepted label ?sec_fetch_site origin =
    (* Passing the origin gate, the missing content type is the next
       rejection: reaching that 400 proves the origin policy accepted. *)
    let response = origin_run label ?sec_fetch_site origin in
    Alcotest.(check int)
      (label ^ ": passes the origin gate")
      400 (status_of response)

  let post_origin_case =
    case "POST request-home origin gate: exact policy of the project POSTs"
      (fun () ->
        origin_accepted "exact origin" (Some "https://earde.com");
        origin_accepted "explicit default port" (Some "https://earde.com:443");
        origin_accepted "fetch metadata" ~sec_fetch_site:"same-origin" None;
        origin_rejected "cross-origin" (Some "https://evil.example");
        origin_rejected "same-site subdomain" (Some "https://www.earde.com");
        origin_rejected "wrong scheme" (Some "http://earde.com");
        origin_rejected "wrong port" (Some "https://earde.com:8443");
        origin_rejected "null" (Some "null");
        origin_rejected "blank" (Some "");
        origin_rejected "mismatch beats same-origin metadata"
          ~sec_fetch_site:"same-origin" (Some "https://evil.example");
        origin_rejected "no signals" None;
        origin_rejected "cross-site" ~sec_fetch_site:"cross-site" None;
        origin_rejected "same-site" ~sec_fetch_site:"same-site" None;
        origin_rejected "none" ~sec_fetch_site:"none" None;
        let response = origin_run "reflection" (Some "https://evil.example") in
        let body = Lwt_main.run (Dream.body response) in
        Alcotest.(check bool) "origin not reflected" false
          (contains body "evil.example"))

  let post_gate_suite =
    [ post_off_case; post_anonymous_case; post_rollout_case;
      post_config_failure_case; post_origin_case ]

  (* === DB-free: POST CSRF handling (rejections precede SQL) === *)

  let request_fields ?(target_id = "1") ?(note = "ciao") () =
    [ ("target_community_id", target_id); ("request_note", note) ]

  let csrf_pipeline () =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    let* () = Dream.set_session_field req "user_id" "42" in
    match Dream.method_ req with
    | `GET ->
        Dream.respond
          (Dream.csrf_token req ^ "\n"
          ^ Dream.csrf_token ~valid_for:(-60.) req)
    | _ ->
        Dream.router
          [ Dream.post "/projects/:slug/request-home"
              (fun r ->
                make_post ~mode:Ob.Public
                  ~load_config:(fun () -> ok_loader ())
                  r)
          ]
          req

  let csrf_post ?cookie ?(content_type = true) pipeline fields =
    let headers =
      [ ("Origin", "https://earde.com") ]
      @ (if content_type then
           [ ("Content-Type", "application/x-www-form-urlencoded") ]
         else [])
      @ match cookie with Some c -> [ ("Cookie", c) ] | None -> []
    in
    match
      Lwt_main.run
        (pipeline
           (Dream.request ~method_:`POST ~target:(target "phch-csrf")
              ~headers (Pch.form_body fields)))
    with
    | response -> `Response response
    | exception _ -> `Db_boundary

  let csrf_rejected label expected result =
    let response = Pch.gate_response label result in
    Alcotest.(check int) (label ^ ": status") expected (status_of response)

  let csrf_case =
    case "POST request-home CSRF: Dream verification gates every submission"
      (fun () ->
        let pipeline = csrf_pipeline () in
        let cookie, fresh, expired = Pch.mint_tokens "mint" pipeline in
        let fields = request_fields () in
        (* Every CSRF failure refuses the submission, but it is answered by
           reloading the authorized current state (a fresh token, nothing
           reflected) rather than a terminal page — so each one reaches the
           read model's DB boundary and none reaches the store. A page whose
           one-hour token outlived its fourteen-day session must not become
           permanently unsubmittable. *)
        Pch.check_db_boundary "missing token re-renders"
          (csrf_post ~cookie pipeline fields);
        Pch.check_db_boundary "invalid token re-renders"
          (csrf_post ~cookie pipeline
             (fields @ [ ("dream.csrf", "not-a-token") ]));
        Pch.check_db_boundary "expired token re-renders"
          (csrf_post ~cookie pipeline (fields @ [ ("dream.csrf", expired) ]));
        Pch.check_db_boundary "duplicate tokens re-render"
          (csrf_post ~cookie pipeline
             (fields @ [ ("dream.csrf", fresh); ("dream.csrf", fresh) ]));
        Pch.check_db_boundary "wrong session re-renders"
          (csrf_post pipeline (fields @ [ ("dream.csrf", fresh) ]));
        (* A wrong content type is still answered without any SQL. *)
        csrf_rejected "wrong content type" 400
          (csrf_post ~cookie ~content_type:false pipeline
             (fields @ [ ("dream.csrf", fresh) ]));
        (* A verified token with valid application fields reaches the DB
           boundary: CSRF passed and Dream stripped its own field before
           the strict parser. *)
        Pch.check_db_boundary "verified form continues"
          (csrf_post ~cookie pipeline (fields @ [ ("dream.csrf", fresh) ]));
        (* A verified token with a malformed application form also reaches
           the DB boundary — the current-state re-render — never a direct
           rejection that skips reauthorization. *)
        Pch.check_db_boundary "malformed form re-render continues"
          (csrf_post ~cookie pipeline
             [ ("request_note", "phch-zz9"); ("dream.csrf", fresh) ]))

  let csrf_suite = [ csrf_case ]

  (* === Database-gated: the real GET/POST flow === *)

  (* The real production shape: sql_pool + secret + memory sessions + the
     real router paths, so both handlers read :slug exactly as in bin/main.
     /mint exists only to hand replay cases a fresh CSRF token for an
     already-established session. *)
  let app_pipeline ?session_user_id ~url () =
    Dream.sql_pool url @@ Dream.set_secret gck_secret
    @@ Dream.memory_sessions
    @@ (fun handler request ->
         match session_user_id with
         | None -> handler request
         | Some uid ->
             let* () =
               Dream.set_session_field request "user_id" (string_of_int uid)
             in
             handler request)
    @@ Dream.router
         [ Dream.get "/mint" (fun req -> Dream.respond (Dream.csrf_token req));
           Dream.get "/projects/:slug/setup" (fun req ->
               Pch.make_setup ~mode:Ob.Public req);
           Dream.get "/projects/:slug/request-home" (fun req ->
               make_get ~mode:Ob.Public req);
           Dream.post "/projects/:slug/request-home"
             (fun req ->
               make_post ~mode:Ob.Public
                 ~load_config:(fun () -> ok_loader ())
                 req);
         ]

  (* One GET that opens the chooser: page, session cookie, and CSRF token
     for the follow-up POST. *)
  let open_choice_page label ~slug pipeline =
    let* response, body = Pch.do_get ~target:(target slug) pipeline in
    Pch.check_page label response;
    let cookie = Pch.session_cookie label response in
    let token = Pch.csrf_of_page label body in
    Lwt.return (cookie, token, body)

  let do_post ?(origin = Some "https://earde.com") ~cookie ~slug ~fields
      pipeline =
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @ [ ("Content-Type", "application/x-www-form-urlencoded");
          ("Cookie", cookie);
        ]
    in
    pipeline
      (Dream.request ~method_:`POST ~target:(target slug) ~headers
         (Pch.form_body fields))

  let count_relations conn project =
    find conn "relation count" Phrq.q_count_for_project project

  let check_no_relations label conn project =
    let* n = count_relations conn project in
    Alcotest.(check int) label 0 n;
    Lwt.return_unit

  let radio_marker id = Printf.sprintf "value='%d'" id

  (* === GET states === *)

  let get_chooser_case =
    db_case "GET: eligible communities render the chooser with a CSRF form"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, _project =
          make_project conn ~user:uid ~ext_id:944800001L ~slug:"phch-states"
        in
        let* pub =
          insert_community ~name:"Phch States Pub"
            ~description:"Descrizione pubblica" conn "phch-states-pub"
        in
        let* unl =
          insert_community ~name:"Phch States Unl" ~indexable:false
            ~discoverable:false conn "phch-states-unl"
        in
        let* _legacy =
          insert_community ~network:false conn "phch-states-legacy"
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* _cookie, _token, body =
          open_choice_page "chooser" ~slug:"phch-states" pipeline
        in
        (* check_page (inside open_choice_page) already asserted 200 +
           no-store + no-referrer; csrf_of_page asserted the framework
           field. *)
        Alcotest.(check bool) "noindex" true (contains body "noindex");
        let frag = ps_fragment body in
        must frag "Connect to an existing community";
        must frag "action='/projects/phch-states/request-home'";
        must frag (radio_marker pub);
        must frag (radio_marker unl);
        must frag "Phch States Pub";
        must frag "Descrizione pubblica";
        must frag "phc-community-visibility'>Public";
        must frag "phc-community-visibility'>Unlisted";
        must_not frag "phch-states-legacy";
        Lwt.return_unit)

  let get_no_eligible_case =
    db_case "GET: zero eligible communities render the no-eligible state"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, _project =
          make_project conn ~user:uid ~ext_id:944800002L ~slug:"phch-none"
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* response, body =
          Pch.do_get ~target:(target "phch-none") pipeline
        in
        Pch.check_page "no eligible" response;
        let frag = ps_fragment body in
        must frag "No eligible published network community";
        must frag "href='/projects/phch-none/setup'";
        must_not frag "<form";
        must_not frag "phc-request-form";
        Lwt.return_unit)

  let get_active_states_case =
    db_case_lifecycle_relaxed "GET: pending, accepted, and drifted active targets render"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, _project =
          make_project conn ~user:uid ~ext_id:944800003L ~slug:"phch-active"
        in
        let* home =
          insert_community ~name:"Phch Active Home" conn "phch-active-home"
        in
        let* rid =
          Phcv.request_pending "pending fixture" conn ~user:uid
            ~slug:"phch-active" ~community:home ~note:"phch secret note" ()
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* response, body =
          Pch.do_get ~target:(target "phch-active") pipeline
        in
        Pch.check_page "pending" response;
        let frag = ps_fragment body in
        must frag "Home request pending";
        must frag "Phch Active Home";
        must frag "/c/phch-active-home";
        must_not frag "phc-request-form";
        must_not frag "<form";
        (* The private note never renders on the workflow page, and an
           eligible target carries no availability marker. *)
        must_not body "phch secret note";
        must_not frag "Currently unavailable";
        (* Drift: an ineligible active target stays visible with only the
           generic availability marker — never the reason. *)
        let* () = exec conn "make private" Phcv.q_make_private home in
        let* response, body =
          Pch.do_get ~target:(target "phch-active") pipeline
        in
        Pch.check_page "drifted pending" response;
        let frag = ps_fragment body in
        must frag "Home request pending";
        must frag "Phch Active Home";
        must frag "Currently unavailable";
        must_not frag "private";
        must_not frag "<form";
        (* Accepted relation. *)
        let* () = exec conn "restore" Phcv.q_make_listed home in
        let* () = exec conn "accept" Phrq.q_mark_accepted rid in
        let* response, body =
          Pch.do_get ~target:(target "phch-active") pipeline
        in
        Pch.check_page "accepted" response;
        let frag = ps_fragment body in
        must frag "Community home connected";
        must frag "Phch Active Home";
        (* No request form: the accepted state cannot solicit a second home.
           Its one form is the steward removal control, whose action is the
           removal route built from both canonical slugs. *)
        must_not frag "phc-request-form";
        Alcotest.(check int) "exactly one form" 1 (ps_count frag "<form");
        must frag
          "action='/projects/phch-active/community-home/phch-active-home/remove'";
        must frag "Remove community home";
        Lwt.return_unit)

  let get_not_found_case =
    db_case "GET: every unavailable project collapses to the generic 404"
      (fun ~url conn ->
        let* a = insert_user conn "phch_a" in
        let* b = insert_user conn "phch_b" in
        let* _inst, project =
          make_project conn ~user:a ~ext_id:944800004L ~slug:"phch-auth"
        in
        let owner = app_pipeline ~session_user_id:a ~url () in
        let foreign = app_pipeline ~session_user_id:b ~url () in
        let expect_404 label pipeline slug =
          let* response, body = Pch.do_get ~target:(target slug) pipeline in
          Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
          Alcotest.(check (option string)) (label ^ ": no-store")
            (Some "no-store")
            (Dream.header response "Cache-Control");
          must body "This page does not exist.";
          (* No project identity leaks through the collapse. *)
          must_not body "Pfin Fixture Project";
          Lwt.return_unit
        in
        let* () = expect_404 "missing slug" owner "phch-absent" in
        let* () = expect_404 "malformed slug" owner "Phch--Bad" in
        let* () = expect_404 "foreign project" foreign "phch-auth" in
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* () = expect_404 "stale project" owner "phch-auth" in
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification (project, "revoked")
        in
        let* () = expect_404 "revoked project" owner "phch-auth" in
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        let* () = exec conn "drop steward" Phrq.q_delete_steward (project, a) in
        expect_404 "creator without stewardship" owner "phch-auth")

  let get_inconsistent_case =
    db_case_lifecycle_relaxed "GET: durable corruption is one generic 500, never a page state"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, _project =
          make_project conn ~user:uid ~ext_id:944800005L ~slug:"phch-mix"
        in
        let* home = insert_community conn "phch-mix-home" in
        let* () = exec conn "mix flags" Phrq.q_mix_community_flags home in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* response, body =
          Pch.do_get ~target:(target "phch-mix") pipeline
        in
        Alcotest.(check int) "500" 500 (status_of response);
        Alcotest.(check (option string)) "no-store" (Some "no-store")
          (Dream.header response "Cache-Control");
        must body "Something went wrong on our side.";
        List.iter (must_not body)
          [ "Inconsistent"; "indexable"; "discoverable"; "PostgreSQL";
            "Caqti" ];
        Lwt.return_unit)

  let get_storage_case =
    db_case "GET: a real database failure collapses to the generic 500"
      (fun ~url _conn ->
        (* A pool whose connections resolve no unqualified table names: a
           real PostgreSQL request failure surfaced through the read model,
           collapsed payload-free by the handler. *)
        let poisoned =
          Uri.to_string
            (Uri.add_query_param' (Uri.of_string url)
               ("options", "-csearch_path=phch_void"))
        in
        let pipeline = app_pipeline ~session_user_id:42 ~url:poisoned () in
        let* response, body =
          Pch.do_get ~target:(target "phch-any") pipeline
        in
        Alcotest.(check int) "500" 500 (status_of response);
        must body "Something went wrong on our side.";
        List.iter (must_not body)
          [ "phch_void"; "search_path"; "PostgreSQL"; "Caqti"; "relation" ];
        Lwt.return_unit)

  let get_db_suite =
    [ get_chooser_case; get_no_eligible_case; get_active_states_case;
      get_not_found_case; get_inconsistent_case; get_storage_case ]

  (* === POST: PRG, replay, and privacy === *)

  let credential_needles =
    [ ("access token", Pod_store.pods_access_fixture)
    ; ("refresh token", Pod_store.pods_refresh_fixture)
    ; ("authorization code", gte_code_string)
    ; ("PKCE verifier", gte_verifier_string)
    ; ("client secret", gte_client_secret)
    ; ("OAuth state", goc_fixture 'S')
    ; ("session binding", goc_fixture 'B')
    ; ("private repository name", gur_private_name)
    ; ("private repository description", gur_private_description)
    ]

  let post_prg_case =
    db_case "POST: request, PRG redirect, pending state, refresh, replay"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, project =
          make_project conn ~user:uid ~ext_id:944800011L ~slug:"phch-flow"
        in
        let* home =
          insert_community ~name:"Phch Flow Home" conn "phch-flow-home"
        in
        let* other =
          insert_community ~name:"Phch Flow Other" conn "phch-flow-other"
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, body =
          open_choice_page "chooser" ~slug:"phch-flow" pipeline
        in
        let frag = ps_fragment body in
        must frag "action='/projects/phch-flow/request-home'";
        must frag (radio_marker home);
        (* The submitted note carries CRLF endings and outer whitespace;
           the domain canonicalizes both. *)
        let note_raw = "  Prima riga \xe2\x98\x95\r\nseconda riga\t \r\n" in
        let note_canonical = "Prima riga \xe2\x98\x95\nseconda riga" in
        let* response =
          do_post ~cookie ~slug:"phch-flow"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", note_raw);
                ("dream.csrf", token);
              ]
            pipeline
        in
        (* Exact PRG: the same permanent route, no query string, no id. *)
        let* () =
          Pch.check_redirect_lwt "created" "/projects/phch-flow/request-home"
            response
        in
        let redirect_cookies =
          String.concat "|" (Dream.headers response "Set-Cookie")
        in
        (* Exactly one pending relation with the canonical note and the
           session requester; nothing else changed. *)
        let* n = count_relations conn project in
        Alcotest.(check int) "one relation" 1 n;
        let* rid = find conn "pending id" q_pending_id project in
        let* ( ((_, rc), (rtype, status))
             , ((req, rev), (stored_note, _)) ) =
          find conn "relation row" Phrq.q_relation_row rid
        in
        Alcotest.(check int) "target community" home rc;
        Alcotest.(check string) "relation type home" "home" rtype;
        Alcotest.(check string) "status pending" "pending" status;
        Alcotest.(check (option int)) "requester is the session user"
          (Some uid) req;
        Alcotest.(check (option int)) "no reviewer" None rev;
        Alcotest.(check (option string)) "canonical note"
          (Some note_canonical) stored_note;
        let* members = find conn "members" Phrq.q_count_members home in
        Alcotest.(check int) "no membership created" 0 members;
        let* mods = find conn "moderators" Phrq.q_count_moderators home in
        Alcotest.(check int) "no moderator created" 0 mods;
        let* stewards =
          find conn "stewards" Phrq.q_count_stewards_for_project project
        in
        Alcotest.(check int) "stewardship unchanged" 1 stewards;
        (* The redirected GET observes the durable pending state. *)
        let* response, body =
          Pch.do_get ~cookie ~target:(target "phch-flow") pipeline
        in
        Pch.check_page "pending state" response;
        let frag = ps_fragment body in
        must frag "Home request pending";
        must frag "Phch Flow Home";
        must_not frag "phc-request-form";
        must_not frag "<form";
        (* The private note and internal ids never render. *)
        must_not body "Prima riga";
        must_not frag (Int64.to_string rid);
        must_not frag (radio_marker other);
        (* No credential fixture reaches the page, the redirect cookies,
           or the relation row. *)
        let* blob =
          find conn "relation blob" Phrq.q_relation_text_blob rid
        in
        List.iter
          (fun (label, needle) ->
            Alcotest.(check bool) (label ^ " absent from page") false
              (goc_contains ~needle body);
            Alcotest.(check bool) (label ^ " absent from cookies") false
              (goc_contains ~needle redirect_cookies);
            Alcotest.(check bool) (label ^ " absent from relation row")
              false
              (goc_contains ~needle blob))
          (credential_needles
          @ [ ("installation id", "944800011")
            ; ("account id", "944900011")
            ; ("repository id", "945200011")
            ]);
        (* Refreshing the destination is a plain GET: no second relation. *)
        let* response, _ =
          Pch.do_get ~cookie ~target:(target "phch-flow") pipeline
        in
        Pch.check_page "refresh" response;
        let* n = count_relations conn project in
        Alcotest.(check int) "still one relation" 1 n;
        (* Replay with a fresh CSRF token: the authoritative active state
           answers 409 with no form and no second relation. *)
        let* fresh = Pch.mint_token "replay mint" ~cookie pipeline in
        let* response =
          do_post ~cookie ~slug:"phch-flow"
            ~fields:
              [ ("target_community_id", string_of_int other);
                ("request_note", "");
                ("dream.csrf", fresh);
              ]
            pipeline
        in
        Alcotest.(check int) "replay 409" 409 (status_of response);
        Alcotest.(check (option string)) "replay no-store" (Some "no-store")
          (Dream.header response "Cache-Control");
        Alcotest.(check (option string)) "replay no redirect" None
          (Dream.header response "Location");
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "already has a pending request or community home";
        must frag "Home request pending";
        must frag "Phch Flow Home";
        must_not frag "phc-request-form";
        must_not frag "<form";
        must_not frag (radio_marker other);
        must_not frag (Int64.to_string rid);
        let* n = count_relations conn project in
        Alcotest.(check int) "replay adds nothing" 1 n;
        let* active =
          find conn "active count" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "one active row" 1 active;
        Lwt.return_unit)

  (* === POST: structural and domain failures === *)

  let post_invalid_form_case =
    db_case "POST: malformed forms re-render the current state as 400"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, project =
          make_project conn ~user:uid ~ext_id:944800012L ~slug:"phch-bad"
        in
        let* home = insert_community conn "phch-bad-home" in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _body =
          open_choice_page "chooser" ~slug:"phch-bad" pipeline
        in
        (* A cross-origin submission is rejected before the form. *)
        let* response =
          do_post ~origin:(Some "https://evil.example") ~cookie
            ~slug:"phch-bad"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", "phch-origin-zz9");
                ("dream.csrf", token);
              ]
            pipeline
        in
        Alcotest.(check int) "cross-origin 403" 403 (status_of response);
        let* () = check_no_relations "origin rejection inserts nothing" conn
                    project
        in
        let* () =
          Lwt_list.iter_s
            (fun (label, fields) ->
              let* response =
                do_post ~cookie ~slug:"phch-bad"
                  ~fields:(fields @ [ ("dream.csrf", token) ])
                  pipeline
              in
              Alcotest.(check int) (label ^ ": 400") 400
                (status_of response);
              Alcotest.(check (option string)) (label ^ ": no redirect")
                None
                (Dream.header response "Location");
              let* body = Dream.body response in
              let frag = ps_fragment body in
              (* The current chooser re-renders with generic feedback;
                 nothing malformed is reflected. *)
              must frag "We couldn't read that request";
              must frag "action='/projects/phch-bad/request-home'";
              must frag (radio_marker home);
              must_not body "phch-zz9";
              Lwt.return_unit)
            [ ("missing target", [ ("request_note", "phch-zz9") ])
            ; ( "malformed target",
                [ ("target_community_id", "phch-zz9");
                  ("request_note", "") ] )
            ; ( "duplicate target",
                ("target_community_id", string_of_int home)
                :: request_fields ~target_id:(string_of_int home)
                     ~note:"phch-zz9" () )
            ; ( "unknown field",
                request_fields ~target_id:(string_of_int home) ~note:""
                  ()
                @ [ ("phch-zz9", "x") ] )
            ]
        in
        check_no_relations "no malformed submission inserts" conn project)

  let post_invalid_note_case =
    db_case "POST: invalid notes are 422; only safe notes are preserved"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, project =
          make_project conn ~user:uid ~ext_id:944800013L ~slug:"phch-note"
        in
        let* home = insert_community conn "phch-note-home" in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _body =
          open_choice_page "chooser" ~slug:"phch-note" pipeline
        in
        (* A safe over-length note (2004 scalars) is rejected by the
           domain but preserved untruncated — escaped — in the textarea. *)
        let overlong = "<b>" ^ String.make 2000 'x' in
        let* response =
          do_post ~cookie ~slug:"phch-note"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", overlong);
                ("dream.csrf", token);
              ]
            pipeline
        in
        Alcotest.(check int) "overlength 422" 422 (status_of response);
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "We couldn't read that request";
        must frag ("&lt;b&gt;" ^ String.make 2000 'x');
        must_not frag "<b>";
        (* An unsafe control-byte note is rejected and never reflected. *)
        let* response =
          do_post ~cookie ~slug:"phch-note"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", "phch\x01unsafe-zz9");
                ("dream.csrf", token);
              ]
            pipeline
        in
        Alcotest.(check int) "unsafe 422" 422 (status_of response);
        let* body = Dream.body response in
        must_not body "unsafe-zz9";
        let frag = ps_fragment body in
        must frag "We couldn't read that request";
        must frag (radio_marker home);
        check_no_relations "no invalid note inserts" conn project)

  (* === POST: community becomes unavailable === *)

  let post_community_unavailable_case =
    db_case_lifecycle_relaxed "POST: a drifted target is a 409 reload without the target"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, project =
          make_project conn ~user:uid ~ext_id:944800014L ~slug:"phch-cu"
        in
        let* home =
          insert_community ~name:"Phch Cu Home" conn "phch-cu-home"
        in
        let* other =
          insert_community ~name:"Phch Cu Other" conn "phch-cu-other"
        in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, body =
          open_choice_page "chooser" ~slug:"phch-cu" pipeline
        in
        must (ps_fragment body) (radio_marker home);
        (* The target drifts to a valid but ineligible lifecycle between
           the render and the submission. *)
        let* () = exec conn "make private" Phcv.q_make_private home in
        let* response =
          do_post ~cookie ~slug:"phch-cu"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", "Nota da conservare phch");
                ("dream.csrf", token);
              ]
            pipeline
        in
        Alcotest.(check int) "409" 409 (status_of response);
        let* body = Dream.body response in
        let frag = ps_fragment body in
        must frag "no longer available for project requests";
        (* The reloaded chooser no longer offers the drifted target, the
           other community remains, and the safe note survives in the
           still-present textarea. *)
        must frag "action='/projects/phch-cu/request-home'";
        must_not frag (radio_marker home);
        must frag (radio_marker other);
        must frag "Nota da conservare phch";
        must_not frag "private";
        check_no_relations "no relation inserted" conn project)

  (* === POST: concurrency === *)

  let post_race_case =
    db_case "POST: racing submissions leave one pending row and a 409 loser"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* _inst, project =
          make_project conn ~user:uid ~ext_id:944800015L ~slug:"phch-race"
        in
        let* home = insert_community conn "phch-race-home" in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token1, _body =
          open_choice_page "chooser" ~slug:"phch-race" pipeline
        in
        let* token2 = Pch.mint_token "second token" ~cookie pipeline in
        let post token =
          do_post ~cookie ~slug:"phch-race"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", "");
                ("dream.csrf", token);
              ]
            pipeline
        in
        let* r1, r2 = Lwt.both (post token1) (post token2) in
        let winner, loser =
          match (status_of r1, status_of r2) with
          | 303, 409 -> (r1, r2)
          | 409, 303 -> (r2, r1)
          | a, b -> Alcotest.failf "race statuses: %d and %d" a b
        in
        Alcotest.(check (option string)) "winner PRG"
          (Some "/projects/phch-race/request-home")
          (Dream.header winner "Location");
        let* body = Dream.body loser in
        let frag = ps_fragment body in
        must frag "already has a pending request or community home";
        must frag "Home request pending";
        must_not frag "phc-request-form";
        let* total = count_relations conn project in
        Alcotest.(check int) "exactly one row" 1 total;
        let* active =
          find conn "active count" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "exactly one active row" 1 active;
        Lwt.return_unit)

  (* === POST: authorization changes between GET and POST === *)

  let post_authorization_change_case =
    db_case "POST: lost stewardship or verification is the generic 404"
      (fun ~url conn ->
        let* uid = insert_user conn "phch_a" in
        let* inst, project =
          make_project conn ~user:uid ~ext_id:944800016L ~slug:"phch-drop"
        in
        let* home = insert_community conn "phch-drop-home" in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _body =
          open_choice_page "chooser" ~slug:"phch-drop" pipeline
        in
        let post () =
          do_post ~cookie ~slug:"phch-drop"
            ~fields:
              [ ("target_community_id", string_of_int home);
                ("request_note", "");
                ("dream.csrf", token);
              ]
            pipeline
        in
        let expect_404 label =
          let* response = post () in
          Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
          let* body = Dream.body response in
          must body "This page does not exist.";
          check_no_relations (label ^ ": no relation") conn project
        in
        (* Stewardship removed between the render and the submission. *)
        let* () =
          exec conn "drop steward" Phrq.q_delete_steward (project, uid)
        in
        let* () = expect_404 "removed stewardship" in
        let* () =
          exec conn "restore steward" Phrq.q_insert_steward
            (project, uid, inst)
        in
        (* Verification lost between the render and the submission. *)
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* () = expect_404 "stale project" in
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification
            (project, "revoked")
        in
        expect_404 "revoked project")

  (* === POST: storage failure === *)

  let post_storage_case =
    db_case "POST: a store failure is one generic 500 with no partial row"
      (fun ~url conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* uid = insert_user conn "phch_a" in
        let* _inst, project =
          make_project conn ~user:uid ~ext_id:944800017L ~slug:"phch-fail"
        in
        let* home = insert_community conn "phch-fail-home" in
        let pipeline = app_pipeline ~session_user_id:uid ~url () in
        let* cookie, token, _body =
          open_choice_page "chooser" ~slug:"phch-fail" pipeline
        in
        let exec_ddl label q =
          let* r = C.exec q () in
          let* () = or_fail label r in
          Lwt.return_unit
        in
        let* () = exec_ddl "pre-drop trigger" q_drop_fail_trigger in
        let* () = exec_ddl "pre-drop function" q_drop_fail_fn in
        let* () = exec_ddl "create function" q_create_fail_fn in
        let* () = exec_ddl "create trigger" q_create_fail_trigger in
        Lwt.finalize
          (fun () ->
            let* response =
              do_post ~cookie ~slug:"phch-fail"
                ~fields:
                  [ ("target_community_id", string_of_int home);
                    ("request_note", phch_poison_note);
                    ("dream.csrf", token);
                  ]
                pipeline
            in
            Alcotest.(check int) "500" 500 (status_of response);
            Alcotest.(check (option string)) "no-store" (Some "no-store")
              (Dream.header response "Cache-Control");
            let* body = Dream.body response in
            must body "Something went wrong on our side.";
            List.iter (must_not body)
              [ "phch fixture failure"; "RAISE"; "community_projects";
                "PostgreSQL"; "Caqti" ];
            check_no_relations "no partial relation" conn project)
          (fun () ->
            let* () = exec_ddl "drop trigger" q_drop_fail_trigger in
            exec_ddl "drop function" q_drop_fail_fn))

  let post_db_suite =
    [ post_prg_case; post_invalid_form_case; post_invalid_note_case;
      post_community_unavailable_case; post_race_case;
      post_authorization_change_case; post_storage_case ]
end

(* === Project home review store (Project_home_review_store) ===
   Transactional moderator accept/reject of the exact pending home
   request, driven over verified permanent projects built through the
   real draft/selection/finalization chain and pending relations written
   by the real request store. Database-gated (EARDE_TEST_DATABASE_URL,
   same opt-in as Mod_scope) with its own reserved
   external-installation-id range 945600001..945600999 (hence account
   ids 945700001..945700999, which also scope the permanent-project
   cleanup), phrv_% usernames, and phrv-% community slugs so no suite
   shares fixtures. Pure validation is proven pre-SQL against a
   deliberately disconnected connection. Reviewer authorization uses
   only the real durable rows: community_moderators role 'top_mod' and
   users.is_admin. No DB-free cases exist deliberately: reviewed_request
   has no public constructor, so the one pure accessor
   (resulting_status) is only exercisable — and is exercised throughout
   — on genuinely committed reviews. Credential assertions are boolean,
   so no fixture byte reaches test output on failure. *)
module Phrv = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rv = Earde.Project_home_review_store
  module Rq = Earde.Project_home_request_store

  let error_str : Rv.error -> string = function
    | Rv.Invalid_user_id -> "Invalid_user_id"
    | Rv.Invalid_project_slug -> "Invalid_project_slug"
    | Rv.Invalid_community_slug -> "Invalid_community_slug"
    | Rv.Project_unavailable -> "Project_unavailable"
    | Rv.Community_unavailable -> "Community_unavailable"
    | Rv.Reviewer_unauthorized -> "Reviewer_unauthorized"
    | Rv.Review_unavailable -> "Review_unavailable"
    | Rv.Target_ineligible -> "Target_ineligible"
    | Rv.Inconsistent_data -> "Inconsistent_data"
    | Rv.Storage_error -> "Storage_error"

  let status_str = Phr.string_of_status
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let make_project = Phrq.make_project
  let insert_community = Phcv.insert_community
  let contains = Cprj_schema.contains

  (* Same dependency order as the sibling suites. Users are deleted after
     communities so moderator rows cascade from either side cleanly. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 945700001 AND 945700999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 945700001 AND 945700999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 945600001 AND 945600999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phrv-%'"
      ; "DELETE FROM users WHERE username LIKE 'phrv_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 945600001 AND 945600999"
      ]

  (* Durable authorization fixtures — the real rows the store reads. *)
  let q_insert_moderator =
    (Caqti_type.(t3 int int string) ->. Caqti_type.unit)
    "INSERT INTO community_moderators (user_id, community_id, role) \
     VALUES ($1, $2, $3)"

  let q_remove_moderator =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
    "DELETE FROM community_moderators \
     WHERE user_id = $1 AND community_id = $2"

  let q_set_moderator_role =
    (Caqti_type.(t3 int int string) ->. Caqti_type.unit)
    "UPDATE community_moderators SET role = $3 \
     WHERE user_id = $1 AND community_id = $2"

  let q_insert_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
    "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  let q_set_admin =
    (Caqti_type.(t2 int bool) ->. Caqti_type.unit)
    "UPDATE users SET is_admin = $2 WHERE id = $1"

  (* Role signature so no-mutation assertions cover the reviewer's own
     durable role. *)
  let q_role_sig =
    (Caqti_type.(t2 int int) ->! Caqti_type.string)
    "SELECT COALESCE((SELECT role FROM community_moderators \
                      WHERE user_id = $1 AND community_id = $2), '<none>')"

  (* Review-time coherence, NULL-safe: presence plus ordering against
     created_at (reviewed_at NULL coalesces to FALSE, never a decode
     error). *)
  let q_review_times =
    (Caqti_type.int64 ->! Caqti_type.(t3 bool bool bool))
    "SELECT reviewed_at IS NOT NULL, \
            COALESCE(reviewed_at >= created_at, FALSE), \
            updated_at >= created_at \
     FROM community_projects WHERE id = $1"

  let q_status =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT status FROM community_projects WHERE id = $1"

  (* Community drift the sibling suites do not already provide. *)
  let q_make_eligible =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET is_network_community = TRUE, \
     onboarding_state = 'published', visibility = 'public', \
     indexable = TRUE, discoverable = TRUE WHERE id = $1"

  let q_mix_flags =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET indexable = TRUE, discoverable = FALSE \
     WHERE id = $1"

  (* Leaking shapes: a draft still publicly listed, and a private
     community still discoverable — both corruption per the shared
     lifecycle rule, both directly representable (the invariant is
     application-level). *)
  let q_leaky_draft =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET onboarding_state = 'draft' WHERE id = $1"

  let q_leaky_private =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET visibility = 'private', indexable = FALSE, \
     discoverable = TRUE WHERE id = $1"

  (* Targeted pending-row corruption. Notes carry only a length CHECK, so
     a non-canonical (padded) note and a forbidden control byte are both
     directly representable. A reviewer or review/removal timestamp on a
     pending row and a non-'home' relation type are blocked by the
     production status-shape and relation-type CHECKs — those
     Inconsistent_data branches stay defensive and are not reachable
     without dropping production constraints. *)
  let q_pad_note =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects SET request_note = '  padded  ' \
     WHERE id = $1"

  let q_control_note =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects \
     SET request_note = 'phrv' || chr(1) || 'bad' WHERE id = $1"

  let q_clear_note =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects SET request_note = NULL WHERE id = $1"

  (* Test-only failure injection for the rollback case: an AFTER UPDATE
     trigger scoped to one reserved note value, so the failure fires only
     after the review update was genuinely attempted (the pending insert
     with the same note is untouched). Installed and dropped inside that
     case alone; production migrations are untouched. *)
  let phrv_poison_note = "phrv poison marker"

  let q_create_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE FUNCTION phrv_fail_update_fn() RETURNS trigger
     LANGUAGE plpgsql
     AS 'BEGIN RAISE EXCEPTION ''phrv fixture failure''; END'"

  let q_create_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE TRIGGER phrv_fail_update
     AFTER UPDATE ON community_projects
     FOR EACH ROW WHEN (NEW.request_note = 'phrv poison marker')
     EXECUTE FUNCTION phrv_fail_update_fn()"

  let q_drop_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP TRIGGER IF EXISTS phrv_fail_update ON community_projects"

  let q_drop_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP FUNCTION IF EXISTS phrv_fail_update_fn()"

  (* Each case gets a fresh connection and a clean fixture slate; cleanup
     runs again afterwards even when an assertion fails mid-way, and the
     connection is disconnected deterministically. *)
  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f conn))

  (* === call helpers === *)

  let review conn ~reviewer ~slug ~community decision =
    Rv.review conn ~reviewer_user_id:reviewer ~project_slug:slug
      ~target_community_slug:community ~decision

  let review_ok label expected conn ~reviewer ~slug ~community decision =
    let* r = review conn ~reviewer ~slug ~community decision in
    match r with
    | Ok reviewed ->
        Alcotest.(check string)
          (label ^ ": resulting status")
          (status_str expected)
          (status_str (Rv.resulting_status reviewed));
        Lwt.return_unit
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let review_expect label expected conn ~reviewer ~slug ~community decision
      =
    let* r = review conn ~reviewer ~slug ~community decision in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  (* Pending fixtures come only through the real request store and the
     real pure constructor. *)
  let request_ok label conn ~user ~slug ~community ?note () =
    let relation = phr_expect_ok (Phr.create_pending ~request_note:note) in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok created -> Lwt.return (Rq.relation_id created)
    | Error e -> Alcotest.failf "%s: %s" label (Phrq.error_str e)

  let add_role conn ~user ~community role =
    exec conn "role fixture" q_insert_moderator (user, community, role)

  let add_top_mod conn ~user ~community =
    add_role conn ~user ~community "top_mod"

  let relation_row = Phrq.relation_row
  let relation_sig conn id = find conn "relation sig" Phrq.q_relation_sig id
  let status_of conn id = find conn "status" q_status id

  let check_pending_unchanged label conn id before =
    let* after = relation_sig conn id in
    Alcotest.(check string) (label ^ ": relation unchanged") before after;
    Lwt.return_unit

  (* Mutation-first serialization: the second connection executes the
     durable mutation inside an open transaction (its row locks held),
     the review is launched against the main connection, and only then
     does the mutation commit — so the review can never observe the
     pre-mutation committed state and the outcome is deterministic
     without sleeps. *)
  let serialized_mutation_first conn2 ~mutate ~launch =
    let (module C2 : Caqti_lwt.CONNECTION) = conn2 in
    let* r = C2.start () in
    let* () = or_fail "second begin" r in
    let* () = mutate () in
    let review_promise = launch () in
    let* r = C2.commit () in
    let* () = or_fail "second commit" r in
    review_promise

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "review: invalid inputs rejected before any SQL" (fun _conn ->
        (* A deliberately unusable connection: pure validation must
           return without touching it — were any SQL attempted, the
           result would be Storage_error (or a test-failing exception),
           never the expected input error. *)
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let expect label e ~reviewer ~slug ~community =
          review_expect label e dead ~reviewer ~slug ~community Rv.Accept
        in
        let* () =
          expect "user id 0" Rv.Invalid_user_id ~reviewer:0 ~slug:"phrv-a"
            ~community:"phrv-c"
        in
        let* () =
          expect "negative user id" Rv.Invalid_user_id ~reviewer:(-7)
            ~slug:"phrv-a" ~community:"phrv-c"
        in
        let* () =
          expect "user checked before slugs" Rv.Invalid_user_id ~reviewer:0
            ~slug:"NOT A SLUG" ~community:"also bad"
        in
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              expect "invalid project slug" Rv.Invalid_project_slug
                ~reviewer:1 ~slug:bad ~community:"phrv-c")
            [ ""
            ; "Phrv-Upper"
            ; "phrv slug"
            ; " phrv-a"
            ; "phrv-a "
            ; "phrv_a"
            ; "phrv/a"
            ; "-phrv"
            ; "phrv-"
            ; "phrv--a"
            ; String.make 81 'a'
            ]
        in
        let* () =
          expect "project slug checked before community slug"
            Rv.Invalid_project_slug ~reviewer:1 ~slug:"phrv--a"
            ~community:"also bad"
        in
        Lwt_list.iter_s
          (fun bad ->
            expect "invalid community slug" Rv.Invalid_community_slug
              ~reviewer:1 ~slug:"phrv-a" ~community:bad)
          [ ""
          ; "phrv c"
          ; " phrv-c"
          ; "phrv-c "
          ; "phrv/c"
          ; "phrv\tc"
          ; "phrv\nc"
          ; "phrv\x01c"
          ; "phrv\x7fc"
          ])

  (* === accept success === *)

  let accept_public_case =
    db_case "review: acceptance round-trips exactly on a public target"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600001L
            ~slug:"phrv-accept"
        in
        let* cid = insert_community conn "phrv-accept-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let note = "Prima riga — gi\xc3\xa0 discutiamo qui \xe2\x98\x95" in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-accept"
            ~community:cid ~note ()
        in
        let* project_before =
          find conn "project sig" Phrq.q_project_sig project
        in
        let* community_before =
          find conn "community sig" Phrq.q_community_sig cid
        in
        let* () =
          review_ok "accept" Phr.Accepted conn ~reviewer ~slug:"phrv-accept"
            ~community:"phrv-accept-home" Rv.Accept
        in
        let* ( ((rp, rc), (rtype, status))
             , ((req, rev), (stored_note, (_, has_removed, upd_ge))) ) =
          relation_row conn rid
        in
        Alcotest.(check int64) "same project fk" project rp;
        Alcotest.(check int) "same community fk" cid rc;
        Alcotest.(check string) "relation type home" "home" rtype;
        Alcotest.(check string) "status accepted" "accepted" status;
        Alcotest.(check (option int)) "requester preserved" (Some owner) req;
        Alcotest.(check (option int)) "exact reviewer stored"
          (Some reviewer) rev;
        Alcotest.(check (option string)) "note preserved byte-exact"
          (Some note) stored_note;
        Alcotest.(check bool) "removed_at NULL" false has_removed;
        Alcotest.(check bool) "updated_at coherent" true upd_ge;
        let* reviewed_present, reviewed_ge, upd_ge2 =
          find conn "review times" q_review_times rid
        in
        Alcotest.(check bool) "reviewed_at present" true reviewed_present;
        Alcotest.(check bool) "reviewed_at coherent" true reviewed_ge;
        Alcotest.(check bool) "updated_at still coherent" true upd_ge2;
        let* total = find conn "total" Phrq.q_count_for_project project in
        Alcotest.(check int) "exactly one relation row" 1 total;
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "exactly one accepted active home" 1 active;
        (* Reviewing grants and changes nothing else. *)
        let* project_after =
          find conn "project sig after" Phrq.q_project_sig project
        in
        let* community_after =
          find conn "community sig after" Phrq.q_community_sig cid
        in
        Alcotest.(check string) "project unchanged" project_before
          project_after;
        Alcotest.(check string) "community unchanged" community_before
          community_after;
        let* members = find conn "members" Phrq.q_count_members cid in
        Alcotest.(check int) "no membership created" 0 members;
        let* mods = find conn "moderators" Phrq.q_count_moderators cid in
        Alcotest.(check int) "moderator roster unchanged" 1 mods;
        let* role = find conn "role" q_role_sig (reviewer, cid) in
        Alcotest.(check string) "reviewer role unchanged" "top_mod" role;
        let* stewards =
          find conn "stewards" Phrq.q_count_stewards_for_project project
        in
        Alcotest.(check int) "stewardship unchanged" 1 stewards;
        Lwt.return_unit)

