        let* () =
          review_ok "second top mod rejects" Phr.Rejected conn
            ~reviewer:second_mod ~slug:"phrv-authority"
            ~community:"phrv-authority-home" Rv.Reject
        in
        (* A durable global administrator — neither member nor moderator
           of the target — may review. *)
        let* _rid =
          request_ok "pending 2" conn ~user:owner ~slug:"phrv-authority"
            ~community:cid ()
        in
        let* () =
          review_ok "durable admin rejects" Phr.Rejected conn
            ~reviewer:admin ~slug:"phrv-authority"
            ~community:"phrv-authority-home" Rv.Reject
        in
        (* The requester may review only through independently held
           target-community authority — here granted explicitly. *)
        let* () = add_top_mod conn ~user:owner ~community:cid in
        let* rid3 =
          request_ok "pending 3" conn ~user:owner ~slug:"phrv-authority"
            ~community:cid ()
        in
        let* () =
          review_ok "requester with own top-mod role accepts" Phr.Accepted
            conn ~reviewer:owner ~slug:"phrv-authority"
            ~community:"phrv-authority-home" Rv.Accept
        in
        let* _, ((req, rev), _) = relation_row conn rid3 in
        Alcotest.(check (option int)) "requester recorded" (Some owner) req;
        Alcotest.(check (option int)) "same user as durable reviewer"
          (Some owner) rev;
        Lwt.return_unit)

  let unauthorized_case =
    db_case "review: every insufficient authority collapses identically"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* member = insert_user conn "phrv_member" in
        let* outsider = insert_user conn "phrv_outsider" in
        let* low_mod = insert_user conn "phrv_lowmod" in
        let* legacy_mod = insert_user conn "phrv_legacymod" in
        let* other_mod = insert_user conn "phrv_othermod" in
        let* removed_mod = insert_user conn "phrv_removedmod" in
        let* downgraded = insert_user conn "phrv_downgraded" in
        let* adminish = insert_user conn "phrv_adminish" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600005L
            ~slug:"phrv-unauth"
        in
        let* cid = insert_community conn "phrv-unauth-home" in
        let* other_cid = insert_community conn "phrv-unauth-other" in
        let* () = exec conn "member" q_insert_member (member, cid) in
        let* () = add_role conn ~user:low_mod ~community:cid "mod" in
        let* () =
          add_role conn ~user:legacy_mod ~community:cid "legacy_mod"
        in
        let* () = add_top_mod conn ~user:other_mod ~community:other_cid in
        let* () = add_top_mod conn ~user:removed_mod ~community:cid in
        let* () =
          exec conn "remove role" q_remove_moderator (removed_mod, cid)
        in
        let* () = add_top_mod conn ~user:downgraded ~community:cid in
        let* () =
          exec conn "downgrade role" q_set_moderator_role
            (downgraded, cid, "mod")
        in
        (* Session/admin-shaped without durable backing: nothing but the
           username suggests administration, and users.is_admin stays
           FALSE. *)
        let* () = exec conn "explicit non-admin" q_set_admin (adminish, false)
        in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-unauth"
            ~community:cid ()
        in
        let* before = relation_sig conn rid in
        let expect label reviewer decision =
          review_expect label Rv.Reviewer_unauthorized conn ~reviewer
            ~slug:"phrv-unauth" ~community:"phrv-unauth-home" decision
        in
        (* The requester is also creator and steward — none of that
           grants community authority. *)
        let* () = expect "requester/creator/steward" owner Rv.Accept in
        let* () = expect "requester/creator/steward reject" owner Rv.Reject
        in
        let* () = expect "ordinary member" member Rv.Accept in
        let* () = expect "non-member" outsider Rv.Accept in
        let* () = expect "lower moderator role" low_mod Rv.Accept in
        let* () = expect "legacy moderator role" legacy_mod Rv.Accept in
        let* () = expect "moderator of another community" other_mod
            Rv.Accept
        in
        let* () = expect "removed moderator" removed_mod Rv.Accept in
        let* () = expect "downgraded moderator" downgraded Rv.Accept in
        let* () = expect "admin-shaped without durable flag" adminish
            Rv.Accept
        in
        let* () = check_pending_unchanged "after all refusals" conn rid
            before
        in
        let* status = status_of conn rid in
        Alcotest.(check string) "still pending" "pending" status;
        Lwt.return_unit)

  (* === project availability === *)

  let project_unavailable_case =
    db_case
      "review: acceptance needs verification; refusals collapse identically"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600006L
            ~slug:"phrv-project"
        in
        let* cid = insert_community conn "phrv-project-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-project"
            ~community:cid ()
        in
        let* before = relation_sig conn rid in
        let expect label slug decision =
          review_expect label Rv.Project_unavailable conn ~reviewer ~slug
            ~community:"phrv-project-home" decision
        in
        (* Missing project: canonical grammar, nothing stored under it,
           refused for both decisions. *)
        let* () = expect "missing project accept" "phrv-absent" Rv.Accept in
        let* () = expect "missing project reject" "phrv-absent" Rv.Reject in
        (* Stale, then revoked verification: acceptance refused through
           the exact same collapsed variant as a missing project — the
           precise status is never distinguishable. *)
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* () = expect "stale project accept" "phrv-project" Rv.Accept in
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification
            (project, "revoked")
        in
        let* () = expect "revoked project accept" "phrv-project" Rv.Accept
        in
        let* () = check_pending_unchanged "after all refusals" conn rid
            before
        in
        let* status = status_of conn rid in
        Alcotest.(check string) "still pending" "pending" status;
        (* Restored verification accepts normally. *)
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        review_ok "restored project accepts" Phr.Accepted conn ~reviewer
          ~slug:"phrv-project" ~community:"phrv-project-home" Rv.Accept)

  let stale_revoked_rejection_case =
    db_case
      "review: rejection closes stale and revoked requests, freeing the slot"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600017L
            ~slug:"phrv-lost"
        in
        let* cid = insert_community conn "phrv-lost-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let note = "Nota conservata dopo la verifica" in
        (* Stale: the request predates the verification loss; rejection
           still closes it completely. *)
        let* rid1 =
          request_ok "pending" conn ~user:owner ~slug:"phrv-lost"
            ~community:cid ~note ()
        in
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* project_before =
          find conn "project sig" Phrq.q_project_sig project
        in
        let* () =
          review_ok "reject stale request" Phr.Rejected conn ~reviewer
            ~slug:"phrv-lost" ~community:"phrv-lost-home" Rv.Reject
        in
        let* ( (_, (_, status))
             , ((req, rev), (stored_note, (_, has_removed, _))) ) =
          relation_row conn rid1
        in
        Alcotest.(check string) "status rejected" "rejected" status;
        Alcotest.(check (option int)) "exact reviewer stored"
          (Some reviewer) rev;
        Alcotest.(check (option int)) "requester preserved" (Some owner)
          req;
        Alcotest.(check (option string)) "note preserved" (Some note)
          stored_note;
        Alcotest.(check bool) "removed_at NULL" false has_removed;
        let* reviewed_present, reviewed_ge, _ =
          find conn "review times" q_review_times rid1
        in
        Alcotest.(check bool) "reviewed_at present" true reviewed_present;
        Alcotest.(check bool) "reviewed_at coherent" true reviewed_ge;
        (* Rejection neither restores nor modifies project verification. *)
        let* project_after =
          find conn "project sig after" Phrq.q_project_sig project
        in
        Alcotest.(check string) "project still stale, untouched"
          project_before project_after;
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "active slot freed" 0 active;
        (* While stale, the request store still refuses a new request —
           the freed slot only becomes usable through reverification. *)
        let* r =
          Rq.create conn ~user_id:owner ~project_slug:"phrv-lost"
            ~target_community_id:cid ~relation:(phr_fresh_pending ())
        in
        let* () =
          match r with
          | Error Rq.Project_unavailable -> Lwt.return_unit
          | Ok _ -> Alcotest.fail "stale project submitted a new request"
          | Error e ->
              Alcotest.failf "stale re-request: %s" (Phrq.error_str e)
        in
        let* rejected_sig = relation_sig conn rid1 in
        (* Reverified: the freed slot admits a fresh request through the
           real request store; history stays untouched. *)
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        let* _rid2 =
          request_ok "fresh request after reverification" conn ~user:owner
            ~slug:"phrv-lost" ~community:cid ()
        in
        let* () =
          check_pending_unchanged "rejected history unchanged" conn rid1
            rejected_sig
        in
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "exactly one active relation" 1 active;
        (* Revoked: same closure path on the fresh pending request. *)
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification
            (project, "revoked")
        in
        let* () =
          review_expect "revoked accept refused" Rv.Project_unavailable
            conn ~reviewer ~slug:"phrv-lost" ~community:"phrv-lost-home"
            Rv.Accept
        in
        let* () =
          review_ok "reject revoked request" Phr.Rejected conn ~reviewer
            ~slug:"phrv-lost" ~community:"phrv-lost-home" Rv.Reject
        in
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "slot freed again" 0 active;
        (* And the slot reopens once more after reverification. *)
        let* () =
          exec conn "restore verified again" Phrq.q_set_verification
            (project, "verified")
        in
        let* _rid3 =
          request_ok "fresh request after revocation closure" conn
            ~user:owner ~slug:"phrv-lost" ~community:cid ()
        in
        let* total = find conn "total" Phrq.q_count_for_project project in
        Alcotest.(check int) "full history retained" 3 total;
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "exactly one active relation again" 1 active;
        Lwt.return_unit)

  (* === community availability and validation === *)

  let community_cases =
    db_case_lifecycle_relaxed "review: missing community and durable community corruption"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600007L
            ~slug:"phrv-community"
        in
        let* cid = insert_community conn "phrv-community-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-community"
            ~community:cid ()
        in
        let* before = relation_sig conn rid in
        (* Missing community: canonical slug, nothing stored under it. *)
        let* () =
          review_expect "missing community" Rv.Community_unavailable conn
            ~reviewer ~slug:"phrv-community" ~community:"phrv-nowhere"
            Rv.Accept
        in
        let expect_corrupt label =
          review_expect label Rv.Inconsistent_data conn ~reviewer
            ~slug:"phrv-community" ~community:"phrv-community-home"
            Rv.Accept
        in
        (* Structurally invalid durable shapes: an empty display name, a
           mixed published flag pair, a draft leaking through public
           listing, and a private community still discoverable. Each is
           restored before the next probe. *)
        (* The blank name is now barred by the scoped identity
           constraints; they are dropped for this probe alone and restored
           under Lwt.finalize once the name is canonical again. *)
        let* () = Ncid_relax.drop conn in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = exec conn "empty name" Phcv.q_set_name (cid, "") in
              expect_corrupt "empty community name")
            (fun () ->
              let* () =
                exec conn "restore name" Phcv.q_set_name
                  (cid, "phrv-community-home")
              in
              Ncid_relax.restore conn)
        in
        let* () = exec conn "mix flags" q_mix_flags cid in
        let* () = expect_corrupt "mixed publication flags" in
        let* () = exec conn "restore eligible" q_make_eligible cid in
        let* () = exec conn "leaky draft" q_leaky_draft cid in
        let* () = expect_corrupt "publicly listed draft" in
        let* () = exec conn "restore eligible" q_make_eligible cid in
        let* () = exec conn "leaky private" q_leaky_private cid in
        let* () = expect_corrupt "discoverable private community" in
        let* () = exec conn "restore eligible" q_make_eligible cid in
        let* () = check_pending_unchanged "after all causes" conn rid before
        in
        (* The restored community reviews normally. *)
        review_ok "restored community rejects" Phr.Rejected conn ~reviewer
          ~slug:"phrv-community" ~community:"phrv-community-home" Rv.Reject)

  (* === currently ineligible targets === *)

  let ineligible_target_case =
    db_case_lifecycle_relaxed
      "review: valid ineligible targets refuse acceptance, allow rejection"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600008L
            ~slug:"phrv-inelig"
        in
        let* cid = insert_community conn "phrv-inelig-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let drift =
          [ ("fully private", Phcv.q_make_private)
          ; ("setup draft", Phcv.q_make_draft_state)
          ; ("legacy non-network", Phcv.q_make_legacy)
          ]
        in
        Lwt_list.iter_s
          (fun (label, q_drift) ->
            (* Requests are created while the target is eligible — the
               drift happens afterwards, as in production. *)
            let* () = exec conn "restore eligible" q_make_eligible cid in
            let* rid =
              request_ok (label ^ ": pending") conn ~user:owner
                ~slug:"phrv-inelig" ~community:cid ()
            in
            let* () = exec conn (label ^ ": drift") q_drift cid in
            let* () =
              review_expect (label ^ ": accept refused")
                Rv.Target_ineligible conn ~reviewer ~slug:"phrv-inelig"
                ~community:"phrv-inelig-home" Rv.Accept
            in
            let* status = status_of conn rid in
            Alcotest.(check string) (label ^ ": still pending") "pending"
              status;
            let* () =
              review_ok (label ^ ": reject allowed") Phr.Rejected conn
                ~reviewer ~slug:"phrv-inelig"
                ~community:"phrv-inelig-home" Rv.Reject
            in
            let* status = status_of conn rid in
            Alcotest.(check string) (label ^ ": rejected") "rejected"
              status;
            Lwt.return_unit)
          drift)

  (* === review unavailable === *)

  let review_unavailable_case =
    db_case "review: every zero-row relation cause collapses identically"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600009L
            ~slug:"phrv-navail"
        in
        let* cid = insert_community conn "phrv-navail-home" in
        let* other_cid = insert_community conn "phrv-navail-other" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* () = add_top_mod conn ~user:reviewer ~community:other_cid in
        let expect label community =
          review_expect label Rv.Review_unavailable conn ~reviewer
            ~slug:"phrv-navail" ~community Rv.Accept
        in
        (* No relation at all. *)
        let* () = expect "no relation" "phrv-navail-home" in
        (* The pending request targets the other community. *)
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-navail"
            ~community:cid ()
        in
        let* () = expect "request targets another community"
            "phrv-navail-other"
        in
        (* Already accepted, and replay after a successful review. *)
        let* () =
          review_ok "accept" Phr.Accepted conn ~reviewer
            ~slug:"phrv-navail" ~community:"phrv-navail-home" Rv.Accept
        in
        let* () = expect "already accepted" "phrv-navail-home" in
        let* () =
          review_expect "reject replay after acceptance"
            Rv.Review_unavailable conn ~reviewer ~slug:"phrv-navail"
            ~community:"phrv-navail-home" Rv.Reject
        in
        (* Removed. *)
        let* () = exec conn "remove" Phrq.q_mark_removed rid in
        let* () = expect "removed relation" "phrv-navail-home" in
        (* Already rejected. *)
        let* _rid2 =
          request_ok "second pending" conn ~user:owner ~slug:"phrv-navail"
            ~community:cid ()
        in
        let* () =
          review_ok "reject" Phr.Rejected conn ~reviewer
            ~slug:"phrv-navail" ~community:"phrv-navail-home" Rv.Reject
        in
        let* () = expect "already rejected" "phrv-navail-home" in
        let* total = find conn "total" Phrq.q_count_for_project project in
        Alcotest.(check int) "exactly the two historical rows" 2 total;
        Lwt.return_unit)

  (* === durable pending corruption === *)

  let pending_corruption_case =
    db_case "review: malformed durable pending data is corruption"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600010L
            ~slug:"phrv-corrupt"
        in
        let* cid = insert_community conn "phrv-corrupt-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-corrupt"
            ~community:cid ()
        in
        (* A stored note outside the canonical shape cannot be
           reconstructed byte-exactly through the pure constructor. *)
        let* () = exec conn "pad note" q_pad_note rid in
        let* () =
          review_expect "non-canonical padded note" Rv.Inconsistent_data
            conn ~reviewer ~slug:"phrv-corrupt"
            ~community:"phrv-corrupt-home" Rv.Accept
        in
        let* () = exec conn "control-byte note" q_control_note rid in
        let* () =
          review_expect "forbidden control byte in note"
            Rv.Inconsistent_data conn ~reviewer ~slug:"phrv-corrupt"
            ~community:"phrv-corrupt-home" Rv.Accept
        in
        let* status = status_of conn rid in
        Alcotest.(check string) "still pending" "pending" status;
        (* A reviewer id, review timestamp, or removal timestamp on a
           pending row and a non-'home' relation type are blocked by the
           production status-shape and relation-type CHECKs; those
           validation branches stay defensive. *)
        let* () = exec conn "restore note" q_clear_note rid in
        review_ok "restored row reviews normally" Phr.Rejected conn
          ~reviewer ~slug:"phrv-corrupt" ~community:"phrv-corrupt-home"
          Rv.Reject)

  (* === concurrency === *)

  let concurrent_reviews_case =
    db_case "review: concurrent decisions leave exactly one durable review"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* r1 = insert_user conn "phrv_mod1" in
        let* r2 = insert_user conn "phrv_mod2" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600011L
            ~slug:"phrv-race"
        in
        let* cid = insert_community conn "phrv-race-home" in
        let* () = add_top_mod conn ~user:r1 ~community:cid in
        let* () = add_top_mod conn ~user:r2 ~community:cid in
        let go conn ~reviewer decision =
          review conn ~reviewer ~slug:"phrv-race"
            ~community:"phrv-race-home" decision
        in
        let one_winner label (ra, rb) =
          match (ra, rb) with
          | Ok w, Error Rv.Review_unavailable
          | Error Rv.Review_unavailable, Ok w ->
              w
          | Ok _, Ok _ -> Alcotest.failf "%s: both succeeded" label
          | Error a, Error b ->
              Alcotest.failf "%s: both failed (%s, %s)" label (error_str a)
                (error_str b)
          | Ok _, Error e | Error e, Ok _ ->
              Alcotest.failf "%s: unexpected loser error %s" label
                (error_str e)
        in
        Pod_store.with_second_connection (fun conn2 ->
            (* Same decision, two reviewers: accepted exactly once. *)
            let* rid =
              request_ok "pending" conn ~user:owner ~slug:"phrv-race"
                ~community:cid ()
            in
            let* results =
              Lwt.both
                (go conn ~reviewer:r1 Rv.Accept)
                (go conn2 ~reviewer:r2 Rv.Accept)
            in
            let w = one_winner "two accepts" results in
            Alcotest.(check string) "accepted result"
              (status_str Phr.Accepted)
              (status_str (Rv.resulting_status w));
            let* _, ((_, rev), _) = relation_row conn rid in
            Alcotest.(check bool) "one durable reviewer recorded" true
              (rev = Some r1 || rev = Some r2);
            let* status = status_of conn rid in
            Alcotest.(check string) "accepted once" "accepted" status;
            let* total =
              find conn "total" Phrq.q_count_for_project project
            in
            Alcotest.(check int) "no duplicate relation" 1 total;
            (* Same again for two rejections. *)
            let* () = exec conn "free slot" Phrq.q_mark_removed rid in
            let* rid2 =
              request_ok "second pending" conn ~user:owner
                ~slug:"phrv-race" ~community:cid ()
            in
            let* results =
              Lwt.both
                (go conn ~reviewer:r1 Rv.Reject)
                (go conn2 ~reviewer:r2 Rv.Reject)
            in
            let w = one_winner "two rejects" results in
            Alcotest.(check string) "rejected result"
              (status_str Phr.Rejected)
              (status_str (Rv.resulting_status w));
            let* status = status_of conn rid2 in
            Alcotest.(check string) "rejected once" "rejected" status;
            (* Opposite decisions: the final state is exactly the
               winner's, with the winner's reviewer. *)
            let* rid3 =
              request_ok "third pending" conn ~user:owner
                ~slug:"phrv-race" ~community:cid ()
            in
            let* ra, rb =
              Lwt.both
                (go conn ~reviewer:r1 Rv.Accept)
                (go conn2 ~reviewer:r2 Rv.Reject)
            in
            let expected_status, expected_reviewer =
              match (ra, rb) with
              | Ok w, Error Rv.Review_unavailable ->
                  (Rv.resulting_status w, r1)
              | Error Rv.Review_unavailable, Ok w ->
                  (Rv.resulting_status w, r2)
              | Ok _, Ok _ ->
                  Alcotest.fail "accept vs reject: both succeeded"
              | Error a, Error b ->
                  Alcotest.failf "accept vs reject: both failed (%s, %s)"
                    (error_str a) (error_str b)
              | Ok _, Error e | Error e, Ok _ ->
                  Alcotest.failf
                    "accept vs reject: unexpected loser error %s"
                    (error_str e)
            in
            let* _, ((_, rev), (_, (has_reviewed, has_removed, upd_ge))) =
              relation_row conn rid3
            in
            let* status = status_of conn rid3 in
            Alcotest.(check string) "winner's status durable"
              (status_str expected_status)
              status;
            Alcotest.(check (option int)) "winner's reviewer durable"
              (Some expected_reviewer) rev;
            Alcotest.(check bool) "reviewed_at present" true has_reviewed;
            Alcotest.(check bool) "removed_at NULL" false has_removed;
            Alcotest.(check bool) "no mixed timestamps" true upd_ge;
            Lwt.return_unit))

  (* === role-removal serialization === *)

  let role_removal_serialization_case =
    db_case "review: role removal serializes through the locked role row"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* admin = insert_user conn "phrv_admin" in
        let* () = exec conn "grant admin" q_set_admin (admin, true) in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600012L
            ~slug:"phrv-role"
        in
        let* cid = insert_community conn "phrv-role-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        (* Outcome 1: the review completes first; the later role removal
           cannot unwind the committed decision. *)
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-role"
            ~community:cid ()
        in
        let* () =
          review_ok "review before removal" Phr.Rejected conn ~reviewer
            ~slug:"phrv-role" ~community:"phrv-role-home" Rv.Reject
        in
        let* () =
          exec conn "remove role afterwards" q_remove_moderator
            (reviewer, cid)
        in
        let* status = status_of conn rid in
        Alcotest.(check string) "committed review stands" "rejected" status;
        (* Outcome 2: the removal's uncommitted row lock is held before
           the review starts, so the review serializes behind it and must
           see the removal. *)
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid2 =
          request_ok "second pending" conn ~user:owner ~slug:"phrv-role"
            ~community:cid ()
        in
        Pod_store.with_second_connection (fun conn2 ->
            let* r =
              serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "held removal" q_remove_moderator
                    (reviewer, cid))
                ~launch:(fun () ->
                  review conn ~reviewer ~slug:"phrv-role"
                    ~community:"phrv-role-home" Rv.Accept)
            in
            (match r with
            | Error Rv.Reviewer_unauthorized -> ()
            | Ok _ -> Alcotest.fail "removed-first review succeeded"
            | Error e ->
                Alcotest.failf "removed-first review: %s" (error_str e));
            let* status = status_of conn rid2 in
            Alcotest.(check string) "still pending after removal race"
              "pending" status;
            (* Downgrade instead of removal, same protocol. *)
            let* () = add_top_mod conn ~user:reviewer ~community:cid in
            let* r =
              serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "held downgrade" q_set_moderator_role
                    (reviewer, cid, "mod"))
                ~launch:(fun () ->
                  review conn ~reviewer ~slug:"phrv-role"
                    ~community:"phrv-role-home" Rv.Accept)
            in
            (match r with
            | Error Rv.Reviewer_unauthorized -> ()
            | Ok _ -> Alcotest.fail "downgraded-first review succeeded"
            | Error e ->
                Alcotest.failf "downgraded-first review: %s" (error_str e));
            (* Admin revocation serializes through the users row alike. *)
            let* r =
              serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "held revocation" q_set_admin (admin, false))
                ~launch:(fun () ->
                  review conn ~reviewer:admin ~slug:"phrv-role"
                    ~community:"phrv-role-home" Rv.Accept)
            in
            (match r with
            | Error Rv.Reviewer_unauthorized -> ()
            | Ok _ -> Alcotest.fail "revoked-first admin review succeeded"
            | Error e ->
                Alcotest.failf "revoked-first admin review: %s"
                  (error_str e));
            let* status = status_of conn rid2 in
            Alcotest.(check string) "still pending after all races"
              "pending" status;
            (* No deadlock residue: a re-qualified reviewer completes. *)
            let* () =
              exec conn "requalify" q_set_moderator_role
                (reviewer, cid, "top_mod")
            in
            review_ok "requalified reviewer rejects" Phr.Rejected conn
              ~reviewer ~slug:"phrv-role" ~community:"phrv-role-home"
              Rv.Reject))

  (* === community-lifecycle serialization === *)

  let lifecycle_serialization_case =
    db_case_lifecycle_relaxed "review: lifecycle change serializes through the community lock"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600013L
            ~slug:"phrv-lifecycle"
        in
        let* cid = insert_community conn "phrv-lifecycle-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        (* Outcome 1: acceptance locks the eligible state first and
           commits; the later privacy change cannot unwind it. *)
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-lifecycle"
            ~community:cid ()
        in
        let* () =
          review_ok "accept before drift" Phr.Accepted conn ~reviewer
            ~slug:"phrv-lifecycle" ~community:"phrv-lifecycle-home"
            Rv.Accept
        in
        let* () = exec conn "drift afterwards" Phcv.q_make_private cid in
        let* status = status_of conn rid in
        Alcotest.(check string) "committed acceptance stands" "accepted"
          status;
        (* Outcome 2: the lifecycle mutation's uncommitted community lock
           is held before the review starts. *)
        let* () = exec conn "restore eligible" q_make_eligible cid in
        let* () = exec conn "free slot" Phrq.q_mark_removed rid in
        let* rid2 =
          request_ok "second pending" conn ~user:owner
            ~slug:"phrv-lifecycle" ~community:cid ()
        in
        Pod_store.with_second_connection (fun conn2 ->
            let* r =
              serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "held privacy change" Phcv.q_make_private cid)
                ~launch:(fun () ->
                  review conn ~reviewer ~slug:"phrv-lifecycle"
                    ~community:"phrv-lifecycle-home" Rv.Accept)
            in
            (match r with
            | Error Rv.Target_ineligible -> ()
            | Ok _ -> Alcotest.fail "drift-first acceptance succeeded"
            | Error e ->
                Alcotest.failf "drift-first acceptance: %s" (error_str e));
            let* status = status_of conn rid2 in
            Alcotest.(check string) "still pending after drift race"
              "pending" status;
            (* Either serialized order still permits rejection. *)
            review_ok "reject the now-private target" Phr.Rejected conn
              ~reviewer ~slug:"phrv-lifecycle"
              ~community:"phrv-lifecycle-home" Rv.Reject))

  (* === project-verification serialization === *)

  let verification_serialization_case =
    db_case "review: verification change serializes through the project lock"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600014L
            ~slug:"phrv-verif"
        in
        let* cid = insert_community conn "phrv-verif-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        (* Outcome 1: the review locks the verified project first and
           commits; the later staleness cannot unwind it. *)
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-verif"
            ~community:cid ()
        in
        let* () =
          review_ok "review before staleness" Phr.Rejected conn ~reviewer
            ~slug:"phrv-verif" ~community:"phrv-verif-home" Rv.Reject
        in
        let* () =
          exec conn "stale afterwards" Phrq.q_set_verification
            (project, "stale")
        in
        let* status = status_of conn rid in
        Alcotest.(check string) "committed review stands" "rejected" status;
        (* Outcome 2: the verification mutation's uncommitted project
           lock is held before the review starts. *)
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        let* rid2 =
          request_ok "second pending" conn ~user:owner ~slug:"phrv-verif"
            ~community:cid ()
        in
        Pod_store.with_second_connection (fun conn2 ->
            let* r =
              serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "held staleness" Phrq.q_set_verification
                    (project, "stale"))
                ~launch:(fun () ->
                  review conn ~reviewer ~slug:"phrv-verif"
                    ~community:"phrv-verif-home" Rv.Accept)
            in
            (match r with
            | Error Rv.Project_unavailable -> ()
            | Ok _ -> Alcotest.fail "stale-first acceptance succeeded"
            | Error e ->
                Alcotest.failf "stale-first acceptance: %s" (error_str e));
            let* status = status_of conn rid2 in
            Alcotest.(check string) "still pending after staleness race"
              "pending" status;
            (* Rejection succeeds even when a further verification loss —
               here stale → revoked — commits first under the same held
               project lock: the pending request can always be closed. *)
            let* r =
              serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "held revocation" Phrq.q_set_verification
                    (project, "revoked"))
                ~launch:(fun () ->
                  review conn ~reviewer ~slug:"phrv-verif"
                    ~community:"phrv-verif-home" Rv.Reject)
            in
            (match r with
            | Ok w ->
                Alcotest.(check string) "revoked-first rejection result"
                  (status_str Phr.Rejected)
                  (status_str (Rv.resulting_status w))
            | Error e ->
                Alcotest.failf "revoked-first rejection: %s" (error_str e));
            let* _, ((_, rev), _) = relation_row conn rid2 in
            let* status = status_of conn rid2 in
            Alcotest.(check string) "rejected despite revocation"
              "rejected" status;
            Alcotest.(check (option int)) "reviewer recorded"
              (Some reviewer) rev;
            Lwt.return_unit))

  (* === failure rollback === *)

  let rollback_case =
    db_case "review: injected update failure leaves the pending row intact"
      (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945600015L
            ~slug:"phrv-fail"
        in
        let* cid = insert_community conn "phrv-fail-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_ok "poisoned pending" conn ~user:owner ~slug:"phrv-fail"
            ~community:cid ~note:phrv_poison_note ()
        in
        let* before = relation_sig conn rid in
        let exec_ddl label q =
          let* r = C.exec q () in
          let* () = or_fail label r in
          Lwt.return_unit
        in
        let* () = exec_ddl "pre-drop trigger" q_drop_fail_trigger in
        let* () = exec_ddl "pre-drop function" q_drop_fail_fn in
        let* () = exec_ddl "create function" q_create_fail_fn in
        let* () = exec_ddl "create trigger" q_create_fail_trigger in
        Lwt.finalize
          (fun () ->
            let* () =
              review_expect "poisoned review" Rv.Storage_error conn
                ~reviewer ~slug:"phrv-fail" ~community:"phrv-fail-home"
                Rv.Accept
            in
            let* () =
              check_pending_unchanged "after injected failure" conn rid
                before
            in
            let* status = status_of conn rid in
            Alcotest.(check string) "still pending" "pending" status;
            let* members = find conn "members" Phrq.q_count_members cid in
            Alcotest.(check int) "no membership side effect" 0 members;
            let* mods = find conn "moderators" Phrq.q_count_moderators cid
            in
            Alcotest.(check int) "moderator roster untouched" 1 mods;
            let* stewards =
              find conn "stewards" Phrq.q_count_stewards_for_project
                project
            in
            Alcotest.(check int) "stewardship untouched" 1 stewards;
            Lwt.return_unit)
          (fun () ->
            let* () = exec_ddl "drop trigger" q_drop_fail_trigger in
            exec_ddl "drop function" q_drop_fail_fn))

  (* === credential and privacy sweep === *)

  let privacy_case =
    db_case "review: no credential fixture reaches the reviewed row"
      (fun conn ->
        let* owner = insert_user conn "phrv_owner" in
        let* reviewer = insert_user conn "phrv_mod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945600016L
            ~slug:"phrv-creds"
        in
        let* cid = insert_community conn "phrv-creds-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let credentials =
          [ "phrv-access-token-A1x"
          ; "phrv-refresh-token-B2x"
          ; "phrv-authorization-code-C3x"
          ; "phrv-pkce-verifier-D4x"
          ; "phrv-client-secret-E5x"
          ; "phrv-oauth-state-F6x"
          ; "phrv-session-binding-G7x"
          ; "945600999" (* installation id fixture *)
          ; "945700999" (* account id fixture *)
          ; "946099999" (* repository id fixture *)
          ; "phrv-private-repo-name-H8x"
          ; "phrv-private-repo-desc-I9x"
          ]
        in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrv-creds"
            ~community:cid ~note:"Ordinary private note." ()
        in
        let* () =
          review_ok "accept" Phr.Accepted conn ~reviewer
            ~slug:"phrv-creds" ~community:"phrv-creds-home" Rv.Accept
        in
        let* blob = find conn "row blob" Phrq.q_relation_text_blob rid in
        List.iter
          (fun credential ->
            Alcotest.(check bool) "credential absent from reviewed row"
              false
              (contains ~needle:credential blob))
          credentials;
        (* A credential-shaped value deliberately supplied as the note is
           legitimate there — and only there, surviving review
           untouched. *)
        let* () = exec conn "free slot" Phrq.q_mark_removed rid in
        let deliberate = List.hd credentials in
        let* rid2 =
          request_ok "deliberate note" conn ~user:owner ~slug:"phrv-creds"
            ~community:cid ~note:deliberate ()
        in
        let* () =
          review_ok "reject deliberate note" Phr.Rejected conn ~reviewer
            ~slug:"phrv-creds" ~community:"phrv-creds-home" Rv.Reject
        in
        let* _, (_, (stored_note, _)) = relation_row conn rid2 in
        Alcotest.(check bool) "deliberate note preserved verbatim" true
          (stored_note = Some deliberate);
        let* nonnote =
          find conn "non-note blob" Phrq.q_relation_nonnote_blob rid2
        in
        Alcotest.(check bool) "note value nowhere else in the row" false
          (contains ~needle:deliberate nonnote);
        Lwt.return_unit)

  let suite =
    [ pure_inputs_case; accept_public_case; accept_unlisted_case;
      reject_case; authority_variants_case; unauthorized_case;
      project_unavailable_case; stale_revoked_rejection_case;
      community_cases; ineligible_target_case;
      review_unavailable_case; pending_corruption_case;
      concurrent_reviews_case; role_removal_serialization_case;
      lifecycle_serialization_case; verification_serialization_case;
      rollback_case; privacy_case ]
end

(* ===== Moderator review page (Project_home_review_pages) =====
   Pure rendering over handler-supplied view models; DB-free. No GitHub,
   installation, repository external id, or credential fixtures exist
   anywhere here. Fragment-scoped assertions pin only what the feature
   templates introduce inside the shared create-shell layout. *)

module Phrp = Earde.Project_home_review_pages

let phrp_case name f = Alcotest.test_case name `Quick f

let phrp_repo ?(full_name = "octo-org/widgets")
    ?(url = "https://github.com/octo-org/widgets") ?(primary = false)
    ?(archived = false) () : Phrp.repository =
  { Phrp.full_name; html_url = url; is_primary = primary; is_archived = archived }

let phrp_request ?(name = "Widget Kit") ?(slug = "widget-kit")
    ?(kind = Pi.Project) ?(login = "octo-org")
    ?(verification = Phrp.Verified) ?repositories ?requester ?note () :
    Phrp.pending_request =
  { Phrp.project_name = name; project_slug = slug; project_kind = kind;
    namespace_login = login; verification;
    repositories =
      (match repositories with Some r -> r | None -> [ phrp_repo ~primary:true () ]);
    requester_name = requester; request_note = note }

let phrp_community ?(name = "Alpine Devs") ?(slug = "alpine")
    ?(eligibility = Phrp.Eligible) () : Phrp.community =
  { Phrp.name; slug; host_eligibility = eligibility }

let phrp_state ?community ?(requests = [ phrp_request () ]) () : Phrp.state =
  { Phrp.community =
      (match community with Some c -> c | None -> phrp_community ());
    requests }

let phrp_render ?user ?(feedback = None) state =
  Phrp.project_home_review_page ?user ~state ~feedback ()

let phrp_frag ?user ?feedback state =
  ps_fragment (phrp_render ?user ?feedback state)

let phrp_content_cases =
  [ phrp_case "empty queue renders copy and no forms" (fun () ->
        let frag = phrp_frag (phrp_state ~requests:[] ()) in
        ps_must frag "Project home requests";
        ps_must frag "Review projects requesting this community";
        ps_must frag "No pending project requests.";
        Alcotest.(check int) "no forms" 0 (ps_count frag "<form"))
  ; phrp_case "verified request: identity, kind, namespace, verification, \
               factual copy" (fun () ->
        let frag = phrp_frag (phrp_state ()) in
        ps_must frag "Widget Kit";
        ps_must frag "phrv-project-kind'>Project<";
        ps_must frag "octo-org";
        ps_must frag "phrv-verification'>Verified<";
        ps_must frag "Project connected through GitHub";
        ps_must_not frag "Official";
        ps_must_not frag "GitHub-approved";
        ps_must_not frag "GitHub-endorsed";
        ps_must_not frag "member";
        ps_must_not frag "karma";
        ps_must_not frag "relation_id";
        ps_must_not frag "project_id";
        ps_must_not frag "community_id")
  ; phrp_case "stale and revoked verification copy stays distinct" (fun () ->
        let stale =
          phrp_frag
            (phrp_state ~requests:[ phrp_request ~verification:Phrp.Stale () ] ())
        in
        ps_must stale "Verification stale";
        let revoked =
          phrp_frag
            (phrp_state
               ~requests:[ phrp_request ~verification:Phrp.Revoked () ] ())
        in
        ps_must revoked "Verification revoked")
  ; phrp_case "public repository links and primary/archived markers, in order"
      (fun () ->
        let repos =
          [ phrp_repo ~full_name:"octo-org/core"
              ~url:"https://github.com/octo-org/core" ~primary:true ()
          ; phrp_repo ~full_name:"octo-org/docs"
              ~url:"https://github.com/octo-org/docs" ~archived:true () ]
        in
        let frag =
          phrp_frag (phrp_state ~requests:[ phrp_request ~repositories:repos () ] ())
        in
        ps_must frag "href='https://github.com/octo-org/core'";
        ps_must frag "octo-org/core";
        ps_must frag "octo-org/docs";
        ps_must frag ">Primary<";
        ps_must frag ">Archived<";
        ps_order frag "octo-org/core" "octo-org/docs")
  ; phrp_case "deleted requester copy; present requester escaped" (fun () ->
        let deleted =
          phrp_frag (phrp_state ~requests:[ phrp_request () ] ())
        in
        ps_must deleted "Requested by Deleted user";
        let named =
          phrp_frag
            (phrp_state ~requests:[ phrp_request ~requester:"a<lice" () ] ())
        in
        ps_must named "Requested by a&lt;lice";
        ps_must_not named "a<lice")
  ; phrp_case "private note is labelled, escaped, never markup" (fun () ->
        let frag =
          phrp_frag
            (phrp_state
               ~requests:
                 [ phrp_request
                     ~note:"<script>alert('x')</script> & <b>b</b>" () ]
               ())
        in
        ps_must frag "Private request note";
        ps_must frag "visible only to";
        ps_must frag
          "&lt;script&gt;alert(&#39;x&#39;)&lt;/script&gt; &amp; \
           &lt;b&gt;b&lt;/b&gt;";
        ps_must_not frag "<script>alert";
        ps_must_not frag "<b>b</b>";
        let none =
          phrp_frag (phrp_state ~requests:[ phrp_request () ] ())
        in
        ps_must_not none "Private request note")
  ; phrp_case "no scripts, inline styles, handlers, javascript urls, or \
               credential material" (fun () ->
        let frag =
          phrp_frag
            (phrp_state ~requests:[ phrp_request ~note:"hi" () ] ())
        in
        ps_must_not frag "<script";
        ps_must_not frag "style=";
        ps_must_not frag "onclick";
        ps_must_not frag "onsubmit";
        ps_must_not frag "javascript:";
        ps_must_not frag "token";
        ps_must_not frag "installation";
        ps_must_not frag "secret")
  ]

let phrp_form_cases =
  [ phrp_case "exact accept and reject actions, nameless submit, zero \
               application fields" (fun () ->
        let frag = phrp_frag (phrp_state ()) in
        Alcotest.(check int) "two forms" 2 (ps_count frag "<form");
        ps_must frag "action='/c/alpine/projects/widget-kit/accept'";
        ps_must frag "action='/c/alpine/projects/widget-kit/reject'";
        ps_must frag ">Accept as community home<";
        ps_must frag ">Reject request<";
        (* No application field and no framework field without a request. *)
        Alcotest.(check int) "no name attributes" 0 (ps_count frag "name=");
        ps_must_not frag "type='hidden'";
        ps_must_not frag "value=";
        ps_must_not frag "disabled")
  ; phrp_case "accept only for Verified + Eligible; rejection always present"
      (fun () ->
        let no_accept label state =
          let frag = phrp_frag state in
          Alcotest.(check int) (label ^ ": one form only") 1
            (ps_count frag "<form");
          ps_must_not frag "/accept'";
          ps_must frag "/reject'";
          ps_must frag "Acceptance is unavailable for this request."
        in
        no_accept "stale"
          (phrp_state ~requests:[ phrp_request ~verification:Phrp.Stale () ] ());
        no_accept "revoked"
          (phrp_state
             ~requests:[ phrp_request ~verification:Phrp.Revoked () ] ());
        no_accept "ineligible community"
          (phrp_state
             ~community:
               (phrp_community ~eligibility:Phrp.Currently_ineligible ())
             ());
        let ok = phrp_frag (phrp_state ()) in
        ps_must ok "/accept'";
        ps_must_not ok "Acceptance is unavailable")
  ; phrp_case "ineligible community: page notice and every accept suppressed"
      (fun () ->
        let frag =
          phrp_frag
            (phrp_state
               ~community:
                 (phrp_community ~eligibility:Phrp.Currently_ineligible ())
               ~requests:
                 [ phrp_request ~slug:"one" (); phrp_request ~slug:"two" () ]
               ())
        in
        ps_must frag
          "This community cannot currently accept project-home requests.";
        Alcotest.(check int) "no accept actions" 0 (ps_count frag "/accept'");
        Alcotest.(check int) "two reject actions" 2 (ps_count frag "/reject'"))
  ; phrp_case "empty repository list suppresses acceptance, keeps rejection"
      (fun () ->
        let frag =
          phrp_frag (phrp_state ~requests:[ phrp_request ~repositories:[] () ] ())
        in
        ps_must_not frag "/accept'";
        ps_must frag "/reject'";
        ps_must frag "Acceptance is unavailable for this request.";
        ps_must frag "No repositories.")
  ]

let phrp_defensive_cases =
