          phrp_frag (phrp_state ~community:(phrp_community ~slug:"bad slug" ()) ())
        in
        Alcotest.(check int) "no forms" 0 (ps_count frag "<form");
        (* Identity still renders — only the actions drop. *)
        ps_must frag "Widget Kit")
  ; phrp_case "invalid project slug suppresses only that request's forms"
      (fun () ->
        let frag =
          phrp_frag
            (phrp_state
               ~requests:
                 [ phrp_request ~name:"Bad One" ~slug:"Bad--Slug" ()
                 ; phrp_request ~name:"Good One" ~slug:"good-one" () ]
