let phrp_feedback_cases =
  [ phrp_case "each feedback variant renders its generic copy" (fun () ->
        List.iter
          (fun (fb, needle) ->
            let frag = phrp_frag ~feedback:(Some fb) (phrp_state ()) in
            ps_must frag "phrv-alert";
            ps_must frag needle)
          [ (Phrp.Stale_form, "This page had been open too long")
          ; (Phrp.Review_unavailable, "no longer pending")
          ; (Phrp.Project_unavailable, "no longer available for acceptance")
          ; (Phrp.Target_ineligible, "cannot currently accept that project")
          ; (Phrp.Review_failed, "couldn't review the request") ])
  ; phrp_case "no feedback renders no alert; feedback is cosmetic" (fun () ->
        ps_must_not (phrp_frag (phrp_state ())) "phrv-alert";
        let with_fb =
          phrp_frag ~feedback:(Some Phrp.Review_failed) (phrp_state ())
        in
        Alcotest.(check int) "forms unchanged by feedback" 2
          (ps_count with_fb "<form"))
  ]

(* --- Page rendering with a live request: the framework CSRF field. --- *)

let phrp_csrf_render state =
  let captured = ref None in
  let pipeline =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    captured :=
      Some (Phrp.project_home_review_page ~request:req ~state ~feedback:None ());
    Dream.html ""
  in
  ignore
    (Lwt_main.run
       (pipeline
          (Dream.request ~method_:`GET ~target:"/c/alpine/review" "")));
  match !captured with
  | Some html -> html
  | None -> Alcotest.fail "renderer did not run"

let phrp_csrf_cases =
  [ phrp_case "with request: one framework field per form, hidden, no \
               application field" (fun () ->
        let frag = ps_fragment (phrp_csrf_render (phrp_state ())) in
        Alcotest.(check int) "two framework fields" 2
          (ps_count frag "name=\"dream.csrf\"");
        Alcotest.(check int) "two hidden framework fields" 2
          (ps_count frag "type=\"hidden\"");
        Alcotest.(check int) "no application hidden field" 0
          (ps_count frag "type='hidden'");
        (* The framework fields are the only name= attributes. *)
        Alcotest.(check int) "only framework name attrs" 2
          (ps_count frag "name="))
  ; phrp_case "form-free states emit no framework field even with a request"
      (fun () ->
        ps_must_not
          (ps_fragment (phrp_csrf_render (phrp_state ~requests:[] ())))
          "dream.csrf";
        ps_must_not
          (ps_fragment
             (phrp_csrf_render
                (phrp_state ~community:(phrp_community ~slug:"bad slug" ()) ())))
          "dream.csrf")
  ; phrp_case "pure rendering without a request stays CSRF-free" (fun () ->
        ps_must_not (phrp_frag (phrp_state ())) "dream.csrf")
  ]

(* === Project home review read model (Project_home_review_read_model) ===
   Moderator-authorized view of the pending home-request queue for one
   community, driven over verified permanent projects built through the real
   draft/selection/finalization chain and pending relations written by the
   real request store. Database-gated (EARDE_TEST_DATABASE_URL, same opt-in
   as Mod_scope) with its own reserved external-installation-id range
   945800001..945800999 (hence account ids 945900001..945900999, which also
   scope the permanent-project cleanup), phrr_% usernames, and phrr-%
   community slugs so no suite shares fixtures. Pure validation is proven
   pre-SQL against a deliberately disconnected connection. Authorization uses
   only the real durable rows: community_moderators role 'top_mod' and
   users.is_admin. Every per-case wrapper disconnects deterministically. *)
module Phrr = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rv = Earde.Project_home_review_read_model
  module Rq = Earde.Project_home_request_store
  module Fin = Earde.Project_finalization_store

  let error_str : Rv.error -> string = function
    | Rv.Invalid_user_id -> "Invalid_user_id"
    | Rv.Invalid_community_slug -> "Invalid_community_slug"
    | Rv.Inconsistent_data -> "Inconsistent_data"
    | Rv.Storage_error -> "Storage_error"

  let verification_str : Rv.project_verification -> string = function
    | Rv.Verified -> "verified"
    | Rv.Stale -> "stale"
    | Rv.Revoked -> "revoked"

  let eligibility_str : Rv.host_eligibility -> string = function
    | Rv.Eligible -> "eligible"
    | Rv.Currently_ineligible -> "ineligible"

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let make_project = Phrq.make_project
  let insert_community = Phcv.insert_community

  (* Same dependency order as the sibling suites; the LIKE pattern also
     catches deliberately corrupted phrr- slugs. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 945900001 AND 945900999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 945900001 AND 945900999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 945800001 AND 945800999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phrr-%'"
      ; "DELETE FROM users WHERE username LIKE 'phrr_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 945800001 AND 945800999"
      ]

  (* Durable authorization fixtures — the real rows the read model reads. *)
  let q_insert_moderator =
    (Caqti_type.(t3 int int string) ->. Caqti_type.unit)
    "INSERT INTO community_moderators (user_id, community_id, role) \
     VALUES ($1, $2, $3)"

  let q_remove_moderator =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
    "DELETE FROM community_moderators WHERE user_id = $1 AND community_id = $2"

  let q_set_moderator_role =
    (Caqti_type.(t3 int int string) ->. Caqti_type.unit)
    "UPDATE community_moderators SET role = $3 \
     WHERE user_id = $1 AND community_id = $2"

  let q_insert_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
    "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  let q_set_admin =
    (Caqti_type.(t2 int bool) ->. Caqti_type.unit)
    "UPDATE users SET is_admin = $2 WHERE id = $1"

  let q_delete_user =
    (Caqti_type.int ->. Caqti_type.unit)
    "DELETE FROM users WHERE id = $1"

  (* Deterministic queue ordering: creation time is a NOW() default, so it
     is pinned directly (a past value keeps updated_at >= created_at). *)
  let q_set_created_at =
    (Caqti_type.(t2 int64 string) ->. Caqti_type.unit)
    "UPDATE community_projects \
     SET created_at = $2::timestamptz, updated_at = NOW() WHERE id = $1"

  (* Targeted durable corruption. request_note carries only a length CHECK,
     so a padded (non-canonical) note and a forbidden control byte are both
     directly representable. *)
  let q_pad_note =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects SET request_note = '  padded  ' WHERE id = $1"

  let q_control_note =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE community_projects \
     SET request_note = 'phrr' || chr(1) || 'bad' WHERE id = $1"

  (* forge_namespace_login only CHECKs btrim<>'' and length, so a control
     byte is directly representable and fails the addressable-segment rule. *)
  let q_corrupt_login =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET forge_namespace_login = 'phrr' || chr(1) || 'bad' WHERE id = $1"

  let q_restore_login =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET forge_namespace_login = 'pfin-owner' WHERE id = $1"

  (* html_url only CHECKs btrim<>'', so a non-canonical URL is directly
     representable and fails the structured reconstruction. *)
  let q_corrupt_repo_url =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE project_repositories \
     SET html_url = 'https://evil.example/x' WHERE project_id = $1"

  let q_restore_repo_url =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE project_repositories \
     SET html_url = 'https://github.com/pfin-owner/alpha' WHERE project_id = $1"

  let q_delete_repos =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM project_repositories WHERE project_id = $1"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f conn))

  (* === call helpers === *)

  let load conn ~reviewer ~community =
    Rv.load_for_reviewer conn ~reviewer_user_id:reviewer
      ~community_slug:community

  let load_view label conn ~reviewer ~community =
    let* r = load conn ~reviewer ~community in
    match r with
    | Ok (Some view) -> Lwt.return view
    | Ok None -> Alcotest.failf "%s: unexpectedly absent" label
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_none label conn ~reviewer ~community =
    let* r = load conn ~reviewer ~community in
    match r with
    | Ok None -> Lwt.return_unit
    | Ok (Some _) -> Alcotest.failf "%s: unexpectedly present" label
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_expect label expected conn ~reviewer ~community =
    let* r = load conn ~reviewer ~community in
    match r with
    | Ok None -> Alcotest.failf "%s: expected %s, got Ok None" label (error_str expected)
    | Ok (Some _) -> Alcotest.failf "%s: expected %s, got Ok Some" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  (* Pending relations come only through the real transactional store. *)
  let request_ok label conn ~user ~slug ~community ?note () =
    let relation = phr_expect_ok (Phr.create_pending ~request_note:note) in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok created -> Lwt.return (Rq.relation_id created)
    | Error e -> Alcotest.failf "%s: %s" label (Phrq.error_str e)

  let add_role conn ~user ~community role =
    exec conn "role fixture" q_insert_moderator (user, community, role)

  let add_top_mod conn ~user ~community =
    add_role conn ~user ~community "top_mod"

  (* A two-repository verified project through the same real chain, for the
     repository ordering assertion. *)
  let make_project2 conn ~user ~ext_id ~slug =
    let base = Int64.add ext_id 400000L in
    let* _inst, draft, _, _ =
      Pfin.make_draft conn ~user ~ext_id (fun account_id ->
          [ Pfin.repo ~account_id ~id:base "alpha"
          ; Pfin.repo ~account_id ~id:(Int64.add base 1L) "beta" ])
    in
    let* ids = Pfin.snapshot_ids conn draft in
    let s1 = List.nth ids 0 and s2 = List.nth ids 1 in
    let* () =
      Pod_select.replace_ok "seed selection" conn ~user ~draft ~primary:s1
        [ s1; s2 ]
    in
    let identity =
      Pfin.identity_exn ~slug ~selected:[ s1; s2 ] ~primary:s1 ()
    in
    let* created = Pfin.finalize_ok "fixture project" conn ~user ~draft identity in
    Lwt.return (Fin.project_id created)

  let expect_one label conn ~reviewer ~community ~slug =
    let* view = load_view label conn ~reviewer ~community in
    let requests = Rv.pending_requests view in
    Alcotest.(check int) (label ^ ": one request") 1 (List.length requests);
    Alcotest.(check string) (label ^ ": project slug") slug
      (Rv.project_slug (List.hd requests));
    Lwt.return_unit

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "review read: invalid inputs rejected before any SQL"
      (fun _conn ->
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let expect label e ~reviewer ~community =
          load_expect label e dead ~reviewer ~community
        in
        let* () = expect "user id 0" Rv.Invalid_user_id ~reviewer:0 ~community:"phrr-c" in
        let* () =
          expect "negative user id" Rv.Invalid_user_id ~reviewer:(-7)
            ~community:"phrr-c"
        in
        let* () =
          expect "user checked before community slug" Rv.Invalid_user_id
            ~reviewer:0 ~community:"also bad"
        in
        Lwt_list.iter_s
          (fun bad ->
            expect "invalid community slug" Rv.Invalid_community_slug
              ~reviewer:1 ~community:bad)
          [ ""
          ; "phrr c"
          ; " phrr-c"
          ; "phrr-c "
          ; "phrr/c"
          ; "phrr\tc"
          ; "phrr\nc"
          ; "phrr\x01c"
          ; "phrr\x7fc"
          ])

  (* === authorization === *)

  let authorization_case =
    db_case "review read: durable top-mod/admin authorize, all else absent"
      (fun conn ->
        let* owner = insert_user conn "phrr_owner" in
        let* mod1 = insert_user conn "phrr_mod1" in
        let* mod2 = insert_user conn "phrr_mod2" in
        let* admin = insert_user conn "phrr_admin" in
        let* member = insert_user conn "phrr_member" in
        let* stranger = insert_user conn "phrr_stranger" in
        let* plain_mod = insert_user conn "phrr_plainmod" in
        let* legacy = insert_user conn "phrr_legacy" in
        let* other = insert_user conn "phrr_other" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:945800001L ~slug:"phrr-auth"
        in
        let* cid = insert_community conn "phrr-auth-home" in
        let* other_cid = insert_community conn "phrr-auth-other" in
        let* _rid =
          request_ok "pending" conn ~user:owner ~slug:"phrr-auth"
            ~community:cid ~note:"please review" ()
        in
        let* () = add_top_mod conn ~user:mod1 ~community:cid in
        let* () = add_top_mod conn ~user:mod2 ~community:cid in
        let* () = exec conn "make admin" q_set_admin (admin, true) in
        let* () = add_role conn ~user:plain_mod ~community:cid "mod" in
        let* () = add_role conn ~user:legacy ~community:cid "legacy_mod" in
        let* () = exec conn "member" q_insert_member (member, cid) in
        let* () = add_top_mod conn ~user:other ~community:other_cid in
        (* Authorized reviewers each see exactly the one pending request. *)
        let* () = expect_one "top_mod" conn ~reviewer:mod1 ~community:"phrr-auth-home" ~slug:"phrr-auth" in
        let* () = expect_one "second top_mod" conn ~reviewer:mod2 ~community:"phrr-auth-home" ~slug:"phrr-auth" in
        let* () = expect_one "durable admin" conn ~reviewer:admin ~community:"phrr-auth-home" ~slug:"phrr-auth" in
        (* Everyone else collapses to Ok None. *)
        let* () = load_none "ordinary member" conn ~reviewer:member ~community:"phrr-auth-home" in
        (* A stranger is also the session-shaped admin case: no durable flag. *)
        let* () = load_none "non-member / session-shaped admin" conn ~reviewer:stranger ~community:"phrr-auth-home" in
        let* () = load_none "plain mod" conn ~reviewer:plain_mod ~community:"phrr-auth-home" in
        let* () = load_none "legacy mod" conn ~reviewer:legacy ~community:"phrr-auth-home" in
        let* () = load_none "other-community top_mod" conn ~reviewer:other ~community:"phrr-auth-home" in
        let* () = load_none "missing community" conn ~reviewer:admin ~community:"phrr-nope" in
        (* Downgrade and removal serialize through the durable role. *)
        let* () = exec conn "downgrade" q_set_moderator_role (mod1, cid, "mod") in
        let* () = load_none "downgraded top_mod" conn ~reviewer:mod1 ~community:"phrr-auth-home" in
        let* () = exec conn "remove" q_remove_moderator (mod2, cid) in
        load_none "removed top_mod" conn ~reviewer:mod2 ~community:"phrr-auth-home")

  (* === community eligibility mapping === *)

  let eligibility_case =
    db_case_lifecycle_relaxed "review read: community host-eligibility mapping" (fun conn ->
        let* reviewer = insert_user conn "phrr_emod" in
        let check label ~slug ~expect ?visibility ?indexable ?network
            ?onboarding ?discoverable () =
          let* cid =
            insert_community ?visibility ?indexable ?network ?onboarding
              ?discoverable conn slug
          in
          let* () = add_top_mod conn ~user:reviewer ~community:cid in
          let* view = load_view label conn ~reviewer ~community:slug in
          Alcotest.(check string)
            (label ^ ": eligibility") expect
            (eligibility_str (Rv.community_host_eligibility (Rv.community view)));
          Lwt.return_unit
        in
        let* () = check "public listed" ~slug:"phrr-elig-pub" ~expect:"eligible" () in
        let* () =
          check "unlisted" ~slug:"phrr-elig-unl" ~expect:"eligible"
            ~indexable:false ~discoverable:false ()
        in
        let* () =
          check "private" ~slug:"phrr-inelig-priv" ~expect:"ineligible"
            ~visibility:"private" ~indexable:false ~discoverable:false ()
        in
        let* () =
          check "draft" ~slug:"phrr-inelig-draft" ~expect:"ineligible"
            ~onboarding:"draft" ~visibility:"private" ~indexable:false
            ~discoverable:false ()
        in
        check "legacy" ~slug:"phrr-inelig-legacy" ~expect:"ineligible"
          ~network:false ())

  let contradictory_flags_case =
    db_case_lifecycle_relaxed "review read: contradictory community flags are corruption"
      (fun conn ->
        let* reviewer = insert_user conn "phrr_cmod" in
        let* stranger = insert_user conn "phrr_cstr" in
        (* Published, public, network, but indexable <> discoverable — a
           leaking published shape. *)
        let* cid =
          insert_community ~indexable:true ~discoverable:false conn
            "phrr-corruptflags"
        in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* () =
          load_expect "mixed flags" Rv.Inconsistent_data conn ~reviewer
            ~community:"phrr-corruptflags"
        in
        (* An unauthorized reviewer still sees only absence: corruption is
           never a probe oracle. *)
        load_none "unauthorized sees no corruption" conn ~reviewer:stranger
          ~community:"phrr-corruptflags")

  (* === queue contents and ordering === *)

  let empty_queue_case =
    db_case "review read: empty queue with a valid community" (fun conn ->
        let* reviewer = insert_user conn "phrr_qmod" in
        let* cid = insert_community conn "phrr-empty" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* view = load_view "empty" conn ~reviewer ~community:"phrr-empty" in
        Alcotest.(check int) "no requests" 0
          (List.length (Rv.pending_requests view));
        Alcotest.(check string) "community name" "phrr-empty"
          (Rv.community_name (Rv.community view));
        Alcotest.(check string) "community slug" "phrr-empty"
          (Rv.community_slug (Rv.community view));
        Lwt.return_unit)

  let ordering_case =
    db_case "review read: queue ordered by created_at then project slug"
      (fun conn ->
        let* owner = insert_user conn "phrr_oowner" in
        let* reviewer = insert_user conn "phrr_omod" in
        let* cid = insert_community conn "phrr-queue" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        (* Built in a scrambled order; created_at (then slug for the tie) is
           what the queue order must reflect. *)
        let build ext slug ts =
          let* _, _ = make_project conn ~user:owner ~ext_id:ext ~slug in
          let* rid = request_ok slug conn ~user:owner ~slug ~community:cid () in
          exec conn ("created_at " ^ slug) q_set_created_at (rid, ts)
        in
        let* () = build 945800010L "phrr-q-alpha" "2020-01-03 00:00:00+00" in
        let* () = build 945800011L "phrr-q-zulu" "2020-01-03 00:00:00+00" in
        let* () = build 945800012L "phrr-q-charlie" "2020-01-01 00:00:00+00" in
        let* () = build 945800013L "phrr-q-bravo" "2020-01-02 00:00:00+00" in
        let* view = load_view "queue" conn ~reviewer ~community:"phrr-queue" in
        let slugs = List.map Rv.project_slug (Rv.pending_requests view) in
        Alcotest.(check (list string)) "created_at then slug order"
          [ "phrr-q-charlie"; "phrr-q-bravo"; "phrr-q-alpha"; "phrr-q-zulu" ]
          slugs;
        Lwt.return_unit)

  let excluded_statuses_case =
    db_case "review read: accepted/rejected/removed excluded from the queue"
      (fun conn ->
        let* owner = insert_user conn "phrr_exowner" in
        let* reviewer = insert_user conn "phrr_exmod" in
        let* cid = insert_community conn "phrr-excl" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let build ext slug mark =
          let* _, _ = make_project conn ~user:owner ~ext_id:ext ~slug in
          let* rid = request_ok slug conn ~user:owner ~slug ~community:cid () in
          exec conn ("mark " ^ slug) mark rid
        in
        let* () = build 945800020L "phrr-excl-acc" Phrq.q_mark_accepted in
        let* () = build 945800021L "phrr-excl-rej" Phrq.q_mark_rejected in
        let* () = build 945800022L "phrr-excl-rem" Phrq.q_mark_removed in
        let* view = load_view "excl" conn ~reviewer ~community:"phrr-excl" in
        Alcotest.(check int) "no pending" 0
          (List.length (Rv.pending_requests view));
        Lwt.return_unit)

  (* === per-request detail === *)

  let verification_mapping_case =
    db_case "review read: verified/stale/revoked project mapping"
      (fun conn ->
        let* owner = insert_user conn "phrr_vowner" in
        let* reviewer = insert_user conn "phrr_vmod" in
        let* cid = insert_community conn "phrr-verif" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        (* A request is created while verified, then verification drifts —
           the request must stay in the queue. *)
        let build ext slug status =
          let* _, project = make_project conn ~user:owner ~ext_id:ext ~slug in
          let* _rid = request_ok slug conn ~user:owner ~slug ~community:cid () in
          if status = "verified" then Lwt.return_unit
          else exec conn ("set " ^ status) Phrq.q_set_verification (project, status)
        in
        let* () = build 945800030L "phrr-v-verified" "verified" in
        let* () = build 945800031L "phrr-v-stale" "stale" in
        let* () = build 945800032L "phrr-v-revoked" "revoked" in
        let* view = load_view "verif" conn ~reviewer ~community:"phrr-verif" in
        let requests = Rv.pending_requests view in
        Alcotest.(check int) "three requests" 3 (List.length requests);
        let of_slug s = List.find (fun r -> Rv.project_slug r = s) requests in
        Alcotest.(check string) "verified maps" "verified"
          (verification_str (Rv.project_verification (of_slug "phrr-v-verified")));
        Alcotest.(check string) "stale maps" "stale"
          (verification_str (Rv.project_verification (of_slug "phrr-v-stale")));
        Alcotest.(check string) "revoked maps" "revoked"
          (verification_str (Rv.project_verification (of_slug "phrr-v-revoked")));
        Lwt.return_unit)

  let detail_case =
    db_case "review read: project, repository, requester, and note detail"
      (fun conn ->
        let* owner = insert_user conn "phrr_downer" in
        let* reviewer = insert_user conn "phrr_dmod" in
        let* _, _ =
          make_project conn ~user:owner ~ext_id:945800040L ~slug:"phrr-detail"
        in
        let* cid = insert_community conn "phrr-detail-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let note = "Prima riga — gi\xc3\xa0 discutiamo qui \xe2\x98\x95" in
        let* _rid =
          request_ok "pending" conn ~user:owner ~slug:"phrr-detail"
            ~community:cid ~note ()
        in
        let* view =
          load_view "detail" conn ~reviewer ~community:"phrr-detail-home"
        in
        let req = List.hd (Rv.pending_requests view) in
        Alcotest.(check string) "project name" "Pfin Fixture Project"
          (Rv.project_name req);
        Alcotest.(check string) "project slug" "phrr-detail"
          (Rv.project_slug req);
        Alcotest.(check bool) "kind is project" true
          (Rv.project_kind req = Pi.Project);
        Alcotest.(check string) "namespace login" "pfin-owner"
          (Rv.project_namespace_login req);
        Alcotest.(check string) "verified" "verified"
          (verification_str (Rv.project_verification req));
        let repos = Rv.project_repositories req in
        Alcotest.(check int) "one repository" 1 (List.length repos);
        let r = List.hd repos in
        Alcotest.(check string) "repo full name" "pfin-owner/alpha"
          (Rv.repository_full_name r);
        Alcotest.(check string) "repo url" "https://github.com/pfin-owner/alpha"
          (Rv.repository_html_url r);
        Alcotest.(check bool) "repo primary" true (Rv.repository_is_primary r);
        Alcotest.(check bool) "repo not archived" false
          (Rv.repository_is_archived r);
        Alcotest.(check (option string)) "requester name" (Some "phrr_downer")
          (Rv.requester_name req);
        Alcotest.(check (option string)) "note round-trips" (Some note)
          (Rv.request_note req);
        Lwt.return_unit)

  let repositories_order_case =
    db_case "review read: repositories preserved in stored position order"
      (fun conn ->
        let* owner = insert_user conn "phrr_rowner" in
        let* reviewer = insert_user conn "phrr_rmod" in
        let* _project =
          make_project2 conn ~user:owner ~ext_id:945800045L ~slug:"phrr-multi"
        in
        let* cid = insert_community conn "phrr-multi-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* _rid =
          request_ok "pending" conn ~user:owner ~slug:"phrr-multi"
            ~community:cid ()
        in
        let* view =
          load_view "multi" conn ~reviewer ~community:"phrr-multi-home"
        in
        let repos = Rv.project_repositories (List.hd (Rv.pending_requests view)) in
        Alcotest.(check (list string)) "repos in position order"
          [ "pfin-owner/alpha"; "pfin-owner/beta" ]
          (List.map Rv.repository_full_name repos);
        Alcotest.(check bool) "first is primary" true
          (Rv.repository_is_primary (List.hd repos));
        Lwt.return_unit)

  let deleted_requester_case =
    db_case "review read: deleted requester collapses to None, note kept"
      (fun conn ->
        let* owner = insert_user conn "phrr_delowner" in
        let* reviewer = insert_user conn "phrr_delmod" in
        let* _, _ =
          make_project conn ~user:owner ~ext_id:945800050L ~slug:"phrr-del"
        in
        let* cid = insert_community conn "phrr-del-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* _rid =
          request_ok "pending" conn ~user:owner ~slug:"phrr-del" ~community:cid
            ~note:"keep me" ()
        in
        (* Deleting the requester (also the steward) SET NULLs the
           provenance; the project and its request survive. *)
        let* () = exec conn "delete requester" q_delete_user owner in
        let* view = load_view "del" conn ~reviewer ~community:"phrr-del-home" in
        let req = List.hd (Rv.pending_requests view) in
        Alcotest.(check (option string)) "requester None" None
          (Rv.requester_name req);
        Alcotest.(check (option string)) "note preserved" (Some "keep me")
          (Rv.request_note req);
        Lwt.return_unit)

  (* === durable corruption === *)

  let note_corruption_case =
    db_case "review read: non-canonical durable note is corruption"
      (fun conn ->
        let* owner = insert_user conn "phrr_nowner" in
        let* reviewer = insert_user conn "phrr_nmod" in
        let* _, _ =
          make_project conn ~user:owner ~ext_id:945800060L ~slug:"phrr-note"
        in
        let* cid = insert_community conn "phrr-note-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_ok "pending" conn ~user:owner ~slug:"phrr-note"
            ~community:cid ~note:"fine" ()
        in
        let* () = exec conn "pad note" q_pad_note rid in
        let* () =
          load_expect "padded note" Rv.Inconsistent_data conn ~reviewer
            ~community:"phrr-note-home"
        in
        let* () = exec conn "control note" q_control_note rid in
        load_expect "control note" Rv.Inconsistent_data conn ~reviewer
          ~community:"phrr-note-home")

  let project_corruption_case =
    db_case "review read: durable project/repository corruption is Inconsistent"
      (fun conn ->
        let* owner = insert_user conn "phrr_cowner" in
        let* reviewer = insert_user conn "phrr_cmod2" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:945800070L ~slug:"phrr-corr"
        in
        let* cid = insert_community conn "phrr-corr-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* _rid =
          request_ok "pending" conn ~user:owner ~slug:"phrr-corr"
            ~community:cid ()
        in
        let* () = exec conn "corrupt login" q_corrupt_login project in
        let* () =
          load_expect "corrupt login" Rv.Inconsistent_data conn ~reviewer
            ~community:"phrr-corr-home"
        in
        let* () = exec conn "restore login" q_restore_login project in
        let* () = exec conn "corrupt repo url" q_corrupt_repo_url project in
        let* () =
          load_expect "corrupt repo url" Rv.Inconsistent_data conn ~reviewer
            ~community:"phrr-corr-home"
        in
        let* () = exec conn "restore repo url" q_restore_repo_url project in
        let* () = exec conn "delete repos" q_delete_repos project in
        load_expect "missing repositories" Rv.Inconsistent_data conn ~reviewer
          ~community:"phrr-corr-home")

  (* Emptying search_path hides the unqualified tables, so the first query
     fails at the SQL layer and Caqti returns an Error the store maps to
     Storage_error — a genuine query failure, not a torn-down connection
     (which the driver signals by raising, not by Error). Reset before the
     case returns so the per-case cleanup still runs. *)
  let q_break_search_path =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO ''"

  let q_reset_search_path =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO public"

  let storage_error_case =
    db_case "review read: storage failure surfaces as Storage_error"
      (fun conn ->
        let* () = exec conn "break search_path" q_break_search_path () in
        let* () =
          load_expect "broken schema" Rv.Storage_error conn ~reviewer:1
            ~community:"phrr-anything"
        in
        exec conn "reset search_path" q_reset_search_path ())

  let suite =
    [ pure_inputs_case; authorization_case; eligibility_case;
      contradictory_flags_case; empty_queue_case; ordering_case;
      excluded_statuses_case; verification_mapping_case; detail_case;
      repositories_order_case; deleted_requester_case; note_corruption_case;
      project_corruption_case; storage_error_case ]
end

(* === Moderator project-home review handlers
   (Project_home_review_handlers) ===
   GET /c/:slug/project-home-requests and the accept/reject POSTs: the
   settings navigation link, the DB-free access/origin/CSRF gates (every
   rejection precedes SQL — no sql_pool is installed in those harnesses),
   and the database-gated end-to-end queue and review flow over verified
   permanent projects, real communities, real durable top-mod/admin rows,
   and the transactional review store. Reserved external-installation-id
   range 946000001..946000999 (hence account ids 946100001..946100999,
   which also scope the permanent-project cleanup), phhr_% usernames, and
   phhr-% community slugs so no suite shares fixtures. Credential and
   privacy assertions are boolean, so no fixture byte reaches test output on
   failure. *)
module Phhr = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Hr = Earde.Project_home_review_handlers
  module Phrp = Earde.Project_home_review_pages

  let case = go_case
  let counting_loader = Gh_start_handler.counting_loader
  let ok_loader = Gh_start_handler.ok_loader
  let status_of = Gh_start_handler.status_of
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let make_project = Phrq.make_project
  let insert_community = Phcv.insert_community
  let request_pending = Phcv.request_pending

  let make_queue ~mode = Hr.make_project_home_review_queue_handler ~mode
  let make_accept ~mode ~load_config =
    Hr.make_project_home_accept_handler ~mode ~load_config
  let make_reject ~mode ~load_config =
    Hr.make_project_home_reject_handler ~mode ~load_config

  let queue_target slug = Printf.sprintf "/c/%s/project-home-requests" slug
  let accept_target ~slug ~project =
    Printf.sprintf "/c/%s/projects/%s/accept" slug project
  let reject_target ~slug ~project =
    Printf.sprintf "/c/%s/projects/%s/reject" slug project

  (* --- Fixtures --- *)

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 946100001 AND 946100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 946100001 AND 946100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 946000001 AND 946000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phhr-%'"
      ; "DELETE FROM users WHERE username LIKE 'phhr_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 946000001 AND 946000999"
      ]

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun ~url conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f ~url conn))

  (* Durable authorization fixtures reused from the store suite: the real
     rows the read model and review store read. *)
  let add_top_mod conn ~user ~community =
    exec conn "top_mod fixture" Phrv.q_insert_moderator
      (user, community, "top_mod")
  let add_role conn ~user ~community role =
    exec conn "role fixture" Phrv.q_insert_moderator (user, community, role)
  let add_member conn ~user ~community =
    exec conn "member fixture" Phrv.q_insert_member (user, community)
  let set_admin conn ~user flag = exec conn "admin fixture" Phrv.q_set_admin (user, flag)
  let remove_moderator conn ~user ~community =
    exec conn "remove mod" Phrv.q_remove_moderator (user, community)
  let set_role conn ~user ~community role =
    exec conn "downgrade" Phrv.q_set_moderator_role (user, community, role)

  let status_of_relation conn id = find conn "status" Phrv.q_status id

  (* === DB-free: settings navigation link === *)

  let settings_community : Earde.Db.community =
    { id = 4242; slug = "phhr-nav"; name = "Phhr Nav"; description = None;
      rules = None; avatar_url = None; banner_url = None; allow_downvotes = true;
      sections_enabled = false; visibility = Earde.Db.Community_public;
      indexable = true; is_network_community = true;
      onboarding_state = Earde.Db.Community_published; discoverable = true }

  (* The settings page renders a framework CSRF field, so it needs a live
     request under a secret + sessions pipeline; no SQL is touched. *)
  let render_settings ~is_admin ~is_top_mod =
    let captured = ref None in
    let pipeline =
      Dream.set_secret gck_secret @@ Dream.memory_sessions
      @@ fun req ->
      captured :=
        Some
          (Earde.Pages.community_settings_page ~is_admin ~is_top_mod
             ~open_reports_count:0 ~community:settings_community ~mods:[]
             ~banned_users:[] ~members:[] ~sections:[] ~channels:[] req);
      Dream.html ""
    in
    ignore
      (Lwt_main.run
         (pipeline
            (Dream.request ~method_:`GET ~target:"/c/phhr-nav/settings" "")));
    match !captured with
    | Some html -> html
    | None -> Alcotest.fail "settings renderer did not run"

  let nav_link = "href='/c/phhr-nav/project-home-requests'"

  let nav_cases =
    [ case "settings nav: top-mod and durable-admin surfaces expose the queue \
            link, canonically, with no id or count" (fun () ->
          let top_mod = render_settings ~is_admin:false ~is_top_mod:true in
          Alcotest.(check bool) "top_mod link present" true
            (contains top_mod nav_link);
          Alcotest.(check bool) "exact link text" true
            (contains top_mod ">Project home requests</a>");
          let admin = render_settings ~is_admin:true ~is_top_mod:false in
          Alcotest.(check bool) "admin link present" true
            (contains admin nav_link);
          (* Canonical slug only — never the community id, a count, a form,
             or script. The framework CSRF fields are dropped first: their
             random token bytes could otherwise spell the id by chance. *)
          Alcotest.(check bool) "no community id in link" false
            (contains (ps_without_csrf_inputs top_mod) "4242");
          Alcotest.(check bool) "one queue link, not two" true
            (ps_count top_mod nav_link = 1))
    ; case "settings nav: an unauthorized (regular-mod) settings surface never \
            gains the link" (fun () ->
          let regular = render_settings ~is_admin:false ~is_top_mod:false in
          Alcotest.(check bool) "no queue link" false
            (contains regular nav_link);
          Alcotest.(check bool) "no queue label" false
            (contains regular "Project home requests"))
    ]

  (* === DB-free: GET access gates === *)

  let gate_slug = "phhr-any"
  let gate_project = "phhr-proj"

  let get_run ?session ~mode () =
    Pch.gate_run ?session ~method_:`GET ~target:(queue_target gate_slug)
      (make_queue ~mode)

  let get_gate_cases =
    [ case "GET queue off: clean /bring redirect before params or SQL"
        (fun () ->
          Pch.check_clean_redirect "off" "/bring"
            (Pch.gate_response "off"
               (get_run ~session:Pch.admin_session ~mode:Ob.Off ())))
    ; case "GET queue: anonymous and invalid sessions to /login" (fun () ->
          Pch.check_clean_redirect "anonymous" "/login"
            (Pch.gate_response "anonymous" (get_run ~mode:Ob.Public ()));
          List.iter
            (fun raw ->
              Pch.check_clean_redirect ("user_id " ^ raw) "/login"
                (Pch.gate_response ("user_id " ^ raw)
                   (get_run ~session:[ ("user_id", raw) ] ~mode:Ob.Public ())))
            [ "not-a-number"; ""; "0"; "-3" ];
          Pch.check_clean_redirect "is_admin only" "/login"
            (Pch.gate_response "is_admin only"
               (get_run ~session:[ ("is_admin", "true") ] ~mode:Ob.Admins ())))
    ; case "GET queue admins mode: non-admin to /bring; authorized reach the \
            no-route 404 with no SQL" (fun () ->
          Pch.check_clean_redirect "non-admin" "/bring"
            (Pch.gate_response "non-admin"
               (get_run ~session:Pch.logged_in ~mode:Ob.Admins ()));
          let continues label session mode =
            let response = Pch.gate_response label (get_run ~session ~mode ()) in
            Alcotest.(check int) (label ^ ": generic 404") 404
              (status_of response)
          in
          continues "admin continues" Pch.admin_session Ob.Admins;
          continues "public user continues" Pch.logged_in Ob.Public)
    ]

  (* === DB-free: POST access gates, configuration, and origin (both verbs) === *)

  (* Route pattern + target + factory, parametrized over the accept and
     reject handlers so both get the same coverage. *)
  let verbs =
    [ ("accept", make_accept, "/c/:slug/projects/:project_slug/accept",
       accept_target ~slug:gate_slug ~project:gate_project)
    ; ("reject", make_reject, "/c/:slug/projects/:project_slug/reject",
       reject_target ~slug:gate_slug ~project:gate_project)
    ]

  let post_run ~make ~target ?session ?(headers = []) ~mode ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST ~target
      (make ~mode ~load_config)

  let routed_post ~make ~pattern ~target ?session ?(headers = []) ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST ~target
      (Dream.router
         [ Dream.post pattern (fun req -> make ~mode:Ob.Public ~load_config req) ])

  let post_gate_cases =
    List.concat_map
      (fun (verb, make, pattern, target) ->
        [ case (verb ^ " off: clean /bring redirect, loader untouched")
            (fun () ->
              let loader, calls = counting_loader (ok_loader ()) in
              let response =
                Pch.gate_response "off"
                  (post_run ~make ~target ~session:Pch.admin_session ~mode:Ob.Off
                     ~load_config:loader ())
              in
              Pch.check_clean_redirect "off" "/bring" response;
              Alcotest.(check int) "loader never called" 0 !calls)
        ; case
            (verb ^ ": anonymous and invalid sessions to /login, loader \
             untouched") (fun () ->
              let loader, calls = counting_loader (ok_loader ()) in
              Pch.check_clean_redirect "anonymous" "/login"
                (Pch.gate_response "anonymous"
                   (post_run ~make ~target ~mode:Ob.Public ~load_config:loader ()));
              List.iter
                (fun raw ->
                  Pch.check_clean_redirect ("user_id " ^ raw) "/login"
                    (Pch.gate_response ("user_id " ^ raw)
                       (post_run ~make ~target
                          ~session:[ ("user_id", raw) ]
                          ~mode:Ob.Public ~load_config:loader ())))
                [ "not-a-number"; ""; "0"; "-3" ];
              Alcotest.(check int) "loader never called" 0 !calls)
        ; case
            (verb ^ " admins mode: non-admin to /bring before route or \
             configuration") (fun () ->
              let loader, calls = counting_loader (ok_loader ()) in
              Pch.check_clean_redirect "non-admin" "/bring"
                (Pch.gate_response "non-admin"
                   (post_run ~make ~target ~session:Pch.logged_in ~mode:Ob.Admins
                      ~load_config:loader ()));
              Alcotest.(check int) "loader never called" 0 !calls;
              (* Past the gates, the routerless harness has no route params:
                 the defensive 404 answers before the configuration load. *)
              let continues label session mode =
                let loader, calls = counting_loader (ok_loader ()) in
                let response =
                  Pch.gate_response label
                    (post_run ~make ~target ~session ~mode ~load_config:loader ())
                in
                Alcotest.(check int) (label ^ ": defensive 404") 404
                  (status_of response);
                Alcotest.(check int) (label ^ ": loader untouched") 0 !calls
              in
              continues "admin continues" Pch.admin_session Ob.Admins;
              continues "public user continues" Pch.logged_in Ob.Public)
        ; case (verb ^ ": configuration error is a generic 503, no form")
            (fun () ->
              let loader, calls =
                counting_loader (gac_of_values ~origin:None ())
              in
              let response =
                Pch.gate_response "config failure"
                  (routed_post ~make ~pattern ~target ~session:Pch.logged_in
                     ~headers:
                       [ ("Origin", "https://earde.com");
                         ("Content-Type", "application/x-www-form-urlencoded");
                       ]
                     ~load_config:loader ())
              in
              Alcotest.(check int) "503" 503 (status_of response);
              Alcotest.(check int) "loader called once" 1 !calls;
              let body = Lwt_main.run (Dream.body response) in
              List.iter
                (fun needle ->
                  Alcotest.(check bool) ("no leak " ^ needle) false
                    (contains body needle))
                [ "EARDE_PUBLIC_ORIGIN"; "Missing"; "Invalid"; "public_origin" ])
        ; case (verb ^ " origin gate: exact policy, before any form parse")
            (fun () ->
              let origin_run label ?sec_fetch_site origin =
                let headers =
                  (match origin with Some o -> [ ("Origin", o) ] | None -> [])
                  @
                  match sec_fetch_site with
                  | Some v -> [ ("Sec-Fetch-Site", v) ]
                  | None -> []
                in
                routed_post ~make ~pattern ~target ~session:Pch.logged_in
                  ~headers ~load_config:(fun () -> ok_loader ()) ()
                |> Pch.gate_response label
              in
              let rejected label ?sec_fetch_site origin =
                Alcotest.(check int) (label ^ ": 403") 403
                  (status_of (origin_run label ?sec_fetch_site origin))
              in
              (* Passing origin, the missing content type is the next
                 rejection (400) — reaching it proves origin accepted. *)
              let accepted label ?sec_fetch_site origin =
                Alcotest.(check int) (label ^ ": passes origin") 400
                  (status_of (origin_run label ?sec_fetch_site origin))
              in
              accepted "exact origin" (Some "https://earde.com");
              accepted "explicit default port" (Some "https://earde.com:443");
              accepted "fetch metadata" ~sec_fetch_site:"same-origin" None;
              rejected "cross-origin" (Some "https://evil.example");
              rejected "same-site subdomain" (Some "https://www.earde.com");
              rejected "wrong scheme" (Some "http://earde.com");
              rejected "null" (Some "null");
              rejected "mismatch beats metadata" ~sec_fetch_site:"same-origin"
                (Some "https://evil.example");
              rejected "no signals" None;
              rejected "cross-site" ~sec_fetch_site:"cross-site" None;
              let leak = origin_run "reflection" (Some "https://evil.example") in
              Alcotest.(check bool) "origin not reflected" false
                (contains (Lwt_main.run (Dream.body leak)) "evil.example"))
        ])
      verbs

  (* === DB-free: POST CSRF and the zero-application-field rule (both verbs) === *)

  let csrf_pipeline ~make ~pattern () =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    let* () = Dream.set_session_field req "user_id" "42" in
    match Dream.method_ req with
    | `GET ->
        Dream.respond
          (Dream.csrf_token req ^ "\n" ^ Dream.csrf_token ~valid_for:(-60.) req)
    | _ ->
        Dream.router
          [ Dream.post pattern (fun r ->
                make ~mode:Ob.Public ~load_config:(fun () -> ok_loader ()) r) ]
          req

  let csrf_post ~target ?cookie ?(content_type = true) pipeline fields =
    let headers =
      [ ("Origin", "https://earde.com") ]
      @ (if content_type then
           [ ("Content-Type", "application/x-www-form-urlencoded") ]
         else [])
      @ match cookie with Some c -> [ ("Cookie", c) ] | None -> []
    in
    match
      Lwt_main.run
        (pipeline
           (Dream.request ~method_:`POST ~target ~headers
              (Pch.form_body fields)))
    with
    | response -> `Response response
    | exception _ -> `Db_boundary

  let csrf_rejected label expected result =
    Alcotest.(check int) (label ^ ": status") expected
      (status_of (Pch.gate_response label result))

  let csrf_cases =
    List.map
      (fun (verb, make, pattern, target) ->
        case
          (verb ^ " CSRF: Dream verification gates every submission; only a \
           zero-field verified form reaches the store")
          (fun () ->
            let pipeline = csrf_pipeline ~make ~pattern () in
            let cookie, fresh, expired = Pch.mint_tokens "mint" pipeline in
            let post = csrf_post ~target in
            (* Every CSRF failure refuses the submission, but it is answered
               by reloading the reviewer-authorized queue with a fresh token
               rather than a terminal page — so each one reaches the read
               model's DB boundary and none reaches the store. A queue whose
               one-hour token outlived its fourteen-day session must not
               become permanently unactionable. *)
            Pch.check_db_boundary "missing token re-renders"
              (post ~cookie pipeline []);
            Pch.check_db_boundary "invalid token re-renders"
              (post ~cookie pipeline [ ("dream.csrf", "not-a-token") ]);
            Pch.check_db_boundary "expired token re-renders"
              (post ~cookie pipeline [ ("dream.csrf", expired) ]);
            Pch.check_db_boundary "duplicate tokens re-render"
              (post ~cookie pipeline
                 [ ("dream.csrf", fresh); ("dream.csrf", fresh) ]);
            Pch.check_db_boundary "wrong session re-renders"
              (post pipeline [ ("dream.csrf", fresh) ]);
            (* A wrong content type is still answered without any SQL. *)
            csrf_rejected "wrong content type" 400
              (post ~cookie ~content_type:false pipeline
                 [ ("dream.csrf", fresh) ]);
            (* An unexpected application field is a generic 400 that never
               reaches the store (a direct response, not the DB boundary). *)
            csrf_rejected "unexpected decision field" 400
              (post ~cookie pipeline
                 [ ("decision", "accept"); ("dream.csrf", fresh) ]);
            csrf_rejected "unexpected id field" 400
              (post ~cookie pipeline
                 [ ("relation_id", "1"); ("dream.csrf", fresh) ]);
            (* A verified token with no application field reaches the DB
               boundary: CSRF passed, Dream stripped its own field, and the
               store call is the next thing to run. *)
            Pch.check_db_boundary "empty verified form continues"
              (post ~cookie pipeline [ ("dream.csrf", fresh) ]))
        )
      verbs

  (* === Database-gated: the real queue and review flow === *)

  (* Production shape: sql_pool + secret + memory sessions + the real router
     paths, so all three handlers read :slug / :project_slug exactly as in
     bin/main. /mint hands replay cases a fresh CSRF token for an
     established session. is_admin is set into the session only when asked —
     durable admin authorization is the users.is_admin column, never the
     session flag. *)
  let app_pipeline ?session_user_id ?(session_admin = false) ~url () =
    Dream.sql_pool url @@ Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ (fun handler request ->
         match session_user_id with
         | None -> handler request
         | Some uid ->
             let* () =
               Dream.set_session_field request "user_id" (string_of_int uid)
             in
             let* () =
               if session_admin then
                 Dream.set_session_field request "is_admin" "true"
               else Lwt.return_unit
             in
             handler request)
    @@ Dream.router
         [ Dream.get "/mint" (fun req -> Dream.respond (Dream.csrf_token req));
           Dream.get "/c/:slug/project-home-requests" (fun req ->
               make_queue ~mode:Ob.Public req);
           Dream.post "/c/:slug/projects/:project_slug/accept" (fun req ->
               make_accept ~mode:Ob.Public
                 ~load_config:(fun () -> ok_loader ())
                 req);
           Dream.post "/c/:slug/projects/:project_slug/reject" (fun req ->
               make_reject ~mode:Ob.Public
                 ~load_config:(fun () -> ok_loader ())
                 req);
         ]

  let get_queue ?cookie ~slug pipeline =
    Pch.do_get ?cookie ~target:(queue_target slug) pipeline

  (* One GET that opens the queue: page, session cookie, and a CSRF token
     for the follow-up POST (either form's token is session-bound, so the
     first serves both routes). *)
  let open_queue label ~slug pipeline =
    let* response, body = get_queue ~slug pipeline in
    Pch.check_page label response;
    let cookie = Pch.session_cookie label response in
    let token = Pch.csrf_of_page label body in
    Lwt.return (cookie, token, body)

  let do_post ?(origin = Some "https://earde.com") ~cookie ~target ~token
      pipeline =
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @ [ ("Content-Type", "application/x-www-form-urlencoded");
          ("Cookie", cookie);
        ]
    in
    pipeline
      (Dream.request ~method_:`POST ~target ~headers
         (Pch.form_body [ ("dream.csrf", token) ]))

  (* === GET authorization === *)

  let get_authz_case =
    db_case "GET queue: top-mods and durable admins see it; every other \
             identity is one generic 404" (fun ~url conn ->
        let* owner = insert_user conn "phhr_owner" in
        let* top1 = insert_user conn "phhr_top1" in
        let* top2 = insert_user conn "phhr_top2" in
        let* admin = insert_user conn "phhr_admin" in
        let* member = insert_user conn "phhr_member" in
        let* stranger = insert_user conn "phhr_stranger" in
        let* modu = insert_user conn "phhr_mod" in
        let* legacy = insert_user conn "phhr_legacy" in
        let* othermod = insert_user conn "phhr_othermod" in
        let* removed = insert_user conn "phhr_removed" in
        let* sonly = insert_user conn "phhr_sonly" in
        let* _, _ =
          make_project conn ~user:owner ~ext_id:946000001L ~slug:"phhr-authz"
        in
        let* cid = insert_community ~name:"Phhr Authz Home" conn "phhr-authz-home" in
        let* other = insert_community conn "phhr-authz-other" in
        let* _rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-authz"
            ~community:cid ~note:"phhr authz note" ()
        in
        let* () = add_top_mod conn ~user:top1 ~community:cid in
        let* () = add_top_mod conn ~user:top2 ~community:cid in
        let* () = set_admin conn ~user:admin true in
        let* () = add_member conn ~user:member ~community:cid in
        let* () = add_role conn ~user:modu ~community:cid "mod" in
        let* () = add_role conn ~user:legacy ~community:cid "legacy_mod" in
        let* () = add_top_mod conn ~user:othermod ~community:other in
        let* () = add_top_mod conn ~user:removed ~community:cid in
        let* () = remove_moderator conn ~user:removed ~community:cid in
        let sees label uid ~admin_session =
          let pipeline =
            app_pipeline ~session_user_id:uid ~session_admin:admin_session ~url ()
          in
          let* response, body = get_queue ~slug:"phhr-authz-home" pipeline in
          Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
          let frag = ps_fragment body in
          Pch.must frag "Project home requests";
          Pch.must frag "Pfin Fixture Project";
          Lwt.return_unit
        in
        let denied label uid ~admin_session ~slug =
          let pipeline =
            app_pipeline ~session_user_id:uid ~session_admin:admin_session ~url ()
          in
          let* response, body = get_queue ~slug pipeline in
          Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
          Pch.must body "This page does not exist.";
          Pch.must_not body "Pfin Fixture Project";
          Pch.must_not body "phhr authz note";
          Lwt.return_unit
        in
        let* () = sees "top mod" top1 ~admin_session:false in
        let* () = sees "second top mod" top2 ~admin_session:false in
        let* () = sees "durable admin" admin ~admin_session:false in
        let* () = denied "ordinary member" member ~admin_session:false ~slug:"phhr-authz-home" in
        let* () = denied "non-member" stranger ~admin_session:false ~slug:"phhr-authz-home" in
        let* () = denied "mod role" modu ~admin_session:false ~slug:"phhr-authz-home" in
        let* () = denied "legacy_mod role" legacy ~admin_session:false ~slug:"phhr-authz-home" in
        let* () = denied "other-community mod" othermod ~admin_session:false ~slug:"phhr-authz-home" in
        let* () = denied "removed top mod" removed ~admin_session:false ~slug:"phhr-authz-home" in
        (* Session-only admin claim without the durable flag. *)
        let* () = denied "session-only admin" sonly ~admin_session:true ~slug:"phhr-authz-home" in
        (* Missing community collapses identically. *)
        denied "missing community" top1 ~admin_session:false ~slug:"phhr-authz-absent")

  (* === GET states === *)

  let get_states_case =
    db_case_lifecycle_relaxed "GET queue: empty, populated, note escaped, verification copy, \
             ineligible warning, closed rows absent, no ids" (fun ~url conn ->
        let* owner = insert_user conn "phhr_sowner" in
        let* reviewer = insert_user conn "phhr_smod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000010L ~slug:"phhr-state"
        in
        let* other_owner = insert_user conn "phhr_sowner2" in
        let* _, _ =
          make_project conn ~user:other_owner ~ext_id:946000011L
            ~slug:"phhr-state-b"
        in
        let* cid = insert_community ~name:"Phhr State Home" conn "phhr-state-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        (* Empty queue. *)
        let* response, body = get_queue ~slug:"phhr-state-home" pipeline in
        Pch.check_page "empty" response;
        Alcotest.(check bool) "noindex" true (contains body "noindex");
        let frag = ps_fragment body in
        Pch.must frag "No pending project requests.";
        Alcotest.(check int) "no forms when empty" 0 (ps_count frag "<form");
        (* Two pending requests; a private note on the first. *)
        let* rid =
          request_pending "pending a" conn ~user:owner ~slug:"phhr-state"
            ~community:cid ~note:"<b>phhr-secret-note</b>" ()
        in
        let* _rid2 =
          request_pending "pending b" conn ~user:other_owner
            ~slug:"phhr-state-b" ~community:cid ()
        in
        let* response, body = get_queue ~slug:"phhr-state-home" pipeline in
        Pch.check_page "populated" response;
        let frag = ps_fragment body in
        Pch.must frag "action='/c/phhr-state-home/projects/phhr-state/accept'";
        Pch.must frag "action='/c/phhr-state-home/projects/phhr-state/reject'";
        Pch.must frag "action='/c/phhr-state-home/projects/phhr-state-b/accept'";
        Pch.must frag "Accept as community home";
        Pch.must frag "Reject request";
        (* The private note is escaped, never raw markup. *)
        Pch.must frag "phhr-secret-note";
        Pch.must frag "&lt;b&gt;phhr-secret-note&lt;/b&gt;";
        Pch.must_not frag "<b>phhr-secret-note</b>";
        Pch.must frag "phrv-verification'>Verified<";
        (* No internal ids leak. *)
        Pch.must_not frag (Int64.to_string rid);
        Pch.must_not frag (Int64.to_string project);
        Pch.must_not frag (string_of_int cid);
        (* Stale then revoked: acceptance suppressed, rejection stays. *)
        let* () = exec conn "stale" Phrq.q_set_verification (project, "stale") in
        let* response, body = get_queue ~slug:"phhr-state-home" pipeline in
        Pch.check_page "stale" response;
        let frag = ps_fragment body in
        Pch.must frag "Verification stale";
        Pch.must_not frag
          "action='/c/phhr-state-home/projects/phhr-state/accept'";
        Pch.must frag "action='/c/phhr-state-home/projects/phhr-state/reject'";
        Pch.must frag "Acceptance is unavailable for this request.";
        let* () = exec conn "revoked" Phrq.q_set_verification (project, "revoked") in
        let* response, body = get_queue ~slug:"phhr-state-home" pipeline in
        Pch.check_page "revoked" response;
        Pch.must (ps_fragment body) "Verification revoked";
        let* () = exec conn "reverify" Phrq.q_set_verification (project, "verified") in
        (* Ineligible community: page-level warning; every accept suppressed;
           reject stays. *)
        let* () = exec conn "make private" Phcv.q_make_private cid in
        let* response, body = get_queue ~slug:"phhr-state-home" pipeline in
        Pch.check_page "ineligible" response;
        let frag = ps_fragment body in
        Pch.must frag "This community cannot currently accept project-home requests.";
        Pch.must_not frag
          "action='/c/phhr-state-home/projects/phhr-state/accept'";
        Pch.must frag "action='/c/phhr-state-home/projects/phhr-state/reject'";
        Pch.must_not frag "private";
        let* () = exec conn "restore" Phrv.q_make_eligible cid in
        (* Accepted and rejected rows drop out of the queue entirely. *)
        let* () = exec conn "accept fixture" Phrq.q_mark_accepted rid in
        let* response, body = get_queue ~slug:"phhr-state-home" pipeline in
        Pch.check_page "after accept" response;
        let frag = ps_fragment body in
        Pch.must_not frag "action='/c/phhr-state-home/projects/phhr-state/accept'";
        Pch.must_not frag "action='/c/phhr-state-home/projects/phhr-state/reject'";
        Pch.must_not frag "phhr-secret-note";
        Lwt.return_unit)

  let credential_needles =
    [ ("access token", Pod_store.pods_access_fixture)
    ; ("refresh token", Pod_store.pods_refresh_fixture)
    ; ("private repository name", gur_private_name)
    ; ("private repository description", gur_private_description)
    ]

  (* === POST accept: PRG, durable review, replay, privacy === *)

  let accept_prg_case =
    db_case "POST accept: PRG, pending disappears, relation accepted, exact \
             reviewer, replay is 409, no side effects" (fun ~url conn ->
        let* owner = insert_user conn "phhr_aowner" in
        let* reviewer = insert_user conn "phhr_amod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000020L ~slug:"phhr-accept"
        in
        let* cid = insert_community ~name:"Phhr Accept Home" conn "phhr-accept-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-accept"
            ~community:cid ~note:"phhr accept note" ()
        in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* cookie, token, _body = open_queue "queue" ~slug:"phhr-accept-home" pipeline in
        let target = accept_target ~slug:"phhr-accept-home" ~project:"phhr-accept" in
        let* response = do_post ~cookie ~target ~token pipeline in
        let* () =
          Pch.check_redirect_lwt "accepted"
            "/c/phhr-accept-home/project-home-requests" response
        in
        let redirect_cookies =
          String.concat "|" (Dream.headers response "Set-Cookie")
        in
        (* Exactly one relation, now accepted with the exact reviewer and a
           coherent review timestamp; note and requester preserved. *)
        let* ( ((_, rc), (rtype, status)), ((req, rev), (note, _)) ) =
          find conn "relation row" Phrq.q_relation_row rid
        in
        Alcotest.(check int) "same community" cid rc;
        Alcotest.(check string) "relation home" "home" rtype;
        Alcotest.(check string) "status accepted" "accepted" status;
        Alcotest.(check (option int)) "requester preserved" (Some owner) req;
        Alcotest.(check (option int)) "reviewer stored" (Some reviewer) rev;
        Alcotest.(check (option string)) "note preserved" (Some "phhr accept note") note;
        let* present, ordered, _ = find conn "review times" Phrv.q_review_times rid in
        Alcotest.(check bool) "reviewed_at present" true present;
        Alcotest.(check bool) "reviewed_at >= created_at" true ordered;
        (* No membership, moderator, or stewardship change from acceptance. *)
        let* members = find conn "members" Phrq.q_count_members cid in
        Alcotest.(check int) "no new member" 0 members;
        let* mods = find conn "moderators" Phrq.q_count_moderators cid in
        Alcotest.(check int) "only the one reviewer mod" 1 mods;
        let* stewards = find conn "stewards" Phrq.q_count_stewards_for_project project in
        Alcotest.(check int) "stewardship unchanged" 1 stewards;
        (* Redirected GET: the reviewed request is gone. *)
        let* response, body = get_queue ~cookie ~slug:"phhr-accept-home" pipeline in
        Pch.check_page "after PRG" response;
        let frag = ps_fragment body in
        Pch.must_not frag "action='/c/phhr-accept-home/projects/phhr-accept/accept'";
        Pch.must_not body "phhr accept note";
        Pch.must_not frag (Int64.to_string rid);
        (* No credential fixture rides in the page or redirect cookies. *)
        List.iter
          (fun (label, needle) ->
            Alcotest.(check bool) (label ^ " absent from page") false
              (goc_contains ~needle body);
            Alcotest.(check bool) (label ^ " absent from cookies") false
              (goc_contains ~needle redirect_cookies))
          credential_needles;
        (* Replay with a fresh CSRF token: 409 authoritative queue, no second
           review, exactly one durable relation. *)
        let* fresh = Pch.mint_token "replay mint" ~cookie pipeline in
        let* replay = do_post ~cookie ~target ~token:fresh pipeline in
        Alcotest.(check int) "replay 409" 409 (status_of replay);
        Alcotest.(check (option string)) "replay no-store" (Some "no-store")
          (Dream.header replay "Cache-Control");
        Alcotest.(check (option string)) "replay no redirect" None
          (Dream.header replay "Location");
        let* rbody = Dream.body replay in
        Pch.must rbody "That request is no longer pending.";
        let* status2 = status_of_relation conn rid in
        Alcotest.(check string) "still accepted" "accepted" status2;
        let* active = find conn "active" Phrq.q_count_active_for_project project in
        Alcotest.(check int) "one active row" 1 active;
        Lwt.return_unit)

  (* === POST reject: PRG frees the slot === *)

  let reject_prg_case =
    db_case "POST reject: PRG, relation rejected, slot freed, requester/note \
             and verification preserved" (fun ~url conn ->
        let* owner = insert_user conn "phhr_rowner" in
        let* reviewer = insert_user conn "phhr_rmod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000030L ~slug:"phhr-reject"
        in
        let* cid = insert_community ~name:"Phhr Reject Home" conn "phhr-reject-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-reject"
            ~community:cid ~note:"phhr reject note" ()
        in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* cookie, token, _body = open_queue "queue" ~slug:"phhr-reject-home" pipeline in
        let target = reject_target ~slug:"phhr-reject-home" ~project:"phhr-reject" in
        let* response = do_post ~cookie ~target ~token pipeline in
        let* () =
          Pch.check_redirect_lwt "rejected"
            "/c/phhr-reject-home/project-home-requests" response
        in
        let* ( ((_, _), (_, status)), ((req, rev), (note, _)) ) =
          find conn "relation row" Phrq.q_relation_row rid
        in
        Alcotest.(check string) "status rejected" "rejected" status;
        Alcotest.(check (option int)) "requester preserved" (Some owner) req;
        Alcotest.(check (option int)) "reviewer stored" (Some reviewer) rev;
        Alcotest.(check (option string)) "note preserved" (Some "phhr reject note") note;
        (* The active-home slot is free again. *)
        let* active = find conn "active" Phrq.q_count_active_for_project project in
        Alcotest.(check int) "no active row" 0 active;
        (* Project verification unchanged by a rejection. *)
        let* psig = find conn "project sig" Phrq.q_project_sig project in
        Alcotest.(check bool) "still verified" true (contains psig "verified");
        (* Redirected GET no longer lists it. *)
        let* response, body = get_queue ~cookie ~slug:"phhr-reject-home" pipeline in
        Pch.check_page "after PRG" response;
        Pch.must_not (ps_fragment body)
          "action='/c/phhr-reject-home/projects/phhr-reject/reject'";
        ignore rid;
        Lwt.return_unit)

  (* === Accept stale/revoked project: 409 Project_unavailable === *)

  let accept_stale_case =
    db_case "POST accept: project gone stale after GET is 409 \
             Project_unavailable; request stays; reject still works"
      (fun ~url conn ->
        let* owner = insert_user conn "phhr_stowner" in
        let* reviewer = insert_user conn "phhr_stmod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000040L ~slug:"phhr-stale"
        in
        let* cid = insert_community ~name:"Phhr Stale Home" conn "phhr-stale-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-stale"
            ~community:cid ()
        in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* cookie, token, _ = open_queue "queue" ~slug:"phhr-stale-home" pipeline in
        (* Verification drifts to stale between GET and POST. *)
        let* () = exec conn "stale" Phrq.q_set_verification (project, "stale") in
        let target = accept_target ~slug:"phhr-stale-home" ~project:"phhr-stale" in
        let* response = do_post ~cookie ~target ~token pipeline in
        Alcotest.(check int) "409" 409 (status_of response);
        Alcotest.(check (option string)) "no redirect" None
          (Dream.header response "Location");
        let* body = Dream.body response in
        Pch.must body "That project is no longer available for acceptance.";
        let frag = ps_fragment body in
        Pch.must frag "Verification stale";
        Pch.must_not frag "action='/c/phhr-stale-home/projects/phhr-stale/accept'";
        Pch.must frag "action='/c/phhr-stale-home/projects/phhr-stale/reject'";
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "still pending" "pending" status;
        (* Rejection of a stale project still succeeds. *)
        let* fresh = Pch.mint_token "reject mint" ~cookie pipeline in
        let rtarget = reject_target ~slug:"phhr-stale-home" ~project:"phhr-stale" in
        let* response = do_post ~cookie ~target:rtarget ~token:fresh pipeline in
        let* () =
          Pch.check_redirect_lwt "reject stale"
            "/c/phhr-stale-home/project-home-requests" response
        in
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "now rejected" "rejected" status;
        Lwt.return_unit)

  (* === Target becomes ineligible: accept 409 Target_ineligible, reject ok === *)

  let target_ineligible_case =
    db_case_lifecycle_relaxed "POST accept: target ineligible after GET is 409 Target_ineligible \
             with no reason leak; reject then succeeds" (fun ~url conn ->
        let* owner = insert_user conn "phhr_tiowner" in
        let* reviewer = insert_user conn "phhr_timod" in
        let* _, _ =
          make_project conn ~user:owner ~ext_id:946000050L ~slug:"phhr-ti"
        in
        let* cid = insert_community ~name:"Phhr TI Home" conn "phhr-ti-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-ti"
            ~community:cid ()
        in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* cookie, token, _ = open_queue "queue" ~slug:"phhr-ti-home" pipeline in
        (* Community goes private (a valid but ineligible host) after GET. *)
        let* () = exec conn "private" Phcv.q_make_private cid in
        let target = accept_target ~slug:"phhr-ti-home" ~project:"phhr-ti" in
        let* response = do_post ~cookie ~target ~token pipeline in
        Alcotest.(check int) "409" 409 (status_of response);
        let* body = Dream.body response in
        Pch.must body "This community cannot currently accept that project.";
        (* The specific ineligibility reason is never named. *)
        Pch.must_not body "private";
        Pch.must_not body "draft";
        Pch.must_not body "legacy";
        let frag = ps_fragment body in
        Pch.must_not frag "action='/c/phhr-ti-home/projects/phhr-ti/accept'";
        Pch.must frag "action='/c/phhr-ti-home/projects/phhr-ti/reject'";
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "still pending" "pending" status;
        (* Reject stays available on an ineligible target. *)
        let* fresh = Pch.mint_token "reject mint" ~cookie pipeline in
        let rtarget = reject_target ~slug:"phhr-ti-home" ~project:"phhr-ti" in
        let* response = do_post ~cookie ~target:rtarget ~token:fresh pipeline in
        let* () =
          Pch.check_redirect_lwt "reject ineligible"
            "/c/phhr-ti-home/project-home-requests" response
        in
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "now rejected" "rejected" status;
        Lwt.return_unit)

  (* === Concurrency by replay: accept-vs-reject, exactly one durable review === *)

  let concurrency_case =
    db_case "POST accept then reject: one winner, loser is 409, exactly one \
             durable review" (fun ~url conn ->
        let* owner = insert_user conn "phhr_cowner" in
        let* reviewer = insert_user conn "phhr_cmod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000060L ~slug:"phhr-conc"
        in
        let* cid = insert_community ~name:"Phhr Conc Home" conn "phhr-conc-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-conc"
            ~community:cid ()
        in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* cookie, token, _ = open_queue "queue" ~slug:"phhr-conc-home" pipeline in
        (* Accept wins. *)
        let atarget = accept_target ~slug:"phhr-conc-home" ~project:"phhr-conc" in
        let* response = do_post ~cookie ~target:atarget ~token pipeline in
        let* () =
          Pch.check_redirect_lwt "accept wins"
            "/c/phhr-conc-home/project-home-requests" response
        in
        (* A follow-up reject (fresh token) loses: no pending row remains. *)
        let* fresh = Pch.mint_token "reject mint" ~cookie pipeline in
        let rtarget = reject_target ~slug:"phhr-conc-home" ~project:"phhr-conc" in
        let* response = do_post ~cookie ~target:rtarget ~token:fresh pipeline in
        Alcotest.(check int) "loser 409" 409 (status_of response);
        let* body = Dream.body response in
        Pch.must body "That request is no longer pending.";
        (* Exactly one relation, accepted, one active slot. *)
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "final accepted" "accepted" status;
        let* total = find conn "total" Phrq.q_count_for_project project in
        Alcotest.(check int) "no duplicate relation" 1 total;
        let* active = find conn "active" Phrq.q_count_active_for_project project in
        Alcotest.(check int) "one active" 1 active;
        Lwt.return_unit)

  (* === Authorization lost between GET and POST === *)

  let authz_loss_case =
    db_case "POST: top-mod removed or admin revoked between GET and POST is a \
             generic 404 with no review" (fun ~url conn ->
        let* owner = insert_user conn "phhr_lowner" in
        let* top = insert_user conn "phhr_ltop" in
        let* admin = insert_user conn "phhr_ladmin" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000070L ~slug:"phhr-loss"
        in
        let* cid = insert_community ~name:"Phhr Loss Home" conn "phhr-loss-home" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        let* () = set_admin conn ~user:admin true in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-loss"
            ~community:cid ()
        in
        let target = accept_target ~slug:"phhr-loss-home" ~project:"phhr-loss" in
        (* Top-mod downgraded to mod after opening the queue. *)
        let tpipe = app_pipeline ~session_user_id:top ~url () in
        let* cookie, token, _ = open_queue "top queue" ~slug:"phhr-loss-home" tpipe in
        let* () = set_role conn ~user:top ~community:cid "mod" in
        let* response = do_post ~cookie ~target ~token tpipe in
        Alcotest.(check int) "downgraded top mod 404" 404 (status_of response);
        Alcotest.(check (option string)) "no redirect" None
          (Dream.header response "Location");
        let* body = Dream.body response in
        Pch.must body "This page does not exist.";
        Pch.must_not body "moderator";
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "still pending after downgrade" "pending" status;
        (* Durable admin revoked after opening the queue. *)
        let apipe = app_pipeline ~session_user_id:admin ~url () in
        let* cookie, token, _ = open_queue "admin queue" ~slug:"phhr-loss-home" apipe in
        let* () = set_admin conn ~user:admin false in
        let* response = do_post ~cookie ~target ~token apipe in
        Alcotest.(check int) "revoked admin 404" 404 (status_of response);
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "still pending after revoke" "pending" status;
        ignore project;
        Lwt.return_unit)

  (* === POST security: origin precedes form; empty-form rule is durable === *)

  let post_security_case =
    db_case "POST security: cross-origin rejected before the form; an \
             unexpected field never reaches the store" (fun ~url conn ->
        let* owner = insert_user conn "phhr_psowner" in
        let* reviewer = insert_user conn "phhr_psmod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000080L ~slug:"phhr-sec"
        in
        let* cid = insert_community ~name:"Phhr Sec Home" conn "phhr-sec-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-sec"
            ~community:cid ()
        in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* cookie, token, _ = open_queue "queue" ~slug:"phhr-sec-home" pipeline in
        let target = accept_target ~slug:"phhr-sec-home" ~project:"phhr-sec" in
        (* Cross-origin is a 403 before any form parse; no review. *)
        let* response =
          do_post ~origin:(Some "https://evil.example") ~cookie ~target ~token
            pipeline
        in
        Alcotest.(check int) "cross-origin 403" 403 (status_of response);
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "no review after origin reject" "pending" status;
        (* An unexpected application field is a 400 that never reviews. *)
        let headers =
          [ ("Origin", "https://earde.com");
            ("Content-Type", "application/x-www-form-urlencoded");
            ("Cookie", cookie);
          ]
        in
        let* response =
          pipeline
            (Dream.request ~method_:`POST ~target ~headers
               (Pch.form_body [ ("decision", "accept"); ("dream.csrf", token) ]))
        in
        Alcotest.(check int) "unexpected field 400" 400 (status_of response);
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "no review after 400" "pending" status;
        ignore project;
        Lwt.return_unit)

  (* === Storage and inconsistency collapse to a payload-free 500 === *)

  let get_storage_case =
    db_case "GET queue: a real database failure collapses to the generic 500"
      (fun ~url _conn ->
        let poisoned =
          Uri.to_string
            (Uri.add_query_param' (Uri.of_string url)
               ("options", "-csearch_path=phhr_void"))
        in
        let pipeline = app_pipeline ~session_user_id:42 ~url:poisoned () in
        let* response, body = get_queue ~slug:"phhr-anything" pipeline in
        Alcotest.(check int) "500" 500 (status_of response);
        Alcotest.(check (option string)) "no-store" (Some "no-store")
          (Dream.header response "Cache-Control");
        Pch.must body "Something went wrong on our side.";
        List.iter (Pch.must_not body)
          [ "phhr_void"; "search_path"; "PostgreSQL"; "Caqti"; "relation" ];
        Lwt.return_unit)

  let get_inconsistent_case =
    db_case_lifecycle_relaxed "GET queue: durable community corruption is one generic 500"
      (fun ~url conn ->
        let* reviewer = insert_user conn "phhr_icmod" in
        (* Published public network community with indexable <> discoverable:
           a leaking shape the read model reports as corruption. *)
        let* cid =
          insert_community ~indexable:true ~discoverable:false conn "phhr-ic"
        in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let pipeline = app_pipeline ~session_user_id:reviewer ~url () in
        let* response, body = get_queue ~slug:"phhr-ic" pipeline in
        Alcotest.(check int) "500" 500 (status_of response);
        Pch.must body "Something went wrong on our side.";
        List.iter (Pch.must_not body)
          [ "Inconsistent"; "indexable"; "discoverable"; "Caqti" ];
        Lwt.return_unit)

  let post_storage_case =
    db_case "POST accept: a review-store database failure is the generic 500, \
             no partial review" (fun ~url conn ->
        let* owner = insert_user conn "phhr_pstowner" in
        let* reviewer = insert_user conn "phhr_pstmod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:946000090L ~slug:"phhr-pst"
        in
        let* cid = insert_community ~name:"Phhr Pst Home" conn "phhr-pst-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          request_pending "pending" conn ~user:owner ~slug:"phhr-pst"
            ~community:cid ()
        in
        (* One poisoned pipeline throughout: /mint touches no SQL (it only
           mints a session-bound CSRF token), so the session cookie and
           token establish here, and the accept POST then fails only inside
           the review store's SQL — the handler collapses it payload-free. *)
        let poisoned =
          Uri.to_string
            (Uri.add_query_param' (Uri.of_string url)
               ("options", "-csearch_path=phhr_void"))
        in
        let poison_pipe = app_pipeline ~session_user_id:reviewer ~url:poisoned () in
        let* mint_response, mint_body = Pch.do_get ~target:"/mint" poison_pipe in
        Alcotest.(check int) "mint 200" 200 (status_of mint_response);
        let cookie = Pch.session_cookie "poison mint" mint_response in
        let token = mint_body in
        let target = accept_target ~slug:"phhr-pst-home" ~project:"phhr-pst" in
        let* response = do_post ~cookie ~target ~token poison_pipe in
        Alcotest.(check int) "500" 500 (status_of response);
        Alcotest.(check (option string)) "no-store" (Some "no-store")
          (Dream.header response "Cache-Control");
        let* body = Dream.body response in
        Pch.must body "Something went wrong on our side.";
        List.iter (Pch.must_not body)
          [ "phhr_void"; "search_path"; "Caqti"; "PostgreSQL" ];
        (* No partial review committed. *)
        let* status = status_of_relation conn rid in
        Alcotest.(check string) "still pending" "pending" status;
        ignore project;
        Lwt.return_unit)

  (* === Suites === *)

  let nav_suite = nav_cases
  let get_gate_suite = get_gate_cases
  let post_gate_suite = post_gate_cases
  let csrf_suite = csrf_cases
  let db_suite =
    [ get_authz_case; get_states_case; accept_prg_case; reject_prg_case;
      accept_stale_case; target_ineligible_case; concurrency_case;
      authz_loss_case; post_security_case; get_storage_case;
      get_inconsistent_case; post_storage_case ]
end

(* === Community connected-projects read model
   (Community_connected_projects_read_model) ===
   The accepted project-home relations of one community, read for the
   "Connected projects" section of the existing community page. Accepted
   relations are produced through the real chain wherever the product has one
   — draft/selection/finalization for the project, the request store plus the
   transactional review store for a reviewed acceptance — and only an
   automatically provisioned home (which no store writes yet) uses a
   schema-valid production-shaped INSERT. Database-gated
   (EARDE_TEST_DATABASE_URL, same opt-in as Mod_scope) with its own reserved
   external-installation-id range 946200001..946200999 (hence account ids
   946300001..946300999, which also scope the permanent-project cleanup),
   ccpr_% usernames, and ccpr-% community slugs so no suite shares fixtures.
   Pure validation is proven pre-SQL against a deliberately disconnected
   connection. Every per-case wrapper disconnects deterministically. *)
module Ccpr = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Cp = Earde.Community_connected_projects_read_model
  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store
  module Fin = Earde.Project_finalization_store

  let error_str : Cp.error -> string = function
    | Cp.Invalid_community_slug -> "Invalid_community_slug"
    | Cp.Community_unavailable -> "Community_unavailable"
    | Cp.Inconsistent_data -> "Inconsistent_data"
    | Cp.Storage_error -> "Storage_error"

  let verification_str : Cp.verification -> string = function
    | Cp.Verified -> "verified"
    | Cp.Stale -> "stale"
    | Cp.Revoked -> "revoked"

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let insert_community = Phcv.insert_community

  (* Distinctive credential-shaped fixtures. None of these may ever reach a
     value the public API returns; assertions on them are boolean so no
     fixture byte reaches test output on failure. *)
  let private_note = "ccpr private note ACCESS_TOKEN_gho_ccpr_secret"

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 946300001 AND 946300999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 946300001 AND 946300999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 946200001 AND 946200999)"
      ; "DELETE FROM communities WHERE slug LIKE 'ccpr-%'"
      ; "DELETE FROM users WHERE username LIKE 'ccpr_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 946200001 AND 946200999"
      ]

  (* An automatically provisioned accepted home: no requester and no reviewer,
     exactly the shape the production status CHECK admits for 'accepted'. No
     store writes this yet, so the row is built directly rather than through a
     test-only constructor. *)
  let q_provision_accepted =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at) \
     VALUES ($1, $2, 'home', 'accepted', NOW())"

  (* A historical removed relation — reviewed and removed, outside the
     one-active-home partial index, so it coexists with nothing active. *)
  let q_insert_removed =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at, \
        removed_at) \
     VALUES ($1, $2, 'home', 'removed', NOW(), NOW())"

  let q_insert_moderator =
    (Caqti_type.(t3 int int string) ->. Caqti_type.unit)
    "INSERT INTO community_moderators (user_id, community_id, role) \
     VALUES ($1, $2, $3)"

  let q_delete_project =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM open_source_projects WHERE id = $1"

  (* Audit history deliberately blocks subject deletion (no cascade on
     project_home_audit_events); a case that deletes a project after real
     lifecycle events must purge its trail explicitly first. *)
  let q_delete_audit_trail =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM project_home_audit_events WHERE project_id = $1"

  (* Targeted durable corruption that the production CHECKs already admit:
     forge_namespace_login only constrains btrim/length, website_url only
     constrains btrim/non-empty/length, html_url only btrim<>'', and position
     only > 0 with a per-project uniqueness rule. *)
  let q_corrupt_login =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET forge_namespace_login = 'ccpr' || chr(1) || 'bad' WHERE id = $1"

  let q_restore_login =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET forge_namespace_login = 'pfin-owner' WHERE id = $1"

  let q_corrupt_name =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET name = 'ccpr' || chr(1) || 'bad' WHERE id = $1"

  let q_set_name =
    (Caqti_type.(t2 int64 string) ->. Caqti_type.unit)
    "UPDATE open_source_projects SET name = $2 WHERE id = $1"

  let q_corrupt_website =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET website_url = 'javascript:alert(1)' WHERE id = $1"

  let q_clear_website =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects SET website_url = NULL WHERE id = $1"

  let q_corrupt_repo_url =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE project_repositories \
     SET html_url = 'https://evil.example/x' WHERE project_id = $1 \
       AND position = 1"

  let q_restore_repo_url =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE project_repositories \
     SET html_url = 'https://github.com/pfin-owner/alpha' \
     WHERE project_id = $1 AND position = 1"

  let q_break_positions =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE project_repositories SET position = 7 \
     WHERE project_id = $1 AND position = 2"

  let q_delete_repos =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM project_repositories WHERE project_id = $1"

  (* Two production constraints make their defensive read-model branches
     unreachable from data alone. Each is dropped and restored inside the one
     case that needs it, under Lwt.finalize so a failed assertion still leaves
     the schema exactly as it was; production migrations are untouched. *)
  let q_drop_verification_check =
    (Caqti_type.unit ->. Caqti_type.unit)
    "ALTER TABLE open_source_projects \
     DROP CONSTRAINT open_source_projects_verification_status_check"

  let q_add_verification_check =
    (Caqti_type.unit ->. Caqti_type.unit)
    "ALTER TABLE open_source_projects \
     ADD CONSTRAINT open_source_projects_verification_status_check \
     CHECK (verification_status IN ('verified', 'stale', 'revoked'))"

  let q_set_verification =
    (Caqti_type.(t2 int64 string) ->. Caqti_type.unit)
    "UPDATE open_source_projects SET verification_status = $2 WHERE id = $1"

  let q_drop_full_name_key =
    (Caqti_type.unit ->. Caqti_type.unit)
    "ALTER TABLE project_repositories \
     DROP CONSTRAINT project_repositories_project_full_name_key"

  let q_add_full_name_key =
    (Caqti_type.unit ->. Caqti_type.unit)
    "ALTER TABLE project_repositories \
     ADD CONSTRAINT project_repositories_project_full_name_key \
     UNIQUE (project_id, full_name)"

  let q_duplicate_full_name =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE project_repositories \
     SET full_name = 'pfin-owner/alpha', \
         html_url = 'https://github.com/pfin-owner/alpha' \
     WHERE project_id = $1 AND position = 2"

  (* Emptying search_path hides the unqualified tables, so the first query
     fails at the SQL layer and Caqti returns an Error the read model maps to
     Storage_error — a genuine query failure, not a torn-down connection
     (which the driver signals by raising, not by Error). *)
  let q_break_search_path =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO ''"

  let q_reset_search_path =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO public"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f conn))

  (* === call helpers === *)

  let load conn ~community = Cp.load_for_community conn ~community_slug:community

  let load_ok label conn ~community =
    let* r = load conn ~community in
    match r with
    | Ok projects -> Lwt.return projects
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_expect label expected conn ~community =
    let* r = load conn ~community in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  let slugs projects = List.map Cp.project_slug projects

  let check_slugs label expected projects =
    Alcotest.(check (list string)) label expected (slugs projects)

  (* === fixtures === *)

  (* Verified permanent projects come only through the real chain — draft
     store, selection store, finalization store — never fixture INSERTs. *)
  let make_project ?kind ?name ?website ?(repos = [ "alpha" ]) conn ~user
      ~ext_id ~slug =
    let base = Int64.add ext_id 400000L in
    let* _inst, draft, _, _ =
      Pfin.make_draft conn ~user ~ext_id (fun account_id ->
          List.mapi
            (fun i n ->
              Pfin.repo ~account_id ~id:(Int64.add base (Int64.of_int i)) n)
            repos)
    in
    let* ids = Pfin.snapshot_ids conn draft in
    let primary = List.nth ids 0 in
    let* () =
      Pod_select.replace_ok "seed selection" conn ~user ~draft ~primary ids
    in
    let identity =
      Pfin.identity_exn ?kind ?name ~slug ?website ~selected:ids ~primary ()
    in
    let* created = Pfin.finalize_ok "fixture project" conn ~user ~draft identity in
    Lwt.return (Fin.project_id created)

  let add_top_mod conn ~user ~community =
    exec conn "top_mod fixture" q_insert_moderator (user, community, "top_mod")

  let request_pending label conn ~user ~slug ~community ?(note = private_note) () =
    let relation = phr_expect_ok (Phr.create_pending ~request_note:(Some note)) in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: request fixture failed" label

  let review label conn ~reviewer ~slug ~community_slug ~decision =
    let* r =
      Rvs.review conn ~reviewer_user_id:reviewer ~project_slug:slug
        ~target_community_slug:community_slug ~decision
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: review fixture failed" label

  (* A reviewed acceptance, end to end through the real stores. *)
  let accept_reviewed label conn ~owner ~reviewer ~slug ~cid ~community_slug =
    let* () = request_pending label conn ~user:owner ~slug ~community:cid () in
    review label conn ~reviewer ~slug ~community_slug ~decision:Rvs.Accept

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "connected projects: invalid slugs rejected before any SQL"
      (fun _conn ->
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        (* A disconnected connection cannot answer a query, so every one of
           these returning Invalid_community_slug proves the check precedes
           SQL. *)
        Lwt_list.iter_s
          (fun bad ->
            load_expect "invalid community slug" Cp.Invalid_community_slug dead
              ~community:bad)
          [ ""
          ; "ccpr c"
          ; " ccpr-c"
          ; "ccpr-c "
          ; "ccpr/c"
          ; "ccpr\tc"
          ; "ccpr\nc"
          ; "ccpr\x01c"
          ; "ccpr\x7fc"
          ])

  (* === community existence === *)

  let missing_community_case =
    db_case "connected projects: a community that does not exist is \
             Community_unavailable; an existing one with no relations is empty"
      (fun conn ->
        let* () =
          load_expect "missing" Cp.Community_unavailable conn
            ~community:"ccpr-nope"
        in
        let* _cid = insert_community conn "ccpr-empty" in
        let* projects = load_ok "empty" conn ~community:"ccpr-empty" in
        Alcotest.(check int) "no connected projects" 0 (List.length projects);
        (* A community whose projects were all deleted returns to empty rather
           than to an error. *)
        Lwt.return_unit)

  (* === accepted relation selection === *)

  let reviewed_accept_case =
    db_case "connected projects: one moderator-reviewed accepted home is \
             visible in full, carrying no requester, reviewer, or note"
      (fun conn ->
        let* owner = insert_user conn "ccpr_owner" in
        let* moderator = insert_user conn "ccpr_mod" in
        let* _project =
          make_project conn ~user:owner ~ext_id:946200001L ~slug:"ccpr-rev"
            ~name:"Ccpr Reviewed" ~website:"https://reviewed.example/"
        in
        let* cid = insert_community conn "ccpr-rev-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "reviewed accept" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-rev" ~cid ~community_slug:"ccpr-rev-home"
        in
        let* projects = load_ok "reviewed" conn ~community:"ccpr-rev-home" in
        Alcotest.(check int) "one project" 1 (List.length projects);
        let p = List.hd projects in
        Alcotest.(check string) "name" "Ccpr Reviewed" (Cp.project_name p);
        Alcotest.(check string) "slug" "ccpr-rev" (Cp.project_slug p);
        Alcotest.(check string) "verification" "verified"
          (verification_str (Cp.project_verification p));
        Alcotest.(check string) "namespace" "pfin-owner"
          (Cp.project_namespace_login p);
        Alcotest.(check (option string)) "website"
          (Some "https://reviewed.example/") (Cp.project_website_url p);
        let repos = Cp.project_repositories p in
        Alcotest.(check int) "one repository" 1 (List.length repos);
        Alcotest.(check string) "repository full name" "pfin-owner/alpha"
          (Cp.repository_full_name (List.hd repos));
        Alcotest.(check string) "repository url"
          "https://github.com/pfin-owner/alpha"
          (Cp.repository_html_url (List.hd repos));
        Alcotest.(check bool) "repository primary" true
          (Cp.repository_is_primary (List.hd repos));
        Alcotest.(check bool) "repository archived" false
          (Cp.repository_is_archived (List.hd repos));
        (* Nothing private or provenance-shaped can be reached through the
           public API: boolean only, so no fixture byte is printed. *)
        let exposed =
          String.concat "\n"
            ([ Cp.project_name p; Cp.project_slug p;
               Cp.project_namespace_login p;
               Option.value ~default:"" (Cp.project_website_url p) ]
            @ List.concat_map
                (fun r -> [ Cp.repository_full_name r; Cp.repository_html_url r ])
                repos)
        in
        List.iter
          (fun (label, needle) ->
            Alcotest.(check bool) label false (contains exposed needle))
          [ ("no private note", private_note)
          ; ("no requester name", "ccpr_owner")
          ; ("no reviewer name", "ccpr_mod")
          ; ("no external installation id", "946200001")
          ; ("no external account id", "946300001")
          ; ("no external repository id", "946600001")
          ];
        Lwt.return_unit)

  let provisioned_accept_case =
    db_case "connected projects: a provisioned accepted home with NULL \
             requester and reviewer appears exactly like a reviewed one"
      (fun conn ->
        let* owner = insert_user conn "ccpr_prov_owner" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200002L ~slug:"ccpr-prov"
            ~name:"Ccpr Provisioned"
        in
        let* cid = insert_community conn "ccpr-prov-home" in
        let* () =
          exec conn "provisioned accept" q_provision_accepted (project, cid)
        in
        let* projects = load_ok "provisioned" conn ~community:"ccpr-prov-home" in
        check_slugs "provisioned visible" [ "ccpr-prov" ] projects;
        Alcotest.(check string) "verification" "verified"
          (verification_str (Cp.project_verification (List.hd projects)));
        Alcotest.(check (option string)) "no website" None
          (Cp.project_website_url (List.hd projects));
        Lwt.return_unit)

  let excluded_statuses_case =
    db_case "connected projects: pending, rejected and removed relations are \
             all excluded"
      (fun conn ->
        let* owner = insert_user conn "ccpr_ex_owner" in
        let* moderator = insert_user conn "ccpr_ex_mod" in
        let* _pending =
          make_project conn ~user:owner ~ext_id:946200010L ~slug:"ccpr-pend"
        in
        let* _rejected =
          make_project conn ~user:owner ~ext_id:946200011L ~slug:"ccpr-rej"
        in
        let* removed =
          make_project conn ~user:owner ~ext_id:946200012L ~slug:"ccpr-rem"
        in
        let* _accepted =
          make_project conn ~user:owner ~ext_id:946200013L ~slug:"ccpr-acc"
        in
        let* cid = insert_community conn "ccpr-ex-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        (* pending: created and deliberately left unreviewed *)
        let* () =
          request_pending "pending" conn ~user:owner ~slug:"ccpr-pend"
            ~community:cid ()
        in
        (* rejected: through the real review store *)
        let* () =
          request_pending "reject seed" conn ~user:owner ~slug:"ccpr-rej"
            ~community:cid ()
        in
        let* () =
          review "reject" conn ~reviewer:moderator ~slug:"ccpr-rej"
            ~community_slug:"ccpr-ex-home" ~decision:Rvs.Reject
        in
        (* removed: a historical row, outside the active-home index *)
        let* () = exec conn "removed row" q_insert_removed (removed, cid) in
        (* accepted: the only one that must appear *)
        let* () =
          accept_reviewed "accept" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-acc" ~cid ~community_slug:"ccpr-ex-home"
        in
        let* projects = load_ok "excluded" conn ~community:"ccpr-ex-home" in
        check_slugs "only the accepted relation" [ "ccpr-acc" ] projects;
        Lwt.return_unit)

  (* === ordering === *)

  let ordering_case =
    db_case "connected projects: deterministic lower(name), slug, id order — \
             never acceptance time"
      (fun conn ->
        let* owner = insert_user conn "ccpr_ord_owner" in
        let* moderator = insert_user conn "ccpr_ord_mod" in
        let* cid = insert_community conn "ccpr-ord-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        (* Accepted in an order that contradicts the required output order,
           and with a case mix that only lower(name) resolves. *)
        let* _ =
          make_project conn ~user:owner ~ext_id:946200020L ~slug:"ccpr-ord-z"
            ~name:"zulu tool"
        in
        let* _ =
          make_project conn ~user:owner ~ext_id:946200021L ~slug:"ccpr-ord-a"
            ~name:"Alpha tool"
        in
        let* _ =
          make_project conn ~user:owner ~ext_id:946200022L ~slug:"ccpr-ord-m"
            ~name:"middle tool"
        in
        let* () =
          accept_reviewed "z" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-ord-z" ~cid ~community_slug:"ccpr-ord-home"
        in
        let* () =
          accept_reviewed "a" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-ord-a" ~cid ~community_slug:"ccpr-ord-home"
        in
        let* () =
          accept_reviewed "m" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-ord-m" ~cid ~community_slug:"ccpr-ord-home"
        in
        let* projects = load_ok "ordering" conn ~community:"ccpr-ord-home" in
        check_slugs "lower(name) order, not acceptance order"
          [ "ccpr-ord-a"; "ccpr-ord-m"; "ccpr-ord-z" ] projects;
        Lwt.return_unit)

  let name_tiebreak_case =
    db_case "connected projects: identical names fall through to the slug \
             tiebreaker"
      (fun conn ->
        let* owner = insert_user conn "ccpr_tie_owner" in
        let* moderator = insert_user conn "ccpr_tie_mod" in
        let* cid = insert_community conn "ccpr-tie-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* _ =
          make_project conn ~user:owner ~ext_id:946200030L ~slug:"ccpr-tie-b"
            ~name:"Same Name"
        in
        let* _ =
          make_project conn ~user:owner ~ext_id:946200031L ~slug:"ccpr-tie-a"
            ~name:"Same Name"
        in
        let* () =
          accept_reviewed "b" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-tie-b" ~cid ~community_slug:"ccpr-tie-home"
        in
        let* () =
          accept_reviewed "a" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-tie-a" ~cid ~community_slug:"ccpr-tie-home"
        in
        let* projects = load_ok "tiebreak" conn ~community:"ccpr-tie-home" in
        check_slugs "slug tiebreaker" [ "ccpr-tie-a"; "ccpr-tie-b" ] projects;
        Lwt.return_unit)

  let repository_order_case =
    db_case "connected projects: repositories keep stored position order"
      (fun conn ->
        let* owner = insert_user conn "ccpr_repo_owner" in
        let* moderator = insert_user conn "ccpr_repo_mod" in
        let* _project =
          make_project conn ~user:owner ~ext_id:946200040L ~slug:"ccpr-repos"
            ~repos:[ "alpha"; "beta"; "gamma" ]
        in
        let* cid = insert_community conn "ccpr-repos-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "repos" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-repos" ~cid ~community_slug:"ccpr-repos-home"
        in
        let* projects = load_ok "repos" conn ~community:"ccpr-repos-home" in
        let repos = Cp.project_repositories (List.hd projects) in
        Alcotest.(check (list string)) "position order"
          [ "pfin-owner/alpha"; "pfin-owner/beta"; "pfin-owner/gamma" ]
          (List.map Cp.repository_full_name repos);
        Alcotest.(check int) "exactly one primary" 1
          (List.length (List.filter Cp.repository_is_primary repos));
        Lwt.return_unit)

  (* === lifecycle === *)

  let verification_mapping_case =
    db_case "connected projects: verified, stale and revoked all stay visible \
             and map exactly"
      (fun conn ->
        let* owner = insert_user conn "ccpr_ver_owner" in
        let* moderator = insert_user conn "ccpr_ver_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200050L ~slug:"ccpr-ver"
        in
        let* cid = insert_community conn "ccpr-ver-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "ver" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-ver" ~cid ~community_slug:"ccpr-ver-home"
        in
        Lwt_list.iter_s
          (fun (stored, expected) ->
            let* () =
              exec conn "set verification" q_set_verification (project, stored)
            in
            let* projects = load_ok stored conn ~community:"ccpr-ver-home" in
            Alcotest.(check int) (stored ^ ": still visible") 1
              (List.length projects);
            Alcotest.(check string) (stored ^ ": mapping") expected
              (verification_str (Cp.project_verification (List.hd projects)));
            Lwt.return_unit)
          [ ("verified", "verified"); ("stale", "stale"); ("revoked", "revoked") ])

  let community_drift_case =
    db_case_lifecycle_relaxed "connected projects: public, unlisted and drifted (private, draft, \
             legacy) target communities all keep the accepted relation"
      (fun conn ->
        let* owner = insert_user conn "ccpr_drift_owner" in
        let* moderator = insert_user conn "ccpr_drift_mod" in
        let* _project =
          make_project conn ~user:owner ~ext_id:946200060L ~slug:"ccpr-drift"
        in
        let* cid = insert_community conn "ccpr-drift-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "drift" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-drift" ~cid ~community_slug:"ccpr-drift-home"
        in
        let expect_visible label =
          let* projects = load_ok label conn ~community:"ccpr-drift-home" in
          check_slugs (label ^ ": still connected") [ "ccpr-drift" ] projects;
          Lwt.return_unit
        in
        let* () = expect_visible "public listed" in
        let* () = exec conn "unlisted" Phcv.q_make_unlisted cid in
        let* () = expect_visible "unlisted" in
        let* () = exec conn "listed again" Phcv.q_make_listed cid in
        let* () = exec conn "private" Phcv.q_make_private cid in
        let* () = expect_visible "private drift" in
        let* () = exec conn "draft" Phcv.q_make_draft_state cid in
        let* () = expect_visible "draft drift" in
        let* () = exec conn "legacy" Phcv.q_make_legacy cid in
        expect_visible "legacy drift")

  let cascade_case =
    db_case "connected projects: deleting the project cascades the relation \
             away"
      (fun conn ->
        let* owner = insert_user conn "ccpr_casc_owner" in
        let* moderator = insert_user conn "ccpr_casc_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200070L ~slug:"ccpr-casc"
        in
        let* cid = insert_community conn "ccpr-casc-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "casc" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-casc" ~cid ~community_slug:"ccpr-casc-home"
        in
        let* before = load_ok "before" conn ~community:"ccpr-casc-home" in
        Alcotest.(check int) "connected before delete" 1 (List.length before);
        (* The lifecycle audit trail RESTRICT-protects the project row; the
           explicit purge here is the deliberate step the FK now demands. *)
        let* () =
          exec conn "purge audit trail" q_delete_audit_trail project
        in
        let* () = exec conn "delete project" q_delete_project project in
        let* after = load_ok "after" conn ~community:"ccpr-casc-home" in
        Alcotest.(check int) "gone after delete" 0 (List.length after);
        Lwt.return_unit)

  (* === website === *)

  let website_case =
    db_case "connected projects: an absent website is None, a present one is \
             byte-preserved, and one outside the permanent grammar is \
             Inconsistent_data"
      (fun conn ->
        let* owner = insert_user conn "ccpr_web_owner" in
        let* moderator = insert_user conn "ccpr_web_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200080L ~slug:"ccpr-web"
            ~website:"https://example.test/path?q=1#frag"
        in
        let* cid = insert_community conn "ccpr-web-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "web" conn ~owner ~reviewer:moderator ~slug:"ccpr-web"
            ~cid ~community_slug:"ccpr-web-home"
        in
        let* projects = load_ok "website" conn ~community:"ccpr-web-home" in
        Alcotest.(check (option string)) "byte-preserved"
          (Some "https://example.test/path?q=1#frag")
          (Cp.project_website_url (List.hd projects));
        let* () = exec conn "clear website" q_clear_website project in
        let* projects = load_ok "no website" conn ~community:"ccpr-web-home" in
        Alcotest.(check (option string)) "absent" None
          (Cp.project_website_url (List.hd projects));
        let* () = exec conn "corrupt website" q_corrupt_website project in
        load_expect "non-http website" Cp.Inconsistent_data conn
          ~community:"ccpr-web-home")

  (* === durable corruption === *)

  let identity_corruption_case =
    db_case "connected projects: malformed project identity is \
             Inconsistent_data, never a silently dropped project"
      (fun conn ->
        let* owner = insert_user conn "ccpr_corr_owner" in
        let* moderator = insert_user conn "ccpr_corr_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200090L ~slug:"ccpr-corr"
            ~name:"Ccpr Corrupt"
        in
        let* cid = insert_community conn "ccpr-corr-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "corr" conn ~owner ~reviewer:moderator
            ~slug:"ccpr-corr" ~cid ~community_slug:"ccpr-corr-home"
        in
        let* () = exec conn "corrupt login" q_corrupt_login project in
        let* () =
          load_expect "control byte in namespace login" Cp.Inconsistent_data
            conn ~community:"ccpr-corr-home"
        in
        let* () = exec conn "restore login" q_restore_login project in
        let* () = exec conn "corrupt name" q_corrupt_name project in
        let* () =
          load_expect "control byte in project name" Cp.Inconsistent_data conn
            ~community:"ccpr-corr-home"
        in
        let* () = exec conn "restore name" q_set_name (project, "Ccpr Corrupt") in
        let* projects = load_ok "restored" conn ~community:"ccpr-corr-home" in
        check_slugs "restored" [ "ccpr-corr" ] projects;
        Lwt.return_unit)

  let repository_corruption_case =
    db_case "connected projects: a malformed or missing repository set fails \
             the whole read"
      (fun conn ->
        let* owner = insert_user conn "ccpr_rc_owner" in
        let* moderator = insert_user conn "ccpr_rc_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200100L ~slug:"ccpr-rc"
            ~repos:[ "alpha"; "beta" ]
        in
        let* cid = insert_community conn "ccpr-rc-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "rc" conn ~owner ~reviewer:moderator ~slug:"ccpr-rc"
            ~cid ~community_slug:"ccpr-rc-home"
        in
        let* () = exec conn "corrupt repo url" q_corrupt_repo_url project in
        let* () =
          load_expect "non-canonical repository URL" Cp.Inconsistent_data conn
            ~community:"ccpr-rc-home"
        in
        let* () = exec conn "restore repo url" q_restore_repo_url project in
        let* () = exec conn "break positions" q_break_positions project in
        let* () =
          load_expect "non-contiguous positions" Cp.Inconsistent_data conn
            ~community:"ccpr-rc-home"
        in
        let* () = exec conn "delete repos" q_delete_repos project in
        load_expect "zero repositories" Cp.Inconsistent_data conn
          ~community:"ccpr-rc-home")

  (* The per-project full-name uniqueness constraint makes this branch
     unreachable from data alone, so the constraint is dropped and restored
     around the assertion; Lwt.finalize restores it even if the check fails. *)
  let duplicate_repository_case =
    db_case "connected projects: duplicate repository full names within one \
             project are Inconsistent_data"
      (fun conn ->
        let* owner = insert_user conn "ccpr_dup_owner" in
        let* moderator = insert_user conn "ccpr_dup_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200110L ~slug:"ccpr-dup"
            ~repos:[ "alpha"; "beta" ]
        in
        let* cid = insert_community conn "ccpr-dup-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "dup" conn ~owner ~reviewer:moderator ~slug:"ccpr-dup"
            ~cid ~community_slug:"ccpr-dup-home"
        in
        let* () = exec conn "drop full-name key" q_drop_full_name_key () in
        Lwt.finalize
          (fun () ->
            let* () =
              exec conn "duplicate full name" q_duplicate_full_name project
            in
            load_expect "duplicate repository full name" Cp.Inconsistent_data
              conn ~community:"ccpr-dup-home")
          (fun () ->
            (* Remove the duplicate before restoring the unique constraint. *)
            let* () = exec conn "delete repos" q_delete_repos project in
            exec conn "restore full-name key" q_add_full_name_key ()))

  (* Same shape: the production CHECK closes the verification vocabulary, so
     the off-enum branch needs the constraint lifted for the length of one
     assertion. *)
  let malformed_status_case =
    db_case "connected projects: an off-enum project verification status is \
             Inconsistent_data"
      (fun conn ->
        let* owner = insert_user conn "ccpr_st_owner" in
        let* moderator = insert_user conn "ccpr_st_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:946200120L ~slug:"ccpr-st"
        in
        let* cid = insert_community conn "ccpr-st-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "st" conn ~owner ~reviewer:moderator ~slug:"ccpr-st"
            ~cid ~community_slug:"ccpr-st-home"
        in
        let* () = exec conn "drop verification check" q_drop_verification_check () in
        Lwt.finalize
          (fun () ->
            let* () =
              exec conn "off-enum status" q_set_verification (project, "unknown")
            in
            load_expect "off-enum verification status" Cp.Inconsistent_data conn
              ~community:"ccpr-st-home")
          (fun () ->
            let* () =
              exec conn "restore status" q_set_verification (project, "verified")
            in
            exec conn "restore verification check" q_add_verification_check ()))

  let storage_error_case =
    db_case "connected projects: storage failure surfaces as Storage_error"
      (fun conn ->
        let* () = exec conn "break search_path" q_break_search_path () in
        let* () =
          load_expect "broken schema" Cp.Storage_error conn
            ~community:"ccpr-anything"
        in
        exec conn "reset search_path" q_reset_search_path ())

  let suite =
    [ pure_inputs_case; missing_community_case; reviewed_accept_case;
      provisioned_accept_case; excluded_statuses_case; ordering_case;
      name_tiebreak_case; repository_order_case; verification_mapping_case;
      community_drift_case; cascade_case; website_case;
      identity_corruption_case; repository_corruption_case;
      duplicate_repository_case; malformed_status_case; storage_error_case ]
end

(* === Community connected-projects section (Community_connected_projects_pages) ===
   The pure fragment composed into the existing community page: section copy,
   verification and kind vocabulary, link safety, defensive degradation, and
   the absence of officiality language, identifiers, and private workflow
   data. DB-free — the renderer depends on no connection, no read model, and
   no session. Privacy assertions are boolean, so no fixture byte reaches test
   output on failure. *)
module Ccpp = struct
  module Ccp = Earde.Community_connected_projects_pages
  module Pi = Earde.Project_identity

  let case = go_case

  let repo ?(primary = false) ?(archived = false) ?url full_name =
    ({ full_name;
       html_url =
         (match url with
          | Some u -> u
          | None -> "https://github.com/" ^ full_name);
       is_primary = primary;
       is_archived = archived }
      : Ccp.repository)

  let project ?(kind = Pi.Project) ?(name = "Ccpp Project")
      ?(slug = "ccpp-project") ?(login = "ccpp-owner")
      ?(verification = Ccp.Verified) ?website ?repositories () =
    ({ name;
       slug;
       kind;
       namespace_login = login;
       verification;
       website_url = website;
       repositories =
         (match repositories with
          | Some r -> r
          | None -> [ repo ~primary:true "ccpp-owner/alpha" ]) }
      : Ccp.project)

  let render projects = Ccp.connected_projects_section ~projects

  let one ?kind ?name ?slug ?login ?verification ?website ?repositories () =
    render [ project ?kind ?name ?slug ?login ?verification ?website ?repositories () ]

  (* Wording that would misrepresent an accepted home as an endorsement. *)
  let forbidden_officiality =
    [ "Official project"; "Official community"; "Official home";
      "GitHub-approved"; "GitHub-endorsed"; "Official" ]

  let check_no_officiality label html =
    List.iter
      (fun needle ->
        Alcotest.(check bool)
          (label ^ ": no " ^ needle)
          false (contains html needle))
      forbidden_officiality

  (* Inertness is asserted structurally, not by substring: hostile input is
     deliberately rendered as escaped TEXT, so a fixture that contains the
     bytes "javascript:" or "onerror=" may legitimately appear in the output.
     What must never happen is that any of it becomes markup. Every '<' in the
     output therefore has to open one of the renderer's own tags — which
     leaves no way to introduce a script, an iframe, an inline style, or an
     event handler — and no attribute may carry a script-bearing URL. *)
  let allowed_tags =
    [ "section"; "/section"; "div"; "/div"; "h2"; "/h2"; "h3"; "/h3"; "p";
      "/p"; "ul"; "/ul"; "li"; "/li"; "a"; "/a"; "span"; "/span" ]

  let check_only_safe_tags label html =
    let n = String.length html in
    let rec go i =
      if i >= n then ()
      else if html.[i] <> '<' then go (i + 1)
      else begin
        let rest = String.sub html (i + 1) (n - i - 1) in
        let ok =
          List.exists
            (fun tag ->
              let t = String.length tag in
              String.length rest >= t
              && String.sub rest 0 t = tag
              && (String.length rest = t
                  || (let c = rest.[t] in
                      c = ' ' || c = '>')))
            allowed_tags
        in
        Alcotest.(check bool)
          (label ^ ": every '<' opens a renderer-authored tag")
          true ok;
        go (i + 1)
      end
    in
    go 0

  let check_no_script_urls label html =
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no " ^ needle) false
          (contains html needle))
      [ "href='javascript:"; "href=\"javascript:"; "href='data:";
        "href='vbscript:"; "href='#'"; "src='javascript:"; "style=" ]

  let check_inert label html =
    check_only_safe_tags label html;
    check_no_script_urls label html

  let empty_cases =
    [ case "connected projects: an empty list renders the empty fragment"
        (fun () ->
          Alcotest.(check string) "empty fragment" "" (render []);
          (* No placeholder is shown to ordinary visitors. *)
          Alcotest.(check bool) "no empty-state copy" false
            (contains (render []) "No connected projects"))
    ]

  let content_cases =
    [ case "connected projects: section copy, identity, kind, namespace and \
            verification all render"
        (fun () ->
          let html =
            one ~name:"Ccpp Alpha" ~slug:"ccpp-alpha" ~login:"ccpp-owner" ()
          in
          Alcotest.(check bool) "heading" true
            (contains html "Connected projects");
          Alcotest.(check bool) "supporting copy" true
            (contains html
               "Open-source projects that use this community as their Earde \
                home.");
          Alcotest.(check bool) "project name" true (contains html "Ccpp Alpha");
          Alcotest.(check bool) "kind copy" true (contains html ">Project<");
          Alcotest.(check bool) "namespace login" true
            (contains html "ccpp-owner");
          Alcotest.(check bool) "verification copy" true
            (contains html "Verified through GitHub");
          Alcotest.(check bool) "safe provenance copy" true
            (contains html "Project connected through GitHub");
          check_no_officiality "content" html;
          check_inert "content" html)
    ; case "connected projects: stale and revoked carry their exact copy and \
            stay visible"
        (fun () ->
          let stale = one ~verification:Ccp.Stale () in
          Alcotest.(check bool) "stale copy" true
            (contains stale "Verification stale");
          Alcotest.(check bool) "stale is not verified copy" false
            (contains stale "Verified through GitHub");
          let revoked = one ~verification:Ccp.Revoked () in
          Alcotest.(check bool) "revoked copy" true
            (contains revoked "Verification revoked");
          Alcotest.(check bool) "revoked still rendered" true
            (contains revoked "Ccpp Project");
          check_no_officiality "stale" stale;
          check_no_officiality "revoked" revoked)
    ; case "connected projects: every project kind uses the current product \
            vocabulary"
        (fun () ->
          List.iter
            (fun (kind, copy) ->
              let html = one ~kind () in
              Alcotest.(check bool)
                ("kind copy " ^ copy)
                true
                (contains html (">" ^ copy ^ "<")))
            [ (Pi.Project, "Project"); (Pi.Organization, "Organization");
              (Pi.Ecosystem, "Ecosystem"); (Pi.Foundation, "Foundation");
              (Pi.Working_group, "Working group"); (Pi.Other, "Other") ])
    ; case "connected projects: repositories keep supplied order and carry \
            Primary and Archived markers"
        (fun () ->
          let html =
            one
              ~repositories:
                [ repo ~primary:true "ccpp-owner/alpha";
                  repo ~archived:true "ccpp-owner/beta";
                  repo "ccpp-owner/gamma" ]
              ()
          in
          let index needle =
            let rec go i =
              if i + String.length needle > String.length html then -1
              else if String.sub html i (String.length needle) = needle then i
              else go (i + 1)
            in
            go 0
          in
          Alcotest.(check bool) "alpha before beta" true
            (index "ccpp-owner/alpha" < index "ccpp-owner/beta");
          Alcotest.(check bool) "beta before gamma" true
            (index "ccpp-owner/beta" < index "ccpp-owner/gamma");
          Alcotest.(check bool) "primary marker" true (contains html ">Primary<");
          Alcotest.(check bool) "archived marker" true
            (contains html ">Archived<");
          Alcotest.(check int) "exactly one primary marker" 1
            (ps_count html ">Primary<");
          Alcotest.(check int) "exactly one archived marker" 1
            (ps_count html ">Archived<"))
    ; case "connected projects: multiple projects preserve the supplied order"
        (fun () ->
          let html =
            render
              [ project ~name:"Ccpp One" ~slug:"ccpp-one" ();
                project ~name:"Ccpp Two" ~slug:"ccpp-two" () ]
          in
          Alcotest.(check int) "two project entries" 2
            (ps_count html "<li class='ccp-project'>");
          let idx needle =
            let rec go i =
              if i + String.length needle > String.length html then -1
              else if String.sub html i (String.length needle) = needle then i
              else go (i + 1)
            in
            go 0
          in
          Alcotest.(check bool) "supplied order kept" true
            (idx "Ccpp One" < idx "Ccpp Two"))
    ]

  let link_cases =
    [ case "connected projects: a safe website is linked; an unsafe one \
            degrades to inert escaped text"
        (fun () ->
          let safe = one ~website:"https://ccpp.example/home" () in
          Alcotest.(check bool) "website linked" true
            (contains safe "href='https://ccpp.example/home'");
          (* Each unsafe scheme renders its text but never an href; the
             repository list is dropped so the only possible href would be the
             website's. *)
          List.iter
            (fun bad ->
              let html = one ~website:bad ~repositories:[] () in
              Alcotest.(check bool)
                ("no href for " ^ bad)
                false
                (contains html "href=");
              check_inert ("unsafe website " ^ bad) html)
            [ "javascript:alert(1)"; "data:text/html,x"; "/relative/path";
              "//evil.example/x"; "ftp://ccpp.example/x"; "" ])
    ; case "connected projects: a repository links only at its canonical \
            HTTPS GitHub URL"
        (fun () ->
          let good = one ~repositories:[ repo "ccpp-owner/alpha" ] () in
          Alcotest.(check bool) "canonical repository linked" true
            (contains good "href='https://github.com/ccpp-owner/alpha'");
          List.iter
            (fun bad ->
              let html =
                one ~repositories:[ repo ~url:bad "ccpp-owner/alpha" ] ()
              in
              Alcotest.(check bool)
                ("no href for " ^ bad)
                false (contains html "href=");
              (* The label still renders, inert and escaped. *)
              Alcotest.(check bool) "full name still shown" true
                (contains html "ccpp-owner/alpha");
              check_inert ("bad repository url " ^ bad) html)
            [ "https://evil.example/ccpp-owner/alpha";
              "https://github.com.evil.example/ccpp-owner/alpha";
              "http://github.com/ccpp-owner/alpha";
              "https://github.com/ccpp-owner/other";
              "javascript:alert(1)"; "" ])
    ; case "connected projects: the project name is never a link and the \
            owner-only setup route is never advertised"
        (fun () ->
          let html = one ~slug:"ccpp-alpha" () in
          Alcotest.(check bool) "no setup link" false
            (contains html "/projects/ccpp-alpha/setup");
          Alcotest.(check bool) "no projects route at all" false
            (contains html "/projects/");
          Alcotest.(check bool) "no request-home link" false
            (contains html "request-home");
          (* The name renders as a heading, never wrapped in an anchor. *)
          Alcotest.(check bool) "name is a heading" true
            (contains html "<h3 class='ccp-name'>Ccpp Project</h3>"))
    ; case "connected projects: an empty repository list still renders the \
            project identity"
        (fun () ->
          let html = one ~repositories:[] () in
          Alcotest.(check bool) "identity present" true
            (contains html "Ccpp Project");
          Alcotest.(check bool) "no repository list" false
            (contains html "ccp-repos");
          Alcotest.(check bool) "no repository link" false (contains html "href="))
    ]

  let defensive_cases =
    [ case "connected projects: a blank project name degrades to a generic \
            safe label"
        (fun () ->
          List.iter
            (fun blank ->
              let html = one ~name:blank () in
              Alcotest.(check bool) "generic label" true
                (contains html "Open-source project");
              Alcotest.(check bool) "no empty heading" false
                (contains html "<h3 class='ccp-name'></h3>"))
            [ ""; "   "; "\t\n" ])
    ; case "connected projects: a duplicated project slug leaves at most one \
            link-carrying group"
        (fun () ->
          let html =
            render
              [ project ~name:"Ccpp One" ~slug:"ccpp-dup"
                  ~website:"https://one.example/" ();
                project ~name:"Ccpp Two" ~slug:"ccpp-dup"
                  ~website:"https://two.example/" () ]
          in
          Alcotest.(check int) "both groups render" 2
            (ps_count html "<li class='ccp-project'>");
          Alcotest.(check bool) "first keeps its website link" true
            (contains html "href='https://one.example/'");
          Alcotest.(check bool) "duplicate carries no website link" false
            (contains html "href='https://two.example/'");
          Alcotest.(check bool) "duplicate still shows its website text" true
            (contains html "https://two.example/");
          (* Exactly one repository link survives across the duplicate pair. *)
          Alcotest.(check int) "one repository link" 1
            (ps_count html "href='https://github.com/ccpp-owner/alpha'"))
    ; case "connected projects: an invalid project slug carries no links"
        (fun () ->
          List.iter
            (fun bad ->
              let html = one ~slug:bad ~website:"https://ccpp.example/" () in
              Alcotest.(check bool) "no links at all" false
                (contains html "href="))
            [ ""; "Ccpp-Alpha"; "ccpp alpha"; "-ccpp"; "ccpp-"; "ccpp/alpha";
              "ccpp\x01" ])
    ; case "connected projects: a duplicated repository full name leaves at \
            most one linked item"
        (fun () ->
          let html =
            one
              ~repositories:
                [ repo ~primary:true "ccpp-owner/alpha";
                  repo "ccpp-owner/alpha" ]
              ()
          in
          Alcotest.(check int) "both rows render" 2
            (ps_count html "<li class='ccp-repo'>");
          Alcotest.(check int) "only one linked" 1
            (ps_count html "href='https://github.com/ccpp-owner/alpha'"))
    ; case "connected projects: a malformed namespace login is escaped, never \
            executed"
        (fun () ->
          let html = one ~login:"<script>alert(1)</script>" () in
          Alcotest.(check bool) "escaped" true
            (contains html "&lt;script&gt;");
          check_inert "malformed login" html)
    ]

  let escaping_cases =
    [ case "connected projects: every displayed field is HTML-escaped"
        (fun () ->
          let hostile = "<img src=x onerror=alert(1)>\"'&" in
          let html =
            one ~name:hostile ~login:hostile
              ~website:("https://ccpp.example/?q=" ^ hostile)
              ~repositories:
                [ repo ~url:"https://github.com/a/b" (hostile ^ "/x") ]
              ()
          in
          Alcotest.(check bool) "no raw img tag" false (contains html "<img ");
          Alcotest.(check bool) "escaped lt" true (contains html "&lt;img");
          Alcotest.(check bool) "escaped amp" true (contains html "&amp;");
          check_inert "hostile fields" html)
    ; case "connected projects: no identifier, provenance or private workflow \
            data can appear"
        (fun () ->
          (* The page model carries none of these, so the assertion is that
             nothing resembling them is synthesized by the renderer. *)
          let html =
            render
              [ project ~name:"Ccpp One" ~slug:"ccpp-one" ();
                project ~name:"Ccpp Two" ~slug:"ccpp-two"
                  ~verification:Ccp.Revoked () ]
          in
          List.iter
            (fun needle ->
              Alcotest.(check bool)
                ("no " ^ needle)
                false (contains html needle))
            [ "Requested by"; "Reviewed by"; "request note"; "Private";
              "relation"; "installation"; "member"; "star"; "karma";
              "moderator"; "Accept"; "Reject" ];
          check_no_officiality "identifiers" html;
          check_inert "identifiers" html)
    ]
end

(* === Connected projects on the real community page (GET /c/:slug) ===
   End-to-end coverage of the integration itself: the section appears inside
   the page the existing route already serves, for exactly the visitors that
   route already authorizes, and never for anyone else. The real handler runs
   behind the real production pipeline shape — sql_pool + secret + memory
   sessions + the real router path — so :slug, Db.get_community_by_slug and
   can_view_community behave exactly as in bin/main; no synthetic parallel
   handler exists. Database-gated with its own reserved
   external-installation-id range 947000001..947000999 (hence account ids
   947100001..947100999, which also scope the permanent-project cleanup),
   ccph_% usernames, and ccph-% community slugs so no suite shares fixtures.
   Credential and privacy assertions are boolean, so no fixture byte reaches
   test output on failure. *)
module Ccph = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store
  module Fin = Earde.Project_finalization_store

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let insert_community = Phcv.insert_community
  let status_of = Gh_start_handler.status_of

  (* Distinctive credential-shaped fixtures. None may appear in the page, its
     headers, or its cookies. *)
  let private_note = "ccph private note gho_CCPH_ACCESS_TOKEN_SECRET"
  let refresh_token_marker = "ghr_CCPH_REFRESH_TOKEN"
  let pkce_verifier_marker = "CCPH_PKCE_VERIFIER_VALUE"
  let oauth_state_marker = "CCPH_OAUTH_STATE_VALUE"
  let client_secret_marker = "CCPH_CLIENT_SECRET_VALUE"
  let authorization_code_marker = "CCPH_AUTHORIZATION_CODE"
  let session_binding_marker = "CCPH_SESSION_BINDING"

  let credential_markers =
    [ ("access token / private note", private_note);
      ("refresh token", refresh_token_marker);
      ("PKCE verifier", pkce_verifier_marker);
      ("OAuth state", oauth_state_marker);
      ("client secret", client_secret_marker);
      ("authorization code", authorization_code_marker);
      ("session binding", session_binding_marker);
      ("external installation id", "947000001");
      ("external account id", "947100001");
      ("external repository id", "947400001")
    ]

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 947100001 AND 947100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 947100001 AND 947100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 947000001 AND 947000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'ccph-%'"
      ; "DELETE FROM users WHERE username LIKE 'ccph_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 947000001 AND 947000999"
      ]

  let q_insert_moderator =
    (Caqti_type.(t3 int int string) ->. Caqti_type.unit)
    "INSERT INTO community_moderators (user_id, community_id, role) \
     VALUES ($1, $2, $3)"

  let q_insert_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
    "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  let q_set_admin =
    (Caqti_type.(t2 int bool) ->. Caqti_type.unit)
    "UPDATE users SET is_admin = $2 WHERE id = $1"

  let q_provision_accepted =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at) \
     VALUES ($1, $2, 'home', 'accepted', NOW())"

  let q_insert_removed =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at, \
        removed_at) \
     VALUES ($1, $2, 'home', 'removed', NOW(), NOW())"

  let q_set_verification =
    (Caqti_type.(t2 int64 string) ->. Caqti_type.unit)
    "UPDATE open_source_projects SET verification_status = $2 WHERE id = $1"

  let q_corrupt_login =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET forge_namespace_login = 'ccph' || chr(1) || 'bad' WHERE id = $1"

  let q_legacy_community =
    (Caqti_type.int ->. Caqti_type.unit)
    "UPDATE communities SET sections_enabled = FALSE WHERE id = $1"

  (* Hiding the relation table makes the community lookup succeed and the
     connected-projects read fail — the only way to exercise the storage
     branch of THIS feature rather than the route's pre-existing lookup
     failure. Renamed and restored inside the one case that needs it, under
     Lwt.finalize; production migrations are untouched. *)
  let q_hide_relations =
    (Caqti_type.unit ->. Caqti_type.unit)
    "ALTER TABLE community_projects RENAME TO community_projects_ccph_hidden"

  let q_show_relations =
    (Caqti_type.unit ->. Caqti_type.unit)
    "ALTER TABLE community_projects_ccph_hidden RENAME TO community_projects"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun ~url conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f ~url conn))

  (* === the real production pipeline shape === *)

  (* One shared single-connection sql_pool pipeline for the whole suite:
     nothing ever closes a Dream.sql_pool, and this suite issues enough
     requests (several visitor identities per case) that a fresh pool per
     request exhausts Postgres max_connections. The session identity is
     swapped per request instead; cases run sequentially. Everything else is
     the real production shape — secret, memory sessions, and the real
     "/c/:slug" router path bound to the real handler, so :slug,
     Db.get_community_by_slug and can_view_community behave exactly as in
     bin/main. *)
  let shared_identity : (int * bool) option ref = ref None
  let shared_pipeline = ref None

  let pipeline_for ~url =
    match !shared_pipeline with
    | Some pipeline -> pipeline
    | None ->
        let pipeline =
          Dream.sql_pool ~size:1 url @@ Dream.set_secret gck_secret
          @@ Dream.memory_sessions
          @@ (fun handler request ->
               match !shared_identity with
               | None -> handler request
               | Some (uid, is_admin) ->
                   let* () =
                     Dream.set_session_field request "user_id"
                       (string_of_int uid)
                   in
                   let* () =
                     if is_admin then
                       Dream.set_session_field request "is_admin" "true"
                     else Lwt.return_unit
                   in
                   handler request)
          @@ Dream.router
               [ Dream.get "/c/:slug" Earde.Handlers.community_page_handler ]
        in
        shared_pipeline := Some pipeline;
        pipeline

  let visit ?session_user_id ?(session_admin = false) ~url ~slug () =
    let pipeline = pipeline_for ~url in
    shared_identity :=
      (match session_user_id with
       | None -> None
       | Some uid -> Some (uid, session_admin));
    let* response =
      pipeline (Dream.request ~method_:`GET ~target:("/c/" ^ slug) "")
    in
    let* body = Dream.body response in
    Lwt.return (response, body)

  let section_marker = "<section class='ccp-section'>"

  let check_has_section label body =
    Alcotest.(check bool) (label ^ ": section present") true
      (contains body section_marker);
    Alcotest.(check bool) (label ^ ": heading") true
      (contains body "Connected projects");
    Alcotest.(check bool) (label ^ ": supporting copy") true
      (contains body
         "Open-source projects that use this community as their Earde home.")

  let check_no_section label body =
    Alcotest.(check bool) (label ^ ": no section") false
      (contains body section_marker);
    Alcotest.(check bool) (label ^ ": no heading") false
      (contains body "Connected projects")

  (* Nothing in this feature may imply endorsement or officiality. *)
  let check_no_officiality label body =
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no " ^ needle) false
          (contains body needle))
      [ "Official project"; "Official community"; "Official home";
        "GitHub-approved"; "GitHub-endorsed" ]

  (* Connected projects must never cause analytics to initialize on a page
     that would not otherwise carry it. The section itself contributes no
     script (proven structurally in the DB-free renderer suite); here the
     assertion is end-to-end — a private or draft page that DOES list
     connected projects still carries no analytics bootstrap, group
     attribute, or consent block. *)
  let check_no_analytics_init label body =
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no " ^ needle) false
          (contains body needle))
      [ "analytics.js"; "data-analytics-group"; "analytics-consent";
        "data-analytics-private-community" ]

  (* Boolean privacy sweep over the page, its headers, and its cookies. *)
  let check_no_credentials label response body =
    let headers =
      String.concat "\n"
        (List.map (fun (k, v) -> k ^ ": " ^ v) (Dream.all_headers response))
    in
    List.iter
      (fun (what, marker) ->
        Alcotest.(check bool)
          (label ^ ": body carries no " ^ what)
          false (contains body marker);
        Alcotest.(check bool)
          (label ^ ": headers carry no " ^ what)
          false (contains headers marker))
      credential_markers

  let check_ok label response =
    Alcotest.(check int) (label ^ ": 200") 200 (status_of response)

  (* The route's single generic unavailable response, used for both a missing
     community and a denied private read. *)
  let check_unavailable label response body =
    Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "This community does not exist.");
    check_no_section label body

  let check_generic_500 label response body =
    Alcotest.(check int) (label ^ ": 500") 500 (status_of response);
    Alcotest.(check (option string))
      (label ^ ": non-cacheable")
      (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "Something went wrong on our side.");
    check_no_section label body;
    (* No SQL diagnostics of any kind. *)
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no " ^ needle) false
          (contains body needle))
      [ "community_projects"; "open_source_projects"; "Caqti"; "PostgreSQL";
        "SELECT"; "relation \"" ]

  (* === fixtures === *)

  let make_project ?kind ?name ?website ?(repos = [ "alpha" ]) conn ~user
      ~ext_id ~slug =
    let base = Int64.add ext_id 400000L in
    let* _inst, draft, _, _ =
      Pfin.make_draft conn ~user ~ext_id (fun account_id ->
          List.mapi
            (fun i n ->
              Pfin.repo ~account_id ~id:(Int64.add base (Int64.of_int i)) n)
            repos)
    in
    let* ids = Pfin.snapshot_ids conn draft in
    let primary = List.nth ids 0 in
    let* () =
      Pod_select.replace_ok "seed selection" conn ~user ~draft ~primary ids
    in
    let identity =
      Pfin.identity_exn ?kind ?name ~slug ?website ~selected:ids ~primary ()
    in
    let* created = Pfin.finalize_ok "fixture project" conn ~user ~draft identity in
    Lwt.return (Fin.project_id created)

  let add_top_mod conn ~user ~community =
    exec conn "top_mod fixture" q_insert_moderator (user, community, "top_mod")

  let add_member conn ~user ~community =
    exec conn "member fixture" q_insert_member (user, community)

  let request_pending label conn ~user ~slug ~community =
    let relation =
      phr_expect_ok (Phr.create_pending ~request_note:(Some private_note))
    in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: request fixture failed" label

  let review label conn ~reviewer ~slug ~community_slug ~decision =
    let* r =
      Rvs.review conn ~reviewer_user_id:reviewer ~project_slug:slug
        ~target_community_slug:community_slug ~decision
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: review fixture failed" label

  let accept_reviewed label conn ~owner ~reviewer ~slug ~cid ~community_slug =
    let* () = request_pending label conn ~user:owner ~slug ~community:cid in
    review label conn ~reviewer ~slug ~community_slug ~decision:Rvs.Accept

  (* === cases === *)

  let empty_case =
    db_case "community page: a public community with no accepted project home \
             renders no section at all" (fun ~url conn ->
        let* _cid = insert_community conn "ccph-empty" in
        let* response, body = visit ~url ~slug:"ccph-empty" () in
        check_ok "anonymous" response;
        check_no_section "anonymous" body;
        (* The community page itself is unchanged. *)
        Alcotest.(check bool) "community still renders" true
          (contains body "ccph-empty");
        Lwt.return_unit)

  let anonymous_case =
    db_case "community page: one accepted home is visible to an anonymous \
             visitor, with factual copy and no GitHub login requirement"
      (fun ~url conn ->
        let* owner = insert_user conn "ccph_owner" in
        let* moderator = insert_user conn "ccph_mod" in
        let* _project =
          make_project conn ~user:owner ~ext_id:947000001L ~slug:"ccph-alpha"
            ~name:"Ccph Alpha" ~website:"https://ccph-alpha.example/"
        in
        let* cid = insert_community conn "ccph-pub" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "accept" conn ~owner ~reviewer:moderator
            ~slug:"ccph-alpha" ~cid ~community_slug:"ccph-pub"
        in
        let* response, body = visit ~url ~slug:"ccph-pub" () in
        check_ok "anonymous" response;
        check_has_section "anonymous" body;
        Alcotest.(check bool) "project name" true (contains body "Ccph Alpha");
        Alcotest.(check bool) "verification copy" true
          (contains body "Verified through GitHub");
        Alcotest.(check bool) "provenance copy" true
          (contains body "Project connected through GitHub");
        Alcotest.(check bool) "repository linked" true
          (contains body "https://github.com/pfin-owner/alpha");
        (* No GitHub authorization is demanded of an ordinary visitor. *)
        Alcotest.(check bool) "no GitHub sign-in prompt" false
          (contains body "github.com/login/oauth");
        Alcotest.(check bool) "no owner-only setup link" false
          (contains body "/projects/ccph-alpha/setup");
        check_no_officiality "anonymous" body;
        check_no_credentials "anonymous" response body;
        Lwt.return_unit)

  let ordering_case =
    db_case "community page: multiple accepted homes keep the read model's \
             deterministic order" (fun ~url conn ->
        let* owner = insert_user conn "ccph_ord_owner" in
        let* moderator = insert_user conn "ccph_ord_mod" in
        let* cid = insert_community conn "ccph-ord" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* _ =
          make_project conn ~user:owner ~ext_id:947000010L ~slug:"ccph-ord-z"
            ~name:"zulu tool"
        in
        let* _ =
          make_project conn ~user:owner ~ext_id:947000011L ~slug:"ccph-ord-a"
            ~name:"Alpha tool"
        in
        let* () =
          accept_reviewed "z" conn ~owner ~reviewer:moderator ~slug:"ccph-ord-z"
            ~cid ~community_slug:"ccph-ord"
        in
        let* () =
          accept_reviewed "a" conn ~owner ~reviewer:moderator ~slug:"ccph-ord-a"
            ~cid ~community_slug:"ccph-ord"
        in
        let* _response, body = visit ~url ~slug:"ccph-ord" () in
        let idx needle =
          match ps_index_of body needle 0 with
          | Some i -> i
          | None -> Alcotest.failf "missing %s" needle
        in
        Alcotest.(check bool) "lower(name) order preserved through rendering"
          true
          (idx "Alpha tool" < idx "zulu tool");
        Lwt.return_unit)

  let excluded_case =
    db_case "community page: pending, rejected and removed relations never \
             appear" (fun ~url conn ->
        let* owner = insert_user conn "ccph_ex_owner" in
        let* moderator = insert_user conn "ccph_ex_mod" in
        let* _pending =
          make_project conn ~user:owner ~ext_id:947000020L ~slug:"ccph-pend"
            ~name:"Ccph Pending"
        in
        let* _rejected =
          make_project conn ~user:owner ~ext_id:947000021L ~slug:"ccph-rej"
            ~name:"Ccph Rejected"
        in
        let* removed =
          make_project conn ~user:owner ~ext_id:947000022L ~slug:"ccph-rem"
            ~name:"Ccph Removed"
        in
        let* cid = insert_community conn "ccph-ex" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          request_pending "pending" conn ~user:owner ~slug:"ccph-pend"
            ~community:cid
        in
        let* () =
          request_pending "reject seed" conn ~user:owner ~slug:"ccph-rej"
            ~community:cid
        in
        let* () =
          review "reject" conn ~reviewer:moderator ~slug:"ccph-rej"
            ~community_slug:"ccph-ex" ~decision:Rvs.Reject
        in
        let* () = exec conn "removed row" q_insert_removed (removed, cid) in
        let* response, body = visit ~url ~slug:"ccph-ex" () in
        check_ok "closed states" response;
        check_no_section "only closed states" body;
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("absent: " ^ needle) false
              (contains body needle))
          [ "Ccph Pending"; "Ccph Rejected"; "Ccph Removed" ];
        check_no_credentials "closed states" response body;
        Lwt.return_unit)

  let drifted_verification_case =
    db_case "community page: stale and revoked projects stay visible with \
             their exact copy" (fun ~url conn ->
        let* owner = insert_user conn "ccph_ver_owner" in
        let* moderator = insert_user conn "ccph_ver_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:947000030L ~slug:"ccph-ver"
            ~name:"Ccph Drifting"
        in
        let* cid = insert_community conn "ccph-ver" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "ver" conn ~owner ~reviewer:moderator ~slug:"ccph-ver"
            ~cid ~community_slug:"ccph-ver"
        in
        let* () = exec conn "stale" q_set_verification (project, "stale") in
        let* _r, body = visit ~url ~slug:"ccph-ver" () in
        check_has_section "stale" body;
        Alcotest.(check bool) "stale copy" true
          (contains body "Verification stale");
        Alcotest.(check bool) "still listed" true (contains body "Ccph Drifting");
        let* () = exec conn "revoked" q_set_verification (project, "revoked") in
        let* _r, body = visit ~url ~slug:"ccph-ver" () in
        check_has_section "revoked" body;
        Alcotest.(check bool) "revoked copy" true
          (contains body "Verification revoked");
        check_no_officiality "revoked" body;
        Lwt.return_unit)

  let provisioned_case =
    db_case "community page: a provisioned accepted home (no requester, no \
             reviewer) is visible like any other" (fun ~url conn ->
        let* owner = insert_user conn "ccph_prov_owner" in
        let* project =
          make_project conn ~user:owner ~ext_id:947000040L ~slug:"ccph-prov"
            ~name:"Ccph Provisioned"
        in
        let* cid = insert_community conn "ccph-prov" in
        let* () = exec conn "provision" q_provision_accepted (project, cid) in
        let* response, body = visit ~url ~slug:"ccph-prov" () in
        check_ok "provisioned" response;
        check_has_section "provisioned" body;
        Alcotest.(check bool) "project listed" true
          (contains body "Ccph Provisioned");
        (* Provenance is not exposed, so nothing distinguishes it from a
           reviewed home. *)
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("no provenance: " ^ needle) false
              (contains body needle))
          [ "Requested by"; "Reviewed by"; "provisioned"; "Provisioned home" ];
        Lwt.return_unit)

  let legacy_branch_case =
    db_case "community page: the simple-feed branch renders the section too"
      (fun ~url conn ->
        let* owner = insert_user conn "ccph_leg_owner" in
        let* moderator = insert_user conn "ccph_leg_mod" in
        let* _project =
          make_project conn ~user:owner ~ext_id:947000050L ~slug:"ccph-leg"
            ~name:"Ccph Legacy"
        in
        let* cid = insert_community conn "ccph-leg" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "leg" conn ~owner ~reviewer:moderator ~slug:"ccph-leg"
            ~cid ~community_slug:"ccph-leg"
        in
        let* () = exec conn "simple feed" q_legacy_community cid in
        let* response, body = visit ~url ~slug:"ccph-leg" () in
        check_ok "simple feed" response;
        check_has_section "simple feed" body;
        Alcotest.(check bool) "project listed" true
          (contains body "Ccph Legacy");
        Lwt.return_unit)

  let unlisted_case =
    db_case "community page: an unlisted community is unchanged and still \
             shows its connected projects" (fun ~url conn ->
        let* owner = insert_user conn "ccph_unl_owner" in
        let* moderator = insert_user conn "ccph_unl_mod" in
        let* _project =
          make_project conn ~user:owner ~ext_id:947000060L ~slug:"ccph-unl"
            ~name:"Ccph Unlisted"
        in
        let* cid = insert_community conn "ccph-unl" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "unl" conn ~owner ~reviewer:moderator ~slug:"ccph-unl"
            ~cid ~community_slug:"ccph-unl"
        in
        let* () = exec conn "unlisted" Phcv.q_make_unlisted cid in
        let* response, body = visit ~url ~slug:"ccph-unl" () in
        check_ok "unlisted" response;
        check_has_section "unlisted" body;
        (* Unchanged indexing policy: an unlisted community stays noindex, and
           this feature adds no discovery surface. *)
        Alcotest.(check bool) "still noindex" true (contains body "noindex");
        Lwt.return_unit)

  let private_case =
    db_case_lifecycle_relaxed "community page: only visitors the route already authorizes see a \
             private community and its connected projects" (fun ~url conn ->
        let* owner = insert_user conn "ccph_priv_owner" in
        let* moderator = insert_user conn "ccph_priv_mod" in
        let* member = insert_user conn "ccph_priv_member" in
        let* stranger = insert_user conn "ccph_priv_stranger" in
        let* admin = insert_user conn "ccph_priv_admin" in
        let* _project =
          make_project conn ~user:owner ~ext_id:947000070L ~slug:"ccph-priv"
            ~name:"Ccph Private"
        in
        let* cid = insert_community conn "ccph-priv" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "priv" conn ~owner ~reviewer:moderator
            ~slug:"ccph-priv" ~cid ~community_slug:"ccph-priv"
        in
        let* () = add_member conn ~user:member ~community:cid in
        let* () = exec conn "make admin" q_set_admin (admin, true) in
        (* Only after acceptance does the community go private — the drift the
           feature must tolerate. *)
        let* () = exec conn "private" Phcv.q_make_private cid in
        (* Authorized: member, moderator, admin. *)
        let* () =
          Lwt_list.iter_s
            (fun (label, uid, is_admin) ->
              let* response, body =
                visit ~url ~session_user_id:uid ~session_admin:is_admin
                  ~slug:"ccph-priv" ()
              in
              check_ok label response;
              check_has_section label body;
              Alcotest.(check bool) (label ^ ": project listed") true
                (contains body "Ccph Private");
              (* Connected projects exist on this private page, and it still
                 initializes no analytics of any kind. *)
              check_no_analytics_init label body;
              check_no_credentials label response body;
              Lwt.return_unit)
            [ ("member", member, false); ("moderator", moderator, false);
              ("admin", admin, true) ]
        in
        (* Unauthorized: anonymous and a signed-in stranger get the route's
           existing generic response, byte-identical to a missing community. *)
        let* anon_response, anon_body = visit ~url ~slug:"ccph-priv" () in
        check_unavailable "anonymous" anon_response anon_body;
        let* str_response, str_body =
          visit ~url ~session_user_id:stranger ~slug:"ccph-priv" ()
        in
        check_unavailable "stranger" str_response str_body;
        let* miss_response, miss_body = visit ~url ~slug:"ccph-missing" () in
        check_unavailable "missing" miss_response miss_body;
        Alcotest.(check bool)
          "denied private is indistinguishable from missing" true
          (String.equal str_body miss_body);
        Alcotest.(check bool) "no project name leaks to the denied visitor"
          false
          (contains str_body "Ccph Private");
        Lwt.return_unit)

  let draft_case =
    db_case "community page: a setup-draft community stays authorized exactly \
             as before" (fun ~url conn ->
        let* owner = insert_user conn "ccph_dr_owner" in
        let* moderator = insert_user conn "ccph_dr_mod" in
        let* stranger = insert_user conn "ccph_dr_stranger" in
        let* _project =
          make_project conn ~user:owner ~ext_id:947000080L ~slug:"ccph-dr"
            ~name:"Ccph Draft"
        in
        let* cid = insert_community conn "ccph-dr" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "dr" conn ~owner ~reviewer:moderator ~slug:"ccph-dr"
            ~cid ~community_slug:"ccph-dr"
        in
        let* () = exec conn "draft" Phcv.q_make_draft_state cid in
        (* The draft's own moderator keeps access, and sees the section. *)
        let* mod_response, mod_body =
          visit ~url ~session_user_id:moderator ~slug:"ccph-dr" ()
        in
        check_ok "draft moderator" mod_response;
        check_has_section "draft moderator" mod_body;
        check_no_analytics_init "draft moderator" mod_body;
        (* An unrelated visitor and an anonymous one are still denied. *)
        let* str_response, str_body =
          visit ~url ~session_user_id:stranger ~slug:"ccph-dr" ()
        in
        check_unavailable "draft stranger" str_response str_body;
        let* anon_response, anon_body = visit ~url ~slug:"ccph-dr" () in
        check_unavailable "draft anonymous" anon_response anon_body;
        Lwt.return_unit)

  let missing_case =
    db_case "community page: a missing community is unchanged" (fun ~url _conn ->
        let* response, body = visit ~url ~slug:"ccph-nope" () in
        check_unavailable "missing" response body;
        Lwt.return_unit)

  let inconsistency_case =
    db_case "community page: durable inconsistency in a connected project is \
             one generic non-cacheable 500, never a partial page"
      (fun ~url conn ->
        let* owner = insert_user conn "ccph_inc_owner" in
        let* moderator = insert_user conn "ccph_inc_mod" in
        let* project =
          make_project conn ~user:owner ~ext_id:947000090L ~slug:"ccph-inc"
            ~name:"Ccph Inconsistent"
        in
        let* cid = insert_community conn "ccph-inc" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () =
          accept_reviewed "inc" conn ~owner ~reviewer:moderator ~slug:"ccph-inc"
            ~cid ~community_slug:"ccph-inc"
        in
        let* ok_response, ok_body = visit ~url ~slug:"ccph-inc" () in
        check_ok "before corruption" ok_response;
        check_has_section "before corruption" ok_body;
        let* () = exec conn "corrupt login" q_corrupt_login project in
        let* response, body = visit ~url ~slug:"ccph-inc" () in
        check_generic_500 "corrupted" response body;
        (* The community's own content is not rendered around the failure. *)
        Alcotest.(check bool) "no partial community page" false
          (contains body "Ccph Inconsistent");
        check_no_credentials "corrupted" response body;
        Lwt.return_unit)

  let storage_failure_case =
    db_case "community page: a connected-projects storage failure is one \
             generic non-cacheable 500" (fun ~url conn ->
        let* _cid = insert_community conn "ccph-store" in
        let* () = exec conn "hide relations" q_hide_relations () in
        Lwt.finalize
          (fun () ->
            let* response, body = visit ~url ~slug:"ccph-store" () in
            check_generic_500 "storage failure" response body;
            Lwt.return_unit)
          (fun () -> exec conn "restore relations" q_show_relations ()))

  let suite =
    [ empty_case; anonymous_case; ordering_case; excluded_case;
      drifted_verification_case; provisioned_case; legacy_branch_case;
      unlisted_case; private_case; draft_case; missing_case;
      inconsistency_case; storage_failure_case ]
end

(* ===== Accepted project-home removal (Project_home_removal_store) =====
   Transactional accepted → removed transition of one exact home relation,
   authorized by any of the three current durable authorities (project
   steward, target top moderator, durable global administrator). Database-
   gated (EARDE_TEST_DATABASE_URL, same opt-in as Mod_scope) with its own
   reserved external-installation-id range 947200001..947200999 (hence
   account ids 947300001..947300999, which also scope the permanent-project
   cleanup), phrm_% usernames, and phrm-% community slugs so no suite shares
   fixtures. Accepted relations are built only through production paths: the
   real request store plus the real review store for a reviewed home, and a
   schema-valid production-shaped insert for a provisioned home (the
   provisioning store does not exist yet). Relation domain values come only
   through the public pure constructors. Every per-case wrapper disconnects
   deterministically. *)
module Phrm = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rm = Earde.Project_home_removal_store
  module Rq = Earde.Project_home_request_store
  module Rv = Earde.Project_home_review_store

  let error_str : Rm.error -> string = function
    | Rm.Invalid_user_id -> "Invalid_user_id"
    | Rm.Invalid_project_slug -> "Invalid_project_slug"
    | Rm.Invalid_community_slug -> "Invalid_community_slug"
    | Rm.Project_unavailable -> "Project_unavailable"
    | Rm.Community_unavailable -> "Community_unavailable"
    | Rm.Actor_unauthorized -> "Actor_unauthorized"
    | Rm.Removal_unavailable -> "Removal_unavailable"
    | Rm.Inconsistent_data -> "Inconsistent_data"
    | Rm.Storage_error -> "Storage_error"

  let status_str = Phr.string_of_status
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let make_project = Phrq.make_project
  let insert_community = Phcv.insert_community
  let contains = Cprj_schema.contains
  let relation_row = Phrq.relation_row
  let serialized_mutation_first = Phrv.serialized_mutation_first

  (* Same dependency order as the sibling suites. Users are deleted after
     communities so moderator rows cascade from either side cleanly. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 947300001 AND 947300999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 947300001 AND 947300999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 947200001 AND 947200999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phrm-%'"
      ; "DELETE FROM users WHERE username LIKE 'phrm_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 947200001 AND 947200999"
      ]

  (* An automatically provisioned accepted home: no requester, no reviewer,
     no note — exactly the shape the production status CHECK admits for
     'accepted'. No store writes this yet, so the row is built directly
     rather than through a test-only constructor. *)
  let q_provision_accepted =
    (Caqti_type.(t2 int64 int) ->! Caqti_type.int64)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at) \
     VALUES ($1, $2, 'home', 'accepted', NOW()) RETURNING id"

  (* Everything removal must leave byte-identical: both foreign keys, the
     relation type, requester, reviewer, the private note, and the exact
     review and creation instants. Status, removed_at and updated_at are
     deliberately absent — those three are what removal writes. *)
  let q_relation_stable_sig =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT project_id::text || '|' || community_id::text || '|' || \
            relation_type || '|' || \
            COALESCE(requested_by_user_id::text, '<null>') || '|' || \
            COALESCE(reviewed_by_user_id::text, '<null>') || '|' || \
            COALESCE(request_note, '<null>') || '|' || \
            COALESCE(reviewed_at::text, '<null>') || '|' || \
            created_at::text \
     FROM community_projects WHERE id = $1"

  (* Removal-time coherence, NULL-safe: presence plus ordering against the
     review and creation instants (a NULL comparison coalesces to FALSE,
     never a decode error). *)
  let q_removed_times =
    (Caqti_type.int64 ->! Caqti_type.(t2 (t2 bool bool) (t2 bool bool)))
    "SELECT removed_at IS NOT NULL, \
            COALESCE(removed_at >= reviewed_at, FALSE), \
            COALESCE(removed_at >= created_at, FALSE), \
            updated_at >= created_at \
     FROM community_projects WHERE id = $1"

  let q_status =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT status FROM community_projects WHERE id = $1"

  let q_count_repositories =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM project_repositories WHERE project_id = $1"

  (* Test-only failure injection for the rollback case: an AFTER UPDATE
     trigger scoped to one reserved note value, installed only once the
     accepted fixture already exists so the review store's own update is
     untouched. Installed and dropped inside that case alone; production
     migrations are untouched. *)
  let phrm_poison_note = "phrm poison marker"

  let q_create_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE FUNCTION phrm_fail_update_fn() RETURNS trigger
     LANGUAGE plpgsql
     AS 'BEGIN RAISE EXCEPTION ''phrm fixture failure''; END'"

  let q_create_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "CREATE TRIGGER phrm_fail_update
     AFTER UPDATE ON community_projects
     FOR EACH ROW WHEN (NEW.request_note = 'phrm poison marker')
     EXECUTE FUNCTION phrm_fail_update_fn()"

  let q_drop_fail_trigger =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP TRIGGER IF EXISTS phrm_fail_update ON community_projects"

  let q_drop_fail_fn =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DROP FUNCTION IF EXISTS phrm_fail_update_fn()"

  (* Each case gets a fresh connection and a clean fixture slate; cleanup
     runs again afterwards even when an assertion fails mid-way, and the
     connection is disconnected deterministically. *)
  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* db_case with the scoped lifecycle CHECK (migration 20260726130000)
     dropped for the whole case: these fixtures deliberately write drift
     shapes the constraint now forbids at the database, and the defensive
     branches they exercise stay covered. The suite cleanup removes every
     fixture row before the constraint returns, validated. *)
  let db_case_lifecycle_relaxed name f =
    db_case name (fun conn ->
        Nclc_relax.around conn
          ~cleanup:(fun () -> Nclc_relax.run_cleanup conn q_cleanup)
          (fun () -> f conn))

  (* === call helpers === *)

  let remove conn ~actor ~slug ~community =
    Rm.remove conn ~actor_user_id:actor ~project_slug:slug
      ~community_slug:community

  let remove_ok label conn ~actor ~slug ~community =
    let* r = remove conn ~actor ~slug ~community in
    match r with
    | Ok removed ->
        Alcotest.(check string)
          (label ^ ": resulting status")
          (status_str Phr.Removed)
          (status_str (Rm.resulting_status removed));
        Lwt.return_unit
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let remove_expect label expected conn ~actor ~slug ~community =
    let* r = remove conn ~actor ~slug ~community in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  (* === fixtures === *)

  (* Pending requests come only through the real request store and the real
     pure constructor. *)
  let request_ok label conn ~user ~slug ~community ?note () =
    let relation = phr_expect_ok (Phr.create_pending ~request_note:note) in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok created -> Lwt.return (Rq.relation_id created)
    | Error e -> Alcotest.failf "%s: %s" label (Phrq.error_str e)

  let review_ok label conn ~reviewer ~slug ~community decision =
    let* r =
      Rv.review conn ~reviewer_user_id:reviewer ~project_slug:slug
        ~target_community_slug:community ~decision
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error e -> Alcotest.failf "%s: %s" label (Phrv.error_str e)

  (* A reviewed accepted home, produced exactly as production produces one:
     the steward's request through the request store, then the target
     moderator's acceptance through the review store. *)
  let reviewed_home label conn ~owner ~reviewer ~slug ~community_id
      ~community_slug ?note () =
    let* rid =
      request_ok (label ^ ": request") conn ~user:owner ~slug
        ~community:community_id ?note ()
    in
    let* () =
      review_ok (label ^ ": accept") conn ~reviewer ~slug
        ~community:community_slug Rv.Accept
    in
    Lwt.return rid

  let provisioned_home label conn ~project ~community_id =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* rid = C.find q_provision_accepted (project, community_id) in
    or_fail label rid

  let add_role conn ~user ~community role =
    exec conn "role fixture" Phrv.q_insert_moderator (user, community, role)

  let add_top_mod conn ~user ~community =
    add_role conn ~user ~community "top_mod"

  let stable_sig conn id = find conn "stable sig" q_relation_stable_sig id
  let status_of conn id = find conn "status" q_status id

  let check_accepted_unchanged label conn id before =
    let* after = stable_sig conn id in
    Alcotest.(check string) (label ^ ": relation unchanged") before after;
    let* status = status_of conn id in
    Alcotest.(check string) (label ^ ": still accepted") "accepted" status;
    let* (present, _), (_, _) = find conn "times" q_removed_times id in
    Alcotest.(check bool) (label ^ ": removed_at still NULL") false present;
    Lwt.return_unit

  (* The full removed-row contract: exactly the three written columns
     changed, all timestamps coherent, everything else byte-identical. *)
  let check_removed label conn id before =
    let* status = status_of conn id in
    Alcotest.(check string) (label ^ ": status removed") "removed" status;
    let* after = stable_sig conn id in
    Alcotest.(check string)
      (label ^ ": requester, reviewer, note and timestamps preserved")
      before after;
    let* (present, after_reviewed), (after_created, updated_ge) =
      find conn "removed times" q_removed_times id
    in
    Alcotest.(check bool) (label ^ ": removed_at present") true present;
    Alcotest.(check bool) (label ^ ": removed_at >= reviewed_at") true
      after_reviewed;
    Alcotest.(check bool) (label ^ ": removed_at >= created_at") true
      after_created;
    Alcotest.(check bool) (label ^ ": updated_at coherent") true updated_ge;
    Lwt.return_unit

  (* One winner plus one exact loser, order unasserted. *)
  let one_winner label (ra, rb) =
    match (ra, rb) with
    | Ok w, Error Rm.Removal_unavailable | Error Rm.Removal_unavailable, Ok w ->
        w
    | Ok _, Ok _ -> Alcotest.failf "%s: both succeeded" label
    | Error a, Error b ->
        Alcotest.failf "%s: both failed (%s, %s)" label (error_str a)
          (error_str b)
    | Ok _, Error e | Error e, Ok _ ->
        Alcotest.failf "%s: unexpected loser error %s" label (error_str e)

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "removal: invalid inputs rejected before any SQL" (fun _conn ->
        (* A deliberately unusable connection: pure validation must return
           without touching it — were any SQL attempted, the result would be
           Storage_error (or a test-failing exception), never the expected
           input error. *)
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let expect label e ~actor ~slug ~community =
          remove_expect label e dead ~actor ~slug ~community
        in
        let* () =
          expect "user id 0" Rm.Invalid_user_id ~actor:0 ~slug:"phrm-a"
            ~community:"phrm-c"
        in
        let* () =
          expect "negative user id" Rm.Invalid_user_id ~actor:(-7)
            ~slug:"phrm-a" ~community:"phrm-c"
        in
        let* () =
          expect "user checked before slugs" Rm.Invalid_user_id ~actor:0
            ~slug:"NOT A SLUG" ~community:"also bad"
        in
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              expect "invalid project slug" Rm.Invalid_project_slug ~actor:1
                ~slug:bad ~community:"phrm-c")
            [ ""
            ; "Phrm-Upper"
            ; "phrm slug"
            ; " phrm-a"
            ; "phrm-a "
            ; "phrm_a"
            ; "phrm/a"
            ; "-phrm"
            ; "phrm-"
            ; "phrm--a"
            ; String.make 81 'a'
            ]
        in
        let* () =
          expect "project slug checked before community slug"
            Rm.Invalid_project_slug ~actor:1 ~slug:"phrm--a"
            ~community:"also bad"
        in
        Lwt_list.iter_s
          (fun bad ->
            expect "invalid community slug" Rm.Invalid_community_slug ~actor:1
              ~slug:"phrm-a" ~community:bad)
          [ ""
          ; "phrm c"
          ; " phrm-c"
          ; "phrm-c "
          ; "phrm/c"
          ; "phrm\tc"
          ; "phrm\nc"
          ; "phrm\x01c"
          ; "phrm\x7fc"
          ])

  (* === project-side authorization === *)

  let steward_removal_case =
    db_case
      "removal: a project steward removes a reviewed home, changing only \
       status and the removal timestamps" (fun conn ->
        let* owner = insert_user conn "phrm_owner" in
        let* reviewer = insert_user conn "phrm_mod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:947200001L ~slug:"phrm-steward"
        in
        let* cid = insert_community conn "phrm-steward-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let note = "Prima riga — nota privata \xe2\x98\x95" in
        let* rid =
          reviewed_home "home" conn ~owner ~reviewer ~slug:"phrm-steward"
            ~community_id:cid ~community_slug:"phrm-steward-home" ~note ()
        in
        let* before = stable_sig conn rid in
        let* project_before = find conn "project sig" Phrq.q_project_sig project in
        let* community_before =
          find conn "community sig" Phrq.q_community_sig cid
        in
        let* role_before = find conn "role" Phrv.q_role_sig (reviewer, cid) in
        let* repos_before = find conn "repos" q_count_repositories project in
        (* The steward is neither a member nor a moderator of the target. *)
        let* () =
          remove_ok "steward removes" conn ~actor:owner ~slug:"phrm-steward"
            ~community:"phrm-steward-home"
        in
        let* () = check_removed "steward removal" conn rid before in
        let* ((rp, rc), (rtype, _)), ((req, rev), (stored_note, _)) =
          relation_row conn rid
        in
        Alcotest.(check int64) "same project fk" project rp;
        Alcotest.(check int) "same community fk" cid rc;
        Alcotest.(check string) "relation type home" "home" rtype;
        Alcotest.(check (option int)) "requester preserved" (Some owner) req;
        Alcotest.(check (option int)) "reviewer preserved, not overwritten"
          (Some reviewer) rev;
        Alcotest.(check (option string)) "note preserved byte-exact"
          (Some note) stored_note;
        (* Nothing else in the world moved. *)
        let* project_after =
          find conn "project sig after" Phrq.q_project_sig project
        in
        let* community_after =
          find conn "community sig after" Phrq.q_community_sig cid
        in
        Alcotest.(check string) "project unchanged" project_before project_after;
        Alcotest.(check string) "community unchanged" community_before
          community_after;
        let* repos_after = find conn "repos after" q_count_repositories project in
        Alcotest.(check int) "project content unchanged" repos_before repos_after;
        let* members = find conn "members" Phrq.q_count_members cid in
        Alcotest.(check int) "no membership created or removed" 0 members;
        let* mods = find conn "moderators" Phrq.q_count_moderators cid in
        Alcotest.(check int) "moderator roster unchanged" 1 mods;
        let* role_after = find conn "role after" Phrv.q_role_sig (reviewer, cid) in
        Alcotest.(check string) "moderator role unchanged" role_before role_after;
        let* stewards =
          find conn "stewards" Phrq.q_count_stewards_for_project project
        in
        Alcotest.(check int) "stewardship unchanged" 1 stewards;
        let* total = find conn "total" Phrq.q_count_for_project project in
        Alcotest.(check int) "exactly the one historical row" 1 total;
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "active home slot freed" 0 active;
        Lwt.return_unit)

  let steward_variants_case =
    db_case
      "removal: a second steward removes, and stale or revoked verification \
       never blocks removal" (fun conn ->
        let* owner = insert_user conn "phrm_owner" in
        let* second = insert_user conn "phrm_steward2" in
        let* reviewer = insert_user conn "phrm_mod" in
        let* inst, project =
          make_project conn ~user:owner ~ext_id:947200002L ~slug:"phrm-stale"
        in
        let* cid = insert_community conn "phrm-stale-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* () =
          exec conn "second steward" Phrq.q_insert_steward
            (project, second, inst)
        in
        (* Stale verification: the home must still be separable. *)
        let* rid1 =
          reviewed_home "stale home" conn ~owner ~reviewer ~slug:"phrm-stale"
            ~community_id:cid ~community_slug:"phrm-stale-home" ()
        in
        let* before1 = stable_sig conn rid1 in
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* () =
          remove_ok "second steward removes a stale project's home" conn
            ~actor:second ~slug:"phrm-stale" ~community:"phrm-stale-home"
        in
        let* () = check_removed "stale removal" conn rid1 before1 in
        (* Revoked verification: likewise. The request store still needs a
           verified project to create the next home, so verification is
           restored first and revoked afterwards — exactly the production
           order. *)
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        let* rid2 =
          reviewed_home "revoked home" conn ~owner ~reviewer ~slug:"phrm-stale"
            ~community_id:cid ~community_slug:"phrm-stale-home" ()
        in
        let* before2 = stable_sig conn rid2 in
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification (project, "revoked")
        in
        let* () =
          remove_ok "original steward removes a revoked project's home" conn
            ~actor:owner ~slug:"phrm-stale" ~community:"phrm-stale-home"
        in
        let* () = check_removed "revoked removal" conn rid2 before2 in
        let* project_sig = find conn "project sig" Phrq.q_project_sig project in
        Alcotest.(check bool) "verification untouched by removal" true
          (contains ~needle:"revoked" project_sig);
        let* total = find conn "total" Phrq.q_count_for_project project in
        Alcotest.(check int) "both historical rows retained" 2 total;
        let* active =
          find conn "active" Phrq.q_count_active_for_project project
        in
        Alcotest.(check int) "no active relation left" 0 active;
        Lwt.return_unit)

  (* === community-side and administrator authorization === *)

  let community_side_case =
    db_case
      "removal: target top moderators and durable admins remove reviewed and \
       provisioned homes" (fun conn ->
        let* owner = insert_user conn "phrm_owner" in
        let* first_mod = insert_user conn "phrm_mod1" in
        let* second_mod = insert_user conn "phrm_mod2" in
