  (* === unauthorized and missing === *)

  let unauthorized_case =
    db_case "removal: every unauthorized identity and every missing or \
             mismatched target is the same generic 404, on both routes"
      (fun ~url conn ->
        let* owner = insert_user conn "phrh_uowner" in
        let* creator = insert_user conn "phrh_ucreator" in
        let* exsteward = insert_user conn "phrh_uex" in
        let* member = insert_user conn "phrh_umember" in
        let* modu = insert_user conn "phrh_umod" in
        let* legacy = insert_user conn "phrh_ulegacy" in
        let* othermod = insert_user conn "phrh_uother" in
        let* sonly = insert_user conn "phrh_usonly" in
        let* top = insert_user conn "phrh_utop" in
        let* project =
          make_project conn ~user:owner ~ext_id:948000070L ~slug:"phrh-uproj"
            ~name:"Phrh Uproj"
        in
        let* cid = insert_community ~name:"Phrh Uhome" conn "phrh-uhome" in
        let* other = insert_community ~name:"Phrh Uother" conn "phrh-uother" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        let* () = add_top_mod conn ~user:othermod ~community:other in
        let* () = add_member conn ~user:member ~community:cid in
        let* () = add_role conn ~user:modu ~community:cid "mod" in
        let* () = add_role conn ~user:legacy ~community:cid "legacy_mod" in
        let* () = exec conn "ex-steward" q_add_steward (project, exsteward) in
        let* () = exec conn "drop ex-steward" q_remove_steward (project, exsteward) in
        let* () =
          accepted_home "fixture" conn ~owner ~reviewer:top ~slug:"phrh-uproj"
            ~cid ~community_slug:"phrh-uhome" ()
        in
        let* rid = relation_id conn ~project ~community:cid in
        let* before = durable_signature conn ~project ~community:cid in
        let denied label uid ~admin_session ~target =
          as_user ~admin_session uid;
          let* response, token = do_get ~url ~target:"/mint" () in
          let cookie = Pch.session_cookie label response in
          let* response = do_post ~url ~cookie ~target ~token () in
          let* body = Dream.body response in
          check_generic_404 label response body;
          check_no_credentials label response body;
          Lwt.return_unit
        in
        let both label uid ~admin_session =
          let* () =
            denied (label ^ " (project route)") uid ~admin_session
              ~target:
                (project_side_target ~project:"phrh-uproj" ~community:"phrh-uhome")
          in
          denied (label ^ " (community route)") uid ~admin_session
            ~target:
              (community_side_target ~community:"phrh-uhome" ~project:"phrh-uproj")
        in
        let* () = both "project creator without stewardship" creator ~admin_session:false in
        let* () = both "removed steward" exsteward ~admin_session:false in
        let* () = both "ordinary member" member ~admin_session:false in
        let* () = both "mod role" modu ~admin_session:false in
        let* () = both "legacy_mod role" legacy ~admin_session:false in
        let* () = both "other-community moderator" othermod ~admin_session:false in
        (* A session admin claim with no durable users.is_admin backing. *)
        let* () = both "session-only admin" sonly ~admin_session:true in
        (* The relation survived every attempt. *)
        let* () = check_status "still accepted" conn rid "accepted" in
        (* Missing project, missing community, and a wrong pair collapse
           identically for an actor who is otherwise fully authorized. *)
        let* () =
          denied "missing project" owner ~admin_session:false
            ~target:
              (project_side_target ~project:"phrh-absent" ~community:"phrh-uhome")
        in
        let* () =
          denied "missing community" owner ~admin_session:false
            ~target:
              (project_side_target ~project:"phrh-uproj" ~community:"phrh-absent")
        in
        (* A wrong project/community pair is the generic 404 for anyone
           without authority over it, exactly like every other unavailable
           state. *)
        let* () =
          denied "wrong pair, unauthorized actor" member ~admin_session:false
            ~target:
              (project_side_target ~project:"phrh-uproj" ~community:"phrh-uother")
        in
        (* A malformed slug is the same generic 404, never reflected. *)
        let* () =
          denied "malformed project slug" owner ~admin_session:false
            ~target:
              (project_side_target ~project:"Phrh-Bad" ~community:"phrh-uhome")
        in
        (* For an actor who does hold authority over the pair, a wrong pair
           reaches the relation lookup and finds nothing — the store's
           Removal_unavailable, which the handler answers with the same safe
           303 current-state destination as success. No relation is touched
           and nothing distinguishes it from a replay. *)
        as_user owner;
        let* mint_response, mint = do_get ~url ~target:"/mint" () in
        let cookie = Pch.session_cookie "authorized wrong pair" mint_response in
        let* response =
          do_post ~url ~cookie
            ~target:
              (project_side_target ~project:"phrh-uproj" ~community:"phrh-uother")
            ~token:mint ()
        in
        let* () =
          check_clean_redirect_lwt "authorized wrong pair"
            "/projects/phrh-uproj/request-home" response
        in
        let* () = check_status "still accepted after probing" conn rid "accepted" in
        check_untouched "unauthorized" conn ~project ~community:cid before)

  (* === replay and concurrency === *)

  let replay_case =
    db_case "removal: a replayed or stale form is the same 303 current-state \
             destination, with exactly one durable removal" (fun ~url conn ->
        let* owner = insert_user conn "phrh_rowner" in
        let* top = insert_user conn "phrh_rtop" in
        let* project =
          make_project conn ~user:owner ~ext_id:948000080L ~slug:"phrh-rproj"
            ~name:"Phrh Rproj"
        in
        let* cid = insert_community ~name:"Phrh Rhome" conn "phrh-rhome" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        let* () =
          accepted_home "fixture" conn ~owner ~reviewer:top ~slug:"phrh-rproj"
            ~cid ~community_slug:"phrh-rhome" ()
        in
        let* rid = relation_id conn ~project ~community:cid in
        as_user owner;
        let* cookie, token, _ =
          open_surface "accepted page" ~url
            ~target:(request_home_target "phrh-rproj") ()
        in
        let target =
          project_side_target ~project:"phrh-rproj" ~community:"phrh-rhome"
        in
        let* first = do_post ~url ~cookie ~target ~token () in
        let* () =
          check_clean_redirect_lwt "first" "/projects/phrh-rproj/request-home"
            first
        in
        (* The same stale form replayed: same destination, no error oracle,
           no second mutation. *)
        let* second = do_post ~url ~cookie ~target ~token () in
        let* () =
          check_clean_redirect_lwt "replay" "/projects/phrh-rproj/request-home"
            second
        in
        let* () = check_status "still removed" conn rid "removed" in
        let* removed = find conn "removed count" q_count_removed project in
        Alcotest.(check int) "exactly one removal" 1 removed;
        let* total = find conn "relation count" q_count_relations project in
        Alcotest.(check int) "no new relation row" 1 total;
        (* A replay from the other surface behaves identically. *)
        as_user top;
        let* response, mint = do_get ~url ~target:"/mint" () in
        let cookie = Pch.session_cookie "top mint" response in
        let* third =
          do_post ~url ~cookie
            ~target:
              (community_side_target ~community:"phrh-rhome" ~project:"phrh-rproj")
            ~token:mint ()
        in
        let* () =
          check_clean_redirect_lwt "cross-surface replay"
            "/c/phrh-rhome/settings?panel=projects" third
        in
        let* removed = find conn "removed count" q_count_removed project in
        Alcotest.(check int) "still exactly one removal" 1 removed;
        Lwt.return_unit)

  let concurrency_case =
    db_case "removal: two concurrent removals commit exactly one; the loser \
             receives the same 303 destination" (fun ~url conn ->
        let* owner = insert_user conn "phrh_kowner" in
        let* top = insert_user conn "phrh_ktop" in
        let* admin = insert_user conn "phrh_kadmin" in
        let* cid = insert_community ~name:"Phrh Khome" conn "phrh-khome" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        let* () = set_admin conn ~user:admin true in
        (* A second connection holds the winning removal's transaction open
           while the HTTP loser is launched, so the outcome is deterministic
           without sleeps. *)
        let url_of () =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some u -> u
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let race label ~ext_id ~slug ~loser ~target ~expected =
          let* project =
            make_project conn ~user:owner ~ext_id ~slug ~name:"Phrh Race"
          in
          let* () =
            accepted_home slug conn ~owner ~reviewer:top ~slug ~cid
              ~community_slug:"phrh-khome" ()
          in
          let* rid = relation_id conn ~project ~community:cid in
          as_user loser;
          let* response, token = do_get ~url ~target:"/mint" () in
          let cookie = Pch.session_cookie label response in
          let* conn2 = Caqti_lwt_unix.connect (Uri.of_string (url_of ())) in
          let* conn2 = or_fail "second connect" conn2 in
          let (module C2 : Caqti_lwt.CONNECTION) = conn2 in
          Lwt.finalize
            (fun () ->
              let* r = C2.start () in
              let* () = or_fail "second begin" r in
              (* The winner removes on the second connection, holding its
                 locks. *)
              let* winner =
                Earde.Project_home_removal_store.remove conn2
                  ~actor_user_id:owner ~project_slug:slug
                  ~community_slug:"phrh-khome"
              in
              (match winner with
               | Ok _ -> ()
               | Error _ -> Alcotest.failf "%s: winner failed" label);
              let loser_promise = do_post ~url ~cookie ~target ~token () in
              let* r = C2.commit () in
              let* () = or_fail "second commit" r in
              let* response = loser_promise in
              let* () = check_clean_redirect_lwt label expected response in
              let* () = check_status label conn rid "removed" in
              let* removed = find conn "removed count" q_count_removed project in
              Alcotest.(check int) (label ^ ": exactly one removal") 1 removed;
              Lwt.return_unit)
            (fun () -> C2.disconnect ())
        in
        (* Two project-side removals. *)
        let* () =
          race "project vs project" ~ext_id:948000090L ~slug:"phrh-k1"
            ~loser:owner
            ~target:
              (project_side_target ~project:"phrh-k1" ~community:"phrh-khome")
            ~expected:"/projects/phrh-k1/request-home"
        in
        (* Project-side winner versus community-side loser. *)
        let* () =
          race "project vs community" ~ext_id:948000091L ~slug:"phrh-k2"
            ~loser:top
            ~target:
              (community_side_target ~community:"phrh-khome" ~project:"phrh-k2")
            ~expected:"/c/phrh-khome/settings?panel=projects"
        in
        (* Top moderator versus durable admin. *)
        race "top mod vs admin" ~ext_id:948000092L ~slug:"phrh-k3" ~loser:admin
          ~target:
            (community_side_target ~community:"phrh-khome" ~project:"phrh-k3")
          ~expected:"/c/phrh-khome/settings?panel=projects")

  (* === lifecycle drift === *)

  let drift_case =
    db_case_lifecycle_relaxed "removal: both surfaces still remove across project verification \
             drift and community lifecycle drift" (fun ~url conn ->
        let* owner = insert_user conn "phrh_downer" in
        let* top = insert_user conn "phrh_dtop" in
        let setup ~ext_id ~slug ~cid ~community_slug =
          let* project =
            make_project conn ~user:owner ~ext_id ~slug ~name:"Phrh Drift"
          in
          let* () =
            accepted_home slug conn ~owner ~reviewer:top ~slug ~cid
              ~community_slug ()
          in
          let* rid = relation_id conn ~project ~community:cid in
          Lwt.return (project, rid)
        in
        let remove_via label uid ~target ~expected =
          as_user uid;
          let* response, token = do_get ~url ~target:"/mint" () in
          let cookie = Pch.session_cookie label response in
          let* response = do_post ~url ~cookie ~target ~token () in
          check_clean_redirect_lwt label expected response
        in
        (* A stale and a revoked project, one per surface. *)
        let* cid = insert_community ~name:"Phrh Dhome" conn "phrh-dhome" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        let* p1, r1 =
          setup ~ext_id:948000100L ~slug:"phrh-d1" ~cid
            ~community_slug:"phrh-dhome"
        in
        let* p2, r2 =
          setup ~ext_id:948000101L ~slug:"phrh-d2" ~cid
            ~community_slug:"phrh-dhome"
        in
        let* () = exec conn "stale" q_set_verification (p1, "stale") in
        let* () = exec conn "revoked" q_set_verification (p2, "revoked") in
        let* () =
          remove_via "stale project" owner
            ~target:(project_side_target ~project:"phrh-d1" ~community:"phrh-dhome")
            ~expected:"/projects/phrh-d1/request-home"
        in
        let* () = check_status "stale project removed" conn r1 "removed" in
        let* () =
          remove_via "revoked project" top
            ~target:
              (community_side_target ~community:"phrh-dhome" ~project:"phrh-d2")
            ~expected:"/c/phrh-dhome/settings?panel=projects"
        in
        let* () = check_status "revoked project removed" conn r2 "removed" in
        (* A private, a draft, and a legacy community. *)
        let drifted label ~ext_id ~slug ~community_slug ~drift ~uid ~target
            ~expected =
          let* cid' = insert_community ~name:label conn community_slug in
          let* () = add_top_mod conn ~user:top ~community:cid' in
          let* _p, rid = setup ~ext_id ~slug ~cid:cid' ~community_slug in
          let* () = drift cid' in
          let* () = remove_via label uid ~target ~expected in
          check_status label conn rid "removed"
        in
        let* () =
          drifted "private community" ~ext_id:948000110L ~slug:"phrh-d3"
            ~community_slug:"phrh-dpriv"
            ~drift:(fun c -> exec conn "private" Phcv.q_make_private c)
            ~uid:owner
            ~target:(project_side_target ~project:"phrh-d3" ~community:"phrh-dpriv")
            ~expected:"/projects/phrh-d3/request-home"
        in
        (* Drift into the exact unpublished network setup draft is the one
           lifecycle that is not ordinary drift. A dedicated draft's home is
           auto-provisioned with no requester, reviewer or note, so a
           moderator-reviewed accepted home under that lifecycle is
           contradictory provenance: the store answers Inconsistent_data and
           the handler turns that into its existing generic 500, never a
           redirect that names a lifecycle. Nothing is mutated. *)
        let* () =
          let* cid' = insert_community ~name:"Phrh Ddraft" conn "phrh-ddraft" in
          let* () = add_top_mod conn ~user:top ~community:cid' in
          let* _p, rid =
            setup ~ext_id:948000111L ~slug:"phrh-d4" ~cid:cid'
              ~community_slug:"phrh-ddraft"
          in
          let* () = exec conn "draft" Phcv.q_make_draft_state cid' in
          as_user top;
          let* response, token = do_get ~url ~target:"/mint" () in
          let cookie = Pch.session_cookie "draft community" response in
          let* response =
            do_post ~url ~cookie
              ~target:
                (community_side_target ~community:"phrh-ddraft"
                   ~project:"phrh-d4")
              ~token ()
          in
          let* body = Dream.body response in
          check_generic_500 "draft community" response body;
          check_status "draft community: relation untouched" conn rid
            "accepted"
        in
        drifted "legacy community" ~ext_id:948000112L ~slug:"phrh-d5"
          ~community_slug:"phrh-dlegacy"
          ~drift:(fun c -> exec conn "legacy" Phcv.q_make_legacy c)
          ~uid:owner
          ~target:
            (project_side_target ~project:"phrh-d5" ~community:"phrh-dlegacy")
          ~expected:"/projects/phrh-d5/request-home")

  (* === durable failures === *)

  let store_failure_case =
    db_case_lifecycle_relaxed "removal: a store storage failure or durable inconsistency is one \
             generic non-cacheable 500 with no partial mutation"
      (fun ~url conn ->
        let* owner = insert_user conn "phrh_gowner" in
        let* top = insert_user conn "phrh_gtop" in
        let* project =
          make_project conn ~user:owner ~ext_id:948000120L ~slug:"phrh-gproj"
            ~name:"Phrh Gproj"
        in
        let* other =
          make_project conn ~user:owner ~ext_id:948000121L ~slug:"phrh-gother"
            ~name:"Phrh Gother"
        in
        let* cid = insert_community ~name:"Phrh Ghome" conn "phrh-ghome" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        (* The poisoned relation carries the reserved note the trigger keys
           on; the trigger is installed only after the review store already
           accepted it. *)
        let* () =
          accepted_home "poisoned" conn ~owner ~reviewer:top ~slug:"phrh-gproj"
            ~cid ~community_slug:"phrh-ghome" ~note:poison_note ()
        in
        let* rid = relation_id conn ~project ~community:cid in
        let* () =
          accepted_home "corrupt" conn ~owner ~reviewer:top ~slug:"phrh-gother"
            ~cid ~community_slug:"phrh-ghome" ()
        in
        let* other_rid = relation_id conn ~project:other ~community:cid in
        let post label ~target =
          as_user owner;
          let* response, token = do_get ~url ~target:"/mint" () in
          let cookie = Pch.session_cookie label response in
          let* response = do_post ~url ~cookie ~target ~token () in
          let* body = Dream.body response in
          check_generic_500 label response body;
          check_no_credentials label response body;
          Lwt.return_unit
        in
        let* () = exec conn "create fn" q_create_fail_fn () in
        let* () =
          Lwt.finalize
          (fun () ->
            let* () = exec conn "create trigger" q_create_fail_trigger () in
            let* () =
              post "storage failure"
                ~target:
                  (project_side_target ~project:"phrh-gproj"
                     ~community:"phrh-ghome")
            in
            (* Complete rollback: the relation is still accepted. *)
            check_status "rolled back" conn rid "accepted")
          (fun () ->
            let* () = exec conn "drop trigger" q_drop_fail_trigger () in
            exec conn "drop fn" q_drop_fail_fn ())
        in
        (* Durable inconsistency: contradictory publication flags on the
           locked community. *)
        let* () = exec conn "mix flags" q_mix_flags cid in
        let* () =
          post "inconsistent data"
            ~target:
              (community_side_target ~community:"phrh-ghome"
                 ~project:"phrh-gother")
        in
        (* Nothing was mutated on the way to the generic 500. *)
        let* () = check_status "still accepted" conn other_rid "accepted" in
        exec conn "restore eligible" Phrv.q_make_eligible cid)

  (* === privacy sweep === *)

  let privacy_case =
    db_case "removal: no credential-shaped fixture, private note, or internal \
             id appears in any form, redirect, error, or cookie"
      (fun ~url conn ->
        let* owner = insert_user conn "phrh_powner" in
        let* top = insert_user conn "phrh_ptop" in
        let* project =
          make_project conn ~user:owner ~ext_id:948000130L ~slug:"phrh-pproj"
            ~name:"Phrh Pproj"
        in
        let* cid = insert_community ~name:"Phrh Phome" conn "phrh-phome" in
        let* () = add_top_mod conn ~user:top ~community:cid in
        let* () =
          accepted_home "fixture" conn ~owner ~reviewer:top ~slug:"phrh-pproj"
            ~cid ~community_slug:"phrh-phome" ()
        in
        let* rid = relation_id conn ~project ~community:cid in
        (* Internal identifiers are swept out of everything the browser can
           keep: the redirect Location and every response header (cookies
           included). Response bodies are swept for the credential-shaped
           fixtures and the private workflow vocabulary instead — a short
           serial id would false-positive inside an opaque CSRF token. *)
        let internal_ids =
          [ ("relation id", Int64.to_string rid);
            ("project id", Int64.to_string project);
            ("community id", string_of_int cid);
            ("steward id", string_of_int owner);
            ("moderator id", string_of_int top)
          ]
        in
        let header_text response =
          String.concat "\n"
            (List.map (fun (k, v) -> k ^ ": " ^ v) (Dream.all_headers response))
        in
        let sweep_headers label response =
          let headers = header_text response in
          List.iter
            (fun (what, needle) ->
              Alcotest.(check bool) (label ^ ": headers free of " ^ what) false
                (contains headers needle))
            internal_ids;
          List.iter
            (fun (what, needle) ->
              Alcotest.(check bool) (label ^ ": headers free of " ^ what) false
                (contains headers needle))
            credential_markers
        in
        let sweep_body label body =
          List.iter
            (fun (what, needle) ->
              Alcotest.(check bool) (label ^ ": body free of " ^ what) false
                (contains body needle))
            credential_markers;
          List.iter
            (fun needle ->
              Alcotest.(check bool) (label ^ ": body free of " ^ needle) false
                (contains body needle))
            [ "requested_by"; "reviewed_by"; "request_note"; "relation_id";
              "top_mod"; "is_admin"; "Requested by"; "Reviewed by" ]
        in
        (* The steward form. *)
        as_user owner;
        let* page_response, page_body =
          do_get ~url ~target:(request_home_target "phrh-pproj") ()
        in
        Alcotest.(check int) "steward page 200" 200 (status_of page_response);
        sweep_body "steward page" page_body;
        sweep_headers "steward page" page_response;
        let cookie = Pch.session_cookie "steward page" page_response in
        let token = Pch.csrf_of_page "steward page" page_body in
        (* The settings management section. *)
        as_user top;
        let* settings_response, settings_body =
          do_get ~url ~target:(settings_projects_target "phrh-phome") ()
        in
        Alcotest.(check int) "settings 200" 200 (status_of settings_response);
        sweep_body "settings section" settings_body;
        sweep_headers "settings section" settings_response;
        (* The redirect itself: an exact server-built Location, nothing else. *)
        as_user owner;
        let* response =
          do_post ~url ~cookie
            ~target:
              (project_side_target ~project:"phrh-pproj" ~community:"phrh-phome")
            ~token ()
        in
        let* redirect_body = Dream.body response in
        Alcotest.(check (option string)) "exact Location"
          (Some "/projects/phrh-pproj/request-home")
          (Dream.header response "Location");
        Alcotest.(check string) "empty redirect body" "" redirect_body;
        sweep_headers "removal redirect" response;
        (* And an error path. *)
        let* stranger = insert_user conn "phrh_pstranger" in
        as_user stranger;
        let* mint_response, mint = do_get ~url ~target:"/mint" () in
        let cookie = Pch.session_cookie "stranger mint" mint_response in
        let* response =
          do_post ~url ~cookie
            ~target:
              (project_side_target ~project:"phrh-pproj" ~community:"phrh-phome")
            ~token:mint ()
        in
        let* body = Dream.body response in
        check_generic_404 "stranger" response body;
        sweep_body "stranger 404" body;
        sweep_headers "stranger 404" response;
        Lwt.return_unit)

  let page_suite =
    project_form_cases @ section_cases @ defensive_cases @ csrf_field_cases
    @ protected_cases

  let db_suite =
    [ project_side_success_case; community_side_success_case;
      settings_surface_case; settings_labels_case; settings_failure_case;
      authority_case; cross_surface_case; unauthorized_case; replay_case;
      concurrency_case; drift_case; store_failure_case; privacy_case ]
end


(* === Initial community-identity form (Project_home_provisioning_form) ===
   The strict parser behind the future POST /projects/:slug/community-home:
   exact field grammar, the canonicalization the future provisioning store
   inherits, and the payload-free error contract. Pure — no DB, no request,
   no session. *)
module Phvf = Earde.Project_home_provisioning_form

let phvf_err : Phvf.error -> string = function
  | Phvf.Invalid_form -> "Invalid_form"
  | Phvf.Invalid_community_name -> "Invalid_community_name"
  | Phvf.Invalid_community_slug -> "Invalid_community_slug"
  | Phvf.Invalid_community_description -> "Invalid_community_description"

let phvf_case = go_case

let phvf_fields ?(name = "Phvf Community") ?(slug = "phvf-community")
    ?(description = "") () =
  [ ("community_name", name);
    ("community_slug", slug);
    ("community_description", description)
  ]

let phvf_ok label fields =
  match Phvf.of_fields fields with
  | Ok parsed -> parsed
  | Error e -> Alcotest.failf "%s: rejected with %s" label (phvf_err e)

let phvf_expect label expected fields =
  match Phvf.of_fields fields with
  | Ok _ -> Alcotest.failf "%s: expected %s, got Ok" label (phvf_err expected)
  | Error e -> Alcotest.(check string) label (phvf_err expected) (phvf_err e)

(* A two-byte scalar, so length rules are proven to count scalars (as
   PostgreSQL char_length does) rather than bytes. *)
let phvf_scalar = "\xc3\xa8"

let phvf_repeat s n = String.concat "" (List.init n (fun _ -> s))

let phvf_grammar_cases =
  [ phvf_case "form: a valid submission keeps every canonical value exactly"
      (fun () ->
        let parsed =
          phvf_ok "valid"
            (phvf_fields ~name:"Phvf Community" ~slug:"phvf-community"
               ~description:"A durable description." ())
        in
        Alcotest.(check string) "name" "Phvf Community"
          (Phvf.community_name parsed);
        Alcotest.(check string) "slug" "phvf-community"
          (Phvf.community_slug parsed);
        Alcotest.(check (option string)) "description"
          (Some "A durable description.")
          (Phvf.community_description parsed))
  ; phvf_case "form: field order is irrelevant" (fun () ->
        let parsed =
          phvf_ok "reordered"
            [ ("community_description", "Body");
              ("community_slug", "phvf-order");
              ("community_name", "Phvf Order")
            ]
        in
        Alcotest.(check string) "name" "Phvf Order" (Phvf.community_name parsed);
        Alcotest.(check string) "slug" "phvf-order" (Phvf.community_slug parsed);
        Alcotest.(check (option string)) "description" (Some "Body")
          (Phvf.community_description parsed))
  ; phvf_case "form: every missing field is the same structural rejection"
      (fun () ->
        List.iter
          (fun drop ->
            let fields =
              List.filter (fun (k, _) -> k <> drop) (phvf_fields ())
            in
            phvf_expect ("missing " ^ drop) Phvf.Invalid_form fields)
          [ "community_name"; "community_slug"; "community_description" ];
        phvf_expect "empty submission" Phvf.Invalid_form [])
  ; phvf_case "form: every duplicated field is the same structural rejection"
      (fun () ->
        List.iter
          (fun (k, v) ->
            phvf_expect ("duplicate " ^ k) Phvf.Invalid_form
              (phvf_fields () @ [ (k, v) ]))
          [ ("community_name", "Phvf Community");
            ("community_slug", "phvf-community");
            ("community_description", "")
          ])
  ; phvf_case "form: unknown, case-variant, and padded field names reject"
      (fun () ->
        List.iter
          (fun name ->
            phvf_expect ("unknown " ^ name) Phvf.Invalid_form
              (phvf_fields () @ [ (name, "x") ]))
          [ "Community_name"; "COMMUNITY_SLUG"; " community_name";
            "community_name "; "community_name\t"; "communityname";
            "community_visibility"; "project_slug"; "project_id"; "user_id";
            "return_url"; "publish"; ""
          ];
        (* A recognized field spelled differently is not a substitute. *)
        phvf_expect "case-variant replacement" Phvf.Invalid_form
          [ ("Community_name", "Phvf"); ("community_slug", "phvf-x");
            ("community_description", "")
          ])
  ; phvf_case "form: a dream.csrf field reaching the parser is a wiring bug, \
               not an accepted field" (fun () ->
        phvf_expect "csrf present" Phvf.Invalid_form
          (("dream.csrf", "token") :: phvf_fields ());
        phvf_expect "csrf last" Phvf.Invalid_form
          (phvf_fields () @ [ ("dream.csrf", "token") ]))
  ; phvf_case "form: a structural failure never becomes a semantic one"
      (fun () ->
        (* Malformed name and slug plus an unknown field: the answer names
           no field at all. *)
        phvf_expect "structure wins" Phvf.Invalid_form
          [ ("community_name", "   "); ("community_slug", "NOPE");
            ("community_description", ""); ("extra", "x")
          ])
  ]

let phvf_name_cases =
  [ phvf_case "form name: outer ASCII whitespace is trimmed, inner bytes are \
               untouched" (fun () ->
        let parsed =
          phvf_ok "trimmed"
            (phvf_fields ~name:"  Progetto Phvf \t\n" ())
        in
        Alcotest.(check string) "canonical name" "Progetto Phvf"
          (Phvf.community_name parsed);
        (* No lowercasing, no Unicode rewriting. *)
        let accented =
          phvf_ok "accented" (phvf_fields ~name:("Perch" ^ phvf_scalar) ())
        in
        Alcotest.(check string) "bytes preserved" ("Perch" ^ phvf_scalar)
          (Phvf.community_name accented))
  ; phvf_case "form name: blank names reject" (fun () ->
        List.iter
          (fun name ->
            phvf_expect ("blank " ^ String.escaped name)
              Phvf.Invalid_community_name (phvf_fields ~name ()))
          [ ""; " "; "\t"; "\n"; "\r"; "\x0c"; "\x0b"; "   \t\n  " ])
  ; phvf_case "form name: the maximum is counted in scalars, not bytes, and \
               nothing is truncated" (fun () ->
        let at_max = phvf_repeat phvf_scalar 120 in
        let parsed = phvf_ok "120 scalars" (phvf_fields ~name:at_max ()) in
        Alcotest.(check string) "kept whole" at_max
          (Phvf.community_name parsed);
        Alcotest.(check int) "240 bytes accepted" 240
          (String.length (Phvf.community_name parsed));
        phvf_expect "121 scalars" Phvf.Invalid_community_name
          (phvf_fields ~name:(phvf_repeat phvf_scalar 121) ());
        phvf_expect "121 ASCII" Phvf.Invalid_community_name
          (phvf_fields ~name:(String.make 121 'a') ());
        let ascii_max = phvf_ok "120 ASCII" (phvf_fields ~name:(String.make 120 'a') ()) in
        Alcotest.(check int) "120 ASCII kept" 120
          (String.length (Phvf.community_name ascii_max)))
  ; phvf_case "form name: invalid UTF-8, NUL, controls, and DEL reject"
      (fun () ->
        List.iter
          (fun name ->
            phvf_expect ("hostile " ^ String.escaped name)
              Phvf.Invalid_community_name (phvf_fields ~name ()))
          [ "Phvf\xff"; "\xc3"; "\xed\xa0\x80"; "Phvf\x00Community";
            "Phvf\x01"; "Phvf\x1f"; "Phvf\x7f"; "Phvf\tCommunity";
            "Phvf\nCommunity"; "Phvf\rCommunity"
          ])
  ]

let phvf_slug_cases =
  [ phvf_case "form slug: the canonical grammar is accepted exactly as \
               submitted" (fun () ->
        List.iter
          (fun slug ->
            let parsed = phvf_ok ("valid " ^ slug) (phvf_fields ~slug ()) in
            Alcotest.(check string) ("byte-identical " ^ slug) slug
              (Phvf.community_slug parsed))
          [ "a"; "z9"; "phvf"; "phvf-community"; "a-b-c-d"; "0"; "0-1";
            String.make 80 'a'; "new"
          ])
  ; phvf_case "form slug: nothing is trimmed, lowercased, or repaired"
      (fun () ->
        List.iter
          (fun slug ->
            phvf_expect ("noncanonical " ^ String.escaped slug)
              Phvf.Invalid_community_slug (phvf_fields ~slug ()))
          [ " phvf"; "phvf "; " phvf "; "\tphvf"; "phvf\n"; "PHVF";
            "Phvf-Community"; "phvF"
          ])
  ; phvf_case "form slug: structural violations reject" (fun () ->
        List.iter
          (fun slug ->
            phvf_expect ("malformed " ^ String.escaped slug)
              Phvf.Invalid_community_slug (phvf_fields ~slug ()))
          [ ""; "-"; "-phvf"; "phvf-"; "phvf--community"; "phvf_community";
            "phvf.community"; "phvf/community"; "phvf community"; "phvf%20x";
            "phvf\x00"; "phvf\x7f"; "phvf" ^ phvf_scalar; "../phvf";
            "phvf?x=1"; "phvf#a"
          ])
  ; phvf_case "form slug: the length boundary is exact" (fun () ->
        let at_max = String.make 80 'a' in
        Alcotest.(check string) "80 accepted" at_max
          (Phvf.community_slug (phvf_ok "80" (phvf_fields ~slug:at_max ())));
        phvf_expect "81" Phvf.Invalid_community_slug
          (phvf_fields ~slug:(String.make 81 'a') ()))
  ]

let phvf_description_cases =
  [ phvf_case "form description: blank input canonicalizes to no description"
      (fun () ->
        List.iter
          (fun description ->
            let parsed =
              phvf_ok ("blank " ^ String.escaped description)
                (phvf_fields ~description ())
            in
            Alcotest.(check (option string))
              ("None for " ^ String.escaped description)
              None
              (Phvf.community_description parsed))
          [ ""; " "; "\t"; "\n"; "\r\n"; "   \t \n  " ])
  ; phvf_case "form description: multiline text survives with LF endings"
      (fun () ->
        let parsed =
          phvf_ok "multiline"
            (phvf_fields ~description:"  First line\r\nSecond\rThird\tcol  " ())
        in
        Alcotest.(check (option string)) "normalized and trimmed"
          (Some "First line\nSecond\nThird\tcol")
          (Phvf.community_description parsed))
  ; phvf_case "form description: the maximum is counted in scalars and nothing \
               is truncated" (fun () ->
        let at_max = phvf_repeat phvf_scalar 2000 in
        let parsed = phvf_ok "2000 scalars" (phvf_fields ~description:at_max ()) in
        Alcotest.(check (option string)) "kept whole" (Some at_max)
          (Phvf.community_description parsed);
        phvf_expect "2001 scalars" Phvf.Invalid_community_description
          (phvf_fields ~description:(phvf_repeat phvf_scalar 2001) ());
        phvf_expect "2001 ASCII" Phvf.Invalid_community_description
          (phvf_fields ~description:(String.make 2001 'a') ()))
  ; phvf_case "form description: invalid UTF-8, NUL, and forbidden controls \
               reject" (fun () ->
        List.iter
          (fun description ->
            phvf_expect ("hostile " ^ String.escaped description)
              Phvf.Invalid_community_description (phvf_fields ~description ()))
          [ "Body\xff"; "\xc3"; "Body\x00"; "Body\x01"; "Body\x1f";
            "Body\x7f"; "Bo\x0bdy"; "Bo\x0cdy"; "Bo\rdy\x00"
          ];
        (* A trailing VT or FF is outer whitespace: it is trimmed away, so
           the surviving text is ordinary and accepted. *)
        List.iter
          (fun description ->
            Alcotest.(check (option string))
              ("trimmed " ^ String.escaped description)
              (Some "Body")
              (Phvf.community_description
                 (phvf_ok "trimmed control" (phvf_fields ~description ()))))
          [ "Body\x0b"; "Body\x0c"; "\x0bBody\x0c" ])
  ; phvf_case "form description: no Markdown or HTML processing happens here"
      (fun () ->
        let raw = "**bold** <script>alert(1)</script> [x](y)" in
        let parsed = phvf_ok "raw" (phvf_fields ~description:raw ()) in
        Alcotest.(check (option string)) "byte-identical" (Some raw)
          (Phvf.community_description parsed))
  ; phvf_case "form: validation order is name, then slug, then description"
      (fun () ->
        phvf_expect "name first" Phvf.Invalid_community_name
          (phvf_fields ~name:"" ~slug:"NOPE" ~description:"Body\x00" ());
        phvf_expect "slug second" Phvf.Invalid_community_slug
          (phvf_fields ~name:"Phvf" ~slug:"NOPE" ~description:"Body\x00" ());
        phvf_expect "description last" Phvf.Invalid_community_description
          (phvf_fields ~name:"Phvf" ~slug:"phvf-x" ~description:"Body\x00" ()))
  ]

let phvf_suite =
  phvf_grammar_cases @ phvf_name_cases @ phvf_slug_cases
  @ phvf_description_cases

(* === Dedicated-home creation page (Project_home_provisioning_pages) ===
   Pure rendering: the exact form contract, the setup-draft and publication
   copy, defensive degradation, escaping, and the absence of officiality
   language, hidden identifiers, and script. DB-free. *)
module Phvp = Earde.Project_home_provisioning_pages

let phvp_case = go_case

let phvp_project ?(name = "Phvp Project") ?(slug = "phvp-project") ?description
    ?(kind = Pi.Project) ?(login = "phvp-owner") () : Phvp.project =
  { Phvp.name; slug; description; kind; namespace_login = login }

let phvp_values ?(name = "") ?(slug = "") ?(description = "") () :
    Phvp.form_values =
  { Phvp.community_name = name;
    community_slug = slug;
    community_description = description
  }

(* Assertions run over the feature fragment, not the whole page: the shared
   shell owns its own forms and chrome, and this suite is about what the
   provisioning surface itself renders. *)
let phvp_render ?request ?(project = phvp_project ())
    ?(values = phvp_values ()) ?feedback () =
  ps_fragment
    (Phvp.project_home_provisioning_page ?request ~project ~values ~feedback ())

(* A live request under a secret + sessions pipeline, so the framework CSRF
   field can be emitted; no SQL is touched. *)
let phvp_live ?project ?values ?feedback () =
  let captured = ref None in
  let pipeline =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    captured := Some (phvp_render ~request:req ?project ?values ?feedback ());
    Dream.html ""
  in
  ignore (Lwt_main.run (pipeline (Dream.request ~method_:`GET ~target:"/" "")));
  match !captured with
  | Some html -> html
  | None -> Alcotest.fail "provisioning renderer did not run"

let phvp_action = "action='/projects/phvp-project/community-home'"

let phvp_copy_cases =
  [ phvp_case "provisioning page: heading, setup-draft copy, and factual \
               verification wording" (fun () ->
        let html = phvp_render () in
        ps_must html "Create a community home";
        ps_must html
          "Create a private setup draft for this project, then configure and \
           publish it as Public or Unlisted.";
        ps_must html "Project connected through GitHub";
        ps_must html "private setup draft";
        ps_must html "It is not public yet.";
        ps_must html "Only authorized setup users can reach it before \
                      publication.";
        ps_must html "initial top moderator";
        ps_must html "Publication is a separate, later step")
  ; phvp_case "provisioning page: publication offers Public or Unlisted and \
               never a fully private published community" (fun () ->
        let html = phvp_render () in
        ps_must html "you choose Public or Unlisted";
        ps_must html "keeps a public home, with private rooms available";
        List.iter (ps_must_not html)
          [ "fully private"; "Fully private"; "Private community";
            "publish as Private"; "Public, Unlisted, or Private"
          ])
  ; phvp_case "provisioning page: no officiality or endorsement language, and \
               no claim that a draft already exists" (fun () ->
        let html = phvp_render ~project:(phvp_project ~description:"A project." ()) () in
        List.iter (ps_must_not html)
          [ "Official"; "official"; "GitHub-approved"; "GitHub-endorsed";
            "endorsed"; "approved by GitHub"
          ];
        List.iter (ps_must_not html)
          [ "Your draft community"; "The draft community is";
            "已"; "already been created"; "has been created"
          ])
  ; phvp_case "provisioning page: the project identity renders as escaped \
               text only" (fun () ->
        let html =
          phvp_render
            ~project:
              (phvp_project ~name:"Phvp Alpha" ~kind:Pi.Ecosystem
                 ~login:"phvp-org" ~description:"**not** <b>markup</b>" ())
            ()
        in
        ps_must html "Phvp Alpha";
        ps_must html "Ecosystem";
        ps_must html "phvp-org";
        ps_must html "**not** &lt;b&gt;markup&lt;/b&gt;";
        ps_must_not html "<b>markup</b>")
  ]

let phvp_form_cases =
  [ phvp_case "provisioning form: exactly one POST form to the exact future \
               route" (fun () ->
        let html = phvp_live () in
        Alcotest.(check int) "one form" 1 (ps_count html "<form");
        Alcotest.(check int) "POST method" 1 (ps_count html "method='POST'");
        Alcotest.(check int) "exact action" 1 (ps_count html phvp_action);
        ps_must html "Create private draft";
        (* Nameless submit control. *)
        ps_must_not html "<button type='submit' name")
  ; phvp_case "provisioning form: exactly the three application fields, and \
               no hidden field of our own" (fun () ->
        let html = phvp_live () in
        List.iter
          (fun field ->
            Alcotest.(check int)
              ("one " ^ field)
              1
              (ps_count html (Printf.sprintf "name='%s'" field)))
          [ "community_name"; "community_slug"; "community_description" ];
        Alcotest.(check int) "two text inputs plus the framework CSRF field" 3
          (ps_count html "<input");
        Alcotest.(check int) "one textarea" 1 (ps_count html "<textarea");
        Alcotest.(check int) "no select" 0 (ps_count html "<select");
        (* The only hidden input is Dream's own, in its own quoting style. *)
        Alcotest.(check int) "no hidden field of ours" 0
          (ps_count html "type='hidden'");
        Alcotest.(check int) "exactly one framework hidden field" 1
          (ps_count html "type=\"hidden\"");
        List.iter (ps_must_not html)
          [ "name='project_slug'"; "name='project_id'"; "name='user_id'";
            "name='installation_id'"; "name='repository_id'";
            "name='return_url'"; "name='visibility'"; "name='publish'";
            "name='active_home'"
          ])
  ; phvp_case "provisioning form: the framework CSRF field appears only with a \
               live request" (fun () ->
        let pure = phvp_render () in
        Alcotest.(check int) "pure render has no CSRF field" 0
          (ps_count pure "dream.csrf");
        Alcotest.(check int) "pure render still has the form" 1
          (ps_count pure "<form");
        let live = phvp_live () in
        Alcotest.(check int) "live render has one CSRF field" 1
          (ps_count live "name=\"dream.csrf\""))
  ; phvp_case "provisioning form: suggested values populate the controls and \
               stay escaped" (fun () ->
        let html =
          phvp_render
            ~values:
              (phvp_values ~name:"Phvp Suggested" ~slug:"phvp-suggested"
                 ~description:"Suggested body" ())
            ()
        in
        ps_must html "value='Phvp Suggested'";
        ps_must html "value='phvp-suggested'";
        ps_must html ">Suggested body</textarea>";
        let hostile =
          phvp_render
            ~values:
              (phvp_values ~name:"' onfocus='alert(1)"
                 ~slug:"'><script>alert(1)</script>"
                 ~description:"</textarea><script>alert(1)</script>" ())
            ()
        in
        ps_must_not hostile "<script";
        ps_must_not hostile "onfocus='alert";
        ps_must hostile "&#39;")
  ; phvp_case "provisioning form: an empty suggested slug renders an empty \
               control rather than a repaired value" (fun () ->
        let html =
          phvp_render ~values:(phvp_values ~name:"Phvp" ~slug:"" ()) ()
        in
        ps_must html "name='community_slug' maxlength='80' value=''")
  ]

let phvp_defensive_cases =
  [ phvp_case "provisioning page: an invalid project slug suppresses the form \
               and every project-derived link" (fun () ->
        List.iter
          (fun slug ->
            let html = phvp_live ~project:(phvp_project ~slug ()) () in
            Alcotest.(check int) ("no form for " ^ String.escaped slug) 0
              (ps_count html "<form");
            Alcotest.(check int) ("no action for " ^ String.escaped slug) 0
              (ps_count html "action=");
            Alcotest.(check int) ("no project link for " ^ String.escaped slug) 0
              (ps_count html "href='/projects/");
            (* The copy survives; only the actions disappear. *)
            ps_must html "Create a community home";
            ps_must html "Project connected through GitHub")
          [ ""; "Phvp-Project"; "phvp_project"; "-phvp"; "phvp-";
            "phvp/project"; "phvp project"; "phvp--project";
            String.make 81 'a'
          ])
  ; phvp_case "provisioning page: a canonical slug yields the back link too"
      (fun () ->
        let html = phvp_render () in
        ps_must html "href='/projects/phvp-project/setup'";
        ps_must html "Back to project setup")
  ; phvp_case "provisioning page: no identifier of any kind is rendered"
      (fun () ->
        let html =
          phvp_live
            ~project:(phvp_project ~description:"desc" ())
            ~values:(phvp_values ~name:"Phvp" ~slug:"phvp-project" ())
            ()
        in
        List.iter (ps_must_not html)
          [ "project_id"; "draft_id"; "installation_id"; "steward_id";
            "relation_id"; "community_id"; "forge_namespace_id"
          ])
  ; phvp_case "provisioning page: no script, inline style, handler, or refresh"
      (fun () ->
        let html = phvp_live ~feedback:Phvp.Provisioning_failed () in
        List.iter (ps_must_not html)
          [ "<script"; "javascript:"; "onclick"; "onsubmit"; "onload";
            "onerror"; "style='"; "style=\""; "http-equiv"; "window.location";
            "location.href"
          ])
  ; phvp_case "provisioning page: no credential-shaped fixture can appear"
      (fun () ->
        let html =
          phvp_live ~project:(phvp_project ~login:"phvp-owner" ()) ()
        in
        List.iter (ps_must_not html)
          [ "gho_"; "ghr_"; "ghs_"; "client_secret"; "code_verifier";
            "access_token"
          ])
  ]

let phvp_feedback_cases =
  [ phvp_case "provisioning page: no feedback renders no alert" (fun () ->
        let html = phvp_render () in
        Alcotest.(check int) "no alert" 0 (ps_count html "phv-alert"))
  ; phvp_case "provisioning page: every feedback variant renders exactly one \
               generic alert that echoes no submitted value" (fun () ->
        let variants =
          [ ("Stale_form", Phvp.Stale_form);
            ("Invalid_form", Phvp.Invalid_form);
            ("Invalid_community_name", Phvp.Invalid_community_name);
            ("Invalid_community_slug", Phvp.Invalid_community_slug);
            ("Invalid_community_description", Phvp.Invalid_community_description);
            ("Community_slug_unavailable", Phvp.Community_slug_unavailable);
            ("Active_home_exists", Phvp.Active_home_exists);
            ("Provisioning_failed", Phvp.Provisioning_failed)
          ]
        in
        let seen = ref [] in
        List.iter
          (fun (label, feedback) ->
            let html =
              phvp_render
                ~values:
                  (phvp_values ~name:"SECRETNAME" ~slug:"SECRETSLUG"
                     ~description:"SECRETBODY" ())
                ~feedback ()
            in
            Alcotest.(check int) (label ^ ": one alert") 1
              (ps_count html "phv-alert");
            (* The alert text itself never repeats what was submitted. *)
            let alert_start =
              match ps_index_of html "phv-alert" 0 with
              | Some i -> i
              | None -> Alcotest.failf "%s: alert missing" label
            in
            let alert_end =
              match ps_index_of html "</div>" alert_start with
              | Some i -> i
              | None -> Alcotest.failf "%s: unterminated alert" label
            in
            let alert =
              String.sub html alert_start (alert_end - alert_start)
            in
            List.iter
              (fun secret ->
                Alcotest.(check bool)
                  (label ^ ": alert free of " ^ secret)
                  false (contains alert secret))
              [ "SECRETNAME"; "SECRETSLUG"; "SECRETBODY" ];
            (* Distinct copy per variant: no two variants share a message. *)
            Alcotest.(check bool)
              (label ^ ": distinct copy") false
              (List.mem alert !seen);
            seen := alert :: !seen;
            (* The form is still offered so the steward can correct. *)
            Alcotest.(check int) (label ^ ": form survives") 1
              (ps_count html "<form"))
          variants)
  ]

let phvp_suite =
  phvp_copy_cases @ phvp_form_cases @ phvp_defensive_cases
  @ phvp_feedback_cases

(* === Dedicated-home creation read model
   (Project_home_provisioning_read_model) ===
   Owner authorization decided in SQL, the active-home exclusion, durable
   revalidation, and the suggested initial identity. Reserved
   external-installation-id range 949000001..949000999 (hence account ids
   949100001..949100999, which also scope the permanent-project cleanup),
   phvr_% usernames, and phvr-% community slugs so no suite shares fixtures.
   Verified projects come only through the real draft/selection/finalization
   chain; relations come only through the real request/review/removal stores.
   Every per-case wrapper disconnects deterministically. *)
module Phvr = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rm = Earde.Project_home_provisioning_read_model
  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store
  module Rms = Earde.Project_home_removal_store
  module Fin = Earde.Project_finalization_store

  let error_str : Rm.error -> string = function
    | Rm.Invalid_user_id -> "Invalid_user_id"
    | Rm.Invalid_project_slug -> "Invalid_project_slug"
    | Rm.Inconsistent_data -> "Inconsistent_data"
    | Rm.Storage_error -> "Storage_error"

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let insert_community = Phcv.insert_community

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 949100001 AND 949100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 949100001 AND 949100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 949000001 AND 949000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phvr-%'"
      ; "DELETE FROM users WHERE username LIKE 'phvr_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 949000001 AND 949000999"
      ]

  (* Durable corruption the read model must refuse to build a suggestion
     from. Each value still satisfies every production CHECK — btrim() only
     trims spaces, and none exceeds a length limit — so nothing here weakens
     a constraint to manufacture the failure. *)
  let q_corrupt_name_control =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects SET name = 'Phvr' || chr(1) || 'Name' \
     WHERE id = $1"

  let q_corrupt_name_untrimmed =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects SET name = chr(9) || 'Phvr Name' WHERE id = $1"

  let q_corrupt_description =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET description = 'Phvr' || chr(1) || 'Body' WHERE id = $1"

  let q_corrupt_login =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects SET forge_namespace_login = 'phvr owner' \
     WHERE id = $1"

  let q_restore_project =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "UPDATE open_source_projects \
     SET name = 'Phvr Project', description = NULL, \
         forge_namespace_login = 'pfin-owner' \
     WHERE id = $1"

  let q_set_verification = Phrq.q_set_verification
  let q_delete_steward = Phrq.q_delete_steward
  let q_insert_steward = Phrq.q_insert_steward
  let q_insert_moderator = Phrv.q_insert_moderator

  (* Emptying search_path hides the unqualified tables, so the query fails at
     the SQL layer and Caqti returns an Error the read model maps to
     Storage_error — a genuine query failure, not a torn-down connection
     (which the driver signals by raising, not by Error). *)
  let q_break_search_path =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO ''"

  let q_reset_search_path =
    (Caqti_type.unit ->. Caqti_type.unit) "SET search_path TO public"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* === fixtures === *)

  (* Verified permanent projects come only through the real chain — draft
     store, selection store, finalization store — never fixture INSERTs.
     Returns the installation record id (for extra-steward fixtures) and the
     permanent project id. *)
  let make_project ?(name = "Phvr Project") ?description conn ~user ~ext_id
      ~slug =
    let repo_id = Int64.add ext_id 400000L in
    let* inst, draft, _, _ =
      Pfin.make_draft conn ~user ~ext_id (fun account_id ->
          [ Pfin.repo ~account_id ~id:repo_id "alpha" ])
    in
    let* ids = Pfin.snapshot_ids conn draft in
    let s1 = List.nth ids 0 in
    let* () =
      Pod_select.replace_ok "seed selection" conn ~user ~draft ~primary:s1
        [ s1 ]
    in
    let identity =
      Pfin.identity_exn ~name ~slug ?description ~selected:[ s1 ] ~primary:s1 ()
    in
    let* created =
      Pfin.finalize_ok "fixture project" conn ~user ~draft identity
    in
    Lwt.return (inst, Fin.project_id created)

  let add_steward conn ~project ~user ~installation =
    exec conn "extra steward" q_insert_steward (project, user, installation)

  let add_top_mod conn ~user ~community =
    exec conn "top_mod fixture" q_insert_moderator (user, community, "top_mod")

  let request_pending label conn ~user ~slug ~community =
    let relation = phr_expect_ok (Phr.create_pending ~request_note:None) in
    let* r =
      Rq.create conn ~user_id:user ~project_slug:slug
        ~target_community_id:community ~relation
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: request fixture failed" label

  let review label conn ~reviewer ~slug ~community_slug decision =
    let* r =
      Rvs.review conn ~reviewer_user_id:reviewer ~project_slug:slug
        ~target_community_slug:community_slug ~decision
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: review fixture failed" label

  let remove label conn ~actor ~slug ~community_slug =
    let* r =
      Rms.remove conn ~actor_user_id:actor ~project_slug:slug
        ~community_slug
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: removal fixture failed" label

  (* === call helpers === *)

  let load conn ~user ~slug =
    Rm.load_for_steward conn ~user_id:user ~project_slug:slug

  let load_view label conn ~user ~slug =
    let* r = load conn ~user ~slug in
    match r with
    | Ok (Some view) -> Lwt.return view
    | Ok None -> Alcotest.failf "%s: unexpectedly absent" label
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_none label conn ~user ~slug =
    let* r = load conn ~user ~slug in
    match r with
    | Ok None -> Lwt.return_unit
    | Ok (Some _) -> Alcotest.failf "%s: unexpectedly present" label
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let load_expect label expected conn ~user ~slug =
    let* r = load conn ~user ~slug in
    match r with
    | Ok None ->
        Alcotest.failf "%s: expected %s, got Ok None" label (error_str expected)
    | Ok (Some _) ->
        Alcotest.failf "%s: expected %s, got Ok Some" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "provisioning read: invalid inputs rejected before any SQL"
      (fun _conn ->
        (* A deliberately unusable connection: pure validation must return
           without touching it — were any SQL attempted, the driver would
           raise on the finished connection and fail the test. *)
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let expect label e ~user ~slug = load_expect label e dead ~user ~slug in
        let* () = expect "user 0" Rm.Invalid_user_id ~user:0 ~slug:"phvr-a" in
        let* () = expect "user -1" Rm.Invalid_user_id ~user:(-1) ~slug:"phvr-a" in
        Lwt_list.iter_s
          (fun slug ->
            expect ("slug " ^ String.escaped slug) Rm.Invalid_project_slug
              ~user:1 ~slug)
          [ ""; " phvr-a"; "phvr-a "; "Phvr-A"; "phvr_a"; "-phvr"; "phvr-";
            "phvr--a"; "phvr/a"; "phvr a"; "phvr\x00"; String.make 81 'a'
          ])

  (* === owner authorization === *)

  let authorization_case =
    db_case "provisioning read: only a current steward of a verified project \
             sees the view; every other identity is the same absence"
      (fun conn ->
        let* owner = insert_user conn "phvr_owner" in
        let* second = insert_user conn "phvr_second" in
        let* stranger = insert_user conn "phvr_stranger" in
        let* admin = insert_user conn "phvr_admin" in
        let* () = exec conn "admin flag" Phrv.q_set_admin (admin, true) in
        let* inst, project =
          make_project conn ~user:owner ~ext_id:949000001L ~slug:"phvr-auth"
        in
        let* view = load_view "owner" conn ~user:owner ~slug:"phvr-auth" in
        Alcotest.(check string) "project slug" "phvr-auth"
          (Rm.project_slug (Rm.project view));
        (* A second steward of the same project is equally authorized. *)
        let* () = add_steward conn ~project ~user:second ~installation:inst in
        let* _ = load_view "second steward" conn ~user:second ~slug:"phvr-auth" in
        (* Everyone else — including a durable global admin who is not a
           steward — collapses to the same absence, matching the sibling
           permanent-project setup and choice read models. *)
        let* () = load_none "stranger" conn ~user:stranger ~slug:"phvr-auth" in
        let* () = load_none "durable admin" conn ~user:admin ~slug:"phvr-auth" in
        let* () = load_none "missing project" conn ~user:owner ~slug:"phvr-gone" in
        (* Removed stewardship revokes access with no distinguishable
           answer. *)
        let* () = exec conn "remove steward" q_delete_steward (project, second) in
        load_none "removed steward" conn ~user:second ~slug:"phvr-auth")

  let verification_case =
    db_case "provisioning read: a stale or revoked project is the same absence"
      (fun conn ->
        let* owner = insert_user conn "phvr_vowner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:949000002L ~slug:"phvr-verif"
        in
        let* _ = load_view "verified" conn ~user:owner ~slug:"phvr-verif" in
        let* () = exec conn "stale" q_set_verification (project, "stale") in
        let* () = load_none "stale" conn ~user:owner ~slug:"phvr-verif" in
        let* () = exec conn "revoked" q_set_verification (project, "revoked") in
        let* () = load_none "revoked" conn ~user:owner ~slug:"phvr-verif" in
        let* () = exec conn "restore" q_set_verification (project, "verified") in
        let* _ = load_view "restored" conn ~user:owner ~slug:"phvr-verif" in
        Lwt.return_unit)

  (* === active-home exclusion === *)

  let active_home_case =
    db_case "provisioning read: a pending request or accepted home closes the \
             entry, and closed history reopens it" (fun conn ->
        let* owner = insert_user conn "phvr_aowner" in
        let* moderator = insert_user conn "phvr_amod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:949000003L ~slug:"phvr-active"
        in
        let* cid = insert_community ~name:"Phvr Home" conn "phvr-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* _ = load_view "no relation" conn ~user:owner ~slug:"phvr-active" in
        (* Pending closes it. *)
        let* () =
          request_pending "pending" conn ~user:owner ~slug:"phvr-active"
            ~community:cid
        in
        let* () = load_none "pending" conn ~user:owner ~slug:"phvr-active" in
        (* A rejected request is history, not an active relation. *)
        let* () =
          review "reject" conn ~reviewer:moderator ~slug:"phvr-active"
            ~community_slug:"phvr-home" Rvs.Reject
        in
        let* _ = load_view "after reject" conn ~user:owner ~slug:"phvr-active" in
        (* Accepted closes it again. *)
        let* () =
          request_pending "second" conn ~user:owner ~slug:"phvr-active"
            ~community:cid
        in
        let* () =
          review "accept" conn ~reviewer:moderator ~slug:"phvr-active"
            ~community_slug:"phvr-home" Rvs.Accept
        in
        let* () = load_none "accepted" conn ~user:owner ~slug:"phvr-active" in
        (* Removal frees the slot and the entry reopens. *)
        let* () =
          remove "remove" conn ~actor:owner ~slug:"phvr-active"
            ~community_slug:"phvr-home"
        in
        let* _ = load_view "after removal" conn ~user:owner ~slug:"phvr-active" in
        Lwt.return_unit)

  (* === suggested identity === *)

  let suggestion_case =
    db_case "provisioning read: the suggested identity is exactly the \
             project's own validated identity" (fun conn ->
        let* owner = insert_user conn "phvr_sowner" in
        let* _ =
          make_project conn ~user:owner ~ext_id:949000004L ~slug:"phvr-suggest"
            ~name:"Phvr Suggested Name" ~description:"Suggested body."
        in
        let* view = load_view "suggestions" conn ~user:owner ~slug:"phvr-suggest" in
        Alcotest.(check string) "name suggestion" "Phvr Suggested Name"
          (Rm.suggested_community_name view);
        Alcotest.(check string) "slug suggestion" "phvr-suggest"
          (Rm.suggested_community_slug view);
        Alcotest.(check (option string)) "description suggestion"
          (Some "Suggested body.")
          (Rm.suggested_community_description view);
        (* Accessors mirror the project itself — no second source of
           truth. *)
        let project = Rm.project view in
        Alcotest.(check string) "project name" "Phvr Suggested Name"
          (Rm.project_name project);
        Alcotest.(check string) "project slug" "phvr-suggest"
          (Rm.project_slug project);
        Alcotest.(check (option string)) "project description"
          (Some "Suggested body.")
          (Rm.project_description project);
        Alcotest.(check string) "namespace login" "pfin-owner"
          (Rm.project_namespace_login project);
        Alcotest.(check string) "kind"
          "project"
          (Pi.string_of_kind (Rm.project_kind project));
        (* Every accepted suggestion is accepted by the form unchanged: the
           GET can never prefill a value the POST would reject. *)
        (match
           Phvf.of_fields
             [ ("community_name", Rm.suggested_community_name view);
               ("community_slug", Rm.suggested_community_slug view);
               ("community_description",
                Option.value ~default:""
                  (Rm.suggested_community_description view))
             ]
         with
        | Ok parsed ->
            Alcotest.(check string) "round-trip name" "Phvr Suggested Name"
              (Phvf.community_name parsed);
            Alcotest.(check string) "round-trip slug" "phvr-suggest"
              (Phvf.community_slug parsed)
        | Error e ->
            Alcotest.failf "suggestion rejected by the form: %s" (phvf_err e));
        Lwt.return_unit)

  let suggestion_shapes_case =
    db_case "provisioning read: every canonical project slug is a usable \
             community-slug suggestion today" (fun conn ->
        let* owner = insert_user conn "phvr_shapes" in
        let long = "phvr-" ^ String.make 75 'a' in
        let* _ =
          make_project conn ~user:owner ~ext_id:949000005L ~slug:long
        in
        let* view = load_view "long slug" conn ~user:owner ~slug:long in
        Alcotest.(check string) "80-character slug suggested whole" long
          (Rm.suggested_community_slug view);
        Alcotest.(check int) "exactly 80 characters" 80 (String.length long);
        let* _ =
          make_project conn ~user:owner ~ext_id:949000006L ~slug:"phvr-a-b-c"
        in
        let* view = load_view "hyphens" conn ~user:owner ~slug:"phvr-a-b-c" in
        Alcotest.(check string) "hyphenated slug suggested whole" "phvr-a-b-c"
          (Rm.suggested_community_slug view);
        (* No description means no suggestion, never an empty string. *)
        Alcotest.(check (option string)) "absent description stays absent" None
          (Rm.suggested_community_description view);
        Lwt.return_unit)

  let no_availability_case =
    db_case "provisioning read: an already-taken slug is still suggested — \
             availability is the provisioning store's answer, not this GET's"
      (fun conn ->
        let* owner = insert_user conn "phvr_taken" in
        let* _ =
          make_project conn ~user:owner ~ext_id:949000007L ~slug:"phvr-taken"
        in
        (* A community already occupies exactly that slug. *)
        let* _cid = insert_community ~name:"Phvr Taken" conn "phvr-taken" in
        let* view = load_view "taken" conn ~user:owner ~slug:"phvr-taken" in
        Alcotest.(check string) "suggestion unchanged" "phvr-taken"
          (Rm.suggested_community_slug view);
        Lwt.return_unit)

  (* === durable revalidation === *)

  let corruption_case =
    db_case "provisioning read: durable project corruption is Inconsistent_data, \
             never a suggestion" (fun conn ->
        let* owner = insert_user conn "phvr_cowner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:949000008L ~slug:"phvr-corrupt"
        in
        let* _ = load_view "healthy" conn ~user:owner ~slug:"phvr-corrupt" in
        let probe label q =
          let* () = exec conn label q project in
          let* () =
            load_expect label Rm.Inconsistent_data conn ~user:owner
              ~slug:"phvr-corrupt"
          in
          exec conn ("restore after " ^ label) q_restore_project project
        in
        let* () = probe "control byte in name" q_corrupt_name_control in
        let* () = probe "untrimmed name" q_corrupt_name_untrimmed in
        let* () = probe "control byte in description" q_corrupt_description in
        let* () = probe "unaddressable namespace login" q_corrupt_login in
        (* Restored data loads again — the failure was the row, not the
           query. *)
        let* _ = load_view "restored" conn ~user:owner ~slug:"phvr-corrupt" in
        Lwt.return_unit)

  let storage_error_case =
    db_case "provisioning read: a storage failure surfaces as the payload-free \
             Storage_error" (fun conn ->
        let* () = exec conn "break search_path" q_break_search_path () in
        let* () =
          load_expect "broken schema" Rm.Storage_error conn ~user:1
            ~slug:"phvr-anything"
        in
        exec conn "reset search_path" q_reset_search_path ())

  let privacy_case =
    db_case "provisioning read: no internal or GitHub identifier crosses the \
             public surface" (fun conn ->
        let* owner = insert_user conn "phvr_privacy" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:949000009L ~slug:"phvr-privacy"
            ~description:"Privacy body."
        in
        let* view = load_view "privacy" conn ~user:owner ~slug:"phvr-privacy" in
        let p = Rm.project view in
        let surface =
          String.concat "|"
            [ Rm.project_name p; Rm.project_slug p;
              Option.value ~default:"" (Rm.project_description p);
              Rm.project_namespace_login p;
              Pi.string_of_kind (Rm.project_kind p);
              Rm.suggested_community_name view;
              Rm.suggested_community_slug view;
              Option.value ~default:"" (Rm.suggested_community_description view)
            ]
        in
        List.iter
          (fun (what, needle) ->
            Alcotest.(check bool) ("surface free of " ^ what) false
              (contains surface needle))
          [ ("permanent project id", Int64.to_string project);
            ("external installation id", "949000009");
            ("external account id", "949100009");
            ("owner user id", string_of_int owner)
          ];
        Lwt.return_unit)

  let suite =
    [ pure_inputs_case; authorization_case; verification_case;
      active_home_case; suggestion_case; suggestion_shapes_case;
      no_availability_case; corruption_case; storage_error_case; privacy_case ]
end

(* === Dedicated-home creation handler (Project_home_provisioning_handlers) ===
   GET /projects/:slug/community-home/new: the DB-free rollout and
   authentication gates (every rejection precedes any route read or SQL — no
   sql_pool is installed in that harness), and the database-gated
   authorization, suggested prefill, generic collapse, and header contract
   over verified permanent projects and real relation stores. Reserved
   external-installation-id range 949200001..949200999 (hence account ids
   949300001..949300999), phvh_% usernames, and phvh-% community slugs so no
   suite shares fixtures. *)
module Phvh = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Hd = Earde.Project_home_provisioning_handlers
  module Rvs = Earde.Project_home_review_store

  let case = go_case
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let insert_community = Phcv.insert_community
  let status_of = Gh_start_handler.status_of

  let route_pattern = "/projects/:slug/community-home/new"
  let target slug = Printf.sprintf "/projects/%s/community-home/new" slug

  let make ~mode = Hd.make_project_home_provisioning_page_handler ~mode

  (* === DB-free: rollout and authentication gates === *)

  (* Unrouted: the handler runs with no "slug" parameter, so a request that
     passes every gate lands on the generic 404 without touching SQL. *)
  let unrouted_run ?session ~mode () =
    Pch.gate_run ?session ~method_:`GET ~target:(target "phvh-any")
      (make ~mode)

  (* Routed but with no sql_pool installed: a request that passes every gate
     reaches Dream.sql and raises, which the harness reports as the DB
     boundary. That is the strong proof that the gates themselves ran no
     SQL. *)
  let routed_run ?session ~mode () =
    Pch.gate_run ?session ~method_:`GET ~target:(target "phvh-any")
      (Dream.router [ Dream.get route_pattern (fun req -> make ~mode req) ])

  let gate_cases =
    [ case "GET provisioning off: clean /bring redirect before any route read \
            or SQL" (fun () ->
          Pch.check_clean_redirect "off" "/bring"
            (Pch.gate_response "off"
               (unrouted_run ~session:Pch.admin_session ~mode:Ob.Off ()));
          Pch.check_clean_redirect "off routed" "/bring"
            (Pch.gate_response "off routed"
               (routed_run ~session:Pch.admin_session ~mode:Ob.Off ())))
    ; case "GET provisioning: anonymous and malformed sessions to /login"
        (fun () ->
          Pch.check_clean_redirect "anonymous" "/login"
            (Pch.gate_response "anonymous" (routed_run ~mode:Ob.Public ()));
          List.iter
            (fun raw ->
              Pch.check_clean_redirect ("user_id " ^ raw) "/login"
                (Pch.gate_response ("user_id " ^ raw)
                   (routed_run ~session:[ ("user_id", raw) ] ~mode:Ob.Public ())))
            [ "not-a-number"; ""; "0"; "-3"; " 42"; "42x" ];
          Pch.check_clean_redirect "is_admin only" "/login"
            (Pch.gate_response "is_admin only"
               (routed_run ~session:[ ("is_admin", "true") ] ~mode:Ob.Admins ())))
    ; case "GET provisioning admins mode: a non-admin is redirected before any \
            route read or SQL" (fun () ->
          Pch.check_clean_redirect "non-admin" "/bring"
            (Pch.gate_response "non-admin"
               (routed_run ~session:Pch.logged_in ~mode:Ob.Admins ())))
    ; case "GET provisioning: authorized modes pass the gates and reach the \
            database boundary, never before it" (fun () ->
          Pch.check_db_boundary "admin in admins mode"
            (routed_run ~session:Pch.admin_session ~mode:Ob.Admins ());
          Pch.check_db_boundary "user in public mode"
            (routed_run ~session:Pch.logged_in ~mode:Ob.Public ());
          Pch.check_db_boundary "admin in public mode"
            (routed_run ~session:Pch.admin_session ~mode:Ob.Public ()))
    ; case "GET provisioning: a missing route parameter is the generic 404, \
            with no SQL" (fun () ->
          let response =
            Pch.gate_response "no route"
              (unrouted_run ~session:Pch.logged_in ~mode:Ob.Public ())
          in
          Alcotest.(check int) "404" 404 (status_of response);
          Alcotest.(check (option string)) "no-store" (Some "no-store")
            (Dream.header response "Cache-Control"))
    ]

  (* === Database-gated integration === *)

  (* Distinctive credential-shaped fixtures. None may appear in any page,
     redirect, header, or cookie this feature produces. *)
  let credential_markers =
    [ ("access token", "gho_PHVH_ACCESS_TOKEN_SECRET");
      ("refresh token", "ghr_PHVH_REFRESH_TOKEN");
      ("client secret", "PHVH_CLIENT_SECRET_VALUE");
      ("external installation id", "949200001");
      ("external account id", "949300001")
    ]

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 949300001 AND 949300999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 949300001 AND 949300999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 949200001 AND 949200999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phvh-%'"
      ; "DELETE FROM users WHERE username LIKE 'phvh_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 949200001 AND 949200999"
      ]

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* One shared single-connection sql_pool for the whole suite: nothing ever
     closes a Dream.sql_pool, and this suite issues many requests across many
     identities, so a fresh pool per request would exhaust Postgres
     max_connections. The session identity is swapped per request through a
     ref instead; cases run sequentially. The real router path is bound to
     the real handler, alongside the sibling setup GET so the two project
     routes are proven to coexist. *)
  let shared_identity : (int * bool) option ref = ref None
  let shared_pipeline = ref None

  let build_pipeline ~url =
    Dream.sql_pool ~size:1 url @@ Dream.set_secret gck_secret
    @@ Dream.memory_sessions
    @@ (fun handler request ->
         match !shared_identity with
         | None -> handler request
         | Some (uid, is_admin) ->
             let* () =
               Dream.set_session_field request "user_id" (string_of_int uid)
             in
             let* () =
               if is_admin then Dream.set_session_field request "is_admin" "true"
               else Lwt.return_unit
             in
             handler request)
    @@ Dream.router
         [ Dream.get route_pattern (fun req -> make ~mode:Ob.Public req);
           Dream.get "/projects/:slug/setup" (fun req ->
               Earde.Project_creation_handlers.make_project_home_setup_handler
                 ~mode:Ob.Public req)
         ]

  let pipeline_for ~url =
    match !shared_pipeline with
    | Some pipeline -> pipeline
    | None ->
        let pipeline = build_pipeline ~url in
        shared_pipeline := Some pipeline;
        pipeline

  let as_user ?(admin_session = false) uid =
    shared_identity := Some (uid, admin_session)

  let do_get ?pipeline ~url ~target () =
    let pipeline =
      match pipeline with Some p -> p | None -> pipeline_for ~url
    in
    let* response = pipeline (Dream.request ~method_:`GET ~target "") in
    let* body = Dream.body response in
    Lwt.return (response, body)

  let check_page label response =
    Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": referrer policy")
      (Some Earde.Request_origin.referrer_policy)
      (Dream.header response "Referrer-Policy")

  let check_generic_404 label response body =
    Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "This page does not exist.")

  let check_generic_500 label response body =
    Alcotest.(check int) (label ^ ": 500") 500 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "Something went wrong on our side.");
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no detail " ^ needle) false
          (contains body needle))
      [ "open_source_projects"; "community_projects"; "Caqti"; "PostgreSQL";
        "SELECT"; "search_path"; "Inconsistent"; "phvh_void"
      ]

  let check_no_credentials label response body =
    let headers =
      String.concat "\n"
        (List.map (fun (k, v) -> k ^ ": " ^ v) (Dream.all_headers response))
    in
    List.iter
      (fun (what, needle) ->
        Alcotest.(check bool) (label ^ ": body free of " ^ what) false
          (contains body needle);
        Alcotest.(check bool) (label ^ ": headers free of " ^ what) false
          (contains headers needle))
      credential_markers

  (* === fixtures === *)

  let make_project = Phvr.make_project
  let add_steward = Phvr.add_steward
  let add_top_mod = Phvr.add_top_mod
  let request_pending = Phvr.request_pending
  let review = Phvr.review

  (* === cases === *)

  let steward_page_case =
    db_case "GET provisioning: a steward gets the page with the project's own \
             identity suggested" (fun ~url conn ->
        let* owner = insert_user conn "phvh_owner" in
        let* inst, _project =
          make_project conn ~user:owner ~ext_id:949200001L ~slug:"phvh-alpha"
            ~name:"Phvh Alpha" ~description:"Alpha body."
        in
        as_user owner;
        let* response, body = do_get ~url ~target:(target "phvh-alpha") () in
        check_page "steward" response;
        (* The page itself. *)
        Alcotest.(check bool) "heading" true
          (contains body "Create a community home");
        Alcotest.(check bool) "setup-draft copy" true
          (contains body "private setup draft");
        Alcotest.(check bool) "verification wording" true
          (contains body "Project connected through GitHub");
        Alcotest.(check bool) "noindex" true
          (contains body "content='noindex'");
        (* The one form, its exact action, and a live CSRF field. *)
        Alcotest.(check bool) "exact action" true
          (contains body "action='/projects/phvh-alpha/community-home'");
        Alcotest.(check bool) "framework CSRF field" true
          (contains body "name=\"dream.csrf\"");
        (* Suggestions prefilled from the project. *)
        Alcotest.(check bool) "name suggested" true
          (contains body "value='Phvh Alpha'");
        Alcotest.(check bool) "slug suggested" true
          (contains body "value='phvh-alpha'");
        Alcotest.(check bool) "description suggested" true
          (contains body ">Alpha body.</textarea>");
        (* No flash or query state, no officiality language. Script and
           style are checked over the feature fragment: the shared shell
           owns its own chrome. *)
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("no " ^ needle) false (contains body needle))
          [ "Official"; "GitHub-approved"; "GitHub-endorsed"; "?feedback=";
            "?error="
          ];
        let frag = ps_fragment body in
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("fragment free of " ^ needle) false
              (contains frag needle))
          [ "<script"; "style='"; "onclick"; "http-equiv" ];
        Alcotest.(check int) "exactly one form in the fragment" 1
          (ps_count frag "<form");
        check_no_credentials "steward page" response body;
        (* A second steward is served identically. *)
        let* second = insert_user conn "phvh_second" in
        let* () = add_steward conn ~project:_project ~user:second ~installation:inst in
        as_user second;
        let* response, body = do_get ~url ~target:(target "phvh-alpha") () in
        check_page "second steward" response;
        Alcotest.(check bool) "second steward sees the form" true
          (contains body "action='/projects/phvh-alpha/community-home'");
        Lwt.return_unit)

  let generic_404_case =
    db_case "GET provisioning: every unavailable project is the same generic \
             404" (fun ~url conn ->
        let* owner = insert_user conn "phvh_gowner" in
        let* stranger = insert_user conn "phvh_gstranger" in
        let* moderator = insert_user conn "phvh_gmod" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:949200010L ~slug:"phvh-gen"
        in
        let* cid = insert_community ~name:"Phvh Home" conn "phvh-home" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let bodies = ref [] in
        let expect_404 label ~user slug =
          as_user user;
          let* response, body = do_get ~url ~target:(target slug) () in
          check_generic_404 label response body;
          check_no_credentials label response body;
          bodies := body :: !bodies;
          Lwt.return_unit
        in
        let* () = expect_404 "missing project" ~user:owner "phvh-missing" in
        let* () = expect_404 "foreign project" ~user:stranger "phvh-gen" in
        let* () = expect_404 "malformed slug" ~user:owner "Phvh-Gen" in
        (* Stale and revoked. *)
        let* () = exec conn "stale" Phrq.q_set_verification (project, "stale") in
        let* () = expect_404 "stale project" ~user:owner "phvh-gen" in
        let* () = exec conn "revoked" Phrq.q_set_verification (project, "revoked") in
        let* () = expect_404 "revoked project" ~user:owner "phvh-gen" in
        let* () =
          exec conn "verified" Phrq.q_set_verification (project, "verified")
        in
        (* Pending, then accepted. *)
        let* () =
          request_pending "pending" conn ~user:owner ~slug:"phvh-gen"
            ~community:cid
        in
        let* () = expect_404 "pending request" ~user:owner "phvh-gen" in
        let* () =
          review "accept" conn ~reviewer:moderator ~slug:"phvh-gen"
            ~community_slug:"phvh-home" Rvs.Accept
        in
        let* () = expect_404 "accepted home" ~user:owner "phvh-gen" in
        (* Unstewarded: the steward row is gone but the project remains. *)
        let* () =
          exec conn "unsteward" Phrq.q_delete_steward (project, owner)
        in
        let* () = expect_404 "removed stewardship" ~user:owner "phvh-gen" in
        (* Byte-identical answers: no state is distinguishable. *)
        (match !bodies with
        | [] -> Alcotest.fail "no 404 bodies captured"
        | first :: rest ->
            List.iteri
              (fun i body ->
                Alcotest.(check bool)
                  (Printf.sprintf "404 body %d identical" i)
                  true (String.equal first body))
              rest);
        Lwt.return_unit)

  let inconsistent_case =
    db_case "GET provisioning: durable project corruption is one generic \
             non-cacheable 500" (fun ~url conn ->
        let* owner = insert_user conn "phvh_icowner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:949200020L ~slug:"phvh-ic"
        in
        let* () =
          exec conn "corrupt name" Phvr.q_corrupt_name_control project
        in
        as_user owner;
        let* response, body = do_get ~url ~target:(target "phvh-ic") () in
        check_generic_500 "corrupt project" response body;
        check_no_credentials "corrupt project" response body;
        Lwt.return_unit)

  let storage_case =
    db_case "GET provisioning: a real database failure is one generic \
             non-cacheable 500" (fun ~url _conn ->
        let poisoned =
          Uri.to_string
            (Uri.add_query_param' (Uri.of_string url)
               ("options", "-csearch_path=phvh_void"))
        in
        (* A dedicated single-connection pool for this one case: the shared
           pipeline must keep talking to the real schema. *)
        let saved = !shared_pipeline in
        shared_pipeline := None;
        let poison_pipe = build_pipeline ~url:poisoned in
        shared_pipeline := saved;
        as_user 42;
        let* response, body =
          do_get ~pipeline:poison_pipe ~url ~target:(target "phvh-anything") ()
        in
        check_generic_500 "poisoned schema" response body;
        Lwt.return_unit)

  let navigation_case =
    db_case "setup page: the two distinct navigation links point at the real \
             routes, and the create link leads to the real page"
      (fun ~url conn ->
        let* owner = insert_user conn "phvh_navowner" in
        let* _ =
          make_project conn ~user:owner ~ext_id:949200030L ~slug:"phvh-nav"
            ~name:"Phvh Nav"
        in
        as_user owner;
        let* response, body =
          do_get ~url ~target:"/projects/phvh-nav/setup" ()
        in
        Alcotest.(check int) "setup 200" 200 (status_of response);
        Alcotest.(check bool) "connect link" true
          (contains body "href='/projects/phvh-nav/request-home'");
        Alcotest.(check bool) "create link" true
          (contains body "href='/projects/phvh-nav/community-home/new'");
        Alcotest.(check bool) "distinct labels" true
          (contains body "Connect to an existing community"
          && contains body ">Create a community home</a>");
        Alcotest.(check bool) "no form in the setup fragment" false
          (contains (ps_fragment body) "<form");
        (* The advertised destination really serves the creation page. *)
        let* response, body =
          do_get ~url ~target:(target "phvh-nav") ()
        in
        check_page "followed create link" response;
        Alcotest.(check bool) "creation page" true
          (contains body "action='/projects/phvh-nav/community-home'");
        Lwt.return_unit)

  let db_suite =
    [ steward_page_case; generic_404_case; inconsistent_case; storage_case;
      navigation_case ]
end

(* === Network-community identity constraints (migration 20260726120000) ===
   The three scoped CHECK constraints on communities: canonical name, slug,
   and description whenever is_network_community is TRUE, with legacy rows
   exempt. Probes run autocommit against the real table with ncid% slugs;
   the down/up round-trip runs inside one rolled-back transaction using
   Ncid_relax's byte-identical statements, so the production constraints
   are never left missing even on assertion failure. *)
module Ncid_schema = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let or_fail = Pod_schema.or_fail
  let reject = Pod_schema.reject

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM communities WHERE slug LIKE 'ncid%'" ]

  let q_insert_network =
    (Caqti_type.(t3 string string (option string)) ->! Caqti_type.int)
    "INSERT INTO communities (slug, name, description, is_network_community) \
     VALUES ($1, $2, $3, TRUE) RETURNING id"

  let q_insert_legacy =
    (Caqti_type.(t3 string string (option string)) ->! Caqti_type.int)
    "INSERT INTO communities (slug, name, description, is_network_community) \
     VALUES ($1, $2, $3, FALSE) RETURNING id"

  let q_identity =
    (Caqti_type.int ->! Caqti_type.(t2 (t2 string string) (option string)))
    "SELECT slug, name, description FROM communities WHERE id = $1"

  (* Exactly the three identity constraints: the sibling scoped lifecycle
     CHECK (communities_network_lifecycle_check, migration 20260726130000)
     shares the prefix and has its own suite. *)
  let q_constraints =
    (Caqti_type.unit ->* Caqti_type.(t2 string bool))
    "SELECT conname, convalidated FROM pg_constraint \
     WHERE conrelid = 'communities'::regclass AND contype = 'c' \
       AND conname LIKE 'communities_network_%' \
       AND conname <> 'communities_network_lifecycle_check' \
     ORDER BY conname"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let accept label conn ?description ~slug ~name () =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* id = C.find q_insert_network (slug, name, description) in
    or_fail label id

  let refuse label conn ?description ~slug ~name () =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* r = C.find q_insert_network (slug, name, description) in
    reject label r

  let constraint_rows conn =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* rows = C.collect_list q_constraints () in
    or_fail "constraint rows" rows

  (* === canonical acceptance === *)

  let valid_case =
    db_case "identity: canonical network identities are accepted byte-exactly"
      (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let name = "Ncid Community \xc3\xa8" in
        let description = "Prima riga.\nSeconda con\ttab \xe2\x98\x95" in
        let* id =
          accept "canonical" conn ~slug:"ncid-valid" ~name
            ~description ()
        in
        let* stored = C.find q_identity id in
        let* (slug_back, name_back), description_back =
          or_fail "readback" stored
        in
        Alcotest.(check string) "slug byte-exact" "ncid-valid" slug_back;
        Alcotest.(check string) "name byte-exact" name name_back;
        Alcotest.(check (option string)) "description byte-exact"
          (Some description) description_back;
        (* NULL description is a first-class canonical value. *)
        let* _ = accept "no description" conn ~slug:"ncid-nodesc"
                   ~name:"Ncid Nodesc" () in
        Lwt.return_unit)

  (* === slug grammar === *)

  let slug_case =
    db_case "identity: the network slug grammar binds at the database"
      (fun conn ->
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              refuse ("slug " ^ String.escaped bad) conn ~slug:bad
                ~name:"Ncid Name" ())
            [ "ncid/slash"
            ; "Ncid-Upper"
            ; "ncid slug"
            ; "ncid_underscore"
            ; " ncid-pad"
            ; "-ncid"
            ; "ncid-"
            ; "ncid--a"
            ; "ncid-" ^ String.make 76 'a' (* 81 characters *)
            ]
        in
        (* The exact 80-character boundary is legal. *)
        let* _ =
          accept "80-character slug" conn
            ~slug:("ncid-" ^ String.make 75 'a')
            ~name:"Ncid Eighty" ()
        in
        Lwt.return_unit)

  (* === name policy === *)

  let name_case =
    db_case "identity: the network name policy binds at the database"
      (fun conn ->
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              refuse ("name " ^ String.escaped bad) conn
                ~slug:"ncid-name-probe" ~name:bad ())
            [ ""
            ; " padded"
            ; "padded "
            ; "\tpadded"
            ; "padded\t"
            ; "\npadded"
            ; "padded\x0b"
            ; "padded\x0c"
            ; "padded\r"
            ; "in\x01side"
            ; "in\x1fside"
            ; "in\x7fside"
            ; phvf_repeat phvf_scalar 121
            ]
        in
        (* 120 Unicode scalars — counted per character, not per byte. *)
        let* _ =
          accept "120-scalar name" conn ~slug:"ncid-name-120"
            ~name:(phvf_repeat phvf_scalar 120) ()
        in
        Lwt.return_unit)

  (* === description policy === *)

  let description_case =
    db_case "identity: the network description policy binds at the database"
      (fun conn ->
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              refuse ("description " ^ String.escaped bad) conn
                ~slug:"ncid-desc-probe" ~name:"Ncid Desc"
                ~description:bad ())
            [ "" (* empty canonical descriptions must be NULL, never '' *)
            ; " padded"
            ; "padded "
            ; "\npadded"
            ; "padded\n"
            ; "\tpadded"
            ; "padded\t"
            ; "with\rreturn"
            ; "with\x01control"
            ; "with\x0bcontrol"
            ; "with\x7fdel"
            ; phvf_repeat phvf_scalar 2001
            ]
        in
        (* LF and tab survive as content; 2,000 scalars is the boundary. *)
        let* _ =
          accept "multiline description" conn ~slug:"ncid-desc-multi"
            ~name:"Ncid Multi"
            ~description:"Line one.\nLine\ttwo." ()
        in
        let* _ =
          accept "2000-scalar description" conn ~slug:"ncid-desc-2000"
            ~name:"Ncid Bound"
            ~description:(phvf_repeat phvf_scalar 2000) ()
        in
        Lwt.return_unit)

  (* === legacy exemption === *)

  let legacy_case =
    db_case "identity: legacy rows stay accepted with noncanonical values"
      (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        (* Every value below violates the network policy — noncanonical
           slug, padded control-bearing name, empty-string description —
           and all of it stays legal while is_network_community is
           FALSE. *)
        let* id =
          C.find q_insert_legacy
            ("ncid LEGACY_slug//", "  padded \x01 name  ", Some "")
        in
        let* _ = or_fail "legacy row" id in
        Lwt.return_unit)

  (* === presence and validation === *)

  let presence_case =
    db_case "identity: all three constraints are present and validated"
      (fun conn ->
        let* rows = constraint_rows conn in
        Alcotest.(check (list (pair string bool)))
          "present and validated"
          [ ("communities_network_description_check", true)
          ; ("communities_network_name_check", true)
          ; ("communities_network_slug_check", true)
          ]
          rows;
        Lwt.return_unit)

  (* === down/up round-trip === *)

  let roundtrip_case =
    db_case "identity: the down/up statement pair round-trips"
      (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        (* The whole round-trip runs inside one transaction that is always
           rolled back, so the live constraints cannot be lost even if an
           assertion fails between the drop and the re-add. *)
        let* r = C.start () in
        let* () = or_fail "begin" r in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = Ncid_relax.drop conn in
              let* rows = constraint_rows conn in
              Alcotest.(check int) "down removes all three" 0
                (List.length rows);
              let* () = Ncid_relax.restore conn in
              let* rows = constraint_rows conn in
              Alcotest.(check (list (pair string bool)))
                "up restores all three, validated"
                [ ("communities_network_description_check", true)
                ; ("communities_network_name_check", true)
                ; ("communities_network_slug_check", true)
                ]
                rows;
              Lwt.return_unit)
            (fun () ->
              let* _ = C.rollback () in
              Lwt.return_unit)
        in
        let* rows = constraint_rows conn in
        Alcotest.(check int) "live constraints untouched" 3
          (List.length rows);
        Lwt.return_unit)

  let suite =
    [ valid_case; slug_case; name_case; description_case; legacy_case;
      presence_case; roundtrip_case ]
end

(* === Scoped network-community lifecycle constraint (migration
   20260726130000) ===
   The durable whole-state defense behind Network_communities.
   lifecycle_state_valid: the exact draft and two published network tuples
   are accepted, every other network combination (public/leaking draft,
   private published, both mixed publication-flag shapes) is rejected at
   the database, legacy rows stay exempt, the constraint is present and
   validated, and the down/up statement pair round-trips. Database-gated
   (EARDE_TEST_DATABASE_URL, same opt-in as Mod_scope); nclc-% community
   slugs so no suite shares fixtures. *)
module Nclc_schema = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let or_fail = Pod_schema.or_fail
  let reject = Pod_schema.reject

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM communities WHERE slug LIKE 'nclc%'" ]

  (* Full lifecycle control on one row; identity stays canonical so only
     the lifecycle constraint can decide the outcome. The network marker is
     a parameter so the same shapes prove the legacy exemption. *)
  let q_insert =
    (Caqti_type.(t2 (t3 string string bool) (t3 string string (t2 bool bool)))
     ->! Caqti_type.int)
    "INSERT INTO communities \
       (slug, name, is_network_community, onboarding_state, visibility, \
        indexable, discoverable) \
     VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING id"

  let q_constraint =
    (Caqti_type.unit ->* Caqti_type.(t2 string bool))
    "SELECT conname, convalidated FROM pg_constraint \
     WHERE conrelid = 'communities'::regclass AND contype = 'c' \
       AND conname = 'communities_network_lifecycle_check' ORDER BY conname"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let insert conn ?(network = true) ~onboarding ~visibility ~indexable
      ~discoverable slug =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    C.find q_insert
      ( (slug, "Nclc Community", network),
        (onboarding, visibility, (indexable, discoverable)) )

  let accept label conn ?network ~onboarding ~visibility ~indexable
      ~discoverable slug =
    let* id =
      insert conn ?network ~onboarding ~visibility ~indexable ~discoverable
        slug
    in
    let* id = or_fail label id in
    Alcotest.(check bool) (label ^ ": positive id") true (id > 0);
    Lwt.return_unit

  let refuse label conn ?network ~onboarding ~visibility ~indexable
      ~discoverable slug =
    let* r =
      insert conn ?network ~onboarding ~visibility ~indexable ~discoverable
        slug
    in
    reject label r

  let constraint_rows conn =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* rows = C.collect_list q_constraint () in
    or_fail "constraint rows" rows

  (* === the three durable network shapes === *)

  let accepted_case =
    db_case
      "lifecycle: exactly the draft, published Public, and published \
       Unlisted network tuples are accepted" (fun conn ->
        let* () =
          accept "private draft" conn ~onboarding:"draft"
            ~visibility:"private" ~indexable:false ~discoverable:false
            "nclc-draft"
        in
        let* () =
          accept "published Public" conn ~onboarding:"published"
            ~visibility:"public" ~indexable:true ~discoverable:true
            "nclc-public"
        in
        accept "published Unlisted" conn ~onboarding:"published"
          ~visibility:"public" ~indexable:false ~discoverable:false
          "nclc-unlisted")

  (* === every other network tuple === *)

  let rejected_case =
    db_case
      "lifecycle: leaking drafts, private published, and mixed publication \
       flags are rejected at the database" (fun conn ->
        Lwt_list.iter_s
          (fun (label, onboarding, visibility, indexable, discoverable) ->
            refuse label conn ~onboarding ~visibility ~indexable
              ~discoverable "nclc-reject")
          [ ("public draft", "draft", "public", false, false)
          ; ("indexable draft", "draft", "private", true, false)
          ; ("discoverable draft", "draft", "private", false, true)
          ; ("leaking public draft", "draft", "public", true, true)
          ; ("private published", "published", "private", false, false)
          ; ("private listed published", "published", "private", true, true)
          ; ("published indexable only", "published", "public", true, false)
          ; ("published discoverable only", "published", "public", false,
             true)
          ])

  (* === legacy exemption === *)

  let legacy_case =
    db_case
      "lifecycle: legacy rows stay accepted in every combination the \
       network constraint rejects" (fun conn ->
        Lwt_list.iter_s
          (fun (label, slug, onboarding, visibility, indexable, discoverable)
             ->
            accept label conn ~network:false ~onboarding ~visibility
              ~indexable ~discoverable slug)
          [ ("legacy public draft", "nclc-l1", "draft", "public", false,
             false)
          ; ("legacy private published", "nclc-l2", "published", "private",
             false, false)
          ; ("legacy mixed indexable", "nclc-l3", "published", "public",
             true, false)
          ; ("legacy mixed discoverable", "nclc-l4", "published", "public",
             false, true)
          ; ("legacy leaking draft", "nclc-l5", "draft", "private", true,
             true)
          ])

  (* === presence and validation === *)

  let presence_case =
    db_case "lifecycle: the constraint is present and validated"
      (fun conn ->
        let* rows = constraint_rows conn in
        Alcotest.(check (list (pair string bool)))
          "present and validated"
          [ ("communities_network_lifecycle_check", true) ]
          rows;
        Lwt.return_unit)

  (* === down/up round-trip === *)

  let roundtrip_case =
    db_case "lifecycle: the down/up statement pair round-trips"
      (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        (* The whole round-trip runs inside one transaction that is always
           rolled back, so the live constraint cannot be lost even if an
           assertion fails between the drop and the re-add. *)
        let* r = C.start () in
        let* () = or_fail "begin" r in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = Nclc_relax.drop conn in
              let* rows = constraint_rows conn in
              Alcotest.(check int) "down removes the constraint" 0
                (List.length rows);
              let* () = Nclc_relax.restore conn in
              let* rows = constraint_rows conn in
              Alcotest.(check (list (pair string bool)))
                "up restores the constraint, validated"
                [ ("communities_network_lifecycle_check", true) ]
                rows;
              Lwt.return_unit)
            (fun () ->
              let* _ = C.rollback () in
              Lwt.return_unit)
        in
        let* rows = constraint_rows conn in
        Alcotest.(check int) "live constraint untouched" 1
          (List.length rows);
        Lwt.return_unit)

  let suite =
    [ accepted_case; rejected_case; legacy_case; presence_case;
      roundtrip_case ]
end

(* === Dedicated-home provisioning store
   (Project_home_provisioning_store) ===
   The single atomic transaction behind "Create a community home": pure
   validation before SQL, project/steward locking and its collapse,
   active-home arbitration, the complete private draft (community,
   membership, top_mod, General section, general channel, accepted
   relation), slug and active-home index arbitration under real
   concurrency, staged rollback injection, and the privacy sweep.
   Reserved external-installation-id range 950000001..950000999 (hence
   account ids 950100001..950100999, which also scope the
   permanent-project cleanup), phvs_% usernames, and phvs-% community
   slugs so no suite shares fixtures. Verified projects come only through
   the real draft/selection/finalization chain; competing relations come
   only through the real request/review/removal stores; identities come
   only through the real provisioning form. Every per-case wrapper
   disconnects deterministically. *)
module Phvs = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Pv = Earde.Project_home_provisioning_store
  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store
  module Rms = Earde.Project_home_removal_store

  let error_str : Pv.error -> string = function
    | Pv.Invalid_user_id -> "Invalid_user_id"
    | Pv.Invalid_project_slug -> "Invalid_project_slug"
    | Pv.Project_unavailable -> "Project_unavailable"
    | Pv.Community_slug_unavailable -> "Community_slug_unavailable"
    | Pv.Active_home_exists -> "Active_home_exists"
    | Pv.Inconsistent_data -> "Inconsistent_data"
    | Pv.Storage_error -> "Storage_error"

  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let collect = Pod_read.collect
  let make_project = Phvr.make_project
  let insert_community = Phcv.insert_community
  let contains = Cprj_schema.contains
  let status_of = Gh_start_handler.status_of

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 950100001 AND 950100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 950100001 AND 950100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 950000001 AND 950000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phvs-%'"
      ; "DELETE FROM users WHERE username LIKE 'phvs_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 950000001 AND 950000999"
      ]

  (* === queries === *)

  let q_count_by_slug =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT COUNT(*) FROM communities WHERE slug = $1"

  (* Everything durable on the community row except the slug key, as one
     signature: identity bytes, the private-draft lifecycle, the network
     marker, both publication flags, and the structured-shell flag. *)
  let q_community_state =
    (Caqti_type.string ->? Caqti_type.(t2 int string))
    "SELECT id, name || '|' || COALESCE(description, '<null>') || '|' || \
            visibility || '|' || onboarding_state || '|' || \
            is_network_community::text || '|' || indexable::text || '|' || \
            discoverable::text || '|' || sections_enabled::text \
     FROM communities WHERE slug = $1"

  let q_member_present =
    (Caqti_type.(t2 int int) ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_members \
     WHERE community_id = $1 AND user_id = $2"

  let q_moderator_role =
    (Caqti_type.(t2 int int) ->? Caqti_type.string)
    "SELECT role FROM community_moderators \
     WHERE community_id = $1 AND user_id = $2"

  let q_section_sigs =
    (Caqti_type.int ->* Caqti_type.string)
    "SELECT slug || '|' || name || '|' || \
            COALESCE(description, '<null>') || '|' || position::text \
            || '|' || default_sort || '|' || \
            is_introduction_section::text || '|' || indexable::text \
     FROM community_sections WHERE community_id = $1 \
     ORDER BY position, slug"

  let q_channel_sigs =
    (Caqti_type.int ->* Caqti_type.string)
    "SELECT slug || '|' || name || '|' || COALESCE(topic, '<null>') \
            || '|' || position::text || '|' || is_archived::text \
            || '|' || indexable::text \
     FROM channels WHERE community_id = $1 ORDER BY position, slug"

  let q_relation_ids =
    (Caqti_type.int64 ->* Caqti_type.int64)
    "SELECT id FROM community_projects WHERE project_id = $1 ORDER BY id"

  let q_relation_times =
    (Caqti_type.int64 ->! Caqti_type.(t2 bool bool))
    "SELECT reviewed_at >= created_at, updated_at >= created_at \
     FROM community_projects WHERE id = $1"

  (* Test-only failure injection: one shared RAISE function plus one
     unconditional AFTER INSERT trigger per poisoned table, installed
     immediately before the single poisoned provision call and dropped
     under Lwt.finalize — within a case the store's own inserts are the
     only ones that can fire it. Production migrations are untouched. *)
  let ddl sql = (Caqti_type.unit ->. Caqti_type.unit) sql

  let q_create_fail_fn =
    ddl
      "CREATE FUNCTION phvs_fail_fn() RETURNS trigger \
       LANGUAGE plpgsql \
       AS 'BEGIN RAISE EXCEPTION ''phvs fixture failure''; END'"

  let q_drop_fail_fn = ddl "DROP FUNCTION IF EXISTS phvs_fail_fn()"

  let poison_tables =
    [ "communities"; "community_members"; "community_moderators";
      "community_sections"; "channels"; "community_projects" ]

  let q_poison table =
    ddl
      (Printf.sprintf
         "CREATE TRIGGER phvs_fail_insert AFTER INSERT ON %s \
          FOR EACH ROW EXECUTE FUNCTION phvs_fail_fn()"
         table)

  let q_unpoison table =
    ddl
      (Printf.sprintf "DROP TRIGGER IF EXISTS phvs_fail_insert ON %s" table)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let with_second ~url f =
    let* conn2 = Caqti_lwt_unix.connect (Uri.of_string url) in
    let* conn2 = or_fail "second connect" conn2 in
    let (module C2 : Caqti_lwt.CONNECTION) = conn2 in
    Lwt.finalize (fun () -> f conn2) (fun () -> C2.disconnect ())

  (* === fixtures and call helpers === *)

  (* Identities come only through the real form parser, exactly as the
     future POST handler will hand them to the store. *)
  let identity ?(name = "Phvs Community Home") ?(slug = "phvs-home")
      ?(description = "") () =
    phvf_ok "identity fixture" (phvf_fields ~name ~slug ~description ())

  let provision conn ~actor ~slug identity =
    Pv.provision conn ~actor_user_id:actor ~project_slug:slug ~identity

  (* Every success asserts both public accessors — the only observable
     surface of the abstract result. *)
  let provision_ok label conn ~actor ~slug ~expect_slug identity =
    let* r = provision conn ~actor ~slug identity in
    match r with
    | Ok home ->
        Alcotest.(check string)
          (label ^ ": community slug")
          expect_slug (Pv.community_slug home);
        Alcotest.(check string)
          (label ^ ": resulting status")
          (Phr.string_of_status Phr.Accepted)
          (Phr.string_of_status (Pv.resulting_status home));
        Lwt.return home
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let provision_expect label expected conn ~actor ~slug identity =
    let* r = provision conn ~actor ~slug identity in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  let community_state label conn slug =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* r = C.find_opt q_community_state slug in
    let* row = or_fail label r in
    match row with
    | Some state -> Lwt.return state
    | None -> Alcotest.failf "%s: community %s missing" label slug

  let check_no_state label conn ~project ~slug =
    let* n = find conn "loser community" q_count_by_slug slug in
    Alcotest.(check int) (label ^ ": no community") 0 n;
    let* relations =
      find conn "relations" Phrq.q_count_for_project project
    in
    Alcotest.(check int) (label ^ ": no relation") 0 relations;
    Lwt.return_unit

  (* The complete durable draft one successful provision must leave. *)
  let check_provisioned_draft label conn ~actor ~project ~slug ~name
      ~description =
    let* cid, state = community_state (label ^ ": community") conn slug in
    Alcotest.(check string)
      (label ^ ": community identity and lifecycle")
      (name ^ "|" ^ description ^ "|private|draft|true|false|false|true")
      state;
    let* members = find conn "members" Phrq.q_count_members cid in
    Alcotest.(check int) (label ^ ": exactly one member") 1 members;
    let* mine = find conn "actor member" q_member_present (cid, actor) in
    Alcotest.(check int) (label ^ ": the member is the actor") 1 mine;
    let* mods = find conn "moderators" Phrq.q_count_moderators cid in
    Alcotest.(check int) (label ^ ": exactly one moderator") 1 mods;
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* role = C.find_opt q_moderator_role (cid, actor) in
    let* role = or_fail (label ^ ": role") role in
    Alcotest.(check (option string))
      (label ^ ": the actor is top_mod")
      (Some "top_mod") role;
    let* sections = collect conn "sections" q_section_sigs cid in
    Alcotest.(check (list string))
      (label ^ ": exactly the default General section")
      [ "general|General|General discussion|0|new|false|true" ]
      sections;
    let* channels = collect conn "channels" q_channel_sigs cid in
    Alcotest.(check (list string))
      (label ^ ": exactly the default general channel")
      [ "general|general|General chat|0|false|true" ]
      channels;
    let* relation_ids = collect conn "relation ids" q_relation_ids project in
    match relation_ids with
    | [ rid ] ->
        let* ((rp, rc), (rtype, rstatus)), ((req, rev), (note, times)) =
          Phrq.relation_row conn rid
        in
        Alcotest.(check int64) (label ^ ": relation project") project rp;
        Alcotest.(check int) (label ^ ": relation community") cid rc;
        Alcotest.(check string) (label ^ ": relation type") "home" rtype;
        Alcotest.(check string) (label ^ ": accepted") "accepted" rstatus;
        Alcotest.(check (option int))
          (label ^ ": no fabricated requester")
          None req;
        Alcotest.(check (option int))
          (label ^ ": no fabricated reviewer")
          None rev;
        Alcotest.(check (option string)) (label ^ ": no note") None note;
        let reviewed_present, removed_present, updated_ok = times in
        Alcotest.(check bool) (label ^ ": reviewed_at present") true
          reviewed_present;
        Alcotest.(check bool) (label ^ ": removed_at absent") false
          removed_present;
        Alcotest.(check bool) (label ^ ": updated coherent") true updated_ok;
        let* reviewed_ok, updated_ok = find conn "times" q_relation_times rid
        in
        Alcotest.(check bool) (label ^ ": reviewed_at >= created_at") true
          reviewed_ok;
        Alcotest.(check bool) (label ^ ": updated_at >= created_at") true
          updated_ok;
        Lwt.return (cid, rid)
    | ids ->
        Alcotest.failf "%s: expected one relation, found %d" label
          (List.length ids)

  (* === pure input validation === *)

  let pure_inputs_case =
    db_case "provision: invalid inputs rejected before any SQL"
      (fun ~url:_ _conn ->
        (* A deliberately unusable connection: pure validation must return
           without touching it — were any SQL attempted, the result would
           be Storage_error (or a test-failing exception), never the
           expected input error. *)
        let url =
          match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
          | Some url -> url
          | None -> Alcotest.fail "EARDE_TEST_DATABASE_URL vanished mid-run"
        in
        let* dead = Caqti_lwt_unix.connect (Uri.of_string url) in
        let* dead = or_fail "dead connect" dead in
        let (module Dead : Caqti_lwt.CONNECTION) = dead in
        let* () = Dead.disconnect () in
        let value = identity () in
        let expect label e ~actor ~slug =
          provision_expect label e dead ~actor ~slug value
        in
        let* () = expect "user id 0" Pv.Invalid_user_id ~actor:0
                    ~slug:"phvs-a" in
        let* () =
          expect "negative user id" Pv.Invalid_user_id ~actor:(-7)
            ~slug:"phvs-a"
        in
        let* () =
          expect "user checked before slug" Pv.Invalid_user_id ~actor:0
            ~slug:"NOT A SLUG"
        in
        Lwt_list.iter_s
          (fun bad ->
            expect "invalid project slug" Pv.Invalid_project_slug ~actor:1
              ~slug:bad)
          [ ""
          ; "Phvs-Upper"
          ; "phvs slug"
          ; " phvs-a"
          ; "phvs-a "
          ; "phvs_a"
          ; "phvs/a"
          ; "-phvs"
          ; "phvs-"
          ; "phvs--a"
          ; String.make 81 'a'
          ])

  (* === successful provisioning === *)

  let success_case =
    db_case
      "provision: a verified steward atomically creates the complete \
       private draft" (fun ~url conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* unrelated = insert_user conn "phvs_other" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000001L
            ~slug:"phvs-alpha"
        in
        let* project_before =
          find conn "project sig" Phrq.q_project_sig project
        in
        let* stewards_before =
          find conn "stewards" Phrq.q_count_stewards_for_project project
        in
        let* repos_before =
          find conn "repos" Phrm.q_count_repositories project
        in
        let name = "Phvs Alpha Home \xc3\xa8" in
        let description = "Prima riga.\nSeconda con\ttab \xe2\x98\x95" in
        let value =
          identity ~name ~slug:"phvs-alpha-home" ~description ()
        in
        let* _ =
          provision_ok "provision" conn ~actor:owner ~slug:"phvs-alpha"
            ~expect_slug:"phvs-alpha-home" value
        in
        let* _ =
          check_provisioned_draft "draft" conn ~actor:owner ~project
            ~slug:"phvs-alpha-home" ~name ~description
        in
        (* The project side is untouched: identity, verification,
           stewardship, and repositories. *)
        let* project_after =
          find conn "project sig after" Phrq.q_project_sig project
        in
        Alcotest.(check string) "project unchanged" project_before
          project_after;
        let* stewards_after =
          find conn "stewards after" Phrq.q_count_stewards_for_project
            project
        in
        Alcotest.(check int) "stewardship unchanged" stewards_before
          stewards_after;
        let* repos_after =
          find conn "repos after" Phrm.q_count_repositories project
        in
        Alcotest.(check int) "repositories unchanged" repos_before
          repos_after;
        (* The real /c/:slug route: the existing private-community
           authorization admits the creating steward and nobody else —
           the anonymous visitor and the unrelated user get the same
           generic 404 a missing community gets. *)
        let* response, body =
          Ccph.visit ~session_user_id:owner ~url ~slug:"phvs-alpha-home" ()
        in
        Alcotest.(check int) "steward reads the draft" 200
          (status_of response);
        Alcotest.(check bool) "draft page carries the community name" true
          (contains ~needle:"Phvs Alpha Home" body);
        let* response, _ =
          Ccph.visit ~session_user_id:unrelated ~url
            ~slug:"phvs-alpha-home" ()
        in
        Alcotest.(check int) "unrelated user gets the generic 404" 404
          (status_of response);
        let* response, _ = Ccph.visit ~url ~slug:"phvs-alpha-home" () in
        Alcotest.(check int) "anonymous visitor gets the generic 404" 404
          (status_of response);
        Lwt.return_unit)

  (* === a second steward provisions === *)

  let second_steward_case =
    db_case
      "provision: a second steward provisions and becomes the sole \
       initial member and top moderator" (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* second = insert_user conn "phvs_second" in
        let* inst, project =
          make_project conn ~user:owner ~ext_id:950000002L
            ~slug:"phvs-second"
        in
        let* () =
          exec conn "second steward" Phrq.q_insert_steward
            (project, second, inst)
        in
        let* _ =
          provision_ok "second steward provisions" conn ~actor:second
            ~slug:"phvs-second" ~expect_slug:"phvs-second-home"
            (identity ~name:"Phvs Second Home" ~slug:"phvs-second-home" ())
        in
        let* cid, _ =
          check_provisioned_draft "second steward draft" conn ~actor:second
            ~project ~slug:"phvs-second-home" ~name:"Phvs Second Home"
            ~description:"<null>"
        in
        (* The first steward gains nothing automatically. *)
        let* owner_member = find conn "owner member" q_member_present
                              (cid, owner) in
        Alcotest.(check int) "owner not a member" 0 owner_member;
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* owner_role = C.find_opt q_moderator_role (cid, owner) in
        let* owner_role = or_fail "owner role" owner_role in
        Alcotest.(check (option string)) "owner not a moderator" None
          owner_role;
        Lwt.return_unit)

  (* === authorization collapse === *)

  let admin_case =
    db_case
      "provision: a durable global admin without stewardship is \
       indistinguishable from a missing project" (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* admin = insert_user conn "phvs_admin" in
        let* () = exec conn "make admin" Ccph.q_set_admin (admin, true) in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000003L
            ~slug:"phvs-admin"
        in
        let* () =
          provision_expect "durable admin" Pv.Project_unavailable conn
            ~actor:admin ~slug:"phvs-admin"
            (identity ~slug:"phvs-admin-home" ())
        in
        check_no_state "durable admin" conn ~project
          ~slug:"phvs-admin-home")

  let unavailable_case =
    db_case
      "provision: missing, foreign, stale, revoked, and unstewarded \
       projects collapse into one error with no partial state"
      (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* other = insert_user conn "phvs_other" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000004L
            ~slug:"phvs-unavail"
        in
        let value = identity ~slug:"phvs-unavail-home" () in
        let expect label ~actor ~slug =
          provision_expect label Pv.Project_unavailable conn ~actor ~slug
            value
        in
        let* () = expect "missing project" ~actor:owner
                    ~slug:"phvs-nowhere" in
        let* () = expect "foreign project" ~actor:other
                    ~slug:"phvs-unavail" in
        let* () =
          exec conn "mark stale" Phrq.q_set_verification (project, "stale")
        in
        let* () = expect "stale project" ~actor:owner ~slug:"phvs-unavail" in
        let* () =
          exec conn "mark revoked" Phrq.q_set_verification
            (project, "revoked")
        in
        let* () = expect "revoked project" ~actor:owner
                    ~slug:"phvs-unavail" in
        let* () =
          exec conn "restore verified" Phrq.q_set_verification
            (project, "verified")
        in
        (* The creator without a steward row does not authorize through
           created_by_user_id. *)
        let* () =
          exec conn "remove stewardship" Phrq.q_delete_steward
            (project, owner)
        in
        let* () = expect "creator without stewardship" ~actor:owner
                    ~slug:"phvs-unavail" in
        check_no_state "unavailable variants" conn ~project
          ~slug:"phvs-unavail-home")

  (* === requested slug conflicts === *)

  let slug_conflict_case =
    db_case
      "provision: an existing community slug loses cleanly, whether \
       legacy or network" (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000005L
            ~slug:"phvs-conflict"
        in
        let probe label cid slug =
          let* sig_before = find conn "community sig" Phrq.q_community_sig
                              cid in
          let* () =
            provision_expect label Pv.Community_slug_unavailable conn
              ~actor:owner ~slug:"phvs-conflict" (identity ~slug ())
          in
          let* sig_after = find conn "community sig after"
                             Phrq.q_community_sig cid in
          Alcotest.(check string) (label ^ ": existing row unchanged")
            sig_before sig_after;
          let* members = find conn "members" Phrq.q_count_members cid in
          Alcotest.(check int) (label ^ ": no membership leak") 0 members;
          let* mods = find conn "moderators" Phrq.q_count_moderators cid in
          Alcotest.(check int) (label ^ ": no moderator leak") 0 mods;
          let* n = find conn "count" q_count_by_slug slug in
          Alcotest.(check int) (label ^ ": exactly one row keeps the slug")
            1 n;
          let* relations =
            find conn "relations" Phrq.q_count_for_project project
          in
          Alcotest.(check int) (label ^ ": no relation") 0 relations;
          Lwt.return_unit
        in
        let* legacy =
          insert_community ~network:false conn "phvs-taken-legacy"
        in
        let* () = probe "legacy holder" legacy "phvs-taken-legacy" in
        let* network = insert_community conn "phvs-taken-net" in
        probe "network holder" network "phvs-taken-net")

  (* === active relations === *)

  let active_relation_case =
    db_case
      "provision: pending and accepted homes block, closed history and \
       completed removal do not" (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* reviewer = insert_user conn "phvs_mod" in
        let* _, _project =
          make_project conn ~user:owner ~ext_id:950000006L
            ~slug:"phvs-active"
        in
        let* target = insert_community conn "phvs-active-target" in
        let* () =
          exec conn "target top mod" Phrv.q_insert_moderator
            (reviewer, target, "top_mod")
        in
        let value = identity ~slug:"phvs-active-home" () in
        (* Pending blocks, and the loser leaves no draft community. *)
        let relation = phr_expect_ok (Phr.create_pending ~request_note:None)
        in
        let* r =
          Rq.create conn ~user_id:owner ~project_slug:"phvs-active"
            ~target_community_id:target ~relation
        in
        let* _ = match r with
          | Ok created -> Lwt.return created
          | Error _ -> Alcotest.fail "pending fixture failed"
        in
        let* () =
          provision_expect "pending blocks" Pv.Active_home_exists conn
            ~actor:owner ~slug:"phvs-active" value
        in
        let* n = find conn "no draft" q_count_by_slug "phvs-active-home" in
        Alcotest.(check int) "pending loser leaves no community" 0 n;
        (* Accepted blocks. *)
        let* r =
          Rvs.review conn ~reviewer_user_id:reviewer
            ~project_slug:"phvs-active"
            ~target_community_slug:"phvs-active-target" ~decision:Rvs.Accept
        in
        let* () = match r with
          | Ok _ -> Lwt.return_unit
          | Error _ -> Alcotest.fail "accept fixture failed"
        in
        let* () =
          provision_expect "accepted blocks" Pv.Active_home_exists conn
            ~actor:owner ~slug:"phvs-active" value
        in
        (* A completed removal frees the slot for a fresh draft. *)
        let* r =
          Rms.remove conn ~actor_user_id:owner ~project_slug:"phvs-active"
            ~community_slug:"phvs-active-target"
        in
        let* () = match r with
          | Ok _ -> Lwt.return_unit
          | Error _ -> Alcotest.fail "removal fixture failed"
        in
        let* _ =
          provision_ok "provision after removal" conn ~actor:owner
            ~slug:"phvs-active" ~expect_slug:"phvs-active-home" value
        in
        (* Rejected history never blocks either. *)
        let* _, project2 =
          make_project conn ~user:owner ~ext_id:950000007L
            ~slug:"phvs-hist"
        in
        let relation = phr_expect_ok (Phr.create_pending ~request_note:None)
        in
        let* r =
          Rq.create conn ~user_id:owner ~project_slug:"phvs-hist"
            ~target_community_id:target ~relation
        in
        let* _ = match r with
          | Ok created -> Lwt.return created
          | Error _ -> Alcotest.fail "second pending fixture failed"
        in
        let* r =
          Rvs.review conn ~reviewer_user_id:reviewer
            ~project_slug:"phvs-hist"
            ~target_community_slug:"phvs-active-target" ~decision:Rvs.Reject
        in
        let* () = match r with
          | Ok _ -> Lwt.return_unit
          | Error _ -> Alcotest.fail "reject fixture failed"
        in
        let* _ =
          provision_ok "provision over rejected history" conn ~actor:owner
            ~slug:"phvs-hist" ~expect_slug:"phvs-hist-home"
            (identity ~slug:"phvs-hist-home" ())
        in
        let* active =
          find conn "active" Phrq.q_count_active_for_project project2
        in
        Alcotest.(check int) "exactly one active relation" 1 active;
        Lwt.return_unit)

  (* === staged rollback injection === *)

  let rollback_case =
    db_case
      "provision: a failure at any stage rolls the whole draft back"
      (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000008L
            ~slug:"phvs-poison"
        in
        let* project_before =
          find conn "project sig" Phrq.q_project_sig project
        in
        let exec_ddl label q =
          let (module C : Caqti_lwt.CONNECTION) = conn in
          let* r = C.exec q () in
          let* _ = or_fail label r in
          Lwt.return_unit
        in
        let* () = exec_ddl "create fail fn" q_create_fail_fn in
        Lwt.finalize
          (fun () ->
            let* () =
              Lwt_list.iter_s
                (fun table ->
                  let* () = exec_ddl ("poison " ^ table) (q_poison table) in
                  Lwt.finalize
                    (fun () ->
                      let* () =
                        provision_expect ("poisoned " ^ table)
                          Pv.Storage_error conn ~actor:owner
                          ~slug:"phvs-poison"
                          (identity ~slug:"phvs-poison-home" ())
                      in
                      let* () =
                        check_no_state ("poisoned " ^ table) conn ~project
                          ~slug:"phvs-poison-home"
                      in
                      let* stewards =
                        find conn "stewards"
                          Phrq.q_count_stewards_for_project project
                      in
                      Alcotest.(check int)
                        ("poisoned " ^ table ^ ": stewardship intact")
                        1 stewards;
                      let* project_after =
                        find conn "project sig" Phrq.q_project_sig project
                      in
                      Alcotest.(check string)
                        ("poisoned " ^ table ^ ": project unchanged")
                        project_before project_after;
                      Lwt.return_unit)
                    (fun () ->
                      exec_ddl ("unpoison " ^ table) (q_unpoison table)))
                poison_tables
            in
            (* With every poison removed the same inputs succeed — the
               failures above were the triggers, not the store. *)
            let* _ =
              provision_ok "clean run after poison" conn ~actor:owner
                ~slug:"phvs-poison" ~expect_slug:"phvs-poison-home"
                (identity ~slug:"phvs-poison-home" ())
            in
            Lwt.return_unit)
          (fun () ->
            let* () =
              Lwt_list.iter_s
                (fun table -> exec_ddl ("drop trigger " ^ table)
                                (q_unpoison table))
                poison_tables
            in
            exec_ddl "drop fail fn" q_drop_fail_fn))

  (* === concurrency === *)

  let one_winner label expected_loser (ra, rb) =
    match (ra, rb) with
    | Ok w, Error e | Error e, Ok w ->
        Alcotest.(check string)
          (label ^ ": loser error")
          (error_str expected_loser) (error_str e);
        w
    | Ok _, Ok _ -> Alcotest.failf "%s: both succeeded" label
    | Error a, Error b ->
        Alcotest.failf "%s: both failed (%s, %s)" label (error_str a)
          (error_str b)

  let same_project_race_case =
    db_case
      "provision: two provisions of one project leave exactly one draft"
      (fun ~url conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000009L
            ~slug:"phvs-race1"
        in
        with_second ~url (fun conn2 ->
            let* results =
              Lwt.both
                (provision conn ~actor:owner ~slug:"phvs-race1"
                   (identity ~slug:"phvs-race1-a" ()))
                (provision conn2 ~actor:owner ~slug:"phvs-race1"
                   (identity ~slug:"phvs-race1-b" ()))
            in
            let winner =
              one_winner "same project" Pv.Active_home_exists results
            in
            let winner_slug = Pv.community_slug winner in
            let loser_slug =
              if String.equal winner_slug "phvs-race1-a" then "phvs-race1-b"
              else "phvs-race1-a"
            in
            let* n = find conn "loser slug" q_count_by_slug loser_slug in
            Alcotest.(check int) "no orphan loser community" 0 n;
            let* _ =
              check_provisioned_draft "winner draft" conn ~actor:owner
                ~project ~slug:winner_slug ~name:"Phvs Community Home"
                ~description:"<null>"
            in
            let* active =
              find conn "active" Phrq.q_count_active_for_project project
            in
            Alcotest.(check int) "one active relation" 1 active;
            Lwt.return_unit))

  let same_slug_race_case =
    db_case
      "provision: two projects racing for one slug leave one clean winner"
      (fun ~url conn ->
        let* owner_a = insert_user conn "phvs_owner" in
        let* owner_b = insert_user conn "phvs_second" in
        let* _, project_a =
          make_project conn ~user:owner_a ~ext_id:950000010L
            ~slug:"phvs-race2a"
        in
        let* _, project_b =
          make_project conn ~user:owner_b ~ext_id:950000011L
            ~slug:"phvs-race2b"
        in
        with_second ~url (fun conn2 ->
            let value = identity ~slug:"phvs-shared-home" () in
            let* ra, rb =
              Lwt.both
                (provision conn ~actor:owner_a ~slug:"phvs-race2a" value)
                (provision conn2 ~actor:owner_b ~slug:"phvs-race2b" value)
            in
            let _ =
              one_winner "same slug" Pv.Community_slug_unavailable (ra, rb)
            in
            let winner_actor, winner_project, loser_project =
              match ra with
              | Ok _ -> (owner_a, project_a, project_b)
              | Error _ -> (owner_b, project_b, project_a)
            in
            let* n = find conn "one community" q_count_by_slug
                       "phvs-shared-home" in
            Alcotest.(check int) "exactly one community with the slug" 1 n;
            let* _ =
              check_provisioned_draft "winner draft" conn
                ~actor:winner_actor ~project:winner_project
                ~slug:"phvs-shared-home" ~name:"Phvs Community Home"
                ~description:"<null>"
            in
            let* loser_relations =
              find conn "loser relations" Phrq.q_count_for_project
                loser_project
            in
            Alcotest.(check int) "loser project has no relation" 0
              loser_relations;
            Lwt.return_unit))

  let versus_request_case =
    db_case
      "provision: racing an existing-community request leaves one active \
       relation" (fun ~url conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000012L
            ~slug:"phvs-race3"
        in
        let* target = insert_community conn "phvs-race3-target" in
        with_second ~url (fun conn2 ->
            let relation =
              phr_expect_ok (Phr.create_pending ~request_note:None)
            in
            let* prov, req =
              Lwt.both
                (provision conn ~actor:owner ~slug:"phvs-race3"
                   (identity ~slug:"phvs-race3-home" ()))
                (Rq.create conn2 ~user_id:owner ~project_slug:"phvs-race3"
                   ~target_community_id:target ~relation)
            in
            let* () =
              match (prov, req) with
              | Ok home, Error Rq.Active_home_exists ->
                  Alcotest.(check string) "provisioned home"
                    "phvs-race3-home" (Pv.community_slug home);
                  let* _ =
                    check_provisioned_draft "provisioning won" conn
                      ~actor:owner ~project ~slug:"phvs-race3-home"
                      ~name:"Phvs Community Home" ~description:"<null>"
                  in
                  Lwt.return_unit
              | Error Pv.Active_home_exists, Ok _ ->
                  (* The request won: a pending relation on the target and
                     no draft community anywhere. *)
                  let* n = find conn "no draft" q_count_by_slug
                             "phvs-race3-home" in
                  Alcotest.(check int) "no draft community survives" 0 n;
                  Lwt.return_unit
              | Ok _, Ok _ -> Alcotest.fail "race: both succeeded"
              | Error a, Error _ ->
                  Alcotest.failf "race: both failed (provision %s)"
                    (error_str a)
              | Ok _, Error _ ->
                  Alcotest.fail "race: unexpected request loser error"
              | Error e, _ ->
                  Alcotest.failf "race: unexpected provision error %s"
                    (error_str e)
            in
            let* active =
              find conn "active" Phrq.q_count_active_for_project project
            in
            Alcotest.(check int) "exactly one active relation" 1 active;
            Lwt.return_unit))

  let verification_loss_race_case =
    db_case
      "provision: a verification loss that commits first wins the project \
       lock race" (fun ~url conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000013L
            ~slug:"phvs-race4"
        in
        with_second ~url (fun conn2 ->
            let* r =
              Phrv.serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "stale first" Phrq.q_set_verification
                    (project, "stale"))
                ~launch:(fun () ->
                  provision conn ~actor:owner ~slug:"phvs-race4"
                    (identity ~slug:"phvs-race4-home" ()))
            in
            let* () =
              match r with
              | Error Pv.Project_unavailable -> Lwt.return_unit
              | Ok _ -> Alcotest.fail "provisioned after verification loss"
              | Error e ->
                  Alcotest.failf "unexpected error %s" (error_str e)
            in
            check_no_state "verification loss" conn ~project
              ~slug:"phvs-race4-home"))

  let steward_loss_race_case =
    db_case
      "provision: a stewardship revocation that commits first wins the \
       lock race" (fun ~url conn ->
        let* owner = insert_user conn "phvs_owner" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000014L
            ~slug:"phvs-race5"
        in
        with_second ~url (fun conn2 ->
            let* r =
              Phrv.serialized_mutation_first conn2
                ~mutate:(fun () ->
                  exec conn2 "revoke stewardship" Phrq.q_delete_steward
                    (project, owner))
                ~launch:(fun () ->
                  provision conn ~actor:owner ~slug:"phvs-race5"
                    (identity ~slug:"phvs-race5-home" ()))
            in
            let* () =
              match r with
              | Error Pv.Project_unavailable -> Lwt.return_unit
              | Ok _ -> Alcotest.fail "provisioned with revoked authority"
              | Error e ->
                  Alcotest.failf "unexpected error %s" (error_str e)
            in
            check_no_state "stewardship loss" conn ~project
              ~slug:"phvs-race5-home"))

  (* === privacy sweep === *)

  (* Durable corruption defenses that cannot be produced without relaxing
     production constraints stay defensive and undriven here:
     project_stewards.role is CHECK-bound to 'steward',
     open_source_projects.slug and verification_status are CHECK-bound,
     community_projects.status and relation_type are CHECK-bound, and a
     second active home is barred by the partial unique index. The
     reachable corruption shapes on the sibling read paths are already
     exercised by their own suites. *)

  let privacy_case =
    db_case
      "provision: no credential-shaped or external-identifier fixture \
       reaches the draft" (fun ~url:_ conn ->
        let* owner = insert_user conn "phvs_priv" in
        let* _, project =
          make_project conn ~user:owner ~ext_id:950000015L
            ~slug:"phvs-priv"
        in
        let name = "Phvs Private Home" in
        let* _ =
          provision_ok "provision" conn ~actor:owner ~slug:"phvs-priv"
            ~expect_slug:"phvs-priv-home" (identity ~name
                                             ~slug:"phvs-priv-home" ())
        in
        let* cid, state =
          community_state "community" conn "phvs-priv-home"
        in
        let* sections = collect conn "sections" q_section_sigs cid in
        let* channels = collect conn "channels" q_channel_sigs cid in
        let* relation_ids = collect conn "relations" q_relation_ids project
        in
        let* relation_blob =
          match relation_ids with
          | [ rid ] -> find conn "blob" Phrq.q_relation_text_blob rid
          | _ -> Alcotest.fail "expected one relation"
        in
        let blob =
          String.concat "|"
            ((state :: relation_blob :: sections) @ channels)
        in
        (* The intentionally supplied safe identity is present; nothing
           else from the steward's GitHub records or account is. *)
        Alcotest.(check bool) "supplied name present" true
          (contains ~needle:name blob);
        List.iter
          (fun (what, marker) ->
            Alcotest.(check bool) ("draft carries no " ^ what) false
              (contains ~needle:marker blob))
          [ ("external installation id", "950000015");
            ("external account id", "950100015");
            ("external repository id", "950400015");
            ("account email", "@test.invalid");
            ("installation login", "pfin-owner")
          ];
        Lwt.return_unit)

  let suite =
    [ pure_inputs_case; success_case; second_steward_case; admin_case;
      unavailable_case; slug_conflict_case; active_relation_case;
      rollback_case; same_project_race_case; same_slug_race_case;
      versus_request_case; verification_loss_race_case;
      steward_loss_race_case; privacy_case ]
end

(* === Dedicated-home provisioning POST integration
   (Project_home_provisioning_handlers) ===
   POST /projects/:slug/community-home end to end: the exact route shape and
   its coexistence with the sibling GET, the shared rollout/authentication
   gates (every rejection precedes any route read, configuration load, origin
   inspection, form parse, or SQL), the configuration/origin/CSRF sequence,
   the four parser rejections with their safe value preservation, and the
   database-gated provisioning flow — the PRG into the new private settings
   draft, slug conflict, active-home and replay behaviour, authorization
   drift, durable failure, real concurrency, destination authorization, the
   mutation rate limit, and the privacy sweep. Reserved
   external-installation-id range 951000001..951000999 (hence account ids
   951100001..951100999, which also scope the permanent-project cleanup),
   phvv_% usernames, and phvv-% community slugs so no suite shares fixtures.
   Verified projects come only through the real draft/selection/finalization
   chain; competing relations come only through the real request/review
   stores. Every per-case wrapper disconnects deterministically. *)
module Phvv = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Hd = Earde.Project_home_provisioning_handlers
  module Pgs = Earde.Project_home_provisioning_pages
  module Rvs = Earde.Project_home_review_store

  let case = go_case
  let counting_loader = Gh_start_handler.counting_loader
  let ok_loader = Gh_start_handler.ok_loader
  let status_of = Gh_start_handler.status_of
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let insert_community = Phcv.insert_community
  let make_project = Phvr.make_project
  let add_steward = Phvr.add_steward
  let add_top_mod = Phvr.add_top_mod
  let request_pending = Phvr.request_pending
  let review = Phvr.review

  (* The one POST pattern this slice registers, and the GET it completes. *)
  let get_pattern = "/projects/:slug/community-home/new"
  let post_pattern = "/projects/:slug/community-home"
  let get_target slug = Printf.sprintf "/projects/%s/community-home/new" slug
  let post_target slug = Printf.sprintf "/projects/%s/community-home" slug
  let request_home_target slug = Printf.sprintf "/projects/%s/request-home" slug
  let settings_target slug = Printf.sprintf "/c/%s/settings" slug
  let community_target slug = Printf.sprintf "/c/%s" slug

  let make_get ~mode = Hd.make_project_home_provisioning_page_handler ~mode

  let make ~mode ~load_config =
    Hd.make_project_home_provisioning_handler ~mode ~load_config

  (* Exactly the three application fields, in the page's own order. *)
  let fields ?(name = "Phvv Community Home") ?(slug = "phvv-home")
      ?(description = "") () =
    [ ("community_name", name);
      ("community_slug", slug);
      ("community_description", description)
    ]

  (* ============ DB-free: the route shape ============ *)

  (* The real router with both patterns and nothing else: the POST target is
     dispatched exactly once, and no alias, sub-path, or method variant
     exists. Mode Off makes each dispatch observable as the clean /bring
     redirect, with no configuration read and no SQL. *)
  let two_route_router () =
    Dream.router
      [ Dream.get get_pattern (fun req -> make_get ~mode:Ob.Off req);
        Dream.post post_pattern (fun req ->
            make ~mode:Ob.Off ~load_config:(fun () -> ok_loader ()) req)
      ]

  let route_run ~method_ ~target =
    Pch.gate_response "route"
      (Pch.gate_run ~method_ ~target (two_route_router ()))

  let route_cases =
    [ case "provisioning route: the registered POST pattern is exactly the \
            action the creation page emits" (fun () ->
          let html =
            Pgs.project_home_provisioning_page
              ~project:
                { Pgs.name = "Phvv Project";
                  slug = "phvv-alpha";
                  description = None;
                  kind = Pi.Project;
                  namespace_login = "phvv-owner"
                }
              ~values:
                { Pgs.community_name = "";
                  community_slug = "";
                  community_description = ""
                }
              ~feedback:None ()
          in
          Alcotest.(check bool) "the page posts to the registered route" true
            (contains html
               (Printf.sprintf "action='%s'" (post_target "phvv-alpha")));
          (* Scoped to the feature fragment: the shared shell owns its own
             chrome forms. *)
          Alcotest.(check int) "exactly one form" 1
            (ps_count (ps_fragment html) "<form"))
    ; case "provisioning route: the POST target resolves once, with no alias \
            and no extra GET" (fun () ->
          Pch.check_clean_redirect "post dispatches" "/bring"
            (route_run ~method_:`POST ~target:(post_target "phvv-alpha"));
          Pch.check_clean_redirect "get dispatches" "/bring"
            (route_run ~method_:`GET ~target:(get_target "phvv-alpha"));
          List.iter
            (fun (label, method_, target) ->
              Alcotest.(check int)
                (label ^ ": unrouted")
                404
                (status_of (route_run ~method_ ~target)))
            [ ("GET on the POST path", `GET, post_target "phvv-alpha");
              ("POST on the GET path", `POST, get_target "phvv-alpha");
              ("trailing slash", `POST, post_target "phvv-alpha" ^ "/");
              ("sub-path", `POST, post_target "phvv-alpha" ^ "/create");
              ("plural alias", `POST, "/projects/phvv-alpha/community-homes");
              ("legacy alias", `POST, "/projects/phvv-alpha/home")
            ])
    ]

  (* ======== DB-free: shared rollout and authentication gates ======== *)

  let post_run ?session ?(headers = []) ~mode ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST
      ~target:(post_target "phvv-any")
      (make ~mode ~load_config)

  let routed_post ?session ?(headers = []) ?(mode = Ob.Public) ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST
      ~target:(post_target "phvv-any")
      (Dream.router
         [ Dream.post post_pattern (fun req -> make ~mode ~load_config req) ])

  let gate_cases =
    [ case "POST provisioning off: clean /bring redirect before any route \
            read, configuration load, or SQL" (fun () ->
          let loader, calls = counting_loader (ok_loader ()) in
          Pch.check_clean_redirect "off" "/bring"
            (Pch.gate_response "off"
               (post_run ~session:Pch.admin_session ~mode:Ob.Off
                  ~load_config:loader ()));
          Pch.check_clean_redirect "off routed" "/bring"
            (Pch.gate_response "off routed"
               (routed_post ~session:Pch.admin_session ~mode:Ob.Off
                  ~load_config:loader ()));
          Alcotest.(check int) "loader never called" 0 !calls)
    ; case "POST provisioning: anonymous and malformed sessions to /login, \
            loader untouched" (fun () ->
          let loader, calls = counting_loader (ok_loader ()) in
          Pch.check_clean_redirect "anonymous" "/login"
            (Pch.gate_response "anonymous" (routed_post ~load_config:loader ()));
          List.iter
            (fun raw ->
              Pch.check_clean_redirect ("user_id " ^ raw) "/login"
                (Pch.gate_response ("user_id " ^ raw)
                   (routed_post
                      ~session:[ ("user_id", raw) ]
                      ~load_config:loader ())))
            [ "not-a-number"; ""; "0"; "-3"; " 42"; "42x" ];
          (* A session admin claim alone is not an identity. *)
          Pch.check_clean_redirect "is_admin only" "/login"
            (Pch.gate_response "is_admin only"
               (routed_post
                  ~session:[ ("is_admin", "true") ]
                  ~mode:Ob.Admins ~load_config:loader ()));
          Alcotest.(check int) "loader never called" 0 !calls)
    ; case "POST provisioning admins mode: a non-admin is redirected before \
            the configuration load" (fun () ->
          let loader, calls = counting_loader (ok_loader ()) in
          Pch.check_clean_redirect "non-admin" "/bring"
            (Pch.gate_response "non-admin"
               (routed_post ~session:Pch.logged_in ~mode:Ob.Admins
                  ~load_config:loader ()));
          Alcotest.(check int) "loader never called" 0 !calls)
    ; case "POST provisioning: authorized sessions continue past the gates, \
            and an unrouted request is the generic 404 before configuration"
        (fun () ->
          (* Routerless: past the gates the missing route parameter is the
             next rejection, so reaching that defensive 404 proves the gates
             passed with no configuration read and no SQL (no sql_pool is
             installed). *)
          let continues label session mode =
            let loader, calls = counting_loader (ok_loader ()) in
            let response =
              Pch.gate_response label
                (post_run ~session ~mode ~load_config:loader ())
            in
            Alcotest.(check int) (label ^ ": defensive 404") 404
              (status_of response);
            Alcotest.(check (option string))
              (label ^ ": no-store")
              (Some "no-store")
              (Dream.header response "Cache-Control");
            Alcotest.(check int) (label ^ ": loader untouched") 0 !calls
          in
          continues "admin in admins mode" Pch.admin_session Ob.Admins;
          continues "user in public mode" Pch.logged_in Ob.Public;
          continues "admin in public mode" Pch.admin_session Ob.Public;
          (* Routed and authorized with a good configuration and origin: the
             next rejection is the missing content type, proving the whole
             prefix ran and still no SQL happened. *)
          Alcotest.(check int) "routed: 400 content type" 400
            (status_of
               (Pch.gate_response "routed"
                  (routed_post ~session:Pch.logged_in
                     ~headers:[ ("Origin", "https://earde.com") ]
                     ~load_config:(fun () -> ok_loader ())
                     ()))))
    ]

  (* ============ DB-free: configuration and origin ============ *)

  let config_origin_cases =
    [ case "POST provisioning: a configuration failure is a generic 503 that \
            names nothing" (fun () ->
          let loader, calls = counting_loader (gac_of_values ~origin:None ()) in
          let response =
            Pch.gate_response "config failure"
              (routed_post ~session:Pch.logged_in
                 ~headers:
                   [ ("Origin", "https://earde.com");
                     ("Content-Type", "application/x-www-form-urlencoded")
                   ]
                 ~load_config:loader ())
          in
          Alcotest.(check int) "503" 503 (status_of response);
          Alcotest.(check int) "loader called once" 1 !calls;
          Alcotest.(check (option string)) "no-store" (Some "no-store")
            (Dream.header response "Cache-Control");
          Alcotest.(check (option string)) "referrer policy"
            (Some Earde.Request_origin.referrer_policy)
            (Dream.header response "Referrer-Policy");
          let body = Lwt_main.run (Dream.body response) in
          List.iter
            (fun needle ->
              Alcotest.(check bool) ("no leak " ^ needle) false
                (contains body needle))
            [ "EARDE_PUBLIC_ORIGIN"; "GITHUB_APP"; "Missing"; "Invalid";
              "public_origin"
            ])
    ; case "POST provisioning origin gate: the exact same-origin policy, \
            before any form parse" (fun () ->
          let origin_run label ?sec_fetch_site origin =
            let headers =
              (match origin with Some o -> [ ("Origin", o) ] | None -> [])
              @
              match sec_fetch_site with
              | Some v -> [ ("Sec-Fetch-Site", v) ]
              | None -> []
            in
            Pch.gate_response label
              (routed_post ~session:Pch.logged_in ~headers
                 ~load_config:(fun () -> ok_loader ())
                 ())
          in
          let rejected label ?sec_fetch_site origin =
            Alcotest.(check int) (label ^ ": 403") 403
              (status_of (origin_run label ?sec_fetch_site origin))
          in
          (* Past the origin gate the missing content type is the next
             rejection (400) — reaching it proves the origin was accepted and
             that the form was not parsed before the check. *)
          let accepted label ?sec_fetch_site origin =
            Alcotest.(check int)
              (label ^ ": passes origin")
              400
              (status_of (origin_run label ?sec_fetch_site origin))
          in
          accepted "exact origin" (Some "https://earde.com");
          accepted "explicit default port" (Some "https://earde.com:443");
          accepted "fetch metadata" ~sec_fetch_site:"same-origin" None;
          rejected "cross-origin" (Some "https://evil.example");
          rejected "same-site subdomain" (Some "https://www.earde.com");
          rejected "wrong scheme" (Some "http://earde.com");
          rejected "null origin" (Some "null");
          rejected "mismatch beats metadata" ~sec_fetch_site:"same-origin"
            (Some "https://evil.example");
          rejected "no signals" None;
          rejected "cross-site" ~sec_fetch_site:"cross-site" None;
          rejected "same-site metadata" ~sec_fetch_site:"same-site" None;
          let leak = origin_run "reflection" (Some "https://evil.example") in
          Alcotest.(check bool) "origin never reflected" false
            (contains (Lwt_main.run (Dream.body leak)) "evil.example"))
    ]

  (* ==================== DB-free: CSRF ==================== *)

  let csrf_pipeline () =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    let* () = Dream.set_session_field req "user_id" "42" in
    match Dream.method_ req with
    | `GET ->
        Dream.respond
          (Dream.csrf_token req ^ "\n" ^ Dream.csrf_token ~valid_for:(-60.) req)
    | _ ->
        Dream.router
          [ Dream.post post_pattern (fun r ->
                make ~mode:Ob.Public ~load_config:(fun () -> ok_loader ()) r)
          ]
          req

  let csrf_post ?cookie ?(content_type = true) pipeline body_fields =
    let headers =
      [ ("Origin", "https://earde.com") ]
      @ (if content_type then
           [ ("Content-Type", "application/x-www-form-urlencoded") ]
         else [])
      @ match cookie with Some c -> [ ("Cookie", c) ] | None -> []
    in
    match
      Lwt_main.run
        (pipeline
           (Dream.request ~method_:`POST ~target:(post_target "phvv-any")
              ~headers (Pch.form_body body_fields)))
    with
    | response -> `Response response
    | exception _ -> `Db_boundary

  let csrf_rejected label expected result =
    Alcotest.(check int) (label ^ ": status") expected
      (status_of (Pch.gate_response label result))

  let csrf_cases =
    [ case "POST provisioning CSRF: Dream verification gates every \
            submission; only a verified form reaches the database" (fun () ->
          let pipeline = csrf_pipeline () in
          let cookie, fresh, expired = Pch.mint_tokens "mint" pipeline in
          let valid = fields () in
          (* Every CSRF failure refuses the submission, but it is answered by
             re-rendering the owner-authorized page (a fresh token, nothing
             reflected) rather than a terminal page — so each one reaches the
             read model's DB boundary and none reaches the store. A page
             whose one-hour token outlived its fourteen-day session must not
             become permanently unsubmittable. *)
          Pch.check_db_boundary "missing token re-renders"
            (csrf_post ~cookie pipeline valid);
          Pch.check_db_boundary "invalid token re-renders"
            (csrf_post ~cookie pipeline
               (("dream.csrf", "not-a-token") :: valid));
          Pch.check_db_boundary "expired token re-renders"
            (csrf_post ~cookie pipeline (("dream.csrf", expired) :: valid));
          Pch.check_db_boundary "duplicate tokens re-render"
            (csrf_post ~cookie pipeline
               (("dream.csrf", fresh) :: ("dream.csrf", fresh) :: valid));
          Pch.check_db_boundary "wrong session re-renders"
            (csrf_post pipeline (("dream.csrf", fresh) :: valid));
          (* A wrong content type is still answered without any SQL. *)
          csrf_rejected "wrong content type" 400
            (csrf_post ~cookie ~content_type:false pipeline
               (("dream.csrf", fresh) :: valid));
          (* A rejected token still answers before the application fields are
             even looked at: the re-render is the same whatever was sent. *)
          Pch.check_db_boundary "bad token beats bad form"
            (csrf_post ~cookie pipeline
               [ ("dream.csrf", "not-a-token"); ("phvv_unknown", "x") ]);
          (* A verified token reaches Dream.sql, which raises without a pool:
             CSRF passed, Dream stripped its own field, and the store call is
             the next thing to run. *)
          Pch.check_db_boundary "verified form continues"
            (csrf_post ~cookie pipeline (("dream.csrf", fresh) :: valid)))
    ; case "POST provisioning CSRF: a verified token with an invalid form \
            still re-authorizes through the database" (fun () ->
          let pipeline = csrf_pipeline () in
          let cookie, fresh, _ = Pch.mint_tokens "mint" pipeline in
          (* Every parser rejection re-renders the owner-authorized page,
             which needs the read model — so it too reaches the database
             boundary rather than answering from the submission alone. *)
          List.iter
            (fun (label, body_fields) ->
              Pch.check_db_boundary label
                (csrf_post ~cookie pipeline
                   (("dream.csrf", fresh) :: body_fields)))
            [ ("unknown field", ("phvv_unknown", "x") :: fields ());
              ("blank name", fields ~name:"   " ());
              ("uppercase slug", fields ~slug:"Phvv-Home" ());
              ( "control byte in description",
                fields ~description:"phvv\001body" () )
            ])
    ]

  (* ================= Database-gated integration ================= *)

  (* Distinctive credential-shaped fixtures. None may appear in any page,
     redirect, header, or cookie this feature produces. *)
  let access_marker = "gho_PHVV_ACCESS_TOKEN_SECRET"
  let refresh_marker = "ghr_PHVV_REFRESH_TOKEN"
  let pkce_marker = "PHVV_PKCE_VERIFIER_VALUE"
  let state_marker = "PHVV_OAUTH_STATE_VALUE"
  let secret_marker = "PHVV_CLIENT_SECRET_VALUE"

  let credential_markers =
    [ ("access token", access_marker);
      ("refresh token", refresh_marker);
      ("PKCE verifier", pkce_marker);
      ("OAuth state", state_marker);
      ("client secret", secret_marker);
      ("external installation id", "951000001");
      ("external account id", "951100001")
    ]

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 951100001 AND 951100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 951100001 AND 951100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 951000001 AND 951000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phvv-%'"
      ; "DELETE FROM users WHERE username LIKE 'phvv_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 951000001 AND 951000999"
      ; "DELETE FROM rate_limits WHERE endpoint LIKE '/projects/phvv-%'"
      ]

  let q_count_by_slug = Phvs.q_count_by_slug

  let q_count_like =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT COUNT(*) FROM communities WHERE slug LIKE $1"

  let q_active_relations =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_projects \
     WHERE project_id = $1 AND status IN ('pending', 'accepted')"

  let q_set_admin = Phrv.q_set_admin

  (* Test-only identity drift, scoped to one reserved slug: the community row
     the store inserts comes back different from the identity it parsed, so
     the store's own bounded revalidation must roll the whole draft back as
     Inconsistent_data. Installed and dropped inside that one case under
     Lwt.finalize; production migrations are untouched, and the mutated name
     still satisfies every scoped network-identity CHECK. *)
  let ddl sql = (Caqti_type.unit ->. Caqti_type.unit) sql

  let q_create_drift_fn =
    ddl
      "CREATE FUNCTION phvv_drift_fn() RETURNS trigger \
       LANGUAGE plpgsql \
       AS 'BEGIN NEW.name := NEW.name || '' Drift''; RETURN NEW; END'"

  let q_create_drift_trigger =
    ddl
      "CREATE TRIGGER phvv_drift BEFORE INSERT ON communities \
       FOR EACH ROW WHEN (NEW.slug = 'phvv-drift-home') \
       EXECUTE FUNCTION phvv_drift_fn()"

  let q_drop_drift_trigger =
    ddl "DROP TRIGGER IF EXISTS phvv_drift ON communities"

  let q_drop_drift_fn = ddl "DROP FUNCTION IF EXISTS phvv_drift_fn()"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* === the real production pipeline shape ===

     One shared two-connection sql_pool for the whole suite: nothing ever
     closes a Dream.sql_pool, so a fresh pool per request would exhaust
     Postgres max_connections; two connections are the minimum that lets the
     concurrency cases run two requests genuinely at once. Everything else is
     the real production shape — secret, memory sessions, the real router
     paths bound to the real handlers, and the POST wrapped in the same
     authenticated-mutation rate limiter main.ml applies. Session identity is
     sticky: a request that already carries a session keeps its own user, so
     independent cookies stay independent under concurrency. *)
  let shared_identity : (int * bool) option ref = ref None
  let shared_pipeline = ref None

  let identity_middleware handler request =
    match Dream.session_field request "user_id" with
    | Some _ -> handler request
    | None -> (
        match !shared_identity with
        | None -> handler request
        | Some (uid, is_admin) ->
            let* () =
              Dream.set_session_field request "user_id" (string_of_int uid)
            in
            let* () =
              if is_admin then Dream.set_session_field request "is_admin" "true"
              else Lwt.return_unit
            in
            handler request)

  let build_pipeline ~url =
    Dream.sql_pool ~size:2 url @@ Dream.set_secret gck_secret
    @@ Dream.memory_sessions @@ identity_middleware
    @@ Dream.router
         [ Dream.get "/mint" (fun req -> Dream.respond (Dream.csrf_token req));
           (* The exact production failure this suite regresses: an
              authentic, correctly signed, same-session token whose one-hour
              lifetime ran out while the page sat open. *)
           Dream.get "/mint-expired" (fun req ->
               Dream.respond (Dream.csrf_token ~valid_for:(-60.) req));
           Dream.get get_pattern (fun req -> make_get ~mode:Ob.Public req);
           Dream.post post_pattern
             (Earde.Handlers.Rate_limit.middleware (fun req ->
                  make ~mode:Ob.Public
                    ~load_config:(fun () -> ok_loader ())
                    req));
           Dream.get "/projects/:slug/request-home" (fun req ->
               Earde.Project_home_request_handlers
               .make_project_home_choice_handler ~mode:Ob.Public req);
           Dream.get "/c/:slug" Earde.Handlers.community_page_handler;
           Dream.get "/c/:slug/settings"
             Earde.Handlers.community_settings_handler
         ]

  let pipeline_for ~url =
    match !shared_pipeline with
    | Some pipeline -> pipeline
    | None ->
        let pipeline = build_pipeline ~url in
        shared_pipeline := Some pipeline;
        pipeline

  let as_user ?(admin_session = false) uid =
    shared_identity := Some (uid, admin_session)

  let as_anonymous () = shared_identity := None

  let do_get ?pipeline ?cookie ~url ~target () =
    let pipeline =
      match pipeline with Some p -> p | None -> pipeline_for ~url
    in
    let headers = match cookie with Some c -> [ ("Cookie", c) ] | None -> [] in
    let* response = pipeline (Dream.request ~method_:`GET ~target ~headers "") in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* [omit_token] posts a body with no framework CSRF field at all — exactly
     what a page rendered without one would send; [extra_headers] carries the
     rest of the real navigation metadata a browser attaches. *)
  let do_post ?pipeline ?(origin = Some "https://earde.com")
      ?(extra_headers = []) ?(omit_token = false) ~url ~cookie ~target ~token
      ~body_fields () =
    let pipeline =
      match pipeline with Some p -> p | None -> pipeline_for ~url
    in
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @ [ ("Content-Type", "application/x-www-form-urlencoded");
          ("Cookie", cookie)
        ]
      @ extra_headers
    in
    let fields =
      if omit_token then body_fields else ("dream.csrf", token) :: body_fields
    in
    let* response =
      pipeline
        (Dream.request ~method_:`POST ~target ~headers (Pch.form_body fields))
    in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* One cookie-less GET that opens a fresh session for this user and returns
     its cookie plus a live CSRF token. *)
  let open_session ?pipeline label ~url uid =
    as_user uid;
    let* response, token = do_get ?pipeline ~url ~target:"/mint" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return (Pch.session_cookie label response, token)

  let mint_token label ~url ~cookie =
    let* response, body = do_get ~url ~cookie ~target:"/mint" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return body

  let mint_expired_token label ~url ~cookie =
    let* response, body = do_get ~url ~cookie ~target:"/mint-expired" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return body

  (* One cookie-less GET of the creation page: the page, its session cookie,
     and the live CSRF token its own form carries. *)
  let open_form label ~url ~slug uid =
    as_user uid;
    let* response, body = do_get ~url ~target:(get_target slug) () in
    Alcotest.(check int) (label ^ ": creation page 200") 200
      (status_of response);
    Lwt.return (Pch.session_cookie label response, Pch.csrf_of_page label body,
                body)

  let check_clean_redirect label expected response body =
    Alcotest.(check int) (label ^ ": 303") 303 (status_of response);
    Alcotest.(check (option string)) (label ^ ": Location") (Some expected)
      (Dream.header response "Location");
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": no-cache") (Some "no-cache")
      (Dream.header response "Pragma");
    Alcotest.(check (option string)) (label ^ ": no-referrer")
      (Some "no-referrer")
      (Dream.header response "Referrer-Policy");
    Alcotest.(check string) (label ^ ": empty body") "" body

  let check_generic_404 label response body =
    Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "This page does not exist.")

  let check_generic_500 label response body =
    Alcotest.(check int) (label ^ ": 500") 500 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "Something went wrong on our side.");
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no detail " ^ needle) false
          (contains body needle))
      [ "communities_slug_key"; "community_projects"; "open_source_projects";
        "Caqti"; "PostgreSQL"; "SELECT"; "search_path"; "Inconsistent";
        "Storage_error"; "phvv_void"; "phvv_drift"
      ]

  (* The re-rendered creation form: the requested status, the exact feedback
     copy, a live CSRF field, and the one form pointing back at this route. *)
  let check_rerender label ~status ~feedback ~slug response body =
    Alcotest.(check int) (label ^ ": status") status (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": referrer policy")
      (Some Earde.Request_origin.referrer_policy)
      (Dream.header response "Referrer-Policy");
    Alcotest.(check bool) (label ^ ": feedback copy") true
      (contains body feedback);
    Alcotest.(check bool) (label ^ ": fresh CSRF field") true
      (contains body "name=\"dream.csrf\"");
    Alcotest.(check bool) (label ^ ": posts back to this route") true
      (contains body (Printf.sprintf "action='%s'" (post_target slug)));
    Alcotest.(check int) (label ^ ": exactly one form") 1
      (ps_count (ps_fragment body) "<form")

  (* The existing community-page unavailable answer, asserted exactly as the
     legacy handler already produces it: this slice deliberately changes no
     community authorization, so the check records that behaviour rather than
     imposing the provisioning handler's own header contract on it. *)
  let check_community_unavailable label response body =
    Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "This community does not exist.")

  let check_body_no_credentials label body =
    List.iter
      (fun (what, needle) ->
        Alcotest.(check bool) (label ^ ": body free of " ^ what) false
          (contains body needle))
      credential_markers

  let check_no_credentials label response body =
    check_body_no_credentials label body;
    let headers =
      String.concat "\n"
        (List.map (fun (k, v) -> k ^ ": " ^ v) (Dream.all_headers response))
    in
    List.iter
      (fun (what, needle) ->
        Alcotest.(check bool) (label ^ ": headers free of " ^ what) false
          (contains headers needle))
      credential_markers

  (* === success: the PRG into the new private settings draft === *)

  let success_case =
    db_case "POST provisioning: a steward's valid submission creates the \
             complete private draft and redirects into its settings"
      (fun ~url conn ->
        let* owner = insert_user conn "phvv_owner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000001L ~slug:"phvv-alpha"
            ~name:"Phvv Alpha"
        in
        let* cookie, token, page =
          open_form "creation" ~url ~slug:"phvv-alpha" owner
        in
        Alcotest.(check bool) "the form posts to the POST route" true
          (contains page
             (Printf.sprintf "action='%s'" (post_target "phvv-alpha")));
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-alpha") ~token
            ~body_fields:
              (fields ~name:"Phvv Provisioned Home" ~slug:"phvv-provisioned"
                 ~description:"A durable home description." ())
            ()
        in
        check_clean_redirect "provisioned" (settings_target "phvv-provisioned")
          response body;
        check_no_credentials "provisioned redirect" response body;
        (* No query, fragment, result token, or internal identifier. *)
        let location =
          match Dream.header response "Location" with Some l -> l | None -> ""
        in
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("Location free of " ^ needle) false
              (contains location needle))
          [ "?"; "#"; "created"; "ok=" ];
        (* The complete durable draft, asserted through the store suite's own
           production-shape checker. *)
        let* cid, _rid =
          Phvs.check_provisioned_draft "durable" conn ~actor:owner ~project
            ~slug:"phvv-provisioned" ~name:"Phvv Provisioned Home"
            ~description:"A durable home description."
        in
        Alcotest.(check bool) "a community id exists" true (cid > 0);
        (* The advertised destination really serves the new draft's settings
           to its creator. *)
        let* settings_response, settings_body =
          do_get ~url ~cookie ~target:(settings_target "phvv-provisioned") ()
        in
        Alcotest.(check int) "settings 200" 200 (status_of settings_response);
        (* The settings surface addresses the community by its canonical
           slug, which is exactly what the redirect built. *)
        Alcotest.(check bool) "settings is the new community's" true
          (contains settings_body "phvv-provisioned");
        check_no_credentials "settings" settings_response settings_body;
        Lwt.return_unit)

  (* === form parsing: 422 rendering and safe value preservation === *)

  let long_name = "Phvv " ^ String.make 130 'n'
  let long_description = String.make 2100 'd'

  let parser_rejection_case =
    db_case "POST provisioning: every parser rejection is a 422 re-render \
             that preserves only provably safe values" (fun ~url conn ->
        let* owner = insert_user conn "phvv_fowner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000002L ~slug:"phvv-form"
            ~name:"Phvv Form"
        in
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-form" owner
        in
        (* 1. Structural: an unknown field carrying a credential-shaped value
           is Invalid_form, and nothing submitted is reflected back. *)
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-form") ~token
            ~body_fields:
              (("phvv_planted", access_marker)
              :: fields ~name:"Phvv Planted Name" ~slug:"phvv-planted"
                   ~description:"Planted body." ())
            ()
        in
        check_rerender "invalid form" ~status:422
          ~feedback:"We couldn't read that submission." ~slug:"phvv-form"
          response body;
        check_no_credentials "invalid form" response body;
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("invalid form reflects no " ^ needle) false
              (contains body needle))
          [ "phvv_planted"; "Phvv Planted Name"; "phvv-planted";
            "Planted body."
          ];
        Alcotest.(check bool) "the controls are blank" true
          (contains body "name='community_slug' maxlength='80' value=''");
        (* 2. Semantic name: the exact submitted values survive. *)
        let* token = mint_token "name" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-form") ~token
            ~body_fields:
              (fields ~name:long_name ~slug:"phvv-kept-slug"
                 ~description:"Kept body." ())
            ()
        in
        check_rerender "invalid name" ~status:422
          ~feedback:"Enter a community name we can use." ~slug:"phvv-form"
          response body;
        Alcotest.(check bool) "name preserved" true (contains body long_name);
        Alcotest.(check bool) "slug preserved" true
          (contains body "value='phvv-kept-slug'");
        Alcotest.(check bool) "description preserved" true
          (contains body ">Kept body.</textarea>");
        (* 3. Semantic slug. *)
        let* token = mint_token "slug" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-form") ~token
            ~body_fields:
              (fields ~name:"Phvv Kept Name" ~slug:"Phvv-Bad-Slug"
                 ~description:"Kept body." ())
            ()
        in
        check_rerender "invalid slug" ~status:422
          ~feedback:"Enter a community address using lowercase letters"
          ~slug:"phvv-form" response body;
        Alcotest.(check bool) "slug preserved verbatim" true
          (contains body "value='Phvv-Bad-Slug'");
        Alcotest.(check bool) "name preserved" true
          (contains body "value='Phvv Kept Name'");
        (* 4. Semantic description. *)
        let* token = mint_token "description" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-form") ~token
            ~body_fields:
              (fields ~name:"Phvv Kept Name" ~slug:"phvv-kept-slug"
                 ~description:long_description ())
            ()
        in
        check_rerender "invalid description" ~status:422
          ~feedback:"That description can't be used." ~slug:"phvv-form"
          response body;
        Alcotest.(check bool) "description preserved" true
          (contains body long_description);
        (* Nothing durable was created by any of the four. *)
        let* communities = find conn "communities" q_count_like "phvv-%" in
        Alcotest.(check int) "no community created" 0 communities;
        let* relations =
          find conn "relations" Phrq.q_count_for_project project
        in
        Alcotest.(check int) "no relation created" 0 relations;
        Lwt.return_unit)

  let escaping_case =
    db_case "POST provisioning: every preserved value is escaped, never \
             markup" (fun ~url conn ->
        let* owner = insert_user conn "phvv_escowner" in
        let* _inst, _project =
          make_project conn ~user:owner ~ext_id:951000003L ~slug:"phvv-esc"
            ~name:"Phvv Esc"
        in
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-esc" owner
        in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-esc") ~token
            ~body_fields:
              (fields ~name:"<script>phvv_x()</script>" ~slug:"Phvv-Bad"
                 ~description:"<b>phvv</b>" ())
            ()
        in
        Alcotest.(check int) "422" 422 (status_of response);
        Alcotest.(check bool) "escaped name" true
          (contains body "&lt;script&gt;phvv_x()&lt;/script&gt;");
        Alcotest.(check bool) "raw name absent" false
          (contains body "<script>phvv_x()</script>");
        Alcotest.(check bool) "escaped description" true
          (contains body "&lt;b&gt;phvv&lt;/b&gt;");
        Alcotest.(check bool) "raw description absent" false
          (contains body "<b>phvv</b>");
        Lwt.return_unit)

  (* === community-slug conflict === *)

  let slug_conflict_case =
    db_case "POST provisioning: a taken community slug is a 409 re-render \
             that preserves the submission and stays retryable"
      (fun ~url conn ->
        let* owner = insert_user conn "phvv_cowner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000004L ~slug:"phvv-conflict"
            ~name:"Phvv Conflict"
        in
        (* A legacy community and a network community, both simply "taken". *)
        let* _legacy =
          insert_community ~name:"Phvv Legacy" ~network:false conn "phvv-legacy"
        in
        let* _network =
          insert_community ~name:"Phvv Network" conn "phvv-network"
        in
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-conflict" owner
        in
        let attempt label ~token ~slug =
          let* response, body =
            do_post ~url ~cookie ~target:(post_target "phvv-conflict") ~token
              ~body_fields:
                (fields ~name:"Phvv Conflict Home" ~slug
                   ~description:"Conflict body." ())
              ()
          in
          check_rerender label ~status:409
            ~feedback:"That community address is already taken."
            ~slug:"phvv-conflict" response body;
          Alcotest.(check bool) (label ^ ": slug preserved") true
            (contains body (Printf.sprintf "value='%s'" slug));
          Alcotest.(check bool) (label ^ ": name preserved") true
            (contains body "value='Phvv Conflict Home'");
          Alcotest.(check bool) (label ^ ": description preserved") true
            (contains body ">Conflict body.</textarea>");
          (* Nothing about the conflicting community leaks. *)
          List.iter
            (fun needle ->
              Alcotest.(check bool) (label ^ ": no leak " ^ needle) false
                (contains body needle))
            [ "Phvv Legacy"; "Phvv Network"; "visibility"; "onboarding_state";
              "is_network_community"
            ];
          check_no_credentials label response body;
          Lwt.return_unit
        in
        let* () = attempt "legacy conflict" ~token ~slug:"phvv-legacy" in
        let* token = mint_token "network" ~url ~cookie in
        let* () = attempt "network conflict" ~token ~slug:"phvv-network" in
        (* Neither attempt created anything, and the project can still win a
           free slug. *)
        let* relations =
          find conn "relations" Phrq.q_count_for_project project
        in
        Alcotest.(check int) "no relation after conflicts" 0 relations;
        let* token = mint_token "retry" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-conflict") ~token
            ~body_fields:
              (fields ~name:"Phvv Conflict Home" ~slug:"phvv-conflict-home"
                 ~description:"Conflict body." ())
            ()
        in
        check_clean_redirect "retry succeeds"
          (settings_target "phvv-conflict-home") response body;
        let* _ =
          Phvs.check_provisioned_draft "retry" conn ~actor:owner ~project
            ~slug:"phvv-conflict-home" ~name:"Phvv Conflict Home"
            ~description:"Conflict body."
        in
        Lwt.return_unit)

  (* === active home, and replay === *)

  let active_home_case =
    db_case "POST provisioning: a pending request or accepted home sends the \
             steward to the authoritative home page, never a stale form"
      (fun ~url conn ->
        let* owner = insert_user conn "phvv_aowner" in
        let* moderator = insert_user conn "phvv_amod" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000005L ~slug:"phvv-active"
            ~name:"Phvv Active"
        in
        let* cid = insert_community ~name:"Phvv Target" conn "phvv-target" in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        (* The form is opened while the project is still eligible; the
           relation appears underneath it. *)
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-active" owner
        in
        let* () =
          request_pending "pending" conn ~user:owner ~slug:"phvv-active"
            ~community:cid
        in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-active") ~token
            ~body_fields:(fields ~slug:"phvv-active-home" ())
            ()
        in
        check_clean_redirect "pending" (request_home_target "phvv-active")
          response body;
        check_no_credentials "pending redirect" response body;
        let* communities =
          find conn "no draft" q_count_by_slug "phvv-active-home"
        in
        Alcotest.(check int) "no community draft survives" 0 communities;
        (* Accepted behaves identically. *)
        let* () =
          review "accept" conn ~reviewer:moderator ~slug:"phvv-active"
            ~community_slug:"phvv-target" Rvs.Accept
        in
        let* token = mint_token "accepted" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-active") ~token
            ~body_fields:(fields ~slug:"phvv-active-home" ())
            ()
        in
        check_clean_redirect "accepted" (request_home_target "phvv-active")
          response body;
        let* communities =
          find conn "still no draft" q_count_by_slug "phvv-active-home"
        in
        Alcotest.(check int) "still no community draft" 0 communities;
        let* active = find conn "active" q_active_relations project in
        Alcotest.(check int) "exactly one active relation" 1 active;
        Lwt.return_unit)

  let replay_case =
    db_case "POST provisioning: replaying a succeeded submission creates \
             nothing and lands on the current home page" (fun ~url conn ->
        let* owner = insert_user conn "phvv_rowner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000006L ~slug:"phvv-replay"
            ~name:"Phvv Replay"
        in
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-replay" owner
        in
        let body_fields =
          fields ~name:"Phvv Replay Home" ~slug:"phvv-replay-home" ()
        in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-replay") ~token
            ~body_fields ()
        in
        check_clean_redirect "first" (settings_target "phvv-replay-home")
          response body;
        (* The very same token replayed. Dream's CSRF tokens are stateless
           and session-bound rather than one-shot, so the token still
           verifies: durable idempotency, not token consumption, is what
           protects this mutation. *)
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-replay") ~token
            ~body_fields ()
        in
        check_clean_redirect "same-token replay"
          (request_home_target "phvv-replay") response body;
        (* A freshly minted token replays to the same place. *)
        let* fresh = mint_token "fresh" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-replay") ~token:fresh
            ~body_fields ()
        in
        check_clean_redirect "fresh-token replay"
          (request_home_target "phvv-replay") response body;
        (* A genuinely unusable token no longer dead-ends: it is refused
           without opening the store and answered by reloading the
           owner-authorized page. This project now has an active home, so
           that reload is exactly the generic 404 its own GET gives. *)
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-replay")
            ~token:"phvv-not-a-token" ~body_fields ()
        in
        check_generic_404 "bad token" response body;
        (* Exactly one of everything. *)
        let* communities =
          find conn "communities" q_count_by_slug "phvv-replay-home"
        in
        Alcotest.(check int) "exactly one community" 1 communities;
        let* relations =
          find conn "relations" Phrq.q_count_for_project project
        in
        Alcotest.(check int) "exactly one relation" 1 relations;
        let* active = find conn "active" q_active_relations project in
        Alcotest.(check int) "exactly one active home" 1 active;
        let* _ =
          Phvs.check_provisioned_draft "after replays" conn ~actor:owner
            ~project ~slug:"phvv-replay-home" ~name:"Phvv Replay Home"
            ~description:"<null>"
        in
        Lwt.return_unit)

  (* === authorization loss and lifecycle drift between GET and POST === *)

  let drift_case =
    db_case "POST provisioning: authorization loss and verification drift \
             between the GET and the POST are one identical generic 404"
      (fun ~url conn ->
        let* owner = insert_user conn "phvv_downer" in
        let* stranger = insert_user conn "phvv_dstranger" in
        let* admin = insert_user conn "phvv_dadmin" in
        let* () = exec conn "durable admin" q_set_admin (admin, true) in
        let* _inst, drifting =
          make_project conn ~user:owner ~ext_id:951000007L ~slug:"phvv-drift"
            ~name:"Phvv Drift"
        in
        let* _inst2, healthy =
          make_project conn ~user:owner ~ext_id:951000008L ~slug:"phvv-sound"
            ~name:"Phvv Sound"
        in
        let bodies = ref [] in
        let expect_404 label ~cookie ~token ~slug =
          let* response, body =
            do_post ~url ~cookie ~target:(post_target slug) ~token
              ~body_fields:(fields ~slug:"phvv-drift-target" ())
              ()
          in
          check_generic_404 label response body;
          check_no_credentials label response body;
          bodies := body :: !bodies;
          Lwt.return_unit
        in
        (* The steward opens the form while everything is still fine. *)
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-drift" owner
        in
        let* () =
          exec conn "stale" Phrq.q_set_verification (drifting, "stale")
        in
        let* () = expect_404 "stale project" ~cookie ~token ~slug:"phvv-drift" in
        let* () =
          exec conn "revoked" Phrq.q_set_verification (drifting, "revoked")
        in
        let* token = mint_token "revoked" ~url ~cookie in
        let* () =
          expect_404 "revoked project" ~cookie ~token ~slug:"phvv-drift"
        in
        let* () =
          exec conn "verified" Phrq.q_set_verification (drifting, "verified")
        in
        let* () = exec conn "unsteward" Phrq.q_delete_steward (drifting, owner) in
        let* token = mint_token "unstewarded" ~url ~cookie in
        let* () =
          expect_404 "removed stewardship" ~cookie ~token ~slug:"phvv-drift"
        in
        (* A durable admin who is not a steward, and an unrelated user, each
           on their own session, against the still-healthy project. *)
        let* admin_cookie, admin_token = open_session "admin" ~url admin in
        let* () =
          expect_404 "durable admin without stewardship" ~cookie:admin_cookie
            ~token:admin_token ~slug:"phvv-sound"
        in
        let* stranger_cookie, stranger_token =
          open_session "stranger" ~url stranger
        in
        let* () =
          expect_404 "unrelated user" ~cookie:stranger_cookie
            ~token:stranger_token ~slug:"phvv-sound"
        in
        (* Byte-identical answers: no state is distinguishable. *)
        (match !bodies with
        | [] -> Alcotest.fail "no 404 bodies captured"
        | first :: rest ->
            List.iteri
              (fun i body ->
                Alcotest.(check bool)
                  (Printf.sprintf "404 body %d identical" i)
                  true (String.equal first body))
              rest);
        let* () =
          Phvs.check_no_state "drifting" conn ~project:drifting
            ~slug:"phvv-drift-target"
        in
        Phvs.check_no_state "healthy" conn ~project:healthy
          ~slug:"phvv-drift-target")

  (* === durable failure === *)

  let inconsistent_case =
    db_case "POST provisioning: a durable identity drift inside the \
             transaction is one generic non-cacheable 500, with no partial \
             draft" (fun ~url conn ->
        let* owner = insert_user conn "phvv_icowner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000009L ~slug:"phvv-ic"
            ~name:"Phvv Ic"
        in
        let* cookie, token, _ = open_form "creation" ~url ~slug:"phvv-ic" owner in
        let* () = exec conn "create drift fn" q_create_drift_fn () in
        Lwt.finalize
          (fun () ->
            let* () =
              exec conn "create drift trigger" q_create_drift_trigger ()
            in
            let* response, body =
              do_post ~url ~cookie ~target:(post_target "phvv-ic") ~token
                ~body_fields:
                  (fields ~name:"Phvv Ic Home" ~slug:"phvv-drift-home" ())
                ()
            in
            check_generic_500 "identity drift" response body;
            check_no_credentials "identity drift" response body;
            Phvs.check_no_state "identity drift" conn ~project
              ~slug:"phvv-drift-home")
          (fun () ->
            let* () = exec conn "drop trigger" q_drop_drift_trigger () in
            exec conn "drop fn" q_drop_drift_fn ()))

  let storage_case =
    db_case "POST provisioning: a real database failure is one generic \
             non-cacheable 500 on both the store and the re-render path"
      (fun ~url _conn ->
        let poisoned =
          Uri.to_string
            (Uri.add_query_param' (Uri.of_string url)
               ("options", "-csearch_path=phvv_void"))
        in
        (* A dedicated pool for this one case: the shared pipeline must keep
           talking to the real schema. *)
        let poison_pipe = build_pipeline ~url:poisoned in
        let* cookie, token =
          open_session ~pipeline:poison_pipe "poisoned" ~url 424242
        in
        let* response, body =
          do_post ~pipeline:poison_pipe ~url ~cookie
            ~target:(post_target "phvv-anything") ~token
            ~body_fields:(fields ~slug:"phvv-void-home" ())
            ()
        in
        check_generic_500 "poisoned store call" response body;
        let* response, body =
          do_post ~pipeline:poison_pipe ~url ~cookie
            ~target:(post_target "phvv-anything") ~token
            ~body_fields:(fields ~slug:"Phvv-Bad" ())
            ()
        in
        check_generic_500 "poisoned re-render" response body;
        Lwt.return_unit)

  (* === concurrency through HTTP === *)

  let location response =
    match Dream.header response "Location" with Some l -> l | None -> ""

  let same_project_race_case =
    db_case "POST provisioning: two concurrent submissions for one project \
             leave exactly one community; the loser lands on the home page"
      (fun ~url conn ->
        let* owner = insert_user conn "phvv_p1owner" in
        let* second = insert_user conn "phvv_p1second" in
        let* inst, project =
          make_project conn ~user:owner ~ext_id:951000010L ~slug:"phvv-race"
            ~name:"Phvv Race"
        in
        let* () = add_steward conn ~project ~user:second ~installation:inst in
        let* cookie_a, token_a, _ =
          open_form "steward a" ~url ~slug:"phvv-race" owner
        in
        let* cookie_b, token_b, _ =
          open_form "steward b" ~url ~slug:"phvv-race" second
        in
        (* Two independent sessions and tokens genuinely in flight at once
           over two pooled connections; the project lock inside the store
           serializes them without any sleep. *)
        let* (response_a, body_a), (response_b, body_b) =
          Lwt.both
            (do_post ~url ~cookie:cookie_a ~target:(post_target "phvv-race")
               ~token:token_a
               ~body_fields:(fields ~name:"Phvv Race A" ~slug:"phvv-race-a" ())
               ())
            (do_post ~url ~cookie:cookie_b ~target:(post_target "phvv-race")
               ~token:token_b
               ~body_fields:(fields ~name:"Phvv Race B" ~slug:"phvv-race-b" ())
               ())
        in
        let a_lost =
          String.equal (location response_a) (request_home_target "phvv-race")
        in
        let win, win_body, lose, lose_body, winning_slug, losing_slug =
          if a_lost then
            (response_b, body_b, response_a, body_a, "phvv-race-b",
             "phvv-race-a")
          else
            (response_a, body_a, response_b, body_b, "phvv-race-a",
             "phvv-race-b")
        in
        check_clean_redirect "winner" (settings_target winning_slug) win
          win_body;
        check_clean_redirect "loser" (request_home_target "phvv-race") lose
          lose_body;
        let* winners = find conn "winner row" q_count_by_slug winning_slug in
        Alcotest.(check int) "winning community exists" 1 winners;
        let* losers = find conn "loser row" q_count_by_slug losing_slug in
        Alcotest.(check int) "loser community absent" 0 losers;
        let* relations =
          find conn "relations" Phrq.q_count_for_project project
        in
        Alcotest.(check int) "exactly one relation" 1 relations;
        let* active = find conn "active" q_active_relations project in
        Alcotest.(check int) "exactly one active home" 1 active;
        Lwt.return_unit)

  let same_slug_race_case =
    db_case "POST provisioning: two projects racing for one community slug \
             leave one winner and a clean 409 loser" (fun ~url conn ->
        let* owner_a = insert_user conn "phvv_s1owner" in
        let* owner_b = insert_user conn "phvv_s2owner" in
        let* _inst_a, project_a =
          make_project conn ~user:owner_a ~ext_id:951000011L ~slug:"phvv-slug-a"
            ~name:"Phvv Slug A"
        in
        let* _inst_b, project_b =
          make_project conn ~user:owner_b ~ext_id:951000012L ~slug:"phvv-slug-b"
            ~name:"Phvv Slug B"
        in
        let* cookie_a, token_a, _ =
          open_form "project a" ~url ~slug:"phvv-slug-a" owner_a
        in
        let* cookie_b, token_b, _ =
          open_form "project b" ~url ~slug:"phvv-slug-b" owner_b
        in
        let body_fields =
          fields ~name:"Phvv Shared Home" ~slug:"phvv-shared-home" ()
        in
        let* (response_a, body_a), (response_b, body_b) =
          Lwt.both
            (do_post ~url ~cookie:cookie_a ~target:(post_target "phvv-slug-a")
               ~token:token_a ~body_fields ())
            (do_post ~url ~cookie:cookie_b ~target:(post_target "phvv-slug-b")
               ~token:token_b ~body_fields ())
        in
        let a_won = status_of response_a = 303 in
        let ( winner, winner_body, winner_project, loser, loser_body,
              loser_project, loser_slug ) =
          if a_won then
            (response_a, body_a, project_a, response_b, body_b, project_b,
             "phvv-slug-b")
          else
            (response_b, body_b, project_b, response_a, body_a, project_a,
             "phvv-slug-a")
        in
        check_clean_redirect "winner" (settings_target "phvv-shared-home")
          winner winner_body;
        check_rerender "loser" ~status:409
          ~feedback:"That community address is already taken." ~slug:loser_slug
          loser loser_body;
        Alcotest.(check bool) "loser keeps its submission" true
          (contains loser_body "value='phvv-shared-home'");
        let* communities =
          find conn "communities" q_count_by_slug "phvv-shared-home"
        in
        Alcotest.(check int) "exactly one community" 1 communities;
        let* winner_relations =
          find conn "winner relations" Phrq.q_count_for_project winner_project
        in
        Alcotest.(check int) "winner has one relation" 1 winner_relations;
        let* loser_relations =
          find conn "loser relations" Phrq.q_count_for_project loser_project
        in
        Alcotest.(check int) "loser has no relation" 0 loser_relations;
        Lwt.return_unit)

  (* === destination authorization and draft privacy === *)

  let destination_case =
    db_case "POST provisioning: the new draft stays private to its creator \
             and out of public discovery" (fun ~url conn ->
        let* owner = insert_user conn "phvv_destowner" in
        let* stranger = insert_user conn "phvv_deststranger" in
        let* _inst, _project =
          make_project conn ~user:owner ~ext_id:951000013L ~slug:"phvv-dest"
            ~name:"Phvv Dest"
        in
        let* cookie, token, _ =
          open_form "creation" ~url ~slug:"phvv-dest" owner
        in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-dest") ~token
            ~body_fields:
              (fields ~name:"Phvv Dest Home" ~slug:"phvv-dest-home" ())
            ()
        in
        check_clean_redirect "provisioned" (settings_target "phvv-dest-home")
          response body;
        (* The creator: settings and the community page are both authorized,
           and the draft is not indexable. *)
        let* settings_response, settings_body =
          do_get ~url ~cookie ~target:(settings_target "phvv-dest-home") ()
        in
        Alcotest.(check int) "creator settings 200" 200
          (status_of settings_response);
        Alcotest.(check bool) "settings is the draft's own" true
          (contains settings_body "phvv-dest-home");
        let* page_response, page_body =
          do_get ~url ~cookie ~target:(community_target "phvv-dest-home") ()
        in
        Alcotest.(check int) "creator community page 200" 200
          (status_of page_response);
        Alcotest.(check bool) "the draft is noindex" true
          (contains page_body "content='noindex'");
        (* An unrelated authenticated user. *)
        let* stranger_cookie, _ = open_session "stranger" ~url stranger in
        let* response, body =
          do_get ~url ~cookie:stranger_cookie
            ~target:(community_target "phvv-dest-home") ()
        in
        check_community_unavailable "stranger community page" response body;
        Alcotest.(check bool) "stranger page carries no draft identity" false
          (contains body "phvv-dest-home");
        let* response, body =
          do_get ~url ~cookie:stranger_cookie
            ~target:(settings_target "phvv-dest-home") ()
        in
        Alcotest.(check int) "stranger settings refused" 403
          (status_of response);
        Alcotest.(check bool) "stranger sees no draft content" false
          (contains body "Phvv Dest Home");
        Alcotest.(check bool) "stranger sees no draft slug" false
          (contains body "phvv-dest-home");
        (* An anonymous visitor. *)
        as_anonymous ();
        let* response, body =
          do_get ~url ~target:(community_target "phvv-dest-home") ()
        in
        check_community_unavailable "anonymous community page" response body;
        Alcotest.(check bool) "anonymous page carries no draft identity" false
          (contains body "phvv-dest-home");
        let* response, body =
          do_get ~url ~target:(settings_target "phvv-dest-home") ()
        in
        Alcotest.(check bool) "anonymous settings never render the draft" true
          (status_of response = 302 || status_of response = 303);
        Alcotest.(check bool) "anonymous body carries no draft identity" false
          (contains body "Phvv Dest Home");
        (* Public discovery: the real search query cannot see it. *)
        let* found = Earde.Db.search_communities conn "Phvv Dest" 20 0 in
        (match found with
        | Ok rows ->
            Alcotest.(check int) "absent from public discovery" 0
              (List.length rows)
        | Error e -> Alcotest.failf "discovery query failed: %s" e);
        Lwt.return_unit)

  (* === the mutation rate limiter really wraps this route === *)

  let rate_limit_case =
    db_case "POST provisioning: the route carries the shared \
             authenticated-mutation rate limit" (fun ~url _conn ->
        let* cookie, token = open_session "rate limit" ~url 424243 in
        let target = post_target "phvv-ratelimit" in
        (* The project does not exist, so every allowed attempt is the
           generic 404 and nothing durable is ever created. *)
        let rec drive n =
          if n > 12 then
            Alcotest.fail "the limiter never blocked within 12 attempts"
          else
            let* response, body =
              do_post ~url ~cookie ~target ~token
                ~body_fields:(fields ~slug:"phvv-ratelimit-home" ())
                ()
            in
            if contains body "Too Many Attempts" then Lwt.return (n, response)
            else (
              Alcotest.(check int)
                (Printf.sprintf "attempt %d is the generic 404" n)
                404 (status_of response);
              drive (n + 1))
        in
        let* attempts, response = drive 1 in
        Alcotest.(check bool) "blocked only after several attempts" true
          (attempts > 1);
        Alcotest.(check int) "blocked page status" 200 (status_of response);
        Lwt.return_unit)

  (* === privacy sweep === *)

  let privacy_case =
    db_case "POST provisioning: no credential-shaped fixture reaches any \
             response, redirect, cookie, or the created draft"
      (fun ~url conn ->
        let* owner = insert_user conn "phvv_privowner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000001L ~slug:"phvv-priv"
            ~name:"Phvv Priv"
        in
        let* cookie, token, page =
          open_form "creation" ~url ~slug:"phvv-priv" owner
        in
        check_body_no_credentials "creation page" page;
        (* A rejected submission carrying every marker in fields the parser
           does not know. *)
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-priv") ~token
            ~body_fields:
              (List.map
                 (fun (_, marker) -> ("phvv_" ^ marker, marker))
                 credential_markers
              @ fields ())
            ()
        in
        Alcotest.(check int) "422" 422 (status_of response);
        check_no_credentials "rejected submission" response body;
        (* A successful submission: redirect, settings page, and the durable
           draft. *)
        let* token = mint_token "success" ~url ~cookie in
        let* response, body =
          do_post ~url ~cookie ~target:(post_target "phvv-priv") ~token
            ~body_fields:
              (fields ~name:"Phvv Priv Home" ~slug:"phvv-priv-home"
                 ~description:"Safe body." ())
            ()
        in
        check_clean_redirect "success" (settings_target "phvv-priv-home")
          response body;
        check_no_credentials "success redirect" response body;
        let* settings_response, settings_body =
          do_get ~url ~cookie ~target:(settings_target "phvv-priv-home") ()
        in
        check_no_credentials "settings page" settings_response settings_body;
        (* The intentionally supplied safe identity is what survives —
           the slug on the settings surface, the full identity durably. *)
        Alcotest.(check bool) "the supplied slug is present" true
          (contains settings_body "phvv-priv-home");
        let* _ =
          Phvs.check_provisioned_draft "privacy" conn ~actor:owner ~project
            ~slug:"phvv-priv-home" ~name:"Phvv Priv Home"
            ~description:"Safe body."
        in
        Lwt.return_unit)

  (* === the real browser contract ===

     A regression for the launch smoke-test blocker: the steward opened
     /projects/<slug>/community-home/new, filled it in, and submitted hours
     later. Dream's framework CSRF token is valid for one hour while
     sql_sessions keeps the login for two weeks, so the still-authenticated
     page posted an authentic but expired token and the handler answered a
     terminal generic 403 — no form, no explanation, no way back into the
     flow, and the typed values gone.

     Everything here goes through the markup the browser actually receives:
     the control names are read out of the rendered form rather than
     hard-coded, and the token is the one the page itself carries. *)

  (* Every control name the rendered creation form submits, in document
     order — the framework CSRF field Dream emits plus the page's own
     application fields. *)
  let form_control_names label ~slug html =
    let opening = Printf.sprintf "action='%s'" (post_target slug) in
    let form_start =
      match ps_index_of html opening 0 with
      | Some i -> i
      | None -> Alcotest.fail (label ^ ": the creation form is not rendered")
    in
    let form_end =
      match ps_index_of html "</form>" form_start with
      | Some i -> i
      | None -> Alcotest.fail (label ^ ": unterminated creation form")
    in
    let form = String.sub html form_start (form_end - form_start) in
    let rec scan from acc =
      match ps_index_of form "name=" from with
      | None -> List.rev acc
      | Some i ->
          let quote_at = i + String.length "name=" in
          if quote_at >= String.length form then List.rev acc
          else
            let quote = form.[quote_at] in
            let start = quote_at + 1 in
            (match String.index_from_opt form start quote with
            | None -> List.rev acc
            | Some e -> scan (e + 1) (String.sub form start (e - start) :: acc))
    in
    scan 0 []

  (* The navigation metadata a same-origin form POST really carries. *)
  let browser_headers =
    [ ("Sec-Fetch-Site", "same-origin");
      ("Sec-Fetch-Mode", "navigate");
      ("Referer", "https://earde.com" ^ get_target "phvv-browser")
    ]

  (* The authenticated-mutation rate limiter allows five attempts per IP and
     endpoint per minute, and the browser-contract case deliberately makes
     more than that: the limiter itself is covered by [rate_limit_case], so
     this one resets its window between phases rather than re-proving it. *)
  let q_clear_rate_limits =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DELETE FROM rate_limits WHERE endpoint LIKE '/projects/phvv-%'"

  let clear_rate_limit conn =
    let (module C : Caqti_lwt.CONNECTION) = conn in
    let* cleared = C.exec q_clear_rate_limits () in
    let* () = or_fail "clear rate limits" cleared in
    Lwt.return_unit

  let q_count_audit =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM project_home_audit_events WHERE project_id = $1"

  let q_count_notifs =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM notifications WHERE project_id = $1"

  let q_count_members_like =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_members m \
     JOIN communities c ON c.id = m.community_id WHERE c.slug LIKE $1"

  let q_count_mods_like =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_moderators m \
     JOIN communities c ON c.id = m.community_id WHERE c.slug LIKE $1"

  let q_count_sections_like =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT COUNT(*) FROM community_sections s \
     JOIN communities c ON c.id = s.community_id WHERE c.slug LIKE $1"

  let q_count_channels_like =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT COUNT(*) FROM channels ch \
     JOIN communities c ON c.id = ch.community_id WHERE c.slug LIKE $1"

  (* Nothing of a community home exists anywhere: not the community, not the
     relation, not the membership, role, section, channel, audit event, or
     notification a real provision would have committed together. *)
  let check_nothing_created label conn ~project =
    let* communities = find conn "communities" q_count_like "phvv-%" in
    Alcotest.(check int) (label ^ ": no community") 0 communities;
    let* relations = find conn "relations" q_active_relations project in
    Alcotest.(check int) (label ^ ": no relation") 0 relations;
    let* members = find conn "members" q_count_members_like "phvv-%" in
    Alcotest.(check int) (label ^ ": no membership") 0 members;
    let* mods = find conn "moderators" q_count_mods_like "phvv-%" in
    Alcotest.(check int) (label ^ ": no moderator") 0 mods;
    let* sections = find conn "sections" q_count_sections_like "phvv-%" in
    Alcotest.(check int) (label ^ ": no section") 0 sections;
    let* channels = find conn "channels" q_count_channels_like "phvv-%" in
    Alcotest.(check int) (label ^ ": no channel") 0 channels;
    let* audit = find conn "audit" q_count_audit project in
    Alcotest.(check int) (label ^ ": no audit event") 0 audit;
    let* notifs = find conn "notifications" q_count_notifs project in
    Alcotest.(check int) (label ^ ": no notification") 0 notifs;
    Lwt.return_unit

  let browser_contract_case =
    db_case "POST provisioning: the rendered form's own fields and token \
             redirect, a stale or forged token re-renders a usable form \
             without creating anything, and exactly one complete draft \
             results" (fun ~url conn ->
        let* owner = insert_user conn "phvv_browser" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:951000002L
            ~slug:"phvv-browser" ~name:"Phvv Browser"
        in
        let* cookie, page_token, page =
          open_form "browser" ~url ~slug:"phvv-browser" owner
        in

        (* --- 1. the page really is the contract the browser follows ---

           Its referrer policy must keep the real Origin on the POST it
           hosts: a "no-referrer" document would make the browser send
           Origin: null, which the same-origin gate rejects. *)
        let* page_response, _ =
          do_get ~url ~cookie ~target:(get_target "phvv-browser") ()
        in
        Alcotest.(check (option string))
          "the page keeps its own POST's Origin"
          (Some Earde.Request_origin.referrer_policy)
          (Dream.header page_response "Referrer-Policy");
        let names = form_control_names "browser" ~slug:"phvv-browser" page in
        Alcotest.(check (list string))
          "exactly the framework field and the three application fields"
          [ "dream.csrf"; "community_name"; "community_slug";
            "community_description"
          ]
          names;
        (* The submitted body is built from those names alone. *)
        let typed =
          [ ("community_name", "Phvv Browser Home");
            ("community_slug", "phvv-browser-home");
            ("community_description", "Private draft for local smoke testing.")
          ]
        in
        let body_fields =
          List.filter_map
            (fun name ->
              if String.equal name "dream.csrf" then None
              else
                match List.assoc_opt name typed with
                | Some value -> Some (name, value)
                | None -> Alcotest.failf "browser: unexpected control %s" name)
            names
        in
        let post ?origin ?omit_token ~token () =
          do_post ?origin ?omit_token ~extra_headers:browser_headers ~url
            ~cookie ~target:(post_target "phvv-browser") ~token ~body_fields ()
        in

        (* --- 2. the exact production failure: an authentic same-session
           token that outlived its one-hour validity --- *)
        let* expired = mint_expired_token "expired" ~url ~cookie in
        let* response, body = post ~token:expired () in
        check_rerender "expired token" ~status:403
          ~feedback:"This page had been open too long"
          ~slug:"phvv-browser" response body;
        check_no_credentials "expired token" response body;
        let* () = check_nothing_created "expired token" conn ~project in

        (* --- 3. a forged, absent, duplicated, or foreign-session token is
           refused exactly as hard, and still creates nothing --- *)
        let* response, body = post ~token:"not-a-token" () in
        check_rerender "forged token" ~status:403
          ~feedback:"This page had been open too long"
          ~slug:"phvv-browser" response body;
        let* response, body = post ~omit_token:true ~token:"" () in
        check_rerender "absent token" ~status:403
          ~feedback:"This page had been open too long"
          ~slug:"phvv-browser" response body;
        (* Another session's live token is not this session's. *)
        let* other_cookie, _ = open_session "other" ~url owner in
        let* foreign = mint_token "foreign" ~url ~cookie:other_cookie in
        as_user owner;
        let* response, body = post ~token:foreign () in
        check_rerender "foreign-session token" ~status:403
          ~feedback:"This page had been open too long"
          ~slug:"phvv-browser" response body;
        let* () = check_nothing_created "rejected tokens" conn ~project in

        (* --- 4. the origin gate is untouched: a cross-origin POST carrying
           the page's own live token is still the terminal 403, with no form
           and no fresh token handed out --- *)
        let* () = clear_rate_limit conn in
        let* response, body =
          post ~origin:(Some "https://evil.example") ~token:page_token ()
        in
        Alcotest.(check int) "cross-origin: 403" 403 (status_of response);
        Alcotest.(check bool) "cross-origin: no form" false
          (contains body "phv-form");
        Alcotest.(check bool) "cross-origin: no fresh token" false
          (contains body "name=\"dream.csrf\"");
        Alcotest.(check bool) "cross-origin: generic refusal" true
          (contains body "This request is not allowed.");
        Alcotest.(check bool) "cross-origin: origin never reflected" false
          (contains body "evil.example");
        let* () = check_nothing_created "cross-origin" conn ~project in

        (* --- 5. the steward recovers from the re-rendered page itself:
           its fresh token, the same typed values, one redirect --- *)
        let* () = clear_rate_limit conn in
        let* response, body = post ~token:expired () in
        let recovered = Pch.csrf_of_page "recovered" body in
        Alcotest.(check bool) "the re-render carries a different token" true
          (not (String.equal recovered expired));
        Alcotest.(check int) "the re-render is still a refusal" 403
          (status_of response);
        let* response, body = post ~token:recovered () in
        check_clean_redirect "recovered submission"
          (settings_target "phvv-browser-home") response body;

        (* --- 6. exactly one complete draft, and no second one --- *)
        let* _cid, _rid =
          Phvs.check_provisioned_draft "browser" conn ~actor:owner ~project
            ~slug:"phvv-browser-home" ~name:"Phvv Browser Home"
            ~description:"Private draft for local smoke testing."
        in
        let* communities = find conn "communities" q_count_like "phvv-%" in
        Alcotest.(check int) "exactly one community" 1 communities;
        let* relations = find conn "relations" q_active_relations project in
        Alcotest.(check int) "exactly one active relation" 1 relations;
        let* named = find conn "named" q_count_by_slug "phvv-browser-home" in
        Alcotest.(check int) "and it is the one just created" 1 named;
        Lwt.return_unit)

  let db_suite =
    [ success_case; browser_contract_case; parser_rejection_case;
      escaping_case; slug_conflict_case; active_home_case; replay_case;
      drift_case; inconsistent_case; storage_case; same_project_race_case;
      same_slug_race_case; destination_case; rate_limit_case; privacy_case
    ]
end

(* === Network-community publication form (Network_community_publication_form) ===
   The final setup submission of a provisioned network community: the exact
   four-field grammar, the publication vocabulary, and the delegation of the
   whole identity half to the frozen provisioning-form policy. Pure — no DB,
   no request, no session. *)

module Ncpf = Earde.Network_community_publication_form

let ncpf_err : Ncpf.error -> string = function
  | Ncpf.Invalid_form -> "Invalid_form"
  | Ncpf.Invalid_community_name -> "Invalid_community_name"
  | Ncpf.Invalid_community_slug -> "Invalid_community_slug"
  | Ncpf.Invalid_community_description -> "Invalid_community_description"
  | Ncpf.Invalid_publication_visibility -> "Invalid_publication_visibility"

let ncpf_case = go_case

let ncpf_vis : Ncpf.publication_visibility -> string = function
  | Ncpf.Public -> "public"
  | Ncpf.Unlisted -> "unlisted"

let ncpf_fields ?(name = "Ncpf Community") ?(slug = "ncpf-community")
    ?(description = "") ?(visibility = "public") () =
  [ ("community_name", name);
    ("community_slug", slug);
    ("community_description", description);
    ("publication_visibility", visibility)
  ]

let ncpf_ok label fields =
  match Ncpf.of_fields fields with
  | Ok parsed -> parsed
  | Error e -> Alcotest.failf "%s: rejected with %s" label (ncpf_err e)

let ncpf_expect label expected fields =
  match Ncpf.of_fields fields with
  | Ok _ -> Alcotest.failf "%s: expected %s, got Ok" label (ncpf_err expected)
  | Error e -> Alcotest.(check string) label (ncpf_err expected) (ncpf_err e)

(* Every ordering of a four-element list, so field-order independence is
   proven exhaustively rather than on a hand-picked pair. *)
let rec ncpf_permutations = function
  | [] -> [ [] ]
  | items ->
      List.concat_map
        (fun x ->
          let rest = List.filter (fun y -> y != x) items in
          List.map (fun p -> x :: p) (ncpf_permutations rest))
        items

let ncpf_field_names =
  [ "community_name"; "community_slug"; "community_description";
    "publication_visibility"
  ]

(* The four canonical values one accepted submission must expose, as one
   comparable signature. *)
let ncpf_signature parsed =
  String.concat "|"
    [ Ncpf.community_name parsed;
      Ncpf.community_slug parsed;
      (match Ncpf.community_description parsed with
      | None -> "<none>"
      | Some text -> text);
      ncpf_vis (Ncpf.publication_visibility parsed)
    ]

let ncpf_grammar_cases =
  [ ncpf_case "publication form: a valid Public submission keeps every \
               canonical value exactly" (fun () ->
        let parsed =
          ncpf_ok "public"
            (ncpf_fields ~name:"Ncpf Community" ~slug:"ncpf-community"
               ~description:"A durable description." ~visibility:"public" ())
        in
        Alcotest.(check string) "name" "Ncpf Community"
          (Ncpf.community_name parsed);
        Alcotest.(check string) "slug" "ncpf-community"
          (Ncpf.community_slug parsed);
        Alcotest.(check (option string)) "description"
          (Some "A durable description.") (Ncpf.community_description parsed);
        Alcotest.(check string) "visibility" "public"
          (ncpf_vis (Ncpf.publication_visibility parsed)))
  ; ncpf_case "publication form: a valid Unlisted submission differs only in \
               the publication choice" (fun () ->
        let parsed =
          ncpf_ok "unlisted" (ncpf_fields ~visibility:"unlisted" ())
        in
        Alcotest.(check string) "visibility" "unlisted"
          (ncpf_vis (Ncpf.publication_visibility parsed));
        Alcotest.(check string) "name unchanged" "Ncpf Community"
          (Ncpf.community_name parsed);
        Alcotest.(check string) "slug unchanged" "ncpf-community"
          (Ncpf.community_slug parsed);
        (* A structurally required but blank description collapses to None,
           never Some "". *)
        Alcotest.(check (option string)) "blank description" None
          (Ncpf.community_description parsed))
  ; ncpf_case "publication form: every field order yields byte-identical \
               values" (fun () ->
        let base =
          ncpf_fields ~name:"Ncpf Order" ~slug:"ncpf-order"
            ~description:"Order body." ~visibility:"unlisted" ()
        in
        let expected = ncpf_signature (ncpf_ok "canonical order" base) in
        let orders = ncpf_permutations base in
        Alcotest.(check int) "24 permutations" 24 (List.length orders);
        List.iter
          (fun fields ->
            let parsed = ncpf_ok "permuted" fields in
            Alcotest.(check string) "same canonical values" expected
              (ncpf_signature parsed))
          orders)
  ; ncpf_case "publication form: every missing field is the same payload-free \
               structural rejection" (fun () ->
        List.iter
          (fun dropped ->
            let fields =
              List.filter
                (fun (key, _) -> not (String.equal key dropped))
                (ncpf_fields ())
            in
            ncpf_expect ("missing " ^ dropped) Ncpf.Invalid_form fields)
          ncpf_field_names;
        ncpf_expect "empty field list" Ncpf.Invalid_form [])
  ; ncpf_case "publication form: every duplicated field is a structural \
               rejection, even when both copies are valid" (fun () ->
        List.iter
          (fun duplicated ->
            let extra =
              match duplicated with
              | "publication_visibility" -> (duplicated, "unlisted")
              | "community_slug" -> (duplicated, "ncpf-community")
              | _ -> (duplicated, "Ncpf Community")
            in
            ncpf_expect ("duplicate " ^ duplicated) Ncpf.Invalid_form
              (ncpf_fields () @ [ extra ]))
          ncpf_field_names)
  ; ncpf_case "publication form: unknown, case-variant, and padded field \
               names are structural rejections" (fun () ->
        List.iter
          (fun (key, value) ->
            ncpf_expect ("unknown " ^ String.escaped key) Ncpf.Invalid_form
              (ncpf_fields () @ [ (key, value) ]))
          [ ("community_id", "42"); ("actor_id", "7"); ("current_slug", "x");
            ("return_url", "/"); ("indexable", "true");
            ("discoverable", "true"); ("onboarding_state", "published")
          ];
        List.iter
          (fun key ->
            let fields =
              List.map
                (fun (k, v) ->
                  if String.equal k "community_name" then (key, v) else (k, v))
                (ncpf_fields ())
            in
            ncpf_expect ("variant " ^ String.escaped key) Ncpf.Invalid_form
              fields)
          [ "Community_name"; "COMMUNITY_NAME"; " community_name";
            "community_name "; "community_name\t"; "communityname"
          ])
  ; ncpf_case "publication form: a dream.csrf field reaching the pure parser \
               is a structural rejection, never silently filtered" (fun () ->
        ncpf_expect "framework field" Ncpf.Invalid_form
          (("dream.csrf", "opaque-token") :: ncpf_fields ());
        ncpf_expect "framework field last" Ncpf.Invalid_form
          (ncpf_fields () @ [ ("dream.csrf", "opaque-token") ]))
  ; ncpf_case "publication form: structure is decided before semantics, so a \
               doubly invalid submission never names a field" (fun () ->
        (* Both the field set and the name are invalid; only the structural
           answer travels. *)
        ncpf_expect "unknown field plus blank name" Ncpf.Invalid_form
          (ncpf_fields ~name:"   " ~visibility:"private" ()
          @ [ ("surprise", "1") ]);
        ncpf_expect "missing field plus bad slug" Ncpf.Invalid_form
          [ ("community_name", ""); ("community_slug", "Not A Slug") ])
  ]

let ncpf_publication_cases =
  [ ncpf_case "publication form: exactly public and unlisted are accepted"
      (fun () ->
        Alcotest.(check string) "public" "public"
          (ncpf_vis
             (Ncpf.publication_visibility
                (ncpf_ok "public" (ncpf_fields ~visibility:"public" ()))));
        Alcotest.(check string) "unlisted" "unlisted"
          (ncpf_vis
             (Ncpf.publication_visibility
                (ncpf_ok "unlisted" (ncpf_fields ~visibility:"unlisted" ())))))
  ; ncpf_case "publication form: private is rejected like any other unknown \
               value — a network community has no fully private published \
               shape" (fun () ->
        List.iter
          (fun value ->
            ncpf_expect ("value " ^ String.escaped value)
              Ncpf.Invalid_publication_visibility
              (ncpf_fields ~visibility:value ()))
          [ "private"; "Private"; "PRIVATE"; "secret"; "hidden" ])
  ; ncpf_case "publication form: nothing is trimmed, case-folded, or repaired \
               on the publication value" (fun () ->
        List.iter
          (fun value ->
            ncpf_expect ("value " ^ String.escaped value)
              Ncpf.Invalid_publication_visibility
              (ncpf_fields ~visibility:value ()))
          [ ""; " "; " public"; "public "; "\tpublic"; "public\n"; "Public";
            "PUBLIC"; "pUbLiC"; "Unlisted"; "UNLISTED"; " unlisted";
            "unlisted "; "public,unlisted"; "published"; "listed"; "0"; "1";
            "true"
          ])
  ; ncpf_case "publication form: identity is validated before the publication \
               choice, and each field maps to its own error" (fun () ->
        (* Both halves invalid: the identity error is the one that travels. *)
        ncpf_expect "bad name wins over bad visibility"
          Ncpf.Invalid_community_name
          (ncpf_fields ~name:"" ~visibility:"private" ());
        ncpf_expect "bad slug wins over bad visibility"
          Ncpf.Invalid_community_slug
          (ncpf_fields ~slug:"Not A Slug" ~visibility:"private" ());
        ncpf_expect "bad description wins over bad visibility"
          Ncpf.Invalid_community_description
          (ncpf_fields ~description:"body\x01here" ~visibility:"private" ());
        (* A valid identity with a bad choice reaches the publication
           error. *)
        ncpf_expect "valid identity, bad visibility"
          Ncpf.Invalid_publication_visibility
          (ncpf_fields ~visibility:"private" ()))
  ]

(* Cross-module parity: the identity half of this form is exactly the frozen
   provisioning policy — same verdicts, same canonical bytes, same error
   constructor — so a community created by provisioning and edited here can
   never drift into a second grammar. *)
let ncpf_identity_probes =
  [ ("plain", "Ncpf Community", "ncpf-community", "");
    ("trimmed name", "  Ncpf Community  ", "ncpf-community", "");
    ("name at the 120-scalar limit", phvf_repeat phvf_scalar 120, "ncpf-a", "");
    ("name one scalar over", phvf_repeat phvf_scalar 121, "ncpf-a", "");
    ("blank name", "   ", "ncpf-a", "");
    ("control in name", "Ncpf\x01Name", "ncpf-a", "");
    ("invalid utf-8 name", "Ncpf\xff", "ncpf-a", "");
    ("single-character slug", "Ncpf", "a", "");
    ("slug at 80 bytes", "Ncpf", String.make 80 'a', "");
    ("slug at 81 bytes", "Ncpf", String.make 81 'a', "");
    ("uppercase slug", "Ncpf", "Ncpf-Community", "");
    ("padded slug", "Ncpf", " ncpf-community", "");
    ("trailing hyphen slug", "Ncpf", "ncpf-", "");
    ("double hyphen slug", "Ncpf", "ncpf--community", "");
    ("underscore slug", "Ncpf", "ncpf_community", "");
    ("slash slug", "Ncpf", "ncpf/community", "");
    ("empty slug", "Ncpf", "", "");
    ("multiline description", "Ncpf", "ncpf-a", "one\r\ntwo\rthree\nfour");
    ("tabbed description", "Ncpf", "ncpf-a", "col\tumn");
    ("whitespace-only description", "Ncpf", "ncpf-a", "  \n\t ");
    ("description at 2000 scalars", "Ncpf", "ncpf-a",
     phvf_repeat phvf_scalar 2000);
    ("description one scalar over", "Ncpf", "ncpf-a",
     phvf_repeat phvf_scalar 2001);
    ("control in description", "Ncpf", "ncpf-a", "body\x01here");
    ("invalid utf-8 description", "Ncpf", "ncpf-a", "body\xff")
  ]

let ncpf_parity_cases =
  [ ncpf_case "publication form: every identity verdict matches \
               Project_home_provisioning_form exactly" (fun () ->
        List.iter
          (fun (label, name, slug, description) ->
            let mine =
              Ncpf.of_fields (ncpf_fields ~name ~slug ~description ())
            in
            let frozen = Phvf.of_fields (phvf_fields ~name ~slug ~description ()) in
            match (mine, frozen) with
            | Ok a, Ok b ->
                Alcotest.(check string)
                  (label ^ ": name")
                  (Phvf.community_name b) (Ncpf.community_name a);
                Alcotest.(check string)
                  (label ^ ": slug")
                  (Phvf.community_slug b) (Ncpf.community_slug a);
                Alcotest.(check (option string))
                  (label ^ ": description")
                  (Phvf.community_description b) (Ncpf.community_description a)
            | Error Ncpf.Invalid_community_name,
              Error Phvf.Invalid_community_name
            | Error Ncpf.Invalid_community_slug,
              Error Phvf.Invalid_community_slug
            | Error Ncpf.Invalid_community_description,
              Error Phvf.Invalid_community_description ->
                ()
            | Error a, Error b ->
                Alcotest.failf "%s: error mismatch %s vs %s" label
                  (ncpf_err a) (phvf_err b)
            | Ok _, Error b ->
                Alcotest.failf "%s: accepted here, %s there" label (phvf_err b)
            | Error a, Ok _ ->
                Alcotest.failf "%s: %s here, accepted there" label (ncpf_err a))
          ncpf_identity_probes)
  ; ncpf_case "publication form: an accepted identity is byte-identical under \
               both publication choices" (fun () ->
        List.iter
          (fun (label, name, slug, description) ->
            match Ncpf.of_fields (ncpf_fields ~name ~slug ~description ()) with
            | Error _ -> ()
            | Ok public ->
                let unlisted =
                  ncpf_ok (label ^ " unlisted")
                    (ncpf_fields ~name ~slug ~description
                       ~visibility:"unlisted" ())
                in
                Alcotest.(check string)
                  (label ^ ": name")
                  (Ncpf.community_name public) (Ncpf.community_name unlisted);
                Alcotest.(check string)
                  (label ^ ": slug")
                  (Ncpf.community_slug public) (Ncpf.community_slug unlisted);
                Alcotest.(check (option string))
                  (label ^ ": description")
                  (Ncpf.community_description public)
                  (Ncpf.community_description unlisted))
          ncpf_identity_probes)
  ; ncpf_case "publication form: accepted values are preserved byte-exactly, \
               never lowercased, normalized, or truncated" (fun () ->
        let parsed =
          ncpf_ok "preservation"
            (ncpf_fields ~name:"  Ncpf MiXeD Ünïcode  " ~slug:"ncpf-a1-b2"
               ~description:"  line one\r\nline two\ttabbed  " ())
        in
        Alcotest.(check string) "name outer-trimmed only" "Ncpf MiXeD Ünïcode"
          (Ncpf.community_name parsed);
        Alcotest.(check string) "slug byte-identical" "ncpf-a1-b2"
          (Ncpf.community_slug parsed);
        Alcotest.(check (option string)) "description normalized to LF"
          (Some "line one\nline two\ttabbed")
          (Ncpf.community_description parsed))
  ]

(* === Network-community publication page (Network_community_publication_pages) ===
   Pure rendering of the review-and-publish surface: heading and draft copy,
   the two publication choices and the absence of a private one, the exact
   one-form contract, defensive degradation, escaping, and every feedback
   variant. DB-free. *)

module Ncpp = Earde.Network_community_publication_pages

let ncpp_case = go_case

let ncpp_project ?(name = "Ncpp Project") ?(slug = "ncpp-project")
    ?(login = "ncpp-owner") ?(kind = Pi.Project) () : Ncpp.project =
  { Ncpp.name; slug; namespace_login = login; kind }

let ncpp_community ?(name = "Ncpp Home") ?(slug = "ncpp-home") ?description () :
    Ncpp.community =
  { Ncpp.name; slug; description }

let ncpp_values ?(name = "Ncpp Home") ?(slug = "ncpp-home") ?(description = "")
    ?(visibility = "public") () : Ncpp.form_values =
  { Ncpp.community_name = name;
    community_slug = slug;
    community_description = description;
    publication_visibility = visibility
  }

(* Assertions run over the feature fragment, not the whole page: the shared
   shell owns its own forms and chrome. *)
let ncpp_render ?request ?(community = ncpp_community ())
    ?(project = ncpp_project ()) ?(values = ncpp_values ()) ?feedback () =
  ps_fragment
    (Ncpp.network_community_publication_page ?request ~community ~project
       ~values ~feedback ())

let ncpp_whole ?request ?(community = ncpp_community ())
    ?(project = ncpp_project ()) ?(values = ncpp_values ()) ?feedback () =
  Ncpp.network_community_publication_page ?request ~community ~project ~values
    ~feedback ()

(* A live request under a secret + sessions pipeline, so the framework CSRF
   field can be emitted; no SQL is touched. *)
let ncpp_live ?community ?project ?values ?feedback () =
  let captured = ref None in
  let pipeline =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    captured := Some (ncpp_render ~request:req ?community ?project ?values ?feedback ());
    Dream.html ""
  in
  ignore
    (Lwt_main.run
       (pipeline (Dream.request ~method_:`GET ~target:"/c/ncpp-home/setup" "")));
  match !captured with
  | Some html -> html
  | None -> Alcotest.fail "publication renderer did not run"

let ncpp_action = "action='/c/ncpp-home/publish'"

let ncpp_copy_cases =
  [ ncpp_case "publication page: heading and the supporting review copy"
      (fun () ->
        let html = ncpp_render () in
        ps_must html "Complete setup and publish";
        ps_must html
          "Review the community identity and choose how people can discover \
           it.")
  ; ncpp_case "publication page: the draft state and the separateness of \
               publication are stated plainly" (fun () ->
        let html = ncpp_render () in
        ps_must html "still a private setup draft";
        ps_must html "Only people authorized for setup can reach it.";
        ps_must html "Publishing is a separate, explicit action.";
        ps_must html "Nothing is published until you submit this form.")
  ; ncpp_case "publication page: Public and Unlisted are each described \
               exactly, and a fully private publication is offered nowhere"
      (fun () ->
        let html = ncpp_render () in
        ps_must html
          "reachable by anyone, listed in Earde&#39;s own discovery surfaces, \
           and open to search-engine indexing";
        ps_must html
          "reachable by anyone with the direct URL, but kept out of \
           Earde&#39;s discovery surfaces and marked <code>noindex</code>";
        ps_must html "It cannot be published as a fully private community.";
        List.iter (ps_must_not html)
          [ "value='private'"; "value=\"private\""; ">Private<";
            "publish as Private"; "Public, Unlisted, or Private";
            "fully private community.</li></ul><li>"
          ])
  ; ncpp_case "publication page: private rooms remain possible under either \
               choice, and publication grants no new permission" (fun () ->
        let html = ncpp_render () in
        ps_must html
          "Private rooms and restricted sections can still exist inside it \
           under either choice";
        ps_must html
          "Publishing does not change who moderates or administers anything.";
        ps_must html
          "Project stewards gain no permission beyond the durable roles they \
           already hold.")
  ; ncpp_case "publication page: the connected project reads factually, with \
               no officiality or endorsement language" (fun () ->
        let html =
          ncpp_render
            ~project:
              (ncpp_project ~name:"Ncpp Alpha" ~kind:Pi.Ecosystem
                 ~login:"ncpp-org" ())
            ()
        in
        ps_must html "Ncpp Alpha";
        ps_must html "Ecosystem";
        ps_must html "ncpp-org";
        ps_must html "Connected and verified through GitHub.";
        List.iter (ps_must_not html)
          [ "Official"; "official"; "GitHub-approved"; "GitHub-endorsed";
            "endorsed"; "approved by GitHub"; "sponsored"
          ])
  ; ncpp_case "publication page: every project kind has its own non-endorsing \
               label" (fun () ->
        List.iter
          (fun (kind, label) ->
            let html = ncpp_render ~project:(ncpp_project ~kind ()) () in
            ps_must html label)
          [ (Pi.Project, "Project"); (Pi.Organization, "GitHub organization");
            (Pi.Ecosystem, "Ecosystem"); (Pi.Foundation, "Foundation");
            (Pi.Working_group, "Working group");
            (Pi.Other, "Other open-source initiative")
          ])
  ]

let ncpp_form_cases =
  [ ncpp_case "publication page: exactly one form, with the exact method and \
               structurally built action" (fun () ->
        let html = ncpp_render () in
        Alcotest.(check int) "one form" 1 (ps_count html "<form");
        Alcotest.(check int) "one closing form" 1 (ps_count html "</form>");
        ps_must html "method='POST'";
        ps_must html ncpp_action;
        (* The action is derived from the community slug alone: a different
           draft slug moves it, nothing else does. *)
        ps_must
          (ncpp_render ~community:(ncpp_community ~slug:"ncpp-other" ()) ())
          "action='/c/ncpp-other/publish'")
  ; ncpp_case "publication page: exactly the four application controls, and \
               no hidden identifier, current slug, return URL, or lifecycle \
               flag" (fun () ->
        let html = ncpp_render () in
        let region = ps_form_region html in
        List.iter (ps_must region)
          [ "name='community_name'"; "name='community_slug'";
            "name='community_description'"; "name='publication_visibility'"
          ];
        Alcotest.(check int) "one name control" 1
          (ps_count region "name='community_name'");
        Alcotest.(check int) "one slug control" 1
          (ps_count region "name='community_slug'");
        Alcotest.(check int) "one description control" 1
          (ps_count region "name='community_description'");
        (* Pure rendering emits no framework field, so the only inputs are
           the application controls: two radios plus two text inputs. *)
        Alcotest.(check int) "four inputs" 4
          (List.length (ps_input_tags region));
        List.iter (ps_must_not region)
          [ "type='hidden'"; "type=\"hidden\""; "name='community_id'";
            "name='project_id'"; "name='relation_id'"; "name='actor_id'";
            "name='user_id'"; "name='current_slug'"; "name='return_url'";
            "name='redirect_to'"; "name='onboarding_state'";
            "name='indexable'"; "name='discoverable'"; "name='visibility'"
          ])
  ; ncpp_case "publication page: exactly two publication radio values, and a \
               nameless submit with no confirmation script" (fun () ->
        let region = ps_form_region (ncpp_render ()) in
        Alcotest.(check int) "two radios" 2
          (ps_count region "type='radio'");
        Alcotest.(check int) "two publication controls" 2
          (ps_count region "name='publication_visibility'");
        Alcotest.(check int) "one public value" 1
          (ps_count region "value='public'");
        Alcotest.(check int) "one unlisted value" 1
          (ps_count region "value='unlisted'");
        ps_must region "<button type='submit'";
        ps_must region ">Publish community</button>";
        List.iter (ps_must_not region)
          [ "<button name"; "onsubmit"; "confirmModal"; "onclick" ])
  ; ncpp_case "publication page: public is the default only when no valid \
               explicit choice is present" (fun () ->
        (* No explicit choice: public preselected. *)
        let default = ps_form_region (ncpp_render ~values:(ncpp_values ~visibility:"" ()) ()) in
        ps_must default "value='public' checked";
        ps_must_not default "value='unlisted' checked";
        (* An explicit unlisted choice survives the round trip. *)
        let unlisted =
          ps_form_region
            (ncpp_render ~values:(ncpp_values ~visibility:"unlisted" ()) ())
        in
        ps_must unlisted "value='unlisted' checked";
        ps_must_not unlisted "value='public' checked";
        (* An explicit public choice stays public. *)
        let public =
          ps_form_region
            (ncpp_render ~values:(ncpp_values ~visibility:"public" ()) ())
        in
        ps_must public "value='public' checked")
  ; ncpp_case "publication page: an invalid submitted publication value \
               selects neither option rather than defaulting to the more \
               exposed one" (fun () ->
        List.iter
          (fun value ->
            let region =
              ps_form_region
                (ncpp_render ~values:(ncpp_values ~visibility:value ()) ())
            in
            Alcotest.(check int)
              ("no preselection for " ^ String.escaped value)
              0 (ps_count region "checked"))
          [ "private"; "Public"; " public"; "unlisted "; "PRIVATE"; "listed" ];
          (* The empty value is "no choice yet", not a rejected one, and is
             the single documented case that falls back to public. *)
          let empty =
            ps_form_region (ncpp_render ~values:(ncpp_values ~visibility:"" ()) ())
          in
          Alcotest.(check int) "empty value defaults to public" 1
            (ps_count empty "value='public' checked"))
  ; ncpp_case "publication page: the framework CSRF field appears only with a \
               live request, and only inside the form" (fun () ->
        let pure = ncpp_render () in
        ps_must_not pure "dream.csrf";
        let live = ncpp_live () in
        let region = ps_form_region live in
        let tags = List.filter ps_is_csrf_input (ps_input_tags region) in
        Alcotest.(check int) "exactly one framework field" 1
          (List.length tags);
        (* Removing it leaves exactly the four application controls. *)
        Alcotest.(check int) "no other framework field in the page" 1
          (ps_count live ps_csrf_input_prefix))
  ; ncpp_case "publication page: the controls prefill from the supplied \
               values, with an absent description as an empty textarea"
      (fun () ->
        let html =
          ncpp_render
            ~values:
              (ncpp_values ~name:"Ncpp Current" ~slug:"ncpp-current"
                 ~description:"Current body." ())
            ()
        in
        ps_must html "value='Ncpp Current'";
        ps_must html "value='ncpp-current'";
        ps_must html "Current body.";
        let blank = ncpp_render ~values:(ncpp_values ~description:"" ()) () in
        ps_must blank "<textarea name='community_description' maxlength='2000' rows='6'>";
        ps_must_not blank ">None<")
  ; ncpp_case "publication page: control limits mirror the server-side policy"
      (fun () ->
        let region = ps_form_region (ncpp_render ()) in
        ps_must region "maxlength='120'";
        ps_must region "maxlength='80'";
        ps_must region "maxlength='2000'")
  ]

let ncpp_defensive_cases =
  [ ncpp_case "publication page: every caller-controlled value is escaped, \
               and a description is never treated as markup" (fun () ->
        let html =
          ncpp_render
            ~community:
              (ncpp_community ~name:"<b>Name</b>"
                 ~description:"**bold** <i>x</i>" ())
            ~project:
              (ncpp_project ~name:"<script>alert(1)</script>"
                 ~login:"o'wner\"x" ())
            ~values:
              (ncpp_values ~name:"a'\"<>&" ~slug:"b'\"<>&"
                 ~description:"**bold** <i>x</i>" ())
            ()
        in
        List.iter (ps_must_not html)
          [ "<script>alert(1)</script>"; "<b>Name</b>"; "<i>x</i>" ];
        ps_must html "&lt;script&gt;alert(1)&lt;/script&gt;";
        ps_must html "**bold** &lt;i&gt;x&lt;/i&gt;")
  ; ncpp_case "publication page: a draft slug outside the canonical network \
               grammar suppresses the whole form rather than emitting an \
               unusable action" (fun () ->
        List.iter
          (fun slug ->
            let html = ncpp_render ~community:(ncpp_community ~slug ()) () in
            Alcotest.(check int)
              ("no form for " ^ String.escaped slug)
              0 (ps_count html "<form");
            ps_must_not html "/publish";
            (* The explanatory copy still renders — the page never raises. *)
            ps_must html "Complete setup and publish")
          [ ""; " "; "Ncpp-Home"; "ncpp home"; "ncpp/home"; "ncpp-";
            "-ncpp"; "ncpp--home"; "ncpp_home"; "ncpp.home"; "ncpp\x01home";
            String.make 81 'a'
          ])
  ; ncpp_case "publication page: no project-derived link exists under any \
               project slug, malformed or not" (fun () ->
        List.iter
          (fun slug ->
            let html = ncpp_render ~project:(ncpp_project ~slug ()) () in
            List.iter (ps_must_not html)
              [ "href='/projects/"; "href=\"/projects/"; "/community-home";
                "/request-home"
              ])
          [ "ncpp-project"; ""; "Ncpp Project"; "ncpp/project"; "ncpp--x" ])
  ; ncpp_case "publication page: no script, inline style, event handler, or \
               refresh redirect" (fun () ->
        let html = ncpp_whole () in
        let feature = ncpp_render () in
        List.iter (ps_must_not feature)
          [ "<script"; "javascript:"; "style='"; "style=\""; "onclick";
            "onsubmit"; "onload"; "onerror"; "http-equiv"
          ];
        (* noindex is a page-level property, so it is asserted on the whole
           document rather than the fragment. *)
        ps_must html "content='noindex'")
  ; ncpp_case "publication page: no identifier of any kind is renderable — \
               the models carry none" (fun () ->
        let html = ps_without_csrf_inputs (ncpp_live ()) in
        List.iter (ps_must_not html)
          [ "community_id"; "project_id"; "relation_id"; "steward_id";
            "installation_id"; "membership_id"
          ])
  ; ncpp_case "publication page: credential-shaped fixtures never reach the \
               rendered page" (fun () ->
        let html =
          ps_without_csrf_inputs
            (ncpp_live
               ~project:
                 (ncpp_project ~name:"gho_NCPP_ACCESS_TOKEN"
                    ~login:"NCPP_CLIENT_SECRET" ())
               ())
        in
        (* The project identity is rendered, so the assertion is that the
           page adds nothing of its own: only the two supplied strings may
           appear, and no token-shaped value the page could have invented. *)
        List.iter (ps_must_not html)
          [ "ghr_"; "ghu_"; "code="; "state="; "code_verifier";
            "client_secret="; "access_token"
          ])
  ]

let ncpp_feedback_cases =
  [ ncpp_case "publication page: no feedback renders no alert" (fun () ->
        ps_must_not (ncpp_render ()) "ncp-alert")
  ; ncpp_case "publication page: every feedback variant renders its own \
               generic message and never a submitted value" (fun () ->
        List.iter
          (fun (feedback, needle) ->
            let html =
