            ~current:"ncps-vf1-home" ~expect_slug:"ncps-vf1-hub"
            ~expect_visibility:Ncpf.Public
            (publication ~slug:"ncps-vf1-hub" ())
        in
        let* project2, _, _ =
          make_draft conn ~user:owner ~ext_id:954000009L
            ~project_slug:"ncps-vf2" ~slug:"ncps-vf2-home"
        in
        let* () = exec conn "revoked" q_set_verification (project2, "revoked")
        in
        let* _ =
          publish_ok "revoked project" conn ~actor:owner
            ~current:"ncps-vf2-home" ~expect_slug:"ncps-vf2-hub"
            ~expect_visibility:Ncpf.Public
            (publication ~slug:"ncps-vf2-hub" ())
        in
        Lwt.return_unit)

  (* === draft corruption === *)

  (* Durable corruption defenses that cannot be produced without relaxing
     production constraints stay defensive and undriven here:
     communities.visibility and onboarding_state off-enum values,
     community_projects.status/relation_type off-enum values, a second
     active home for one project (partial unique index), and non-positive
     ids (sequences). The lifecycle and identity shapes below are now
     constraint-protected too, so they run with the matching scoped CHECK
     dropped through Nclc_relax / Ncid_relax and restored under
     Lwt.finalize once the row is normalized again. *)

  let shell_corruption_case =
    db_case
      "publish: a missing or malformed shell, membership, moderation, or \
       relation is refused as corruption" (fun ~url:_ conn ->
        let* owner = insert_user conn "ncps_owner" in
        let* admin = insert_user conn "ncps_admin" in
        let* () = exec conn "admin flag" q_set_admin (admin, true) in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:954000010L
            ~project_slug:"ncps-cor" ~slug:"ncps-cor-home"
        in
        let value = publication ~slug:"ncps-cor-hub" () in
        (* The durable-admin actor keeps authorization satisfied, so each
           probe reaches the complete-draft validation it targets. *)
        let expect label =
          let* () =
            publish_expect label St.Inconsistent_data conn ~actor:admin
              ~current:"ncps-cor-home" value
          in
          let* n = find conn (label ^ ": no hub") q_count_by_slug
                     "ncps-cor-hub" in
          Alcotest.(check int) (label ^ ": no partial publication") 0 n;
          Lwt.return_unit
        in
        (* Missing General section. *)
        let* () = exec conn "drop sections" q_delete_sections cid in
        let* () = expect "missing General section" in
        let* () = exec conn "restore section" q_insert_general_section cid in
        (* Missing (archived) general channel. *)
        let* () = exec conn "archive channels" q_archive_channels cid in
        let* () = expect "missing general channel" in
        let* () = exec conn "unarchive channels" q_unarchive_channels cid in
        (* No top moderator at all. *)
        let* () = exec conn "drop moderators" q_delete_moderators cid in
        let* () = expect "no top moderator" in
        let* () =
          exec conn "restore top mod" q_insert_moderator
            (owner, cid, "top_mod")
        in
        (* No member at all. *)
        let* () = exec conn "drop members" q_delete_members cid in
        let* () = expect "no member" in
        let* () = exec conn "restore member" q_insert_member (owner, cid) in
        (* Absent accepted relation. *)
        let* () = exec conn "purge audit" q_purge_audit cid in
        let* () = exec conn "drop relations" q_delete_relations cid in
        let* () = expect "absent accepted relation" in
        let* () =
          exec conn "restore relation" q_insert_provisioned_relation
            (project, cid)
        in
        (* Non-provisioned accepted relation shape: a fabricated
           requester. *)
        let* relation_ids = collect conn "relation ids" Phvs.q_relation_ids
                              project in
        let* rid2 =
          match relation_ids with
          | [ r ] -> Lwt.return r
          | _ -> Alcotest.fail "expected one restored relation"
        in
        let* () =
          exec conn "fabricate requester" q_set_relation_requester
            (rid2, Some owner)
        in
        let* () = expect "non-provisioned accepted relation" in
        let* () =
          exec conn "clear requester" q_set_relation_requester (rid2, None)
        in
        (* Contradictory active relation state: a pending home relation of
           another project targeting this community. *)
        let* _, project2, _rid3 =
          let* _inst, p2 =
            make_project conn ~user:owner ~ext_id:954000011L
              ~slug:"ncps-cor2"
          in
          Lwt.return (0, p2, 0L)
        in
        let* () =
          exec conn "pending intruder" q_insert_pending_relation
            (project2, cid)
        in
        let* () = expect "pending relation on the community" in
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* pending_ids = collect conn "pending ids" Phvs.q_relation_ids
                             project2 in
        let* () =
          Lwt_list.iter_s
            (fun id -> exec conn "drop intruder" q_delete_relation_by_id id)
            pending_ids
        in
        (* A second accepted home from another project: the candidate
           resolution itself must refuse the duplicate. *)
        let* () =
          exec conn "second accepted" q_insert_provisioned_relation
            (project2, cid)
        in
        let* () = expect "second accepted home on the community" in
        let* accepted_ids = collect conn "accepted ids" Phvs.q_relation_ids
                              project2 in
        let* () =
          Lwt_list.iter_s
            (fun id -> exec conn "drop second" q_delete_relation_by_id id)
            accepted_ids
        in
        ignore rid;
        (* With every probe repaired the same inputs succeed — the
           refusals above were the corruption, not the store. *)
        let* _ =
          publish_ok "clean run after probes" conn ~actor:admin
            ~current:"ncps-cor-home" ~expect_slug:"ncps-cor-hub"
            ~expect_visibility:Ncpf.Public value
        in
        Lwt.return_unit)

  let lifecycle_corruption_case =
    db_case
      "publish: constraint-protected lifecycle and identity corruption is \
       refused" (fun ~url:_ conn ->
        let* owner = insert_user conn "ncps_owner" in
        let* _project, cid, _rid =
          make_draft conn ~user:owner ~ext_id:954000012L
            ~project_slug:"ncps-lcc" ~slug:"ncps-lcc-home"
        in
        let value = publication ~slug:"ncps-lcc-hub" () in
        let expect label current =
          let* () =
            publish_expect label St.Inconsistent_data conn ~actor:owner
              ~current value
          in
          let* n = find conn (label ^ ": no hub") q_count_by_slug
                     "ncps-lcc-hub" in
          Alcotest.(check int) (label ^ ": no partial publication") 0 n;
          Lwt.return_unit
        in
        (* Lifecycle shapes the new CHECK forbids: producible only with
           the constraint dropped for the length of the probe. *)
        let* () = Nclc_relax.drop conn in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = exec conn "public draft" q_set_visibility
                          (cid, "public") in
              let* () = expect "public draft" "ncps-lcc-home" in
              let* () = exec conn "back private" q_set_visibility
                          (cid, "private") in
              let* () = exec conn "leaking draft" q_set_indexable (cid, true)
              in
              let* () = expect "indexable draft" "ncps-lcc-home" in
              exec conn "back dark" q_set_indexable (cid, false))
            (fun () ->
              (* The row is a valid private draft again before the
                 constraint returns, validated. *)
              let* () = exec conn "normalize visibility" q_set_visibility
                          (cid, "private") in
              let* () = exec conn "normalize indexable" q_set_indexable
                          (cid, false) in
              Nclc_relax.restore conn)
        in
        (* Identity shapes the scoped identity CHECKs forbid. *)
        let* () = Ncid_relax.drop conn in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () =
                exec conn "control name" q_set_name
                  (cid, "Ncps\x01Corrupt")
              in
              let* () = expect "control byte in name" "ncps-lcc-home" in
              let* () = exec conn "restore name" q_set_name
                          (cid, "Ncps Community Home") in
              let* () =
                exec conn "noncanonical slug" q_set_slug (cid, "Ncps-Upper")
              in
              let* () = expect "noncanonical stored slug" "Ncps-Upper" in
              exec conn "restore slug" q_set_slug (cid, "ncps-lcc-home"))
            (fun () ->
              let* () =
                exec conn "recanonicalize" Ncid_relax.q_recanonicalize
                  (cid, "ncps-lcc-home", "Ncps Community Home")
              in
              Ncid_relax.restore conn)
        in
        (* The uncorrupted draft still publishes. *)
        let* _ =
          publish_ok "clean run after corruption" conn ~actor:owner
            ~current:"ncps-lcc-home" ~expect_slug:"ncps-lcc-hub"
            ~expect_visibility:Ncpf.Public value
        in
        Lwt.return_unit)

  (* === slug conflicts === *)

  let slug_conflict_case =
    db_case
      "publish: legacy, draft, and published holders of the requested slug \
       all win, leaving the loser byte-identical" (fun ~url:_ conn ->
        let* owner = insert_user conn "ncps_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:954000013L
            ~project_slug:"ncps-cf" ~slug:"ncps-cf-home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let probe label taken =
          let* holder_id = find conn (label ^ ": holder id") q_community_id
                             taken in
          let* holder_before = find conn (label ^ ": holder sig")
                                 q_community_sig holder_id in
          let* () =
            publish_expect label St.Community_slug_unavailable conn
              ~actor:owner ~current:"ncps-cf-home"
              (publication ~slug:taken ())
          in
          let* holder_after = find conn (label ^ ": holder sig after")
                                q_community_sig holder_id in
          Alcotest.(check string) (label ^ ": holder unchanged")
            holder_before holder_after;
          let* n = find conn (label ^ ": one owner") q_count_by_slug taken
          in
          Alcotest.(check int) (label ^ ": exactly one row keeps the slug")
            1 n;
          check_unchanged label conn ~cid ~project ~rid before
        in
        (* A legacy community. *)
        let* _legacy =
          insert_community ~network:false conn "ncps-taken-legacy"
        in
        let* () = probe "legacy holder" "ncps-taken-legacy" in
        (* Another network draft under its own current slug. *)
        let* _, _, _ =
          make_draft conn ~user:owner ~ext_id:954000014L
            ~project_slug:"ncps-cf2" ~slug:"ncps-cf2-home"
        in
        let* () = probe "draft holder" "ncps-cf2-home" in
        (* A published network community. *)
        let* _ =
          publish_ok "publish the second draft" conn ~actor:owner
            ~current:"ncps-cf2-home" ~expect_slug:"ncps-cf2-hub"
            ~expect_visibility:Ncpf.Public
            (publication ~slug:"ncps-cf2-hub" ())
        in
        let* () = probe "published holder" "ncps-cf2-hub" in
        (* The loser is still a live draft: a fresh slug publishes. *)
        let* _ =
          publish_ok "recovery" conn ~actor:owner ~current:"ncps-cf-home"
            ~expect_slug:"ncps-cf-free" ~expect_visibility:Ncpf.Public
            (publication ~slug:"ncps-cf-free" ())
        in
        Lwt.return_unit)

  (* === rollback injection === *)

  let rollback_case =
    db_case
      "publish: a failing update or a failing post-update validation rolls \
       the whole publication back" (fun ~url:_ conn ->
        let* owner = insert_user conn "ncps_owner" in
        let* intruder = insert_user conn "ncps_intruder" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:954000016L
            ~project_slug:"ncps-rb" ~slug:"ncps-rb-home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let exec_ddl label q =
          let (module C : Caqti_lwt.CONNECTION) = conn in
          let* r = C.exec q () in
          let* _ = or_fail label r in
          Lwt.return_unit
        in
        let value = publication ~slug:"ncps-rb-hub" () in
        (* 1: the community update itself fails. *)
        let* () = exec_ddl "create fail fn" q_create_fail_fn in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = exec_ddl "poison update" q_create_fail_trigger in
              Lwt.finalize
                (fun () ->
                  let* () =
                    publish_expect "poisoned update" St.Storage_error conn
                      ~actor:owner ~current:"ncps-rb-home" value
                  in
                  let* () =
                    check_unchanged "poisoned update" conn ~cid ~project
                      ~rid before
                  in
                  let* n = find conn "no hub" q_count_by_slug "ncps-rb-hub"
                  in
                  Alcotest.(check int) "poisoned update: no publication" 0 n;
                  Lwt.return_unit)
                (fun () -> exec_ddl "unpoison update" q_drop_fail_trigger))
            (fun () -> exec_ddl "drop fail fn" q_drop_fail_fn)
        in
        (* 2: the update succeeds but the complete post-update validation
           finds a moved aggregate (a membership row inserted behind the
           store's back) and refuses to commit. *)
        let* () = exec_ddl "create side fn" (q_create_side_fn
                                               ~user_id:intruder) in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = exec_ddl "install side trigger"
                          q_create_side_trigger in
              Lwt.finalize
                (fun () ->
                  let* () =
                    publish_expect "poisoned validation"
                      St.Inconsistent_data conn ~actor:owner
                      ~current:"ncps-rb-home" value
                  in
                  let* () =
                    check_unchanged "poisoned validation" conn ~cid ~project
                      ~rid before
                  in
                  let* n = find conn "no hub" q_count_by_slug "ncps-rb-hub"
                  in
                  Alcotest.(check int) "poisoned validation: no publication"
                    0 n;
                  let* members = find conn "members" Phrq.q_count_members
                                   cid in
                  Alcotest.(check int)
                    "the injected membership rolled back too" 1 members;
                  Lwt.return_unit)
                (fun () ->
                  exec_ddl "drop side trigger" q_drop_side_trigger))
            (fun () -> exec_ddl "drop side fn" q_drop_side_fn)
        in
        (* With every trigger removed the same inputs succeed. *)
        let* _ =
          publish_ok "clean run after poison" conn ~actor:owner
            ~current:"ncps-rb-home" ~expect_slug:"ncps-rb-hub"
            ~expect_visibility:Ncpf.Public value
        in
        Lwt.return_unit)

  (* === concurrency === *)

  let same_draft_race_case =
    db_case
      "publish: two submissions of one draft leave exactly one published \
       identity" (fun ~url conn ->
        let* owner = insert_user conn "ncps_owner" in
        let* second = insert_user conn "ncps_second" in
        let* _, cid, _ =
          make_draft conn ~user:owner ~ext_id:954000017L
            ~project_slug:"ncps-race1" ~slug:"ncps-race1-home"
        in
        let* () = exec conn "second member" q_insert_member (second, cid) in
        let* () =
          exec conn "second top mod" q_insert_moderator
            (second, cid, "top_mod")
        in
        with_second ~url (fun conn2 ->
            let sub_a =
              publication ~name:"Ncps Race A" ~slug:"ncps-race1-a"
                ~visibility:"public" ()
            in
            let sub_b =
              publication ~name:"Ncps Race B" ~slug:"ncps-race1-b"
                ~visibility:"unlisted" ()
            in
            let* ra, rb =
              Lwt.both
                (publish conn ~actor:owner ~current:"ncps-race1-home" sub_a)
                (publish conn2 ~actor:second ~current:"ncps-race1-home"
                   sub_b)
            in
            let winner_state =
              match (ra, rb) with
              | Ok w, Error St.Draft_unavailable ->
                  Alcotest.(check string) "winner slug" "ncps-race1-a"
                    (St.community_slug w);
                  "Ncps Race A|<null>|public|published|true|true|true"
              | Error St.Draft_unavailable, Ok w ->
                  Alcotest.(check string) "winner slug" "ncps-race1-b"
                    (St.community_slug w);
                  "Ncps Race B|<null>|public|published|true|false|false"
              | Ok _, Ok _ -> Alcotest.fail "race: both succeeded"
              | Error a, Error b ->
                  Alcotest.failf "race: both failed (%s, %s)" (error_str a)
                    (error_str b)
              | Ok _, Error e | Error e, Ok _ ->
                  Alcotest.failf "race: unexpected loser error %s"
                    (error_str e)
            in
            let* state = find conn "state" q_community_state cid in
            Alcotest.(check string) "exactly the winner identity survives"
              winner_state state;
            let loser_slug =
              match ra with
              | Ok _ -> "ncps-race1-b"
              | Error _ -> "ncps-race1-a"
            in
            let* n = find conn "loser slug" q_count_by_slug loser_slug in
            Alcotest.(check int) "no partial second identity" 0 n;
            let* old_n = find conn "old slug" q_count_by_slug
                           "ncps-race1-home" in
            Alcotest.(check int) "the draft slug is gone" 0 old_n;
            Lwt.return_unit))

  let same_slug_race_case =
    db_case
      "publish: two drafts racing for one final slug leave one clean \
       winner" (fun ~url conn ->
        let* owner_a = insert_user conn "ncps_owner" in
        let* owner_b = insert_user conn "ncps_second" in
        let* project_a, cid_a, rid_a =
          make_draft conn ~user:owner_a ~ext_id:954000018L
            ~project_slug:"ncps-race2a" ~slug:"ncps-race2a-home"
        in
        let* project_b, cid_b, rid_b =
          make_draft conn ~user:owner_b ~ext_id:954000019L
            ~project_slug:"ncps-race2b" ~slug:"ncps-race2b-home"
        in
        let* before_a = snapshot "a before" conn ~cid:cid_a
                          ~project:project_a ~rid:rid_a in
        let* before_b = snapshot "b before" conn ~cid:cid_b
                          ~project:project_b ~rid:rid_b in
        with_second ~url (fun conn2 ->
            let value = publication ~slug:"ncps-shared-final" () in
            let* ra, rb =
              Lwt.both
                (publish conn ~actor:owner_a ~current:"ncps-race2a-home"
                   value)
                (publish conn2 ~actor:owner_b ~current:"ncps-race2b-home"
                   value)
            in
            let* () =
              match (ra, rb) with
              | Ok w, Error St.Community_slug_unavailable ->
                  Alcotest.(check string) "winner slug" "ncps-shared-final"
                    (St.community_slug w);
                  (* The loser remains byte-identical under its original
                     slug as a private draft. *)
                  check_unchanged "loser b" conn ~cid:cid_b
                    ~project:project_b ~rid:rid_b before_b
              | Error St.Community_slug_unavailable, Ok w ->
                  Alcotest.(check string) "winner slug" "ncps-shared-final"
                    (St.community_slug w);
                  check_unchanged "loser a" conn ~cid:cid_a
                    ~project:project_a ~rid:rid_a before_a
              | Ok _, Ok _ -> Alcotest.fail "race: both succeeded"
              | Error a, Error b ->
                  Alcotest.failf "race: both failed (%s, %s)" (error_str a)
                    (error_str b)
              | Ok _, Error e | Error e, Ok _ ->
                  Alcotest.failf "race: unexpected loser error %s"
                    (error_str e)
            in
            let* n = find conn "one owner" q_count_by_slug
                       "ncps-shared-final" in
            Alcotest.(check int) "exactly one community owns the slug" 1 n;
            Lwt.return_unit))

  (* A publication blocked on the held relation row shows up as a backend
     some other backend is blocking; polling for it on the idle second
     connection is deterministic coordination, not a sleep. (A single
     row-lock waiter parks on the holder's transactionid, so pg_locks
     shows no not-granted entry on the table itself — pg_blocking_pids is
     the reliable signal.) *)
  let q_relation_lock_waiters =
    (Caqti_type.unit ->! Caqti_type.int)
    "SELECT COUNT(*) FROM pg_stat_activity \
     WHERE datname = current_database() \
       AND cardinality(pg_blocking_pids(pid)) > 0"

  let q_lock_relation_row =
    (Caqti_type.int64 ->! Caqti_type.int64)
    "SELECT id FROM community_projects WHERE id = $1 FOR UPDATE"

  let versus_removal_case =
    db_case
      "publish: removal serializes on the shared project-first order in \
       both directions" (fun ~url conn ->
        let* owner = insert_user conn "ncps_owner" in
        (* Removal commits first, deterministically: the second connection
           locks the accepted relation row before the publication is
           launched, waits until the publication is provably blocked on
           that row (it has already passed candidate resolution and locked
           project, community, and authorization), then completes the
           removal-shaped mutation and commits — so the publication always
           re-reads the relation after the removal committed. *)
        let* _, _, rid =
          make_draft conn ~user:owner ~ext_id:954000020L
            ~project_slug:"ncps-race3" ~slug:"ncps-race3-home"
        in
        let* () =
          with_second ~url (fun conn2 ->
              let (module C2 : Caqti_lwt.CONNECTION) = conn2 in
              let* r = C2.start () in
              let* () = Phrv.or_fail "second begin" r in
              let* _ = find conn2 "hold relation" q_lock_relation_row rid in
              let publish_promise =
                publish conn ~actor:owner ~current:"ncps-race3-home"
                  (publication ~slug:"ncps-race3-hub" ())
              in
              let rec await_blocked () =
                let* waiters =
                  find conn2 "lock waiters" q_relation_lock_waiters ()
                in
                if waiters > 0 then Lwt.return_unit
                else
                  let* () = Lwt.pause () in
                  await_blocked ()
              in
              let* () = await_blocked () in
              let* () = exec conn2 "removal first" q_mark_removed rid in
              let* r = C2.commit () in
              let* () = Phrv.or_fail "second commit" r in
              let* r = publish_promise in
              match r with
              | Error St.Draft_unavailable -> Lwt.return_unit
              | Ok _ -> Alcotest.fail "published after removal"
              | Error e ->
                  Alcotest.failf "unexpected error %s" (error_str e))
        in
        let* n = find conn "no hub" q_count_by_slug "ncps-race3-hub" in
        Alcotest.(check int) "removal winner leaves no publication" 0 n;
        (* Publication commits first: the real removal store may then
           remove the accepted relation while the published community and
           its content remain. *)
        let* project2, cid2, _ =
          make_draft conn ~user:owner ~ext_id:954000021L
            ~project_slug:"ncps-race4" ~slug:"ncps-race4-home"
        in
        let* _ =
          publish_ok "publication first" conn ~actor:owner
            ~current:"ncps-race4-home" ~expect_slug:"ncps-race4-home"
            ~expect_visibility:Ncpf.Public
            (publication ~slug:"ncps-race4-home" ())
        in
        let* r =
          Rms.remove conn ~actor_user_id:owner ~project_slug:"ncps-race4"
            ~community_slug:"ncps-race4-home"
        in
        let* () =
          match r with
          | Ok _ -> Lwt.return_unit
          | Error _ -> Alcotest.fail "removal after publication failed"
        in
        let* state = find conn "state" q_community_state cid2 in
        Alcotest.(check string) "published community remains"
          "Ncps Community Home|<null>|public|published|true|true|true"
          state;
        let* active = find conn "active" Phrq.q_count_active_for_project
                        project2 in
        Alcotest.(check int) "the relation is removed" 0 active;
        Lwt.return_unit)

  let authority_revocation_race_case =
    db_case
      "publish: top-mod removal, downgrade, and admin revocation that \
       commit first win the lock race" (fun ~url conn ->
        let* owner = insert_user conn "ncps_owner" in
        let* admin = insert_user conn "ncps_admin" in
        let* () = exec conn "admin flag" q_set_admin (admin, true) in
        let* _, cid, _ =
          make_draft conn ~user:owner ~ext_id:954000022L
            ~project_slug:"ncps-race5" ~slug:"ncps-race5-home"
        in
        let race label ~mutate ~actor =
          with_second ~url (fun conn2 ->
              let* r =
                Phrv.serialized_mutation_first conn2
                  ~mutate:(fun () -> mutate conn2)
                  ~launch:(fun () ->
                    publish conn ~actor ~current:"ncps-race5-home"
                      (publication ~slug:"ncps-race5-hub" ()))
              in
              match r with
              | Error St.Draft_unavailable -> Lwt.return_unit
              | Ok _ -> Alcotest.failf "%s: published anyway" label
              | Error e ->
                  Alcotest.failf "%s: unexpected error %s" label
                    (error_str e))
        in
        (* Top-mod removal. *)
        let* () =
          race "top-mod removal"
            ~mutate:(fun conn2 ->
              exec conn2 "revoke role" q_remove_moderator (owner, cid))
            ~actor:owner
        in
        let* () =
          exec conn "restore role" q_insert_moderator (owner, cid, "top_mod")
        in
        (* Top-mod downgrade. *)
        let* () =
          race "top-mod downgrade"
            ~mutate:(fun conn2 ->
              exec conn2 "downgrade" q_set_moderator_role (owner, cid, "mod"))
            ~actor:owner
        in
        let* () =
          exec conn "restore role" q_set_moderator_role
            (owner, cid, "top_mod")
        in
        (* Durable-admin revocation, for an admin-only publisher. *)
        let* () =
          race "admin revocation"
            ~mutate:(fun conn2 ->
              exec conn2 "revoke admin" q_set_admin (admin, false))
            ~actor:admin
        in
        let* n = find conn "no hub" q_count_by_slug "ncps-race5-hub" in
        Alcotest.(check int) "no revoked publication survives" 0 n;
        (* A verification change that commits first does not block: all
           three known states publish. *)
        let* () =
          with_second ~url (fun conn2 ->
              let* project_id =
                find conn "project id"
                  ((Caqti_type.string ->! Caqti_type.int64)
                     "SELECT id FROM open_source_projects WHERE slug = $1")
                  "ncps-race5"
              in
              let* r =
                Phrv.serialized_mutation_first conn2
                  ~mutate:(fun () ->
                    exec conn2 "stale first" q_set_verification
                      (project_id, "stale"))
                  ~launch:(fun () ->
                    publish conn ~actor:owner ~current:"ncps-race5-home"
                      (publication ~slug:"ncps-race5-hub" ()))
              in
              match r with
              | Ok published ->
                  Alcotest.(check string) "published despite staleness"
                    "ncps-race5-hub" (St.community_slug published);
                  Lwt.return_unit
              | Error e ->
                  Alcotest.failf "verification race: %s" (error_str e))
        in
        Lwt.return_unit)

  let versus_provisioning_race_case =
    db_case
      "publish: a provisioning insert racing for the same final slug \
       leaves exactly one owner" (fun ~url conn ->
        let* owner_a = insert_user conn "ncps_owner" in
        let* owner_b = insert_user conn "ncps_second" in
        let* project_a, cid_a, rid_a =
          make_draft conn ~user:owner_a ~ext_id:954000023L
            ~project_slug:"ncps-race6" ~slug:"ncps-race6-home"
        in
        let* _inst, project_b =
          make_project conn ~user:owner_b ~ext_id:954000024L
            ~slug:"ncps-race7"
        in
        let* before_a = snapshot "a before" conn ~cid:cid_a
                          ~project:project_a ~rid:rid_a in
        with_second ~url (fun conn2 ->
            let contested = "ncps-contested" in
            let* pub_r, prov_r =
              Lwt.both
                (publish conn ~actor:owner_a ~current:"ncps-race6-home"
                   (publication ~slug:contested ()))
                (Pv.provision conn2 ~actor_user_id:owner_b
                   ~project_slug:"ncps-race7"
                   ~identity:
                     (phvf_ok "provision identity"
                        (phvf_fields ~name:"Ncps Contested"
                           ~slug:contested ~description:"" ())))
            in
            let* () =
              match (pub_r, prov_r) with
              | Ok w, Error Pv.Community_slug_unavailable ->
                  Alcotest.(check string) "publication owns the slug"
                    contested (St.community_slug w);
                  (* The provisioning loser left no community and no
                     relation. *)
                  let* relations =
                    find conn "loser relations" Phrq.q_count_for_project
                      project_b
                  in
                  Alcotest.(check int) "no loser relation" 0 relations;
                  Lwt.return_unit
              | Error St.Community_slug_unavailable, Ok home ->
                  Alcotest.(check string) "provisioning owns the slug"
                    contested (Pv.community_slug home);
                  (* The publication loser remains byte-identical under
                     its original slug as a private draft. *)
                  check_unchanged "loser draft" conn ~cid:cid_a
                    ~project:project_a ~rid:rid_a before_a
              | Ok _, Ok _ -> Alcotest.fail "race: both owned the slug"
              | Error a, Error _ ->
                  Alcotest.failf "race: both failed (publication %s)"
                    (error_str a)
              | Ok _, Error _ ->
                  Alcotest.fail "race: unexpected provisioning error"
              | Error e, _ ->
                  Alcotest.failf "race: unexpected publication error %s"
                    (error_str e)
            in
            let* n = find conn "one owner" q_count_by_slug contested in
            Alcotest.(check int) "exactly one community owns the slug" 1 n;
            Lwt.return_unit))

  (* === privacy sweep === *)

  let privacy_case =
    db_case
      "publish: no credential-shaped or external-identifier fixture \
       reaches the published surface" (fun ~url conn ->
        let* owner = insert_user conn "ncps_priv" in
        let* project, cid, _rid =
          make_draft conn ~user:owner ~ext_id:954000015L
            ~project_slug:"ncps-priv" ~slug:"ncps-priv-home"
        in
        let name = "Ncps Private Hub" in
        let* published =
          publish_ok "publish" conn ~actor:owner ~current:"ncps-priv-home"
            ~expect_slug:"ncps-priv-hub" ~expect_visibility:Ncpf.Public
            (publication ~name ~slug:"ncps-priv-hub" ())
        in
        (* The abstract result exposes exactly the final slug and the
           selected mode — asserted through its only two accessors. *)
        Alcotest.(check string) "result slug only" "ncps-priv-hub"
          (St.community_slug published);
        Alcotest.(check string) "result visibility only" "public"
          (ncpf_vis (St.publication_visibility published));
        let* community = find conn "community sig" q_community_sig cid in
        let* sections = collect conn "sections" Phvs.q_section_sigs cid in
        let* channels = collect conn "channels" Phvs.q_channel_sigs cid in
        let* relation_ids = collect conn "relations" Phvs.q_relation_ids
                              project in
        let* relation_blob =
          match relation_ids with
          | [ rid ] -> find conn "blob" Phrq.q_relation_text_blob rid
          | _ -> Alcotest.fail "expected one relation"
        in
        let* _, page = Ccph.visit ~url ~slug:"ncps-priv-hub" () in
        let durable_blob =
          String.concat "|"
            ((community :: relation_blob :: sections) @ channels)
        in
        let page_blob = durable_blob ^ "|" ^ page in
        (* The intentionally public identity is present; nothing from the
           owner's GitHub records, account, or the store's internals is.
           The project namespace login is deliberately public identity on
           the published page (the connected-projects section renders it by
           design), so its absence is asserted on the durable community
           surface only. *)
        Alcotest.(check bool) "published name present" true
          (contains ~needle:name page_blob);
        List.iter
          (fun (what, marker) ->
            Alcotest.(check bool)
              ("published surface carries no " ^ what)
              false
              (contains ~needle:marker page_blob))
          [ ("external installation id", "954000015");
            ("external account id", "954100015");
            ("external repository id", "954400015");
            ("account email", "@test.invalid")
          ];
        Alcotest.(check bool)
          "the community rows carry no installation login" false
          (contains ~needle:"pfin-owner" durable_blob);
        Lwt.return_unit)

  let suite =
    [ pure_inputs_case; public_case; unlisted_case; same_slug_case;
      authority_case; unauthorized_case; verification_case;
      shell_corruption_case; lifecycle_corruption_case; slug_conflict_case;
      rollback_case; same_draft_race_case; same_slug_race_case;
      versus_removal_case; authority_revocation_race_case;
      versus_provisioning_race_case; privacy_case ]
end

(* === Network-community publication POST (POST /c/:slug/publish) ===
   The HTTP integration that completes the dedicated-community journey: the
   review-and-publish form the setup GET renders, submitted through the real
   router, the shared authenticated-mutation rate limiter, the same-origin
   policy, Dream's framework CSRF, the strict publication parser, and the
   atomic publication store.

   DB-free coverage is the route shape, the rollout/authentication gates,
   the configuration and origin sequence, and CSRF. Database-gated coverage
   (EARDE_TEST_DATABASE_URL, the same opt-in as Mod_scope) drives the whole
   GET -> POST -> 303 -> GET sequence over real rows, with its own reserved
   external-installation-id range 956000001..956000999 (hence account ids
   956100001..956100999), ncpb_% usernames, and ncpb-% community slugs so no
   suite shares fixtures. Verified projects come only through the real
   draft/selection/finalization chain and drafts only through the real
   provisioning store. Every per-case wrapper disconnects deterministically. *)
module Ncpb = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Hd = Earde.Network_community_publication_handlers
  module Pgs = Earde.Network_community_publication_pages
  module Rmh = Earde.Project_home_removal_handlers

  let case = go_case
  let counting_loader = Gh_start_handler.counting_loader
  let ok_loader = Gh_start_handler.ok_loader
  let status_of = Gh_start_handler.status_of
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let insert_community = Phcv.insert_community
  let make_draft = Ncps.make_draft
  let snapshot = Ncps.snapshot
  let check_unchanged = Ncps.check_unchanged
  let check_published = Ncps.check_published
  let search_lists = Ncps.search_lists

  (* The two patterns this feature owns, and the neighbours the flow lands
     on. *)
  let get_pattern = "/c/:slug/setup"
  let post_pattern = "/c/:slug/publish"
  let get_target slug = Printf.sprintf "/c/%s/setup" slug
  let post_target slug = Printf.sprintf "/c/%s/publish" slug
  let community_target slug = Printf.sprintf "/c/%s" slug
  let settings_target slug = Printf.sprintf "/c/%s/settings" slug

  let project_side_remove ~project ~community =
    Printf.sprintf "/projects/%s/community-home/%s/remove" project community

  let community_side_remove ~community ~project =
    Printf.sprintf "/c/%s/projects/%s/remove-home" community project

  let request_home_target slug = Printf.sprintf "/projects/%s/request-home" slug

  let settings_projects_target slug =
    Printf.sprintf "/c/%s/settings?panel=projects" slug

  let make_get ~mode = Hd.make_network_community_publication_page_handler ~mode

  let make ~mode ~load_config =
    Hd.make_network_community_publication_handler ~mode ~load_config

  (* Exactly the four application fields, in the page's own order. *)
  let fields ?(name = "Ncpb Community Home") ?(slug = "ncpb-home")
      ?(description = "") ?(visibility = "public") () =
    [ ("community_name", name);
      ("community_slug", slug);
      ("community_description", description);
      ("publication_visibility", visibility)
    ]

  (* ============ DB-free: the route shape ============ *)

  (* The real router with both patterns and the neighbouring settings GET,
     and nothing else: the POST target is dispatched exactly once, and no
     alias, sub-path, or method variant exists. Mode Off makes each dispatch
     observable as the clean /bring redirect, with no configuration read and
     no SQL. *)
  let route_router () =
    Dream.router
      [ Dream.get get_pattern (fun req -> make_get ~mode:Ob.Off req);
        Dream.post post_pattern (fun req ->
            make ~mode:Ob.Off ~load_config:(fun () -> ok_loader ()) req);
        Dream.get "/c/:slug/settings" (fun _req -> Dream.html "settings")
      ]

  let route_run ~method_ ~target =
    Pch.gate_response "route"
      (Pch.gate_run ~method_ ~target (route_router ()))

  let route_cases =
    [ case "publication route: the registered POST pattern is exactly the \
            action the setup page's form emits" (fun () ->
          let html =
            Pgs.network_community_publication_page
              ~community:
                { Pgs.name = "Ncpb Home";
                  slug = "ncpb-alpha-home";
                  description = None
                }
              ~project:
                { Pgs.name = "Ncpb Project";
                  slug = "ncpb-alpha";
                  namespace_login = "ncpb-owner";
                  kind = Pi.Project
                }
              ~values:
                { Pgs.community_name = "";
                  community_slug = "";
                  community_description = "";
                  publication_visibility = ""
                }
              ~feedback:None ()
          in
          Alcotest.(check bool) "the page posts to the registered route" true
            (contains html
               (Printf.sprintf "action='%s'" (post_target "ncpb-alpha-home")));
          Alcotest.(check int) "exactly one form" 1
            (ps_count (ps_fragment html) "<form"))
    ; case "publication route: the POST target resolves once, the setup GET \
            stays registered, and no alias exists" (fun () ->
          Pch.check_clean_redirect "post dispatches" "/bring"
            (route_run ~method_:`POST ~target:(post_target "ncpb-alpha-home"));
          Pch.check_clean_redirect "get dispatches" "/bring"
            (route_run ~method_:`GET ~target:(get_target "ncpb-alpha-home"));
          (* The neighbouring settings GET is unshadowed by either. *)
          Alcotest.(check int) "settings unshadowed" 200
            (status_of
               (route_run ~method_:`GET ~target:(settings_target "ncpb-any")));
          List.iter
            (fun (label, method_, target) ->
              Alcotest.(check int)
                (label ^ ": unrouted")
                404
                (status_of (route_run ~method_ ~target)))
            [ ("GET on the POST path", `GET, post_target "ncpb-alpha-home");
              ("POST on the GET path", `POST, get_target "ncpb-alpha-home");
              ("trailing slash", `POST, post_target "ncpb-alpha-home" ^ "/");
              ("sub-path", `POST, post_target "ncpb-alpha-home" ^ "/confirm");
              ("plural alias", `POST, "/c/ncpb-alpha-home/publishes");
              ("legacy alias", `POST, "/c/ncpb-alpha-home/publication");
              ("bare", `POST, "/publish");
              ("segmentless", `POST, "/c/publish")
            ])
    ]

  (* ======== DB-free: shared rollout and authentication gates ======== *)

  let post_run ?session ?(headers = []) ~mode ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST
      ~target:(post_target "ncpb-any")
      (make ~mode ~load_config)

  let routed_post ?session ?(headers = []) ?(mode = Ob.Public) ~load_config () =
    Pch.gate_run ?session ~headers ~method_:`POST
      ~target:(post_target "ncpb-any")
      (Dream.router
         [ Dream.post post_pattern (fun req -> make ~mode ~load_config req) ])

  let gate_cases =
    [ case "POST publish off: clean /bring redirect before any route read, \
            configuration load, or SQL" (fun () ->
          let loader, calls = counting_loader (ok_loader ()) in
          Pch.check_clean_redirect "off" "/bring"
            (Pch.gate_response "off"
               (post_run ~session:Pch.admin_session ~mode:Ob.Off
                  ~load_config:loader ()));
          Pch.check_clean_redirect "off routed" "/bring"
            (Pch.gate_response "off routed"
               (routed_post ~session:Pch.admin_session ~mode:Ob.Off
                  ~load_config:loader ()));
          Alcotest.(check int) "loader never called" 0 !calls)
    ; case "POST publish: anonymous and malformed sessions to /login, loader \
            untouched" (fun () ->
          let loader, calls = counting_loader (ok_loader ()) in
          Pch.check_clean_redirect "anonymous" "/login"
            (Pch.gate_response "anonymous" (routed_post ~load_config:loader ()));
          List.iter
            (fun raw ->
              Pch.check_clean_redirect ("user_id " ^ raw) "/login"
                (Pch.gate_response ("user_id " ^ raw)
                   (routed_post
                      ~session:[ ("user_id", raw) ]
                      ~load_config:loader ())))
            [ "not-a-number"; ""; "0"; "-3"; " 42"; "42x" ];
          (* A session admin claim alone is not an identity. *)
          Pch.check_clean_redirect "is_admin only" "/login"
            (Pch.gate_response "is_admin only"
               (routed_post
                  ~session:[ ("is_admin", "true") ]
                  ~mode:Ob.Admins ~load_config:loader ()));
          Alcotest.(check int) "loader never called" 0 !calls)
    ; case "POST publish admins mode: a non-admin is redirected before the \
            configuration load" (fun () ->
          let loader, calls = counting_loader (ok_loader ()) in
          Pch.check_clean_redirect "non-admin" "/bring"
            (Pch.gate_response "non-admin"
               (routed_post ~session:Pch.logged_in ~mode:Ob.Admins
                  ~load_config:loader ()));
          Alcotest.(check int) "loader never called" 0 !calls)
    ; case "POST publish: authorized sessions continue past the gates, and \
            an unrouted request is the generic 404 before configuration"
        (fun () ->
          (* Routerless: past the gates the missing route parameter is the
             next rejection, so reaching that defensive 404 proves the gates
             passed with no configuration read and no SQL (no sql_pool is
             installed). *)
          let continues label session mode =
            let loader, calls = counting_loader (ok_loader ()) in
            let response =
              Pch.gate_response label
                (post_run ~session ~mode ~load_config:loader ())
            in
            Alcotest.(check int) (label ^ ": defensive 404") 404
              (status_of response);
            Alcotest.(check (option string))
              (label ^ ": no-store")
              (Some "no-store")
              (Dream.header response "Cache-Control");
            Alcotest.(check int) (label ^ ": loader untouched") 0 !calls
          in
          continues "admin in admins mode" Pch.admin_session Ob.Admins;
          continues "user in public mode" Pch.logged_in Ob.Public;
          continues "admin in public mode" Pch.admin_session Ob.Public;
          (* Routed and authorized with a good configuration and origin: the
             next rejection is the missing content type, proving the whole
             prefix ran and still no SQL happened. *)
          Alcotest.(check int) "routed: 400 content type" 400
            (status_of
               (Pch.gate_response "routed"
                  (routed_post ~session:Pch.logged_in
                     ~headers:[ ("Origin", "https://earde.com") ]
                     ~load_config:(fun () -> ok_loader ())
                     ()))))
    ]

  (* ============ DB-free: configuration and origin ============ *)

  let config_origin_cases =
    [ case "POST publish: a configuration failure is a generic 503 that names \
            nothing" (fun () ->
          let loader, calls = counting_loader (gac_of_values ~origin:None ()) in
          let response =
            Pch.gate_response "config failure"
              (routed_post ~session:Pch.logged_in
                 ~headers:
                   [ ("Origin", "https://earde.com");
                     ("Content-Type", "application/x-www-form-urlencoded")
                   ]
                 ~load_config:loader ())
          in
          Alcotest.(check int) "503" 503 (status_of response);
          Alcotest.(check int) "loader called once" 1 !calls;
          Alcotest.(check (option string)) "no-store" (Some "no-store")
            (Dream.header response "Cache-Control");
          Alcotest.(check (option string)) "referrer policy"
            (Some Earde.Request_origin.referrer_policy)
            (Dream.header response "Referrer-Policy");
          let body = Lwt_main.run (Dream.body response) in
          List.iter
            (fun needle ->
              Alcotest.(check bool) ("no leak " ^ needle) false
                (contains body needle))
            [ "EARDE_PUBLIC_ORIGIN"; "GITHUB_APP"; "Missing"; "Invalid";
              "public_origin"
            ])
    ; case "POST publish origin gate: the exact same-origin policy, before \
            any form parse" (fun () ->
          let origin_run label ?sec_fetch_site origin =
            let headers =
              (match origin with Some o -> [ ("Origin", o) ] | None -> [])
              @
              match sec_fetch_site with
              | Some v -> [ ("Sec-Fetch-Site", v) ]
              | None -> []
            in
            Pch.gate_response label
              (routed_post ~session:Pch.logged_in ~headers
                 ~load_config:(fun () -> ok_loader ())
                 ())
          in
          let rejected label ?sec_fetch_site origin =
            Alcotest.(check int) (label ^ ": 403") 403
              (status_of (origin_run label ?sec_fetch_site origin))
          in
          (* Past the origin gate the missing content type is the next
             rejection (400) — reaching it proves the origin was accepted and
             that the form was not parsed before the check. *)
          let accepted label ?sec_fetch_site origin =
            Alcotest.(check int)
              (label ^ ": passes origin")
              400
              (status_of (origin_run label ?sec_fetch_site origin))
          in
          accepted "exact origin" (Some "https://earde.com");
          accepted "explicit default port" (Some "https://earde.com:443");
          accepted "fetch metadata" ~sec_fetch_site:"same-origin" None;
          rejected "cross-origin" (Some "https://evil.example");
          rejected "same-site subdomain" (Some "https://www.earde.com");
          rejected "wrong scheme" (Some "http://earde.com");
          rejected "null origin" (Some "null");
          rejected "mismatch beats metadata" ~sec_fetch_site:"same-origin"
            (Some "https://evil.example");
          rejected "no signals" None;
          rejected "cross-site" ~sec_fetch_site:"cross-site" None;
          rejected "same-site metadata" ~sec_fetch_site:"same-site" None;
          let leak = origin_run "reflection" (Some "https://evil.example") in
          Alcotest.(check bool) "origin never reflected" false
            (contains (Lwt_main.run (Dream.body leak)) "evil.example"))
    ]

  (* ==================== DB-free: CSRF ==================== *)

  let csrf_pipeline () =
    Dream.set_secret gck_secret @@ Dream.memory_sessions
    @@ fun req ->
    let* () = Dream.set_session_field req "user_id" "42" in
    match Dream.method_ req with
    | `GET ->
        Dream.respond
          (Dream.csrf_token req ^ "\n" ^ Dream.csrf_token ~valid_for:(-60.) req)
    | _ ->
        Dream.router
          [ Dream.post post_pattern (fun r ->
                make ~mode:Ob.Public ~load_config:(fun () -> ok_loader ()) r)
          ]
          req

  let csrf_post ?cookie ?(content_type = true) pipeline body_fields =
    let headers =
      [ ("Origin", "https://earde.com") ]
      @ (if content_type then
           [ ("Content-Type", "application/x-www-form-urlencoded") ]
         else [])
      @ match cookie with Some c -> [ ("Cookie", c) ] | None -> []
    in
    match
      Lwt_main.run
        (pipeline
           (Dream.request ~method_:`POST ~target:(post_target "ncpb-any")
              ~headers (Pch.form_body body_fields)))
    with
    | response -> `Response response
    | exception _ -> `Db_boundary

  let csrf_rejected label expected result =
    Alcotest.(check int) (label ^ ": status") expected
      (status_of (Pch.gate_response label result))

  let csrf_cases =
    [ case "POST publish CSRF: Dream verification gates every submission; \
            only a verified form reaches the database" (fun () ->
          let pipeline = csrf_pipeline () in
          let cookie, fresh, expired = Pch.mint_tokens "mint" pipeline in
          let valid = fields () in
          (* Every CSRF failure refuses the submission, but it is answered by
             re-rendering the owner-authorized page (a fresh token, nothing
             reflected) rather than a terminal page — so each one reaches the
             read model's DB boundary and none reaches the store. A page
             whose one-hour token outlived its fourteen-day session must not
             become permanently unsubmittable. *)
          Pch.check_db_boundary "missing token re-renders"
            (csrf_post ~cookie pipeline valid);
          Pch.check_db_boundary "invalid token re-renders"
            (csrf_post ~cookie pipeline
               (("dream.csrf", "not-a-token") :: valid));
          Pch.check_db_boundary "expired token re-renders"
            (csrf_post ~cookie pipeline (("dream.csrf", expired) :: valid));
          Pch.check_db_boundary "duplicate tokens re-render"
            (csrf_post ~cookie pipeline
               (("dream.csrf", fresh) :: ("dream.csrf", fresh) :: valid));
          Pch.check_db_boundary "wrong session re-renders"
            (csrf_post pipeline (("dream.csrf", fresh) :: valid));
          (* A wrong content type is still answered without any SQL. *)
          csrf_rejected "wrong content type" 400
            (csrf_post ~cookie ~content_type:false pipeline
               (("dream.csrf", fresh) :: valid));
          (* A rejected token still answers before the application fields are
             even looked at: the re-render is the same whatever was sent. *)
          Pch.check_db_boundary "bad token beats bad form"
            (csrf_post ~cookie pipeline
               [ ("dream.csrf", "not-a-token"); ("ncpb_unknown", "x") ]);
          (* A verified token reaches Dream.sql, which raises without a pool:
             CSRF passed, Dream stripped its own field, and the store call is
             the next thing to run. *)
          Pch.check_db_boundary "verified form continues"
            (csrf_post ~cookie pipeline (("dream.csrf", fresh) :: valid)))
    ; case "POST publish CSRF: a verified token with an invalid form still \
            re-authorizes through the database" (fun () ->
          let pipeline = csrf_pipeline () in
          let cookie, fresh, _ = Pch.mint_tokens "mint" pipeline in
          (* Every parser rejection re-renders the owner-authorized page,
             which needs the read model — so it too reaches the database
             boundary rather than answering from the submission alone. *)
          List.iter
            (fun (label, body_fields) ->
              Pch.check_db_boundary label
                (csrf_post ~cookie pipeline
                   (("dream.csrf", fresh) :: body_fields)))
            [ ("unknown field", ("ncpb_unknown", "x") :: fields ());
              ("blank name", fields ~name:"   " ());
              ("uppercase slug", fields ~slug:"Ncpb-Home" ());
              ( "control byte in description",
                fields ~description:"ncpb\001body" () );
              ("unknown visibility", fields ~visibility:"private" ())
            ])
    ]

  (* ================= Database-gated integration ================= *)

  (* Distinctive credential-shaped fixtures. None may appear in any page,
     redirect, header, or cookie this feature produces. *)
  let access_marker = "gho_NCPB_ACCESS_TOKEN_SECRET"
  let refresh_marker = "ghr_NCPB_REFRESH_TOKEN"
  let pkce_marker = "NCPB_PKCE_VERIFIER_VALUE"
  let state_marker = "NCPB_OAUTH_STATE_VALUE"
  let secret_marker = "NCPB_CLIENT_SECRET_VALUE"

  let credential_markers =
    [ ("access token", access_marker);
      ("refresh token", refresh_marker);
      ("PKCE verifier", pkce_marker);
      ("OAuth state", state_marker);
      ("client secret", secret_marker);
      ("external installation id", "956000001");
      ("external account id", "956100001")
    ]

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 956100001 AND 956100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 956100001 AND 956100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 956000001 AND 956000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'ncpb-%'"
      ; "DELETE FROM users WHERE username LIKE 'ncpb_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 956000001 AND 956000999"
      ; "DELETE FROM rate_limits WHERE endpoint LIKE '/c/ncpb-%'"
      ; "DELETE FROM rate_limits WHERE endpoint LIKE '/projects/ncpb-%'"
      ]

  (* The shared authenticated-mutation limiter buckets by (client ip, path).
     Every case but the limiter's own drives more submissions against one
     path than a 60-second window allows, so the bucket is cleared between
     attempts; the limiter itself stays installed exactly as production
     wires it. *)
  let q_clear_limits =
    (Caqti_type.unit ->. Caqti_type.unit)
    "DELETE FROM rate_limits \
     WHERE endpoint LIKE '/c/ncpb-%' OR endpoint LIKE '/projects/ncpb-%'"

  let q_count_by_slug = Ncps.q_count_by_slug
  let q_community_state = Ncps.q_community_state
  let q_delete_sections = Ncps.q_delete_sections
  let q_set_verification = Phrq.q_set_verification
  let q_mark_removed = Phrq.q_mark_removed
  let q_insert_moderator = Phrv.q_insert_moderator
  let q_remove_moderator = Phrv.q_remove_moderator
  let q_set_moderator_role = Phrv.q_set_moderator_role
  let q_insert_member = Phrv.q_insert_member
  let q_set_admin = Phrv.q_set_admin

  let q_verification =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT verification_status FROM open_source_projects WHERE id = $1"

  let q_relation_status =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT status FROM community_projects WHERE id = $1"

  let q_insert_post =
    (Caqti_type.(t2 int int) ->! Caqti_type.int)
    "INSERT INTO posts (title, content, community_id, user_id) \
     VALUES ('Ncpb Post', 'Ncpb body', $1, $2) RETURNING id"

  let q_count_posts =
    (Caqti_type.int ->! Caqti_type.int)
    "SELECT COUNT(*) FROM posts WHERE community_id = $1"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* === the real production pipeline shape ===

     One shared two-connection sql_pool for the whole suite: nothing ever
     closes a Dream.sql_pool, so a fresh pool per request would exhaust
     Postgres max_connections; two connections are the minimum that lets the
     concurrency cases run two requests genuinely at once. Everything else is
     the real production shape — secret, memory sessions, the real router
     paths bound to the real handlers, and every mutation POST wrapped in the
     same authenticated-mutation rate limiter main.ml applies. Session
     identity is sticky: a request that already carries a session keeps its
     own user, so independent cookies stay independent under concurrency. *)
  let shared_identity : (int * bool) option ref = ref None
  let shared_pipeline = ref None

  let identity_middleware handler request =
    match Dream.session_field request "user_id" with
    | Some _ -> handler request
    | None -> (
        match !shared_identity with
        | None -> handler request
        | Some (uid, is_admin) ->
            let* () =
              Dream.set_session_field request "user_id" (string_of_int uid)
            in
            let* () =
              Dream.set_session_field request "username"
                ("ncpb_user_" ^ string_of_int uid)
            in
            let* () =
              if is_admin then Dream.set_session_field request "is_admin" "true"
              else Lwt.return_unit
            in
            handler request)

  let limited inner = Earde.Handlers.Rate_limit.middleware inner

  let build_pipeline ~url =
    Dream.sql_pool ~size:2 url @@ Dream.set_secret gck_secret
    @@ Dream.memory_sessions @@ identity_middleware
    @@ Dream.router
         [ Dream.get "/mint" (fun req -> Dream.respond (Dream.csrf_token req));
           Dream.get get_pattern (fun req -> make_get ~mode:Ob.Public req);
           Dream.post post_pattern
             (limited (fun req ->
                  make ~mode:Ob.Public
                    ~load_config:(fun () -> ok_loader ())
                    req));
           Dream.post "/projects/:project_slug/community-home/:community_slug/remove"
             (limited (fun req ->
                  Rmh.make_project_side_home_removal_handler ~mode:Ob.Public
                    ~load_config:(fun () -> ok_loader ())
                    req));
           Dream.post "/c/:community_slug/projects/:project_slug/remove-home"
             (limited (fun req ->
                  Rmh.make_community_side_home_removal_handler ~mode:Ob.Public
                    ~load_config:(fun () -> ok_loader ())
                    req));
           Dream.get "/c/:slug" Earde.Handlers.community_page_handler;
           Dream.get "/c/:slug/settings"
             Earde.Handlers.community_settings_handler
         ]

  let pipeline_for ~url =
    match !shared_pipeline with
    | Some pipeline -> pipeline
    | None ->
        let pipeline = build_pipeline ~url in
        shared_pipeline := Some pipeline;
        pipeline

  let as_user ?(admin_session = false) uid =
    shared_identity := Some (uid, admin_session)

  let as_anonymous () = shared_identity := None

  let clear_limits conn = exec conn "clear rate limits" q_clear_limits ()

  let do_get ?pipeline ?cookie ~url ~target () =
    let pipeline =
      match pipeline with Some p -> p | None -> pipeline_for ~url
    in
    let headers = match cookie with Some c -> [ ("Cookie", c) ] | None -> [] in
    let* response = pipeline (Dream.request ~method_:`GET ~target ~headers "") in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* [?conn] clears this feature's limiter buckets first, so a case that
     drives many submissions against one path stays deterministic without
     removing the limiter from the pipeline. *)
  let do_post ?pipeline ?conn ?(origin = Some "https://earde.com") ~url ~cookie
      ~target ~token ~body_fields () =
    let* () =
      match conn with Some c -> clear_limits c | None -> Lwt.return_unit
    in
    let pipeline =
      match pipeline with Some p -> p | None -> pipeline_for ~url
    in
    let headers =
      (match origin with Some o -> [ ("Origin", o) ] | None -> [])
      @ [ ("Content-Type", "application/x-www-form-urlencoded");
          ("Cookie", cookie)
        ]
    in
    let* response =
      pipeline
        (Dream.request ~method_:`POST ~target ~headers
           (Pch.form_body (("dream.csrf", token) :: body_fields)))
    in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* A field-free POST, for the removal routes this flow interacts with. *)
  let do_bare_post ?conn ~url ~cookie ~target ~token () =
    do_post ?conn ~url ~cookie ~target ~token ~body_fields:[] ()

  (* One cookie-less GET that opens a fresh session for this user and returns
     its cookie plus a live CSRF token. *)
  let open_session ?(admin_session = false) label ~url uid =
    as_user ~admin_session uid;
    let* response, token = do_get ~url ~target:"/mint" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return (Pch.session_cookie label response, token)

  let mint_token label ~url ~cookie =
    let* response, body = do_get ~url ~cookie ~target:"/mint" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return body

  (* One cookie-less GET of the setup page: the page, its session cookie, and
     the live CSRF token its own form carries. *)
  let open_setup label ~url ~slug uid =
    as_user uid;
    let* response, body = do_get ~url ~target:(get_target slug) () in
    Alcotest.(check int) (label ^ ": setup page 200") 200 (status_of response);
    Lwt.return
      (Pch.session_cookie label response, Pch.csrf_of_page label body, body)

  let check_clean_redirect label expected response body =
    Alcotest.(check int) (label ^ ": 303") 303 (status_of response);
    Alcotest.(check (option string)) (label ^ ": Location") (Some expected)
      (Dream.header response "Location");
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": no-cache") (Some "no-cache")
      (Dream.header response "Pragma");
    Alcotest.(check (option string)) (label ^ ": no-referrer")
      (Some "no-referrer")
      (Dream.header response "Referrer-Policy");
    Alcotest.(check string) (label ^ ": empty body") "" body

  let check_generic_404 label response body =
    Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "This page does not exist.")

  let check_generic_500 label response body =
    Alcotest.(check int) (label ^ ": 500") 500 (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "Something went wrong on our side.");
    List.iter
      (fun needle ->
        Alcotest.(check bool) (label ^ ": no detail " ^ needle) false
          (contains body needle))
      [ "communities_slug_key"; "community_projects"; "open_source_projects";
        "Caqti"; "PostgreSQL"; "SELECT"; "search_path"; "Inconsistent";
        "Storage_error"; "ncpb_void"
      ]

  (* The re-rendered publication form: the requested status, the exact
     feedback copy, a live CSRF field, and the one form pointing back at this
     route under the community's current slug. *)
  let check_rerender label ~status ~feedback ~slug response body =
    Alcotest.(check int) (label ^ ": status") status (status_of response);
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": referrer policy")
      (Some Earde.Request_origin.referrer_policy)
      (Dream.header response "Referrer-Policy");
    Alcotest.(check bool) (label ^ ": feedback copy") true
      (contains body feedback);
    Alcotest.(check bool) (label ^ ": fresh CSRF field") true
      (contains body "name=\"dream.csrf\"");
    Alcotest.(check bool) (label ^ ": posts back to this route") true
      (contains body (Printf.sprintf "action='%s'" (post_target slug)));
    Alcotest.(check int) (label ^ ": exactly one form") 1
      (ps_count (ps_fragment body) "<form")

  (* The existing community-page unavailable answer, asserted exactly as the
     legacy handler already produces it: this slice deliberately changes no
     community authorization. *)
  let check_community_unavailable label response body =
    Alcotest.(check int) (label ^ ": 404") 404 (status_of response);
    Alcotest.(check bool) (label ^ ": generic copy") true
      (contains body "This community does not exist.")

  let check_body_no_credentials label body =
    List.iter
      (fun (what, needle) ->
        Alcotest.(check bool) (label ^ ": body free of " ^ what) false
          (contains body needle))
      credential_markers

  let check_no_credentials label response body =
    check_body_no_credentials label body;
    let headers =
      String.concat "\n"
        (List.map (fun (k, v) -> k ^ ": " ^ v) (Dream.all_headers response))
    in
    List.iter
      (fun (what, needle) ->
        Alcotest.(check bool) (label ^ ": headers free of " ^ what) false
          (contains headers needle))
      credential_markers

  let location response =
    match Dream.header response "Location" with Some l -> l | None -> ""

  (* Masks one intentionally-varying substring so two answers can be compared
     for byte-identity everywhere else. *)
  let replace_substring haystack ~needle ~replacement =
    let nl = String.length needle in
    if nl = 0 then haystack
    else
      let buf = Buffer.create (String.length haystack) in
      let rec go i =
        match ps_index_of haystack needle i with
        | None ->
            Buffer.add_string buf
              (String.sub haystack i (String.length haystack - i))
        | Some j ->
            Buffer.add_string buf (String.sub haystack i (j - i));
            Buffer.add_string buf replacement;
            go (j + nl)
      in
      go 0;
      Buffer.contents buf

  (* === success: Public === *)

  let public_success_case =
    db_case "POST publish: a top moderator's Public submission publishes the \
             community and redirects to its final public home" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_owner" in
        let* reader = insert_user conn "ncpb_reader" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000001L
            ~project_slug:"ncpb-alpha" ~slug:"ncpb-alpha-home"
            ~name:"Ncpb Alpha Home"
        in
        (* Real content inside the draft, so "content remains" is asserted
           against something. *)
        let* _post = find conn "post" q_insert_post (cid, owner) in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie, token, page =
          open_setup "setup" ~url ~slug:"ncpb-alpha-home" owner
        in
        Alcotest.(check bool) "the form posts to the POST route" true
          (contains page
             (Printf.sprintf "action='%s'" (post_target "ncpb-alpha-home")));
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-alpha-home")
            ~token
            ~body_fields:
              (fields ~name:"Ncpb Alpha Hub" ~slug:"ncpb-alpha-hub"
                 ~description:"A durable hub description."
                 ~visibility:"public" ())
            ()
        in
        check_clean_redirect "published" (community_target "ncpb-alpha-hub")
          response body;
        check_no_credentials "published redirect" response body;
        (* No query, fragment, result token, or internal identifier — and
           never the settings route. *)
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("Location free of " ^ needle) false
              (contains (location response) needle))
          [ "?"; "#"; "published"; "ok="; "settings" ];
        (* The exact durable lifecycle: published, public, indexable,
           discoverable, with everything else byte-unchanged. *)
        let* () =
          check_published "durable" conn ~cid ~project ~rid ~before
            ~name:"Ncpb Alpha Hub" ~description:"A durable hub description."
            ~slug:"ncpb-alpha-hub" ~old_slug:"ncpb-alpha-home" ~indexable:true
            ~discoverable:true
        in
        let* posts = find conn "posts" q_count_posts cid in
        Alcotest.(check int) "the draft's content survives" 1 posts;
        let* status = find conn "relation" q_relation_status rid in
        Alcotest.(check string) "relation still accepted" "accepted" status;
        (* The advertised destination really serves the published community,
           to its publisher, to an unrelated user, and anonymously. *)
        let* response, page_body =
          do_get ~url ~cookie ~target:(community_target "ncpb-alpha-hub") ()
        in
        Alcotest.(check int) "publisher reads the community" 200
          (status_of response);
        Alcotest.(check bool) "the published name renders" true
          (contains page_body "Ncpb Alpha Hub");
        Alcotest.(check bool) "a Public community is indexable" false
          (contains page_body "content='noindex'");
        check_no_credentials "published community page" response page_body;
        let* reader_cookie, _ = open_session "reader" ~url reader in
        let* response, _ =
          do_get ~url ~cookie:reader_cookie
            ~target:(community_target "ncpb-alpha-hub") ()
        in
        Alcotest.(check int) "an unrelated user reads it" 200
          (status_of response);
        as_anonymous ();
        let* response, _ =
          do_get ~url ~target:(community_target "ncpb-alpha-hub") ()
        in
        Alcotest.(check int) "an anonymous visitor reads it" 200
          (status_of response);
        (* The old slug is gone: no alias, no redirect. *)
        let* response, body =
          do_get ~url ~target:(community_target "ncpb-alpha-home") ()
        in
        check_community_unavailable "old slug" response body;
        (* Public discovery lists it. *)
        let* () =
          search_lists "discovery" conn ~name:"Ncpb Alpha Hub"
            ~slug:"ncpb-alpha-hub" true
        in
        (* The setup surface is over: the draft no longer exists. *)
        as_user owner;
        let* response, body =
          do_get ~url ~cookie ~target:(get_target "ncpb-alpha-hub") ()
        in
        check_generic_404 "setup after publication" response body;
        Lwt.return_unit)

  (* === success: Unlisted === *)

  let unlisted_success_case =
    db_case "POST publish: an Unlisted submission stays reachable by URL but \
             out of indexing and discovery" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_unowner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000002L
            ~project_slug:"ncpb-unl" ~slug:"ncpb-unl-home"
            ~name:"Ncpb Unlisted Home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie, token, _ =
          open_setup "setup" ~url ~slug:"ncpb-unl-home" owner
        in
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-unl-home")
            ~token
            ~body_fields:
              (fields ~name:"Ncpb Unlisted Home" ~slug:"ncpb-unl-home"
                 ~visibility:"unlisted" ())
            ()
        in
        (* Publishing under the unchanged slug: normal success, no false
           conflict handling. *)
        check_clean_redirect "published unlisted"
          (community_target "ncpb-unl-home") response body;
        let* () =
          check_published "durable" conn ~cid ~project ~rid ~before
            ~name:"Ncpb Unlisted Home" ~description:"<null>"
            ~slug:"ncpb-unl-home" ~old_slug:"ncpb-unl-home" ~indexable:false
            ~discoverable:false
        in
        (* Direct anonymous reachability under existing public
           authorization. *)
        as_anonymous ();
        let* response, page_body =
          do_get ~url ~target:(community_target "ncpb-unl-home") ()
        in
        Alcotest.(check int) "anonymous direct URL works" 200
          (status_of response);
        Alcotest.(check bool) "but it is marked noindex" true
          (contains page_body "content='noindex'");
        (* And it is absent from discovery. *)
        let* () =
          search_lists "discovery" conn ~name:"Ncpb Unlisted Home"
            ~slug:"ncpb-unl-home" false
        in
        Lwt.return_unit)

  (* === form parsing: 422 rendering and safe value preservation === *)

  let long_name = "Ncpb " ^ String.make 130 'n'
  let long_description = String.make 2100 'd'

  let parser_rejection_case =
    db_case "POST publish: every parser rejection is a 422 re-render that \
             preserves only provably safe values and mutates nothing"
      (fun ~url conn ->
        let* owner = insert_user conn "ncpb_fowner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000003L
            ~project_slug:"ncpb-form" ~slug:"ncpb-form-home"
            ~name:"Ncpb Form Home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie, token, _ =
          open_setup "setup" ~url ~slug:"ncpb-form-home" owner
        in
        let target = post_target "ncpb-form-home" in
        (* 1. Structural: an unknown field carrying a credential-shaped value
           is Invalid_form, and nothing submitted is reflected back. *)
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (("ncpb_planted", access_marker)
              :: fields ~name:"Ncpb Planted Name" ~slug:"ncpb-planted"
                   ~description:"Planted body." ~visibility:"unlisted" ())
            ()
        in
        check_rerender "invalid form" ~status:422
          ~feedback:"We couldn't read that submission." ~slug:"ncpb-form-home"
          response body;
        check_no_credentials "invalid form" response body;
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("invalid form reflects no " ^ needle) false
              (contains body needle))
          [ "ncpb_planted"; "Ncpb Planted Name"; "ncpb-planted";
            "Planted body."
          ];
        Alcotest.(check bool) "the controls are blank" true
          (contains body "name='community_slug' maxlength='80' value=''");
        (* A duplicated known field is structurally invalid too, and reflects
           nothing. *)
        let* token = mint_token "duplicate" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (("community_slug", "ncpb-dup-one")
              :: fields ~slug:"ncpb-dup-two" ())
            ()
        in
        check_rerender "duplicate field" ~status:422
          ~feedback:"We couldn't read that submission." ~slug:"ncpb-form-home"
          response body;
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("duplicate reflects no " ^ needle) false
              (contains body needle))
          [ "ncpb-dup-one"; "ncpb-dup-two" ];
        (* 2. Semantic name: the exact submitted values survive. *)
        let* token = mint_token "name" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:long_name ~slug:"ncpb-kept-slug"
                 ~description:"Kept body." ~visibility:"unlisted" ())
            ()
        in
        check_rerender "invalid name" ~status:422
          ~feedback:"Enter a community name we can use." ~slug:"ncpb-form-home"
          response body;
        Alcotest.(check bool) "name preserved" true (contains body long_name);
        Alcotest.(check bool) "slug preserved" true
          (contains body "value='ncpb-kept-slug'");
        Alcotest.(check bool) "description preserved" true
          (contains body ">Kept body.</textarea>");
        Alcotest.(check bool) "choice preserved" true
          (contains body "value='unlisted' checked");
        (* 3. Semantic slug. *)
        let* token = mint_token "slug" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Kept Name" ~slug:"Ncpb-Bad-Slug"
                 ~description:"Kept body." ())
            ()
        in
        check_rerender "invalid slug" ~status:422
          ~feedback:"Enter a community address using lowercase letters"
          ~slug:"ncpb-form-home" response body;
        Alcotest.(check bool) "slug preserved verbatim" true
          (contains body "value='Ncpb-Bad-Slug'");
        Alcotest.(check bool) "name preserved" true
          (contains body "value='Ncpb Kept Name'");
        (* 4. Semantic description. *)
        let* token = mint_token "description" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Kept Name" ~slug:"ncpb-kept-slug"
                 ~description:long_description ())
            ()
        in
        check_rerender "invalid description" ~status:422
          ~feedback:"That description can't be used." ~slug:"ncpb-form-home"
          response body;
        Alcotest.(check bool) "description preserved" true
          (contains body long_description);
        (* 5. Publication choice: every rejected spelling, including the one
           shape a network community can never have. *)
        let* () =
          Lwt_list.iter_s
            (fun bad ->
              let* token = mint_token "visibility" ~url ~cookie in
              let* response, body =
                do_post ~conn ~url ~cookie ~target ~token
                  ~body_fields:
                    (fields ~name:"Ncpb Kept Name" ~slug:"ncpb-kept-slug"
                       ~visibility:bad ())
                  ()
              in
              check_rerender
                ("invalid visibility " ^ String.escaped bad)
                ~status:422
                ~feedback:
                  "Choose whether the community should be public or unlisted."
                ~slug:"ncpb-form-home" response body;
              Lwt.return_unit)
            [ "private"; "Public"; " public"; ""; "listed" ]
        in
        (* A rejected non-empty choice preselects neither radio: it never
           moves the publisher onto the more exposed option. Only the empty
           value — no choice at all — falls back to the documented default. *)
        let* token = mint_token "preselection" ~url ~cookie in
        let* _response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Kept Name" ~slug:"ncpb-kept-slug"
                 ~visibility:"private" ())
            ()
        in
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("no preselection: " ^ needle) false
              (contains body needle))
          [ "value='public' checked"; "value='unlisted' checked" ];
        Alcotest.(check bool) "the rejected value is not reflected as markup"
          false (contains body "value='private'");
        let* token = mint_token "empty preselection" ~url ~cookie in
        let* _response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Kept Name" ~slug:"ncpb-kept-slug"
                 ~visibility:"" ())
            ()
        in
        Alcotest.(check bool) "no choice falls back to public" true
          (contains body "value='public' checked");
        (* Escaping: preserved values are text, never markup. *)
        let* token = mint_token "escaping" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"<script>ncpb_x()</script>" ~slug:"Ncpb-Bad"
                 ~description:"<b>ncpb</b>" ())
            ()
        in
        Alcotest.(check int) "422" 422 (status_of response);
        Alcotest.(check bool) "escaped name" true
          (contains body "&lt;script&gt;ncpb_x()&lt;/script&gt;");
        Alcotest.(check bool) "raw name absent" false
          (contains body "<script>ncpb_x()</script>");
        Alcotest.(check bool) "escaped description" true
          (contains body "&lt;b&gt;ncpb&lt;/b&gt;");
        Alcotest.(check bool) "raw description absent" false
          (contains body "<b>ncpb</b>");
        (* Nothing durable moved through any of them. *)
        check_unchanged "after every rejection" conn ~cid ~project ~rid before)

  (* === community-slug conflict and retry === *)

  let slug_conflict_case =
    db_case "POST publish: a taken final slug is a safe 409 re-render that \
             keeps the draft intact and stays retryable" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_cowner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000004L
            ~project_slug:"ncpb-conf" ~slug:"ncpb-conf-home"
            ~name:"Ncpb Conf Home"
        in
        (* Three shapes of "taken": a legacy community, an unpublished
           network draft, and a published network community. *)
        let* _legacy =
          insert_community ~name:"Ncpb Legacy" ~network:false conn
            "ncpb-taken-legacy"
        in
        let* _draft =
          insert_community ~name:"Ncpb Other Draft" ~visibility:"private"
            ~indexable:false ~discoverable:false ~onboarding:"draft" conn
            "ncpb-taken-draft"
        in
        let* _published =
          insert_community ~name:"Ncpb Other Published" conn
            "ncpb-taken-published"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie, token, _ =
          open_setup "setup" ~url ~slug:"ncpb-conf-home" owner
        in
        let target = post_target "ncpb-conf-home" in
        (* The three answers may differ only in the value the publisher
           themselves submitted, so that one value is masked before they are
           compared; everything else — copy, structure, status — must be
           byte-identical, or the 409 would be a conflicting-community
           oracle. *)
        let bodies = ref [] in
        let normalized ~slug body =
          replace_substring
            (ps_without_csrf_inputs body)
            ~needle:slug ~replacement:"SUBMITTED-SLUG"
        in
        let attempt label ~token ~slug =
          let* response, body =
            do_post ~conn ~url ~cookie ~target ~token
              ~body_fields:
                (fields ~name:"Ncpb Conf Home" ~slug
                   ~description:"Conflict body." ~visibility:"unlisted" ())
              ()
          in
          check_rerender label ~status:409
            ~feedback:"That community address is already taken."
            ~slug:"ncpb-conf-home" response body;
          Alcotest.(check bool) (label ^ ": slug preserved") true
            (contains body (Printf.sprintf "value='%s'" slug));
          Alcotest.(check bool) (label ^ ": name preserved") true
            (contains body "value='Ncpb Conf Home'");
          Alcotest.(check bool) (label ^ ": description preserved") true
            (contains body ">Conflict body.</textarea>");
          Alcotest.(check bool) (label ^ ": choice preserved") true
            (contains body "value='unlisted' checked");
          (* Nothing about the conflicting community leaks. *)
          List.iter
            (fun needle ->
              Alcotest.(check bool) (label ^ ": no leak " ^ needle) false
                (contains body needle))
            [ "Ncpb Legacy"; "Ncpb Other Draft"; "Ncpb Other Published";
              "onboarding_state"; "is_network_community"; "visibility ="
            ];
          check_no_credentials label response body;
          bodies := normalized ~slug body :: !bodies;
          Lwt.return_unit
        in
        let* () = attempt "legacy conflict" ~token ~slug:"ncpb-taken-legacy" in
        let* token = mint_token "draft" ~url ~cookie in
        let* () = attempt "draft conflict" ~token ~slug:"ncpb-taken-draft" in
        let* token = mint_token "published" ~url ~cookie in
        let* () =
          attempt "published conflict" ~token ~slug:"ncpb-taken-published"
        in
        (* A legacy community, an unpublished network draft, and a published
           network community are one indistinguishable safe answer. *)
        (match !bodies with
        | [] -> Alcotest.fail "no 409 bodies captured"
        | first :: rest ->
            List.iteri
              (fun i body ->
                Alcotest.(check bool)
                  (Printf.sprintf "409 body %d identical once the submitted \
                                   slug is masked" i)
                  true (String.equal first body))
              rest);
        (* The draft is byte-unchanged: old slug, private lifecycle,
           identity, relation, membership, moderation, shell. *)
        let* () = check_unchanged "after conflicts" conn ~cid ~project ~rid
                    before in
        (* And a free slug still publishes. *)
        let* token = mint_token "retry" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Conf Home" ~slug:"ncpb-conf-final"
                 ~description:"Conflict body." ~visibility:"unlisted" ())
            ()
        in
        check_clean_redirect "retry succeeds"
          (community_target "ncpb-conf-final") response body;
        check_published "retry" conn ~cid ~project ~rid ~before
          ~name:"Ncpb Conf Home" ~description:"Conflict body."
          ~slug:"ncpb-conf-final" ~old_slug:"ncpb-conf-home" ~indexable:false
          ~discoverable:false)

  (* === durable authority variants === *)

  let authority_case =
    db_case "POST publish: every durable publication authority works, and \
             only durable authority does" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_aowner" in
        let* second = insert_user conn "ncpb_asecond" in
        let* admin = insert_user conn "ncpb_aadmin" in
        let* both = insert_user conn "ncpb_aboth" in
        let* () = exec conn "durable admin" q_set_admin (admin, true) in
        let* () = exec conn "durable admin" q_set_admin (both, true) in
        let publish_as label ~ext_id ~project_slug ~slug ~final ~actor ~setup =
          let* project, cid, rid =
            make_draft conn ~user:owner ~ext_id ~project_slug ~slug
              ~name:"Ncpb Authority Home"
          in
          let* () = setup ~community:cid in
          let* before = snapshot label conn ~cid ~project ~rid in
          let* cookie, token, _ = open_setup label ~url ~slug actor in
          let* response, body =
            do_post ~conn ~url ~cookie ~target:(post_target slug) ~token
              ~body_fields:
                (fields ~name:"Ncpb Authority Home" ~slug:final ())
              ()
          in
          check_clean_redirect label (community_target final) response body;
          check_published label conn ~cid ~project ~rid ~before
            ~name:"Ncpb Authority Home" ~description:"<null>" ~slug:final
            ~old_slug:slug ~indexable:true ~discoverable:true
        in
        (* The creating top moderator. *)
        let* () =
          publish_as "creating top mod" ~ext_id:956000005L
            ~project_slug:"ncpb-auth-a" ~slug:"ncpb-auth-a-home"
            ~final:"ncpb-auth-a-live" ~actor:owner
            ~setup:(fun ~community:_ -> Lwt.return_unit)
        in
        (* A second current top moderator with no creation provenance. *)
        let* () =
          publish_as "second top mod" ~ext_id:956000006L
            ~project_slug:"ncpb-auth-b" ~slug:"ncpb-auth-b-home"
            ~final:"ncpb-auth-b-live" ~actor:second
            ~setup:(fun ~community ->
              exec conn "second top_mod" q_insert_moderator
                (second, community, "top_mod"))
        in
        (* A durable global administrator with no local role at all. *)
        let* () =
          publish_as "durable admin" ~ext_id:956000007L
            ~project_slug:"ncpb-auth-c" ~slug:"ncpb-auth-c-home"
            ~final:"ncpb-auth-c-live" ~actor:admin
            ~setup:(fun ~community:_ -> Lwt.return_unit)
        in
        (* An actor holding both authorities at once. *)
        publish_as "top mod and durable admin" ~ext_id:956000008L
          ~project_slug:"ncpb-auth-d" ~slug:"ncpb-auth-d-home"
          ~final:"ncpb-auth-d-live" ~actor:both
          ~setup:(fun ~community ->
            exec conn "both top_mod" q_insert_moderator
              (both, community, "top_mod")))

  (* === unavailable and unauthorized === *)

  let unavailable_case =
    db_case "POST publish: every unavailable or unauthorized state is one \
             byte-identical generic 404" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_uowner" in
        let* member = insert_user conn "ncpb_umember" in
        let* moddy = insert_user conn "ncpb_umod" in
        let* legacy_mod = insert_user conn "ncpb_ulegacymod" in
        let* foreign_mod = insert_user conn "ncpb_uforeign" in
        let* demoted = insert_user conn "ncpb_udemoted" in
        let* removed = insert_user conn "ncpb_uremoved" in
        let* stranger = insert_user conn "ncpb_ustranger" in
        let* _project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000009L
            ~project_slug:"ncpb-un" ~slug:"ncpb-un-home"
        in
        (* Everyone below opens their own session; nobody but a durable
           top_mod or admin can even see the setup page, so tokens come from
           /mint rather than the form. *)
        let bodies = ref [] in
        let expect_404 label ?(admin_session = false) ~user ~slug () =
          as_user ~admin_session user;
          let* cookie, token = open_session label ~url user in
          let* response, body =
            do_post ~conn ~url ~cookie ~target:(post_target slug) ~token
              ~body_fields:(fields ~slug:"ncpb-un-final" ())
              ()
          in
          check_generic_404 label response body;
          check_no_credentials label response body;
          bodies := body :: !bodies;
          Lwt.return_unit
        in
        let* () =
          exec conn "member" q_insert_member (member, cid)
        in
        let* () = expect_404 "ordinary member" ~user:member ~slug:"ncpb-un-home" () in
        let* () =
          exec conn "mod" q_insert_moderator (moddy, cid, "mod")
        in
        let* () = expect_404 "mod" ~user:moddy ~slug:"ncpb-un-home" () in
        let* () =
          exec conn "legacy_mod" q_insert_moderator
            (legacy_mod, cid, "legacy_mod")
        in
        let* () =
          expect_404 "legacy_mod" ~user:legacy_mod ~slug:"ncpb-un-home" ()
        in
        (* A top moderator of a different community. *)
        let* other = insert_community ~name:"Ncpb Other" conn "ncpb-un-other" in
        let* () =
          exec conn "foreign top_mod" q_insert_moderator
            (foreign_mod, other, "top_mod")
        in
        let* () =
          expect_404 "moderator of another community" ~user:foreign_mod
            ~slug:"ncpb-un-home" ()
        in
        (* A downgraded top moderator, and a removed one. *)
        let* () =
          exec conn "downgrade seed" q_insert_moderator
            (demoted, cid, "top_mod")
        in
        let* () =
          exec conn "downgrade" q_set_moderator_role (demoted, cid, "mod")
        in
        let* () =
          expect_404 "downgraded top moderator" ~user:demoted
            ~slug:"ncpb-un-home" ()
        in
        let* () =
          exec conn "removal seed" q_insert_moderator (removed, cid, "top_mod")
        in
        let* () = exec conn "remove" q_remove_moderator (removed, cid) in
        let* () =
          expect_404 "removed top moderator" ~user:removed ~slug:"ncpb-un-home"
            ()
        in
        (* A session-shaped admin with no durable users.is_admin row. *)
        let* () =
          expect_404 "session-shaped admin" ~admin_session:true ~user:stranger
            ~slug:"ncpb-un-home" ()
        in
        (* A nonexistent community, and a legacy one, even to its own top
           moderator. *)
        let* () =
          expect_404 "missing community" ~user:owner ~slug:"ncpb-un-nothing" ()
        in
        let* legacy =
          insert_community ~name:"Ncpb Legacy" ~network:false conn
            "ncpb-un-legacy"
        in
        let* () =
          exec conn "legacy top_mod" q_insert_moderator (owner, legacy, "top_mod")
        in
        let* () =
          expect_404 "legacy community" ~user:owner ~slug:"ncpb-un-legacy" ()
        in
        (match !bodies with
        | [] -> Alcotest.fail "no 404 bodies captured"
        | first :: rest ->
            List.iteri
              (fun i body ->
                Alcotest.(check bool)
                  (Printf.sprintf "404 body %d identical" i)
                  true (String.equal first body))
              rest);
        (* Nothing published, and the draft is otherwise untouched apart from
           the fixtures this case installed. *)
        let* n = find conn "no final slug" q_count_by_slug "ncpb-un-final" in
        Alcotest.(check int) "nothing published" 0 n;
        let* state = find conn "state" q_community_state cid in
        Alcotest.(check bool) "still a private draft" true
          (contains state "|private|draft|true|false|false");
        (* An already-published community is the same generic 404 as every
           state above — the replay suite drives that end to end, and here it
           is only the durable precondition that differs. *)
        (* A draft whose accepted home relation is already gone at candidate
           resolution is deliberately NOT this 404: the provisioning store
           writes the community and its accepted relation atomically and the
           draft-protection rule forbids detaching it before publication, so
           the store classifies that shape as durable corruption. Reaching it
           at all needs direct SQL. Draft_unavailable still covers the real
           race — a removal that commits between candidate resolution and the
           lock. *)
        let* () = exec conn "remove relation" q_mark_removed rid in
        let* cookie, token = open_session "relation removed" ~url owner in
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-un-home")
            ~token
            ~body_fields:(fields ~slug:"ncpb-un-final" ())
            ()
        in
        check_generic_500 "home relation removed first" response body;
        check_no_credentials "home relation removed first" response body;
        let* n = find conn "still nothing" q_count_by_slug "ncpb-un-final" in
        Alcotest.(check int) "still nothing published" 0 n;
        Lwt.return_unit)

  (* === project verification drift === *)

  let verification_case =
    db_case "POST publish: publication survives every known project \
             verification state" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_vowner" in
        let publish_with label ~ext_id ~project_slug ~slug ~final ~status
            ~visibility ~indexable =
          let* project, cid, rid =
            make_draft conn ~user:owner ~ext_id ~project_slug ~slug
              ~name:"Ncpb Verification Home"
          in
          let* cookie, token, _ = open_setup label ~url ~slug owner in
          (* The drift lands between the GET and the POST. *)
          let* () = exec conn label q_set_verification (project, status) in
          let* before = snapshot label conn ~cid ~project ~rid in
          let* response, body =
            do_post ~conn ~url ~cookie ~target:(post_target slug) ~token
              ~body_fields:
                (fields ~name:"Ncpb Verification Home" ~slug:final ~visibility
                   ())
              ()
          in
          check_clean_redirect label (community_target final) response body;
          let* () =
            check_published label conn ~cid ~project ~rid ~before
              ~name:"Ncpb Verification Home" ~description:"<null>" ~slug:final
              ~old_slug:slug ~indexable ~discoverable:indexable
          in
          (* Publication never touches verification. *)
          let* after = find conn (label ^ ": verification") q_verification
                         project in
          Alcotest.(check string) (label ^ ": verification unchanged") status
            after;
          Lwt.return_unit
        in
        let* () =
          publish_with "verified" ~ext_id:956000010L
            ~project_slug:"ncpb-ver-a" ~slug:"ncpb-ver-a-home"
            ~final:"ncpb-ver-a-live" ~status:"verified" ~visibility:"public"
            ~indexable:true
        in
        let* () =
          publish_with "stale" ~ext_id:956000011L ~project_slug:"ncpb-ver-b"
            ~slug:"ncpb-ver-b-home" ~final:"ncpb-ver-b-live" ~status:"stale"
            ~visibility:"unlisted" ~indexable:false
        in
        publish_with "revoked" ~ext_id:956000012L ~project_slug:"ncpb-ver-c"
          ~slug:"ncpb-ver-c-home" ~final:"ncpb-ver-c-live" ~status:"revoked"
          ~visibility:"public" ~indexable:true)

  (* === replay === *)

  let replay_case =
    db_case "POST publish: replaying a succeeded submission publishes nothing \
             more and is the generic 404" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_rowner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000013L
            ~project_slug:"ncpb-replay" ~slug:"ncpb-replay-home"
            ~name:"Ncpb Replay Home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie, token, _ =
          open_setup "setup" ~url ~slug:"ncpb-replay-home" owner
        in
        let target = post_target "ncpb-replay-home" in
        let body_fields =
          fields ~name:"Ncpb Replay Home" ~slug:"ncpb-replay-live" ()
        in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token ~body_fields ()
        in
        check_clean_redirect "first" (community_target "ncpb-replay-live")
          response body;
        (* The very same token replayed. Dream's CSRF tokens are stateless and
           session-bound rather than one-shot, so the token still verifies:
           the store observing a non-draft community, not token consumption,
           is what stops the second publication. *)
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token ~body_fields ()
        in
        check_generic_404 "same-token replay" response body;
        Alcotest.(check (option string)) "no redirect" None
          (Dream.header response "Location");
        Alcotest.(check bool) "no final slug leaks" false
          (contains body "ncpb-replay-live");
        (* A freshly minted token replays to the same place. *)
        let* fresh = mint_token "fresh" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token:fresh ~body_fields ()
        in
        check_generic_404 "fresh-token replay" response body;
        (* Replaying against the new slug is the same answer: the community
           is no longer a draft. *)
        let* fresh = mint_token "new slug" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-replay-live")
            ~token:fresh ~body_fields ()
        in
        check_generic_404 "replay under the final slug" response body;
        (* A genuinely unusable token no longer dead-ends: it is refused
           without opening the store and answered by re-rendering the
           owner-authorized page. This community is no longer a draft, so
           that re-render is exactly the generic 404 its own GET gives. *)
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token:"ncpb-not-a-token"
            ~body_fields ()
        in
        check_generic_404 "bad token" response body;
        (* Exactly one publication, and no duplicate or partial state. *)
        let* n = find conn "final" q_count_by_slug "ncpb-replay-live" in
        Alcotest.(check int) "exactly one community owns the final slug" 1 n;
        let* old_n = find conn "old" q_count_by_slug "ncpb-replay-home" in
        Alcotest.(check int) "the old slug stays released" 0 old_n;
        check_published "after replays" conn ~cid ~project ~rid ~before
          ~name:"Ncpb Replay Home" ~description:"<null>"
          ~slug:"ncpb-replay-live" ~old_slug:"ncpb-replay-home"
          ~indexable:true ~discoverable:true)

  (* === durable failures === *)

  let inconsistent_case =
    db_case "POST publish: durable draft corruption is one generic \
             non-cacheable 500 with no partial publication" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_icowner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000014L
            ~project_slug:"ncpb-ic" ~slug:"ncpb-ic-home"
        in
        (* The setup page is opened while the draft is still sound; the shell
           is corrupted underneath it. *)
        let* cookie, token, _ =
          open_setup "setup" ~url ~slug:"ncpb-ic-home" owner
        in
        let* () = exec conn "drop sections" q_delete_sections cid in
        let* before = snapshot "corrupt" conn ~cid ~project ~rid in
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-ic-home")
            ~token
            ~body_fields:(fields ~slug:"ncpb-ic-live" ())
            ()
        in
        check_generic_500 "corrupt draft" response body;
        check_no_credentials "corrupt draft" response body;
        let* n = find conn "no publication" q_count_by_slug "ncpb-ic-live" in
        Alcotest.(check int) "nothing published" 0 n;
        check_unchanged "rolled back" conn ~cid ~project ~rid before)

  let storage_case =
    db_case "POST publish: a real database failure is one generic \
             non-cacheable 500 on both the store and the re-render path"
      (fun ~url _conn ->
        let poisoned =
          Uri.to_string
            (Uri.add_query_param' (Uri.of_string url)
               ("options", "-csearch_path=ncpb_void"))
        in
        (* A dedicated pool for this one case: the shared pipeline must keep
           talking to the real schema. *)
        let saved = !shared_pipeline in
        shared_pipeline := None;
        let poison_pipe = build_pipeline ~url:poisoned in
        shared_pipeline := saved;
        as_user 424244;
        let* response, token =
          do_get ~pipeline:poison_pipe ~url ~target:"/mint" ()
        in
        Alcotest.(check int) "mint 200" 200 (status_of response);
        let cookie = Pch.session_cookie "poisoned" response in
        let* response, body =
          do_post ~pipeline:poison_pipe ~url ~cookie
            ~target:(post_target "ncpb-anything") ~token
            ~body_fields:(fields ~slug:"ncpb-void-live" ())
            ()
        in
        check_generic_500 "poisoned store call" response body;
        let* response, body =
          do_post ~pipeline:poison_pipe ~url ~cookie
            ~target:(post_target "ncpb-anything") ~token
            ~body_fields:(fields ~slug:"Ncpb-Bad" ())
            ()
        in
        check_generic_500 "poisoned re-render" response body;
        Lwt.return_unit)

  (* === concurrency through HTTP === *)

  let same_draft_race_case =
    db_case "POST publish: two concurrent submissions for one draft publish \
             it exactly once; the loser is the generic 404" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_p1owner" in
        let* second = insert_user conn "ncpb_p1second" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000015L
            ~project_slug:"ncpb-race" ~slug:"ncpb-race-home"
            ~name:"Ncpb Race Home"
        in
        let* () =
          exec conn "second top_mod" q_insert_moderator (second, cid, "top_mod")
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie_a, token_a, _ =
          open_setup "publisher a" ~url ~slug:"ncpb-race-home" owner
        in
        let* cookie_b, token_b, _ =
          open_setup "publisher b" ~url ~slug:"ncpb-race-home" second
        in
        let* () = clear_limits conn in
        let target = post_target "ncpb-race-home" in
        (* Two independent sessions and tokens genuinely in flight at once
           over two pooled connections; the community lock inside the store
           serializes them without any sleep. *)
        let* (response_a, body_a), (response_b, body_b) =
          Lwt.both
            (do_post ~url ~cookie:cookie_a ~target ~token:token_a
               ~body_fields:
                 (fields ~name:"Ncpb Race Home" ~slug:"ncpb-race-a" ())
               ())
            (do_post ~url ~cookie:cookie_b ~target ~token:token_b
               ~body_fields:
                 (fields ~name:"Ncpb Race Home" ~slug:"ncpb-race-b" ())
               ())
        in
        let a_won = status_of response_a = 303 in
        let win, win_body, lose, lose_body, winning_slug, losing_slug =
          if a_won then
            (response_a, body_a, response_b, body_b, "ncpb-race-a",
             "ncpb-race-b")
          else
            (response_b, body_b, response_a, body_a, "ncpb-race-b",
             "ncpb-race-a")
        in
        check_clean_redirect "winner" (community_target winning_slug) win
          win_body;
        check_generic_404 "loser" lose lose_body;
        let* winners = find conn "winner row" q_count_by_slug winning_slug in
        Alcotest.(check int) "the winning slug exists" 1 winners;
        let* losers = find conn "loser row" q_count_by_slug losing_slug in
        Alcotest.(check int) "the losing slug was never taken" 0 losers;
        check_published "one publication only" conn ~cid ~project ~rid ~before
          ~name:"Ncpb Race Home" ~description:"<null>" ~slug:winning_slug
          ~old_slug:"ncpb-race-home" ~indexable:true ~discoverable:true)

  let same_slug_race_case =
    db_case "POST publish: two drafts racing for one final slug leave one \
             winner and a clean, retryable 409 loser" (fun ~url conn ->
        let* owner_a = insert_user conn "ncpb_s1owner" in
        let* owner_b = insert_user conn "ncpb_s2owner" in
        let* project_a, cid_a, rid_a =
          make_draft conn ~user:owner_a ~ext_id:956000016L
            ~project_slug:"ncpb-slug-a" ~slug:"ncpb-slug-a-home"
            ~name:"Ncpb Slug A"
        in
        let* project_b, cid_b, rid_b =
          make_draft conn ~user:owner_b ~ext_id:956000017L
            ~project_slug:"ncpb-slug-b" ~slug:"ncpb-slug-b-home"
            ~name:"Ncpb Slug B"
        in
        let* before_a = snapshot "before a" conn ~cid:cid_a ~project:project_a
                          ~rid:rid_a in
        let* before_b = snapshot "before b" conn ~cid:cid_b ~project:project_b
                          ~rid:rid_b in
        let* cookie_a, token_a, _ =
          open_setup "draft a" ~url ~slug:"ncpb-slug-a-home" owner_a
        in
        let* cookie_b, token_b, _ =
          open_setup "draft b" ~url ~slug:"ncpb-slug-b-home" owner_b
        in
        let* () = clear_limits conn in
        let body_fields =
          fields ~name:"Ncpb Shared Home" ~slug:"ncpb-shared-live" ()
        in
        let* (response_a, body_a), (response_b, body_b) =
          Lwt.both
            (do_post ~url ~cookie:cookie_a
               ~target:(post_target "ncpb-slug-a-home") ~token:token_a
               ~body_fields ())
            (do_post ~url ~cookie:cookie_b
               ~target:(post_target "ncpb-slug-b-home") ~token:token_b
               ~body_fields ())
        in
        let a_won = status_of response_a = 303 in
        let ( winner, winner_body, loser, loser_body, loser_slug, loser_cookie,
              loser_cid, loser_project, loser_rid, loser_before ) =
          if a_won then
            (response_a, body_a, response_b, body_b, "ncpb-slug-b-home",
             cookie_b, cid_b, project_b, rid_b, before_b)
          else
            (response_b, body_b, response_a, body_a, "ncpb-slug-a-home",
             cookie_a, cid_a, project_a, rid_a, before_a)
        in
        check_clean_redirect "winner" (community_target "ncpb-shared-live")
          winner winner_body;
        check_rerender "loser" ~status:409
          ~feedback:"That community address is already taken." ~slug:loser_slug
          loser loser_body;
        Alcotest.(check bool) "loser keeps its submission" true
          (contains loser_body "value='ncpb-shared-live'");
        let* n = find conn "shared" q_count_by_slug "ncpb-shared-live" in
        Alcotest.(check int) "exactly one community owns the slug" 1 n;
        (* The loser is byte-unchanged and still publishable. *)
        let* () =
          check_unchanged "loser unchanged" conn ~cid:loser_cid
            ~project:loser_project ~rid:loser_rid loser_before
        in
        let* token = mint_token "loser retry" ~url ~cookie:loser_cookie in
        let* response, body =
          do_post ~conn ~url ~cookie:loser_cookie
            ~target:(post_target loser_slug) ~token
            ~body_fields:
              (fields ~name:"Ncpb Shared Home" ~slug:"ncpb-shared-other" ())
            ()
        in
        check_clean_redirect "loser retries successfully"
          (community_target "ncpb-shared-other") response body;
        Lwt.return_unit)

  (* === draft protection and post-publication removal === *)

  let removal_case =
    db_case "POST publish: home removal is refused while the community is a \
             draft and works once it is published" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_remowner" in
        (* Two drafts, so each existing removal route is exercised on its
           own. *)
        let* project_a, cid_a, rid_a =
          make_draft conn ~user:owner ~ext_id:956000018L
            ~project_slug:"ncpb-rem-a" ~slug:"ncpb-rem-a-home"
            ~name:"Ncpb Rem A"
        in
        let* _project_b, _cid_b, rid_b =
          make_draft conn ~user:owner ~ext_id:956000019L
            ~project_slug:"ncpb-rem-b" ~slug:"ncpb-rem-b-home"
            ~name:"Ncpb Rem B"
        in
        let* _post = find conn "post" q_insert_post (cid_a, owner) in
        let* before_a = snapshot "before a" conn ~cid:cid_a ~project:project_a
                          ~rid:rid_a in
        let* cookie, token, _ =
          open_setup "setup a" ~url ~slug:"ncpb-rem-a-home" owner
        in
        (* 1. Forged removal while the community is still a draft: the
           existing safe redirect, and no mutation on either surface. *)
        let* response, body =
          do_bare_post ~conn ~url ~cookie
            ~target:
              (project_side_remove ~project:"ncpb-rem-a"
                 ~community:"ncpb-rem-a-home")
            ~token ()
        in
        check_clean_redirect "project-side refusal"
          (request_home_target "ncpb-rem-a") response body;
        let* token = mint_token "community side" ~url ~cookie in
        let* response, body =
          do_bare_post ~conn ~url ~cookie
            ~target:
              (community_side_remove ~community:"ncpb-rem-a-home"
                 ~project:"ncpb-rem-a")
            ~token ()
        in
        check_clean_redirect "community-side refusal"
          (settings_projects_target "ncpb-rem-a-home") response body;
        let* status = find conn "relation" q_relation_status rid_a in
        Alcotest.(check string) "relation still accepted" "accepted" status;
        let* () =
          check_unchanged "draft untouched by refused removals" conn ~cid:cid_a
            ~project:project_a ~rid:rid_a before_a
        in
        (* 2. Setup remains publishable, and publishing succeeds. *)
        let* token = mint_token "publish a" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-rem-a-home")
            ~token
            ~body_fields:(fields ~name:"Ncpb Rem A" ~slug:"ncpb-rem-a-live" ())
            ()
        in
        check_clean_redirect "published a" (community_target "ncpb-rem-a-live")
          response body;
        (* 3. Removal after publication succeeds through the project-side
           route, and the published community and its content remain. *)
        let* token = mint_token "remove a" ~url ~cookie in
        let* response, body =
          do_bare_post ~conn ~url ~cookie
            ~target:
              (project_side_remove ~project:"ncpb-rem-a"
                 ~community:"ncpb-rem-a-live")
            ~token ()
        in
        check_clean_redirect "project-side removal"
          (request_home_target "ncpb-rem-a") response body;
        let* status = find conn "relation after" q_relation_status rid_a in
        Alcotest.(check string) "relation removed" "removed" status;
        let* state = find conn "community after" q_community_state cid_a in
        Alcotest.(check bool) "the community stays published and public" true
          (contains state "|public|published|true|true|true");
        let* posts = find conn "posts" q_count_posts cid_a in
        Alcotest.(check int) "content survives removal" 1 posts;
        (* 4. The community-side route behaves the same on the second
           draft. *)
        let* cookie_b, token_b, _ =
          open_setup "setup b" ~url ~slug:"ncpb-rem-b-home" owner
        in
        let* response, body =
          do_post ~conn ~url ~cookie:cookie_b
            ~target:(post_target "ncpb-rem-b-home") ~token:token_b
            ~body_fields:(fields ~name:"Ncpb Rem B" ~slug:"ncpb-rem-b-live" ())
            ()
        in
        check_clean_redirect "published b" (community_target "ncpb-rem-b-live")
          response body;
        let* token_b = mint_token "remove b" ~url ~cookie:cookie_b in
        let* response, body =
          do_bare_post ~conn ~url ~cookie:cookie_b
            ~target:
              (community_side_remove ~community:"ncpb-rem-b-live"
                 ~project:"ncpb-rem-b")
            ~token:token_b ()
        in
        check_clean_redirect "community-side removal"
          (settings_projects_target "ncpb-rem-b-live") response body;
        let* status = find conn "relation b" q_relation_status rid_b in
        Alcotest.(check string) "relation b removed" "removed" status;
        Lwt.return_unit)

  (* === the mutation rate limiter really wraps this route === *)

  let rate_limit_case =
    db_case "POST publish: the route carries the shared \
             authenticated-mutation rate limit" (fun ~url conn ->
        let* () = clear_limits conn in
        let* cookie, token = open_session "rate limit" ~url 424245 in
        let target = post_target "ncpb-ratelimit" in
        (* The community does not exist, so every allowed attempt is the
           generic 404 and nothing durable is ever published. *)
        let rec drive n =
          if n > 12 then
            Alcotest.fail "the limiter never blocked within 12 attempts"
          else
            let* response, body =
              do_post ~url ~cookie ~target ~token
                ~body_fields:(fields ~slug:"ncpb-ratelimit-live" ())
                ()
            in
            if contains body "Too Many Attempts" then Lwt.return (n, response)
            else (
              Alcotest.(check int)
                (Printf.sprintf "attempt %d is the generic 404" n)
                404 (status_of response);
              drive (n + 1))
        in
        let* attempts, response = drive 1 in
        Alcotest.(check bool) "blocked only after several attempts" true
          (attempts > 1);
        Alcotest.(check int) "blocked page status" 200 (status_of response);
        clear_limits conn)

  (* === privacy sweep === *)

  let privacy_case =
    db_case "POST publish: no credential-shaped fixture reaches any response, \
             redirect, cookie, or the published community" (fun ~url conn ->
        let* owner = insert_user conn "ncpb_privowner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:956000001L
            ~project_slug:"ncpb-priv" ~slug:"ncpb-priv-home"
            ~name:"Ncpb Priv Home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* cookie, token, page =
          open_setup "setup" ~url ~slug:"ncpb-priv-home" owner
        in
        check_body_no_credentials "setup page" page;
        let target = post_target "ncpb-priv-home" in
        (* A rejected submission carrying every marker in fields the parser
           does not know. *)
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (List.map
                 (fun (_, marker) -> ("ncpb_" ^ marker, marker))
                 credential_markers
              @ fields ())
            ()
        in
        Alcotest.(check int) "422" 422 (status_of response);
        check_no_credentials "rejected submission" response body;
        (* A 409 body: only the intentionally submitted safe identity. *)
        let* _taken = insert_community ~name:"Ncpb Taken" conn "ncpb-priv-taken" in
        let* token = mint_token "conflict" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Priv Home" ~slug:"ncpb-priv-taken" ())
            ()
        in
        Alcotest.(check int) "409" 409 (status_of response);
        check_no_credentials "conflict" response body;
        (* A generic 404 body. *)
        let* token = mint_token "missing" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target:(post_target "ncpb-priv-nothing")
            ~token
            ~body_fields:(fields ~slug:"ncpb-priv-live" ())
            ()
        in
        check_generic_404 "missing community" response body;
        check_no_credentials "missing community" response body;
        (* The success redirect and the published community itself. *)
        let* token = mint_token "success" ~url ~cookie in
        let* response, body =
          do_post ~conn ~url ~cookie ~target ~token
            ~body_fields:
              (fields ~name:"Ncpb Priv Home" ~slug:"ncpb-priv-live"
                 ~description:"Safe body." ())
            ()
        in
        check_clean_redirect "success" (community_target "ncpb-priv-live")
          response body;
        check_no_credentials "success redirect" response body;
        let* response, page_body =
          do_get ~url ~cookie ~target:(community_target "ncpb-priv-live") ()
        in
        check_no_credentials "published community" response page_body;
        (* The intentionally supplied public identity is what survives. *)
        Alcotest.(check bool) "the supplied name is public" true
          (contains page_body "Ncpb Priv Home");
        check_published "privacy" conn ~cid ~project ~rid ~before
          ~name:"Ncpb Priv Home" ~description:"Safe body."
          ~slug:"ncpb-priv-live" ~old_slug:"ncpb-priv-home" ~indexable:true
          ~discoverable:true)

  let db_suite =
    [ public_success_case; unlisted_success_case; parser_rejection_case;
      slug_conflict_case; authority_case; unavailable_case;
      verification_case; replay_case; inconsistent_case; storage_case;
      same_draft_race_case; same_slug_race_case; removal_case;
      rate_limit_case; privacy_case
    ]
end

(* === Unpublished network-draft home protection (classification B) ===
   The rule that keeps a dedicated-community setup draft publishable: while
   a community is exactly the unpublished network draft (network, draft,
   private, neither indexable nor discoverable) and its accepted home
   carries exactly the provisioned shape the provisioning store wrote (NULL
   requester, NULL reviewer, NULL note, reviewed_at present, removed_at
   NULL), no authority may detach that relation — not the project steward,
   not the target top moderator, not a durable global administrator, and not
   an actor holding several of those at once. Without it, either removal
   surface could strand the draft: the publication store requires the
   relation, so a removed home leaves an orphan community carrying
   membership, moderation and shell rows that can never be published.

   The store is the authority; the two surfaces only stop advertising a
   control the store would refuse. This suite therefore covers the durable
   rule, both renderings, and forged same-origin POSTs against both route
   shapes, plus the resumption of ordinary removal after publication and the
   untouched legacy path.

   Database-gated (EARDE_TEST_DATABASE_URL, the same opt-in as Mod_scope)
   with its own reserved external-installation-id range
   955000001..955000999 (hence account ids 955100001..955100999, which also
   scope the permanent-project cleanup), phdp_% usernames, and phdp-%
   community slugs so no suite shares fixtures. Verified projects come only
   through the real draft/selection/finalization chain, drafts only through
   the real provisioning store, publications only through the real
   publication store and form, reviewed homes only through the real
   request/review stores. Every per-case wrapper disconnects
   deterministically. *)
module Phdp = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rms = Earde.Project_home_removal_store
  module Pv = Earde.Project_home_provisioning_store
  module Pub = Earde.Network_community_publication_store
  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store

  let error_str = Phrm.error_str
  let or_fail = Pod_store.or_fail
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let collect = Pod_read.collect
  let make_project = Phvr.make_project
  let insert_community = Phcv.insert_community
  let status_of = Gh_start_handler.status_of
  let ok_loader = Gh_start_handler.ok_loader

  (* Positional substring test, matching the sibling handler suites' shape. *)
  let contains haystack needle = Cprj_schema.contains haystack ~needle

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 955100001 AND 955100999)"
        ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 955100001 AND 955100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 955000001 AND 955000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phdp-%'"
      ; "DELETE FROM users WHERE username LIKE 'phdp_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 955000001 AND 955000999"
      ]

  (* === queries === *)

  let q_community_id =
    (Caqti_type.string ->! Caqti_type.int)
    "SELECT id FROM communities WHERE slug = $1"

  (* The exact lifecycle tuple the protection rule keys on. *)
  let q_lifecycle =
    (Caqti_type.int ->! Caqti_type.string)
    "SELECT visibility || '|' || onboarding_state || '|' || \
            is_network_community::text || '|' || indexable::text || '|' || \
            discoverable::text \
     FROM communities WHERE id = $1"

  let q_community_sig = Ncps.q_community_sig
  let q_relation_sig = Ncps.q_relation_sig
  let q_project_sig = Ncps.q_project_sig
  let q_relation_ids = Phvs.q_relation_ids
  let q_section_sigs = Phvs.q_section_sigs
  let q_channel_sigs = Phvs.q_channel_sigs

  let q_status =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT status FROM community_projects WHERE id = $1"

  let q_member_sig =
    (Caqti_type.int ->! Caqti_type.string)
    "SELECT COALESCE(string_agg(user_id::text, ',' ORDER BY user_id), \
                     '<none>') \
     FROM community_members WHERE community_id = $1"

  let q_moderator_sig =
    (Caqti_type.int ->! Caqti_type.string)
    "SELECT COALESCE(string_agg(user_id::text || ':' || role, ',' \
              ORDER BY user_id), '<none>') \
     FROM community_moderators WHERE community_id = $1"

  let q_steward_sig =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT COALESCE(string_agg(user_id::text || ':' || role, ',' \
              ORDER BY user_id), '<none>') \
     FROM project_stewards WHERE project_id = $1"

  (* The installation record the project's existing stewardship already
     references, so an extra steward row keeps a coherent provenance FK. *)
  let q_project_installation =
    (Caqti_type.int64 ->! Caqti_type.int64)
    "SELECT github_installation_record_id FROM project_stewards \
     WHERE project_id = $1 ORDER BY user_id LIMIT 1"

  let q_insert_post =
    (Caqti_type.(t2 int int) ->! Caqti_type.int)
    "INSERT INTO posts (title, content, community_id, user_id) \
     VALUES ('Phdp Post', 'Phdp body', $1, $2) RETURNING id"

  let q_count_posts =
    (Caqti_type.int ->! Caqti_type.int)
    "SELECT COUNT(*) FROM posts WHERE community_id = $1"

  (* Malformed-draft fixtures. Every value below still satisfies the
     production community_projects_status_shape_check: an 'accepted' row may
     legitimately carry a requester, a reviewer, and a note — that is exactly
     the reviewed accepted home the review store writes. So no constraint is
     relaxed to reach these branches; only the *combination* of that shape
     with an unpublished network draft is contradictory, and that is what the
     store must reject.

     Deliberately not reachable, and therefore not attempted: an accepted row
     with reviewed_at NULL. The shape CHECK forbids it at the database, so
     that branch of the store is schema-protected rather than test-driven. *)
  let q_set_requester =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "UPDATE community_projects SET requested_by_user_id = $2 WHERE id = $1"

  let q_set_reviewer =
    (Caqti_type.(t2 int64 int) ->. Caqti_type.unit)
    "UPDATE community_projects SET reviewed_by_user_id = $2 WHERE id = $1"

  let q_set_note =
    (Caqti_type.(t2 int64 string) ->. Caqti_type.unit)
    "UPDATE community_projects SET request_note = $2 WHERE id = $1"

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let with_second ~url f =
    let* conn2 = Caqti_lwt_unix.connect (Uri.of_string url) in
    let* conn2 = or_fail "second connect" conn2 in
    let (module C2 : Caqti_lwt.CONNECTION) = conn2 in
    Lwt.finalize (fun () -> f conn2) (fun () -> C2.disconnect ())

  (* === call helpers === *)

  let remove conn ~actor ~slug ~community =
    Rms.remove conn ~actor_user_id:actor ~project_slug:slug
      ~community_slug:community

  let remove_ok label conn ~actor ~slug ~community =
    let* r = remove conn ~actor ~slug ~community in
    match r with
    | Ok removed ->
        Alcotest.(check string)
          (label ^ ": resulting status")
          (Phr.string_of_status Phr.Removed)
          (Phr.string_of_status (Rms.resulting_status removed));
        Lwt.return_unit
    | Error e -> Alcotest.failf "%s: %s" label (error_str e)

  let remove_expect label expected conn ~actor ~slug ~community =
    let* r = remove conn ~actor ~slug ~community in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (error_str expected)
    | Error e ->
        Alcotest.(check string) label (error_str expected) (error_str e);
        Lwt.return_unit

  (* === fixtures === *)

  (* One complete unpublished dedicated-community draft, only through the
     real chain: permanent project via draft/selection/finalization, then the
     real atomic provisioning transaction. *)
  let make_draft ?(name = "Phdp Community Home") conn ~user ~ext_id
      ~project_slug ~slug =
    let* _inst, project = make_project conn ~user ~ext_id ~slug:project_slug in
    let identity =
      phvf_ok "identity fixture" (phvf_fields ~name ~slug ~description:"" ())
    in
    let* r = Pv.provision conn ~actor_user_id:user ~project_slug ~identity in
    let* () =
      match r with
      | Ok home ->
          Alcotest.(check string) "draft fixture slug" slug
            (Pv.community_slug home);
          Lwt.return_unit
      | Error _ -> Alcotest.failf "draft fixture failed for %s" slug
    in
    let* cid = find conn "draft community id" q_community_id slug in
    let* ids = collect conn "relation ids" q_relation_ids project in
    match ids with
    | [ rid ] -> Lwt.return (project, cid, rid)
    | ids ->
        Alcotest.failf "draft fixture: expected one relation, found %d"
          (List.length ids)

  (* Publication only through the real store and the real form, keeping the
     identity byte-identical so the community stays addressable at the same
     slug and only the lifecycle changes. *)
  let publish_draft label conn ~actor ~slug ~visibility
      ?(name = "Phdp Community Home") () =
    let value =
      ncpf_ok "publication fixture"
        (ncpf_fields ~name ~slug ~description:"" ~visibility ())
    in
    let* r =
      Pub.publish conn ~actor_user_id:actor ~current_community_slug:slug
        ~publication:value
    in
    match r with
    | Ok _ -> Lwt.return_unit
    | Error _ -> Alcotest.failf "%s: publication fixture failed" label

  let add_role conn ~user ~community role =
    exec conn "role fixture" Phrv.q_insert_moderator (user, community, role)

  let add_top_mod conn ~user ~community =
    add_role conn ~user ~community "top_mod"

  let add_member conn ~user ~community =
    exec conn "member fixture" Phrv.q_insert_member (user, community)

  let set_admin conn ~user flag =
    exec conn "admin fixture" Phrv.q_set_admin (user, flag)

  let add_steward conn ~project ~user ~installation =
    exec conn "steward fixture" Phvr.q_insert_steward
      (project, user, installation)

  (* A reviewed accepted home on an ordinary legacy community, produced
     exactly as production produces one. *)
  let reviewed_home label conn ~owner ~reviewer ~slug ~cid ~community_slug =
    let relation =
      phr_expect_ok (Phr.create_pending ~request_note:(Some "phdp note"))
    in
    let* r =
      Rq.create conn ~user_id:owner ~project_slug:slug ~target_community_id:cid
        ~relation
    in
    let* rid =
      match r with
      | Ok created -> Lwt.return (Rq.relation_id created)
      | Error _ -> Alcotest.failf "%s: request fixture failed" label
    in
    let* r =
      Rvs.review conn ~reviewer_user_id:reviewer ~project_slug:slug
        ~target_community_slug:community_slug ~decision:Rvs.Accept
    in
    match r with
    | Ok _ -> Lwt.return rid
    | Error _ -> Alcotest.failf "%s: review fixture failed" label

  (* === durable snapshots ===

     Everything a protected removal attempt must leave byte-identical: the
     complete community row, its exact lifecycle tuple, the whole relation
     row (timestamps included), the project row, membership, moderation,
     stewardship, the shell, and the community's content. *)
  let snapshot label conn ~cid ~project ~rid =
    let* community = find conn (label ^ ": community") q_community_sig cid in
    let* lifecycle = find conn (label ^ ": lifecycle") q_lifecycle cid in
    let* relation = find conn (label ^ ": relation") q_relation_sig rid in
    let* project_sig = find conn (label ^ ": project") q_project_sig project in
    let* members = find conn (label ^ ": members") q_member_sig cid in
    let* moderators = find conn (label ^ ": mods") q_moderator_sig cid in
    let* stewards = find conn (label ^ ": stewards") q_steward_sig project in
    let* sections = collect conn (label ^ ": sections") q_section_sigs cid in
    let* channels = collect conn (label ^ ": channels") q_channel_sigs cid in
    let* posts = find conn (label ^ ": posts") q_count_posts cid in
    Lwt.return
      (String.concat "||"
         ([ community; lifecycle; relation; project_sig; members; moderators;
            stewards; string_of_int posts ]
         @ sections @ channels))

  let check_unchanged label conn ~cid ~project ~rid before =
    let* after = snapshot label conn ~cid ~project ~rid in
    Alcotest.(check string)
      (label
     ^ ": community, lifecycle, relation, project, membership, moderation, \
        stewardship, shell and content all unchanged")
      before after;
    Lwt.return_unit

  (* The exact protected draft tuple, asserted directly rather than only
     through the snapshot, so a fixture that silently stopped being a draft
     could never make the protection assertions vacuous. *)
  let check_is_draft label conn cid =
    let* lifecycle = find conn (label ^ ": lifecycle") q_lifecycle cid in
    Alcotest.(check string)
      (label ^ ": private non-indexable non-discoverable network draft")
      "private|draft|true|false|false" lifecycle;
    Lwt.return_unit

  let check_status label conn rid expected =
    let* status = find conn (label ^ ": status") q_status rid in
    Alcotest.(check string) (label ^ ": relation status") expected status;
    Lwt.return_unit

  (* ================= Store: the draft is protected ================= *)

  (* Every durable authority, separately and then combined, against the same
     freshly provisioned draft. Each attempt must answer with the ordinary
     collapsed Removal_unavailable and leave the whole draft byte-identical.
     Both route-independent call shapes are the same store entry point, so
     the loop below is exactly what either HTTP route reaches. *)
  let protected_authorities_case =
    db_case
      "draft protection: no steward, top moderator, durable admin, or \
       multiply authorized actor can detach a provisioned home while the \
       community is an unpublished draft" (fun ~url:_ conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* moderator = insert_user conn "phdp_mod" in
        let* admin = insert_user conn "phdp_admin" in
        let* both = insert_user conn "phdp_both" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:955000001L
            ~project_slug:"phdp-alpha" ~slug:"phdp-alpha-home"
        in
        (* The provisioning actor is already the draft's top_mod; the other
           identities gain exactly one authority each, and the last gains
           all three at once. *)
        let* () = add_member conn ~user:moderator ~community:cid in
        let* () = add_top_mod conn ~user:moderator ~community:cid in
        let* () = set_admin conn ~user:admin true in
        let* installation =
          find conn "installation" q_project_installation project
        in
        let* () = add_steward conn ~project ~user:both ~installation in
        let* () = add_member conn ~user:both ~community:cid in
        let* () = add_top_mod conn ~user:both ~community:cid in
        let* () = set_admin conn ~user:both true in
        let* () = check_is_draft "fixture" conn cid in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* () =
          Lwt_list.iter_s
            (fun (who, actor) ->
              let* () =
                remove_expect
                  (who ^ " cannot detach a protected draft home")
                  Rms.Removal_unavailable conn ~actor ~slug:"phdp-alpha"
                  ~community:"phdp-alpha-home"
              in
              (* Nothing accumulates across attempts either. *)
              check_unchanged (who ^ ": after") conn ~cid ~project ~rid before)
            [ ("project steward", owner);
              ("target top moderator", moderator);
              ("durable global administrator", admin);
              ("multiply authorized actor", both)
            ]
        in
        let* () = check_status "after every attempt" conn rid "accepted" in
        let* () = check_is_draft "after every attempt" conn cid in
        (* The draft stays complete and therefore still publishable: the
           relation the publication store requires is intact, and so is the
           shell around it. *)
        let* sections = collect conn "sections" q_section_sigs cid in
        let* channels = collect conn "channels" q_channel_sigs cid in
        Alcotest.(check int) "General section survives" 1
          (List.length sections);
        Alcotest.(check int) "general channel survives" 1
          (List.length channels);
        (* Proof the draft really is still publishable — the whole point of
           the rule — through the real publication store. *)
        publish_draft "still publishable" conn ~actor:owner
          ~slug:"phdp-alpha-home" ~visibility:"public" ())

  (* An unauthorized actor must still learn nothing: protection must not
     become a second oracle that distinguishes drafts from anything else. *)
  let protected_unauthorized_case =
    db_case
      "draft protection: an unauthorized actor still receives the \
       authorization answer, not the protection answer" (fun ~url:_ conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* stranger = insert_user conn "phdp_stranger" in
        let* member = insert_user conn "phdp_member" in
        let* plain_mod = insert_user conn "phdp_plainmod" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:955000002L
            ~project_slug:"phdp-beta" ~slug:"phdp-beta-home"
        in
        let* () = add_member conn ~user:member ~community:cid in
        let* () = add_member conn ~user:plain_mod ~community:cid in
        let* () = add_role conn ~user:plain_mod ~community:cid "mod" in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        let* () =
          Lwt_list.iter_s
            (fun (who, actor) ->
              remove_expect who Rms.Actor_unauthorized conn ~actor
                ~slug:"phdp-beta" ~community:"phdp-beta-home")
            [ ("stranger", stranger); ("plain member", member);
              ("community mod", plain_mod)
            ]
        in
        check_unchanged "after" conn ~cid ~project ~rid before)

  (* ================= Store: publication lifts the protection ============ *)

  (* Public and Unlisted separately, and for each the three authorities
     separately — each on its own draft, because a successful removal
     consumes the relation. *)
  let published_removable_case =
    db_case
      "published network community: the provisioned home becomes removable \
       again by every durable authority, and the community and its content \
       remain" (fun ~url:_ conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* moderator = insert_user conn "phdp_mod" in
        let* admin = insert_user conn "phdp_admin" in
        let* () = set_admin conn ~user:admin true in
        let next_ext = ref 955000010L in
        let scenario (visibility, who, actor_of) index =
          let ext = !next_ext in
          next_ext := Int64.add ext 1L;
          let tag = Printf.sprintf "%s-%d" visibility index in
          let project_slug = "phdp-pub-" ^ tag in
          let slug = "phdp-pub-" ^ tag ^ "-home" in
          let label = visibility ^ " / " ^ who in
          let* project, cid, rid =
            make_draft conn ~user:owner ~ext_id:ext ~project_slug ~slug
          in
          let* () = add_member conn ~user:moderator ~community:cid in
          let* () = add_top_mod conn ~user:moderator ~community:cid in
          (* One post, so "the community and its content remain" is a real
             assertion rather than a vacuous one. *)
          let* _ = find conn "post fixture" q_insert_post (cid, owner) in
          let* () =
            publish_draft label conn ~actor:owner ~slug ~visibility ()
          in
          let* lifecycle = find conn (label ^ ": lifecycle") q_lifecycle cid in
          Alcotest.(check string)
            (label ^ ": published lifecycle")
            (if visibility = "public" then "public|published|true|true|true"
             else "public|published|true|false|false")
            lifecycle;
          let* community_before =
            find conn (label ^ ": community") q_community_sig cid
          in
          let* () =
            remove_ok label conn
              ~actor:(actor_of ~owner ~moderator ~admin)
              ~slug:project_slug ~community:slug
          in
          let* () = check_status label conn rid "removed" in
          (* The community, its lifecycle, its shell and its content all
             survive detaching the relation. *)
          let* community_after =
            find conn (label ^ ": community after") q_community_sig cid
          in
          Alcotest.(check string)
            (label ^ ": community row untouched by removal")
            community_before community_after;
          let* posts = find conn (label ^ ": posts") q_count_posts cid in
          Alcotest.(check int) (label ^ ": content remains") 1 posts;
          let* sections = collect conn (label ^ ": sections") q_section_sigs cid in
          let* channels = collect conn (label ^ ": channels") q_channel_sigs cid in
          Alcotest.(check int) (label ^ ": section remains") 1
            (List.length sections);
          Alcotest.(check int) (label ^ ": channel remains") 1
            (List.length channels);
          let* project_still =
            find conn (label ^ ": project") q_project_sig project
          in
          Alcotest.(check bool) (label ^ ": project remains") true
            (String.length project_still > 0);
          Lwt.return_unit
        in
        let authorities =
          [ ("steward", fun ~owner ~moderator:_ ~admin:_ -> owner);
            ("top moderator", fun ~owner:_ ~moderator ~admin:_ -> moderator);
            ("durable admin", fun ~owner:_ ~moderator:_ ~admin -> admin)
          ]
        in
        Lwt_list.iteri_s
          (fun i (visibility, (who, actor_of)) ->
            scenario (visibility, who, actor_of) i)
          (List.concat_map
             (fun v -> List.map (fun a -> (v, a)) authorities)
             [ "public"; "unlisted" ]))

  (* ================= Store: legacy behaviour is untouched ============== *)

  let legacy_reviewed_case =
    db_case
      "legacy community: an ordinary reviewed accepted home stays removable \
       exactly as before" (fun ~url:_ conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* reviewer = insert_user conn "phdp_mod" in
        let* _inst, _project =
          make_project conn ~user:owner ~ext_id:955000030L
            ~slug:"phdp-legacy"
        in
        (* A plain legacy community: not a network community at all, so no
           lifecycle protection can apply to it. *)
        let* cid = insert_community conn "phdp-legacy-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* rid =
          reviewed_home "legacy" conn ~owner ~reviewer ~slug:"phdp-legacy"
            ~cid ~community_slug:"phdp-legacy-home"
        in
        let* community_before = find conn "community" q_community_sig cid in
        let* () =
          remove_ok "legacy steward removal" conn ~actor:owner
            ~slug:"phdp-legacy" ~community:"phdp-legacy-home"
        in
        let* () = check_status "legacy" conn rid "removed" in
        let* community_after =
          find conn "community after" q_community_sig cid
        in
        Alcotest.(check string) "legacy community untouched" community_before
          community_after;
        Lwt.return_unit)

  (* ================= Store: malformed draft relations ================== *)

  let malformed_draft_case =
    db_case
      "malformed draft: an accepted home carrying review provenance under an \
       unpublished draft is corruption, not a removable relation"
      (fun ~url:_ conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* other = insert_user conn "phdp_other" in
        let next_ext = ref 955000040L in
        let scenario (what, corrupt) index =
          let ext = !next_ext in
          next_ext := Int64.add ext 1L;
          let project_slug = Printf.sprintf "phdp-mal-%d" index in
          let slug = Printf.sprintf "phdp-mal-%d-home" index in
          let* project, cid, rid =
            make_draft conn ~user:owner ~ext_id:ext ~project_slug ~slug
          in
          let* () = corrupt conn rid in
          let* before = snapshot what conn ~cid ~project ~rid in
          (* Every authority answers identically: corruption is never
             silently treated as an ordinary removable relation. *)
          let* () =
            remove_expect
              (what ^ ": steward")
              Rms.Inconsistent_data conn ~actor:owner ~slug:project_slug
              ~community:slug
          in
          let* () = check_unchanged (what ^ ": after") conn ~cid ~project ~rid
                      before in
          check_status (what ^ ": still accepted") conn rid "accepted"
        in
        Lwt_list.iteri_s
          (fun i (what, corrupt) -> scenario (what, corrupt) i)
          [ ( "non-NULL requester",
              fun conn rid -> exec conn "requester" q_set_requester (rid, other)
            );
            ( "non-NULL reviewer",
              fun conn rid -> exec conn "reviewer" q_set_reviewer (rid, other)
            );
            ( "non-NULL request note",
              fun conn rid ->
                exec conn "note" q_set_note (rid, "phdp forged note") )
          ])

  (* ================= Store: publication / removal concurrency ========== *)

  (* Both serializations, with two real connections and deterministic
     coordination — the losing side is made to observe committed state, never
     a sleep. The two stores share the project-first lock order, so neither
     ordering can deadlock. *)
  let removal_first_race_case =
    db_case
      "race: a removal that reaches the unpublished draft first is refused, \
       and publication then still succeeds" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:955000050L
            ~project_slug:"phdp-race" ~slug:"phdp-race-home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        with_second ~url (fun conn2 ->
            (* The removal runs first and completes on its own connection,
               against the committed draft state. *)
            let* () =
              remove_expect "removal reaches the draft first"
                Rms.Removal_unavailable conn2 ~actor:owner ~slug:"phdp-race"
                ~community:"phdp-race-home"
            in
            let* () = check_unchanged "after refusal" conn ~cid ~project ~rid
                        before in
            let* () = check_status "still accepted" conn rid "accepted" in
            (* Publication then proceeds on the other connection. *)
            let* () =
              publish_draft "publication after refused removal" conn
                ~actor:owner ~slug:"phdp-race-home" ~visibility:"public" ()
            in
            let* lifecycle = find conn "lifecycle" q_lifecycle cid in
            Alcotest.(check string) "published after the refused removal"
              "public|published|true|true|true" lifecycle;
            Lwt.return_unit))

  let publication_first_race_case =
    db_case
      "race: when publication commits first, the subsequent removal succeeds \
       normally and the published community remains" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:955000051L
            ~project_slug:"phdp-race2" ~slug:"phdp-race2-home"
        in
        let* _ = find conn "post fixture" q_insert_post (cid, owner) in
        with_second ~url (fun conn2 ->
            (* Publication commits on the second connection while the first
               holds nothing; the removal that follows observes only the
               published state. *)
            let* () =
              publish_draft "publication first" conn2 ~actor:owner
                ~slug:"phdp-race2-home" ~visibility:"unlisted" ()
            in
            let* lifecycle = find conn "lifecycle" q_lifecycle cid in
            Alcotest.(check string) "published first"
              "public|published|true|false|false" lifecycle;
            let* community_before = find conn "community" q_community_sig cid in
            let* () =
              remove_ok "removal after publication" conn ~actor:owner
                ~slug:"phdp-race2" ~community:"phdp-race2-home"
            in
            let* () = check_status "removed" conn rid "removed" in
            let* community_after =
              find conn "community after" q_community_sig cid
            in
            Alcotest.(check string) "published community remains"
              community_before community_after;
            let* posts = find conn "posts" q_count_posts cid in
            Alcotest.(check int) "content remains" 1 posts;
            let* project_still = find conn "project" q_project_sig project in
            Alcotest.(check bool) "project remains" true
              (String.length project_still > 0);
            Lwt.return_unit))

  (* A publication that loses its authority mid-flight leaves the draft
     unpublished — and therefore still protected. *)
  let publication_fails_case =
    db_case
      "race: when publication fails, the draft home stays protected"
      (fun ~url:_ conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* outsider = insert_user conn "phdp_outsider" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:955000052L
            ~project_slug:"phdp-fail" ~slug:"phdp-fail-home"
        in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        (* An actor with no publication authority: the draft stays a draft. *)
        let value =
          ncpf_ok "publication"
            (ncpf_fields ~name:"Phdp Community Home" ~slug:"phdp-fail-home"
               ~description:"" ~visibility:"public" ())
        in
        let* r =
          Pub.publish conn ~actor_user_id:outsider
            ~current_community_slug:"phdp-fail-home" ~publication:value
        in
        (match r with
        | Ok _ -> Alcotest.fail "unauthorized publication unexpectedly succeeded"
        | Error _ -> ());
        let* () = check_is_draft "after failed publication" conn cid in
        let* () =
          remove_expect "still protected" Rms.Removal_unavailable conn
            ~actor:owner ~slug:"phdp-fail" ~community:"phdp-fail-home"
        in
        check_unchanged "after" conn ~cid ~project ~rid before)

  let store_suite =
    [ protected_authorities_case; protected_unauthorized_case;
      published_removable_case; legacy_reviewed_case; malformed_draft_case;
      removal_first_race_case; publication_first_race_case;
      publication_fails_case
    ]

  (* ================= HTTP: the real production pipeline ================ *)

  (* One shared single-connection sql_pool for the whole suite, exactly as
     the sibling removal-handler suite does: nothing closes a
     Dream.sql_pool, and a fresh pool per request would exhaust
     max_connections. The session identity is swapped through a ref; cases
     run sequentially. Everything else is the real production shape — the
     real router paths bound to the real handlers. *)
  let shared_identity : (int * bool) option ref = ref None
  let shared_pipeline = ref None

  let pipeline_for ~url =
    match !shared_pipeline with
    | Some pipeline -> pipeline
    | None ->
        let pipeline =
          Dream.sql_pool ~size:1 url @@ Dream.set_secret gck_secret
          @@ Dream.memory_sessions
          @@ (fun handler request ->
               match !shared_identity with
               | None -> handler request
               | Some (uid, is_admin) ->
                   let* () =
                     Dream.set_session_field request "user_id"
                       (string_of_int uid)
                   in
                   let* () =
                     if is_admin then
                       Dream.set_session_field request "is_admin" "true"
                     else Lwt.return_unit
                   in
                   handler request)
          @@ Dream.router
               [ (* A protected surface renders no form, so there is no
                    page-embedded CSRF field to lift: a forged submission
                    must mint its own token, which is exactly what an
                    attacker with a live session would do. *)
                 Dream.get "/mint" (fun req ->
                     Dream.respond (Dream.csrf_token req));
                 Dream.get "/c/:slug/settings"
                   Earde.Handlers.community_settings_handler;
                 Dream.get "/projects/:slug/request-home" (fun req ->
                     Earde.Project_home_request_handlers
                     .make_project_home_choice_handler ~mode:Ob.Public req);
                 Dream.post
                   "/projects/:project_slug/community-home/:community_slug/remove"
                   (fun req ->
                     Earde.Project_home_removal_handlers
                     .make_project_side_home_removal_handler ~mode:Ob.Public
                       ~load_config:(fun () -> ok_loader ())
                       req);
                 Dream.post "/c/:community_slug/projects/:project_slug/remove-home"
                   (fun req ->
                     Earde.Project_home_removal_handlers
                     .make_community_side_home_removal_handler ~mode:Ob.Public
                       ~load_config:(fun () -> ok_loader ())
                       req);
               ]
        in
        shared_pipeline := Some pipeline;
        pipeline

  let as_user ?(admin_session = false) uid =
    shared_identity := Some (uid, admin_session)

  let do_get ~url ~target () =
    let pipeline = pipeline_for ~url in
    let* response = pipeline (Dream.request ~method_:`GET ~target "") in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* A live session cookie plus a valid framework CSRF token, minted
     independently of any rendered page. *)
  let mint ~url =
    let pipeline = pipeline_for ~url in
    let* response = pipeline (Dream.request ~method_:`GET ~target:"/mint" "") in
    let cookie = Pch.session_cookie "mint" response in
    let* token = Dream.body response in
    Lwt.return (cookie, token)

  let do_post ~url ~cookie ~target ~token () =
    let pipeline = pipeline_for ~url in
    let headers =
      [ ("Origin", "https://earde.com");
        ("Content-Type", "application/x-www-form-urlencoded");
        ("Cookie", cookie)
      ]
    in
    pipeline
      (Dream.request ~method_:`POST ~target ~headers
         (Pch.form_body [ ("dream.csrf", token) ]))

  let check_clean_redirect label expected response =
    Alcotest.(check int) (label ^ ": 303") 303 (status_of response);
    Alcotest.(check (option string)) (label ^ ": exact Location, no query or \
      fragment") (Some expected) (Dream.header response "Location");
    Alcotest.(check (option string)) (label ^ ": no-store") (Some "no-store")
      (Dream.header response "Cache-Control");
    Alcotest.(check (option string)) (label ^ ": no-referrer")
      (Some "no-referrer")
      (Dream.header response "Referrer-Policy");
    let* body = Dream.body response in
    Alcotest.(check string) (label ^ ": empty body") "" body;
    Lwt.return_unit

  (* Nothing anywhere in a response may name the protection reason, the
     lifecycle, the authority, or the relation's provenance. *)
  let check_no_reason label response body =
    let headers =
      String.concat "\n"
        (List.map (fun (k, v) -> k ^ ": " ^ v) (Dream.all_headers response))
    in
    let blob = body ^ "\n" ^ headers in
    List.iter
      (fun (what, needle) ->
        Alcotest.(check bool) (label ^ ": free of " ^ what) false
          (contains blob needle))
      [ ("onboarding state", "onboarding_state"); ("draft marker", "draft");
        ("network marker", "is_network_community");
        ("relation table", "community_projects");
        ("index name", "one_active_home");
        ("store variant", "Removal_unavailable");
        ("authority source", "top_mod"); ("steward source", "project_stewards")
      ]

  (* ================= HTTP: project-side rendering ====================== *)

  let project_side_render_case =
    db_case
      "project side: the accepted-home page of an unpublished draft carries \
       no removal form and no removal action, and explains why"
      (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* _project, cid, _rid =
          make_draft conn ~user:owner ~ext_id:955000060L
            ~project_slug:"phdp-render" ~slug:"phdp-render-home"
        in
        let* () = check_is_draft "fixture" conn cid in
        as_user owner;
        let* response, body =
          do_get ~url ~target:"/projects/phdp-render/request-home" ()
        in
        Alcotest.(check int) "200" 200 (status_of response);
        (* The accepted state itself still renders. *)
        Alcotest.(check bool) "accepted copy" true
          (contains body "Community home connected");
        (* The load-bearing assertion: no action path a forged submission
           could be lifted from. Asserted on the removal route and controls
           specifically — the surrounding site chrome legitimately carries
           its own unrelated forms, so a blanket "<form" count on the whole
           page would prove nothing about this fragment. *)
        Alcotest.(check bool) "no removal action emitted" false
          (contains body "community-home");
        Alcotest.(check bool) "no removal form element" false
          (contains body "phrm-removal-form");
        Alcotest.(check bool) "no remove control" false
          (contains body "Remove home");
        Alcotest.(check bool) "no removal heading" false
          (contains body "Remove community home");
        (* Nothing stands in for the missing form: no hidden field carries
           the identities the action path would have. *)
        Alcotest.(check bool) "no hidden project slug" false
          (contains body "name='project_slug'");
        Alcotest.(check bool) "no hidden community slug" false
          (contains body "name='community_slug'");
        (* The restrained explanation is present and promises nothing. *)
        Alcotest.(check bool) "draft-integrity copy" true
          (contains body
             "This project home is part of an unpublished community setup \
              draft.");
        Alcotest.(check bool) "next step named" true
          (contains body
             "Complete setup and publish the community before detaching it.");
        Alcotest.(check bool) "no destructive alternative" false
          (contains body "Delete");
        (* No setup link: project stewardship never establishes that the
           viewer may reach the community's setup surface. *)
        Alcotest.(check bool) "no setup link inferred from stewardship" false
          (contains body "/c/phdp-render-home/setup");
        Lwt.return_unit)

  let project_side_published_render_case =
    db_case
      "project side: Public, Unlisted and legacy reviewed accepted homes all \
       keep the existing removal form" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* reviewer = insert_user conn "phdp_mod" in
        let check label ~project_slug ~community_slug =
          as_user owner;
          let* response, body =
            do_get ~url
              ~target:("/projects/" ^ project_slug ^ "/request-home")
              ()
          in
          Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
          Alcotest.(check bool) (label ^ ": removal form present") true
            (contains body
               (Printf.sprintf "action='/projects/%s/community-home/%s/remove'"
                  project_slug community_slug));
          Alcotest.(check bool) (label ^ ": remove control") true
            (contains body "Remove home");
          Alcotest.(check bool) (label ^ ": association-only warning") true
            (contains body "This removes the association only.");
          Alcotest.(check bool) (label ^ ": no draft copy") false
            (contains body "unpublished community setup draft");
          Lwt.return_unit
        in
        (* Published Public. *)
        let* _p, _c, _r =
          make_draft conn ~user:owner ~ext_id:955000061L
            ~project_slug:"phdp-rpub" ~slug:"phdp-rpub-home"
        in
        let* () =
          publish_draft "public" conn ~actor:owner ~slug:"phdp-rpub-home"
            ~visibility:"public" ()
        in
        let* () = check "public" ~project_slug:"phdp-rpub"
                    ~community_slug:"phdp-rpub-home" in
        (* Published Unlisted. *)
        let* _p, _c, _r =
          make_draft conn ~user:owner ~ext_id:955000062L
            ~project_slug:"phdp-runl" ~slug:"phdp-runl-home"
        in
        let* () =
          publish_draft "unlisted" conn ~actor:owner ~slug:"phdp-runl-home"
            ~visibility:"unlisted" ()
        in
        let* () = check "unlisted" ~project_slug:"phdp-runl"
                    ~community_slug:"phdp-runl-home" in
        (* Legacy reviewed accepted home. *)
        let* _inst, _project =
          make_project conn ~user:owner ~ext_id:955000063L ~slug:"phdp-rleg"
        in
        let* cid = insert_community conn "phdp-rleg-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* _rid =
          reviewed_home "legacy render" conn ~owner ~reviewer
            ~slug:"phdp-rleg" ~cid ~community_slug:"phdp-rleg-home"
        in
        check "legacy reviewed" ~project_slug:"phdp-rleg"
          ~community_slug:"phdp-rleg-home")

  let project_side_pending_case =
    db_case
      "project side: the pending and chooser states are unchanged by the \
       protection rule" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* _inst, _project =
          make_project conn ~user:owner ~ext_id:955000064L ~slug:"phdp-pend"
        in
        let* cid = insert_community conn "phdp-pend-home" in
        let relation =
          phr_expect_ok (Phr.create_pending ~request_note:(Some "phdp note"))
        in
        let* r =
          Rq.create conn ~user_id:owner ~project_slug:"phdp-pend"
            ~target_community_id:cid ~relation
        in
        let* () =
          match r with
          | Ok _ -> Lwt.return_unit
          | Error _ -> Alcotest.fail "pending fixture failed"
        in
        as_user owner;
        let* response, body =
          do_get ~url ~target:"/projects/phdp-pend/request-home" ()
        in
        Alcotest.(check int) "200" 200 (status_of response);
        Alcotest.(check bool) "pending copy" true
          (contains body "Home request pending");
        Alcotest.(check bool) "no removal form" false
          (contains body "community-home");
        Alcotest.(check bool) "no draft copy" false
          (contains body "unpublished community setup draft");
        Lwt.return_unit)

  (* ================= HTTP: community-settings rendering =============== *)

  let settings_render_case =
    db_case
      "community settings: a draft's top moderator and a durable admin both \
       see the connected project without any removal form, alongside the \
       existing setup link" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* admin = insert_user conn "phdp_admin" in
        let* _project, cid, _rid =
          make_draft conn ~user:owner ~ext_id:955000070L
            ~project_slug:"phdp-set" ~slug:"phdp-set-home"
        in
        let* () = set_admin conn ~user:admin true in
        let* () = check_is_draft "fixture" conn cid in
        let check label ~actor ~admin_session =
          as_user ~admin_session actor;
          let* response, body =
            do_get ~url ~target:"/c/phdp-set-home/settings?panel=projects" ()
          in
          Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
          (* The connected project's identity is still shown. *)
          Alcotest.(check bool) (label ^ ": connected project identity") true
            (contains body "phdp-set");
          Alcotest.(check bool) (label ^ ": panel present") true
            (contains body "Connected projects");
          (* But no removal control anywhere. *)
          Alcotest.(check bool) (label ^ ": no removal action") false
            (contains body "remove-home");
          Alcotest.(check bool) (label ^ ": no remove control") false
            (contains body "Remove home");
          Alcotest.(check bool) (label ^ ": draft-integrity copy") true
            (contains body "unpublished community setup draft");
          Alcotest.(check bool) (label ^ ": association-only warning replaced")
            false
            (contains body "This removes the association only.");
          (* The existing publication navigation is preserved. *)
          Alcotest.(check bool) (label ^ ": setup and publish link") true
            (contains body "/c/phdp-set-home/setup");
          Alcotest.(check bool) (label ^ ": setup link copy") true
            (contains body "Complete setup and publish");
          Lwt.return_unit
        in
        let* () = check "top moderator" ~actor:owner ~admin_session:false in
        check "durable admin" ~actor:admin ~admin_session:true)

  let settings_published_render_case =
    db_case
      "community settings: Public, Unlisted and legacy communities keep the \
       existing removal form" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* reviewer = insert_user conn "phdp_mod" in
        let check label ~actor ~community_slug ~project_slug =
          as_user actor;
          let* response, body =
            do_get ~url
              ~target:("/c/" ^ community_slug ^ "/settings?panel=projects")
              ()
          in
          Alcotest.(check int) (label ^ ": 200") 200 (status_of response);
          Alcotest.(check bool) (label ^ ": removal form present") true
            (contains body
               (Printf.sprintf "action='/c/%s/projects/%s/remove-home'"
                  community_slug project_slug));
          Alcotest.(check bool) (label ^ ": remove control") true
            (contains body "Remove home");
          Alcotest.(check bool) (label ^ ": no draft copy") false
            (contains body "unpublished community setup draft");
          Lwt.return_unit
        in
        let* _p, _c, _r =
          make_draft conn ~user:owner ~ext_id:955000071L
            ~project_slug:"phdp-spub" ~slug:"phdp-spub-home"
        in
        let* () =
          publish_draft "public" conn ~actor:owner ~slug:"phdp-spub-home"
            ~visibility:"public" ()
        in
        let* () = check "public" ~actor:owner ~community_slug:"phdp-spub-home"
                    ~project_slug:"phdp-spub" in
        let* _p, _c, _r =
          make_draft conn ~user:owner ~ext_id:955000072L
            ~project_slug:"phdp-sunl" ~slug:"phdp-sunl-home"
        in
        let* () =
          publish_draft "unlisted" conn ~actor:owner ~slug:"phdp-sunl-home"
            ~visibility:"unlisted" ()
        in
        let* () = check "unlisted" ~actor:owner ~community_slug:"phdp-sunl-home"
                    ~project_slug:"phdp-sunl" in
        let* _inst, _project =
          make_project conn ~user:owner ~ext_id:955000073L ~slug:"phdp-sleg"
        in
        let* cid = insert_community conn "phdp-sleg-home" in
        let* () = add_top_mod conn ~user:reviewer ~community:cid in
        let* _rid =
          reviewed_home "legacy settings" conn ~owner ~reviewer
            ~slug:"phdp-sleg" ~cid ~community_slug:"phdp-sleg-home"
        in
        check "legacy" ~actor:reviewer ~community_slug:"phdp-sleg-home"
          ~project_slug:"phdp-sleg")

  let settings_unauthorized_case =
    db_case
      "community settings: an ordinary moderator gains no management panel \
       on a protected draft, and the public page gains no controls"
      (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* plain_mod = insert_user conn "phdp_plainmod" in
        let* _project, cid, _rid =
          make_draft conn ~user:owner ~ext_id:955000074L
            ~project_slug:"phdp-un" ~slug:"phdp-un-home"
        in
        let* () = add_member conn ~user:plain_mod ~community:cid in
        let* () = add_role conn ~user:plain_mod ~community:cid "mod" in
        as_user plain_mod;
        let* response, body =
          do_get ~url ~target:"/c/phdp-un-home/settings?panel=projects" ()
        in
        Alcotest.(check int) "200" 200 (status_of response);
        (* No panel at all: the route never loads the read model for a
           non-top-mod, so neither identities nor copy nor controls appear. *)
        Alcotest.(check bool) "no management panel" false
          (contains body "Connected projects");
        Alcotest.(check bool) "no removal action" false
          (contains body "remove-home");
        Alcotest.(check bool) "no draft-integrity copy either" false
          (contains body "unpublished community setup draft");
        Lwt.return_unit)

  (* ================= HTTP: forged POSTs against both routes =========== *)

  (* A valid same-origin, valid-CSRF submission that no rendered page
     offered. Both route shapes must reach the store, receive the ordinary
     Removal_unavailable, and follow the handlers' existing safe
     current-state redirect — the same destination a successful removal
     uses, so the response is not an oracle either. *)
  let forged_post_case =
    db_case
      "forged POST: both route shapes reach the store, are refused, and \
       redirect exactly as an ordinary unavailable removal" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:955000080L
            ~project_slug:"phdp-forge" ~slug:"phdp-forge-home"
        in
        let* () = check_is_draft "fixture" conn cid in
        let* before = snapshot "before" conn ~cid ~project ~rid in
        as_user owner;
        let* cookie, token = mint ~url in
        let attempt label ~target ~expected =
          let* response = do_post ~url ~cookie ~target ~token () in
          let* () = check_clean_redirect label expected response in
          let* body = Dream.body response in
          check_no_reason label response body;
          (* No mutation of any kind. *)
          let* () = check_unchanged (label ^ ": durable state") conn ~cid
                      ~project ~rid before in
          check_status (label ^ ": still accepted") conn rid "accepted"
        in
        let* () =
          attempt "project-side route"
            ~target:
              "/projects/phdp-forge/community-home/phdp-forge-home/remove"
            ~expected:"/projects/phdp-forge/request-home"
        in
        let* () =
          attempt "community-side route"
            ~target:"/c/phdp-forge-home/projects/phdp-forge/remove-home"
            ~expected:"/c/phdp-forge-home/settings?panel=projects"
        in
        (* And the draft is still publishable afterwards. *)
        publish_draft "publishable after forged POSTs" conn ~actor:owner
          ~slug:"phdp-forge-home" ~visibility:"public" ())

  (* The same two routes, after publication: the identical submission now
     commits, proving the redirect above really was the shared destination
     and not a protection-specific response. *)
  let forged_post_after_publication_case =
    db_case
      "after publication: the same submission against each route removes the \
       home and lands on the same destination" (fun ~url conn ->
        let* owner = insert_user conn "phdp_owner" in
        let scenario label ~ext ~project_slug ~slug ~target ~expected =
          let* _project, cid, rid =
            make_draft conn ~user:owner ~ext_id:ext ~project_slug ~slug
          in
          let* () =
            publish_draft label conn ~actor:owner ~slug ~visibility:"public" ()
          in
          let* community_before =
            find conn (label ^ ": community") q_community_sig cid
          in
          as_user owner;
          let* cookie, token = mint ~url in
          let* response = do_post ~url ~cookie ~target ~token () in
          let* () = check_clean_redirect label expected response in
          let* () = check_status (label ^ ": removed") conn rid "removed" in
          let* community_after =
            find conn (label ^ ": community after") q_community_sig cid
          in
          Alcotest.(check string)
            (label ^ ": published community remains")
            community_before community_after;
          Lwt.return_unit
        in
        let* () =
          scenario "project-side route" ~ext:955000081L
            ~project_slug:"phdp-fpub" ~slug:"phdp-fpub-home"
            ~target:"/projects/phdp-fpub/community-home/phdp-fpub-home/remove"
            ~expected:"/projects/phdp-fpub/request-home"
        in
        scenario "community-side route" ~ext:955000082L
          ~project_slug:"phdp-fpub2" ~slug:"phdp-fpub2-home"
          ~target:"/c/phdp-fpub2-home/projects/phdp-fpub2/remove-home"
          ~expected:"/c/phdp-fpub2-home/settings?panel=projects")

  let http_suite =
    [ project_side_render_case; project_side_published_render_case;
      project_side_pending_case; settings_render_case;
      settings_published_render_case; settings_unauthorized_case;
      forged_post_case; forged_post_after_publication_case
    ]

end

(* === Project-home lifecycle audit
   (Project_home_audit + project_home_audit_events) ===
   The append-only audit trail of the six home-lifecycle transitions:
   the schema itself (closed action vocabulary, required subject FKs,
   SET NULL actor retention, RESTRICT-protected subjects, the four
   listing indexes, the down/up round-trip, and the absence of any
   private or credential-shaped column), exactly one event per
   successful store transition through the real production stores, no
   event on any refused/failed/replayed path, whole-mutation rollback
   when the audit insertion itself fails, event uniqueness under
   concurrent attempts, and actor deletion/privacy. Fixtures use the
   reserved external-installation-id range 958000001..958000999 (hence
   namespace ids 958100001..958100999), phau_% usernames, and phau-%
   community slugs so no suite shares fixtures. Events come only
   through the real stores except in the schema suite, whose raw rows
   probe the table's own constraints. Every per-case wrapper
   disconnects deterministically. *)
module Phau = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store
  module Rms = Earde.Project_home_removal_store
  module Pv = Earde.Project_home_provisioning_store
  module Pub = Earde.Network_community_publication_store

  let or_fail = Pod_store.or_fail
  let reject = Pod_schema.reject
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let collect = Pod_read.collect
  let make_project = Phvr.make_project
  let insert_community = Phcv.insert_community
  let make_draft = Ncps.make_draft
  let status_str = Phr.string_of_status
  let contains haystack needle = Cprj_schema.contains haystack ~needle

  (* Failure-injection DDL is dropped first so a crashed case can never
     leave a trigger behind; audit events must go before projects and
     communities because their subject FKs deliberately RESTRICT-protect
     both. Then the shared dependency order of the sibling suites. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DROP TRIGGER IF EXISTS phau_fail_audit ON project_home_audit_events"
      ; "DROP TRIGGER IF EXISTS phau_fail_business ON community_projects"
      ; "DROP FUNCTION IF EXISTS phau_fail_fn()"
      ; "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 958100001 AND 958100999)"
      ; "DELETE FROM project_home_audit_events \
         WHERE community_id IN \
           (SELECT id FROM communities WHERE slug LIKE 'phau-%')"
      ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 958100001 AND 958100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 958000001 AND 958000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phau-%'"
      ; "DELETE FROM users WHERE username LIKE 'phau_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 958000001 AND 958000999"
      ]

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* === event observation === *)

  (* One tuple per event, in append (id) order. The project is the query
     key, so each row reduces to action, actor, community, relation. *)
  let q_events_for_project =
    (Caqti_type.int64
     ->* Caqti_type.(t2 (t2 string (option int)) (t2 int int64)))
    "SELECT action, actor_user_id, community_id, relation_id \
     FROM project_home_audit_events WHERE project_id = $1 ORDER BY id"

  let q_count_events =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM project_home_audit_events WHERE project_id = $1"

  (* Timestamp coherence: every event carries a real timestamp no older
     than its subject relation's own creation and no newer than now. *)
  let q_coherent_count =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM project_home_audit_events e \
     JOIN community_projects r ON r.id = e.relation_id \
     WHERE e.project_id = $1 \
       AND e.created_at >= r.created_at AND e.created_at <= NOW()"

  (* The complete first event row as one text signature, for
     append-only/immutability assertions across later transitions. *)
  let q_first_event_sig =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT COALESCE((SELECT e::text FROM project_home_audit_events e \
                      WHERE e.project_id = $1 ORDER BY e.id LIMIT 1), \
                     '<none>')"

  (* Every stored byte of a project's events, for the boolean
     credential-absence sweep. *)
  let q_audit_blob =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT COALESCE(string_agg(e::text, '|'), '<none>') \
     FROM project_home_audit_events e WHERE e.project_id = $1"

  let event_t = Alcotest.(pair (pair string (option int)) (pair int int64))

  let check_events label conn ~project expected =
    let* rows =
      collect conn (label ^ ": events") q_events_for_project project
    in
    Alcotest.(check (list event_t)) (label ^ ": exact events") expected rows;
    let* coherent = find conn (label ^ ": coherent") q_coherent_count project in
    Alcotest.(check int)
      (label ^ ": every event timestamp coherent")
      (List.length expected) coherent;
    Lwt.return_unit

  let check_event_count label conn ~project expected =
    let* n = find conn (label ^ ": count") q_count_events project in
    Alcotest.(check int) (label ^ ": event count") expected n;
    Lwt.return_unit

  (* === store call helpers === *)

  let request_ok label conn ~user ~slug ~community =
    let* created =
      Phrq.create_ok label conn ~user ~slug ~community (phr_fresh_pending ())
    in
    Lwt.return (Rq.relation_id created)

  let review conn ~reviewer ~slug ~community decision =
    Rvs.review conn ~reviewer_user_id:reviewer ~project_slug:slug
      ~target_community_slug:community ~decision

  let review_ok label conn ~reviewer ~slug ~community decision expected =
    let* r = review conn ~reviewer ~slug ~community decision in
    match r with
    | Ok reviewed ->
        Alcotest.(check string)
          (label ^ ": resulting status")
          (status_str expected)
          (status_str (Rvs.resulting_status reviewed));
        Lwt.return_unit
    | Error e -> Alcotest.failf "%s: %s" label (Phrv.error_str e)

  let review_expect label expected conn ~reviewer ~slug ~community decision =
    let* r = review conn ~reviewer ~slug ~community decision in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (Phrv.error_str expected)
    | Error e ->
        Alcotest.(check string) label (Phrv.error_str expected)
          (Phrv.error_str e);
        Lwt.return_unit

  let remove conn ~actor ~slug ~community =
    Rms.remove conn ~actor_user_id:actor ~project_slug:slug
      ~community_slug:community

  let remove_ok label conn ~actor ~slug ~community =
    let* r = remove conn ~actor ~slug ~community in
    match r with
    | Ok removed ->
        Alcotest.(check string)
          (label ^ ": resulting status")
          (status_str Phr.Removed)
          (status_str (Rms.resulting_status removed));
        Lwt.return_unit
    | Error e -> Alcotest.failf "%s: %s" label (Phrm.error_str e)

  let remove_expect label expected conn ~actor ~slug ~community =
    let* r = remove conn ~actor ~slug ~community in
    match r with
    | Ok _ ->
        Alcotest.failf "%s: expected %s, got Ok" label (Phrm.error_str expected)
    | Error e ->
        Alcotest.(check string) label (Phrm.error_str expected)
          (Phrm.error_str e);
        Lwt.return_unit

  let q_status =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT status FROM community_projects WHERE id = $1"

  let check_status label conn relation expected =
    let* status = find conn (label ^ ": status") q_status relation in
    Alcotest.(check string) (label ^ ": relation status") expected status;
    Lwt.return_unit

  let q_delete_user =
    (Caqti_type.int ->. Caqti_type.unit) "DELETE FROM users WHERE id = $1"

  (* === schema fixtures (raw rows: the table's own constraints are the
     subject here, so events do not go through the stores) === *)

  let q_insert_project_raw =
    (Caqti_type.(t2 string int64) ->! Caqti_type.int64)
    "INSERT INTO open_source_projects \
       (name, slug, kind, forge_namespace_id, forge_namespace_login, \
        forge_namespace_type) \
     VALUES ('Phau fixture', $1, 'project', $2, 'phau-raw-owner', 'user') \
     RETURNING id"

  let q_insert_relation_raw =
    (Caqti_type.(t2 int64 int) ->! Caqti_type.int64)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at) \
     VALUES ($1, $2, 'home', 'accepted', NOW()) RETURNING id"

  let q_insert_event_raw =
    (Caqti_type.(t2 (t2 string (option int)) (t3 int64 int int64))
     ->! Caqti_type.int64)
    "INSERT INTO project_home_audit_events \
       (action, actor_user_id, project_id, community_id, relation_id) \
     VALUES ($1, $2, $3, $4, $5) RETURNING id"

  (* NULL-capable subject columns, for the required-reference probes. *)
  let q_insert_event_nullable =
    (Caqti_type.(t2 (t2 string (option int))
                    (t3 (option int64) (option int) (option int64)))
     ->! Caqti_type.int64)
    "INSERT INTO project_home_audit_events \
       (action, actor_user_id, project_id, community_id, relation_id) \
     VALUES ($1, $2, $3, $4, $5) RETURNING id"

  let q_event_row =
    (Caqti_type.int64
     ->! Caqti_type.(t2 (t2 string (option int)) (t3 int64 int int64)))
    "SELECT action, actor_user_id, project_id, community_id, relation_id \
     FROM project_home_audit_events WHERE id = $1"

  let q_event_exists =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM project_home_audit_events WHERE id = $1"

  let q_delete_event =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM project_home_audit_events WHERE id = $1"

  let q_delete_project_raw =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM open_source_projects WHERE id = $1"

  let q_delete_community_raw =
    (Caqti_type.int ->. Caqti_type.unit)
    "DELETE FROM communities WHERE id = $1"

  let q_delete_relation_raw =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM community_projects WHERE id = $1"

  let q_absent_project_id =
    (Caqti_type.unit ->! Caqti_type.int64)
    "SELECT COALESCE(MAX(id), 0) + 1000000 FROM open_source_projects"

  let q_absent_community_id =
    (Caqti_type.unit ->! Caqti_type.int)
    "SELECT COALESCE(MAX(id), 0) + 1000000 FROM communities"

  let q_absent_relation_id =
    (Caqti_type.unit ->! Caqti_type.int64)
    "SELECT COALESCE(MAX(id), 0) + 1000000 FROM community_projects"

  let q_absent_user_id =
    (Caqti_type.unit ->! Caqti_type.int)
    "SELECT COALESCE(MAX(id), 0) + 1000000 FROM users"

  (* === schema signatures === *)

  let q_constraints =
    (Caqti_type.unit ->* Caqti_type.(t3 string string bool))
    "SELECT conname, contype::text, convalidated FROM pg_constraint \
     WHERE conrelid = 'project_home_audit_events'::regclass \
     ORDER BY conname"

  let q_fk_deltypes =
    (Caqti_type.unit ->* Caqti_type.(t2 string string))
    "SELECT conname, confdeltype::text FROM pg_constraint \
     WHERE conrelid = 'project_home_audit_events'::regclass \
       AND contype = 'f' \
     ORDER BY conname"

  let q_indexdefs =
    (Caqti_type.unit ->* Caqti_type.string)
    "SELECT indexdef FROM pg_indexes \
     WHERE schemaname = 'public' \
       AND tablename = 'project_home_audit_events' \
     ORDER BY indexname"

  (* The only non-numeric, non-timestamp column may be the closed action
     vocabulary itself: no note, no email, no username, no free text. *)
  let q_text_columns =
    (Caqti_type.unit ->* Caqti_type.string)
    "SELECT column_name FROM information_schema.columns \
     WHERE table_schema = 'public' \
       AND table_name = 'project_home_audit_events' \
       AND data_type NOT IN ('integer', 'bigint', \
                             'timestamp with time zone') \
     ORDER BY column_name"

  let q_credential_columns =
    (Caqti_type.unit ->* Caqti_type.string)
    "SELECT column_name FROM information_schema.columns \
     WHERE table_schema = 'public' \
       AND table_name = 'project_home_audit_events' \
       AND (column_name ~* 'token' OR column_name ~* 'secret' \
            OR column_name ~* 'verifier' OR column_name ~* 'oauth' \
            OR column_name ~* 'session' OR column_name ~* 'note' \
            OR column_name ~* 'email' OR column_name ~* 'username' \
            OR column_name ~* 'login' OR column_name ~* 'json' \
            OR column_name ~* 'github' OR column_name ~* 'installation' \
            OR column_name ~* 'account' OR column_name ~* 'namespace')"

  let q_table_exists =
    (Caqti_type.unit ->! Caqti_type.int)
    "SELECT COUNT(*) FROM pg_class \
     WHERE relname = 'project_home_audit_events' AND relkind = 'r'"

  let ddl sql = (Caqti_type.unit ->. Caqti_type.unit) sql

  let q_drop_table = ddl "DROP TABLE project_home_audit_events"

  (* Byte-for-byte the migration's up statements, for the transactional
     round-trip below. *)
  let q_recreate_table =
    ddl
      "CREATE TABLE project_home_audit_events ( \
         id            BIGSERIAL   PRIMARY KEY, \
         action        TEXT        NOT NULL \
                                   CHECK (action IN ('project_home_requested', \
                                                     'project_home_accepted', \
                                                     'project_home_rejected', \
                                                     'project_home_removed', \
                                                     'dedicated_home_provisioned', \
                                                     'network_community_published')), \
         actor_user_id INTEGER     REFERENCES users(id) ON DELETE SET NULL, \
         project_id    BIGINT      NOT NULL REFERENCES open_source_projects(id), \
         community_id  INTEGER     NOT NULL REFERENCES communities(id), \
         relation_id   BIGINT      NOT NULL REFERENCES community_projects(id), \
         created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW() \
       )"

  let q_recreate_indexes =
    List.map ddl
      [ "CREATE INDEX idx_project_home_audit_events_project \
         ON project_home_audit_events (project_id, created_at DESC)"
      ; "CREATE INDEX idx_project_home_audit_events_community \
         ON project_home_audit_events (community_id, created_at DESC)"
      ; "CREATE INDEX idx_project_home_audit_events_relation \
         ON project_home_audit_events (relation_id, created_at DESC)"
      ; "CREATE INDEX idx_project_home_audit_events_actor \
         ON project_home_audit_events (actor_user_id, created_at DESC)"
      ]

  (* === failure injection (installed and dropped per case) === *)

  let q_create_fail_fn =
    ddl
      "CREATE FUNCTION phau_fail_fn() RETURNS trigger \
       LANGUAGE plpgsql \
       AS 'BEGIN RAISE EXCEPTION ''phau fixture failure''; END'"

  let q_drop_fail_fn = ddl "DROP FUNCTION IF EXISTS phau_fail_fn()"

  let q_poison_audit =
    ddl
      "CREATE TRIGGER phau_fail_audit \
       BEFORE INSERT ON project_home_audit_events \
       FOR EACH ROW EXECUTE FUNCTION phau_fail_fn()"

  let q_unpoison_audit =
    ddl "DROP TRIGGER IF EXISTS phau_fail_audit ON project_home_audit_events"

  let q_poison_relation_insert =
    ddl
      "CREATE TRIGGER phau_fail_business \
       AFTER INSERT ON community_projects \
       FOR EACH ROW EXECUTE FUNCTION phau_fail_fn()"

  let q_poison_relation_update =
    ddl
      "CREATE TRIGGER phau_fail_business \
       AFTER UPDATE ON community_projects \
       FOR EACH ROW EXECUTE FUNCTION phau_fail_fn()"

  let q_unpoison_business =
    ddl "DROP TRIGGER IF EXISTS phau_fail_business ON community_projects"

  let with_poison conn ~install ~remove f =
    let* () = exec conn "create fail fn" q_create_fail_fn () in
    Lwt.finalize
      (fun () ->
        let* () = exec conn "install poison trigger" install () in
        Lwt.finalize f
          (fun () -> exec conn "drop poison trigger" remove ()))
      (fun () -> exec conn "drop fail fn" q_drop_fail_fn ())

  let sole_relation label conn project =
    let* ids =
      collect conn (label ^ ": relation ids") Phvs.q_relation_ids project
    in
    match ids with
    | [ rid ] -> Lwt.return rid
    | l ->
        Alcotest.failf "%s: expected one relation, found %d" label
          (List.length l)

  (* ==================== schema suite ==================== *)

  let raw_fixture conn ~pslug ~cslug ~ext =
    let* actor = insert_user conn ("phau_raw_" ^ pslug) in
    let* project = find conn "raw project" q_insert_project_raw
                     (("phau-" ^ pslug), ext) in
    let* cid = insert_community conn ("phau-" ^ cslug) in
    let* rid = find conn "raw relation" q_insert_relation_raw (project, cid) in
    Lwt.return (actor, project, cid, rid)

  let actions_case =
    db_case "schema: exactly the six closed actions are accepted; anything \
             else is rejected" (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-act" ~cslug:"sch-act-home"
            ~ext:958100001L
        in
        let* () =
          Lwt_list.iter_s
            (fun action ->
              let* id =
                C.find q_insert_event_raw
                  ((action, Some actor), (project, cid, rid))
              in
              let* id = or_fail ("accept " ^ action) id in
              Alcotest.(check bool) (action ^ ": positive id") true
                (Int64.compare id 0L > 0);
              Lwt.return_unit)
            [ "project_home_requested"; "project_home_accepted";
              "project_home_rejected"; "project_home_removed";
              "dedicated_home_provisioned"; "network_community_published"
            ]
        in
        Lwt_list.iter_s
          (fun action ->
            let* r =
              C.find q_insert_event_raw
                ((action, Some actor), (project, cid, rid))
            in
            reject ("reject " ^ action) r)
          [ "made_up_action"; "PROJECT_HOME_REQUESTED"; "";
            " project_home_requested"; "home_requested"
          ])

  let required_references_case =
    db_case "schema: project, community, and relation references are \
             required and must resolve; the actor may be NULL" (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-ref" ~cslug:"sch-ref-home"
            ~ext:958100002L
        in
        (* NULL subjects: NOT NULL refuses each. *)
        let* () =
          Lwt_list.iter_s
            (fun (label, p, c, r) ->
              let* res =
                C.find q_insert_event_nullable
                  (("project_home_requested", Some actor), (p, c, r))
              in
              reject label res)
            [ ("null project", None, Some cid, Some rid);
              ("null community", Some project, None, Some rid);
              ("null relation", Some project, Some cid, None)
            ]
        in
        (* Dangling subjects and a dangling actor: the FKs refuse each. *)
        let* ghost_p = find conn "ghost project" q_absent_project_id () in
        let* ghost_c = find conn "ghost community" q_absent_community_id () in
        let* ghost_r = find conn "ghost relation" q_absent_relation_id () in
        let* ghost_u = find conn "ghost user" q_absent_user_id () in
        let* () =
          Lwt_list.iter_s
            (fun (label, a, p, c, r) ->
              let* res =
                C.find q_insert_event_raw
                  (("project_home_requested", a), (p, c, r))
              in
              reject label res)
            [ ("dangling project", Some actor, ghost_p, cid, rid);
              ("dangling community", Some actor, project, ghost_c, rid);
              ("dangling relation", Some actor, project, cid, ghost_r);
              ("dangling actor", Some ghost_u, project, cid, rid)
            ]
        in
        (* A NULL actor is the legal retention shape. *)
        let* id =
          C.find q_insert_event_raw
            (("project_home_requested", None), (project, cid, rid))
        in
        let* id = or_fail "null actor accepted" id in
        Alcotest.(check bool) "null actor: positive id" true
          (Int64.compare id 0L > 0);
        Lwt.return_unit)

  let actor_deletion_case =
    db_case "schema: deleting the actor nulls the reference and the event \
             survives untouched" (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-del" ~cslug:"sch-del-home"
            ~ext:958100003L
        in
        let* event =
          C.find q_insert_event_raw
            (("project_home_accepted", Some actor), (project, cid, rid))
        in
        let* event = or_fail "event" event in
        let* () = exec conn "delete actor" q_delete_user actor in
        let* row = find conn "event row" q_event_row event in
        Alcotest.(check
                    (pair (pair string (option int))
                       (triple int64 int int64)))
          "event survives with a NULL actor and intact subjects"
          (("project_home_accepted", None), (project, cid, rid))
          (let (action_actor, (p, c, r)) = row in
           (action_actor, (p, c, r)));
        Lwt.return_unit)

  let subject_protection_case =
    db_case "schema: audit history RESTRICT-protects project, community, \
             and relation until explicitly purged" (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-pro" ~cslug:"sch-pro-home"
            ~ext:958100004L
        in
        let* event =
          C.find q_insert_event_raw
            (("project_home_removed", Some actor), (project, cid, rid))
        in
        let* event = or_fail "event" event in
        (* Each subject deletion is refused while the event exists. The
           relation delete is probed directly; project and community
           deletes are refused through their community_projects
           cascades reaching the same protected relation — and the
           community delete would also trip the community FK itself. *)
        let* r = C.exec q_delete_relation_raw rid in
        let* () = reject "relation delete refused" r in
        let* r = C.exec q_delete_project_raw project in
        let* () = reject "project delete refused" r in
        let* r = C.exec q_delete_community_raw cid in
        let* () = reject "community delete refused" r in
        (* After the explicit purge, ordinary deletion resumes. *)
        let* () = exec conn "purge event" q_delete_event event in
        let* () = exec conn "project delete succeeds" q_delete_project_raw
                    project in
        let* n = find conn "event gone" q_event_exists event in
        Alcotest.(check int) "purged event gone" 0 n;
        Lwt.return_unit)

  let constraints_indexes_case =
    db_case "schema: constraints and the four listing indexes are present, \
             validated, and carry the chosen deletion semantics" (fun conn ->
        let* rows = collect conn "constraints" q_constraints () in
        Alcotest.(check (list (triple string string bool)))
          "constraints present and validated"
          [ ("project_home_audit_events_action_check", "c", true);
            ("project_home_audit_events_actor_user_id_fkey", "f", true);
            ("project_home_audit_events_community_id_fkey", "f", true);
            ("project_home_audit_events_pkey", "p", true);
            ("project_home_audit_events_project_id_fkey", "f", true);
            ("project_home_audit_events_relation_id_fkey", "f", true)
          ]
          rows;
        let* deltypes = collect conn "fk deltypes" q_fk_deltypes () in
        Alcotest.(check (list (pair string string)))
          "SET NULL actor, NO ACTION subjects"
          [ ("project_home_audit_events_actor_user_id_fkey", "n");
            ("project_home_audit_events_community_id_fkey", "a");
            ("project_home_audit_events_project_id_fkey", "a");
            ("project_home_audit_events_relation_id_fkey", "a")
          ]
          deltypes;
        let* defs = collect conn "index defs" q_indexdefs () in
        Alcotest.(check (list string))
          "exactly the four listing indexes plus the primary key"
          [ "CREATE INDEX idx_project_home_audit_events_actor ON \
             public.project_home_audit_events USING btree (actor_user_id, \
             created_at DESC)"
          ; "CREATE INDEX idx_project_home_audit_events_community ON \
             public.project_home_audit_events USING btree (community_id, \
             created_at DESC)"
          ; "CREATE INDEX idx_project_home_audit_events_project ON \
             public.project_home_audit_events USING btree (project_id, \
             created_at DESC)"
          ; "CREATE INDEX idx_project_home_audit_events_relation ON \
             public.project_home_audit_events USING btree (relation_id, \
             created_at DESC)"
          ; "CREATE UNIQUE INDEX project_home_audit_events_pkey ON \
             public.project_home_audit_events USING btree (id)"
          ]
          defs;
        Lwt.return_unit)

  let column_privacy_case =
    db_case "schema: the closed action is the only textual column and no \
             credential-shaped column exists" (fun conn ->
        let* text_columns = collect conn "text columns" q_text_columns () in
        Alcotest.(check (list string))
          "only the action column is non-numeric" [ "action" ] text_columns;
        let* bad = collect conn "credential columns" q_credential_columns () in
        Alcotest.(check (list string)) "no credential-shaped column" [] bad;
        Lwt.return_unit)

  let roundtrip_case =
    db_case "schema: the down/up statement pair round-trips" (fun conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        (* The whole round-trip runs inside one transaction that is
           always rolled back, so the live table cannot be lost even if
           an assertion fails between the drop and the re-create. *)
        let* r = C.start () in
        let* () = or_fail "begin" r in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () = exec conn "down" q_drop_table () in
              let* n = find conn "absent" q_table_exists () in
              Alcotest.(check int) "down removes the table" 0 n;
              let* () = exec conn "up table" q_recreate_table () in
              let* () =
                Lwt_list.iter_s (fun q -> exec conn "up index" q ()) q_recreate_indexes
              in
              let* n = find conn "present" q_table_exists () in
              Alcotest.(check int) "up restores the table" 1 n;
              let* rows = collect conn "constraints" q_constraints () in
              Alcotest.(check int)
                "up restores all six constraints" 6 (List.length rows);
              Lwt.return_unit)
            (fun () ->
              let* _ = C.rollback () in
              Lwt.return_unit)
        in
        let* n = find conn "live table" q_table_exists () in
        Alcotest.(check int) "live table untouched" 1 n;
        Lwt.return_unit)

  let schema_suite =
    [ actions_case; required_references_case; actor_deletion_case;
      subject_protection_case; constraints_indexes_case; column_privacy_case;
      roundtrip_case
    ]

  (* ============ one event per successful transition ============ *)

