            Rvs.Accept
        in
        let* () =
          exec conn "restore verification" Phrq.q_set_verification
            (project, "verified")
        in
        let* () = requested_only "after revoked" in
        (* Replay: a second decision finds nothing pending. *)
        let* () =
          review_ok "accept" conn ~reviewer:moderator ~slug:"phau-frv"
            ~community:"phau-frv-home" Rvs.Accept Phr.Accepted
        in
        let* () =
          review_expect "replay" Rvs.Review_unavailable conn
            ~reviewer:moderator ~slug:"phau-frv" ~community:"phau-frv-home"
            Rvs.Accept
        in
