        let* moderator = insert_user conn "phau_rbm_mod" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000022L ~slug:"phau-rbm"
        in
        let* cid = insert_community conn "phau-rbm-home" in
        let* () =
          exec conn "top mod" Phrv.q_insert_moderator (moderator, cid, "top_mod")
        in
        let* rid =
          request_ok "request" conn ~user:owner ~slug:"phau-rbm"
            ~community:cid
        in
        let* () =
          review_ok "accept" conn ~reviewer:moderator ~slug:"phau-rbm"
            ~community:"phau-rbm-home" Rvs.Accept Phr.Accepted
        in
        let* () =
          with_poison conn ~install:q_poison_audit ~remove:q_unpoison_audit
            (fun () ->
              remove_expect "poisoned removal" Rms.Storage_error conn
                ~actor:owner ~slug:"phau-rbm" ~community:"phau-rbm-home")
        in
        let* () = check_status "after rollback" conn rid "accepted" in
        check_events "no removal event" conn ~project
          [ (("project_home_requested", Some owner), (cid, rid));
            (("project_home_accepted", Some moderator), (cid, rid))
          ])

  (* Provisioning rollback leaves none of the six draft rows behind. *)
  let q_draft_leftovers =
    (Caqti_type.(t2 string int64)
     ->! Caqti_type.(t2 (t3 int int int) (t3 int int int)))
    "SELECT \
       (SELECT COUNT(*) FROM communities WHERE slug = $1), \
       (SELECT COUNT(*) FROM community_members WHERE community_id IN \
          (SELECT id FROM communities WHERE slug = $1)), \
       (SELECT COUNT(*) FROM community_moderators WHERE community_id IN \
          (SELECT id FROM communities WHERE slug = $1)), \
       (SELECT COUNT(*) FROM community_sections WHERE community_id IN \
          (SELECT id FROM communities WHERE slug = $1)), \
       (SELECT COUNT(*) FROM channels WHERE community_id IN \
          (SELECT id FROM communities WHERE slug = $1)), \
       (SELECT COUNT(*) FROM community_projects WHERE project_id = $2)"

  let provisioning_rollback_case =
    db_case "rollback: a failed provisioning audit insertion leaves no \
             community, membership, moderator, shell, or relation"
      (fun conn ->
        let* owner = insert_user conn "phau_rbp_owner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000023L ~slug:"phau-rbp"
        in
        let* () =
          with_poison conn ~install:q_poison_audit ~remove:q_unpoison_audit
            (fun () ->
              Phvs.provision_expect "poisoned provisioning" Pv.Storage_error
                conn ~actor:owner ~slug:"phau-rbp"
                (Phvs.identity ~name:"Phau Rbp" ~slug:"phau-rbp-home" ()))
        in
        let* leftovers =
          find conn "leftovers" q_draft_leftovers ("phau-rbp-home", project)
        in
        Alcotest.(check (pair (triple int int int) (triple int int int)))
          "the whole draft rolled back" ((0, 0, 0), (0, 0, 0)) leftovers;
        check_event_count "no event" conn ~project 0)

  let publication_rollback_case =
    db_case "rollback: a failed publication audit insertion leaves slug, \
             identity, lifecycle, relation, and shell unchanged" (fun conn ->
        let* owner = insert_user conn "phau_rbb_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:958000024L
            ~project_slug:"phau-rbb" ~slug:"phau-rbb-home"
        in
        let* before = Ncps.snapshot "before" conn ~cid ~project ~rid in
        let* () =
          with_poison conn ~install:q_poison_audit ~remove:q_unpoison_audit
            (fun () ->
              Ncps.publish_expect "poisoned publication" Pub.Storage_error
                conn ~actor:owner ~current:"phau-rbb-home"
                (Ncps.publication ~name:"Phau Rbb Hub" ~slug:"phau-rbb-hub"
                   ()))
        in
        let* () =
          Ncps.check_unchanged "after rollback" conn ~cid ~project ~rid
            before
        in
        let* hub = find conn "loser slug" Phvs.q_count_by_slug
                     "phau-rbb-hub" in
        Alcotest.(check int) "no community under the requested slug" 0 hub;
        check_events "provisioned event alone" conn ~project
          [ (("dedicated_home_provisioned", Some owner), (cid, rid)) ])

  let rollback_suite =
    [ request_rollback_case; review_rollback_case; removal_rollback_case;
      provisioning_rollback_case; publication_rollback_case
    ]

  (* ==================== concurrency ==================== *)

  let request_race_case =
    db_case "concurrency: two live identical requests leave one pending \
             relation and exactly one request event" (fun conn ->
        let* owner = insert_user conn "phau_crq_owner" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000030L ~slug:"phau-crq"
        in
        let* cid = insert_community conn "phau-crq-home" in
        let* _created =
          Pod_store.with_second_connection (fun conn2 ->
              let* results =
                Lwt.both
                  (Phrq.create conn ~user:owner ~slug:"phau-crq"
                     ~community:cid (phr_fresh_pending ()))
                  (Phrq.create conn2 ~user:owner ~slug:"phau-crq"
                     ~community:cid (phr_fresh_pending ()))
              in
              Lwt.return
                (Phrq.ok_and_error "request race" Rq.Active_home_exists
                   results))
        in
        let* rid = sole_relation "one relation" conn project in
        check_events "one event" conn ~project
          [ (("project_home_requested", Some owner), (cid, rid)) ])

  let review_race_case =
    db_case "concurrency: two reviewers produce exactly one decision event"
      (fun conn ->
        let* owner = insert_user conn "phau_crv_owner" in
        let* mod1 = insert_user conn "phau_crv_mod1" in
        let* mod2 = insert_user conn "phau_crv_mod2" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000031L ~slug:"phau-crv"
        in
        let* cid = insert_community conn "phau-crv-home" in
        let* () =
          exec conn "top mod 1" Phrv.q_insert_moderator (mod1, cid, "top_mod")
        in
        let* () =
          exec conn "top mod 2" Phrv.q_insert_moderator (mod2, cid, "top_mod")
        in
        let* rid =
          request_ok "request" conn ~user:owner ~slug:"phau-crv"
            ~community:cid
        in
        let* () =
          review_ok "first reviewer" conn ~reviewer:mod1 ~slug:"phau-crv"
            ~community:"phau-crv-home" Rvs.Accept Phr.Accepted
        in
        let* () =
          review_expect "second reviewer" Rvs.Review_unavailable conn
            ~reviewer:mod2 ~slug:"phau-crv" ~community:"phau-crv-home"
            Rvs.Reject
        in
        check_events "one decision event" conn ~project
          [ (("project_home_requested", Some owner), (cid, rid));
            (("project_home_accepted", Some mod1), (cid, rid))
          ])

  let removal_race_case =
    db_case "concurrency: two removers produce exactly one removal event"
      (fun conn ->
        let* owner = insert_user conn "phau_crm_owner" in
        let* moderator = insert_user conn "phau_crm_mod" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000032L ~slug:"phau-crm"
        in
        let* cid = insert_community conn "phau-crm-home" in
        let* () =
          exec conn "top mod" Phrv.q_insert_moderator (moderator, cid, "top_mod")
        in
        let* rid =
          request_ok "request" conn ~user:owner ~slug:"phau-crm"
            ~community:cid
        in
        let* () =
          review_ok "accept" conn ~reviewer:moderator ~slug:"phau-crm"
            ~community:"phau-crm-home" Rvs.Accept Phr.Accepted
        in
        let* () =
          remove_ok "first remover" conn ~actor:owner ~slug:"phau-crm"
            ~community:"phau-crm-home"
        in
        let* () =
          remove_expect "second remover" Rms.Removal_unavailable conn
            ~actor:moderator ~slug:"phau-crm" ~community:"phau-crm-home"
        in
        check_events "one removal event" conn ~project
          [ (("project_home_requested", Some owner), (cid, rid));
            (("project_home_accepted", Some moderator), (cid, rid));
            (("project_home_removed", Some owner), (cid, rid))
          ])

  let provisioning_race_case =
    db_case "concurrency: a second provisioning attempt creates no second \
             provision event and no loser community" (fun conn ->
        let* owner = insert_user conn "phau_crp_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:958000033L
            ~project_slug:"phau-crp" ~slug:"phau-crp-home"
        in
        let* () =
          Phvs.provision_expect "loser" Pv.Active_home_exists conn
            ~actor:owner ~slug:"phau-crp"
            (Phvs.identity ~name:"Phau Crp" ~slug:"phau-crp-loser" ())
        in
        let* loser = find conn "loser slug" Phvs.q_count_by_slug
                       "phau-crp-loser" in
        Alcotest.(check int) "no loser community" 0 loser;
        check_events "one provision event" conn ~project
          [ (("dedicated_home_provisioned", Some owner), (cid, rid)) ])

  let publication_race_case =
    db_case "concurrency: a second publication attempt creates no second \
             publication event" (fun conn ->
        let* owner = insert_user conn "phau_crb_owner" in
        let* project, cid, rid =
          make_draft conn ~user:owner ~ext_id:958000034L
            ~project_slug:"phau-crb" ~slug:"phau-crb-home"
        in
        let* _ =
          Ncps.publish_ok "winner" conn ~actor:owner
            ~current:"phau-crb-home" ~expect_slug:"phau-crb-hub"
            ~expect_visibility:Ncpf.Public
            (Ncps.publication ~name:"Phau Crb Hub" ~slug:"phau-crb-hub" ())
        in
        let* () =
          Ncps.publish_expect "loser" Pub.Draft_unavailable conn
            ~actor:owner ~current:"phau-crb-hub"
            (Ncps.publication ~name:"Phau Crb Hub" ~slug:"phau-crb-hub" ())
        in
        check_events "one publication event" conn ~project
          [ (("dedicated_home_provisioned", Some owner), (cid, rid));
            (("network_community_published", Some owner), (cid, rid))
          ])

  let concurrency_suite =
    [ request_race_case; review_race_case; removal_race_case;
      provisioning_race_case; publication_race_case
    ]

  (* ============== actor deletion and privacy ============== *)

  let actor_deletion_retention_case =
    db_case "retention: deleting an actor nulls only that actor's events; \
             history and subjects survive" (fun conn ->
        let* owner = insert_user conn "phau_ret_owner" in
        let* moderator = insert_user conn "phau_ret_mod" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000040L ~slug:"phau-ret"
        in
        let* cid = insert_community conn "phau-ret-home" in
        let* () =
          exec conn "top mod" Phrv.q_insert_moderator (moderator, cid, "top_mod")
        in
        let* rid =
          request_ok "request" conn ~user:owner ~slug:"phau-ret"
            ~community:cid
        in
        let* () =
          review_ok "accept" conn ~reviewer:moderator ~slug:"phau-ret"
            ~community:"phau-ret-home" Rvs.Accept Phr.Accepted
        in
        let* () = exec conn "delete requester" q_delete_user owner in
        let* () =
          check_events "after actor deletion" conn ~project
            [ (("project_home_requested", None), (cid, rid));
              (("project_home_accepted", Some moderator), (cid, rid))
            ]
        in
        let* () = check_status "relation intact" conn rid "accepted" in
        Lwt.return_unit)

  let privacy_case =
    db_case "privacy: no note, credential, email, username, or GitHub \
             identifier reaches audit storage" (fun conn ->
        let* owner = insert_user conn "phau_priv_owner" in
        let* moderator = insert_user conn "phau_priv_mod" in
        let* _inst, project =
          make_project conn ~user:owner ~ext_id:958000041L ~slug:"phau-priv"
        in
        let* cid = insert_community conn "phau-priv-home" in
        let* () =
          exec conn "top mod" Phrv.q_insert_moderator (moderator, cid, "top_mod")
        in
        (* A deliberately credential-shaped private note travels through
           the real request; none of it may reach audit storage. *)
        let note =
          "PHAU_NOTE_SECRET_MARKER gho_PHAU_ACCESS_TOKEN \
           PHAU_SESSION_COOKIE_VALUE"
        in
        let relation =
          phr_expect_ok (Phr.create_pending ~request_note:(Some note))
        in
        let* created =
          Phrq.create_ok "request with note" conn ~user:owner
            ~slug:"phau-priv" ~community:cid relation
        in
        let rid = Rq.relation_id created in
        let* () =
          review_ok "accept" conn ~reviewer:moderator ~slug:"phau-priv"
            ~community:"phau-priv-home" Rvs.Accept Phr.Accepted
        in
        let* () =
          remove_ok "remove" conn ~actor:owner ~slug:"phau-priv"
            ~community:"phau-priv-home"
        in
        let* () =
          check_events "full lifecycle" conn ~project
            [ (("project_home_requested", Some owner), (cid, rid));
              (("project_home_accepted", Some moderator), (cid, rid));
              (("project_home_removed", Some owner), (cid, rid))
            ]
        in
        let* blob = find conn "audit blob" q_audit_blob project in
        List.iter
          (fun (label, marker) ->
            Alcotest.(check bool)
              ("no " ^ label ^ " in audit storage")
              false (contains blob marker))
          [ ("request note", "PHAU_NOTE_SECRET_MARKER");
            ("access token shape", "gho_");
            ("session value", "PHAU_SESSION_COOKIE_VALUE");
            ("username", "phau_priv_owner");
            ("email", "@test.invalid");
            ("github namespace login", "pfin-owner")
          ];
        Lwt.return_unit)

  let actor_privacy_suite = [ actor_deletion_retention_case; privacy_case ]
end

(* === Project-home lifecycle notifications
   (Project_home_notifications + the extended notifications table) ===
   The durable in-app notifications of the four counterparty-facing
   home-lifecycle transitions: the extended schema itself (the closed
   kind vocabulary via the notif_type CHECK, the two row shapes via the
   shape CHECK, required subject FKs with the
   user-facing CASCADE convention, SET NULL actor retention, the
   per-recipient/kind/relation dedup index, the down/up round-trip, and
   the absence of any note or credential column), the exact recipient
   set of each real store transition, whole-mutation rollback when the
   notification insertion itself fails, no notification on any refused
   or failed path, single delivery under concurrent attempts, the real
   notification-center handlers (labels, structural links, unread and
   mark-read behavior, recipient isolation, escaping, deleted actors,
   protected destinations), and a privacy sweep over rows, HTML, and
   headers. Fixtures use the reserved external-installation-id range
   960000001..960000999 (hence namespace ids 960100001..960100999),
   phnt_% usernames, and phnt-% community slugs so no suite shares
   fixtures. Notifications come only through the real stores except in
   the schema suite, whose raw rows probe the table's own constraints.
   Every per-case wrapper disconnects deterministically. *)
module Phnt = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  module Rq = Earde.Project_home_request_store
  module Rvs = Earde.Project_home_review_store
  module Rms = Earde.Project_home_removal_store

  let or_fail = Pod_store.or_fail
  let reject = Pod_schema.reject
  let insert_user = Pod_store.insert_user
  let exec = Pod_read.exec
  let find = Pod_read.find
  let collect = Pod_read.collect
  let make_project = Phrq.make_project
  let insert_community = Phcv.insert_community
  let make_draft = Ncps.make_draft
  let contains haystack needle = Cprj_schema.contains haystack ~needle
  let status_of = Gh_start_handler.status_of

  (* Store call and audit observation helpers shared with the audit
     suite — the notification suite always asserts the audit trail
     beside the notification set, because the two must commit or roll
     back together. *)
  let request_ok = Phau.request_ok
  let review_ok = Phau.review_ok
  let review_expect = Phau.review_expect
  let remove_ok = Phau.remove_ok
  let remove_expect = Phau.remove_expect
  let check_status = Phau.check_status
  let check_events = Phau.check_events
  let check_event_count = Phau.check_event_count
  let sole_relation = Phau.sole_relation
  let q_delete_user = Phau.q_delete_user

  (* Failure-injection DDL is dropped first so a crashed case can never
     leave a trigger behind; notifications and audit events must go
     before projects and communities (audit RESTRICT-protects both),
     then the shared dependency order of the sibling suites. *)
  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DROP TRIGGER IF EXISTS phnt_fail_notif ON notifications"
      ; "DROP TRIGGER IF EXISTS phnt_fail_audit ON project_home_audit_events"
      ; "DROP FUNCTION IF EXISTS phnt_fail_fn()"
      ; "DELETE FROM notifications \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 960100001 AND 960100999)"
      ; "DELETE FROM notifications \
         WHERE community_id IN \
           (SELECT id FROM communities WHERE slug LIKE 'phnt-%')"
      ; "DELETE FROM notifications \
         WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'phnt_%')"
      ; "DELETE FROM project_home_audit_events \
         WHERE project_id IN \
           (SELECT id FROM open_source_projects \
            WHERE forge_namespace_id BETWEEN 960100001 AND 960100999)"
      ; "DELETE FROM project_home_audit_events \
         WHERE community_id IN \
           (SELECT id FROM communities WHERE slug LIKE 'phnt-%')"
      ; "DELETE FROM open_source_projects \
         WHERE forge_namespace_id BETWEEN 960100001 AND 960100999"
      ; "DELETE FROM project_onboarding_drafts \
         WHERE github_installation_record_id IN \
           (SELECT id FROM github_installations \
            WHERE github_installation_id BETWEEN 960000001 AND 960000999)"
      ; "DELETE FROM communities WHERE slug LIKE 'phnt-%'"
      ; "DELETE FROM users WHERE username LIKE 'phnt_%'"
      ; "DELETE FROM github_installations \
         WHERE github_installation_id BETWEEN 960000001 AND 960000999"
      ]

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url conn)
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  (* === notification observation === *)

  (* One tuple per notification, in append (id) order. The project is
     the query key, so each row reduces to recipient, kind, actor,
     community, relation. *)
  let q_notifs_for_project =
    (Caqti_type.int64
     ->* Caqti_type.(t2 (t2 int string) (t3 (option int) int int64)))
    "SELECT user_id, notif_type, actor_user_id, community_id, relation_id \
     FROM notifications WHERE project_id = $1 ORDER BY id"

  let q_count_notifs_for_project =
    (Caqti_type.int64 ->! Caqti_type.int)
    "SELECT COUNT(*) FROM notifications WHERE project_id = $1"

  let q_count_kind_for_project =
    (Caqti_type.(t2 int64 string) ->! Caqti_type.int)
    "SELECT COUNT(*) FROM notifications \
     WHERE project_id = $1 AND notif_type = $2"

  (* Creation must never mark anything read. *)
  let q_all_unread =
    (Caqti_type.int64 ->! Caqti_type.bool)
    "SELECT COALESCE(BOOL_AND(NOT is_read), TRUE) \
     FROM notifications WHERE project_id = $1"

  (* Every stored byte of a project's notifications, for the boolean
     credential-absence sweep. *)
  let q_notif_blob =
    (Caqti_type.int64 ->! Caqti_type.string)
    "SELECT COALESCE(string_agg(n::text, '|'), '<none>') \
     FROM notifications n WHERE project_id = $1"

  let notif_t =
    Alcotest.(pair (pair int string) (triple (option int) int int64))

  let check_notifs label conn ~project expected =
    let* rows =
      collect conn (label ^ ": notifications") q_notifs_for_project project
    in
    Alcotest.(check (list notif_t))
      (label ^ ": exact notifications") expected rows;
    let* unread = find conn (label ^ ": unread") q_all_unread project in
    Alcotest.(check bool) (label ^ ": all rows unread") true unread;
    Lwt.return_unit

  let check_notif_count label conn ~project expected =
    let* n = find conn (label ^ ": count") q_count_notifs_for_project project in
    Alcotest.(check int) (label ^ ": notification count") expected n;
    Lwt.return_unit

  let check_kind_count label conn ~project ~kind expected =
    let* n =
      find conn (label ^ ": kind count") q_count_kind_for_project
        (project, kind)
    in
    Alcotest.(check int) (label ^ ": " ^ kind ^ " count") expected n;
    Lwt.return_unit

  (* === schema fixtures (raw rows: the table's own constraints are the
     subject here, so notifications do not go through the stores) === *)

  let q_insert_project_raw =
    (Caqti_type.(t2 string int64) ->! Caqti_type.int64)
    "INSERT INTO open_source_projects \
       (name, slug, kind, forge_namespace_id, forge_namespace_login, \
        forge_namespace_type) \
     VALUES ('Phnt fixture', $1, 'project', $2, 'phnt-raw-owner', 'user') \
     RETURNING id"

  let q_insert_relation_raw =
    (Caqti_type.(t2 int64 int) ->! Caqti_type.int64)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at) \
     VALUES ($1, $2, 'home', 'accepted', NOW()) RETURNING id"

  (* A second, historical relation for the same project: outside the
     active-home index predicate, so it can coexist with the accepted
     one. *)
  let q_insert_relation_removed_raw =
    (Caqti_type.(t2 int64 int) ->! Caqti_type.int64)
    "INSERT INTO community_projects \
       (project_id, community_id, relation_type, status, reviewed_at, \
        removed_at) \
     VALUES ($1, $2, 'home', 'removed', NOW(), NOW()) RETURNING id"

  let q_insert_post_raw =
    (Caqti_type.(t2 int int) ->! Caqti_type.int)
    "INSERT INTO posts (title, content, community_id, user_id) \
     VALUES ('phnt post', 'phnt body', $1, $2) RETURNING id"

  (* The structured project-home row shape. *)
  let q_insert_notif_raw =
    (Caqti_type.(t2 (t2 int string) (t2 (option int) (t3 int64 int int64)))
     ->! Caqti_type.int)
    "INSERT INTO notifications \
       (user_id, notif_type, actor_user_id, project_id, community_id, \
        relation_id) \
     VALUES ($1, $2, $3, $4, $5, $6) RETURNING id"

  (* NULL-capable subject columns, for the required-reference probes. *)
  let q_insert_notif_nullable =
    (Caqti_type.(
       t2 (t2 int string)
         (t2 (option int) (t3 (option int64) (option int) (option int64))))
     ->! Caqti_type.int)
    "INSERT INTO notifications \
       (user_id, notif_type, actor_user_id, project_id, community_id, \
        relation_id) \
     VALUES ($1, $2, $3, $4, $5, $6) RETURNING id"

  (* Forbidden mixed shapes. *)
  let q_insert_home_with_message =
    (Caqti_type.(t2 (t2 int string) (t3 int64 int int64))
     ->! Caqti_type.int)
    "INSERT INTO notifications \
       (user_id, notif_type, message, project_id, community_id, relation_id) \
     VALUES ($1, $2, 'phnt prose', $3, $4, $5) RETURNING id"

  let q_insert_home_with_post =
    (Caqti_type.(t2 (t2 int string) (t2 int (t3 int64 int int64)))
     ->! Caqti_type.int)
    "INSERT INTO notifications \
       (user_id, notif_type, post_id, project_id, community_id, relation_id) \
     VALUES ($1, $2, $3, $4, $5, $6) RETURNING id"

  (* Legacy rows: prose message, optional post, no subject or actor. *)
  let q_insert_legacy_raw =
    (Caqti_type.(t3 int string (option int)) ->! Caqti_type.int)
    "INSERT INTO notifications (user_id, notif_type, message, post_id) \
     VALUES ($1, $2, 'phnt legacy message', $3) RETURNING id"

  let q_insert_legacy_with_actor =
    (Caqti_type.(t2 int int) ->! Caqti_type.int)
    "INSERT INTO notifications \
       (user_id, notif_type, message, actor_user_id) \
     VALUES ($1, 'comment_reply', 'phnt legacy message', $2) RETURNING id"

  let q_notif_by_id =
    (Caqti_type.int
     ->! Caqti_type.(
           t2 (t2 int string) (t2 (option int) (t3 int64 int int64))))
    "SELECT user_id, notif_type, actor_user_id, project_id, community_id, \
            relation_id \
     FROM notifications WHERE id = $1"

  let q_notif_exists =
    (Caqti_type.int ->! Caqti_type.int)
    "SELECT COUNT(*) FROM notifications WHERE id = $1"

  let q_delete_project_raw =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM open_source_projects WHERE id = $1"

  let q_delete_community_raw =
    (Caqti_type.int ->. Caqti_type.unit)
    "DELETE FROM communities WHERE id = $1"

  let q_delete_relation_raw =
    (Caqti_type.int64 ->. Caqti_type.unit)
    "DELETE FROM community_projects WHERE id = $1"

  let q_absent_project_id = Phau.q_absent_project_id
  let q_absent_community_id = Phau.q_absent_community_id
  let q_absent_relation_id = Phau.q_absent_relation_id
  let q_absent_user_id = Phau.q_absent_user_id

  (* === schema signatures === *)

  let q_constraints =
    (Caqti_type.unit ->* Caqti_type.(t3 string string bool))
    "SELECT conname, contype::text, convalidated FROM pg_constraint \
     WHERE conrelid = 'notifications'::regclass \
     ORDER BY conname"

  let q_fk_deltypes =
    (Caqti_type.unit ->* Caqti_type.(t2 string string))
    "SELECT conname, confdeltype::text FROM pg_constraint \
     WHERE conrelid = 'notifications'::regclass \
       AND contype = 'f' \
     ORDER BY conname"

  let q_indexdefs =
    (Caqti_type.unit ->* Caqti_type.string)
    "SELECT indexdef FROM pg_indexes \
     WHERE schemaname = 'public' \
       AND tablename = 'notifications' \
     ORDER BY indexname"

  (* The only textual columns may be the closed kind vocabulary and the
     legacy prose message: no note, no email, no username, no URL. *)
  let q_text_columns =
    (Caqti_type.unit ->* Caqti_type.string)
    "SELECT column_name FROM information_schema.columns \
     WHERE table_schema = 'public' \
       AND table_name = 'notifications' \
       AND data_type NOT IN ('integer', 'bigint', 'boolean', \
                             'timestamp without time zone') \
     ORDER BY column_name"

  let q_credential_columns =
    (Caqti_type.unit ->* Caqti_type.string)
    "SELECT column_name FROM information_schema.columns \
     WHERE table_schema = 'public' \
       AND table_name = 'notifications' \
       AND (column_name ~* 'token' OR column_name ~* 'secret' \
            OR column_name ~* 'verifier' OR column_name ~* 'oauth' \
            OR column_name ~* 'session' OR column_name ~* 'note' \
            OR column_name ~* 'email' OR column_name ~* 'username' \
            OR column_name ~* 'login' OR column_name ~* 'json' \
            OR column_name ~* 'github' OR column_name ~* 'installation' \
            OR column_name ~* 'account' OR column_name ~* 'namespace' \
            OR column_name ~* 'url')"

  let q_extension_columns =
    (Caqti_type.unit ->! Caqti_type.int)
    "SELECT COUNT(*) FROM information_schema.columns \
     WHERE table_schema = 'public' AND table_name = 'notifications' \
       AND column_name IN ('actor_user_id', 'project_id', 'community_id', \
                           'relation_id')"

  let ddl sql = (Caqti_type.unit ->. Caqti_type.unit) sql

  (* Byte-for-byte the migration's down and up statements, for the
     transactional round-trip below. *)
  let q_down_statements =
    List.map ddl
      [ "DELETE FROM notifications \
         WHERE notif_type IN ('project_home_requested', \
                              'project_home_accepted', \
                              'project_home_rejected', \
                              'project_home_removed')"
      ; "DROP INDEX idx_notifications_actor"
      ; "DROP INDEX idx_notifications_relation"
      ; "DROP INDEX idx_notifications_community"
      ; "DROP INDEX idx_notifications_project"
      ; "DROP INDEX uq_notifications_recipient_kind_relation"
      ; "ALTER TABLE notifications \
         DROP CONSTRAINT notifications_project_home_shape_check"
      ; "ALTER TABLE notifications \
         DROP CONSTRAINT notifications_notif_type_check"
      ; "ALTER TABLE notifications \
         DROP COLUMN relation_id, \
         DROP COLUMN community_id, \
         DROP COLUMN project_id, \
         DROP COLUMN actor_user_id"
      ; "ALTER TABLE notifications ALTER COLUMN message SET NOT NULL"
      ]

  let q_up_statements =
    List.map ddl
      [ "ALTER TABLE notifications ALTER COLUMN message DROP NOT NULL"
      ; "ALTER TABLE notifications \
         ADD COLUMN actor_user_id INTEGER \
           CONSTRAINT notifications_actor_user_id_fkey \
           REFERENCES users(id) ON DELETE SET NULL, \
         ADD COLUMN project_id BIGINT \
           CONSTRAINT notifications_project_id_fkey \
           REFERENCES open_source_projects(id) ON DELETE CASCADE, \
         ADD COLUMN community_id INTEGER \
           CONSTRAINT notifications_community_id_fkey \
           REFERENCES communities(id) ON DELETE CASCADE, \
         ADD COLUMN relation_id BIGINT \
           CONSTRAINT notifications_relation_id_fkey \
           REFERENCES community_projects(id) ON DELETE CASCADE"
      ; "ALTER TABLE notifications \
         ADD CONSTRAINT notifications_notif_type_check CHECK ( \
           notif_type IN ('comment_reply', \
                          'mention', \
                          'mod_action', \
                          'project_home_requested', \
                          'project_home_accepted', \
                          'project_home_rejected', \
                          'project_home_removed') \
         )"
      ; "ALTER TABLE notifications \
         ADD CONSTRAINT notifications_project_home_shape_check CHECK ( \
           (notif_type IN ('project_home_requested', \
                           'project_home_accepted', \
                           'project_home_rejected', \
                           'project_home_removed') \
             AND project_id IS NOT NULL \
             AND community_id IS NOT NULL \
             AND relation_id IS NOT NULL \
             AND message IS NULL \
             AND post_id IS NULL) \
           OR \
           (notif_type NOT IN ('project_home_requested', \
                               'project_home_accepted', \
                               'project_home_rejected', \
                               'project_home_removed') \
             AND project_id IS NULL \
             AND community_id IS NULL \
             AND relation_id IS NULL \
             AND actor_user_id IS NULL \
             AND message IS NOT NULL) \
         )"
      ; "CREATE UNIQUE INDEX uq_notifications_recipient_kind_relation \
         ON notifications (user_id, notif_type, relation_id) \
         WHERE relation_id IS NOT NULL"
      ; "CREATE INDEX idx_notifications_project \
         ON notifications (project_id) WHERE project_id IS NOT NULL"
      ; "CREATE INDEX idx_notifications_community \
         ON notifications (community_id) WHERE community_id IS NOT NULL"
      ; "CREATE INDEX idx_notifications_relation \
         ON notifications (relation_id) WHERE relation_id IS NOT NULL"
      ; "CREATE INDEX idx_notifications_actor \
         ON notifications (actor_user_id) WHERE actor_user_id IS NOT NULL"
      ]

  (* === failure injection (installed and dropped per case) === *)

  let q_create_fail_fn =
    ddl
      "CREATE FUNCTION phnt_fail_fn() RETURNS trigger \
       LANGUAGE plpgsql \
       AS 'BEGIN RAISE EXCEPTION ''phnt fixture failure''; END'"

  let q_drop_fail_fn = ddl "DROP FUNCTION IF EXISTS phnt_fail_fn()"

  let q_poison_notifications =
    ddl
      "CREATE TRIGGER phnt_fail_notif \
       BEFORE INSERT ON notifications \
       FOR EACH ROW EXECUTE FUNCTION phnt_fail_fn()"

  let q_unpoison_notifications =
    ddl "DROP TRIGGER IF EXISTS phnt_fail_notif ON notifications"

  let q_poison_audit =
    ddl
      "CREATE TRIGGER phnt_fail_audit \
       BEFORE INSERT ON project_home_audit_events \
       FOR EACH ROW EXECUTE FUNCTION phnt_fail_fn()"

  let q_unpoison_audit =
    ddl "DROP TRIGGER IF EXISTS phnt_fail_audit ON project_home_audit_events"

  let with_poison conn ~install ~remove f =
    let* () = exec conn "create fail fn" q_create_fail_fn () in
    Lwt.finalize
      (fun () ->
        let* () = exec conn "install poison trigger" install () in
        Lwt.finalize f
          (fun () -> exec conn "drop poison trigger" remove ()))
      (fun () -> exec conn "drop fail fn" q_drop_fail_fn ())

  (* === display-name fixtures for the UI cases === *)

  let q_set_project_name =
    (Caqti_type.(t2 string int64) ->. Caqti_type.unit)
    "UPDATE open_source_projects SET name = $1 WHERE id = $2"

  (* ==================== schema suite ==================== *)

  let raw_fixture conn ~pslug ~cslug ~ns =
    let* recipient = insert_user conn ("phnt_raw_" ^ pslug) in
    let* actor = insert_user conn ("phnt_act_" ^ pslug) in
    let* project =
      find conn "raw project" q_insert_project_raw (("phnt-" ^ pslug), ns)
    in
    let* cid = insert_community conn ("phnt-" ^ cslug) in
    let* rid = find conn "raw relation" q_insert_relation_raw (project, cid) in
    Lwt.return (recipient, actor, project, cid, rid)

  let kinds_case =
    db_case "schema: the four project-home kinds and the three real \
             legacy kinds are the whole durable vocabulary" (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-kind" ~cslug:"sch-kind-home"
            ~ns:960100001L
        in
        let* () =
          Lwt_list.iter_s
            (fun kind ->
              let* id =
                C.find q_insert_notif_raw
                  ((recipient, kind), (Some actor, (project, cid, rid)))
              in
              let* id = or_fail ("accept " ^ kind) id in
              Alcotest.(check bool) (kind ^ ": positive id") true (id > 0);
              Lwt.return_unit)
            [ "project_home_requested"; "project_home_accepted";
              "project_home_rejected"; "project_home_removed"
            ]
        in
        (* Every real legacy kind — exactly what create_notif emits and
           pages.ml renders — stays accepted in its legacy shape. *)
        let* () =
          Lwt_list.iter_s
            (fun kind ->
              let* id = C.find q_insert_legacy_raw (recipient, kind, None) in
              let* id = or_fail ("accept legacy " ^ kind) id in
              Alcotest.(check bool)
                ("legacy " ^ kind ^ ": positive id") true (id > 0);
              Lwt.return_unit)
            [ "comment_reply"; "mention"; "mod_action" ]
        in
        (* Anything else is refused even in structured shape — including
           a legacy kind trying to borrow the structured columns. *)
        Lwt_list.iter_s
          (fun kind ->
            let* r =
              C.find q_insert_notif_raw
                ((recipient, kind), (Some actor, (project, cid, rid)))
            in
            reject ("reject " ^ kind) r)
          [ "project_home_bogus"; "PROJECT_HOME_REQUESTED"; "";
            " project_home_requested"; "home_requested"; "comment_reply";
            "mention"; "mod_action"
          ])

  let unknown_kind_shapes_case =
    db_case "schema: an unknown kind is rejected durably in legacy, \
             structured, and mixed shapes alike" (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-unk" ~cslug:"sch-unk-home"
            ~ns:960100008L
        in
        (* A perfectly valid-looking legacy row: prose message, every
           structured column NULL. The shape CHECK alone accepts this,
           so only the closed-vocabulary CHECK stands in the way — the
           regression this case exists for. *)
        let* r =
          C.find q_insert_legacy_raw
            (recipient, "completely_unknown_kind", None)
        in
        let* () = reject "unknown kind, legacy shape" r in
        (* A perfectly valid-looking structured row. *)
        let* r =
          C.find q_insert_notif_raw
            ( (recipient, "completely_unknown_kind"),
              (Some actor, (project, cid, rid)) )
        in
        let* () = reject "unknown kind, structured shape" r in
        (* Mixed shapes: prose plus subjects, and a partial subject set. *)
        let* r =
          C.find q_insert_home_with_message
            ((recipient, "completely_unknown_kind"), (project, cid, rid))
        in
        let* () = reject "unknown kind, prose plus subjects" r in
        let* r =
          C.find q_insert_notif_nullable
            ( (recipient, "completely_unknown_kind"),
              (Some actor, (Some project, None, None)) )
        in
        reject "unknown kind, partial subjects" r)

  let required_shape_case =
    db_case "schema: a project-home notification requires all three \
             subject references and no prose, post, or legacy mixing"
      (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-shape" ~cslug:"sch-shape-home"
            ~ns:960100002L
        in
        (* NULL subjects: the shape CHECK refuses each. *)
        let* () =
          Lwt_list.iter_s
            (fun (label, p, c, r) ->
              let* res =
                C.find q_insert_notif_nullable
                  ( (recipient, "project_home_requested"),
                    (Some actor, (p, c, r)) )
              in
              reject label res)
            [ ("null project", None, Some cid, Some rid);
              ("null community", Some project, None, Some rid);
              ("null relation", Some project, Some cid, None)
            ]
        in
        (* Prose or a post link on a structured row: refused. *)
        let* post =
          find conn "legacy post" q_insert_post_raw (cid, recipient)
        in
        let* r =
          C.find q_insert_home_with_message
            ((recipient, "project_home_requested"), (project, cid, rid))
        in
        let* () = reject "prose on a project-home row" r in
        let* r =
          C.find q_insert_home_with_post
            ((recipient, "project_home_requested"), (post, (project, cid, rid)))
        in
        let* () = reject "post link on a project-home row" r in
        (* Legacy rows keep working, but can never borrow the new
           columns. *)
        let* id =
          C.find q_insert_legacy_raw (recipient, "comment_reply", Some post)
        in
        let* id = or_fail "legacy with post accepted" id in
        Alcotest.(check bool) "legacy with post: positive id" true (id > 0);
        let* id = C.find q_insert_legacy_raw (recipient, "mod_action", None) in
        let* id = or_fail "legacy without post accepted" id in
        Alcotest.(check bool) "legacy without post: positive id" true (id > 0);
        let* r = C.find q_insert_legacy_with_actor (recipient, actor) in
        let* () = reject "actor on a legacy row" r in
        (* A NULL actor is the legal retention shape for a structured
           row. *)
        let* id =
          C.find q_insert_notif_raw
            ((recipient, "project_home_requested"), (None, (project, cid, rid)))
        in
        let* id = or_fail "null actor accepted" id in
        Alcotest.(check bool) "null actor: positive id" true (id > 0);
        (* Dangling references: the FKs refuse each. *)
        let* ghost_p = find conn "ghost project" q_absent_project_id () in
        let* ghost_c = find conn "ghost community" q_absent_community_id () in
        let* ghost_r = find conn "ghost relation" q_absent_relation_id () in
        let* ghost_u = find conn "ghost user" q_absent_user_id () in
        Lwt_list.iter_s
          (fun (label, recip, a, p, c, r) ->
            let* res =
              C.find q_insert_notif_raw
                ((recip, "project_home_accepted"), (a, (p, c, r)))
            in
            reject label res)
          [ ("dangling project", recipient, Some actor, ghost_p, cid, rid);
            ("dangling community", recipient, Some actor, project, ghost_c,
             rid);
            ("dangling relation", recipient, Some actor, project, cid,
             ghost_r);
            ("dangling actor", recipient, Some ghost_u, project, cid, rid);
            ("dangling recipient", ghost_u, Some actor, project, cid, rid)
          ])

  let dedup_case =
    db_case "schema: at most one notification per recipient, kind, and \
             relation; other kinds, recipients, and relations coexist"
      (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-dedup" ~cslug:"sch-dedup-home"
            ~ns:960100003L
        in
        let* other = insert_user conn "phnt_raw_sch_dedup_b" in
        let insert recip kind relation =
          C.find q_insert_notif_raw
            ((recip, kind), (Some actor, (project, cid, relation)))
        in
        let* id = insert recipient "project_home_requested" rid in
        let* id = or_fail "first" id in
        Alcotest.(check bool) "first: positive id" true (id > 0);
        (* The exact triple again: the unique index refuses it. *)
        let* r = insert recipient "project_home_requested" rid in
        let* () = reject "duplicate triple" r in
        (* Another kind, another recipient: both legal. *)
        let* id = insert recipient "project_home_accepted" rid in
        let* _ = or_fail "other kind" id in
        let* id = insert other "project_home_requested" rid in
        let* _ = or_fail "other recipient" id in
        (* A future replacement relation notifies again. *)
        let* rid2 =
          find conn "removed relation" q_insert_relation_removed_raw
            (project, cid)
        in
        let* id = insert recipient "project_home_requested" rid2 in
        let* id = or_fail "replacement relation" id in
        Alcotest.(check bool) "replacement: positive id" true (id > 0);
        Lwt.return_unit)

  let actor_deletion_case =
    db_case "schema: deleting the actor nulls the reference and the \
             notification survives untouched" (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-adel" ~cslug:"sch-adel-home"
            ~ns:960100004L
        in
        let* notif =
          C.find q_insert_notif_raw
            ((recipient, "project_home_accepted"), (Some actor, (project, cid, rid)))
        in
        let* notif = or_fail "notification" notif in
        let* () = exec conn "delete actor" q_delete_user actor in
        let* row = find conn "notification row" q_notif_by_id notif in
        Alcotest.(check notif_t)
          "notification survives with a NULL actor and intact subjects"
          ((recipient, "project_home_accepted"), (None, cid, rid))
          (let ((recip, kind), (a, (_p, c, r))) = row in
           ((recip, kind), (a, c, r)));
        Lwt.return_unit)

  let recipient_deletion_case =
    db_case "schema: deleting the recipient deletes the notification, as \
             for every other notification kind" (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-rdel" ~cslug:"sch-rdel-home"
            ~ns:960100005L
        in
        let* notif =
          C.find q_insert_notif_raw
            ((recipient, "project_home_removed"), (Some actor, (project, cid, rid)))
        in
        let* notif = or_fail "notification" notif in
        let* () = exec conn "delete recipient" q_delete_user recipient in
        let* n = find conn "gone" q_notif_exists notif in
        Alcotest.(check int) "recipient deletion removes the row" 0 n;
        Lwt.return_unit)

  let subject_deletion_case =
    db_case "schema: subject deletion follows the user-facing cascade \
             convention for relation, project, and community"
      (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        let* recipient, actor, project, cid, rid =
          raw_fixture conn ~pslug:"sch-sdel" ~cslug:"sch-sdel-home"
            ~ns:960100006L
        in
        let insert kind relation =
          let* n =
            C.find q_insert_notif_raw
              ((recipient, kind), (Some actor, (project, cid, relation)))
          in
          or_fail ("notification " ^ kind) n
        in
        (* Relation deletion cascades its notification only. *)
        let* n1 = insert "project_home_requested" rid in
        let* () = exec conn "delete relation" q_delete_relation_raw rid in
        let* gone = find conn "n1 gone" q_notif_exists n1 in
        Alcotest.(check int) "relation cascade" 0 gone;
        (* Project deletion cascades through its relations and rows. *)
        let* rid2 = find conn "relation 2" q_insert_relation_raw (project, cid) in
        let* n2 = insert "project_home_accepted" rid2 in
        let* () = exec conn "delete project" q_delete_project_raw project in
        let* gone = find conn "n2 gone" q_notif_exists n2 in
        Alcotest.(check int) "project cascade" 0 gone;
        (* Community deletion cascades likewise. *)
        let* project2 =
          find conn "raw project 2" q_insert_project_raw
            ("phnt-sch-sdel2", 960100007L)
        in
        let* rid3 =
          find conn "relation 3" q_insert_relation_raw (project2, cid)
        in
        let* n3 =
          let* n =
            C.find q_insert_notif_raw
              ((recipient, "project_home_rejected"),
               (Some actor, (project2, cid, rid3)))
          in
          or_fail "notification 3" n
        in
        let* () = exec conn "delete community" q_delete_community_raw cid in
        let* gone = find conn "n3 gone" q_notif_exists n3 in
        Alcotest.(check int) "community cascade" 0 gone;
        Lwt.return_unit)

  let constraints_indexes_case =
    db_case "schema: constraints and indexes are present, validated, and \
             carry the chosen deletion semantics" (fun ~url:_ conn ->
        let* rows = collect conn "constraints" q_constraints () in
        Alcotest.(check (list (triple string string bool)))
          "constraints present and validated"
          [ ("notifications_actor_user_id_fkey", "f", true);
            ("notifications_community_id_fkey", "f", true);
            ("notifications_notif_type_check", "c", true);
            ("notifications_pkey", "p", true);
            ("notifications_post_id_fkey", "f", true);
            ("notifications_project_home_shape_check", "c", true);
            ("notifications_project_id_fkey", "f", true);
            ("notifications_relation_id_fkey", "f", true);
            ("notifications_user_id_fkey", "f", true)
          ]
          rows;
        let* deltypes = collect conn "fk deltypes" q_fk_deltypes () in
        Alcotest.(check (list (pair string string)))
          "SET NULL actor, CASCADE recipient and subjects"
          [ ("notifications_actor_user_id_fkey", "n");
            ("notifications_community_id_fkey", "c");
            ("notifications_post_id_fkey", "c");
            ("notifications_project_id_fkey", "c");
            ("notifications_relation_id_fkey", "c");
            ("notifications_user_id_fkey", "c")
          ]
          deltypes;
        let* defs = collect conn "index defs" q_indexdefs () in
        Alcotest.(check (list string))
          "exactly the dedup index, the four FK indexes, and the primary key"
          [ "CREATE INDEX idx_notifications_actor ON public.notifications \
             USING btree (actor_user_id) WHERE (actor_user_id IS NOT NULL)"
          ; "CREATE INDEX idx_notifications_community ON \
             public.notifications USING btree (community_id) WHERE \
             (community_id IS NOT NULL)"
          ; "CREATE INDEX idx_notifications_project ON public.notifications \
             USING btree (project_id) WHERE (project_id IS NOT NULL)"
          ; "CREATE INDEX idx_notifications_relation ON \
             public.notifications USING btree (relation_id) WHERE \
             (relation_id IS NOT NULL)"
          ; "CREATE UNIQUE INDEX notifications_pkey ON public.notifications \
             USING btree (id)"
          ; "CREATE UNIQUE INDEX uq_notifications_recipient_kind_relation \
             ON public.notifications USING btree (user_id, notif_type, \
             relation_id) WHERE (relation_id IS NOT NULL)"
          ]
          defs;
        Lwt.return_unit)

  let column_privacy_case =
    db_case "schema: the closed kind and the legacy prose message are the \
             only textual columns and no credential-shaped column exists"
      (fun ~url:_ conn ->
        let* text_columns = collect conn "text columns" q_text_columns () in
        Alcotest.(check (list string))
          "only message and notif_type are textual"
          [ "message"; "notif_type" ] text_columns;
        let* bad = collect conn "credential columns" q_credential_columns () in
        Alcotest.(check (list string)) "no credential-shaped column" [] bad;
        Lwt.return_unit)

  let roundtrip_case =
    db_case "schema: the down/up statement pair round-trips" (fun ~url:_ conn ->
        let (module C : Caqti_lwt.CONNECTION) = conn in
        (* The whole round-trip runs inside one transaction that is
           always rolled back, so the live table cannot be lost even if
           an assertion fails between the drop and the re-create. *)
        let* r = C.start () in
        let* () = or_fail "begin" r in
        let* () =
          Lwt.finalize
            (fun () ->
              let* () =
                Lwt_list.iter_s (fun q -> exec conn "down" q ())
                  q_down_statements
              in
              let* n = find conn "absent" q_extension_columns () in
              Alcotest.(check int) "down removes the four columns" 0 n;
              let* () =
                Lwt_list.iter_s (fun q -> exec conn "up" q ()) q_up_statements
              in
              let* n = find conn "present" q_extension_columns () in
              Alcotest.(check int) "up restores the four columns" 4 n;
              let* rows = collect conn "constraints" q_constraints () in
              Alcotest.(check int)
                "up restores all nine constraints" 9 (List.length rows);
              Lwt.return_unit)
            (fun () ->
              let* _ = C.rollback () in
              Lwt.return_unit)
        in
        let* n = find conn "live columns" q_extension_columns () in
        Alcotest.(check int) "live table untouched" 4 n;
        Lwt.return_unit)

  let schema_suite =
    [ kinds_case; unknown_kind_shapes_case; required_shape_case; dedup_case;
      actor_deletion_case;
      recipient_deletion_case; subject_deletion_case;
      constraints_indexes_case; column_privacy_case; roundtrip_case
    ]

