  let request_rollback_case =
    db_case "rollback: a failed request notification insertion leaves no \
             pending relation, no audit event, and no notification"
      (fun ~url:_ conn ->
        let* owner = insert_user conn "phnt_rbq_owner" in
        let* m1 = insert_user conn "phnt_rbq_m1" in
