          make_project conn ~user:owner ~ext_id:960000030L ~slug:"phnt-frq"
        in
        let* cid = insert_community conn "phnt-frq-home" in
        let* () =
          exec conn "top mod" Phrv.q_insert_moderator (m1, cid, "top_mod")
        in
        (* Invalid pure input. *)
        let* () =
          Phrq.create_expect "invalid user" Rq.Invalid_user_id conn ~user:0
            ~slug:"phnt-frq" ~community:cid (phr_fresh_pending ())
        in
        (* Unavailable project and community. *)
        let* () =
          Phrq.create_expect "missing project" Rq.Project_unavailable conn
            ~user:owner ~slug:"phnt-frq-none" ~community:cid
            (phr_fresh_pending ())
        in
        let* ghost_c = find conn "ghost community" q_absent_community_id () in
        let* () =
          Phrq.create_expect "missing community" Rq.Community_unavailable
            conn ~user:owner ~slug:"phnt-frq" ~community:ghost_c
            (phr_fresh_pending ())
        in
        (* Unauthorized actor: not a steward. *)
        let* () =
          Phrq.create_expect "outsider" Rq.Project_unavailable conn
            ~user:outsider ~slug:"phnt-frq" ~community:cid
            (phr_fresh_pending ())
        in
        let* () = check_notif_count "only failures so far" conn ~project 0 in
        (* Duplicate: the second request finds the active-home slot
           taken and adds nothing. *)
        let* rid =
          request_ok "winner" conn ~user:owner ~slug:"phnt-frq"
            ~community:cid
        in
        let* () =
          Phrq.create_expect "duplicate" Rq.Active_home_exists conn
            ~user:owner ~slug:"phnt-frq" ~community:cid
            (phr_fresh_pending ())
        in
        check_notifs "after duplicate" conn ~project
          [ ((m1, "project_home_requested"), (Some owner, cid, rid)) ])

