          ~distinct_id:(Printf.sprintf "user:%d" steward)
          ~props:
            [ ("user_id", `Int steward);
              ("removal_surface", `String "project")
            ]
          captured;
        let* label, response, captured =
          remove "community surface"
            ~target:
              (community_side_remove ~community:"anfn-rm-b-home"
                 ~project:"anfn-rm-b")
        in
        check_redirect label
          ~location:"/c/anfn-rm-b-home/settings?panel=projects" response;
        check_single_capture label ~name:"project_home_removed"
          ~distinct_id:(Printf.sprintf "user:%d" steward)
          ~props:
            [ ("user_id", `Int steward);
              ("removal_surface", `String "community")
            ]
          captured;
        (* A replay reaches the same destination — deliberately — with no
           second event. *)
        let* label, response, captured =
          remove "replay"
            ~target:
              (project_side_remove ~project:"anfn-rm-a"
                 ~community:"anfn-rm-a-home")
        in
        check_redirect label ~location:"/projects/anfn-rm-a/request-home"
          response;
        check_no_capture label captured;
        Lwt.return_unit)

  let removal_failure_case =
    db_case
      "removal: a protected unpublished draft home and an unauthorized \
       actor capture nothing"
      (fun ~url conn ->
        let* uid = insert_user conn "anfn_rmfail" in
        let* outsider = insert_user conn "anfn_rmout" in
        let* project, _cid, _rid =
          make_home_draft conn ~user:uid ~ext_id:962000073L
            ~project_slug:"anfn-rmfail" ~slug:"anfn-rmfail-home"
        in
        let* cookie, token = open_session "rmfail" ~url uid in
        let target =
          project_side_remove ~project:"anfn-rmfail"
            ~community:"anfn-rmfail-home"
        in
        (* The provisioned home of an unpublished setup draft is protected:
           the redirect is the same as a success, and there is deliberately
           no event. *)
        let* (response, _body), captured =
          with_sink_lwt (fun () ->
              do_post ~url ~cookie ~target ~token ~body_fields:[] ())
        in
        check_redirect "protected draft"
          ~location:"/projects/anfn-rmfail/request-home" response;
        check_no_capture "protected draft" captured;
        let* status = find conn "status" q_relation_status project in
        Alcotest.(check string) "home still accepted" "accepted" status;
        let* out_cookie, out_token = open_session "outsider" ~url outsider in
        let* (response, _body), captured =
          with_sink_lwt (fun () ->
              do_post ~url ~cookie:out_cookie ~target ~token:out_token
                ~body_fields:[] ())
        in
        Alcotest.(check int) "unauthorized 404" 404 (status_of response);
        check_no_capture "unauthorized" captured;
        Lwt.return_unit)

  let removal_concurrency_case =
    db_case
      "removal concurrency: two removers on both surfaces produce exactly \
       one removal event"
      (fun ~url conn ->
        let* steward = insert_user conn "anfn_rmrsteward" in
        let* moderator = insert_user conn "anfn_rmrmod" in
        let* _inst, project =
          make_project conn ~user:steward ~ext_id:962000074L
            ~slug:"anfn-rmrace"
        in
        let* community = insert_community conn "anfn-rmrace-home" in
        let* () =
          exec conn "top mod" q_insert_moderator
            (moderator, community, "top_mod")
        in
        let* () =
          pending_request conn ~user:steward ~slug:"anfn-rmrace" ~community ()
        in
        let* () =
          accept_request conn ~reviewer:moderator ~project_slug:"anfn-rmrace"
            ~community_slug:"anfn-rmrace-home"
        in
        let* steward_cookie, steward_token =
          open_session "steward" ~url steward
        in
        let* mod_cookie, mod_token = open_session "moderator" ~url moderator in
        let* (first, second), captured =
          with_sink_lwt (fun () ->
              Lwt.both
                (do_post ~url ~cookie:steward_cookie
                   ~target:
                     (project_side_remove ~project:"anfn-rmrace"
                        ~community:"anfn-rmrace-home")
                   ~token:steward_token ~body_fields:[] ())
                (do_post ~url ~cookie:mod_cookie
                   ~target:
                     (community_side_remove ~community:"anfn-rmrace-home"
                        ~project:"anfn-rmrace")
                   ~token:mod_token ~body_fields:[] ()))
        in
        (* Both surfaces answer 303 whether they removed or found nothing to
           remove — that collapse is the point of the design. *)
        Alcotest.(check (list int)) "both redirect" [ 303; 303 ]
          [ status_of (fst first); status_of (fst second) ];
        Alcotest.(check int) "exactly one removal event" 1
          (List.length captured);
        Alcotest.(check (list string)) "and it is the removal event"
          [ "project_home_removed" ] (an_event_names captured);
        let* status = find conn "status" q_relation_status project in
        Alcotest.(check string) "relation removed once" "removed" status;
        Lwt.return_unit)

  (* === Privacy sweep === *)

  let privacy_case =
    db_case
      "privacy: no email, GitHub identifier, repository name, slug, note, or \
       description reaches an event name, a property, a distinct id, or a \
       captured body"
      (fun ~url conn ->
        let* steward = insert_user conn "anfn_privsteward" in
        let* moderator = insert_user conn "anfn_privmod" in
        let repo_name = "anfnPrivateRepoFixture" in
        let note = "anfn-NOTE-fixture-9f2b" in
        let description = "anfn-DESCRIPTION-fixture-4c7d" in
        let* _inst, draft, _v, _acct =
          Pfin.make_draft ~login:"anfn-owner-fixture" conn ~user:steward
            ~ext_id:962000081L
            (fun account_id ->
              [ (* the listing fixture substitutes raw JSON per field, so a
                   description travels as a JSON string literal *)
                Pfin.repo ~owner_login:"anfn-owner-fixture" ~account_id
                  ~description:(Printf.sprintf "%S" description)
                  ~id:962900081L repo_name
              ])
        in
        let* ids = Pfin.snapshot_ids conn draft in
        let s1 = List.nth ids 0 in
        let* () =
          Pod_select.replace_ok "seed" conn ~user:steward ~draft ~primary:s1
            [ s1 ]
        in
        let* cookie, token = open_session "privacy" ~url steward in
        let collected = ref [] in
        let run label target fields =
          let* (response, _body), captured =
            with_sink_lwt (fun () ->
                do_post ~url ~cookie ~target ~token ~body_fields:fields ())
          in
          collected := !collected @ captured;
          Lwt.return (label, response)
        in
        let* _ =
          run "select" "/projects/new/repositories"
            [ ("draft_id", Int64.to_string draft);
              ("repository", Int64.to_string s1)
            ]
        in
        let* _ =
          run "create" "/projects"
            (Pch.identity_fields ~draft:(Int64.to_string draft)
               ~name:"Anfn Privacy Project" ~slug:"anfn-privacy"
               ~description ~website:"https://anfn.example/privacy"
               ~primary:(Int64.to_string s1) ())
        in
        let* community = insert_community conn "anfn-privacy-home" in
        let* () =
          exec conn "top mod" q_insert_moderator
            (moderator, community, "top_mod")
        in
        let* _ =
          run "request"
            (request_home_target "anfn-privacy")
            (request_fields ~community ~note ())
        in
        let* mod_cookie, mod_token = open_session "moderator" ~url moderator in
        let* (_response, _body), captured =
          with_sink_lwt (fun () ->
              do_post ~url ~cookie:mod_cookie
                ~target:
                  (accept_target ~community:"anfn-privacy-home"
                     ~project:"anfn-privacy")
                ~token:mod_token ~body_fields:[] ())
        in
        collected := !collected @ captured;
        let payloads = !collected in
        Alcotest.(check int) "four funnel events" 4 (List.length payloads);
        Alcotest.(check (list string)) "the expected four"
          [ "github_repositories_selected"; "github_project_created";
            "project_home_request_submitted"; "project_home_request_reviewed"
          ]
          (an_event_names payloads);
        (* Distinct ids are only the two intended user identities. *)
        let distinct_ids =
          List.filter_map
            (fun p ->
              match payload_member "distinct_id" p with
              | Some (`String s) -> Some s
              | _ -> None)
            payloads
        in
        List.iter
          (fun id ->
            Alcotest.(check bool) "distinct id is user:<id>" true
              (id = Printf.sprintf "user:%d" steward
              || id = Printf.sprintf "user:%d" moderator))
          distinct_ids;
        let serialized =
          String.concat "|" (List.map Yojson.Safe.to_string payloads)
        in
        List.iter
          (fun (what, needle) ->
            Alcotest.(check bool)
              ("no " ^ what ^ " anywhere in the captured payloads")
              false
              (contains serialized needle))
          [ ("email", "anfn_privsteward@test.invalid");
            ("username", "anfn_privsteward");
            ("moderator username", "anfn_privmod");
            ("github login", "anfn-owner-fixture");
            ("repository name", repo_name);
            ("repository full name", "anfn-owner-fixture/" ^ repo_name);
            ("repository url", "https://github.com/anfn-owner-fixture");
            ("installation id", "962000081");
            ("account id", "962100081");
            ("github repository id", "962900081");
            ("project slug", "anfn-privacy");
            ("community slug", "anfn-privacy-home");
            ("request note", note);
            ("description", description);
            ("website", "anfn.example")
          ];
        (* Small serial ids (draft id, snapshot id) are deliberately NOT
           probed by substring: they can legitimately appear inside an
           exported project_id or user_id, which would make the assertion
           meaningless. Their absence is pinned instead by the exact closed
           property allowlist every other case asserts. *)
        Lwt.return_unit)

  let suite =
    [ selection_case; selection_failure_case; creation_case;
      creation_failure_case; request_case; request_failure_case;
      request_concurrency_case; review_case; review_failure_case;
      review_concurrency_case; provisioning_case; provisioning_failure_case;
      provisioning_concurrency_case; publication_case;
      publication_failure_case; publication_concurrency_case; removal_case;
      removal_failure_case; removal_concurrency_case; privacy_case
    ]
end


(* === Login session replacement (stale-admin privilege regression) ===
   The successful-login path must derive the session exclusively from the
   newly authenticated user: it invalidates whatever session the browser
   presented (rotating the session id) and rewrites every canonical field —
   user_id, username, and is_admin unconditionally, including the false
   case. Before the fix, is_admin was written only when true, so an
   admin → non-admin re-login in the same browser session silently kept
   admin authorization. These cases drive the real handlers through one
   pipeline instance with a cookie jar, exactly like a browser reusing a
   session cookie across logins. Database-gated. *)
module Auth_session_replacement = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM notifications WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'asr_%')"
      ; "DELETE FROM pending_signups WHERE username LIKE 'asr_%'"
      ; "DELETE FROM users WHERE username LIKE 'asr_%'"
      ]

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let or_fail_s label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label e

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let q_insert_user =
    (Caqti_type.(t3 string string bool) ->! Caqti_type.int)
      "INSERT INTO users (username, email, password_hash, is_email_verified, is_admin)
       VALUES ($1, $1 || '@test.invalid', $2, TRUE, $3) RETURNING id"

  let q_is_banned =
    (Caqti_type.int ->! Caqti_type.bool)
      "SELECT is_banned FROM users WHERE id = $1"

  let q_set_banned =
    (Caqti_type.int ->. Caqti_type.unit)
      "UPDATE users SET is_banned = TRUE WHERE id = $1"

  let q_insert_pending =
    (Caqti_type.(t2 string string) ->. Caqti_type.unit)
      "INSERT INTO pending_signups (username, email, password_hash, token_hash, expires_at)
       VALUES ($1, $1 || '@test.invalid', 'x', $2, NOW() + INTERVAL '1 hour')"

  let form_body fields =
    String.concat "&"
      (List.map
         (fun (k, v) ->
           Dream.to_percent_encoded k ^ "=" ^ Dream.to_percent_encoded v)
         fields)

  (* One [client] models one browser: a single pipeline instance (so
     memory_sessions state persists across requests) plus a cookie jar
     carried between requests. POST forms get a valid dream.csrf minted
     inside the pipeline, under the session the jar cookie selects — the
     same token a served form would carry. The extra probe routes are
     test-only: /whoami serializes the full session dictionary (field
     names and fixture values only), and /poison plants another user's
     authenticated fields to model the pre-fix stale state directly. *)
  type client = {
    pipeline : Dream.request -> Dream.response Dream.promise;
    jar : (string * string) list ref;
    pending_form : (string * string) list option ref;
  }

  let make_client ~url ~poison_fields =
    let pending_form = ref None in
    let with_form handler req =
      (match !pending_form with
      | None -> ()
      | Some fields ->
          pending_form := None;
          let csrf = Dream.csrf_token req in
          Dream.set_body req (form_body (("dream.csrf", csrf) :: fields)));
      handler req
    in
    let pipeline =
      Dream.sql_pool url @@ Dream.memory_sessions
      @@ Dream.router
           [ Dream.get "/login" Earde.Handlers.login_page
           ; Dream.post "/login" (with_form Earde.Handlers.login_handler)
           ; Dream.post "/logout" Earde.Handlers.logout_handler
           ; Dream.get "/confirm" Earde.Handlers.confirm_email_handler
           ; Dream.get "/admin" Earde.Handlers.admin_dashboard_handler
           ; Dream.post "/admin/ban/user/:id"
               (with_form Earde.Handlers.ban_user_handler)
           ; Dream.post "/admin/unban/user/:id"
               (with_form Earde.Handlers.unban_user_global_handler)
           ; Dream.get "/whoami" (fun req ->
                 Dream.respond
                   (String.concat "\n"
                      (List.sort compare
                         (List.map
                            (fun (k, v) -> k ^ "=" ^ v)
                            (Dream.all_session_fields req)))))
           ; Dream.get "/poison" (fun req ->
                 let* () =
                   Lwt_list.iter_s
                     (fun (k, v) -> Dream.set_session_field req k v)
                     poison_fields
                 in
                 Dream.respond "poisoned")
           ]
    in
    { pipeline; jar = ref []; pending_form }

  let update_jar jar response =
    List.iter
      (fun header ->
        match String.split_on_char ';' header with
        | pair :: _ -> (
            match String.index_opt pair '=' with
            | Some i ->
                let name = String.sub pair 0 i in
                let value =
                  String.sub pair (i + 1) (String.length pair - i - 1)
                in
                jar := (name, value) :: List.remove_assoc name !jar
            | None -> ())
        | [] -> ())
      (Dream.headers response "Set-Cookie")

  let send client ?(method_ = `GET) ?form target =
    client.pending_form := form;
    let headers =
      (match !(client.jar) with
      | [] -> []
      | pairs ->
          [ ( "Cookie",
              String.concat "; "
                (List.map (fun (n, v) -> n ^ "=" ^ v) pairs) ) ])
      @
      match form with
      | Some _ -> [ ("Content-Type", "application/x-www-form-urlencoded") ]
      | None -> []
    in
    let request = Dream.request ~method_ ~target ~headers "" in
    let* response = client.pipeline request in
    update_jar client.jar response;
    let* body = Dream.body response in
    Lwt.return (Dream.status_to_int (Dream.status response), body)

  (* The session id is material: comparisons are boolean, and failure
     messages never print a cookie value. *)
  let session_cookie client =
    match List.assoc_opt "dream.session" !(client.jar) with
    | Some v -> v
    | None -> Alcotest.fail "no dream.session cookie in the jar"

  let check_session label expected body =
    Alcotest.(check string) (label ^ ": exact session fields") expected body

  let session_of ~uid ~username ~is_admin =
    Printf.sprintf "is_admin=%b\nuser_id=%d\nusername=%s" is_admin uid
      username

  let login client ~identifier ~password =
    send client ~method_:`POST
      ~form:[ ("identifier", identifier); ("password", password) ]
      "/login"

  let fixture_users (module C : Caqti_lwt.CONNECTION) =
    let* hash = Earde.Auth.hash_password "asr password" in
    let* hash = or_fail_s "hash" hash in
    let* admin = C.find q_insert_user ("asr_admin", hash, true) in
    let* admin = or_fail "admin" admin in
    let* user = C.find q_insert_user ("asr_user", hash, false) in
    let* user = or_fail "user" user in
    let* victim = C.find q_insert_user ("asr_victim", hash, false) in
    let* victim = or_fail "victim" victim in
    Lwt.return (admin, user, victim)

  let admin_then_user_case =
    db_case
      "admin then non-admin login in one browser session drops all admin \
       authorization"
      (fun ~url c ->
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* admin, user, victim = fixture_users c in
        let client = make_client ~url ~poison_fields:[] in
        (* Pre-auth browsing creates the pre-session the login must replace. *)
        let* status, _ = send client "/login" in
        Alcotest.(check int) "login page" 200 status;
        let pre_auth_cookie = session_cookie client in
        let* status, _ =
          login client ~identifier:"asr_admin" ~password:"asr password"
        in
        Alcotest.(check bool) "admin login redirects" true (status / 100 = 3);
        let admin_cookie = session_cookie client in
        Alcotest.(check bool) "login rotates the pre-auth session id" false
          (String.equal pre_auth_cookie admin_cookie);
        let* _, body = send client "/whoami" in
        check_session "admin session"
          (session_of ~uid:admin ~username:"asr_admin" ~is_admin:true)
          body;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "admin dashboard allowed" 200 status;
        (* Reversible protected POST: ban then unban really hit the DB. The
           empty form still carries the session's minted dream.csrf — the
           hardened handlers validate it before mutating. *)
        let* status, _ =
          send client ~method_:`POST ~form:[]
            (Printf.sprintf "/admin/ban/user/%d" victim)
        in
        Alcotest.(check bool) "ban redirects" true (status / 100 = 3);
        let* banned = C.find q_is_banned victim in
        let* banned = or_fail "banned" banned in
        Alcotest.(check bool) "victim banned by admin" true banned;
        let* status, _ =
          send client ~method_:`POST ~form:[]
            (Printf.sprintf "/admin/unban/user/%d" victim)
        in
        Alcotest.(check bool) "unban redirects" true (status / 100 = 3);
        let* banned = C.find q_is_banned victim in
        let* banned = or_fail "unbanned" banned in
        Alcotest.(check bool) "victim unbanned again" false banned;
        (* The same browser session now logs in as a non-admin. *)
        let* status, _ =
          login client ~identifier:"asr_user" ~password:"asr password"
        in
        Alcotest.(check bool) "user login redirects" true (status / 100 = 3);
        let user_cookie = session_cookie client in
        Alcotest.(check bool) "re-login rotates the session id" false
          (String.equal admin_cookie user_cookie);
        let* _, body = send client "/whoami" in
        check_session "non-admin session inherits nothing"
          (session_of ~uid:user ~username:"asr_user" ~is_admin:false)
          body;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "admin dashboard now denied" 403 status;
        let* status, body =
          send client ~method_:`POST
            (Printf.sprintf "/admin/ban/user/%d" victim)
        in
        Alcotest.(check int) "ban denied status" 200 status;
        Alcotest.(check bool) "ban denied body" true
          (contains body "not an Admin");
        let* banned = C.find q_is_banned victim in
        let* banned = or_fail "still unbanned" banned in
        Alcotest.(check bool) "denied ban wrote nothing" false banned;
        Lwt.return_unit)

  let user_then_admin_case =
    db_case
      "non-admin then admin login gains admin; logout clears the session"
      (fun ~url c ->
        let* admin, user, _victim = fixture_users c in
        let client = make_client ~url ~poison_fields:[] in
        let* _ =
          login client ~identifier:"asr_user" ~password:"asr password"
        in
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "user denied admin" 403 status;
        let* status, _ =
          login client ~identifier:"asr_admin" ~password:"asr password"
        in
        Alcotest.(check bool) "admin login redirects" true (status / 100 = 3);
        let* _, body = send client "/whoami" in
        check_session "admin session after upgrade"
          (session_of ~uid:admin ~username:"asr_admin" ~is_admin:true)
          body;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "admin allowed after upgrade" 200 status;
        (* Logout must leave no user-derived field behind. *)
        let* status, _ = send client ~method_:`POST ~form:[] "/logout" in
        Alcotest.(check bool) "logout redirects" true (status / 100 = 3);
        let* _, body = send client "/whoami" in
        check_session "logged-out session is empty" "" body;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "admin denied after logout" 403 status;
        (* Login after logout derives only from the new user. *)
        let* _ =
          login client ~identifier:"asr_user" ~password:"asr password"
        in
        let* _, body = send client "/whoami" in
        check_session "post-logout login is only the new user"
          (session_of ~uid:user ~username:"asr_user" ~is_admin:false)
          body;
        Lwt.return_unit)

  let failed_login_case =
    db_case
      "failed and banned logins authenticate no one and leave the prior \
       session unmixed"
      (fun ~url c ->
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* admin, _user, victim = fixture_users c in
        (* Failed attempt from a clean browser: no identity, no admin. *)
        let clean = make_client ~url ~poison_fields:[] in
        let* status, _ =
          login clean ~identifier:"asr_user" ~password:"wrong"
        in
        Alcotest.(check int) "failed login status" 200 status;
        let* _, body = send clean "/whoami" in
        check_session "failed login leaves no identity" "" body;
        let* status, _ = send clean "/admin" in
        Alcotest.(check int) "failed login grants nothing" 403 status;
        (* Failed attempt while an admin session exists: the old session
           survives intact — no mixed identity, no privilege change. *)
        let client = make_client ~url ~poison_fields:[] in
        let* _ =
          login client ~identifier:"asr_admin" ~password:"asr password"
        in
        let* status, _ =
          login client ~identifier:"asr_user" ~password:"wrong"
        in
        Alcotest.(check int) "failed re-login status" 200 status;
        let* _, body = send client "/whoami" in
        check_session "prior admin session unchanged"
          (session_of ~uid:admin ~username:"asr_admin" ~is_admin:true)
          body;
        (* A banned account with the right password gets no session either. *)
        let* r = C.exec q_set_banned victim in
        let* () = or_fail "ban victim" r in
        let banned_client = make_client ~url ~poison_fields:[] in
        let* status, _ =
          login banned_client ~identifier:"asr_victim"
            ~password:"asr password"
        in
        Alcotest.(check int) "banned login status" 200 status;
        let* _, body = send banned_client "/whoami" in
        check_session "banned login leaves no identity" "" body;
        Lwt.return_unit)

  let poisoned_session_case =
    db_case
      "stale pre-authentication session fields cannot survive a successful \
       login"
      (fun ~url c ->
        let* admin, user, _victim = fixture_users c in
        (* Plant the exact pre-fix stale state: an authenticated admin
           session, then a non-admin login over it. *)
        let client =
          make_client ~url
            ~poison_fields:
              [ ("user_id", string_of_int admin)
              ; ("username", "asr_admin")
              ; ("is_admin", "true")
              ]
        in
        let* status, _ = send client "/poison" in
        Alcotest.(check int) "poison probe" 200 status;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "poisoned session is admin-capable" 200 status;
        let* _ =
          login client ~identifier:"asr_user" ~password:"asr password"
        in
        let* _, body = send client "/whoami" in
        check_session "login replaced every stale field"
          (session_of ~uid:user ~username:"asr_user" ~is_admin:false)
          body;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "stale admin capability gone" 403 status;
        Lwt.return_unit)

  let confirm_no_session_case =
    db_case "signup email confirmation establishes no authenticated session"
      (fun ~url c ->
        let (module C : Caqti_lwt.CONNECTION) = c in
        let hash = Earde.Db.pending_signup_hash_token "asr_confirm_tok" in
        let* r = C.exec q_insert_pending ("asr_signup", hash) in
        let* () = or_fail "pending" r in
        let client = make_client ~url ~poison_fields:[] in
        let* status, _ = send client "/confirm?token=asr_confirm_tok" in
        Alcotest.(check int) "confirm status" 200 status;
        let* _, body = send client "/whoami" in
        check_session "confirmation leaves no identity" "" body;
        let* status, _ = send client "/admin" in
        Alcotest.(check int) "confirmation grants nothing" 403 status;
        Lwt.return_unit)

  let suite =
    [ admin_then_user_case; user_then_admin_case; failed_login_case;
      poisoned_session_case; confirm_no_session_case
    ]
end

(* === Report flow private-community authorization ==========================
   Regression suite for the private-target exposure in GET /c/:slug/report and
   POST /c/:slug/reports: both handlers must run can_view_community BEFORE any
   ban check or target resolution, and deny an outsider with the canonical
   community_not_found 404 — byte-identical to a missing community, a missing
   target and a wrong-typed target, leaking neither community existence nor
   target existence. Exercises the REAL handlers over a real Dream pipeline
   (router + sql_pool + memory_sessions), never the access helper alone.
   Database-gated (EARDE_TEST_DATABASE_URL). *)
module Report_private_authz = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM reports WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"
      ; "DELETE FROM reports WHERE reporter_user_id IN (SELECT id FROM users WHERE username LIKE 'rpta_%')"
      ; "DELETE FROM notifications WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'rpta_%')"
      ; "DELETE FROM mod_actions WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"
      ; "DELETE FROM comments WHERE post_id IN (SELECT id FROM posts WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%'))"
      ; "DELETE FROM posts WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"
      ; "DELETE FROM community_bans WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"
      ; "DELETE FROM community_members WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"
      ; "DELETE FROM community_moderators WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"
      ; "DELETE FROM communities WHERE slug LIKE 'rpta-%'"
      ; "DELETE FROM users WHERE username LIKE 'rpta_%'"
      ]

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let q_insert_user =
    (Caqti_type.string ->! Caqti_type.int)
      "INSERT INTO users (username, email, password_hash, is_email_verified)
       VALUES ($1, $1 || '@test.invalid', 'x', TRUE) RETURNING id"

  let q_insert_community =
    (Caqti_type.(t2 string string) ->! Caqti_type.int)
      "INSERT INTO communities (slug, name, sections_enabled, visibility)
       VALUES ($1, $1, FALSE, $2) RETURNING id"

  let q_insert_post =
    (Caqti_type.(t3 string int int) ->! Caqti_type.int)
      "INSERT INTO posts (title, content, community_id, user_id)
       VALUES ($1, $1 || ' body', $2, $3) RETURNING id"

  let q_insert_comment =
    (Caqti_type.(t3 string int int) ->! Caqti_type.int)
      "INSERT INTO comments (content, post_id, user_id)
       VALUES ($1, $2, $3) RETURNING id"

  let q_add_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  let q_add_moderator =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_moderators (user_id, community_id, role) VALUES ($1, $2, 'mod')"

  let q_add_community_ban =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_bans (user_id, community_id) VALUES ($1, $2)"

  let q_set_globally_banned =
    (Caqti_type.int ->. Caqti_type.unit)
      "UPDATE users SET is_banned = TRUE WHERE id = $1"

  let q_count_reports =
    (Caqti_type.unit ->! Caqti_type.int)
      "SELECT COUNT(*) FROM reports WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"

  let q_count_mod_actions =
    (Caqti_type.unit ->! Caqti_type.int)
      "SELECT COUNT(*) FROM mod_actions WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'rpta-%')"

  let q_count_notifications =
    (Caqti_type.unit ->! Caqti_type.int)
      "SELECT COUNT(*) FROM notifications WHERE user_id IN (SELECT id FROM users WHERE username LIKE 'rpta_%')"

  (* Distinctive markers that must NEVER appear in a denied response. *)
  let secret_post_title = "RPTA-PRIV-SECRET post title"
  let secret_comment_body = "RPTA-PRIV-SECRET comment body"

  type fx = {
    outsider : int;
    member : int;
    moderator : int;
    admin : int;
    pub_author : int;
    priv_author : int;
    pub : int;
    pub_post : int;
    priv_post : int;
    pub_comment : int;
    priv_comment : int;
  }

  let make_fixtures (module C : Caqti_lwt.CONNECTION) =
    let user name =
      let* id = C.find q_insert_user name in
      or_fail name id
    in
    let* outsider = user "rpta_outsider" in
    let* member = user "rpta_member" in
    let* moderator = user "rpta_moderator" in
    let* admin = user "rpta_admin" in
    let* pub_author = user "rpta_pubauthor" in
    let* priv_author = user "rpta_privauthor" in
    let* pub = C.find q_insert_community ("rpta-pub", "public") in
    let* pub = or_fail "pub community" pub in
    let* priv = C.find q_insert_community ("rpta-priv", "private") in
    let* priv = or_fail "priv community" priv in
    (* member and priv_author are members of the private community; the
       moderator has ONLY a moderator row (no membership) — mod access must
       not depend on a membership row. *)
    let* r = C.exec q_add_member (member, priv) in
    let* () = or_fail "member row" r in
    let* r = C.exec q_add_member (priv_author, priv) in
    let* () = or_fail "priv author member row" r in
    let* r = C.exec q_add_moderator (moderator, priv) in
    let* () = or_fail "moderator row" r in
    let* pub_post = C.find q_insert_post ("rpta public post", pub, pub_author) in
    let* pub_post = or_fail "pub post" pub_post in
    let* priv_post = C.find q_insert_post (secret_post_title, priv, priv_author) in
    let* priv_post = or_fail "priv post" priv_post in
    let* pub_comment = C.find q_insert_comment ("rpta public comment", pub_post, pub_author) in
    let* pub_comment = or_fail "pub comment" pub_comment in
    let* priv_comment = C.find q_insert_comment (secret_comment_body, priv_post, priv_author) in
    let* priv_comment = or_fail "priv comment" priv_comment in
    Lwt.return
      { outsider; member; moderator; admin; pub_author; priv_author;
        pub; pub_post; priv_post; pub_comment; priv_comment }

  let form_body fields =
    String.concat "&"
      (List.map
         (fun (k, v) ->
           Dream.to_percent_encoded k ^ "=" ^ Dream.to_percent_encoded v)
         fields)

  let router =
    Dream.router
      [ Dream.get "/c/:slug/report" Earde.Handlers.report_form_handler
      ; Dream.post "/c/:slug/reports" Earde.Handlers.create_report_handler
      ]

  (* One request against the real pipeline. A [form] makes it a POST and
     injects a fresh, VALID dream.csrf minted under the same session — so a
     denied POST is denied by authorization, never by CSRF. *)
  let run ~url ?(session = []) ?form target =
    let pipeline =
      Dream.sql_pool url @@ Dream.memory_sessions @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      (match form with
       | None -> ()
       | Some fields ->
           let csrf = Dream.csrf_token req in
           Dream.set_body req (form_body (("dream.csrf", csrf) :: fields)));
      router req
    in
    let method_ = match form with Some _ -> `POST | None -> `GET in
    let headers =
      match form with
      | Some _ -> [ ("Content-Type", "application/x-www-form-urlencoded") ]
      | None -> []
    in
    let request = Dream.request ~method_ ~target ~headers "" in
    let* response = pipeline request in
    let* body = Dream.body response in
    Lwt.return
      ( Dream.status_to_int (Dream.status response),
        Dream.header response "Location",
        body )

  let session_of ?(admin = false) uid name =
    [ ("user_id", string_of_int uid); ("username", name) ]
    @ if admin then [ ("is_admin", "true") ] else []

  let find_sub hay needle from =
    let nl = String.length needle and hl = String.length hay in
    let rec go i =
      if i + nl > hl then None
      else if String.sub hay i nl = needle then Some i
      else go (i + 1)
    in
    if nl = 0 then Some from else go from

  let has_sub hay needle = find_sub hay needle 0 <> None

  (* Blank the one volatile value in an authorized form document: the
     dream.csrf hidden input's value. Everything else must be stable. *)
  let mask_csrf body =
    match find_sub body "dream.csrf" 0 with
    | None -> body
    | Some i ->
        (match find_sub body "value=\"" i with
         | None -> body
         | Some j ->
             let vstart = j + String.length "value=\"" in
             (match String.index_from_opt body vstart '"' with
              | None -> body
              | Some vend ->
                  String.sub body 0 vstart
                  ^ "CSRF"
                  ^ String.sub body vend (String.length body - vend)))

  let check_no_leak label body =
    Alcotest.(check bool) (label ^ ": no post excerpt") false
      (has_sub body secret_post_title);
    Alcotest.(check bool) (label ^ ": no comment excerpt") false
      (has_sub body secret_comment_body);
    Alcotest.(check bool) (label ^ ": no private community name") false
      (has_sub body "rpta-priv")

  let get_target slug ty id =
    Printf.sprintf "/c/%s/report?type=%s&id=%d" slug ty id

  let post_form ty id =
    [ ("target_type", ty); ("target_id", string_of_int id);
      ("reason", "spam"); ("details", "rpta details") ]

  let is_redirect s = s = 301 || s = 302 || s = 303 || s = 307 || s = 308

  let submit_ok ~url ~label ~session ~slug ~ty ~id () =
    let* status, _, body =
      run ~url ~session ~form:(post_form ty id) ("/c/" ^ slug ^ "/reports")
    in
    Alcotest.(check int) (label ^ ": POST status") 200 status;
    Alcotest.(check bool) (label ^ ": submitted") true
      (has_sub body "Report submitted");
    Lwt.return_unit

  let open_form_ok ~url ~label ~session ~slug ~ty ~id () =
    let* status, _, body = run ~url ~session (get_target slug ty id) in
    Alcotest.(check int) (label ^ ": GET status") 200 status;
    Alcotest.(check bool) (label ^ ": form present") true
      (has_sub body ("<form action='/c/" ^ slug ^ "/reports' method='POST'"));
    Lwt.return body

  (* 1: anonymous access keeps its existing contract (redirect to /login). *)
  let anonymous_case =
    db_case "anonymous GET and POST redirect to /login, nothing rendered"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let* status, location, body =
          run ~url (get_target "rpta-priv" "post" fx.priv_post)
        in
        Alcotest.(check bool) "GET redirects" true (is_redirect status);
        Alcotest.(check (option string)) "GET location" (Some "/login") location;
        check_no_leak "anonymous GET" body;
        let* status, location, _ =
          run ~url ~form:(post_form "post" fx.priv_post) "/c/rpta-priv/reports"
        in
        Alcotest.(check bool) "POST redirects" true (is_redirect status);
        Alcotest.(check (option string)) "POST location" (Some "/login") location;
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* n = C.find q_count_reports () in
        let* n = or_fail "count" n in
        Alcotest.(check int) "no report row" 0 n;
        Lwt.return_unit)

  (* 2+3: public-community reporting still works for members AND non-members. *)
  let public_reporting_case =
    db_case "public community: member and non-member can open and submit"
      (fun ~url c ->
        let* fx = make_fixtures c in
        (* rpta_member is a member of the PRIVATE community only, so against
           the public community it is a plain authenticated non-member. *)
        let outsider = session_of fx.outsider "rpta_outsider" in
        let member = session_of fx.member "rpta_member" in
        let* _ =
          open_form_ok ~url ~label:"non-member post form" ~session:outsider
            ~slug:"rpta-pub" ~ty:"post" ~id:fx.pub_post ()
        in
        let* _ =
          open_form_ok ~url ~label:"non-member comment form" ~session:outsider
            ~slug:"rpta-pub" ~ty:"comment" ~id:fx.pub_comment ()
        in
        let* () =
          submit_ok ~url ~label:"non-member post" ~session:outsider
            ~slug:"rpta-pub" ~ty:"post" ~id:fx.pub_post ()
        in
        let* () =
          submit_ok ~url ~label:"non-member comment" ~session:outsider
            ~slug:"rpta-pub" ~ty:"comment" ~id:fx.pub_comment ()
        in
        let* _ =
          open_form_ok ~url ~label:"member form" ~session:member
            ~slug:"rpta-pub" ~ty:"post" ~id:fx.pub_post ()
        in
        let* () =
          submit_ok ~url ~label:"member post" ~session:member ~slug:"rpta-pub"
            ~ty:"post" ~id:fx.pub_post ()
        in
        (* Duplicate contract unchanged: a second identical open report by the
           same reporter inserts nothing and says so. *)
        let* status, _, body =
          run ~url ~session:member ~form:(post_form "post" fx.pub_post)
            "/c/rpta-pub/reports"
        in
        Alcotest.(check int) "duplicate status" 200 status;
        Alcotest.(check bool) "duplicate copy" true
          (has_sub body "Already reported");
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* n = C.find q_count_reports () in
        let* n = or_fail "count" n in
        Alcotest.(check int) "three rows (dup inserted nothing)" 3 n;
        Lwt.return_unit)

  (* 4+5+6: authorized private viewers (member, moderator-without-membership,
     admin) keep full access. *)
  let private_authorized_case =
    db_case "private community: member, moderator and admin open and submit"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let member = session_of fx.member "rpta_member" in
        let moderator = session_of fx.moderator "rpta_moderator" in
        let admin = session_of ~admin:true fx.admin "rpta_admin" in
        let* body =
          open_form_ok ~url ~label:"member post form" ~session:member
            ~slug:"rpta-priv" ~ty:"post" ~id:fx.priv_post ()
        in
        Alcotest.(check bool) "member sees the excerpt" true
          (has_sub body secret_post_title);
        let* _ =
          open_form_ok ~url ~label:"member comment form" ~session:member
            ~slug:"rpta-priv" ~ty:"comment" ~id:fx.priv_comment ()
        in
        let* () =
          submit_ok ~url ~label:"member post" ~session:member
            ~slug:"rpta-priv" ~ty:"post" ~id:fx.priv_post ()
        in
        let* () =
          submit_ok ~url ~label:"member comment" ~session:member
            ~slug:"rpta-priv" ~ty:"comment" ~id:fx.priv_comment ()
        in
        let* _ =
          open_form_ok ~url ~label:"moderator form (no member row)"
            ~session:moderator ~slug:"rpta-priv" ~ty:"post" ~id:fx.priv_post ()
        in
        let* () =
          submit_ok ~url ~label:"moderator post" ~session:moderator
            ~slug:"rpta-priv" ~ty:"post" ~id:fx.priv_post ()
        in
        let* _ =
          open_form_ok ~url ~label:"admin form" ~session:admin
            ~slug:"rpta-priv" ~ty:"post" ~id:fx.priv_post ()
        in
        let* () =
          submit_ok ~url ~label:"admin post" ~session:admin ~slug:"rpta-priv"
            ~ty:"post" ~id:fx.priv_post ()
        in
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* n = C.find q_count_reports () in
        let* n = or_fail "count" n in
        Alcotest.(check int) "four rows" 4 n;
        Lwt.return_unit)

  (* 7+8+11+12: outsider GETs — valid post, valid comment, nonexistent id and
     missing community are ALL the same canonical 404, byte for byte. *)
  let outsider_get_case =
    db_case
      "outsider GET: private targets, bogus ids and missing communities are \
       one indistinguishable 404"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let outsider = session_of fx.outsider "rpta_outsider" in
        let get t = run ~url ~session:outsider t in
        let* s1, _, valid_post = get (get_target "rpta-priv" "post" fx.priv_post) in
        let* s2, _, valid_comment =
          get (get_target "rpta-priv" "comment" fx.priv_comment)
        in
        let* s3, _, bogus_id = get (get_target "rpta-priv" "post" 999999999) in
        let* s4, _, missing_community =
          get (get_target "rpta-missing" "post" fx.priv_post)
        in
        let* s5, _, wrong_type = get (get_target "rpta-priv" "comment" fx.priv_post) in
        Alcotest.(check (list int)) "all 404"
          [ 404; 404; 404; 404; 404 ] [ s1; s2; s3; s4; s5 ];
        Alcotest.(check string) "valid post = valid comment" valid_post valid_comment;
        Alcotest.(check string) "valid = nonexistent id" valid_post bogus_id;
        Alcotest.(check string) "existing private = missing community"
          valid_post missing_community;
        Alcotest.(check string) "valid = wrong-typed id" valid_post wrong_type;
        check_no_leak "outsider GET" valid_post;
        Lwt.return_unit)

  (* 9+10+11+14+15: outsider POSTs — same canonical 404 for every private
     variant, with a fresh valid CSRF token, and ZERO side effects. *)
  let outsider_post_case =
    db_case
      "outsider POST: valid CSRF still denies, indistinguishably, with no \
       report/modlog/notification row"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let outsider = session_of fx.outsider "rpta_outsider" in
        let post ~slug form = run ~url ~session:outsider ~form ("/c/" ^ slug ^ "/reports") in
        let* s1, _, valid_post = post ~slug:"rpta-priv" (post_form "post" fx.priv_post) in
        let* s2, _, valid_comment =
          post ~slug:"rpta-priv" (post_form "comment" fx.priv_comment)
        in
        let* s3, _, bogus_id = post ~slug:"rpta-priv" (post_form "post" 999999999) in
        let* s4, _, missing_community =
          post ~slug:"rpta-missing" (post_form "post" fx.priv_post)
        in
        Alcotest.(check (list int)) "all 404" [ 404; 404; 404; 404 ]
          [ s1; s2; s3; s4 ];
        Alcotest.(check string) "valid post = valid comment" valid_post valid_comment;
        Alcotest.(check string) "valid = nonexistent id" valid_post bogus_id;
        Alcotest.(check string) "existing private = missing community"
          valid_post missing_community;
        check_no_leak "outsider POST" valid_post;
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* n = C.find q_count_reports () in
        let* n = or_fail "reports" n in
        Alcotest.(check int) "no report row" 0 n;
        let* n = C.find q_count_mod_actions () in
        let* n = or_fail "mod_actions" n in
        Alcotest.(check int) "no modlog row" 0 n;
        let* n = C.find q_count_notifications () in
        let* n = or_fail "notifications" n in
        Alcotest.(check int) "no notification" 0 n;
        Lwt.return_unit)

  (* 13: cross-community tampering under a PUBLIC slug must not reveal that
     the private target id exists — identical to a nonexistent id. *)
  let cross_community_case =
    db_case
      "cross-community tampering: private id under a public slug behaves \
       exactly like a nonexistent id"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let outsider = session_of fx.outsider "rpta_outsider" in
        let* s1, _, tampered_get =
          run ~url ~session:outsider (get_target "rpta-pub" "post" fx.priv_post)
        in
        let* s2, _, bogus_get =
          run ~url ~session:outsider (get_target "rpta-pub" "post" 999999999)
        in
        Alcotest.(check (list int)) "GET statuses" [ 400; 400 ] [ s1; s2 ];
        Alcotest.(check string) "tampered GET = bogus GET" bogus_get tampered_get;
        check_no_leak "tampered GET" tampered_get;
        let* s3, _, tampered_post =
          run ~url ~session:outsider ~form:(post_form "post" fx.priv_post)
            "/c/rpta-pub/reports"
        in
        let* s4, _, bogus_post =
          run ~url ~session:outsider ~form:(post_form "post" 999999999)
            "/c/rpta-pub/reports"
        in
        Alcotest.(check (list int)) "POST statuses" [ 404; 404 ] [ s3; s4 ];
        Alcotest.(check string) "tampered POST = bogus POST" bogus_post tampered_post;
        check_no_leak "tampered POST" tampered_post;
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* n = C.find q_count_reports () in
        let* n = or_fail "count" n in
        Alcotest.(check int) "no report row" 0 n;
        Lwt.return_unit)

  (* 16: global-ban, community-ban and self-report restrictions unchanged for
     viewers the community gate admits; an unauthorized outsider's global ban
     no longer confirms private-community existence. *)
  let restrictions_case =
    db_case "ban and self-report gates unchanged; ban page never leaks privates"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let (module C : Caqti_lwt.CONNECTION) = c in
        (* Globally banned user on a PUBLIC community: same Account Banned page. *)
        let* r = C.exec q_set_globally_banned fx.outsider in
        let* () = or_fail "gban" r in
        let outsider = session_of fx.outsider "rpta_outsider" in
        let* status, _, body =
          run ~url ~session:outsider (get_target "rpta-pub" "post" fx.pub_post)
        in
        Alcotest.(check int) "gban GET public 403" 403 status;
        Alcotest.(check bool) "gban copy" true (has_sub body "Account Banned");
        let* status, _, _ =
          run ~url ~session:outsider ~form:(post_form "post" fx.pub_post)
            "/c/rpta-pub/reports"
        in
        Alcotest.(check int) "gban POST public 403" 403 status;
        (* The same banned OUTSIDER against the PRIVATE community gets the
           canonical 404 — the ban page must not confirm the community exists. *)
        let* status, _, body =
          run ~url ~session:outsider (get_target "rpta-priv" "post" fx.priv_post)
        in
        Alcotest.(check int) "gban outsider private 404" 404 status;
        check_no_leak "gban outsider" body;
        (* A globally banned MEMBER of the private community still sees the
           ban page: the view gate admits them, then the ban gate fires. *)
        let* r = C.exec q_set_globally_banned fx.member in
        let* () = or_fail "gban member" r in
        let member = session_of fx.member "rpta_member" in
        let* status, _, body =
          run ~url ~session:member (get_target "rpta-priv" "post" fx.priv_post)
        in
        Alcotest.(check int) "gban member private 403" 403 status;
        Alcotest.(check bool) "gban member copy" true
          (has_sub body "Account Banned");
        (* Community ban on the public community. *)
        let* r = C.exec q_add_community_ban (fx.priv_author, fx.pub) in
        let* () = or_fail "cban" r in
        let cbanned = session_of fx.priv_author "rpta_privauthor" in
        let* status, _, body =
          run ~url ~session:cbanned (get_target "rpta-pub" "post" fx.pub_post)
        in
        Alcotest.(check int) "cban GET 403" 403 status;
        Alcotest.(check bool) "cban copy" true
          (has_sub body "Banned from Community");
        let* status, _, _ =
          run ~url ~session:cbanned ~form:(post_form "post" fx.pub_post)
            "/c/rpta-pub/reports"
        in
        Alcotest.(check int) "cban POST 403" 403 status;
        (* Self-report still refused. *)
        let author = session_of fx.pub_author "rpta_pubauthor" in
        let* status, _, body =
          run ~url ~session:author (get_target "rpta-pub" "post" fx.pub_post)
        in
        Alcotest.(check int) "self GET 403" 403 status;
        Alcotest.(check bool) "self copy" true (has_sub body "Cannot Report");
        let* status, _, _ =
          run ~url ~session:author ~form:(post_form "post" fx.pub_post)
            "/c/rpta-pub/reports"
        in
        Alcotest.(check int) "self POST 403" 403 status;
        let* n = C.find q_count_reports () in
        let* n = or_fail "count" n in
        Alcotest.(check int) "nothing inserted" 0 n;
        Lwt.return_unit)

  (* 17: the authorized Cartographic form document is stable — two renders
     differ only in the dream.csrf value — and the pinned form contract
     (action, hidden fields, reasons, details cap) is intact. *)
  let form_contract_case =
    db_case "authorized form: byte-stable after CSRF masking, contract pinned"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let member = session_of fx.member "rpta_member" in
        let target = get_target "rpta-priv" "post" fx.priv_post in
        let* s1, _, first = run ~url ~session:member target in
        let* s2, _, second = run ~url ~session:member target in
        Alcotest.(check (list int)) "both 200" [ 200; 200 ] [ s1; s2 ];
        Alcotest.(check bool) "csrf token present" true
          (has_sub first "dream.csrf");
        Alcotest.(check string) "byte-identical after csrf masking"
          (mask_csrf first) (mask_csrf second);
        List.iter
          (fun needle ->
            Alcotest.(check bool) ("contract: " ^ needle) true
              (has_sub first needle))
          [ "<form action='/c/rpta-priv/reports' method='POST'"
          ; "<input type='hidden' name='target_type' value='post'>"
          ; Printf.sprintf "<input type='hidden' name='target_id' value='%d'>"
              fx.priv_post
          ; "<option value='spam'>"
          ; "<option value='abuse'>"
          ; "<option value='off_topic'>"
          ; "<option value='illegal'>"
          ; "<option value='other'>"
          ; "maxlength='1000'"
          ];
        Lwt.return_unit)

  let suite =
    [ anonymous_case; public_reporting_case; private_authorized_case;
      outsider_get_case; outsider_post_case; cross_community_case;
      restrictions_case; form_contract_case
    ]
end

(* === Flat-community guest Share script (pass 15A follow-up) ===
   The byte-pinned render_post rows show the Share control to every viewer,
   but only member documents carry the full launch behavior script (which
   defines copyPostLink). The flat community home therefore ships the
   guest-only share script — the SAME single copyPostLink source — so the
   control works anonymously without any notification fetch or
   authenticated-only behavior. These cases exercise the real
   community_page_handler through the production pipeline shape. *)
module Flat_share_script = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM posts WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'fshr-%')"
      ; "DELETE FROM community_members WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'fshr-%')"
      ; "DELETE FROM community_moderators WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'fshr-%')"
      ; "DELETE FROM communities WHERE slug LIKE 'fshr-%'"
      ; "DELETE FROM users WHERE username LIKE 'fshr_%'"
      ]

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let q_insert_user =
    (Caqti_type.string ->! Caqti_type.int)
      "INSERT INTO users (username, email, password_hash, is_email_verified)
       VALUES ($1, $1 || '@test.invalid', 'x', TRUE) RETURNING id"

  (* sections_enabled drives the /c/:slug branch under test: FALSE = the
     converted flat feed, TRUE = the (stable) structured overview. *)
  let q_insert_community =
    (Caqti_type.(t3 string bool string) ->! Caqti_type.int)
      "INSERT INTO communities (slug, name, sections_enabled, visibility)
       VALUES ($1, $1, $2, $3) RETURNING id"

  let q_insert_post =
    (Caqti_type.(t3 string int int) ->! Caqti_type.int)
      "INSERT INTO posts (title, content, community_id, user_id)
       VALUES ($1, $1 || ' body', $2, $3) RETURNING id"

  let q_add_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  type fx = {
    author : int;
    outsider : int;
    post_a : int;
    post_b : int;
  }

  let make_fixtures (module C : Caqti_lwt.CONNECTION) =
    let user name =
      let* id = C.find q_insert_user name in
      or_fail name id
    in
    let* author = user "fshr_author" in
    let* outsider = user "fshr_outsider" in
    let* flat = C.find q_insert_community ("fshr-flat", false, "public") in
    let* flat = or_fail "flat community" flat in
    let* () =
      let* r = C.exec q_add_member (author, flat) in
      or_fail "member" r
    in
    let* post_a = C.find q_insert_post ("Fshr share target A", flat, author) in
    let* post_a = or_fail "post a" post_a in
    let* post_b = C.find q_insert_post ("Fshr share target B", flat, author) in
    let* post_b = or_fail "post b" post_b in
    Lwt.return { author; outsider; post_a; post_b }

  (* The real /c/:slug handler, plus a probe route that renders the SAME
     shared render_post fragment the flat page must splice byte-identically.
     Anonymous rows emit no CSRF material, so the probe's bytes are
     request-independent and must appear verbatim in the page document. *)
  let router =
    Dream.router
      [ Dream.get "/c/:slug" Earde.Handlers.community_page_handler
      ; Dream.get "/feed" Earde.Handlers.feed_handler
      ; Dream.get "/search" Earde.Handlers.search_handler
      ; Dream.get "/u/:username" Earde.Handlers.view_profile_handler
      ; Dream.get "/probe/rows/:slug" (fun req ->
            Dream.sql req (fun db ->
                let slug = Dream.param req "slug" in
                let* community = Earde.Db.get_community_by_slug db slug in
                match community with
                | Ok (Some community) ->
                    let* posts =
                      Earde.Db.get_posts_by_community db community.Earde.Db.id
                        Earde.Db.Hot 20 0
                    in
                    (match posts with
                     | Ok posts ->
                         Dream.respond
                           (String.concat "\n"
                              (List.map
                                 (Earde.Components.render_post req [])
                                 posts))
                     | Error _ -> Dream.respond ~status:`Internal_Server_Error "")
                | _ -> Dream.respond ~status:`Not_Found ""))
      ]

  let run ~url ?(session = []) target =
    let pipeline =
      Dream.sql_pool url @@ Dream.memory_sessions @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      router req
    in
    let request = Dream.request ~method_:`GET ~target "" in
    let* response = pipeline request in
    let* body = Dream.body response in
    Lwt.return (Dream.status_to_int (Dream.status response), body)

  let session_of uid name =
    [ ("user_id", string_of_int uid); ("username", name) ]

  let share_onclick post_id =
    Printf.sprintf "onclick='copyPostLink(\"/p/%d\", this)'" post_id

  (* 1: an anonymous public flat page carries exactly one working
     copyPostLink definition, wired to the canonical /p/:id path, with no
     notification fetch and none of the authenticated-only behavior. *)
  let guest_case =
    db_case "anonymous flat page: one copyPostLink, no notif fetch, no auth \
             behavior" (fun ~url c ->
        let* fx = make_fixtures c in
        let* status, body = run ~url "/c/fshr-flat" in
        Alcotest.(check int) "200" 200 status;
        Alcotest.(check int) "exactly one copyPostLink definition" 1
          (ps_count body "function copyPostLink");
        Alcotest.(check int) "share button wired to post A" 1
          (ps_count body (share_onclick fx.post_a));
        Alcotest.(check int) "share button wired to post B" 1
          (ps_count body (share_onclick fx.post_b));
        Alcotest.(check int) "no notification fetch" 0
          (ps_count body "/api/unread-notifs");
        Alcotest.(check int) "no notif badge markup or init" 0
          (ps_count body "notif-badge");
        Alcotest.(check int) "no authenticated confirm modal" 0
          (ps_count body "function confirmModal");
        Alcotest.(check int) "no vote handler wiring" 0
          (ps_count body "form[action='/vote']");
        Lwt.return_unit)

  (* 2: the authenticated page still carries the full behavior script — and
     still exactly one copyPostLink definition (no duplicate from the guest
     script). *)
  let member_case =
    db_case "authenticated flat page: full behavior script, still exactly one \
             copyPostLink" (fun ~url c ->
        let* fx = make_fixtures c in
        let session = session_of fx.author "fshr_author" in
        let* status, body = run ~url ~session "/c/fshr-flat" in
        Alcotest.(check int) "200" 200 status;
        Alcotest.(check int) "exactly one copyPostLink definition" 1
          (ps_count body "function copyPostLink");
        Alcotest.(check int) "one notification fetch" 1
          (ps_count body "/api/unread-notifs");
        Alcotest.(check int) "confirm modal present" 1
          (ps_count body "function confirmModal");
        Alcotest.(check int) "share button wired" 1
          (ps_count body (share_onclick fx.post_a));
        Lwt.return_unit)

  (* 3: the spliced feed rows are the untouched shared renderer's bytes: the
     probe route renders Components.render_post for the same posts under the
     same anonymous viewer state, and that fragment appears verbatim. *)
  let row_bytes_case =
    db_case "anonymous flat rows are byte-identical to the shared render_post \
             output" (fun ~url c ->
        let* _fx = make_fixtures c in
        let* pstatus, fragment = run ~url "/probe/rows/fshr-flat" in
        Alcotest.(check int) "probe 200" 200 pstatus;
        Alcotest.(check bool) "probe rendered rows" true
          (String.length fragment > 0);
        let* status, body = run ~url "/c/fshr-flat" in
        Alcotest.(check int) "page 200" 200 status;
        Alcotest.(check bool) "row fragment spliced verbatim" true
          (ps_index_of body fragment 0 <> None);
        Lwt.return_unit)

  (* 4: the guest share script is flat-route-only — the structured overview
     and the other anonymous launch documents stay script-free. *)
  let siblings_case =
    db_case "structured overview, feed, search and profile stay free of the \
             share script" (fun ~url c ->
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* _fx = make_fixtures c in
        let* structured =
          C.find q_insert_community ("fshr-struct", true, "public")
        in
        let* _structured = or_fail "structured community" structured in
        Lwt_list.iter_s
          (fun (label, target) ->
            let* status, body = run ~url target in
            Alcotest.(check int) (label ^ ": 200") 200 status;
            Alcotest.(check int) (label ^ ": no copyPostLink") 0
              (ps_count body "function copyPostLink");
            Alcotest.(check int) (label ^ ": no notif fetch") 0
              (ps_count body "/api/unread-notifs");
            Lwt.return_unit)
          [ ("structured overview", "/c/fshr-struct"); ("feed", "/feed");
            ("search", "/search?q=fshr"); ("profile", "/u/fshr_author") ])

  (* 5: private flat communities keep the canonical anti-enumeration 404 —
     byte-identical to a missing slug, with no share script and no title
     leak. *)
  let private_case =
    db_case "private flat community: outsider gets the canonical 404, no \
             script, no leak" (fun ~url c ->
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* fx = make_fixtures c in
        let* priv =
          C.find q_insert_community ("fshr-priv", false, "private")
        in
        let* priv = or_fail "private community" priv in
        let* secret =
          C.find q_insert_post ("FSHR-PRIV-SECRET title", priv, fx.author)
        in
        let* _secret = or_fail "secret post" secret in
        let outsider = session_of fx.outsider "fshr_outsider" in
        let* s1, denied = run ~url ~session:outsider "/c/fshr-priv" in
        let* s2, missing = run ~url ~session:outsider "/c/fshr-missing" in
        Alcotest.(check (list int)) "both 404" [ 404; 404 ] [ s1; s2 ];
        Alcotest.(check bool) "denied == missing byte-identical" true
          (String.equal denied missing);
        Alcotest.(check bool) "generic copy" true
          (contains denied "This community does not exist.");
        (* The 404 is the legacy msg_page, whose layout script has always
           carried its own copyPostLink — the byte-equality above pins that
           the guest share script changed nothing about this response. *)
        Alcotest.(check bool) "no secret title" false
          (contains denied "FSHR-PRIV-SECRET");
        let* s3, anon = run ~url "/c/fshr-priv" in
        Alcotest.(check int) "anonymous 404" 404 s3;
        Alcotest.(check bool) "anonymous no secret" false
          (contains anon "FSHR-PRIV-SECRET");
        Lwt.return_unit)

  let suite =
    [ guest_case; member_case; row_bytes_case; siblings_case; private_case ]
end

(* ===== /new-post private-community authorization (pass 15B) =====
   Pins the two disclosure fixes in Handlers.new_post_page:
   1. GET /new-post?community=:slug runs can_view_community before rendering
      the creation form or join gate — a private-community outsider gets the
      canonical community_not_found 404, byte-identical to a missing slug,
      instead of learning the community's existence and name from the join
      gate and document title.
   2. The no-parameter chooser filters Db.get_all_communities through the
      same predicate — private communities are listed only for members,
      moderators, and admins.
   Exercises the REAL handler through the production-like Dream router,
   SQL pool and memory-session pipeline (same harness as the report-flow
   authorization suite). Product behavior deliberately pinned as-is: the
   creation form itself requires an ordinary membership row, so an
   authorized private moderator-without-membership or a non-member admin
   receives the (named, authorized) join gate, never the canonical 404. *)
module New_post_private_authz = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM community_sections WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'nppa-%')"
      ; "DELETE FROM community_members WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'nppa-%')"
      ; "DELETE FROM community_moderators WHERE community_id IN (SELECT id FROM communities WHERE slug LIKE 'nppa-%')"
      ; "DELETE FROM communities WHERE slug LIKE 'nppa-%'"
      ; "DELETE FROM users WHERE username LIKE 'nppa_%'"
      ]

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let q_insert_user =
    (Caqti_type.string ->! Caqti_type.int)
      "INSERT INTO users (username, email, password_hash, is_email_verified)
       VALUES ($1, $1 || '@test.invalid', 'x', TRUE) RETURNING id"

  let q_insert_community =
    (Caqti_type.(t4 string string bool string) ->! Caqti_type.int)
      "INSERT INTO communities (slug, name, sections_enabled, visibility)
       VALUES ($1, $2, $3, $4) RETURNING id"

  let q_insert_section =
    (Caqti_type.(t3 int string string) ->! Caqti_type.int)
      "INSERT INTO community_sections (community_id, name, slug)
       VALUES ($1, $2, $3) RETURNING id"

  let q_add_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  let q_add_moderator =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_moderators (user_id, community_id, role) VALUES ($1, $2, 'mod')"

  (* Distinctive markers that must NEVER appear in a denied or filtered
     response: the private community's display name is deliberately distinct
     from its slug so both leak channels are asserted independently. *)
  let priv_slug = "nppa-priv"
  let priv_name = "NPPA Private Secret"

  type fx = {
    outsider : int;
    member : int;        (* member of nppa-priv and nppa-struct *)
    pmember : int;       (* member of nppa-pub only *)
    smember : int;       (* member of nppa-struct ONLY — no private rows *)
    moderator : int;     (* moderator row ONLY on nppa-priv, no membership *)
    admin : int;         (* no rows at all; session is_admin=true *)
    pub : int;
    struct_ : int;
    priv : int;
    sec_a : int;
    sec_b : int;
    priv_sec : int;
  }

  let make_fixtures (module C : Caqti_lwt.CONNECTION) =
    let user name =
      let* id = C.find q_insert_user name in
      or_fail name id
    in
    let* outsider = user "nppa_outsider" in
    let* member = user "nppa_member" in
    let* pmember = user "nppa_pmember" in
    let* smember = user "nppa_smember" in
    let* moderator = user "nppa_moderator" in
    let* admin = user "nppa_admin" in
    (* Insertion order pins the chooser's pass-through ordering below. *)
    let* pub = C.find q_insert_community ("nppa-pub", "NPPA Public Flat", false, "public") in
    let* pub = or_fail "pub" pub in
    let* struct_ = C.find q_insert_community ("nppa-struct", "NPPA Public Structured", true, "public") in
    let* struct_ = or_fail "struct" struct_ in
    let* priv = C.find q_insert_community (priv_slug, priv_name, true, "private") in
    let* priv = or_fail "priv" priv in
    let* sec_a = C.find q_insert_section (struct_, "NPPA Section A", "nppa-sec-a") in
    let* sec_a = or_fail "sec a" sec_a in
    let* sec_b = C.find q_insert_section (struct_, "NPPA Section B", "nppa-sec-b") in
    let* sec_b = or_fail "sec b" sec_b in
    let* priv_sec = C.find q_insert_section (priv, "NPPA Hidden Section", "nppa-hidden-sec") in
    let* priv_sec = or_fail "priv sec" priv_sec in
    let* r = C.exec q_add_member (pmember, pub) in
    let* () = or_fail "pmember row" r in
    let* r = C.exec q_add_member (member, struct_) in
    let* () = or_fail "member struct row" r in
    let* r = C.exec q_add_member (member, priv) in
    let* () = or_fail "member priv row" r in
    let* r = C.exec q_add_member (smember, struct_) in
    let* () = or_fail "smember struct row" r in
    let* r = C.exec q_add_moderator (moderator, priv) in
    let* () = or_fail "moderator row" r in
    Lwt.return
      { outsider; member; pmember; smember; moderator; admin;
        pub; struct_; priv; sec_a; sec_b; priv_sec }

  let router = Dream.router [ Dream.get "/new-post" Earde.Handlers.new_post_page ]

  (* One GET against the real pipeline: sql_pool + memory_sessions + router,
     with the session fields written under the same session the handler
     reads. *)
  let run ~url ?(session = []) target =
    let pipeline =
      Dream.sql_pool url @@ Dream.memory_sessions @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      router req
    in
    let request = Dream.request ~method_:`GET ~target "" in
    let* response = pipeline request in
    let* body = Dream.body response in
    Lwt.return
      ( Dream.status_to_int (Dream.status response),
        Dream.header response "Location",
        body )

  let session_of ?(admin = false) uid name =
    [ ("user_id", string_of_int uid); ("username", name) ]
    @ if admin then [ ("is_admin", "true") ] else []

  let find_sub hay needle from =
    let nl = String.length needle and hl = String.length hay in
    let rec go i =
      if i + nl > hl then None
      else if String.sub hay i nl = needle then Some i
      else go (i + 1)
    in
    if nl = 0 then Some from else go from

  let has_sub hay needle = find_sub hay needle 0 <> None

  (* Blank the one volatile value in an authorized document: the dream.csrf
     hidden input's value (each of the three authorized states renders
     exactly one). Everything else must be byte-stable. *)
  let mask_csrf body =
    match find_sub body "dream.csrf" 0 with
    | None -> body
    | Some i ->
        (match find_sub body "value=\"" i with
         | None -> body
         | Some j ->
             let vstart = j + String.length "value=\"" in
             (match String.index_from_opt body vstart '"' with
              | None -> body
              | Some vend ->
                  String.sub body 0 vstart
                  ^ "CSRF"
                  ^ String.sub body vend (String.length body - vend)))

  let is_redirect s = s = 301 || s = 302 || s = 303 || s = 307 || s = 308

  (* Every marker a denied response must not carry: the private identifiers
     themselves, and any launch-shell / creation-surface rendering (the
     denial is the shared legacy 404 — no rail, no sidebar, no create
     fragment, no launch scope class, no private analytics marker). *)
  let check_denied_clean label body =
    Alcotest.(check bool) (label ^ ": no private name") false
      (has_sub body priv_name);
    Alcotest.(check bool) (label ^ ": no private slug") false
      (has_sub body priv_slug);
    Alcotest.(check bool) (label ^ ": no create-shell") false
      (has_sub body "create-shell");
    Alcotest.(check bool) (label ^ ": no join gate") false
      (has_sub body "Members only");
    Alcotest.(check bool) (label ^ ": no launch rail") false
      (has_sub body "rail__item");
    Alcotest.(check bool) (label ^ ": no launch scope class") false
      (has_sub body "launch-post-creation");
    Alcotest.(check bool) (label ^ ": no private analytics marker") false
      (has_sub body "data-analytics-private-community")

  let creation_form_marker =
    "<form action='/posts' method='POST' enctype='multipart/form-data' class='create-form'>"

  let join_form_marker = "<form action='/join' method='POST' class='create-form'>"

  let community_id_hidden id =
    Printf.sprintf "<input type='hidden' name='community_id' value='%d'>" id

  let chooser_row slug =
    Printf.sprintf "<a href='/new-post?community=%s' class='create-comm'>" slug

  (* 1: anonymous requests keep the existing login redirect, and render no
     creation surface, rail data or notification wiring at all. *)
  let anonymous_case =
    db_case "anonymous /new-post keeps the login redirect, renders nothing"
      (fun ~url c ->
        let* _fx = make_fixtures c in
        let* s1, l1, b1 = run ~url "/new-post" in
        Alcotest.(check bool) "chooser redirects" true (is_redirect s1);
        Alcotest.(check (option string)) "chooser location" (Some "/login") l1;
        let* s2, l2, b2 = run ~url ("/new-post?community=" ^ priv_slug) in
        Alcotest.(check bool) "private target redirects" true (is_redirect s2);
        Alcotest.(check (option string)) "private target location" (Some "/login") l2;
        List.iter
          (fun b ->
            check_denied_clean "anonymous" b;
            Alcotest.(check bool) "no notification fetch" false
              (has_sub b "unread-notifs"))
          [ b1; b2 ];
        Lwt.return_unit)

  (* 2: public community, authenticated non-member — the Members-only join
     gate survives, with the community named and the real join round-trip. *)
  let public_join_gate_case =
    db_case "public community non-member still gets the named join gate"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let outsider = session_of fx.outsider "nppa_outsider" in
        let* status, _, body = run ~url ~session:outsider "/new-post?community=nppa-pub" in
        Alcotest.(check int) "status" 200 status;
        Alcotest.(check bool) "gate copy" true (has_sub body "Members only");
        Alcotest.(check bool) "community named" true
          (has_sub body "<span class='create-gate-name'>/c/nppa-pub</span>");
        Alcotest.(check bool) "join form" true (has_sub body join_form_marker);
        Alcotest.(check bool) "join target id" true
          (has_sub body (community_id_hidden fx.pub));
        Alcotest.(check bool) "join redirect destination" true
          (has_sub body
             "<input type='hidden' name='redirect_to' value='/new-post?community=nppa-pub'>");
        Alcotest.(check bool) "create-shell marker" true (has_sub body "create-shell");
        Lwt.return_unit)

  (* 3: public flat member — the real creation form, and no section field on
     a flat community. *)
  let public_member_form_case =
    db_case "public flat member gets the creation form without a section field"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let pmember = session_of fx.pmember "nppa_pmember" in
        let* status, _, body = run ~url ~session:pmember "/new-post?community=nppa-pub" in
        Alcotest.(check int) "status" 200 status;
        Alcotest.(check bool) "creation form" true (has_sub body creation_form_marker);
        Alcotest.(check bool) "community bound" true
          (has_sub body (community_id_hidden fx.pub));
        Alcotest.(check bool) "no section field on flat" false
          (has_sub body "name='section_id'");
        List.iter
          (fun marker ->
            Alcotest.(check bool) ("field: " ^ marker) true (has_sub body marker))
          [ "<input type='text' name='title' required class='create-input'"
          ; "<input type='url' name='url' class='create-input'"
          ; "<input type='file' name='image' accept='image/*' class='create-file'"
          ; "<textarea name='content' class='create-textarea'" ];
        Lwt.return_unit)

  (* 4+5+6: authorized private viewers. The MEMBER gets the creation form;
     the moderator-without-membership and the non-member admin are authorized
     past the privacy gate and receive the (named) join gate — the form
     itself has always required an ordinary membership row. All three see
     the private community in the chooser. *)
  let private_authorized_case =
    db_case "private community: member form; moderator and admin authorized; all three choosers list it"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let member = session_of fx.member "nppa_member" in
        let moderator = session_of fx.moderator "nppa_moderator" in
        let admin = session_of ~admin:true fx.admin "nppa_admin" in
        let target = "/new-post?community=" ^ priv_slug in
        let* status, _, body = run ~url ~session:member target in
        Alcotest.(check int) "member status" 200 status;
        Alcotest.(check bool) "member creation form" true
          (has_sub body creation_form_marker);
        Alcotest.(check bool) "member form bound to private id" true
          (has_sub body (community_id_hidden fx.priv));
        Alcotest.(check bool) "member sees private section option" true
          (has_sub body (Printf.sprintf "<option value='%d'" fx.priv_sec));
        let* status, _, body = run ~url ~session:moderator target in
        Alcotest.(check int) "moderator status (never 404)" 200 status;
        Alcotest.(check bool) "moderator sees the named gate" true
          (has_sub body ("<span class='create-gate-name'>/c/" ^ priv_slug ^ "</span>"));
        let* status, _, body = run ~url ~session:admin target in
        Alcotest.(check int) "admin status (never 404)" 200 status;
        Alcotest.(check bool) "admin sees the named gate" true
          (has_sub body ("<span class='create-gate-name'>/c/" ^ priv_slug ^ "</span>"));
        let* () =
          Lwt_list.iter_s
            (fun (label, session) ->
              let* status, _, chooser = run ~url ~session "/new-post" in
              Alcotest.(check int) (label ^ " chooser status") 200 status;
              Alcotest.(check bool) (label ^ " chooser lists private name") true
                (has_sub chooser priv_name);
              Alcotest.(check bool) (label ^ " chooser links private slug") true
                (has_sub chooser (chooser_row priv_slug));
              Lwt.return_unit)
            [ ("member", member); ("moderator", moderator); ("admin", admin) ]
        in
        Lwt.return_unit)

  (* 7+9+10: the outsider's direct request — the canonical anti-enumeration
     404. An existing private slug, a missing slug and an empty slug are one
     indistinguishable response, byte for byte, with no private identifier
     and no creation/launch rendering. *)
  let outsider_direct_case =
    db_case "outsider direct: private, missing and empty slugs are one indistinguishable 404"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let outsider = session_of fx.outsider "nppa_outsider" in
        let get t = run ~url ~session:outsider t in
        let* s1, _, denied = get ("/new-post?community=" ^ priv_slug) in
        let* s2, _, missing = get "/new-post?community=nppa-missing" in
        let* s3, _, empty = get "/new-post?community=" in
        Alcotest.(check (list int)) "all 404" [ 404; 404; 404 ] [ s1; s2; s3 ];
        Alcotest.(check bool) "denied == missing byte-identical" true
          (String.equal denied missing);
        Alcotest.(check bool) "denied == empty byte-identical" true
          (String.equal denied empty);
        Alcotest.(check bool) "generic copy" true
          (has_sub denied "This community does not exist.");
        check_denied_clean "outsider direct" denied;
        ignore fx.priv;
        Lwt.return_unit)

  (* 8+13: the outsider's chooser — publics listed in pass-through order with
     the /bring fallback, the private community entirely absent: no name, no
     slug, no destination URL. *)
  let outsider_chooser_case =
    db_case "outsider chooser: publics in order with /bring fallback, private fully absent"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let outsider = session_of fx.outsider "nppa_outsider" in
        let* status, _, body = run ~url ~session:outsider "/new-post" in
        Alcotest.(check int) "status" 200 status;
        Alcotest.(check bool) "public flat listed" true
          (has_sub body "NPPA Public Flat");
        Alcotest.(check bool) "public structured listed" true
          (has_sub body "NPPA Public Structured");
        Alcotest.(check bool) "public rows link the composer" true
          (has_sub body (chooser_row "nppa-pub"));
        Alcotest.(check bool) "unjoined public still offered" true
          (has_sub body (chooser_row "nppa-struct"));
        (* get_all_communities has no ORDER BY: the chooser passes rows
           through, so freshly-inserted fixtures keep insertion order. *)
        (match
           ( find_sub body (chooser_row "nppa-pub") 0,
             find_sub body (chooser_row "nppa-struct") 0 )
         with
        | Some i, Some j ->
            Alcotest.(check bool) "insertion order preserved" true (i < j)
        | _ -> Alcotest.fail "expected both public chooser rows");
        Alcotest.(check bool) "no private name" false (has_sub body priv_name);
        Alcotest.(check bool) "no private slug anywhere" false
          (has_sub body priv_slug);
        Alcotest.(check bool) "no private destination URL" false
          (has_sub body (chooser_row priv_slug));
        Alcotest.(check bool) "bring fallback" true
          (has_sub body "href='/bring' class='create-link'>Connect a project</a>");
        Alcotest.(check bool) "post-here affordance" true (has_sub body "Post here");
        ignore fx.outsider;
        Lwt.return_unit)

  (* 13 (empty world): with no viewable community at all, the chooser renders
     no nppa row and keeps the /bring fallback. Scoped to this suite's
     fixtures so parallel suites' data cannot flake it. *)
  let empty_chooser_case =
    db_case "chooser with no eligible nppa community keeps the /bring fallback"
      (fun ~url c ->
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* viewer = C.find q_insert_user "nppa_lonely" in
        let* viewer = or_fail "viewer" viewer in
        let* priv = C.find q_insert_community (priv_slug, priv_name, false, "private") in
        let* _ = or_fail "priv" priv in
        let* status, _, body =
          run ~url ~session:(session_of viewer "nppa_lonely") "/new-post"
        in
        Alcotest.(check int) "status" 200 status;
        Alcotest.(check bool) "no nppa row" false (has_sub body "nppa-");
        Alcotest.(check bool) "no private name" false (has_sub body priv_name);
        Alcotest.(check bool) "bring fallback" true
          (has_sub body "href='/bring' class='create-link'>Connect a project</a>");
        Lwt.return_unit)

  (* 11+12: authorized section preselection — the real slug preselects its
     option; a bogus slug and a PRIVATE community's section slug preselect
     nothing and reveal nothing. *)
  let section_preselect_case =
    db_case "section preselection: own slug selects; bogus and foreign-private slugs select and reveal nothing"
      (fun ~url c ->
        let* fx = make_fixtures c in
        (* smember belongs to the structured community ONLY — so its joined
           rail carries no private tile, and any private name/slug in this
           document would be a real leak, not the viewer's own membership. *)
        let member = session_of fx.smember "nppa_smember" in
        let* status, _, body =
          run ~url ~session:member "/new-post?community=nppa-struct&section=nppa-sec-b"
        in
        Alcotest.(check int) "preselect status" 200 status;
        Alcotest.(check bool) "structured section field" true
          (has_sub body "<select name='section_id' required class='create-select'>");
        Alcotest.(check bool) "section B preselected" true
          (has_sub body (Printf.sprintf "<option value='%d' selected>" fx.sec_b));
        Alcotest.(check bool) "section A not preselected" true
          (has_sub body (Printf.sprintf "<option value='%d'>" fx.sec_a));
        let expect_no_preselect label target =
          let* status, _, body = run ~url ~session:member target in
          Alcotest.(check int) (label ^ " status") 200 status;
          Alcotest.(check bool) (label ^ " renders the form") true
            (has_sub body creation_form_marker);
          Alcotest.(check bool) (label ^ " preselects nothing") false
            (has_sub body "' selected>");
          Lwt.return body
        in
        let* _ =
          expect_no_preselect "bogus slug"
            "/new-post?community=nppa-struct&section=nppa-nope"
        in
        let* body =
          expect_no_preselect "private community's section slug"
            "/new-post?community=nppa-struct&section=nppa-hidden-sec"
        in
        Alcotest.(check bool) "no private name leaked" false
          (has_sub body priv_name);
        Alcotest.(check bool) "no private slug leaked" false
          (has_sub body priv_slug);
        Alcotest.(check bool) "no private section option" false
          (has_sub body (Printf.sprintf "<option value='%d'" fx.priv_sec));
        Lwt.return_unit)

  (* 15: the three authorized create-shell states are byte-stable across
     independent requests once the single CSRF value is masked — the pinned
     form contract cannot drift request-to-request. *)
  let form_stability_case =
    db_case "authorized flat form, structured form and join gate are byte-stable after CSRF masking"
      (fun ~url c ->
        let* fx = make_fixtures c in
        let stable label session target expected_markers =
          let* s1, _, one = run ~url ~session target in
          let* s2, _, two = run ~url ~session target in
          Alcotest.(check (list int)) (label ^ " statuses") [ 200; 200 ] [ s1; s2 ];
          Alcotest.(check bool) (label ^ " byte-stable") true
            (String.equal (mask_csrf one) (mask_csrf two));
          List.iter
            (fun m ->
              Alcotest.(check bool) (label ^ " pins: " ^ m) true (has_sub one m))
            expected_markers;
          Lwt.return_unit
        in
        let* () =
          stable "flat form"
            (session_of fx.pmember "nppa_pmember")
            "/new-post?community=nppa-pub"
            [ creation_form_marker; community_id_hidden fx.pub;
              "<div class='create-shell'>" ]
        in
        let* () =
          stable "structured form"
            (session_of fx.member "nppa_member")
            "/new-post?community=nppa-struct"
            [ creation_form_marker; community_id_hidden fx.struct_;
              "<select name='section_id' required class='create-select'>";
              "<div class='create-shell'>" ]
        in
        let* () =
          stable "join gate"
            (session_of fx.outsider "nppa_outsider")
            "/new-post?community=nppa-pub"
            [ join_form_marker; community_id_hidden fx.pub;
              "<div class='create-shell'>" ]
        in
        Lwt.return_unit)

  let suite =
    [ anonymous_case; public_join_gate_case; public_member_form_case;
      private_authorized_case; outsider_direct_case; outsider_chooser_case;
      empty_chooser_case; section_preselect_case; form_stability_case ]
end

(* === Reset-token attribute escaping (pass 16B security fix) ===

   Pages.reset_password_page re-emits the attacker-controlled reset token in a
   single-quoted hidden attribute: [<input type='hidden' name='token'
   value='...'>]. Before the fix the raw token was interpolated verbatim, so a
   token containing a quote escaped the attribute on the POST handler's
   mismatch / too-short re-render — a reflected-XSS path. These tests pin the
   escaped contract structurally: exactly one token input whose bounded value
   contains no markup-significant byte, escaping that HTML-decodes back to the
   original token losslessly, the rest of the form byte-pinned, and the same
   guarantees through the real reset_password_handler's two re-render arms
   (which never touch the database, so this suite runs ungated). *)
module Reset_token_escaping = struct
  let ( let* ) = Lwt.bind
  let case name f = Alcotest.test_case name `Quick f

  (* Renders the real page through real session middleware (the page embeds a
     CSRF tag) — same harness as render_search. *)
  let render_reset ?error token =
    let rendered = ref "" in
    let (_ : Dream.response) =
      Lwt_main.run
        (Dream.memory_sessions
           (fun req ->
             rendered := Earde.Pages.reset_password_page ~token ?error req;
             Dream.html "")
           (Dream.request ~method_:`GET ~target:"/reset-password" ""))
    in
    !rendered

  let form_body fields =
    String.concat "&"
      (List.map
         (fun (k, v) ->
           Dream.to_percent_encoded k ^ "=" ^ Dream.to_percent_encoded v)
         fields)

  (* Drives the REAL Handlers.reset_password_handler: a valid same-session
     dream.csrf is minted inside the pipeline and injected into the urlencoded
     body, exactly like the analytics POST runner. The mismatch and too-short
     arms re-render before any Dream.sql call, so no pool is mounted — if a
     future change makes these arms touch the database, this harness fails
     loudly rather than silently passing. *)
  let run_reset_post ~token ~password ~confirm =
    let status = ref 0 and body_html = ref "" in
    Lwt_main.run
      (let pipeline =
         Dream.memory_sessions (fun req ->
             let csrf = Dream.csrf_token req in
             Dream.set_body req
               (form_body
                  [ ("dream.csrf", csrf); ("token", token);
                    ("password", password); ("confirm_password", confirm) ]);
             Earde.Handlers.reset_password_handler req)
       in
       let request =
         Dream.request ~method_:`POST ~target:"/reset-password"
           ~headers:
             [ ("Content-Type", "application/x-www-form-urlencoded") ]
           ""
       in
       let* response = pipeline request in
       status := Dream.status_to_int (Dream.status response);
       let* body = Dream.body response in
       body_html := body;
       Lwt.return_unit);
    (!status, !body_html)

  (* Reference escaping (Components.html_escape's closed entity set) and its
     inverse, so tests can prove the round-trip is lossless rather than only
     spot-checking one entity. *)
  let escape = Earde.Components.html_escape

  let unescape s =
    let entities =
      [ ("&amp;", "&"); ("&lt;", "<"); ("&gt;", ">"); ("&quot;", "\"");
        ("&#39;", "'") ]
    in
    let buf = Buffer.create (String.length s) in
    let sl = String.length s in
    let rec go i =
      if i >= sl then Buffer.contents buf
      else
        match
          List.find_opt
            (fun (e, _) ->
              let el = String.length e in
              i + el <= sl && String.sub s i el = e)
            entities
        with
        | Some (e, raw) ->
            Buffer.add_string buf raw;
            go (i + String.length e)
        | None ->
            Buffer.add_char buf s.[i];
            go (i + 1)
    in
    go 0

  let token_input_prefix = "<input type='hidden' name='token' value='"

  (* The complete pinned tag for an escaped token value. *)
  let token_input_of escaped = token_input_prefix ^ escaped ^ "'>"

  (* Exactly one token input in the region, returned as raw tag text. *)
  let token_tag region =
    match
      List.filter (fun t -> contains t "name='token'") (ps_input_tags region)
    with
    | [ t ] -> t
    | l ->
        Alcotest.fail
          (Printf.sprintf "expected exactly one token input, found %d"
             (List.length l))

  (* Structural inertness: the tag is the pinned prefix, then a bounded value
     that is the tag's LAST attribute, and the value byte-region holds no
     markup-significant character — so no smuggled attribute, no event
     handler, no autofocus, no element breakout is representable. Mirrors the
     ps_is_csrf_input technique. Returns the raw (still-escaped) value. *)
  let audit_token_tag tag =
    let pl = String.length token_input_prefix and tl = String.length tag in
    Alcotest.(check bool)
      "token tag starts with the pinned prefix" true
      (tl >= pl + 2 && String.sub tag 0 pl = token_input_prefix);
    Alcotest.(check bool)
      "token tag closes immediately after the value" true
      (String.sub tag (tl - 2) 2 = "'>");
    let value = String.sub tag pl (tl - pl - 2) in
    String.iter
      (fun c ->
        if c = '\'' || c = '"' || c = '<' || c = '>' then
          Alcotest.fail
            (Printf.sprintf "markup-significant byte %C inside token value" c))
      value;
    value

  (* Full audit of the reset form region for a given raw token: pinned token
     tag, lossless round-trip, one framework CSRF field, an exact input
     census (csrf + token + two pinned password fields — nothing else), the
     pinned action/method and controls, and no element injection anywhere in
     the form. *)
  let audit_reset_form page ~token =
    let region = ps_form_region page in
    let escaped = escape token in
    Alcotest.(check int) "exactly one name='token' field" 1
      (ps_count region "name='token'");
    ps_must region (token_input_of escaped);
    let value = audit_token_tag (token_tag region) in
    Alcotest.(check string) "escaped value decodes back to the raw token"
      token (unescape value);
    (match List.filter ps_is_csrf_input (ps_input_tags region) with
    | [ _ ] -> ()
    | l ->
        Alcotest.fail
          (Printf.sprintf "expected exactly one CSRF input, found %d"
             (List.length l)));
    Alcotest.(check int) "input census: csrf + token + 2 passwords" 4
      (List.length (ps_input_tags region));
    ps_must page "<form action='/reset-password' method='POST' class='auth-form'>";
    ps_must region
      "<input class='auth-input' type='password' id='rp-password' name='password' required minlength='8'>";
    ps_must region
      "<input class='auth-input' type='password' id='rp-confirm' name='confirm_password' required minlength='8'>";
    Alcotest.(check int) "both password fields keep minlength" 2
      (ps_count region "minlength='8'");
    ps_must region "<button type='submit' class='auth-btn'>Reset password</button>";
    ps_must_not region "<script";
    ps_must_not region "<img";
    ps_must_not region "onerror"

  (* Attribute-breakout payload: quote out of the value, then an autofocus +
     event-handler pair that would fire on load if the quote survived. *)
  let breakout_payload = "x'autofocus onfocus='alert(1)"
  let script_payload = "'><script>alert(1)</script>"

  let single_quote_case =
    case "single-quote + event-handler payload stays inside the attribute"
      (fun () ->
        let page = render_reset breakout_payload in
        audit_reset_form page ~token:breakout_payload;
        (* The raw breakout shape must not exist anywhere in the document. *)
        ps_must_not page "value='x'autofocus";
        ps_must_not page "onfocus='alert";
        ps_must page "value='x&#39;autofocus onfocus=&#39;alert(1)'>")

  let double_quote_case =
    case "double-quote payload is entity-escaped" (fun () ->
        let token = "x\"y onmouseover=\"alert(1)" in
        let page = render_reset token in
        audit_reset_form page ~token;
        ps_must_not page "\"y onmouseover=\"";
        ps_must page "value='x&quot;y onmouseover=&quot;alert(1)'>")

  let script_tag_case =
    case "script-tag payload never becomes an element" (fun () ->
        let page = render_reset script_payload in
        audit_reset_form page ~token:script_payload;
        ps_must_not page "<script>alert";
        ps_must_not page "</script>";
        ps_must page "value='&#39;&gt;&lt;script&gt;alert(1)&lt;/script&gt;'>")

  let amp_angle_case =
    case "ampersand and angle brackets round-trip as entities" (fun () ->
        let token = "a&b<c>d&amp;e" in
        let page = render_reset token in
        (* Double-escaping guard: the literal "&amp;e" in the token must
           render as "&amp;amp;e", and decode back to exactly one "&amp;e". *)
        audit_reset_form page ~token;
        ps_must page "value='a&amp;b&lt;c&gt;d&amp;amp;e'>")

  let ordinary_token_case =
    case "ordinary token is preserved byte-exact with the full form contract"
      (fun () ->
        let token = "AbC123_-xyz0" in
        let page = render_reset token in
        audit_reset_form page ~token;
        (* No escapable byte: the attribute must carry the token verbatim. *)
        ps_must page (token_input_of token);
        Alcotest.(check string) "value is the raw token" token
          (audit_token_tag (token_tag (ps_form_region page))))

  let error_notice_of msg =
    "<div class='auth-alert auth-alert--error'>" ^ msg ^ "</div>"

  (* The two real handler re-render arms. Both must keep the converted shell,
     the renderer-owned notice, and the escaped token. *)
  let handler_rerender_audit ~password ~confirm ~notice () =
    let status, page =
      run_reset_post ~token:script_payload ~password ~confirm
    in
    Alcotest.(check int) "re-render status" 200 status;
    ps_must page "<body class='launch-auth launch-reset-password'>";
    ps_must page (error_notice_of notice);
    audit_reset_form page ~token:script_payload;
    ps_must_not page "<script>alert";
    (* Submitted passwords are never echoed back. *)
    ps_must_not page password

  let mismatch_rerender_case =
    case "real handler: mismatch re-render escapes the crafted token"
      (handler_rerender_audit ~password:"password-one-1"
         ~confirm:"password-two-2" ~notice:"Passwords do not match.")

  let too_short_rerender_case =
    case "real handler: too-short re-render escapes the crafted token"
      (handler_rerender_audit ~password:"short" ~confirm:"short"
         ~notice:"Password must be at least 8 characters.")

  let wrapper_case =
    case "wrapper: launch auth shell, noindex, only local launch assets"
      (fun () ->
        let page = render_reset "wrap-check-token" in
        ps_must page "<body class='launch-auth launch-reset-password'>";
        ps_must page "<title>Reset Password - Earde</title>";
        ps_must page "<meta name='robots' content='noindex'>";
        ps_must page "<link rel='stylesheet' href='/static/css/earde.css'>";
        Alcotest.(check int) "exactly one stylesheet" 1
          (ps_count page "<link rel='stylesheet'");
        ps_must_not page "auth.css";
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "unread-notifs";
        ps_must_not page "notif-badge";
        (* No script may live inside the form region regardless of the
           document-level analytics configuration other suites may leave. *)
        ps_must_not (ps_form_region page) "<script")

  (* /login and /signup share the wrapper this pass reused; pin their form
     contracts so a regression in the shared helper or an accidental edit to
     the sibling renderers cannot slip through this suite. *)
  let render_login () =
    let rendered = ref "" in
    let (_ : Dream.response) =
      Lwt_main.run
        (Dream.memory_sessions
           (fun req ->
             rendered := Earde.Pages.login_form req;
             Dream.html "")
           (Dream.request ~method_:`GET ~target:"/login" ""))
    in
    !rendered

  let render_signup () =
    let rendered = ref "" in
    let (_ : Dream.response) =
      Lwt_main.run
        (Dream.memory_sessions
           (fun req ->
             rendered := Earde.Pages.signup_form req;
             Dream.html "")
           (Dream.request ~method_:`GET ~target:"/signup" ""))
    in
    !rendered

  let login_signup_case =
    case "login and signup form contracts are unchanged" (fun () ->
        let login = render_login () in
        ps_must login "<body class='launch-auth launch-login'>";
        ps_must login "<title>Log in - Earde</title>";
        ps_must login "<form action='/login' method='POST' class='auth__card'>";
        ps_must login
          "<input class='input input--inset' type='text' id='li-identifier' name='identifier' required>";
        ps_must login
          "<input class='input input--inset' type='password' id='li-password' name='password' required>";
        ps_must login "href='/forgot-password'";
        Alcotest.(check int) "login input census" 3
          (List.length (ps_input_tags (ps_form_region login)));
        ps_must_not login "auth.css";
        ps_must_not login "tailwind";
        ps_must_not login "fonts.googleapis";
        let signup = render_signup () in
        ps_must signup "<body class='launch-auth launch-signup'>";
        ps_must signup "<title>Create an account - Earde</title>";
        ps_must signup "<form action='/signup' method='POST' class='auth__card'>";
        ps_must signup "name='username' required>";
        ps_must signup "name='email' required>";
        ps_must signup "name='password' required>";
        ps_must signup "id='website' name='website' tabindex='-1' autocomplete='off'>";
        ps_must signup "id='privacy' name='privacy' type='checkbox' required>";
        Alcotest.(check int) "signup input census" 6
          (List.length (ps_input_tags (ps_form_region signup)));
        ps_must_not signup "auth.css";
        ps_must_not signup "tailwind";
        ps_must_not signup "fonts.googleapis")

  let suite =
    [ single_quote_case; double_quote_case; script_tag_case; amp_angle_case;
      ordinary_token_case; mismatch_rerender_case; too_short_rerender_case;
      wrapper_case; login_signup_case ]
end

(* Cartographic Civic pass 16C: /privacy through the launch entry wrapper.
   The legal document is authoritative: its complete inner fragment is pinned
   byte-for-byte below, so any wording, structure, heading, list or link
   drift in the policy fails loudly. The wrapper contract is asserted against
   the real renderer through real session middleware: single local
   stylesheet, no Tailwind CDN, no Google Fonts, no auth.css, no
   notification chrome, no forms, and a viewer-independent document (the
   ignored ?user must not change a byte). *)
module Privacy_launch = struct
  let case name f = Alcotest.test_case name `Quick f

  let render_privacy ?user () =
    let rendered = ref "" in
    let (_ : Dream.response) =
      Lwt_main.run
        (Dream.memory_sessions
           (fun req ->
             rendered := Earde.Pages.privacy_page ?user req;
             Dream.html "")
           (Dream.request ~method_:`GET ~target:"/privacy" ""))
    in
    !rendered

  (* Byte-for-byte copy of the legal fragment the renderer embeds. *)
  let legal_fragment = {|
    <div class='max-w-2xl mx-auto mt-10 mb-16 px-4'>

      <h1 class='text-3xl font-extrabold text-gray-900 mb-2'>Privacy Policy</h1>
      <p class='text-sm text-gray-400 mb-10'>This page explains, in plain terms, what data Earde handles and why.</p>

      <div class='space-y-8 text-gray-700 leading-relaxed'>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>What Earde is</h2>
          <p>Earde is a community platform for technical communities. It combines live chat with durable discussion threads and a searchable archive.</p>
        </section>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>Data we may collect or store</h2>
          <p class='mb-3'>To operate the service, Earde may store:</p>
          <ul class='list-disc list-inside space-y-2 text-sm'>
            <li>Account information, such as your username and email address.</li>
            <li>Profile information you choose to add.</li>
            <li>Community content, posts, and comments you create.</li>
            <li>Chat messages you send.</li>
            <li>Session and authentication data needed to keep you signed in.</li>
            <li>Moderation records related to reports and enforcement actions.</li>
            <li>Operational and security logs.</li>
          </ul>
        </section>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>How we use data</h2>
          <ul class='list-disc list-inside space-y-2 text-sm'>
            <li>To operate and provide the service.</li>
            <li>To authenticate users and keep accounts secure.</li>
            <li>To display community content.</li>
            <li>To moderate abuse and enforce community rules.</li>
            <li>To maintain the security of the service.</li>
            <li>To debug problems and improve reliability.</li>
          </ul>
        </section>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>Cookies and sessions</h2>
          <p>Earde may use cookies or similar browser storage for login and session functionality and for basic operation of the site.</p>
        </section>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>Analytics and tracking</h2>
          <p>If analytics or tracking tools are added in the future, they should be disclosed here and configured deliberately.</p>
        </section>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>Your controls</h2>
          <p class='mb-3'>You can contact the operator of this site with any questions about your account or your data.</p>
          <p>From your <a href='/settings' class='text-[#C94C4C] underline hover:text-[#A83A3A]'>account settings</a> you can update your profile or delete your account, and you can <a href='/export-data' class='text-[#C94C4C] underline hover:text-[#A83A3A]'>export your data</a>.</p>
        </section>

        <section>
          <h2 class='text-lg font-bold text-gray-900 mb-3 pb-1 border-b border-[#E0D9CC]'>Changes to this page</h2>
          <p>This page may be updated as Earde changes.</p>
        </section>

      </div>
    </div>|}

  let wrapper_case =
    case "wrapper: launch entry shell, only local launch assets" (fun () ->
        let page = render_privacy () in
        ps_must page "<body class='launch-privacy'>";
        ps_must page "<title>Privacy Policy - Earde</title>";
        ps_must page "<link rel='stylesheet' href='/static/css/earde.css'>";
        Alcotest.(check int) "exactly one stylesheet" 1
          (ps_count page "<link rel='stylesheet'");
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "auth.css";
        ps_must_not page "mobile-gate.css";
        ps_must_not page "unread-notifs";
        ps_must_not page "notif-badge";
        ps_must_not page "noindex";
        ps_must_not page "href='#'";
        (* Entry chrome is form-free and the document carries none. *)
        ps_must_not page "<form")

  let legal_identity_case =
    case "legal fragment is embedded byte-for-byte" (fun () ->
        let page = render_privacy () in
        ps_must page legal_fragment;
        Alcotest.(check int) "one h1" 1 (ps_count page "<h1");
        Alcotest.(check int) "seven h2" 7 (ps_count page "<h2");
        Alcotest.(check int) "two lists" 2 (ps_count page "<ul");
        Alcotest.(check int) "thirteen items" 13 (ps_count page "<li>");
        Alcotest.(check int) "settings link" 1 (ps_count page "href='/settings'");
        Alcotest.(check int) "export link" 1 (ps_count page "href='/export-data'"))

  let viewer_independence_case =
    case "ignored ?user changes nothing" (fun () ->
        Alcotest.(check string) "anonymous = authenticated"
          (render_privacy ()) (render_privacy ~user:"qa-viewer" ()))

  (* The signup consent link is the page's primary inbound route: pin its
     exact destination and security attributes. *)
  let signup_consent_link_case =
    case "signup consent link still targets /privacy" (fun () ->
        let rendered = ref "" in
        let (_ : Dream.response) =
          Lwt_main.run
            (Dream.memory_sessions
               (fun req ->
                 rendered := Earde.Pages.signup_form req;
                 Dream.html "")
               (Dream.request ~method_:`GET ~target:"/signup" ""))
        in
        ps_must !rendered
          "<a href='/privacy' target='_blank'>Privacy Policy</a>")

  let suite =
    [ wrapper_case; legal_identity_case; viewer_independence_case;
      signup_consent_link_case ]
end

(* Cartographic Civic pass 17: the shared Pages.msg_page through the new
   launch message wrapper. ~400 handler call sites across every status
   family render through this one document, several under byte-identity
   anti-enumeration pins, so the suite pins the wrapper contract (single
   local stylesheet, no legacy assets, no forms, no notification wiring,
   viewer- and ~auth-independence) and the renderer contract (title and
   message always escaped — markup supplied in either stays inert text —
   the alert_type glyph mapping, and the verbatim return_url Go back
   link). Handlers stay authoritative for status and headers; the gated
   suites keep pinning those and the byte-identity pairs. *)
module Msg_launch = struct
  let case name f = Alcotest.test_case name `Quick f

  let render ?user ?auth ?(title = "Not Found")
      ?(message = "This page does not exist.") ?(alert_type = "error")
      ?(return_url = "/") () =
    let rendered = ref "" in
    let (_ : Dream.response) =
      Lwt_main.run
        (Dream.memory_sessions
           (fun req ->
             rendered :=
               Earde.Pages.msg_page ?user ?auth ~title ~message ~alert_type
                 ~return_url req;
             Dream.html "")
           (Dream.request ~method_:`GET ~target:"/qa-msg" ""))
    in
    !rendered

  let wrapper_case =
    case "wrapper: neutral launch message document, only local assets"
      (fun () ->
        let page = render () in
        ps_must page "<body class='launch-message-page'>";
        ps_must page "<title>Not Found - Earde</title>";
        ps_must page "<link rel='stylesheet' href='/static/css/earde.css'>";
        Alcotest.(check int) "exactly one stylesheet" 1
          (ps_count page "<link rel='stylesheet'");
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "auth.css";
        ps_must_not page "shell.css";
        ps_must_not page "mobile-gate.css";
        ps_must_not page "unread-notifs";
        ps_must_not page "notif-badge";
        ps_must_not page "copyPostLink";
        ps_must_not page "confirmModal";
        ps_must_not page "noindex";
        ps_must_not page "href='#'";
        (* No chrome that could vary by resource or viewer. *)
        ps_must_not page "rail__item";
        ps_must_not page "topbar";
        (* The document introduces no forms and (analytics unconfigured in
           tests) no ids at all — trivially no duplicates. *)
        ps_must_not page "<form";
        Alcotest.(check int) "no ids" 0 (ps_count page " id='"))

  (* Both historical ~auth branches collapse into the same document family —
     byte-identical, since they already were under the legacy wrapper. *)
  let auth_branch_parity_case =
    case "~auth:true and ~auth:false render byte-identically" (fun () ->
        let a = render ~auth:true () and b = render ~auth:false () in
        ps_must a "<body class='launch-message-page'>";
        Alcotest.(check string) "auth branches identical" a b)

  let viewer_independence_case =
    case "ignored ?user changes nothing" (fun () ->
        Alcotest.(check string) "anonymous = authenticated" (render ())
          (render ~user:"qa-viewer" ()))

  (* The always-escaped-text contract: no caller-supplied markup in title or
     message may reach the document unescaped (msg_page has never accepted
     trusted HTML). *)
  let escaping_case =
    case "title and message stay escaped text" (fun () ->
        let page =
          render ~title:"Alert <\"quoted\"> & 'ticked'"
            ~message:"See <a href='/x'>link</a> & <script>alert(1)</script>" ()
        in
        ps_must page
          "<h1 class='auth__title'>Alert &lt;&quot;quoted&quot;&gt; &amp; \
           &#39;ticked&#39;</h1>";
        ps_must page
          "<title>Alert &lt;&quot;quoted&quot;&gt; &amp; &#39;ticked&#39; - \
           Earde</title>";
        ps_must page
          "See &lt;a href=&#39;/x&#39;&gt;link&lt;/a&gt; &amp; \
           &lt;script&gt;alert(1)&lt;/script&gt;";
        ps_must_not page "<a href='/x'>";
        ps_must_not page "<script>alert")

  (* The renderer's own return-to-context link: verbatim caller URL, one
     link, unchanged label. *)
  let go_back_case =
    case "return_url renders as the single Go back link" (fun () ->
        let page = render ~return_url:"/c/qa-somewhere/settings" () in
        ps_must page
          "<a href='/c/qa-somewhere/settings' class='launch-msg__back'>Go \
           back</a>";
        Alcotest.(check int) "exactly one Go back" 1 (ps_count page "Go back"))

  (* alert_type keeps its historical mapping: success / info / everything
     else (including unknown values) is the error glyph. *)
  let alert_type_case =
    case "alert_type maps onto the three glyph variants" (fun () ->
        List.iter
          (fun (alert_type, variant) ->
            let page = render ~alert_type () in
            ps_must page ("launch-msg__icon launch-msg__icon--" ^ variant);
            Alcotest.(check int) (alert_type ^ ": one glyph") 1
              (ps_count page "launch-msg__icon "))
          [ ("success", "success"); ("info", "info"); ("error", "error");
            ("banana", "error") ])

  (* The wrapper must not introduce the substrings the project-home 409
     neutrality tests forbid, nor any resource-derived copy. *)
  let neutral_copy_case =
    case "wrapper adds no forbidden or resource-derived copy" (fun () ->
        let page =
          String.lowercase_ascii
            (render ~title:"Not Allowed"
               ~message:"This request is not allowed." ())
        in
        ps_must_not page "private";
        ps_must_not page "draft";
        ps_must_not page "legacy")

  let suite =
    [ wrapper_case; auth_branch_parity_case; viewer_independence_case;
      escaping_case; go_back_case; alert_type_case; neutral_copy_case ]
end

(* === Final create-page callers (pass 19) ==================================
   The last two live Components.create_page documents move onto launch
   wrappers, with everything else preserved:
   1. GET /new-community (Pages.new_community_form) → launch_app_page under
      body.launch-new-community. Renderer pins (DB-free, real session
      middleware for the CSRF tag): wrapper identity, local assets only
      (earde.css + mobile-gate.css, no Tailwind / Google Fonts / shell.css /
      create.css), the byte-preserved POST /communities form contract, one
      behavior script and one notification fetch, and a launch rail fed only
      by handler-supplied joined communities. Handler pins (DB-free — the
      denial paths never reach SQL): the pre-existing global-admin gate.
      Gated: a real global admin receives the form with their real joined
      rail; a real top moderator without the admin session flag keeps the
      /bring redirect; the POST authorization / validation / duplicate /
      CSRF / success contracts are unchanged (handler untouched).
   2. The moderator review queue's degraded document
      (Project_home_review_pages, shell:None — the durable community record
      could not be re-read for chrome) → launch_message_page: the neutral
      body class, no chrome, no scripts, no notification wiring, viewer
      independence, and the identical feature fragment (the pending-request
      list bytes match the launch community document for the same state). *)
module Final_create_page = struct
  let case name f = Alcotest.test_case name `Quick f
  let ( let* ) = Lwt.bind

  (* --- /new-community renderer --- *)

  let render_form ?user ?(rail_communities = []) () =
    let rendered = ref None in
    let pipeline =
      Dream.set_secret gck_secret @@ Dream.memory_sessions
      @@ fun req ->
      rendered :=
        Some (Earde.Pages.new_community_form ?user ~rail_communities req);
      Dream.html ""
    in
    ignore
      (Lwt_main.run
         (pipeline (Dream.request ~method_:`GET ~target:"/new-community" "")));
    match !rendered with
    | Some html -> html
    | None -> Alcotest.fail "renderer did not run"

  let form_marker =
    "<form action='/communities' method='POST' class='create-form' \
     id='new-community-form'>"

  let wrapper_case =
    case
      "authorized document: launch wrapper, local assets only, one script, \
       one notification fetch, real rail"
      (fun () ->
        let page =
          render_form ~user:"ncl_admin"
            ~rail_communities:[ nav_test_community ] ()
        in
        ps_must page "<body class='launch-new-community'>";
        ps_must page "<title>New Community - Earde</title>";
        ps_must page "<link rel='stylesheet' href='/static/css/earde.css'>";
        ps_must page
          "<link rel='stylesheet' href='/static/css/mobile-gate.css'>";
        Alcotest.(check int) "exactly two stylesheets" 2
          (ps_count page "<link rel='stylesheet'");
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "shell.css";
        ps_must_not page "create.css";
        Alcotest.(check int) "exactly one notification fetch" 1
          (ps_count page "/api/unread-notifs");
        Alcotest.(check int) "exactly one behavior script" 1
          (ps_count page "function confirmModal");
        (* The dark rail: Feed (the only active marker), the real joined
           community, and the + Connect tile — nothing invented, no
           current-page tile for this utility. *)
        Alcotest.(check int) "one active rail marker" 1
          (ps_count page "rail__marker");
        ps_must page "href='/c/ocaml/ch/general'";
        ps_must page "rail__item--add' href='/bring'";
        (* Factual administrative context precedes the create-shell marker;
           the page never sells itself as the onboarding flow. *)
        ps_order page "launch-newcomm-context" "<div class='create-shell'>";
        ps_must page "Administrator utility";
        ps_must_not page "/projects/new")

  let form_contract_case =
    case "the POST /communities form contract is byte-intact" (fun () ->
        let page = render_form ~user:"ncl_admin" () in
        ps_must page form_marker;
        Alcotest.(check int) "one creation form" 1
          (ps_count page "action='/communities'");
        Alcotest.(check int) "one framework CSRF field" 1
          (ps_count page "dream.csrf");
        ps_must page
          "<input type='hidden' name='section_count' id='section_count' \
           value='0'>";
        ps_must page
          "<input type='hidden' name='channel_count' id='channel_count' \
           value='0'>";
        ps_must page
          "<input type='text' name='name' required class='create-input' \
           placeholder='e.g., Italian Cuisine'>";
        ps_must page
          "<input type='text' name='slug' required class='create-input' \
           placeholder='italian-cuisine'>";
        ps_must page
          "<textarea name='description' class='create-textarea' \
           placeholder='What is this community about?'></textarea>";
        ps_must page "<div class='create-shell'>";
        ps_must page "Start a community";
        ps_must page "<span class='create-chip-name'>general</span>";
        ps_must page "<span class='create-chip-name'>General</span>";
        ps_must page
          "<button type='submit' class='create-btn create-btn--block'>Create \
           community</button>";
        ps_must_not page "enctype";
        Alcotest.(check int) "single form id" 1
          (ps_count page "id='new-community-form'");
        (* The row-management scripts the server-side count loop depends on. *)
        ps_must page "function addChannel()";
        ps_must page "function addSection()";
        ps_must page "function renumberChannels()";
        ps_must page "function renumberSections()")

  let viewerless_render_case =
    case "viewer-less render carries no script or notification wiring"
      (fun () ->
        let page = render_form () in
        ps_must page "<body class='launch-new-community'>";
        ps_must_not page "/api/unread-notifs";
        ps_must_not page "confirmModal")

  let renderer_suite =
    [ wrapper_case; form_contract_case; viewerless_render_case ]

  (* --- /new-community handler: DB-free denial paths (the /bring and
     /login redirects run before any SQL — no pool is installed, so a
     regression that queried before the gate would raise, not pass). --- *)

  let handler_router =
    Dream.router
      [ Dream.get "/new-community" Earde.Handlers.new_community_page ]

  let run_get ?(session = []) target =
    let pipeline =
      Dream.set_secret gck_secret @@ Dream.memory_sessions
      @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      handler_router req
    in
    Lwt_main.run
      (let* response = pipeline (Dream.request ~method_:`GET ~target "") in
       let* body = Dream.body response in
       Lwt.return
         ( Dream.status_to_int (Dream.status response),
           Dream.header response "Location",
           body ))

  let is_redirect s = s = 301 || s = 302 || s = 303 || s = 307 || s = 308

  let check_denied_clean label body =
    List.iter
      (fun marker ->
        Alcotest.(check bool) (label ^ ": no " ^ marker) false
          (contains body marker))
      [ form_marker; "create-shell"; "launch-new-community"; "unread-notifs";
        "rail__item"; "Start a community"; "dream.csrf" ]

  let anonymous_gate_case =
    case "anonymous GET keeps the /bring redirect and renders nothing"
      (fun () ->
        let status, location, body = run_get "/new-community" in
        Alcotest.(check bool) "redirects" true (is_redirect status);
        Alcotest.(check (option string)) "location" (Some "/bring") location;
        check_denied_clean "anonymous" body)

  (* Community moderators carry no is_admin session field, so this case is
     also the moderator gate; the gated case below re-proves it against a
     real top_mod row. *)
  let ordinary_user_gate_case =
    case "ordinary authenticated GET keeps the /bring redirect" (fun () ->
        let status, location, body =
          run_get
            ~session:[ ("user_id", "424242"); ("username", "ncl_user") ]
            "/new-community"
        in
        Alcotest.(check bool) "redirects" true (is_redirect status);
        Alcotest.(check (option string)) "location" (Some "/bring") location;
        check_denied_clean "ordinary user" body)

  let stale_admin_gate_case =
    case "admin flag without a user id keeps the /login redirect" (fun () ->
        let status, location, body =
          run_get ~session:[ ("is_admin", "true") ] "/new-community"
        in
        Alcotest.(check bool) "redirects" true (is_redirect status);
        Alcotest.(check (option string)) "location" (Some "/login") location;
        check_denied_clean "stale admin" body)

  let gate_suite =
    [ anonymous_gate_case; ordinary_user_gate_case; stale_admin_gate_case ]

  (* --- Gated: real rows, real pool, real handlers --- *)

  open Caqti_request.Infix

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM channels WHERE community_id IN \
         (SELECT id FROM communities WHERE slug LIKE 'ncl-%')"
      ; "DELETE FROM community_sections WHERE community_id IN \
         (SELECT id FROM communities WHERE slug LIKE 'ncl-%')"
      ; "DELETE FROM community_moderators WHERE community_id IN \
         (SELECT id FROM communities WHERE slug LIKE 'ncl-%')"
      ; "DELETE FROM community_members WHERE community_id IN \
         (SELECT id FROM communities WHERE slug LIKE 'ncl-%')"
      ; "DELETE FROM communities WHERE slug LIKE 'ncl-%'"
      ; "DELETE FROM users WHERE username LIKE 'ncl_%'"
      ]

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let q_insert_user =
    (Caqti_type.string ->! Caqti_type.int)
      "INSERT INTO users (username, email, password_hash, is_email_verified)
       VALUES ($1, $1 || '@test.invalid', 'x', TRUE) RETURNING id"

  let q_insert_community =
    (Caqti_type.(t4 string string bool string) ->! Caqti_type.int)
      "INSERT INTO communities (slug, name, sections_enabled, visibility)
       VALUES ($1, $2, $3, $4) RETURNING id"

  let q_add_member =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_members (user_id, community_id) VALUES ($1, $2)"

  let q_add_top_mod =
    (Caqti_type.(t2 int int) ->. Caqti_type.unit)
      "INSERT INTO community_moderators (user_id, community_id, role) \
       VALUES ($1, $2, 'top_mod')"

  let q_community_id =
    (Caqti_type.string ->? Caqti_type.int)
      "SELECT id FROM communities WHERE slug = $1"

  let q_count_sections =
    (Caqti_type.int ->! Caqti_type.int)
      "SELECT COUNT(*)::int FROM community_sections WHERE community_id = $1"

  let q_count_channels =
    (Caqti_type.int ->! Caqti_type.int)
      "SELECT COUNT(*)::int FROM channels WHERE community_id = $1"

  let q_has_top_mod =
    (Caqti_type.(t2 int int) ->! Caqti_type.bool)
      "SELECT EXISTS(SELECT 1 FROM community_moderators \
       WHERE user_id = $1 AND community_id = $2 AND role = 'top_mod')"

  let q_has_member =
    (Caqti_type.(t2 int int) ->! Caqti_type.bool)
      "SELECT EXISTS(SELECT 1 FROM community_members \
       WHERE user_id = $1 AND community_id = $2)"

  let run_get_db ~url ?(session = []) target =
    let pipeline =
      Dream.sql_pool url @@ Dream.set_secret gck_secret
      @@ Dream.memory_sessions
      @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      handler_router req
    in
    let* response = pipeline (Dream.request ~method_:`GET ~target "") in
    let* body = Dream.body response in
    Lwt.return
      ( Dream.status_to_int (Dream.status response),
        Dream.header response "Location",
        body )

  let form_body fields =
    String.concat "&"
      (List.map
         (fun (k, v) ->
           Dream.to_percent_encoded k ^ "=" ^ Dream.to_percent_encoded v)
         fields)

  (* POST /communities through the real handler; the CSRF token is minted
     inside the same request/session, exactly like the analytics harness. *)
  let run_post ~url ?(session = []) ?(with_csrf = true) form =
    let pipeline =
      Dream.sql_pool url @@ Dream.set_secret gck_secret
      @@ Dream.memory_sessions
      @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      let fields =
        if with_csrf then ("dream.csrf", Dream.csrf_token req) :: form
        else form
      in
      Dream.set_body req (form_body fields);
      Earde.Handlers.create_community_handler req
    in
    let request =
      Dream.request ~method_:`POST ~target:"/communities"
        ~headers:
          [ ("Content-Type", "application/x-www-form-urlencoded") ]
        ""
    in
    let* response = pipeline request in
    let* body = Dream.body response in
    Lwt.return
      ( Dream.status_to_int (Dream.status response),
        Dream.header response "Location",
        body )

  let admin_session uid name =
    [ ("user_id", string_of_int uid); ("username", name);
      ("is_admin", "true") ]

  let plain_session uid name =
    [ ("user_id", string_of_int uid); ("username", name) ]

  let admin_get_case =
    db_case "global admin gets the real form with the real joined rail"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = C.find q_insert_user "ncl_admin" in
        let* uid = or_fail "admin" uid in
        let* cid = C.find q_insert_community ("ncl-joined", "NCL Joined", true, "public") in
        let* cid = or_fail "community" cid in
        let* r = C.exec q_add_member (uid, cid) in
        let* () = or_fail "membership" r in
        let* status, _, body =
          run_get_db ~url ~session:(admin_session uid "ncl_admin")
            "/new-community"
        in
        Alcotest.(check int) "status" 200 status;
        Alcotest.(check bool) "launch wrapper" true
          (contains body "<body class='launch-new-community'>");
        Alcotest.(check bool) "real form" true (contains body form_marker);
        Alcotest.(check bool) "joined rail tile" true
          (contains body "href='/c/ncl-joined/ch/general'");
        Alcotest.(check int) "one notification fetch" 1
          (ps_count body "/api/unread-notifs");
        Alcotest.(check bool) "no shell.css" false (contains body "shell.css");
        Alcotest.(check bool) "no create.css" false (contains body "create.css");
        Alcotest.(check bool) "no tailwind" false (contains body "tailwind");
        Lwt.return_unit)

  let top_mod_get_case =
    db_case "real top moderator without the admin flag keeps the /bring \
             redirect"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = C.find q_insert_user "ncl_topmod" in
        let* uid = or_fail "top mod" uid in
        let* cid = C.find q_insert_community ("ncl-modded", "NCL Modded", true, "public") in
        let* cid = or_fail "community" cid in
        let* r = C.exec q_add_top_mod (uid, cid) in
        let* () = or_fail "top mod row" r in
        let* r = C.exec q_add_member (uid, cid) in
        let* () = or_fail "membership" r in
        let* status, location, body =
          run_get_db ~url ~session:(plain_session uid "ncl_topmod")
            "/new-community"
        in
        Alcotest.(check bool) "redirects" true (is_redirect status);
        Alcotest.(check (option string)) "location" (Some "/bring") location;
        check_denied_clean "top moderator" body;
        Lwt.return_unit)

  let post_forbidden_case =
    db_case "non-admin POST is rejected outright with no rows created"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = C.find q_insert_user "ncl_pleb" in
        let* uid = or_fail "user" uid in
        let* status, _, body =
          run_post ~url ~session:(plain_session uid "ncl_pleb")
            [ ("name", "NCL Forged"); ("slug", "ncl-forged");
              ("section_count", "0") ]
        in
        Alcotest.(check int) "403" 403 status;
        Alcotest.(check bool) "denial copy" true
          (contains body
             "Forbidden: community creation is restricted to Earde \
              administrators.");
        let* row = C.find_opt q_community_id "ncl-forged" in
        let* row = or_fail "lookup" row in
        Alcotest.(check bool) "no community row" true (row = None);
        Lwt.return_unit)

  let post_validation_case =
    db_case "missing name keeps the Validation Error message page" (fun ~url
        (module C : Caqti_lwt.CONNECTION) ->
        let* uid = C.find q_insert_user "ncl_admin2" in
        let* uid = or_fail "admin" uid in
        let* _status, _, body =
          run_post ~url ~session:(admin_session uid "ncl_admin2")
            [ ("name", ""); ("slug", "ncl-noname"); ("section_count", "0") ]
        in
        Alcotest.(check bool) "validation copy" true
          (contains body "Community name and URL slug are required.");
        Alcotest.(check bool) "shared message wrapper" true
          (contains body "launch-message-page");
        let* row = C.find_opt q_community_id "ncl-noname" in
        let* row = or_fail "lookup" row in
        Alcotest.(check bool) "no community row" true (row = None);
        Lwt.return_unit)

  let post_missing_csrf_case =
    db_case "admin POST without the framework token keeps the Form Error \
             answer"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = C.find q_insert_user "ncl_admin3" in
        let* uid = or_fail "admin" uid in
        let* status, _, body =
          run_post ~url ~with_csrf:false
            ~session:(admin_session uid "ncl_admin3")
            [ ("name", "NCL Stale"); ("slug", "ncl-stale");
              ("section_count", "0") ]
        in
        Alcotest.(check int) "400" 400 status;
        Alcotest.(check bool) "form error copy" true
          (contains body "Your form submission was invalid.");
        let* row = C.find_opt q_community_id "ncl-stale" in
        let* row = or_fail "lookup" row in
        Alcotest.(check bool) "no community row" true (row = None);
        Lwt.return_unit)

  let post_success_case =
    db_case "successful creation keeps its database state, redirect and \
             duplicate-slug answer"
      (fun ~url (module C : Caqti_lwt.CONNECTION) ->
        let* uid = C.find q_insert_user "ncl_admin4" in
        let* uid = or_fail "admin" uid in
        let session = admin_session uid "ncl_admin4" in
        let* status, location, _ =
          run_post ~url ~session
            [ ("name", "NCL Created"); ("slug", "ncl-created");
              ("description", "A pass-19 fixture");
              ("section_count", "1"); ("section_name_1", "Docs");
              ("section_sort_1", "top");
              ("channel_count", "1"); ("channel_name_1", "lab") ]
        in
        Alcotest.(check bool) "redirects" true (is_redirect status);
        Alcotest.(check (option string)) "canonical destination"
          (Some "/c/ncl-created") location;
        let* cid = C.find_opt q_community_id "ncl-created" in
        let* cid = or_fail "created" cid in
        let cid =
          match cid with
          | Some id -> id
          | None -> Alcotest.fail "community row missing"
        in
        let* sections = C.find q_count_sections cid in
        let* sections = or_fail "sections" sections in
        Alcotest.(check int) "General + Docs" 2 sections;
        let* channels = C.find q_count_channels cid in
        let* channels = or_fail "channels" channels in
        Alcotest.(check int) "general + lab" 2 channels;
        let* top_mod = C.find q_has_top_mod (uid, cid) in
        let* top_mod = or_fail "top mod" top_mod in
        Alcotest.(check bool) "creator is top_mod" true top_mod;
        let* joined = C.find q_has_member (uid, cid) in
        let* joined = or_fail "member" joined in
        Alcotest.(check bool) "creator joined" true joined;
        (* The pre-existing duplicate-slug answer is unchanged. *)
        let* dup_status, _, dup_body =
          run_post ~url ~session
            [ ("name", "NCL Created Again"); ("slug", "ncl-created");
              ("section_count", "0") ]
        in
        Alcotest.(check int) "duplicate 500" 500 dup_status;
        Alcotest.(check bool) "duplicate copy" true
          (contains dup_body
             "Could not create community. The URL slug may already be \
              taken.");
        Lwt.return_unit)

  let db_suite =
    [ admin_get_case; top_mod_get_case; post_forbidden_case;
      post_validation_case; post_missing_csrf_case; post_success_case ]

  (* --- The review queue's degraded document --- *)

  let degraded_render ?user ?(state = phrp_state ()) () =
    Phrp.project_home_review_page ?user ~state ~feedback:None ()

  let launch_shell : Phrp.launch_shell =
    { Phrp.community_record = nav_test_community;
      rail_communities = [ nav_test_community ];
      sidebar = "<div class='ncl-sidebar-mark'></div>" }

  let launch_render ?user ?(state = phrp_state ()) () =
    Phrp.project_home_review_page ?user ~shell:launch_shell ~state
      ~feedback:None ()

  let degraded_wrapper_case =
    case
      "degraded document: neutral message wrapper, no chrome, no scripts, \
       no notification wiring"
      (fun () ->
        let page = degraded_render () in
        ps_must page "<body class='launch-message-page'>";
        ps_must page "<title>Project home requests - Earde</title>";
        ps_must page "<meta name='robots' content='noindex'>";
        ps_must page "<link rel='stylesheet' href='/static/css/earde.css'>";
        Alcotest.(check int) "exactly one stylesheet" 1
          (ps_count page "<link rel='stylesheet'");
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "shell.css";
        ps_must_not page "create.css";
        ps_must_not page "unread-notifs";
        ps_must_not page "confirmModal";
        ps_must_not page "copyPostLink";
        ps_must_not page "rail__item";
        ps_must_not page "topbar";
        (* The real fragment survives inside the create-shell marker. *)
        let frag = ps_fragment page in
        ps_must frag "Project home requests";
        ps_must frag "Review projects requesting this community";
        ps_must frag "Widget Kit")

  let degraded_viewer_independence_case =
    case "degraded document ignores ?user (no viewer-derived chrome)"
      (fun () ->
        Alcotest.(check string) "anonymous = named viewer"
          (degraded_render ())
          (degraded_render ~user:"ncl_reviewer" ()))

  (* The pending-request list — every phrv-* element and form — is byte
     identical between the degraded and the launch community documents for
     the same state. *)
  let degraded_fragment_parity_case =
    case "request-list bytes match the launch community document" (fun () ->
        let slice html =
          let start = "<ul class='phrv-request-list'>" in
          match ps_index_of html start 0 with
          | None -> Alcotest.fail "request list missing"
          | Some s -> (
              match ps_index_of html "</ul>" s with
              | None -> Alcotest.fail "unterminated request list"
              | Some e -> String.sub html s (e - s))
        in
        Alcotest.(check string) "identical request list"
          (slice (launch_render ()))
          (slice (degraded_render ())))

  let launch_branch_unchanged_case =
    case "normal branch still renders the launch community document"
      (fun () ->
        let page = launch_render ~user:"ncl_reviewer" () in
        ps_must page "<body class='launch-project-home-review'>";
        ps_must page "launch-review-context";
        ps_must page "<div class='ncl-sidebar-mark'></div>";
        ps_must page "<div class='create-shell'>";
        ps_must_not page "launch-message-page")

  let degraded_suite =
    [ degraded_wrapper_case; degraded_viewer_independence_case;
      degraded_fragment_parity_case; launch_branch_unchanged_case ]
end

(* === Global admin dashboard on the launch shell (pass 18A) =================
   DB-free renderer pins for Pages.admin_dashboard_page: wrapper identity
   (body.launch-global-admin, local assets only, noindex), the preserved
   unban form contract (route, method, CSRF, confirm hook), escaping of the
   rendered usernames/emails, the replay-masking tables, and the
   single-notification-fetch contract. Authorization itself (200 admin / 403
   everyone else, no queries on denial) is pinned end-to-end by the gated
   login_session_replacement suite. *)
module Admin_launch = struct
  let case name f = Alcotest.test_case name `Quick f
  let ( let* ) = Lwt.bind

  let mk_recent ?(id = 1) ?(username = "alice") ?(email = "alice@example.com")
      ?(created_at = "2026-01-01 00:00:00") ?(is_admin = false)
      ?(is_banned = false) ?(post_count = 0) ?(comment_count = 0)
      ?(message_count = 0) () : Earde.Db.admin_recent_user =
    { id; username; email; created_at; is_admin; is_banned; post_count;
      comment_count; message_count }

  let mk_pending ?(id = 1) ?(username = "penny")
      ?(email = "penny@example.com") ?(created_at = "2026-01-01 00:00:00")
      ?(expires_at = "2026-01-02 00:00:00") ?ip_address () :
      Earde.Db.pending_signup_row =
    { id; username; email; created_at; expires_at; ip_address }

  let mk_banned ~id ~username ~email : Earde.Db.user = { id; username; email }

  (* Renders the real page through real session middleware (the unban forms
     embed a CSRF tag); the session carries the admin identity the topbar
     user menu reads. The handler's own gate is not re-tested here. *)
  let render ?(recent_users = []) ?(pending = []) ?(banned_users = [])
      ?(signups_enabled = true) ?(turnstile = `Configured)
      ?(brevo_configured = true) () =
    let rendered = ref "" in
    let (_ : Dream.response) =
      Lwt_main.run
        (Dream.memory_sessions
           (fun req ->
             let* () = Dream.set_session_field req "user_id" "1" in
             let* () = Dream.set_session_field req "username" "qa-admin" in
             let* () = Dream.set_session_field req "is_admin" "true" in
             rendered :=
               Earde.Pages.admin_dashboard_page ~user:"qa-admin"
                 ~signups_enabled ~turnstile ~brevo_configured ~recent_users
                 ~pending ~banned_users req;
             Dream.html "")
           (Dream.request ~method_:`GET ~target:"/admin" ""))
    in
    !rendered

  let wrapper_case =
    case "wrapper: launch document, local assets only, noindex" (fun () ->
        let page = render () in
        ps_must page "<body class='launch-global-admin'>";
        ps_must page "<title>Admin Dashboard - Earde</title>";
        ps_must page "<meta name='robots' content='noindex'>";
        Alcotest.(check int) "exactly one earde.css" 1
          (ps_count page "href='/static/css/earde.css'");
        Alcotest.(check int) "exactly one mobile-gate.css" 1
          (ps_count page "mobile-gate.css");
        Alcotest.(check int) "exactly two stylesheets" 2
          (ps_count page "<link rel='stylesheet'");
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "admin.css";
        ps_must_not page "shell.css";
        ps_must_not page "href='#'";
        (* Serif head; KPI monitoring moved to PostHog — no dashboard link. *)
        ps_must page "<h1 class='page__title'>Administration</h1>";
        ps_must_not page "earde-hq-dashboard";
        (* Exactly one one-shot notification fetch, one badge, one shared
           behavior script (one confirmModal definition). *)
        Alcotest.(check int) "one notification fetch" 1
          (ps_count page "fetch('/api/unread-notifs')");
        Alcotest.(check int) "one notif badge" 1
          (ps_count page "id='notif-badge'");
        Alcotest.(check int) "one confirmModal definition" 1
          (ps_count page "function confirmModal");
        (* Admin session: the user menu links back to /admin exactly once. *)
        Alcotest.(check int) "one /admin menu link" 1
          (ps_count page "href='/admin'"))

  let empty_states_case =
    case "empty dashboard keeps the three real empty states" (fun () ->
        let page = render () in
        ps_must page "No users yet.";
        ps_must page "No active pending signups.";
        ps_must page "No users are currently globally banned.";
        (* All three data tables stay replay-masked. *)
        Alcotest.(check int) "three masked tables" 3
          (ps_count page "<table class='admin-table ph-no-capture'>"))

  (* The one action form on the dashboard: POST /admin/unban/user/:id with a
     framework CSRF field and the existing confirm hook — byte contract. *)
  let unban_form_case =
    case "unban forms keep route, method, CSRF and confirm hook" (fun () ->
        let page =
          render
            ~banned_users:
              [ mk_banned ~id:41 ~username:"marge" ~email:"marge@example.com"
              ; mk_banned ~id:42 ~username:"o'brien"
                  ~email:"obrien@example.com"
              ] ()
        in
        ps_must page
          "<form class='admin-act-form' action='/admin/unban/user/41' method='POST' onsubmit=\"confirmModal(event, 'Lift global ban on u/marge?')\">";
        ps_must page
          "<form class='admin-act-form' action='/admin/unban/user/42' method='POST' onsubmit=\"confirmModal(event, 'Lift global ban on u/o&#39;brien?')\">";
        Alcotest.(check int) "exactly two unban forms" 2
          (ps_count page "action='/admin/unban/user/");
        Alcotest.(check int) "one Unban button per form" 2
          (ps_count page
             "<button type='submit' class='admin-btn-unban'>Unban</button>");
        (* CSRF census: the unban forms are the only token-carrying forms on
           the page (search is GET; the menu logout form has never carried
           one). *)
        Alcotest.(check int) "exactly two CSRF fields" 2
          (List.length
             (List.filter ps_is_csrf_input (ps_input_tags page))))

  (* Usernames and emails reach three different tables; all render through
     html_escape in both text and attribute contexts. *)
  let escaping_case =
    case "hostile usernames and emails stay escaped everywhere" (fun () ->
        let u = "ban<script>me" and e = "evil&<x>\"@qa" in
        let page =
          render
            ~recent_users:[ mk_recent ~id:9 ~username:u ~email:e () ]
            ~pending:[ mk_pending ~id:5 ~username:u ~email:e () ]
            ~banned_users:[ mk_banned ~id:7 ~username:u ~email:e ] ()
        in
        ps_must_not page "ban<script>me";
        ps_must_not page "evil&<x>";
        ps_must page "ban&lt;script&gt;me";
        ps_must page "evil&amp;&lt;x&gt;&quot;@qa";
        (* Profile links build from the escaped username too. *)
        ps_must page "href='/u/ban&lt;script&gt;me'";
        (* The recent-users table shows no email column — the address must
           appear exactly twice (pending + banned). *)
        Alcotest.(check int) "email in pending and banned only" 2
          (ps_count page "evil&amp;&lt;x&gt;&quot;@qa"))

  (* Real config/status values render; no invented metrics appear. *)
  let status_ledger_case =
    case "status ledger maps real config states onto the chips" (fun () ->
        let page =
          render ~signups_enabled:false ~turnstile:`Misconfigured
            ~brevo_configured:false ()
        in
        ps_must page "admin-stat-val--off'>closed";
        ps_must page "admin-stat-val--bad'>misconfigured";
        ps_must page "admin-stat-val--warn'>not configured";
        let page2 = render () in
        ps_must page2 "admin-stat-val--ok'>enabled";
        ps_must page2 "admin-stat-val--ok'>required &amp; configured";
        ps_must page2 "admin-stat-val--ok'>configured")

  let suite =
    [ wrapper_case; empty_states_case; unban_form_case; escaping_case;
      status_ledger_case ]
end

(* === safe_local_redirect grammar (global-admin hardening) ===
   The helper reduces attacker-controlled redirect targets (the Referer
   header, form-carried return paths) to a local path+query. Browsers send
   Referer as an absolute URL, so a same-origin absolute http(s) URL must be
   accepted and reduced; everything else must collapse to the caller's
   trusted local default. Pure, DB-free. *)
module Slr = struct
  let case name f = Alcotest.test_case name `Quick f

  let request ?(host = Some "earde.com") () =
    Dream.request
      ~headers:(match host with Some h -> [ ("Host", h) ] | None -> [])
      ""

  let check ?default ?host label target expected =
    Alcotest.(check string) label expected
      (Earde.Handlers.safe_local_redirect ?default (request ?host ()) target)

  let local_paths_case =
    case "local relative paths pass; query kept; fragment dropped" (fun () ->
        check "plain path" "/admin" "/admin";
        check "root" "/" "/";
        check "query preserved" "/u/gab_target?tab=posts" "/u/gab_target?tab=posts";
        check "fragment dropped" "/admin#banned" "/admin";
        check "query kept, fragment dropped" "/u/bob?tab=posts#top" "/u/bob?tab=posts")

  let same_origin_case =
    case "absolute same-origin URLs reduce to path+query" (fun () ->
        check "https referer" "https://earde.com/admin" "/admin";
        check "http referer" "http://earde.com/admin" "/admin";
        check "query preserved" "https://earde.com/u/gab_target?tab=posts"
          "/u/gab_target?tab=posts";
        check "fragment dropped" "https://earde.com/admin#sec" "/admin";
        check "explicit https port" "https://earde.com:443/admin" "/admin";
        check "explicit http port" "http://earde.com:80/admin" "/admin";
        check "empty path becomes root" "https://earde.com" "/";
        check "case-insensitive host and scheme" "HTTPS://EARDE.COM/admin" "/admin";
        check ~host:(Some "localhost:8080") "host with port"
          "http://localhost:8080/admin?tab=x" "/admin?tab=x")

  let foreign_case =
    case "foreign origins collapse to the default" (fun () ->
        check "foreign host" "https://evil.example/admin" "/";
        check "foreign subdomain" "https://evil.earde.com/admin" "/";
        check ~default:"/admin" "foreign host, caller default"
          "https://evil.example/admin" "/admin";
        check ~host:(Some "localhost:8080") "mismatched port"
          "http://localhost:9090/admin" "/";
        check ~host:(Some "earde.com") "unexpected explicit port"
          "https://earde.com:8443/admin" "/";
        check ~host:None "no Host header to compare against"
          "https://earde.com/admin" "/")

  let hostile_case =
    case "protocol-relative, userinfo, malformed and encoded tricks fall back"
      (fun () ->
        check "protocol-relative" "//evil.example" "/";
        check "protocol-relative with path" "//evil.example/admin" "/";
        check "same-origin protocol-relative path"
          "https://earde.com//evil.example" "/";
        check "userinfo trick" "https://earde.com@evil.example/admin" "/";
        check "userinfo on own host" "https://user@earde.com/admin" "/";
        check "backslash path" "/admin\\evil.example" "/";
        check "absolute with backslash" "https://earde.com/a\\b" "/";
        check "header-splitting CR LF" "/admin\r\nSet-Cookie: x=y" "/";
        check "control byte" "/admin\x00" "/";
        check "non-http scheme" "javascript:alert(1)" "/";
        check "schemeless authority" "earde.com/admin" "/";
        check "half scheme" "https:/earde.com/admin" "/";
        check "empty" "" "/";
        check ~default:"/admin" "default honored on garbage" "not a url" "/admin")

  (* The output can never carry a scheme or authority, whatever comes in. *)
  let never_absolute_case =
    case "no input yields a scheme, authority, or fragment" (fun () ->
        List.iter
          (fun target ->
            let out =
              Earde.Handlers.safe_local_redirect (request ()) target
            in
            Alcotest.(check bool)
              (target ^ ": starts with single /") true
              (String.length out > 0 && out.[0] = '/'
              && not (String.length out >= 2 && out.[1] = '/'));
            Alcotest.(check bool) (target ^ ": no scheme") false
              (contains out "://");
            Alcotest.(check bool) (target ^ ": no fragment") false
              (String.contains out '#'))
          [ "/admin"; "https://earde.com/u/x?tab=posts#f"; "//evil.example";
            "https://evil.example/x"; "https://earde.com//evil.example";
            "ftp://earde.com/x"; "\\\\evil.example"; "https://earde.com#f";
            "https://earde.com"; "" ])

  let suite =
    [ local_paths_case; same_origin_case; foreign_case; hostile_case;
      never_absolute_case ]
end

(* === Global-admin ban/unban POST hardening ===
   Two pre-existing defects, both regressed here through the real routes over
   a real database: (1) the forms rendered Dream's CSRF tag but the handlers
   never parsed the body, so any cross-site POST from an admin's browser
   mutated ban state; (2) the post-action redirect fed the browser's absolute
   Referer into a helper that only accepted local paths, so every successful
   action bounced to "/" instead of the originating /admin or /u/:username
   surface. Database-gated (EARDE_TEST_DATABASE_URL). *)
module Gab = struct
  let ( let* ) = Lwt.bind

  open Caqti_request.Infix

  let status_of response = Dream.status_to_int (Dream.status response)

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM notifications WHERE user_id IN \
         (SELECT id FROM users WHERE username LIKE 'gab_%')"
      ; "DELETE FROM users WHERE username LIKE 'gab_%'"
      ]

  let q_insert_user =
    (Caqti_type.(t3 string bool bool) ->! Caqti_type.int)
      "INSERT INTO users \
         (username, email, password_hash, is_email_verified, is_admin, is_banned) \
       VALUES ($1, $1 || '@test.invalid', 'x', TRUE, $2, $3) RETURNING id"

  let q_set_banned =
    (Caqti_type.(t2 bool int) ->. Caqti_type.unit)
      "UPDATE users SET is_banned = $1 WHERE id = $2"

  let q_is_banned =
    (Caqti_type.int ->! Caqti_type.bool)
      "SELECT is_banned FROM users WHERE id = $1"

  let q_notif_count =
    (Caqti_type.int ->! Caqti_type.int)
      "SELECT COUNT(*) FROM notifications WHERE user_id = $1"

  let q_mod_action_notifs =
    (Caqti_type.int ->! Caqti_type.int)
      "SELECT COUNT(*) FROM notifications \
       WHERE user_id = $1 AND notif_type = 'mod_action'"

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let insert_user ?(admin = false) ?(banned = false) (module C : Caqti_lwt.CONNECTION)
      username =
    let* id = C.find q_insert_user (username, admin, banned) in
    or_fail username id

  let set_banned (module C : Caqti_lwt.CONNECTION) ~banned id =
    let* r = C.exec q_set_banned (banned, id) in
    or_fail "set_banned" r

  let is_banned (module C : Caqti_lwt.CONNECTION) id =
    let* r = C.find q_is_banned id in
    or_fail "is_banned" r

  let notif_count (module C : Caqti_lwt.CONNECTION) id =
    let* r = C.find q_notif_count id in
    or_fail "notif_count" r

  let mod_action_notifs (module C : Caqti_lwt.CONNECTION) id =
    let* r = C.find q_mod_action_notifs id in
    or_fail "mod_action_notifs" r

  (* One shared pipeline: real routes, real handlers, real session and CSRF
     machinery. The identity middleware plants the session the way login
     would, once per fresh cookie. *)
  let shared_identity : (int * string * bool) option ref = ref None
  let shared_pipeline = ref None

  let identity_middleware handler request =
    match Dream.session_field request "user_id" with
    | Some _ -> handler request
    | None -> (
        match !shared_identity with
        | None -> handler request
        | Some (uid, username, is_admin) ->
            let* () =
              Dream.set_session_field request "user_id" (string_of_int uid)
            in
            let* () = Dream.set_session_field request "username" username in
            let* () =
              if is_admin then Dream.set_session_field request "is_admin" "true"
              else Lwt.return_unit
            in
            handler request)

  let build_pipeline ~url =
    Dream.sql_pool ~size:2 url @@ Dream.set_secret gck_secret
    @@ Dream.memory_sessions @@ identity_middleware
    @@ Dream.router
         [ Dream.get "/mint" (fun req -> Dream.respond (Dream.csrf_token req));
           Dream.get "/mint-expired" (fun req ->
               Dream.respond (Dream.csrf_token ~valid_for:(-60.) req));
           Dream.get "/u/:username" Earde.Handlers.view_profile_handler;
           Dream.get "/admin" Earde.Handlers.admin_dashboard_handler;
           Dream.post "/admin/ban/user/:id" Earde.Handlers.ban_user_handler;
           Dream.post "/admin/unban/user/:id"
             Earde.Handlers.unban_user_global_handler
         ]

  let pipeline_for ~url =
    match !shared_pipeline with
    | Some pipeline -> pipeline
    | None ->
        let pipeline = build_pipeline ~url in
        shared_pipeline := Some pipeline;
        pipeline

  let as_user identity = shared_identity := Some identity
  let as_anonymous () = shared_identity := None

  (* Every request carries the Host header a real browser sends — the
     same-origin Referer reduction compares against it. *)
  let host = "earde.com"

  let do_get ?cookie ~url ~target () =
    let pipeline = pipeline_for ~url in
    let headers =
      ("Host", host)
      :: (match cookie with Some c -> [ ("Cookie", c) ] | None -> [])
    in
    let* response = pipeline (Dream.request ~method_:`GET ~target ~headers "") in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* [omit_token] posts an empty urlencoded body — exactly what a scripted
     cross-site POST without the token would carry. *)
  let do_post ?cookie ?referer ?(omit_token = false) ~url ~target ~token () =
    let pipeline = pipeline_for ~url in
    let headers =
      [ ("Host", host); ("Content-Type", "application/x-www-form-urlencoded") ]
      @ (match cookie with Some c -> [ ("Cookie", c) ] | None -> [])
      @ (match referer with Some r -> [ ("Referer", r) ] | None -> [])
    in
    let body =
      if omit_token then "" else Pch.form_body [ ("dream.csrf", token) ]
    in
    let* response =
      pipeline (Dream.request ~method_:`POST ~target ~headers body)
    in
    let* body = Dream.body response in
    Lwt.return (response, body)

  (* One cookie-less GET that opens a fresh session for this identity and
     returns its cookie plus a live same-session CSRF token. *)
  let open_session label ~url identity =
    as_user identity;
    let* response, token = do_get ~url ~target:"/mint" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return (Pch.session_cookie label response, token)

  let mint_expired label ~url ~cookie =
    let* response, body = do_get ~url ~cookie ~target:"/mint-expired" () in
    Alcotest.(check int) (label ^ ": mint 200") 200 (status_of response);
    Lwt.return body

  let ban_target id = Printf.sprintf "/admin/ban/user/%d" id
  let unban_target id = Printf.sprintf "/admin/unban/user/%d" id

  let check_redirect label expected response =
    Alcotest.(check int) (label ^ ": 303") 303 (status_of response);
    Alcotest.(check (option string)) (label ^ ": Location") (Some expected)
      (Dream.header response "Location")

  let check_form_error label response body =
    Alcotest.(check int) (label ^ ": 400") 400 (status_of response);
    Alcotest.(check bool) (label ^ ": form-error copy") true
      (contains body "Invalid form submission.");
    Alcotest.(check (option string)) (label ^ ": no redirect") None
      (Dream.header response "Location")

  (* --- 13. the rendered forms are the contract the browser submits --- *)
  let form_contract_case =
    db_case "profile ban form and /admin unban form keep route, method, CSRF \
             field and confirm hook" (fun ~url conn ->
        let* admin = insert_user ~admin:true conn "gab_admin" in
        let* target = insert_user conn "gab_target" in
        let* banned = insert_user ~banned:true conn "gab_banned" in
        let* cookie, _ = open_session "forms" ~url (admin, "gab_admin", true) in
        let* response, body = do_get ~url ~cookie ~target:"/u/gab_target" () in
        Alcotest.(check int) "profile 200" 200 (status_of response);
        Alcotest.(check bool) "ban form action" true
          (contains body
             (Printf.sprintf "<form action='/admin/ban/user/%d' method='POST'"
                target));
        Alcotest.(check bool) "ban confirm hook" true
          (contains body "confirmModal(event, 'Permanently ban u/gab_target?");
        let* _ = Lwt.return (Pch.csrf_of_page "profile ban form CSRF" body) in
        let* response, body = do_get ~url ~cookie ~target:"/admin" () in
        Alcotest.(check int) "/admin 200" 200 (status_of response);
        Alcotest.(check bool) "unban form action" true
          (contains body
             (Printf.sprintf
                "<form class='admin-act-form' action='/admin/unban/user/%d' \
                 method='POST'"
                banned));
        Alcotest.(check bool) "unban confirm hook" true
          (contains body "confirmModal(event, 'Lift global ban on u/gab_banned?");
        let* _ = Lwt.return (Pch.csrf_of_page "/admin unban form CSRF" body) in
        Lwt.return_unit)

  (* --- 1, 2, 14, 15: the happy paths, returning to the real surfaces --- *)
  let happy_path_case =
    db_case "valid same-session token bans and unbans; absolute same-origin \
             Referers return to the profile and /admin" (fun ~url conn ->
        let* admin = insert_user ~admin:true conn "gab_admin" in
        let* target = insert_user conn "gab_target" in
        let* cookie, token =
          open_session "happy" ~url (admin, "gab_admin", true)
        in
        let* response, _ =
          do_post ~url ~cookie ~token
            ~referer:"https://earde.com/u/gab_target"
            ~target:(ban_target target) ()
        in
        check_redirect "ban" "/u/gab_target" response;
        let* banned = is_banned conn target in
        Alcotest.(check bool) "target banned" true banned;
        let* notifs = mod_action_notifs conn target in
        Alcotest.(check int) "one mod_action notification" 1 notifs;
        let* response, _ =
          do_post ~url ~cookie ~token ~referer:"https://earde.com/admin"
            ~target:(unban_target target) ()
        in
        check_redirect "unban" "/admin" response;
        let* banned = is_banned conn target in
        Alcotest.(check bool) "target unbanned" false banned;
        (* Unban never notifies — the count is still the ban's single row. *)
        let* notifs = notif_count conn target in
        Alcotest.(check int) "no unban notification" 1 notifs;
        Lwt.return_unit)

  (* --- 3-9: every rejected token leaves zero side effects --- *)
  let rejected_tokens_case label ~action ~initially_banned =
    db_case label (fun ~url conn ->
        let* admin = insert_user ~admin:true conn "gab_admin" in
        let* target =
          insert_user ~banned:initially_banned conn "gab_target"
        in
        let* cookie, live =
          open_session "rejects" ~url (admin, "gab_admin", true)
        in
        let* expired = mint_expired "rejects" ~url ~cookie in
        let* _other_cookie, foreign =
          open_session "foreign" ~url (admin, "gab_admin", true)
        in
        as_user (admin, "gab_admin", true);
        let post_target =
          if action = `Ban then ban_target target else unban_target target
        in
        let attempts =
          [ ("missing token", None, true); ("forged token", Some "not-a-token", false);
            ("stale token", Some expired, false);
            ("foreign-session token", Some foreign, false)
          ]
        in
        let* () =
          Lwt_list.iter_s
            (fun (name, token, omit_token) ->
              let* response, body =
                do_post ~url ~cookie ~omit_token
                  ~token:(Option.value token ~default:"")
                  ~referer:"https://earde.com/admin" ~target:post_target ()
              in
              check_form_error name response body;
              let* banned = is_banned conn target in
              Alcotest.(check bool) (name ^ ": ban state untouched")
                initially_banned banned;
              let* notifs = notif_count conn target in
              Alcotest.(check int) (name ^ ": no notification") 0 notifs;
              Lwt.return_unit)
            attempts
        in
        (* The live token still works afterwards — rejection is per-request,
           not a session poison. *)
        let* response, _ =
          do_post ~url ~cookie ~token:live ~referer:"https://earde.com/admin"
            ~target:post_target ()
        in
        check_redirect "live token still accepted" "/admin" response;
        let* banned = is_banned conn target in
        Alcotest.(check bool) "action applied" (action = `Ban) banned;
        Lwt.return_unit)

  let ban_rejects_case =
    rejected_tokens_case
      "ban: missing, forged, stale and foreign-session tokens are rejected \
       with zero side effects"
      ~action:`Ban ~initially_banned:false

  let unban_rejects_case =
    rejected_tokens_case
      "unban: missing, forged, stale and foreign-session tokens are rejected \
       with zero side effects"
      ~action:`Unban ~initially_banned:true

  (* --- 10, 11: authorization comes first and is not bought by a token --- *)
  let authorization_case =
    db_case "non-admin with a valid token and anonymous POSTs keep the \
             existing denial; no mutation" (fun ~url conn ->
        let* _admin = insert_user ~admin:true conn "gab_admin" in
        let* peon = insert_user conn "gab_peon" in
        let* target = insert_user conn "gab_target" in
        let* banned_user = insert_user ~banned:true conn "gab_banned" in
        let* cookie, token =
          open_session "peon" ~url (peon, "gab_peon", false)
        in
        let* response, body =
          do_post ~url ~cookie ~token ~target:(ban_target target) ()
        in
        Alcotest.(check int) "non-admin ban: 200 page" 200 (status_of response);
        Alcotest.(check bool) "non-admin ban: denial copy" true
          (contains body "You are not an Admin.");
        let* response, body =
          do_post ~url ~cookie ~token ~target:(unban_target banned_user) ()
        in
        Alcotest.(check int) "non-admin unban: 200 page" 200
          (status_of response);
        Alcotest.(check bool) "non-admin unban: denial copy" true
          (contains body "You are not an Admin.");
        as_anonymous ();
        let* response, body =
          do_post ~url ~token:"" ~omit_token:true ~target:(ban_target target) ()
        in
        Alcotest.(check int) "anonymous ban: 200 page" 200 (status_of response);
        Alcotest.(check bool) "anonymous ban: denial copy" true
          (contains body "You are not an Admin.");
        let* banned = is_banned conn target in
        Alcotest.(check bool) "target never banned" false banned;
        let* still = is_banned conn banned_user in
        Alcotest.(check bool) "banned user still banned" true still;
        let* notifs = notif_count conn target in
        Alcotest.(check int) "no notification" 0 notifs;
        Lwt.return_unit)

  (* --- 12: target resolution stays authoritative and post-CSRF --- *)
  let unknown_target_case =
    db_case "unknown and malformed target ids keep the existing post-CSRF \
             behavior" (fun ~url conn ->
        let* admin = insert_user ~admin:true conn "gab_admin" in
        let* cookie, token =
          open_session "unknown" ~url (admin, "gab_admin", true)
        in
        (* A nonexistent id: the 0-row UPDATE still reads as success, the
           best-effort notification insert fails silently, and the redirect
           follows the usual fallback. Pinned as the pre-existing contract. *)
        let* response, _ =
          do_post ~url ~cookie ~token ~target:(ban_target 999999999) ()
        in
        check_redirect "unknown ban target" "/" response;
        let* response, _ =
          do_post ~url ~cookie ~token ~target:(unban_target 999999999) ()
        in
        check_redirect "unknown unban target" "/admin" response;
        (* A non-numeric id parses to 0 and stays the plain 400. *)
        let* response, body =
          do_post ~url ~cookie ~token ~target:"/admin/ban/user/abc" ()
        in
        Alcotest.(check int) "malformed id: 400" 400 (status_of response);
        Alcotest.(check bool) "malformed id: copy" true
          (contains body "Invalid user ID.");
        Lwt.return_unit)

  (* --- 16-21 + missing-Referer fallbacks, through the real handlers --- *)
  let redirect_grammar_case =
    db_case "Referer handling: local and same-origin values return to their \
             surface, hostile values fall back, no response ever leaves the \
             origin" (fun ~url conn ->
        let* admin = insert_user ~admin:true conn "gab_admin" in
        let* target = insert_user conn "gab_target" in
        let* cookie, token =
          open_session "grammar" ~url (admin, "gab_admin", true)
        in
        let ban ?referer () =
          let* () = set_banned conn ~banned:false target in
          do_post ~url ~cookie ~token ?referer ~target:(ban_target target) ()
        in
        let unban ?referer () =
          let* () = set_banned conn ~banned:true target in
          do_post ~url ~cookie ~token ?referer ~target:(unban_target target) ()
        in
        (* 16: relative local destinations stay accepted. *)
        let* response, _ = unban ~referer:"/admin" () in
        check_redirect "relative Referer" "/admin" response;
        (* 19: same-origin query strings survive. *)
        let* response, _ =
          ban ~referer:"https://earde.com/u/gab_target?tab=posts" ()
        in
        check_redirect "query preserved" "/u/gab_target?tab=posts" response;
        (* 20: fragments never reach the Location header. *)
        let* response, _ = unban ~referer:"https://earde.com/admin#banned" () in
        check_redirect "fragment dropped" "/admin" response;
        (* 17: a foreign origin falls back to each action's local default. *)
        let* response, _ = ban ~referer:"https://evil.example/u/gab_target" () in
        check_redirect "foreign Referer, ban fallback" "/" response;
        let* response, _ = unban ~referer:"https://evil.example/admin" () in
        check_redirect "foreign Referer, unban fallback" "/admin" response;
        (* 18: protocol-relative and malformed values fall back safely. *)
        let* response, _ = ban ~referer:"//evil.example/admin" () in
        check_redirect "protocol-relative Referer" "/" response;
        let* response, _ = unban ~referer:"earde.com/admin" () in
        check_redirect "malformed Referer" "/admin" response;
        (* Missing Referer: the documented local fallbacks. *)
        let* response, _ = ban () in
        check_redirect "no Referer, ban" "/" response;
        let* response, _ = unban () in
        check_redirect "no Referer, unban" "/admin" response;
        (* 21: sweep — no redirect above may carry a foreign origin; spot-
           check the worst offender end to end. *)
        let* response, _ =
          ban ~referer:"https://earde.com@evil.example/admin" ()
        in
        (match Dream.header response "Location" with
        | Some l ->
            Alcotest.(check bool) "userinfo trick: local Location" true
              (String.length l > 0 && l.[0] = '/'
              && not (String.length l >= 2 && l.[1] = '/'));
            Alcotest.(check bool) "userinfo trick: no evil.example" false
              (contains l "evil.example")
        | None -> Alcotest.fail "userinfo trick: no redirect");
        Lwt.return_unit)

  let suite =
    [ form_contract_case; happy_path_case; ban_rejects_case;
      unban_rejects_case; authorization_case; unknown_target_case;
      redirect_grammar_case ]
end

(* === Legacy /p/:id post fallback (pass 20A) ================================
   The last user-reachable Components.layout `Site document — Pages.post_page,
   view_post_handler's safe fallback for the pathological unmappable post
   (community_slug = "") — moves onto Components.launch_app_page under
   body.launch-legacy-post, with the warm-card fragment (post card, recursive
   comment tree, every vote/comment/delete/mod_delete/ban/join form, the
   mod/admin/ban dialogs and the toggleComment script) pinned byte-for-byte.
   Renderer pins (DB-free, real session middleware for the CSRF tag): wrapper
   identity and local assets only, one behavior script and one notification
   fetch for members, the guest share-only script and zero notification
   fetches for guests, the pinned form/dialog/id contracts across viewer
   states (guest / member / author / moderator / admin / banned target /
   tombstoned), the launch rail fed only by handler-supplied joined
   communities, and the h1 title escaping regression (the one interpolation
   this renderer emitted raw). Route pins (database-gated, the real handler):
   the untouched canonical 301 (status + Location + a launch-free redirect
   document byte-identical across viewer states), missing/invalid-id 404s,
   the private-community anti-enumeration gate running BEFORE any fallback
   chrome, and the real fallback render for both viewer states. *)
module Legacy_post_fallback = struct
  let case name f = Alcotest.test_case name `Quick f
  let ( let* ) = Lwt.bind

  (* The handler's synthesized minimal record for the unmappable post (its
     community_res is Ok None when the slug is empty), reproduced here for
     direct renderer calls. *)
  let fallback_community : Earde.Db.community =
    { id = 9107; slug = ""; name = ""; description = None; rules = None;
      avatar_url = None; banner_url = None; allow_downvotes = true;
      sections_enabled = false; visibility = Earde.Db.Community_public;
      indexable = true; is_network_community = false;
      onboarding_state = Earde.Db.Community_published; discoverable = true }

  let rail_community : Earde.Db.community =
    { fallback_community with id = 9108; slug = "qa-lgp-rail";
      name = "qa-lgp-rail" }

  let make_post ?(id = 9107) ?(title = "Qa fallback discussion")
      ?(content = Some "Qa fallback body") ?url ?image_url
      ?(username = "qa_lgp_author") () : Earde.Db.post =
    { id; title; url; content; community_id = 9107; user_id = 42; username;
      community_slug = ""; created_at = "2026-07-30 12:00:00"; score = 3;
      comment_count = 1; allow_downvotes = true; image_url;
      section_name = None; section_slug = None;
      community_sections_enabled = false; author_local_karma = 5;
      author_local_post_count = 2; author_local_comment_count = 3;
      author_first_active_at = None }

  let make_comment ?(id = 501) ?(content = "Qa fallback comment")
      ?(username = "qa_lgp_commenter") ?parent_id () : Earde.Db.comment =
    { id; content; username; created_at = "2026-07-30 12:05:00"; score = 1;
      parent_id; avatar_url = None; author_local_karma = 1;
      author_local_post_count = 0; author_local_comment_count = 1;
      author_first_active_at = None }

  let render ?user ?(session = []) ?(noindex = false) ?(is_member = false)
      ?(is_current_user_mod = false) ?(mod_usernames = [])
      ?(admin_usernames = []) ?(banned_usernames = [])
      ?(user_communities = []) ?(post = make_post ()) ?(comments = []) () =
    let rendered = ref None in
    let pipeline =
      Dream.set_secret gck_secret @@ Dream.memory_sessions
      @@ fun req ->
      let* () =
        Lwt_list.iter_s (fun (k, v) -> Dream.set_session_field req k v) session
      in
      rendered :=
        Some
          (Earde.Pages.post_page ?user ~noindex ~is_member
             ~is_current_user_mod ~mod_usernames ~admin_usernames
             ~banned_usernames ~community:fallback_community ~user_communities
             ~moderated_communities:[] [] [] post comments req);
      Dream.html ""
    in
    ignore
      (Lwt_main.run
         (pipeline (Dream.request ~method_:`GET ~target:"/p/9107" "")));
    match !rendered with
    | Some s -> s
    | None -> Alcotest.fail "renderer did not run"

  let member_session name = [ ("user_id", "43"); ("username", name) ]

  (* 1: anonymous document — launch wrapper, local assets only, the guest
     share-only script and nothing authenticated. *)
  let guest_wrapper_case =
    case "guest: launch wrapper, local assets, share-only script, zero \
          notification fetches" (fun () ->
        let page = render ~comments:[ make_comment () ] () in
        ps_must page "<body class='launch-legacy-post'>";
        ps_must page "<title>Qa fallback discussion - Earde</title>";
        ps_must page "<link rel='stylesheet' href='/static/css/earde.css'>";
        ps_must page
          "<link rel='stylesheet' href='/static/css/mobile-gate.css'>";
        ps_must_not page "tailwind";
        ps_must_not page "fonts.googleapis";
        ps_must_not page "fonts.gstatic";
        ps_must_not page "shell.css";
        ps_must_not page "create.css";
        ps_must_not page "auth.css";
        ps_must_not page "Nunito";
        (* Guest interaction surface: the byte-pinned Share control works via
           the share-only script; nothing else runs. *)
        Alcotest.(check int) "exactly one copyPostLink definition" 1
          (ps_count page "function copyPostLink");
        ps_must page "onclick='copyPostLink(\"/p/9107\", this)'";
        Alcotest.(check int) "zero notification fetches" 0
          (ps_count page "/api/unread-notifs");
        Alcotest.(check int) "no notif badge markup" 0
          (ps_count page "notif-badge");
        Alcotest.(check int) "no confirm modal" 0
          (ps_count page "function confirmModal");
        Alcotest.(check int) "no vote handler wiring" 0
          (ps_count page "form[action='/vote']");
        (* Anonymous gates preserved: vote arrows are /login links, the join
           box keeps its exact redirect_to, readable content stays. *)
        ps_must page "<a href='/login'";
        ps_must page "<input type='hidden' name='redirect_to' value='/p/9107'>";
        ps_must page "Qa fallback body";
        ps_must page "Qa fallback comment";
        ps_must page "ph-mask";
        (* Cartographic chrome + neutral copy; noindex only when asked. *)
        ps_must page "class='topbar'";
        ps_must page "class='rail'";
        ps_must_not page "noindex";
        ps_must page "toggleComment";
        ps_must_not page "Legacy";
        ps_must_not page "orphaned";
        let flagged = render ~noindex:true () in
        ps_must flagged "<meta name='robots' content='noindex'>")

  (* 2: member document — the shared behavior script exactly once (single
     copyPostLink source), one notification fetch, real vote forms, the rail
     fed by handler-supplied joined communities only. *)
  let member_scripts_case =
    case "member: one behavior script, one notification fetch, joined rail"
      (fun () ->
        let page =
          render ~user:"qa_lgp_member"
            ~session:(member_session "qa_lgp_member")
            ~user_communities:[ rail_community ]
            ~comments:[ make_comment () ] ()
        in
        Alcotest.(check int) "exactly one copyPostLink definition" 1
          (ps_count page "function copyPostLink");
        Alcotest.(check int) "exactly one notification fetch" 1
          (ps_count page "fetch('/api/unread-notifs')");
        Alcotest.(check int) "one confirm modal definition" 1
          (ps_count page "function confirmModal");
        ps_must page "id='notif-badge'";
        ps_must page "<form action='/vote' method='POST' class='m-0 p-0 flex'>";
        ps_must page "<form action='/vote-comment' method='POST' class='m-0 p-0'>";
        ps_must page "name=\"dream.csrf\"";
        (* The launch rail carries the real joined community and nothing
           invented — no current-community tile, no fallback entry. *)
        ps_must page "href='/c/qa-lgp-rail/ch/general'";
        Alcotest.(check int) "one community tile" 1
          (ps_count page "rail__item--community"))

  (* 3: the pinned fragment across author/member state — every form action,
     method, hidden id and dialog id byte-intact. *)
  let fragment_contract_case =
    case "author member: composer, reply, vote, delete and join contracts \
          byte-intact" (fun () ->
        let comments =
          [ make_comment (); make_comment ~id:502 ~parent_id:501
              ~content:"Qa nested reply" () ]
        in
        let page =
          render ~user:"qa_lgp_author"
            ~session:(member_session "qa_lgp_author")
            ~is_member:true ~comments ()
        in
        (* Top-level composer + per-comment reply forms (member-only). *)
        ps_must page "<form action='/comments' method='POST' class='mt-0'>";
        ps_must page "<input type='hidden' name='post_id' value='9107'>";
        ps_must page
          "<form id='reply-form-501' action='/comments' method='POST' \
           class='hidden w-full mt-3 mb-2'>";
        ps_must page "<input type='hidden' name='parent_id' value='501'>";
        (* Vote forms keep the optimistic-vote DOM contract. *)
        ps_must page "<input type='hidden' name='comment_id' value='501'>";
        ps_must page "<input type='hidden' name='direction' value='1'>";
        (* Own-post personal delete (Rule A) with its confirm hook. *)
        ps_must page "<form action='/delete-post' method='POST' class='inline \
                      m-0 p-0 ml-3' onsubmit=\"confirmModal(event, 'Do you \
                      really want to delete this post? This action cannot be \
                      undone.')\">";
        (* Member documents drop the join box; comment tree ids stay. *)
        ps_must_not page "name='redirect_to'";
        ps_must page "id='comment-content-501'";
        ps_must page "id='comment-children-501'";
        ps_must page "Qa nested reply";
        (* No nested forms: every <form is matched by exactly one </form>. *)
        Alcotest.(check int) "form open/close balance"
          (ps_count page "<form") (ps_count page "</form>"))

  (* 4: moderation permissions unchanged — mod dialogs (with the historical
     empty-slug action paths), admin fallback, banned badge, admin-target
     immunity. *)
  let moderation_case =
    case "moderator and admin controls unchanged (dialogs, ban, immunity)"
      (fun () ->
        let comments = [ make_comment () ] in
        let mod_page =
          render ~user:"qa_lgp_mod" ~session:(member_session "qa_lgp_mod")
            ~is_current_user_mod:true ~comments ()
        in
        ps_must mod_page "Mod Remove";
        ps_must mod_page "id='mod-modal-9107'";
        (* The unmappable post's historical action path is preserved verbatim
           (empty community slug and all). *)
        ps_must mod_page "action='/c//posts/9107/mod_delete'";
        ps_must mod_page "action='/c//comments/501/mod_delete'";
        ps_must mod_page "<form action='/ban-community-user' method='POST'";
        ps_must mod_page
          "<input type='hidden' name='target_username' value='qa_lgp_author'>";
        ps_must mod_page "<input type='hidden' name='community_id' value='9107'>";
        ps_must_not mod_page "Admin Remove";
        let admin_page =
          render ~user:"qa_lgp_admin"
            ~session:(("is_admin", "true") :: member_session "qa_lgp_admin")
            ~comments ()
        in
        ps_must admin_page "Admin Remove";
        ps_must admin_page "Admin Ban";
        ps_must_not admin_page "Mod Remove";
        (* Already-banned target shows the badge, not a second hammer. *)
        let banned_page =
          render ~user:"qa_lgp_mod" ~session:(member_session "qa_lgp_mod")
            ~is_current_user_mod:true
            ~banned_usernames:[ "qa_lgp_author"; "qa_lgp_commenter" ]
            ~comments ()
        in
        ps_must banned_page "🚫 Banned";
        ps_must_not banned_page "Mod Ban";
        (* Admin-authored content is immune to mod removal. *)
        let immune_page =
          render ~user:"qa_lgp_mod" ~session:(member_session "qa_lgp_mod")
            ~is_current_user_mod:true
            ~admin_usernames:[ "qa_lgp_author"; "qa_lgp_commenter" ]
            ~comments ()
        in
        ps_must_not immune_page "Mod Remove")

  (* 5: tombstoned content keeps its quiet state — no action buttons. *)
  let tombstone_case =
    case "deleted post and comment tombstones drop every action control"
      (fun () ->
        let page =
          render ~user:"qa_lgp_author"
            ~session:(member_session "qa_lgp_author")
            ~post:(make_post ~content:(Some "[deleted]") ())
            ~comments:[ make_comment ~content:"[removed by moderator]" () ] ()
        in
        ps_must_not page "action='/delete-post'";
        ps_must_not page "action='/delete-comment'";
        ps_must_not page "Mod Remove")

  (* 6: the h1 escaping regression — the one interpolation this renderer
     emitted raw. Every user-controlled field stays escaped text. *)
  let escaping_case =
    case "post title (h1 + <title>) and comment content stay escaped text"
      (fun () ->
        let page =
          render
            ~post:
              (make_post
                 ~title:"Qa <script>alert(1)</script> & \"q\" 'tick'"
                 ~content:(Some "body <img src=x onerror=alert(2)>") ())
            ~comments:
              [ make_comment ~content:"<b>bold</b> & <i>sneaky</i>" () ] ()
        in
        ps_must page
          "Qa &lt;script&gt;alert(1)&lt;/script&gt; &amp; &quot;q&quot; \
           &#39;tick&#39;";
        ps_must page
          "<title>Qa &lt;script&gt;alert(1)&lt;/script&gt; &amp; \
           &quot;q&quot; &#39;tick&#39; - Earde</title>";
        ps_must_not page "<script>alert(1)";
        ps_must page "body &lt;img src=x onerror=alert(2)&gt;";
        ps_must_not page "<img src=x";
        ps_must page "&lt;b&gt;bold&lt;/b&gt; &amp; &lt;i&gt;sneaky&lt;/i&gt;";
        ps_must_not page "<b>bold</b>")

  let renderer_suite =
    [ guest_wrapper_case; member_scripts_case; fragment_contract_case;
      moderation_case; tombstone_case; escaping_case ]

  (* --- Route suite: the real GET /p/:id handler over a real database. --- *)

  open Caqti_request.Infix

  let q_cleanup =
    List.map
      (fun sql -> (Caqti_type.unit ->. Caqti_type.unit) sql)
      [ "DELETE FROM comments WHERE post_id IN (SELECT id FROM posts WHERE title LIKE 'Legpost %')"
      ; "DELETE FROM posts WHERE title LIKE 'Legpost %'"
      ; "DELETE FROM community_members WHERE community_id IN (SELECT id FROM communities WHERE slug = 'legpost-c' OR name LIKE 'legpost %')"
      ; "DELETE FROM communities WHERE slug = 'legpost-c' OR name LIKE 'legpost %'"
      ; "DELETE FROM users WHERE username LIKE 'legpost_%'"
      ]

  let or_fail label = function
    | Ok v -> Lwt.return v
    | Error e -> Alcotest.failf "%s: %s" label (Caqti_error.show e)

  let db_case name f =
    Alcotest.test_case name `Quick (fun () ->
        match Sys.getenv_opt "EARDE_TEST_DATABASE_URL" with
        | None | Some "" -> Alcotest.skip ()
        | Some url ->
            Lwt_main.run
              (let* conn = Caqti_lwt_unix.connect (Uri.of_string url) in
               let* conn = or_fail "connect" conn in
               let (module C : Caqti_lwt.CONNECTION) = conn in
               let cleanup () =
                 Lwt_list.iter_s
                   (fun q ->
                     let* r = C.exec q () in
                     let* _ = or_fail "cleanup" r in
                     Lwt.return_unit)
                   q_cleanup
               in
               let* () = cleanup () in
               Lwt.finalize
                 (fun () -> f ~url (module C : Caqti_lwt.CONNECTION))
                 (fun () ->
                   Lwt.finalize cleanup (fun () -> C.disconnect ()))))

  let q_insert_user =
    (Caqti_type.(t2 string bool) ->! Caqti_type.int)
      "INSERT INTO users (username, email, password_hash, is_email_verified, is_admin)
       VALUES ($1, $1 || '@test.invalid', 'x', TRUE, $2) RETURNING id"

  let q_insert_community =
    (Caqti_type.(t2 string string) ->! Caqti_type.int)
      "INSERT INTO communities (slug, name) VALUES ($1, $2) RETURNING id"

  let q_make_private =
    (Caqti_type.int ->. Caqti_type.unit)
      "UPDATE communities SET visibility = 'private' WHERE id = $1"

  let q_insert_post =
    (Caqti_type.(t3 string int int) ->! Caqti_type.int)
      "INSERT INTO posts (title, content, community_id, user_id)
       VALUES ($1, $1 || ' body', $2, $3) RETURNING id"

  let q_insert_comment =
    (Caqti_type.(t3 string int int) ->! Caqti_type.int)
      "INSERT INTO comments (content, post_id, user_id)
       VALUES ($1, $2, $3) RETURNING id"

  type fx = {
    author : int;
    admin : int;
    canonical_post : int;
    fallback_post : int;
    fallback_community : int;
  }

  (* One mappable community/post pair (the 301 arm) and one unmappable pair:
     a community row whose slug is the empty string — the only durable state
     that reaches the fallback renderer (the app cannot create it; it stands
     in for historical/corrupt rows). *)
  let make_fixtures (module C : Caqti_lwt.CONNECTION) =
    let* author = C.find q_insert_user ("legpost_author", false) in
    let* author = or_fail "author" author in
    let* admin = C.find q_insert_user ("legpost_admin", true) in
    let* admin = or_fail "admin" admin in
    let* canonical_c = C.find q_insert_community ("legpost-c", "legpost canonical") in
    let* canonical_c = or_fail "canonical community" canonical_c in
    let* fallback_c = C.find q_insert_community ("", "legpost fallback") in
    let* fallback_c = or_fail "fallback community" fallback_c in
    let* canonical_post =
      C.find q_insert_post ("Legpost canonical post", canonical_c, author)
    in
    let* canonical_post = or_fail "canonical post" canonical_post in
    let* fallback_post =
      C.find q_insert_post ("Legpost fallback post", fallback_c, author)
    in
    let* fallback_post = or_fail "fallback post" fallback_post in
    let* comment =
      C.find q_insert_comment ("Legpost fallback comment", fallback_post, author)
    in
    let* _ = or_fail "comment" comment in
    Lwt.return
      { author; admin; canonical_post; fallback_post;
        fallback_community = fallback_c }

  let router =
    Dream.router [ Dream.get "/p/:id" Earde.Handlers.view_post_handler ]

  let run ~url ?(session = []) target =
    let pipeline =
      Dream.sql_pool url @@ Dream.set_secret gck_secret
      @@ Dream.memory_sessions
      @@ fun req ->
      let* () =
        Lwt_list.iter_s
          (fun (k, v) -> Dream.set_session_field req k v)
          session
      in
      router req
    in
    let request = Dream.request ~method_:`GET ~target "" in
    let* response = pipeline request in
    let* body = Dream.body response in
    let location = Dream.header response "Location" in
    Lwt.return (Dream.status_to_int (Dream.status response), location, body)

  let session_of uid name =
    [ ("user_id", string_of_int uid); ("username", name) ]

  (* 1: the canonical arm is untouched — exact 301 + Location, no launch
     document, no notification wiring, and a redirect response byte-identical
     across anonymous and authenticated viewers. *)
  let redirect_case =
    db_case "canonical post: exact 301 + Location, launch-free, viewer-\
             independent" (fun ~url c ->
        let* fx = make_fixtures c in
        let target = "/p/" ^ string_of_int fx.canonical_post in
        let* status, location, body = run ~url target in
        Alcotest.(check int) "301" 301 status;
        Alcotest.(check (option string)) "Location"
          (Some
             (Earde.Components.canonical_thread_path "legpost-c"
                fx.canonical_post "Legpost canonical post"))
          location;
        ps_must_not body "launch-legacy-post";
        ps_must_not body "unread-notifs";
        ps_must_not body "earde.css";
        ps_must_not body "<form";
        let* status2, location2, body2 =
          run ~url ~session:(session_of fx.author "legpost_author") target
        in
        Alcotest.(check int) "authenticated 301" 301 status2;
        Alcotest.(check (option string)) "authenticated Location" location
          location2;
        Alcotest.(check string) "redirect body byte-identical across viewers"
          body body2;
        Lwt.return_unit)

  (* 2: the real fallback render, both viewer states. *)
  let fallback_case =
    db_case "fallback post: launch document, guest zero / member one \
             notification fetch" (fun ~url c ->
        let* fx = make_fixtures c in
        let target = "/p/" ^ string_of_int fx.fallback_post in
        let* status, _, body = run ~url target in
        Alcotest.(check int) "anonymous 200" 200 status;
        ps_must body "<body class='launch-legacy-post'>";
        ps_must body "<link rel='stylesheet' href='/static/css/earde.css'>";
        ps_must body
          "<link rel='stylesheet' href='/static/css/mobile-gate.css'>";
        ps_must_not body "tailwind";
        ps_must_not body "fonts.googleapis";
        ps_must body "Legpost fallback post";
        ps_must body "Legpost fallback comment";
        Alcotest.(check int) "guest: one copyPostLink" 1
          (ps_count body "function copyPostLink");
        Alcotest.(check int) "guest: zero notification fetches" 0
          (ps_count body "/api/unread-notifs");
        ps_must body "<a href='/login'";
        let* status2, _, body2 =
          run ~url ~session:(session_of fx.author "legpost_author") target
        in
        Alcotest.(check int) "member 200" 200 status2;
        Alcotest.(check int) "member: exactly one notification fetch" 1
          (ps_count body2 "fetch('/api/unread-notifs')");
        Alcotest.(check int) "member: one copyPostLink" 1
          (ps_count body2 "function copyPostLink");
        ps_must body2 "<form action='/vote' method='POST'";
        ps_must body2 "name=\"dream.csrf\"";
        (* Author is not a member: the join box keeps its exact redirect. *)
        ps_must body2
          ("<input type='hidden' name='redirect_to' value='/p/"
          ^ string_of_int fx.fallback_post ^ "'>");
        Lwt.return_unit)

  (* 3: missing / invalid ids keep their 404 message pages — no launch post
     document, no notification wiring. *)
  let missing_case =
    db_case "missing and invalid ids: unchanged 404 message pages"
      (fun ~url c ->
        let* _fx = make_fixtures c in
        let* status, _, body = run ~url "/p/999999999" in
        Alcotest.(check int) "missing 404" 404 status;
        ps_must body "This post does not exist or has been deleted.";
        ps_must_not body "launch-legacy-post";
        ps_must_not body "unread-notifs";
        let* status2, _, body2 = run ~url "/p/not-a-number" in
        Alcotest.(check int) "invalid 404" 404 status2;
        ps_must body2 "Invalid post ID.";
        ps_must_not body2 "launch-legacy-post";
        Lwt.return_unit)

  (* 4: the private gate still runs BEFORE anything renders — outsiders get
     the canonical community 404 with zero fallback chrome or content leak;
     a global admin still reaches the fallback document. *)
  let private_gate_case =
    db_case "private fallback community: anti-enumeration 404 first, admin \
             still renders" (fun ~url c ->
        let* fx = make_fixtures c in
        let (module C : Caqti_lwt.CONNECTION) = c in
        let* r = C.exec q_make_private fx.fallback_community in
        let* () = or_fail "make private" r in
        let target = "/p/" ^ string_of_int fx.fallback_post in
        let* status, _, body = run ~url target in
        Alcotest.(check int) "outsider 404" 404 status;
        ps_must body "This community does not exist.";
        ps_must_not body "Legpost fallback post";
        ps_must_not body "launch-legacy-post";
        ps_must_not body "unread-notifs";
        let* status2, _, body2 =
          run ~url
            ~session:
              (("is_admin", "true") :: session_of fx.admin "legpost_admin")
            target
        in
        Alcotest.(check int) "admin 200" 200 status2;
        ps_must body2 "<body class='launch-legacy-post'>";
        ps_must body2 "Legpost fallback post";
        Lwt.return_unit)

  let route_suite =
    [ redirect_case; fallback_case; missing_case; private_gate_case ]
end

(* === Legacy-asset census (final cleanup pass) =============================
   A static/regression guard over the PRODUCTION sources and a set of live
   rendered documents, proving the removals of this pass stay removed:

   - GET /earde-hq-dashboard has no route registration, handler or renderer,
     and the router has no catch-all that could answer it — so the path falls
     to Dream's normal unknown-route response;
   - none of the deleted chrome wrappers has a production caller;
   - no production source or rendered document references a deleted
     stylesheet, the Tailwind CDN, or Google Fonts;
   - every launch document loads exactly the two approved local stylesheets;
   - the redirects, routes and shared renderers that had to survive are all
     still registered and still render on launch chrome.

   Source-census only — no database, no server, no shell commands. The scanned
   set is every lib/*.ml{,i} plus bin/main.ml, declared as dune deps. Comments
   count: a stale note naming a deleted file is as much a lie as a live link,
   so the OCaml sources are scanned verbatim. *)
module Legacy_census = struct
  let lc_case name f = Alcotest.test_case name `Quick f

  (* dune test runs in test/, dune exec from the project root. *)
  let root = if Sys.file_exists "../bin/main.ml" then ".." else "."

  let read path =
    let ic = open_in_bin (Filename.concat root path) in
    let n = in_channel_length ic in
    let s = really_input_string ic n in
    close_in ic;
    s

  (* Every production OCaml source, discovered rather than listed, so a new
     module cannot quietly escape the census. *)
  let production_sources =
    let lib = Filename.concat root "lib" in
    let lib_files =
      Sys.readdir lib |> Array.to_list
      |> List.filter (fun f ->
             Filename.check_suffix f ".ml" || Filename.check_suffix f ".mli")
      |> List.sort compare
      |> List.map (fun f -> ("lib/" ^ f, read ("lib/" ^ f)))
    in
    ("bin/main.ml", read "bin/main.ml") :: lib_files

  let main_ml = List.assoc "bin/main.ml" production_sources

  let absent_everywhere label needle =
    List.iter
      (fun (path, body) ->
        if contains body needle then
          Alcotest.failf "%s: %s still contains %S" label path needle)
      production_sources

  let count_in haystack needle = count_sub haystack needle

  (* --- 1. no production route for the retired KPI dashboard -------------- *)
  let hq_route_case =
    lc_case "no /earde-hq-dashboard route, handler or renderer" (fun () ->
        (* The route table is the authority: no registration of any method. *)
        List.iter
          (fun needle ->
            Alcotest.(check bool)
              (Printf.sprintf "main.ml free of %S" needle)
              false (contains main_ml needle))
          [ "\"/earde-hq-dashboard\""; "hq_dashboard" ];
        (* Handler and renderer are gone from every production source. The
           page-view exclusion filter in handlers.ml deliberately still names
           the retired path (unchanged analytics behaviour for 404 traffic),
           so the symbol census is what proves the surface is gone. *)
        absent_everywhere "hq handler" "hq_dashboard_handler";
        absent_everywhere "hq renderer" "hq_dashboard_page";
        absent_everywhere "kpi query" "get_kpi_dashboard";
        absent_everywhere "dau/mau query" "get_dau_mau_ratio")

  (* --- 2. no production caller of any deleted wrapper -------------------- *)
  let deleted_wrappers =
    [ "Components.layout"; "Components.auth_page"; "Components.create_page"
    ; "Components.admin_page"; "Components.account_page"
    ; "Components.community_manage_page"; "Components.community_home_page"
    ; "Components.search_page"; "Components.global_shell"
    ; "Components.community_shell"; "Components.feed_shell"
    ; "Components.render_app_topbar"; "Components.left_sidebar"
    ; "Components.community_card"; "Pages.index"; "Handlers.home_handler" ]

  let dead_wrapper_case =
    lc_case "no production caller of any deleted wrapper" (fun () ->
        List.iter (fun n -> absent_everywhere "deleted wrapper" n)
          deleted_wrappers;
        (* and no definition survives either *)
        List.iter
          (fun n -> absent_everywhere "deleted definition" n)
          [ "let layout "; "let auth_page "; "let create_page "
          ; "let admin_page "; "let account_page "; "let community_manage_page "
          ; "let community_home_page "; "let search_page "; "let global_shell "
          ; "let community_shell "; "let feed_shell "; "let render_app_topbar "
          ; "let left_sidebar "; "let community_card "; "let home_handler "
          ; "type rail_active"; "type nav_item"; "type nav_group" ])

  (* --- 3./4./5. deleted stylesheets, Tailwind CDN, Google Fonts ---------- *)
  let deleted_stylesheets =
    [ "shell.css"; "create.css"; "admin.css"; "auth.css"; "account.css"
    ; "community-manage.css"; "community-home.css"; "search.css" ]

  let deleted_css_case =
    lc_case "no production reference to a deleted stylesheet" (fun () ->
        List.iter
          (fun f ->
            absent_everywhere "deleted stylesheet" f;
            absent_everywhere "deleted stylesheet path" ("/static/css/" ^ f))
          deleted_stylesheets)

  let approved_stylesheets = [ "earde.css"; "mobile-gate.css" ]

  let surviving_css_case =
    lc_case "only the two approved stylesheets are served" (fun () ->
        (* Every <link rel='stylesheet'> the production sources emit points at
           an approved local path. *)
        let sources =
          List.concat_map
            (fun (_, body) ->
              let marker = "href='/static/css/" in
              let ml = String.length marker in
              let rec loop i acc =
                match index_of (String.sub body i (String.length body - i)) marker with
                | None -> acc
                | Some j ->
                    let start = i + j + ml in
                    let stop =
                      let rec f k = if body.[k] = '\'' then k else f (k + 1) in
                      f start
                    in
                    loop stop (String.sub body start (stop - start) :: acc)
              in
              loop 0 [])
            production_sources
        in
        Alcotest.(check bool) "at least one stylesheet is emitted" true
          (sources <> []);
        List.iter
          (fun f ->
            if not (List.mem f approved_stylesheets) then
              Alcotest.failf "unapproved stylesheet reference: %S" f)
          sources;
        (* Both survivors are actually still used. *)
        List.iter
          (fun f ->
            Alcotest.(check bool)
              (Printf.sprintf "%s is still linked" f)
              true (List.mem f sources))
          approved_stylesheets)

  let external_assets_case =
    lc_case "no Tailwind CDN and no Google Fonts in production" (fun () ->
        List.iter
          (fun n -> absent_everywhere "external asset" n)
          [ "cdn.tailwindcss.com"; "tailwindcss"; "fonts.googleapis.com"
          ; "fonts.gstatic.com" ];
        (* The two shipped stylesheets must not pull them in either. *)
        List.iter
          (fun sheet ->
            let css = read ("static/css/" ^ sheet) in
            List.iter
              (fun n ->
                if contains css n then
                  Alcotest.failf "%s imports %S" sheet n)
              [ "fonts.googleapis.com"; "fonts.gstatic.com"
              ; "cdn.tailwindcss.com"; "@import url('http" ])
          approved_stylesheets)

  (* --- 6./13. rendered documents: approved local CSS only ---------------- *)
  let census_community ~visibility : Earde.Db.community =
    { id = 3; slug = "census"; name = "Census"; description = None
    ; rules = None; avatar_url = None; banner_url = None
    ; allow_downvotes = true; sections_enabled = true; visibility
    ; indexable = true; is_network_community = false
    ; onboarding_state = Earde.Db.Community_published; discoverable = true }

  (* One document per live wrapper family. *)
  let launch_documents () =
    let community = census_community ~visibility:Earde.Db.Community_public in
    [ ( "launch_entry_page"
      , Earde.Components.launch_entry_page ~page_class:"launch-bring"
          ~title:"T" ~content:"B" () )
    ; ( "launch_auth_page"
      , Earde.Components.launch_auth_page ~page_class:"launch-login" ~title:"T"
          ~content:"B" () )
    ; ( "launch_message_page"
      , Earde.Components.launch_message_page ~title:"T" ~content:"B" () )
    ; ( "launch_app_page (anonymous)"
      , Earde.Components.launch_app_page ~page_class:"launch-feed" ~title:"T"
          ~content:"B" () )
    ; ( "launch_app_page (member)"
      , Earde.Components.launch_app_page ~user:"alice"
          ~page_class:"launch-feed" ~title:"T" ~content:"B" () )
    ; ( "launch_onboarding_page"
      , Earde.Components.launch_onboarding_page
          ~page_class:"launch-project-new" ~title:"T" ~content:"B" () )
    ; ( "launch_community_page"
      , Earde.Components.launch_community_page ~community ~sidebar:"S"
          ~page_class:"launch-community-overview" ~title:"T" ~content:"B" () )
    ; ( "launch_community_surface_page"
      , Earde.Components.launch_community_surface_page ~community ~sidebar:"S"
          ~page_class:"launch-community-channel" ~title:"T"
          ~main_el:"<main class='cs-main'>B</main>" () )
    ]

  let rendered_css_case =
    lc_case "every launch document loads approved local CSS only" (fun () ->
        List.iter
          (fun (label, html) ->
            (* no off-origin asset of any kind *)
            List.iter
              (fun needle ->
                if contains html needle then
                  Alcotest.failf "%s references %S" label needle)
              [ "cdn.tailwindcss.com"; "fonts.googleapis.com"
              ; "fonts.gstatic.com"; "href='http"; "href=\"http"
              ; "src='http"; "src=\"http"; "@import" ];
            List.iter
              (fun sheet ->
                if contains html sheet then
                  Alcotest.failf "%s still loads %s" label sheet)
              deleted_stylesheets;
            Alcotest.(check bool)
              (label ^ " loads earde.css")
              true
              (contains html "<link rel='stylesheet' href='/static/css/earde.css'>"))
          (launch_documents ()))

  (* --- 7./8./9./10. routes that had to survive --------------------------- *)
  let surviving_routes_case =
    lc_case "surviving route registrations are intact" (fun () ->
        List.iter
          (fun needle ->
            Alcotest.(check bool)
              (Printf.sprintf "main.ml registers %s" needle)
              true (contains main_ml needle))
          [ (* 7. root redirect *)
            "Dream.get \"/\" (fun request -> Dream.redirect request \"/feed\")"
            (* 8. legacy /all redirect *)
          ; "Dream.get \"/all\" (fun request -> Dream.redirect request \"/feed\")"
          ; "Dream.get \"/feed\" Earde.Handlers.feed_handler"
            (* 9. canonical /p/:id + its converted fallback *)
          ; "Dream.get \"/p/:id\" Earde.Handlers.view_post_handler"
            (* 10. /admin and its global ban/unban actions *)
          ; "Dream.get  \"/admin\" Earde.Handlers.admin_dashboard_handler"
          ; "Dream.post \"/admin/ban/user/:id\" Earde.Handlers.ban_user_handler"
          ; "Dream.post \"/admin/unban/user/:id\" \
             Earde.Handlers.unban_user_global_handler"
            (* explicitly retained by the product decision *)
          ; "Dream.get \"/_debug/state\" Earde.Handlers.debug_state_handler"
          ; "Dream.get \"/new-community\" Earde.Handlers.new_community_page"
          ])

  (* --- 14. a removed route reaches the normal unknown-route response ----- *)
  let unknown_route_case =
    lc_case "no catch-all can answer a removed route" (fun () ->
        (* Dream answers an unmatched target with its own 404. The only way the
           retired path could still be served is a wildcard route, so the
           router must carry exactly one — the static file mount. *)
        Alcotest.(check int) "wildcard routes" 1 (count_in main_ml "/**");
        Alcotest.(check bool) "the wildcard is the static mount" true
          (contains main_ml
             "Dream.get \"/static/**\" (Dream.static \"static\")");
        (* Dream.any is used once, for the analytics-consent 405 arm. *)
        Alcotest.(check int) "Dream.any routes" 1 (count_in main_ml "Dream.any");
        Alcotest.(check bool) "and it is path-specific" true
          (contains main_ml "Dream.any \"/analytics/consent\""))

  (* --- 10b. /admin carries no KPI-dashboard link ------------------------- *)
  let admin_no_kpi_case =
    lc_case "/admin offers no KPI dashboard and no analytics vendor link"
      (fun () ->
        let html =
          with_session_request ~target:"/admin" (fun req ->
              Earde.Pages.admin_dashboard_page ~user:"root"
                ~signups_enabled:true ~turnstile:`Configured
                ~brevo_configured:true ~recent_users:[] ~pending:[]
                ~banned_users:[] req)
        in
        List.iter
          (fun needle ->
            if contains html needle then
              Alcotest.failf "/admin still offers %S" needle)
          [ "earde-hq-dashboard"; "hq-dashboard"; "Mission Control"
          ; "posthog.com"; "PostHog" ];
        (* still the real admin surface *)
        Alcotest.(check bool) "renders the launch admin document" true
          (contains html "<body class='launch-global-admin'>"))

  (* --- 11. the shared message document survives -------------------------- *)
  let msg_page_case =
    lc_case "shared msg_page is intact on the launch message document"
      (fun () ->
        (* signature retention *)
        ignore
          (Earde.Pages.msg_page
            : ?user:string ->
              ?auth:bool ->
              title:string ->
              message:string ->
              alert_type:string ->
              return_url:string ->
              Dream.request ->
              string);
        let render ?auth () =
          Earde.Pages.msg_page ?auth ~title:"T" ~message:"M"
            ~alert_type:"success" ~return_url:"/login"
            (Dream.request ~method_:`GET ~target:"/login" "")
        in
        let plain = render () in
        Alcotest.(check bool) "neutral launch message document" true
          (contains plain "<body class='launch-message-page'>");
        (* the anti-enumeration equality: both arms stay byte-identical *)
        Alcotest.(check string) "~auth arms are byte-identical" plain
          (render ~auth:true ());
        Alcotest.(check string) "~auth:false is the same document" plain
          (render ~auth:false ()))

  (* --- 12. exactly one behavior-script definition ------------------------ *)
  let single_behavior_script_case =
    lc_case "launch helpers keep exactly one behavior-script definition"
      (fun () ->
        let components = List.assoc "lib/components.ml" production_sources in
        List.iter
          (fun (label, needle) ->
            Alcotest.(check int)
              (Printf.sprintf "one %s" label)
              1 (count_in components needle))
          [ ("behavior script", "let launch_behavior_script")
          ; ("share snippet", "let launch_share_snippet")
          ; ("share script", "let launch_share_script")
          ; ("mobile gate panel", "let mobile_desktop_gate")
          ; ("analytics assets", "let analytics_assets") ];
        (* The share helper is one snippet reused by both scripts, so
           copyPostLink can never fork. *)
        Alcotest.(check int) "one copyPostLink definition" 1
          (count_in components "function copyPostLink");
        (* Exactly one notification fetch call in the whole component library,
           so a member document can never fire two and an anonymous one can
           never inherit it. *)
        Alcotest.(check int) "one unread-notifs fetch call" 1
          (count_in components "fetch('/api/unread-notifs')"))

  let suite =
    [ hq_route_case; dead_wrapper_case; deleted_css_case; surviving_css_case
    ; external_assets_case; rendered_css_case; surviving_routes_case
    ; unknown_route_case; admin_no_kpi_case; msg_page_case
    ; single_behavior_script_case ]
end

(* The persistent top-right launch-topbar action (Components.launch_connect_cta).
   It replaced the ochre "＋ Connect" outline control with a compact dark
   GitHub-mark "Connect" button, and it is the ONE shared value the four launch
   documents render, so the assertions here are both rendered-document and
   source-census: no wrapper may grow a private copy or drift back to the plus
   glyph.

   The second half pins what must NOT have moved: /bring's own full-label
   primary action stays byte-identical (the whole <form>…</form>, mark
   included), the anonymous cluster keeps its three links and no Connect
   button, and the auth/message documents — which have no application topbar —
   gain nothing at all. Pure renderers plus a file scan: no database, no
   server. *)
module Launch_cta = struct
  let cc_case name f = Alcotest.test_case name `Quick f

  let community = nav_test_community

  (* The exact element, as the wrapper emits it. Byte-exact on purpose: copy,
     destination, element type, accessible name and icon size are all product
     decisions, and a diff here should be a deliberate edit, not a surprise. *)
  let cta_open =
    "<a class='btn btn--connect-github' href='/bring' title='Connect an \
     open-source project' aria-label='Connect GitHub'>"

  let github_path = "<path d='M8 0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 7.59"

  (* Every live launch document whose top bar carries the persistent action:
     the viewer-independent entry chrome plus the member arm of each app-chrome
     wrapper. *)
  let cta_documents () =
    [ ( "launch_entry_page"
      , Earde.Components.launch_entry_page ~page_class:"launch-bring"
          ~title:"T" ~content:"B" () )
    ; ( "launch_app_page (member)"
      , Earde.Components.launch_app_page ~user:"alice"
          ~page_class:"launch-feed" ~title:"T" ~content:"B" () )
    ; ( "launch_onboarding_page (member)"
      , Earde.Components.launch_onboarding_page ~user:"alice"
          ~page_class:"launch-project-new" ~title:"T" ~content:"B" () )
    ; ( "launch_community_page (member)"
      , Earde.Components.launch_community_page ~user:"alice" ~community
          ~sidebar:"S" ~page_class:"launch-community-overview" ~title:"T"
          ~content:"B" () )
    ; ( "launch_community_surface_page (member)"
      , Earde.Components.launch_community_surface_page ~user:"alice" ~community
          ~sidebar:"S" ~page_class:"launch-community-channel" ~title:"T"
          ~main_el:"<main class='cs-main'>B</main>" () )
    ]

  (* 1./2./3./4./5. — the shape of the control itself, on every wrapper that
     renders it. /feed, /search, /notifications, /u/:name, /settings and /admin
     are all launch_app_page; the community surfaces are launch_community_doc;
     so covering the wrappers covers the routes. *)
  let shape_case =
    cc_case "every launch topbar renders one compact GitHub Connect action"
      (fun () ->
        List.iter
          (fun (label, html) ->
            Alcotest.(check int)
              (label ^ ": exactly one CTA")
              1 (count_sub html cta_open);
            Alcotest.(check bool)
              (label ^ ": visible text is Connect")
              true
              (contains html (cta_open ^ "<svg"));
            Alcotest.(check bool)
              (label ^ ": label closes the element")
              true
              (contains html "<span>Connect</span></a>");
            (* exactly one local GitHub mark in the topbar chrome *)
            Alcotest.(check int)
              (label ^ ": one GitHub mark")
              1 (count_sub html github_path);
            Alcotest.(check bool)
              (label ^ ": mark is 15px and decorative")
              true
              (contains html
                 "<svg width='15' height='15' viewBox='0 0 16 16' \
                  fill='currentColor' aria-hidden='true'>");
            (* no plus glyph anywhere in the actions cluster wording *)
            List.iter
              (fun needle ->
                Alcotest.(check bool)
                  (label ^ ": no " ^ needle)
                  false (contains html needle))
              [ "&#65291; Connect"; "btn--outline-ochre" ];
            (* still a same-tab GET link to /bring: no form, no new window, no
               query string, no script hook *)
            List.iter
              (fun needle ->
                Alcotest.(check bool)
                  (label ^ ": CTA keeps no " ^ needle)
                  false
                  (contains cta_open needle))
              [ "target="; "onclick"; "?"; "method"; "http" ])
          (cta_documents ()))

  (* 10. the mark is inlined local markup — no request leaves the origin for
     it, and no icon font or sprite is introduced. *)
  (* The rendered element, sliced out of a real document so the test never
     needs the helper itself in Components' public surface. *)
  let cta_element html =
    let rec find_open from =
      if from + String.length cta_open > String.length html then
        Alcotest.fail "no launch Connect CTA in document"
      else if String.sub html from (String.length cta_open) = cta_open then from
      else find_open (from + 1)
    in
    let i = find_open 0 in
    let close = "</a>" in
    let rec find_close from =
      if from + String.length close > String.length html then
        Alcotest.fail "launch Connect CTA is unclosed"
      else if String.sub html from (String.length close) = close then
        from + String.length close
      else find_close (from + 1)
    in
    let j = find_close i in
    String.sub html i (j - i)

  let no_external_asset_case =
    cc_case "the GitHub mark is inlined, not fetched" (fun () ->
        let cta =
          cta_element
            (Earde.Components.launch_app_page ~user:"alice"
               ~page_class:"launch-feed" ~title:"T" ~content:"B" ())
        in
        List.iter
          (fun needle ->
            Alcotest.(check bool)
              ("CTA references " ^ needle)
              false (contains cta needle))
          [ "http"; "//"; "<img"; "url("; "@font-face"; "github.com"
          ; "githubusercontent" ];
        Alcotest.(check bool) "mark is an inline svg" true
          (contains cta github_path))

  (* State behavior: anonymous viewers keep exactly the cluster they had. *)
  let anonymous_case =
    cc_case "anonymous launch chrome is unchanged and shows no Connect button"
      (fun () ->
        List.iter
          (fun (label, html) ->
            Alcotest.(check int)
              (label ^ ": no Connect button")
              0 (count_sub html cta_open);
            Alcotest.(check int)
              (label ^ ": no GitHub mark")
              0 (count_sub html github_path);
            List.iter
              (fun needle ->
                Alcotest.(check bool)
                  (label ^ ": keeps " ^ needle)
                  true (contains html needle))
              [ "<a class='btn btn--quiet' href='/bring'>Bring a project</a>"
              ; "<a class='btn btn--secondary btn--auth' href='/login'>Log \
                 in</a>"
              ; "<a class='btn btn--primary btn--auth' href='/signup'>Sign \
                 up</a>" ])
          [ ( "launch_app_page (anonymous)"
            , Earde.Components.launch_app_page ~page_class:"launch-feed"
                ~title:"T" ~content:"B" () )
          ; ( "launch_onboarding_page (anonymous)"
            , Earde.Components.launch_onboarding_page
                ~page_class:"launch-project-new" ~title:"T" ~content:"B" () )
          ; ( "launch_community_page (anonymous)"
            , Earde.Components.launch_community_page ~community ~sidebar:"S"
                ~page_class:"launch-community-overview" ~title:"T" ~content:"B"
                () )
          ])

  (* 8. documents without the application topbar gain nothing. *)
  let chromeless_case =
    cc_case "auth and message documents keep no application Connect action"
      (fun () ->
        List.iter
          (fun (label, html) ->
            List.iter
              (fun needle ->
                Alcotest.(check bool)
                  (label ^ ": no " ^ needle)
                  false (contains html needle))
              [ "btn--connect-github"; github_path; "&#65291; Connect" ])
          [ ( "launch_auth_page (login)"
            , Earde.Components.launch_auth_page ~page_class:"launch-login"
                ~title:"T" ~content:"B" () )
          ; ( "launch_auth_page (signup)"
            , Earde.Components.launch_auth_page ~page_class:"launch-signup"
                ~title:"T" ~content:"B" () )
          ; ( "launch_message_page"
            , Earde.Components.launch_message_page ~title:"T" ~content:"B" () )
          ])

  (* 6./7. /bring's own primary action is untouched, byte-for-byte: element,
     method, action, classes, 20px mark and full label. Rendered through the
     real handler, so this is the page a browser gets. *)
  let bring_start_form =
    "<form method='POST' action='/integrations/github/install/start'><button \
     type='submit' class='btn btn--dark'><svg width='20' height='20' \
     viewBox='0 0 16 16' fill='currentColor' aria-hidden='true'><path d='M8 \
     0C3.58 0 0 3.58 0 8c0 3.54 2.29 6.53 5.47 \
     7.59.4.07.55-.17.55-.38 0-.19-.01-.82-.01-1.49-2.01.37-2.53-.49-2.69-.94-.09-.23-.48-.94-.82-1.13-.28-.15-.68-.52-.01-.53.63-.01 \
     1.08.58 1.23.82.72 1.21 1.87.87 \
     2.33.66.07-.52.28-.87.51-1.07-1.78-.2-3.64-.89-3.64-3.95 \
     0-.87.31-1.59.82-2.15-.08-.2-.36-1.02.08-2.12 0 0 .67-.21 2.2.82a7.6 \
     7.6 0 0 1 4 0c1.53-1.04 2.2-.82 2.2-.82.44 1.1.16 1.92.08 \
     2.12.51.56.82 1.27.82 2.15 0 3.07-1.87 3.75-3.65 \
     3.95.29.25.54.73.54 1.48 0 1.07-.01 1.93-.01 2.2 0 \
     .21.15.46.55.38A8.01 8.01 0 0 0 16 8c0-4.42-3.58-8-8-8Z'/></svg> \
     Connect a GitHub project</button></form>"

  let bring_untouched_case =
    cc_case "/bring keeps its byte-identical full-label primary action"
      (fun () ->
        let body =
          Gh_bring.body_of (Gh_bring.run ~session:Gh_bring.member ())
        in
        Alcotest.(check int) "start form appears exactly once" 1
          (count_sub body bring_start_form);
        Alcotest.(check bool) "full label intact" true
          (contains body "Connect a GitHub project");
        (* Intentional on /bring only: the compact topbar action and the
           explicit page CTA are both present, so the page carries two marks
           and exactly one of them is the topbar's. *)
        Alcotest.(check int) "topbar CTA present too" 1
          (count_sub body cta_open);
        Alcotest.(check int) "two GitHub marks in total" 2
          (count_sub body github_path);
        (* The topbar action is still a link: /bring's non-ready states assert
           zero forms, so the chrome must not have grown one. *)
        Alcotest.(check int) "still exactly one form" 1
          (count_sub body "<form"))

  (* One definition, four call sites, no survivors: the control cannot drift
     between wrappers and the retired outline class is gone from production. *)
  let single_definition_case =
    cc_case "one shared CTA definition feeds every launch topbar" (fun () ->
        let components =
          List.assoc "lib/components.ml" Legacy_census.production_sources
        in
        Alcotest.(check int) "one definition" 1
          (count_sub components "let launch_connect_cta");
        Alcotest.(check int) "definition plus four call sites" 5
          (count_sub components "launch_connect_cta");
        Alcotest.(check int) "four topbar action clusters" 4
          (count_sub components "<div class='topbar__actions'>");
        Legacy_census.absent_everywhere "retired plus glyph" "&#65291; Connect";
        (* The generic ochre outline button survives for its own callers, but
           no launch topbar uses it any more. *)
        Alcotest.(check int) "components.ml drops btn--outline-ochre" 0
          (count_sub components "btn--outline-ochre");
        (* CSS isolation: the modifier exists and is scoped under the top bar,
           and the responsive hide rule followed the class rename. *)
        let css = Legacy_census.read "static/css/earde.css" in
        Alcotest.(check bool) "modifier is topbar-scoped" true
          (contains css ".topbar__actions .btn--connect-github {");
        Alcotest.(check int) "modifier is never styled unscoped" 0
          (count_sub css "\n.btn--connect-github");
        Alcotest.(check bool) "narrow viewports still hide it" true
          (contains css ".topbar__actions .btn--connect-github { display: none; }"))

  let suite =
    [ shape_case; no_external_asset_case; anonymous_case; chromeless_case
    ; bring_untouched_case; single_definition_case ]
end

